// MemoryMap AI frontend: plain JS, no framework (locked decision, plan §2).
// All DOM nodes are built with createElement/textContent, never innerHTML,
// so a note containing <script> is just text, not code.

// --- browser log capture (Wave A) -----------------------------------------------
// Installed before anything else runs so no message is missed. Shown in
// Settings → Logs alongside the server's records.

const browserLogs = [];
const MAX_BROWSER_LOGS = 500;

function recordBrowserLog(level, parts) {
  const record = {
    time: new Date().toISOString(),
    level,
    message: parts
      .map((p) => {
        if (typeof p === "string") return p;
        try {
          return JSON.stringify(p);
        } catch {
          return String(p);
        }
      })
      .join(" "),
  };
  browserLogs.push(record);
  if (browserLogs.length > MAX_BROWSER_LOGS) browserLogs.shift();

  // Live-push into the Logs page if it is currently open.
  // `logRecords`, `logScreenOpen`, `sortLogRecords`, `renderActiveLogView`,
  // `scrollLogToBottom` and `bumpLogErrorBadge` all live in settings.js now
  // (§88.3 item 4; previously later in this same file), which loads after
  // this one: so any `console.*` call during app.js's own early boot,
  // before settings.js has run, needs the same typeof guard this line
  // needed even when everything was one file. Confirmed live: this is
  // exactly the path a `console.warn`/`console.error` fired from app.js's
  // own startup would take, and it already degrades to "skip the live
  // push" rather than throwing, same as before the split.
  if (typeof logRecords !== "undefined" && typeof logScreenOpen !== "undefined") {
    const liveRecord = { ...record, source: "browser", logger: "browser",
      key: `b-live-${Date.now()}-${Math.random()}` };
    logRecords.push(liveRecord);
    if (typeof sortLogRecords === "function") sortLogRecords();
    if (logScreenOpen && typeof renderActiveLogView === "function") {
      renderActiveLogView();
      // Scroll to bottom so the new error is visible without manual scroll.
      if (typeof scrollLogToBottom === "function") scrollLogToBottom();
    }
    // Bump the error badge in the Logs button so the user knows to check.
    if (typeof bumpLogErrorBadge === "function") bumpLogErrorBadge(record);
  }
}

for (const level of ["log", "info", "warn", "error"]) {
  const original = console[level].bind(console);
  console[level] = (...parts) => {
    recordBrowserLog(level.toUpperCase(), parts);
    original(...parts);
  };
}
window.addEventListener("error", (e) =>
  // e.error.stack, when present, is what actually locates the bug, the
  // message/filename/lineno triple alone has sent more than one session
  // hunting for a null-dereference with no line number to start from.
  recordBrowserLog("ERROR", [
    `${e.message} (${e.filename}:${e.lineno}:${e.colno})`,
    e.error?.stack || "",
  ])
);
window.addEventListener("unhandledrejection", (e) =>
  recordBrowserLog("ERROR", [
    "Unhandled promise rejection:",
    e.reason?.stack || String(e.reason),
  ])
);

// Below this confidence an entry gets a "check this" flag (plan Phase 3).
const REVIEW_THRESHOLD = 50;

let allEntries = []; // latest GET /entries result, newest first
// Whether that has ever come back. An empty notebook and a notebook that
// has not loaded yet look identical from `allEntries.length` alone.
let entriesEverLoaded = false;
// Bumped by every loadEntries() call, checked by its own background page
// fetches before they touch allEntries, the same "stale response" guard
// loadOnboardingDiagnostics uses. loadEntries can page in the background for
// a large notebook (see ENTRIES_PAGE_SIZE below), and loadEntries can also
// be called again mid-page-load (saving a note, deleting a category), a
// slow page from the *first* call landing after a second call already
// replaced allEntries would silently splice stale/duplicate rows back in.
let _entriesLoadGeneration = 0;
let activeCategory = null; // sidebar filter; null = All
// A second, orthogonal sidebar filter (not a category): asked for
// directly, so drafts (Writing Room saves, "Save as draft note" captures)
// are findable as a group instead of only a per-note chip. Mutually
// exclusive with activeCategory: picking one clears the other, same as
// switching categories already does.
let draftsOnly = false;
// **Favourites, as a third sidebar filter over a flag that already existed.**
// Asked for: "there should be a favourites folder or side parallel category
// that isnt an actual category but could be treated as one if toggled?? for
// notes??"
//
// Built on `entry.pinned` rather than on a new "starred" column, and that is
// the whole design decision. `pinned` is already per-note, already persisted,
// already toggled from a note's own chip, and already searchable as
// `is:pinned`, a second boolean meaning almost the same thing would be two
// half-used flags and two places to star something, which is exactly the
// "everything is different from everything else" this round is undoing. What
// was missing was never the data; it was the *place*: a row in the sidebar you
// can click, alongside the categories, the way Drafts already is.
//
// So `pinned` keeps its sort meaning (float to the top) and gains a collection
// meaning (a group you can go to). The same note is in both readings.
let favouritesOnly = false;
let linkSource = null; // entry id waiting for its link partner
let editingId = null; // entry id currently in inline-edit mode
let inlineAction = null; // {id, kind: "context"|"continue"} open on a card
let busyEntryId = null; // entry the AI is currently working on (spinner shown)
let flashConfidenceId = null; // entry whose confidence badge just changed (flash once)
let noteSearch = ""; // Notes-tab text filter (Wave J)
// Why each note is in the filtered list, keyed by id: `{explain, scores}` from
// `GET /search` (the retrieval engine, Brief 11). The list itself is still
// filtered here in the browser, which is what keeps typing instant; this is
// the *explanation* the browser cannot produce, because two of the three
// signals (meaning, and distance over the links) only exist on the server.
// Cleared whenever the box is, so a stale reason can never outlive its query.
const noteSearchWhy = new Map();
let noteSort = "newest"; // newest | oldest | az | most-used (Wave J)
// BACKLOG §77 item 1. "all" (the default) keeps the existing continuous
// scroll (§86's renderIncrementally) untouched; a numeric size switches
// renderEntries to a single flat page of that many notes instead. Persisted
// the same way graph-gravity/graph-spread are, a plain localStorage read at
// declaration time, not the async preferences endpoint, since this is a
// display choice with no reason to round-trip the server.
let notesPageSize = localStorage.getItem("notes-page-size") || "all";
let notesCurrentPage = 1;

const $ = (id) => document.getElementById(id);
const show = (...ids) => ids.forEach((id) => $(id).classList.remove("hidden"));
const hide = (...ids) => ids.forEach((id) => $(id).classList.add("hidden"));

// --- tiny API helper --------------------------------------------------------

function authToken() {
  return localStorage.getItem("token") || "";
}

// `/media/...` and `/files/...` are the two routes a plain `<img src>` (or a
// note's own inline `![]()` markdown, rendered straight into an `<img>` tag)
// points at directly: a declarative resource load never attaches the
// X-Auth-Token header the way `apiJson`/`fetch` calls here do, so every such
// image was a silent 401 (an empty/broken image, nothing thrown, nothing
// logged, `isRenderableUrl` already having confirmed it same-origin) on any
// notebook with a password set, which is the normal case. The backend's
// `require_unlock_media` accepts the token this way for exactly these two
// routes; every other endpoint stays header-only. A no-op on anything that
// isn't one of these two paths, so every call site can use it unconditionally.
//: **Declared up here, and the reason is the `SPACE_ALL` story below.** A
//: `const` is in the temporal dead zone until its own line runs, and
//: `mediaSrc` is called during boot, long before the capture composer's own
//: section of this file is reached. Left where they logically belong (beside
//: `handleFileUpload`), the very first render would throw
//: `ReferenceError: Cannot access 'STAGED_URL_PREFIX' before initialization`,
//: which `node --check` cannot see because the file is syntactically perfect.
const STAGED_URL_PREFIX = "staged:";

//: Images waiting for a note to exist, the bytes stay in the browser until
//: Save produces an id. See `handleFileUpload` for the whole arrangement.
let captureStagedImages = [];

//: The one place that knows the placeholder's shape, so the renderer and the
//: rewrite cannot disagree about it.
function stagedImageUrl(key) {
  return `${STAGED_URL_PREFIX}${key}`;
}

function stagedImageByUrl(url) {
  if (typeof url !== "string" || !url.startsWith(STAGED_URL_PREFIX)) return null;
  const key = url.slice(STAGED_URL_PREFIX.length);
  return captureStagedImages.find((image) => image.key === key) || null;
}

//: **The one thing staging must never do: reach the database.**
//:
//: REDESIGN.md §R7.2 held this feature back for a whole session over exactly
//: this failure mode, and the wording is worth keeping: every path that can
//: save the composer has to rewrite the staged markers first, and one that
//: does not leaves `staged:`/`blob:` URLs inside saved note content, 
//: *corrupted notes, which is worse than the recoverable orphan it replaces*
//: (orphans already have a collector; a note whose picture is a dead
//: in-memory key has nothing).
//:
//: That section asked for "a test per save path". This is the stronger
//: version of the same idea and the reason there is no allowlist of save
//: paths anywhere: rather than enumerate the functions that must remember to
//: call `rewriteStagedUrls`, an enumeration a future save path joins by
//: being forgotten: every request in the app passes through `api()`, so the
//: check lives there and a new save path is covered by existing.
//:
//: It throws rather than repairing. A silent fix would hide the bug and ship
//: a note missing its picture; a throw surfaces in the caller's own error
//: toast with the note still unsaved in the box, so nothing is lost.
//:
//: Matched on the markdown embed shape, not on the bare scheme: a note that
//: happens to contain the word "staged:" is ordinary prose, while `](staged:`
//: is a link target this app wrote and never a sentence a person typed.
const STAGED_IN_BODY = /]\((?:staged|blob):/;

function refuseStagedUrls(body) {
  if (typeof body !== "string" || !STAGED_IN_BODY.test(body)) return;
  throw new Error(
    "That still holds an image that hasn't finished uploading: try saving again in a moment."
  );
}

function mediaSrc(url) {
  //: A staged picture has no server url yet; its bytes are a Blob in this
  //: tab. Resolved here rather than at each `<img>` so every surface that
  //: renders note markdown, the composer preview, the live view, a widget , 
  //: shows it without knowing staging exists.
  if (typeof url === "string" && url.startsWith(STAGED_URL_PREFIX)) {
    return stagedImageByUrl(url)?.objectUrl || url;
  }
  if (typeof url !== "string" || !/^\/(media|files)\//.test(url)) return url;
  const token = authToken();
  if (!token) return url;
  const sep = url.includes("?") ? "&" : "?";
  return `${url}${sep}token=${encodeURIComponent(token)}`;
}

// **A file that is no longer there should say so, not draw a broken frame.**
//
// Reported with a screenshot of a timeline popup: "a photo i attached to a
// note ages ago but deleted still randomly shows itself as a placeholder
// empty image with the image filename". A note's body keeps the
// `![name](/media/…)` markdown it was written with, so deleting the upload
// leaves a live `<img>` pointing at a 404, and what a browser draws for that
// is its own torn-page glyph beside the alt text, which is the filename. It
// looks like the app is broken rather than like the file is gone.
//
// One delegated listener rather than an `onerror` at each of the twenty-odd
// places that build an `<img>`: `error` does not bubble, but it *does*
// capture, so a single capturing listener on the document sees every image
// failure in the app, including the ones inside rendered markdown, which no
// call site here constructs and could not have been given a handler anyway.
//
// The note's text is deliberately left alone. Rewriting a person's own words
// because a file they referenced is missing is a bigger claim than this
// evidence supports (a media route can 404 for a locked notebook or a
// half-finished restore too), and it is not reversible. This says what is
// true, there was an image here and it is not available, in the app's own
// materials, and leaves the source as the record.
function replaceMissingMedia(img) {
  const src = img.getAttribute("src") || "";
  // Only this app's own stored files. An external image that fails is a
  // different situation, and the note may well want it back when the network
  // returns.
  if (!/^\/(media|files)\//.test(src)) return;
  //: **An image the app addresses by id is hidden, never replaced.** This
  //: listener was written for the images inside rendered markdown, which are
  //: built fresh on every render and referred to by nobody: swapping one for a
  //: placeholder costs nothing. `#ocr-image` is the opposite: one long-lived
  //: element that the OCR workspace sets a new `src` on for every page of
  //: every document it opens.
  //:
  //: Measured. Opening a text file (a .md attachment) in the workspace sets
  //: `img.src` to that file's own url before the text branch of `ocrLoadPage`
  //: runs, the browser cannot decode markdown as an image, this listener fired
  //: and `img.replaceWith(gone)` deleted `#ocr-image` from the document. After
  //: that the stage held `SPAN.media-missing` and no `<img>` at all, for the
  //: rest of the session: every later open threw "Cannot set properties of
  //: null (setting 'src')" at `ocrLoadPage`, so clicking the next file's name
  //: opened a workspace that never showed the page. CLAUDE.md's own shape: the
  //: damage lands nowhere near the code that caused it.
  //:
  //: Hidden rather than replaced, so nothing draws a torn-page glyph and the
  //: element the app is holding on to is still there. The surfaces that own
  //: such an image say what happened in their own words (`#ocr-message`), and
  //: they unhide it themselves the moment a page really loads.
  if (img.id) {
    img.classList.add("hidden");
    return;
  }
  if (img.dataset.mediaMissing) return;
  img.dataset.mediaMissing = "1";
  const gone = document.createElement("span");
  gone.className = "media-missing";
  const name = (img.getAttribute("alt") || "").trim();
  setLabel(gone, `ph:image-broken ${name || "Image"}`);
  const note = document.createElement("span");
  note.className = "media-missing-note";
  note.textContent = "no longer in this notebook";
  gone.append(note);
  gone.title = `${name || "This image"} was removed. The note still mentions it.`;
  img.replaceWith(gone);
}

document.addEventListener(
  "error",
  (event) => {
    const img = event.target;
    if (img instanceof HTMLImageElement) replaceMissingMedia(img);
  },
  true,
);

// A page-load-order bug lived here: this was declared down in the spaces
// section (appended at the end of the file), and `api()`, called from
// `initAuth()` at module load, long before that point in the script runs, 
// reads it via `activeSpaceId()` on every request's headers below. A `const`
// is in the temporal dead zone until its own declaration executes, so the
// very first request the app ever made threw `ReferenceError: Cannot access
// 'SPACE_ALL' before initialization`, caught by api()'s own try/catch and
// surfaced only as "Can't reach the MemoryMap server", the lock screen
// never appeared, with no console error and no failed network request,
// because the fetch was never reached. `node --check` cannot catch this: the
// file is syntactically valid, only wrong in execution order. Declared here,
// before `api()` is ever callable, so this cannot happen again regardless of
// what gets appended below.
const SPACE_ALL = "all";

async function api(path, options = {}) {
  // `silent`: a background poll (model status, reminders): a 401 must not
  // yank the user to the lock screen mid-session (Wave O fix for a
  // long-standing intermittent re-lock). Only an explicit user action
  // shows the lock screen on 401.
  // `timeoutMs`: opt-in abort so a call can't hang the UI forever (used by the
  // startup probe). Off by default, so long-running requests, model pulls,
  // blocking chat: are unaffected.
  // `ownsAuthErrors`: this call treats 401 as part of its own result rather
  // than as an expired session. Change-password answers 401 for "that isn't
  // your current password", a typo there must show a message beside the
  // field, not throw the user out to the lock screen.
  const { silent, timeoutMs, ownsAuthErrors, ...fetchOptions } = options;
  refuseStagedUrls(fetchOptions.body);
  // Any write invalidates the read cache above, see clearApiCache().
  if (fetchOptions.method && fetchOptions.method !== "GET") clearApiCache();
  let timer = null;
  if (timeoutMs) {
    const controller = new AbortController();
    timer = setTimeout(() => controller.abort(), timeoutMs);
    fetchOptions.signal = fetchOptions.signal || controller.signal;
  }
  let response;
  try {
    response = await fetch(path, {
      headers: {
        "Content-Type": "application/json",
        "X-Auth-Token": authToken(),
        // Which space this request is scoped to. The server reads it in
        // get_session() and adds a loader criterion for it, so leaving it off
        // means every request silently sees every space, the switcher would
        // change the label in the header and nothing else.
        "X-Workspace-ID": activeSpaceId(),
      },
      ...fetchOptions,
    });
  } catch (networkErr) {
    // fetch() itself threw: this is a real network failure (offline, CORS,
    // connection refused). Log it explicitly so it always appears in Logs.
    //
    // `!networkErr?.name === 'AbortError'` is what this said, which parses as
    // `(!networkErr?.name) === 'AbortError'`, a boolean compared to a string,
    // so it was always false and no network failure was ever logged. The one
    // case the check exists to skip (our own timeout abort) was being logged
    // and everything else was too.
    if (networkErr?.name !== "AbortError") {
      recordBrowserLog("ERROR", [
        `[Network] ${fetchOptions.method || 'GET'} ${path}: ${networkErr.message}`
      ]);
    }
    throw networkErr;
  } finally {
    if (timer) clearTimeout(timer);
  }
  if (response.status === 401 && !ownsAuthErrors) {
    if (!silent) showLockScreen(false); // token expired (e.g. app restarted)
    const locked = new Error("Locked");
    // Marked, so `startApp()`'s bootstrap loop can tell "the session expired"
    // apart from "this one endpoint failed". Reported: *"before signing in, a
    // popup shows a message saying failed to load entries"*, a stale token
    // in localStorage (server restarted since the last visit) makes `startApp`
    // fire a dozen requests in parallel before the user has unlocked
    // anything, every one of them hits this 401, and every one of them used
    // to toast its own "Couldn't load X: Locked" on top of the lock screen
    // that had already, correctly, just appeared. One state: not logged in
    //, was being reported as a dozen unrelated failures.
    locked.isLockout = true;
    throw locked;
  }
  if (!response.ok) {
    const detail = await response.json().catch(() => ({}));
    const errMsg = typeof detail.detail === 'string' ? detail.detail : (JSON.stringify(detail.detail) || `Request failed (${response.status})`);
    if (!silent) {
      // Log HTTP errors so they always appear in Settings → Logs for debugging.
      recordBrowserLog("ERROR", [
        `[HTTP ${response.status}] ${fetchOptions.method || 'GET'} ${path}: ${errMsg}`
      ]);
    }
    throw new Error(errMsg);
  }
  //: A write that can leave a model running on a background thread gets the
  //: task poll looked at now, rather than up to ten seconds from now.
  //:
  //: Reported as *"notifications dont appear when generating image
  //: captions"*, and the cause is a cadence, not a missing notification.
  //: `refreshModelStatus` idles at 10s (120s behind a hidden tab), and
  //: `noticeTaskTransitions` can only announce a job it has actually *seen*
  //: in a `/tasks` payload. A caption is one model round-trip, often
  //: shorter than the gap between two idle polls, so it began and ended
  //: unobserved: no "Started" line, no status-bar job slot, nothing. The
  //: long jobs this panel was built for (a re-index, a model pull) never hit
  //: this because they outlive any poll interval.
  if (fetchOptions.method && fetchOptions.method !== "GET" && JOB_STARTING_PATH.test(path)) {
    kickBackgroundTaskPoll();
  }
  return response;
}

// --- reading a paged list endpoint whole ---------------------------------------
//
// `GET /documents`, `GET /media`, `GET /reminders` and the rest each return a
// page and an `X-Total-Count` header saying how big the selection really is
// (INBOX 117; `GET /entries` has worked this way for longer, see
// `loadEntries`). A caller that needs every row asks for the next page until it
// has them all, which is the half that makes a cap safe: a cap with no offset
// makes everything past it permanently unreachable, and that is exactly the
// failure the old uncapped list was avoiding.
//
// **It lives here, immediately below `api()`, and that placement is the whole
// of a crash report.** It used to live in documents.js, whose own comment
// argued that "both call it from inside a function body, so load order is
// satisfied either way". That stopped being true the moment app.js called it
// from boot code: index.html loads app.js first and documents.js ten lines
// later, so `initNotesSubtabs` running at the bottom of this file reached a
// function that did not exist yet, and the Notes tab died with
// `ReferenceError: apiPagedList is not defined` before it drew anything. Six
// frontend files call this now; the file every one of them is loaded after is
// this one. `tests/test_frontend_load_order.py` is the rule, so the next
// shared helper cannot be put somewhere only some callers can see.
//
// `options` is passed through to `api()` untouched (library.js wants
// `{ silent: true }`). A page that comes back empty ends the loop whatever the
// header says, so a stale or wrong total can never spin forever.
async function apiPagedList(path, pageSize, options = {}) {
  const rows = [];
  let total = Infinity; // discovered from the first response's X-Total-Count
  while (rows.length < total) {
    const joiner = path.includes("?") ? "&" : "?";
    const response = await api(`${path}${joiner}limit=${pageSize}&offset=${rows.length}`, options);
    const page = await response.json();
    if (!Array.isArray(page) || !page.length) break;
    rows.push(...page);
    const reported = Number(response.headers.get("X-Total-Count"));
    total = Number.isFinite(reported) && reported > 0 ? reported : rows.length;
  }
  return rows;
}


//: Paths whose response can leave captioning, OCR or a librarian pass running
//: on a background thread. Deliberately a short list rather than "every
//: write": filing a note or a message is exactly when an attached image
//: starts being read (`core/media_process.py` runs at *commit*, not at
//: upload), but a rename or a preference save can start nothing and should
//: not cost a poll.
const JOB_STARTING_PATH =
  /^\/(entries|documents|media\/upload|media\/\d+\/|files\/\d+\/|conversations\/\d+\/messages|extras\/|models\/pull|search\/reindex|tasks\/trigger-autonomous)/;

//: Debounced, because committing a note with four images is four writes and
//: one job list. 600ms rather than immediately: the thread is started after
//: the response is written, so a poll racing it by a millisecond sees the
//: state from just before the job existed, the exact miss this fixes.
let jobPollKick = null;
function kickBackgroundTaskPoll() {
  clearTimeout(jobPollKick);
  jobPollKick = setTimeout(() => {
    refreshBackgroundTasks().catch(() => {
      // A poll is best-effort, it runs again on the status loop regardless.
    });
  }, 600);
}

// A short-lived cache for GET responses, opt-in per call.
//
// Every dashboard widget fetches its own data, and switching away from the
// Dashboard and back re-ran all of them against data that is, in practice,
// seconds old: a network round trip and a re-render for nothing new to
// show. Opt-in (`cacheMs`) rather than global: silently serving a stale
// answer to something that must be current the instant it changes (reminder
// due-times, model status) would be a worse bug than the one this fixes.
//
// Invalidated wholesale by any mutating request (see `api()` below) rather
// than tracked per-endpoint: simpler, and correct: the common case this
// exists for is "nothing changed since I was last on this tab", and any
// write at all means that's no longer true.
const _apiCache = new Map();

function clearApiCache() {
  _apiCache.clear();
}

async function apiJson(path, options = {}) {
  const { cacheMs, ...rest } = options;
  if (cacheMs && (!rest.method || rest.method === "GET")) {
    const hit = _apiCache.get(path);
    if (hit && Date.now() - hit.at < cacheMs) return hit.data;
    const data = await (await api(path, rest)).json();
    _apiCache.set(path, { data, at: Date.now() });
    return data;
  }
  return (await api(path, options)).json();
}

// --- auth gate (Phase 4) -----------------------------------------------------

function showLockScreen(setupMode) {
  $("lock-overlay").classList.remove("hidden");
  $("lock-title").textContent = setupMode ? "Welcome to MemoryMap" : "Unlock MemoryMap";
  $("lock-message").textContent = setupMode
    ? "First run: choose a password (or PIN) to protect your notebook. You'll need it every time the app starts."
    : "Enter your password to unlock your notebook.";
  $("lock-submit").textContent = setupMode ? "Set password & start" : "Unlock";
  $("lock-overlay").dataset.mode = setupMode ? "setup" : "unlock";
  // One field in two modes (no separate setup form), autocomplete has to
  // switch with it, or a password manager offers to fill an *existing*
  // saved password into a first-run "choose a new one" field.
  $("lock-password").setAttribute("aria-label", setupMode ? "Choose a password" : "Password");
  $("lock-password").autocomplete = setupMode ? "new-password" : "current-password";
  $("lock-password").focus();
}

async function submitLockForm() {
  const password = $("lock-password").value;
  const errorLine = $("lock-error");
  errorLine.textContent = "";
  if (password.length < 4) {
    errorLine.textContent = "Use at least 4 characters.";
    return;
  }
  const mode = $("lock-overlay").dataset.mode;
  try {
    const body = await apiJson(`/auth/${mode === "setup" ? "setup" : "unlock"}`, {
      method: "POST",
      body: JSON.stringify({ password }),
    });
    localStorage.setItem("token", body.token);
    $("lock-password").value = "";
    // **Give the focus back, or every single-key shortcut in the app is
    // dead.** Hiding the overlay does not move focus off the field inside
    // it, so `document.activeElement` stayed `#lock-password` for the whole
    // session that followed. Every handler that (correctly) refuses to steal
    // a keystroke while someone is typing, the whiteboard's V/H/P tool keys,
    // its `n` and `/`, and the same guard elsewhere, therefore returned
    // immediately on every press, until the reader happened to click some
    // other focusable control. Found while testing the tool shortcuts: they
    // did nothing at all from a freshly unlocked app.
    $("lock-password").blur();
    $("lock-overlay").classList.add("hidden");
    $("lock-btn").classList.remove("hidden");
    // Signing in starts a session, and a session starts at the front of every
    // tab: see `resetNavigationForNewSession`. Here as well as at load
    // because the lock screen is an *overlay*, not a page: unlocking after an
    // idle lock never reloads anything, so the load-time reset alone would
    // leave every sub-tab exactly where it was hours ago. Called before
    // `startApp()`, which is what reads the stored section back.
    resetNavigationToDefaults();
    startApp();
  } catch (error) {
    errorLine.textContent = error.message;
  }
}

//: **The containers that hold the user's own words**, cleared when the
//: notebook locks. Enumerated explicitly rather than derived, because this is
//: a privacy boundary and a reviewer should be able to read exactly what is
//: purged without running anything.
//:
//: Static UI text (the Settings panels, the capture form's own labels) is
//: deliberately not here: it belongs to the app, not to the user, and
//: clearing markup that `startApp()` does not rebuild would break the app on
//: unlock.
const LOCK_PURGE_IDS = [
  "entry-list", // notes
  "chat-messages", // the conversation
  "library-grid", // files and images
  "library-docs-list", // documents
  "timeline-scroll", // the timeline
  "reminder-list-card", // reminders
  "graph-svg", // node labels are note titles
  "palette-list", // whatever was last searched for
  "doc-live",
  "doc-preview",
];

//: Empty everything the lock screen is covering.
//:
//: **The lock overlay was a visual cover, not a purge**, and the roadmap
//: ranked auditing it first precisely because it is this app's only privacy
//: boundary. Measured with the notebook locked: `#entry-list` still held 61
//: notes and 3,431 characters of their text, `#library-grid` 5,089, the
//: documents list 6,422: all of it one devtools click, one screen reader,
//: or one browser extension away from being read.
//:
//: The server side was already right (every endpoint answers 401 while
//: locked, verified in the same audit), so this closes the client half.
//:
//: Safe because unlocking runs `startApp()`, which re-fetches and re-renders
//: all of it. The codebase already reasons this way elsewhere, 
//: `hideBootSplash` removes itself from the DOM rather than leaving a hidden
//: overlay, on the same principle that nothing should sit over the viewport
//: invisibly.
function purgeLockedContent() {
  for (const id of LOCK_PURGE_IDS) {
    const el = document.getElementById(id);
    if (el) el.replaceChildren();
  }
  // A textarea's text lives in `.value`, which `replaceChildren` never
  // touches: the document editor would otherwise keep the whole document
  // readable behind the lock screen.
  for (const id of ["doc-content", "doc-title", "entry-input", "chat-input"]) {
    const field = document.getElementById(id);
    if (field && "value" in field) field.value = "";
  }
}

async function lockNow() {
  try {
    await api("/auth/lock", { method: "POST" });
  } catch {
    /* locking locally regardless */
  }
  localStorage.removeItem("token");
  purgeLockedContent();
  showLockScreen(false);
}

// Fades out and removes #boot-splash (index.html): called once, from
// initAuth() below, the moment its /auth/status round trip resolves,
// whichever of that function's four branches it turns out to be. Removed
// from the DOM after the fade rather than left `hidden`: nothing should
// keep sitting fixed over the whole viewport, even invisibly, once the app
// has decided what it's actually showing.
function hideBootSplash() {
  const splash = document.getElementById("boot-splash");
  if (!splash) return;
  // Snap the bar to 100% before the fade starts, so it never visibly
  // disappears mid-crawl: it always reads as "finished", never "cut off".
  document.getElementById("boot-splash-progress-fill")?.classList.add("done");
  splash.classList.add("hidden");
  splash.addEventListener("transitionend", () => splash.remove(), { once: true });
  // Reduced-motion strips the transition (00-tokens-shell.css), so
  // transitionend never fires: remove immediately in that case instead of
  // leaving a zero-opacity element sitting in the DOM forever.
  if (reducedMotionWanted()) splash.remove();
}

async function initAuth() {
  // Bounded probe: if the server is unreachable or hangs, fail fast with a
  // clear message instead of an indefinite blank/"connecting" screen.
  const status = await apiJson("/auth/status", { timeoutMs: 8000 }).catch(() => null);
  hideBootSplash();
  if (!status) {
    $("save-status").textContent =
      "Can't reach the MemoryMap server, check it's running, then refresh.";
    toast("Can't reach the MemoryMap server. Is it running?", true);
    return;
  }
  if (status.setup_required) {
    showLockScreen(true);
    return;
  }
  $("lock-btn").classList.remove("hidden");
  if (!authToken()) {
    showLockScreen(false);
    return;
  }
  // Token might be stale after a server restart, startApp()'s first
  // request will bounce us to the lock screen if so.
  startApp();
}

function startApp() {
  // Whatever the shell was last saying about being unable to reach the server
  // is now provably false, we are about to talk to it. Left uncleared, the
  // "check it's running, then refresh" line sat under the capture form for the
  // whole session after one slow start, telling the user the app was broken
  // while it worked perfectly. Screenshotted.
  const shellStatus = $("save-status");
  if (shellStatus) shellStatus.textContent = "";

  // A failed load must be visible, not a silently empty page, and one
  // broken endpoint must never stop the rest of the app from coming up.
  // Every bootstrap step is isolated so a single rejection surfaces a toast
  // instead of leaving the user staring at a half-loaded (or blank) app.
  const step = (label, fn) => {
    try {
      const result = fn();
      if (result && typeof result.catch === "function") {
        return result.catch((error) => {
          // The lock screen already said what happened; a toast under it
          // repeating "Couldn't X: Locked" for every parallel step is noise
          // about one state dressed up as several failures.
          if (!error.isLockout) toast(`Couldn't ${label}: ${error.message}`, true);
        });
      }
      return Promise.resolve(result);
    } catch (error) {
      if (!error.isLockout) toast(`Couldn't ${label}: ${error.message}`, true);
      return Promise.resolve();
    }
  };

  // Before anything reads a stored setting: bring back whatever this browser
  // has lost. A shell that does not keep localStorage, the desktop window is
  // the reported one (§35E): starts every launch with the default theme and
  // an onboarding tour it has already been through, because both live there
  // and nowhere else. The server's copy fills the gaps, then the look is
  // re-applied so the app settles into the remembered theme rather than
  // staying on the default it painted a moment ago.
  const looksReady = step("restore your settings", async () => {
    if (!prefsCache) {
      prefsCache = await apiJson("/preferences", { silent: true }).catch(() => null);
    }
    if (prefsCache && seedUiStateFromServer(prefsCache.ui_state)) {
      // The same three calls the theme picker makes, in the same order: the
      // root attributes, then the light/dark choice and the palette, neither
      // of which re-records itself as a manual override.
      applyAppearance();
      applyThemeChoice(appearancePref("theme"), false);
      applyPalette(appearancePref("palette"), false);
      renderBrandLogo();
      if (bgArtOn()) startBgArt();
    }
    
    // Always check battery efficient mode regardless of ui_state seeding
    const indicator = $("power-saver-indicator");
    if (indicator) {
      if (prefsCache && prefsCache.battery_efficient_mode) {
        indicator.classList.remove("hidden");
      } else {
        indicator.classList.add("hidden");
      }
    }
    // The bell's own icon reads the mute preference, re-render now that
    // prefsCache actually has it, rather than leaving the pre-load default
    // (unmuted) on screen until the notifications panel happens to be opened.
    renderNotificationBadge();
    // Same reason, for the status bar: the slots the user has turned off are
    // in `prefsCache`, and hiding them here rather than on first paint would
    // mean a visible flash of a bar they chose not to have.
    applyStatusBarSlots();
    applyStatusClock();
  });

  const entriesReady = step("load entries", loadEntries);
  step("load recent questions", loadRecentQuestions);
  step("load ask history badge", loadAskHistoryBadge);
  step("load suggestions", loadSuggestions);
  step("load your most-used items", loadMostUsed);
  step("load templates", loadTemplates).then(() =>
    step("set up chat options", () => {
      personaOptions();
      // Wave G: skills chips + the agent-mode toggle read the
      // same prefsCache that loadTemplates just filled.
      loadChatSkills();
      $("tools-toggle").checked = !prefsCache || prefsCache.tools_enabled !== false;
      renderChatModeSeg();
      renderWebSearchToggle();
    })
  );
  step("load answer-length options", loadResponseModes);
  // Here, not at module level beside initSpaceSwitcher(). The switcher's
  // LISTENERS can be bound before there is a token, nothing about a click
  // handler needs the server, but the LIST cannot: /spaces 401s before
  // unlock, the catch leaves spacesCache empty, and nothing ever asks again.
  // The menu would then offer "All spaces" and nothing else, for the whole
  // session, on every fresh start. This is the same shape as the comment
  // below about switchTab painting from a pile of 401s.
  step("load spaces", loadSpaces);
  step("tell the server your timezone", reportTimezone);
  // Fires only if the user opted in (Settings -> About); the endpoint itself
  // also checks the preference server-side, but skipping the call here means
  // an opted-out install makes zero network attempts, not a wasted one.
  step("check for an update", () => {
    if (prefsCache && prefsCache.update_check_enabled) return checkForUpdate(true);
  });
  // Independent of update_check_enabled above, this isn't a network
  // check, it's reporting a fact: start.sh/start.bat already git-pulled a
  // real update before this process even started (their own step 0, no
  // preference gates it either). "Only if the app auto updates though,
  // not every time they login", the endpoint self-clears after one read,
  // so this only ever fires the run right after a real update landed.
  step("check for a source-checkout update notice", checkForSourceUpdateNotice);
  step("load conversations", loadConversationList);
  step("check the AI model status", refreshModelStatus);
  // Reminders poll on their own timer once running (see startReminderWatch);
  // starting that here, not at module level, is the other half of the fix
  // described above revealTab("dashboard")'s module-level call: the same
  // pile of pre-auth 401s, one endpoint earlier.
  step("watch reminders", startReminderWatch);

  // Re-render whichever tab is on screen. This used to be switchTab() itself,
  // called at module level before initAuth() has a token, so a tab that
  // fetches its own data painted itself from a pile of 401s and then never
  // tried again. On the dashboard that meant an empty grid until you opened
  // Edit layout and cancelled out of it, which re-ran renderDashboard by hand
  // (user-reported). Now the module-level call is revealTab(), DOM only,
  // no fetch: and this is the one place the real data load happens.
  // *After* the entries land, not alongside them. These two ran concurrently,
  // so on a cold load the dashboard rendered against an `allEntries` that was
  // still `[]` and drew its brand-new-notebook card instead of the widgets, 
  // reported as "the dashboard widgets are missing until I refresh or change
  // tabs". Every tab wants the notes; none of them wants to guess.
  entriesReady.then(() => step("load this tab", () => refreshActiveTab()));

  // First-run welcome tour (guarded by localStorage; re-runnable from Help).
  //
  // **After the settings are restored, not alongside them.** This is the
  // second half of the reported "onboarding shows every time": the flag lives
  // in localStorage, so a shell that lost it needs the server's copy back
  // *before* this asks: otherwise the tour opens, the flag arrives a moment
  // later, and the person is welcomed to an app they have used for a month.
  looksReady.then(maybeShowOnboarding);
  looksReady.then(maybeShowConsoleViewIntro);
}

// First-run "Dev view or User view?" prompt for the desktop app, asked
// for directly: "dev view is the default on install and the user will be
// presented with a popup option to change it just after install." Gated on
// its own preference (console_view_intro_seen) rather than piggybacking on
// onboardingDone, so changing the console mode later from Settings doesn't
// make this reappear, and vice versa. Browser-tab users never see this, 
// there's no console to speak of outside the desktop shell.
//
// Two bugs reported live, both fixed here:
//
// 1. "Showed both before and after I signed in, and kept coming back." The
//    guard only checked `prefsCache?.console_view_intro_seen`, but
//    `startApp()` also runs with a *stale* token (comment above `apiJson`'s
//    401 handling: "a stale token in localStorage... fire[s] a dozen
//    requests... before the user has unlocked anything"), and on that run
//    the silent /preferences fetch 401s and leaves prefsCache null. `null?.x`
//    is `undefined`, which is falsy, so the prompt fired on that pass too, 
//    before the real sign-in the user was about to do. It then fired AGAIN
//    on the real post-login startApp(), because whatever this function saved
//    the first time round never reached a real, authenticated session.
//    Requiring prefsCache to actually exist closes that: a failed fetch is
//    "we don't know yet", not "this is a fresh profile that hasn't seen it".
//
// 2. "Randomly signed me out." This used to POST /system/console-mode, the
//    same route Settings and the tray use, which restarts the whole desktop
//    process (pythonw.exe/python.exe relaunch, see __main__.py) the instant
//    the choice differs from the default. That is the right call for an
//    explicit Settings/tray toggle, where the user just asked for a live
//    switch and the toast says "restarting…". It is the wrong call for a
//    popup that appears on its own during first login: killing the server
//    (in-memory sessions and all, core/config.py, "restarting locks it
//    again") out from under someone who hasn't even finished signing in is
//    exactly the "signed out at random" report. It also raced its own
//    "remember this was answered" write against that same process exit, 
//    the second request sometimes lost, which is why the popup came back
//    "every other time" rather than never or always. A single PUT that sets
//    both preferences at once, with no restart, has neither problem: the
//    choice takes effect next launch (said plainly below), same as every
//    other preference in this app that isn't asking for a live switch.
async function maybeShowConsoleViewIntro() {
  if (!(await desktopShell())) return;
  if (!prefsCache || prefsCache.console_view_intro_seen) return;
  const wantsDevView = await confirmDialog(
    "Keep a console window open when MemoryMap AI starts?\n\n" +
      "Dev view shows a terminal window alongside the app, useful for " +
      "logs and troubleshooting. User view runs quietly in the background " +
      "with no console window at all, just this app window and a system " +
      "tray icon. Either way, you can switch any time from Settings or " +
      "the tray icon's own menu.\n\nTakes effect next launch.",
    { confirmLabel: "Dev view", cancelLabel: "User view", danger: false }
  );
  try {
    prefsCache = await apiJson("/preferences", {
      method: "PUT",
      body: JSON.stringify({
        show_console_on_startup: wantsDevView,
        console_view_intro_seen: true,
      }),
    });
    toast(
      `${wantsDevView ? "Dev" : "User"} view: starting from next launch.`
    );
  } catch (error) {
    toast(error.message || "Couldn't save your console view choice.", true);
  }
}

// The browser is the only thing that knows where the user actually is. The
// server may be running in UTC, a container, a NAS, a machine whose clock was
// never set: and every relative time the AI computes ("in 10 minutes",
// "tomorrow at 9") is resolved against that. So the zone is reported once at
// startup, and again whenever it changes (travel, or a DST shift).
//
// Only the IANA NAME is sent, never coordinates: "Australia/Brisbane" is what
// makes the arithmetic right, and it is far less identifying than a location.
async function reportTimezone() {
  let zone = "";
  try {
    zone = Intl.DateTimeFormat().resolvedOptions().timeZone || "";
  } catch {
    return; // an environment without Intl still works, just on server time
  }
  if (!zone || (prefsCache && prefsCache.timezone === zone)) return;
  prefsCache = await apiJson("/preferences", {
    method: "PUT",
    body: JSON.stringify({ timezone: zone }),
    silent: true,
  }).catch(() => prefsCache);
}

// The per-tab data loads switchTab performs, without the tab-switching itself.
// Kept beside switchTab's own dispatch so the two can't drift apart.
function refreshActiveTab() {
  const name = localStorage.getItem("activeTab") || "notes";

  // Relocate the back-to-top button so it aligns with the chat area bounds
  const scrollTopBtn = document.querySelector(".scroll-top");
  if (scrollTopBtn) {
    if (name === "chat") {
      document.querySelector(".chat-dock")?.appendChild(scrollTopBtn);
    } else {
      document.body.appendChild(scrollTopBtn);
    }
  }
  
  if (name === "dashboard") return renderDashboard();
  if (name === "graph") return renderGraph();
  if (name === "documents") return loadDocuments();
  if (name === "library") return loadLibrary();
  if (name === "reminders") {
    refreshReminderDefaults();
    return loadReminders();
  }
  if (name === "chat") return loadChatSuggestions();
  return undefined; // the notes tab is covered by loadEntries above
}

// --- capture templates (Wave B) ---------------------------------------------------

const BUILTIN_TEMPLATES = [
  { name: "Journal", content: "Journal: {date}\n\nToday I " },
  { name: "Recipe", content: "Recipe: \n\nIngredients:\n- \n\nSteps:\n1. " },
  { name: "Contact", content: "Contact: \nPhone/email: \nWhere we met: \nNotes: " },
  { name: "Meeting", content: "Meeting about \nWho: \nDecisions: \nTo do: " },
];

async function loadTemplates() {
  // Built-ins + the user's own (kept in preferences).
  prefsCache = await apiJson("/preferences").catch(() => prefsCache);
  // Saved filters live in the same payload, so draw them while it's fresh.
  renderSavedSearches();
  const custom = (prefsCache && prefsCache.custom_templates) || [];
  const select = $("entry-template");
  select.replaceChildren();
  const none = document.createElement("option");
  none.value = "";
  none.textContent = "No template";
  select.appendChild(none);
  // Grouped the same way the chat skill picker groups "Yours" ahead of
  // "Built-in" (§entry-template extension): one recognisable shape for
  // "your stuff first, then what shipped" instead of a flat, unsorted list.
  for (const [templates, title] of [[custom, "Yours"], [BUILTIN_TEMPLATES, "Built-in"]]) {
    if (!templates.length) continue;
    const group = document.createElement("optgroup");
    group.label = title;
    for (const template of templates) {
      const option = document.createElement("option");
      option.value = template.name;
      option.textContent = template.name;
      option.dataset.content = template.content;
      if (template.description) option.title = template.description;
      group.appendChild(option);
    }
    select.appendChild(group);
  }
}

async function applyTemplate() {
  const select = $("entry-template");
  const option = select.selectedOptions[0];
  if (!option || !option.dataset.content) return;
  const box = $("entry-content");
  // Never silently overwrite what's already been typed, ask first, and put
  // the dropdown back to blank on "keep my text" so it doesn't sit there
  // showing a template name that was never actually applied.
  if (box.value.trim()) {
    const replace = await confirmDialog(
      `Replace what you've already written with the “${option.textContent}” template?`,
      { confirmLabel: "Replace", cancelLabel: "Keep my text" }
    );
    if (!replace) {
      select.value = "";
      return;
    }
  }
  box.value = option.dataset.content.replace(
    "{date}",
    new Date().toLocaleDateString()
  );
  box.focus();
}

function refreshTagSuggestions() {
  // Autocomplete for the tags box, from tags already in use.
  const tags = [...new Set(allEntries.flatMap((e) => e.tags))].sort();
  const datalist = $("tag-suggestions");
  datalist.replaceChildren();
  for (const tag of tags) {
    const option = document.createElement("option");
    option.value = tag;
    datalist.appendChild(option);
  }
}

// --- rendering ---------------------------------------------------------------

// --- icon-aware labels -------------------------------------------------------
//
// Most of the app's small controls are built in JS and take a plain string
// label: chip("Notes"), smallButton("Delete", …), { label: "Improve" }. That
// is why the emoji reform kept missing three hundred icons: they are not in
// index.html, they are string literals passed to functions that assign
// textContent, and you cannot put an <i> in a textContent.
//
// So the label grammar gains one form: a leading `ph:name ` marker.
//
//     chip("ph:file-text Notes")   ->   <i class="ph ph-file-text"></i> Notes
//     smallButton("ph:trash", …)   ->   <i class="ph ph-trash"></i>
//
// Everything else about a label is unchanged, and a label with no marker is
// still set with textContent, so nothing here can turn user text into markup.
// The marker is matched with an anchored, bounded pattern and the captured
// name is rebuilt into a class, a caller cannot smuggle a second class or a
// closing tag through it.
//
// Prose never carries a marker. A toast, a tooltip and anything sent to the
// model are sentences, and `ph:link` in the middle of one is just noise the
// reader has to decode.
const PH_LABEL = /^ph:([a-z0-9-]{1,40})\s*/;

// Fills `el` with a label, turning a leading `ph:` marker into a real icon
// element. Returns the element, so it composes.
function setLabel(el, label) {
  const text = String(label ?? "");
  const match = PH_LABEL.exec(text);
  if (!match) {
    el.textContent = text;
    return el;
  }
  const icon = document.createElement("i");
  icon.className = `ph ph-${match[1]}`;
  icon.setAttribute("aria-hidden", "true");
  const rest = text.slice(match[0].length);
  // **The gap is a margin, not a space, and it has to be.** A plain " " text
  // node between the icon and the label is what this did first, and it worked
  // everywhere except in a flex container, where CSS discards anonymous
  // whitespace-only children outright. Half the labels in this app live in
  // flex rows (chips, buttons, status items), so half of them rendered with
  // the glyph jammed against the first letter and the other half did not,
  // which reads as a random inconsistency rather than a rule.
  //
  // Only when there IS following text: an icon-only button must stay exactly
  // as tight as it was, or every icon button in the app gains trailing space
  // and stops being square.
  if (rest) icon.classList.add("ph-lead");
  el.replaceChildren(icon);
  if (rest) {
    const textSpan = document.createElement("span");
    textSpan.className = "ph-text";
    textSpan.textContent = rest;
    el.append(textSpan);
  }
  return el;
}

//: **Is the Settings dialog open?** Defined here, in app.js, and not in
//: settings.js where the rest of that dialog lives. Reported from a real
//: session, five times in one second:
//:
//:     Uncaught ReferenceError: settingsModalOpen is not defined
//:       at HTMLDocument.<anonymous> (app.js:30278)
//:
//: app.js registers its document-wide keydown handler while it parses, and
//: settings.js is the last script on the page -- so every key pressed in the
//: window between the two threw, and the handler that runs Escape, "/" and
//: every other shortcut died with it. One call site already carried a
//: `typeof ... === "function"` guard, which is the same bug being worked
//: around one line at a time. A three-line DOM check has no reason to live in
//: another file; moving it removes the window entirely rather than papering
//: over it at each caller.
function settingsModalOpen() {
  const modal = document.getElementById("settings-modal");
  return Boolean(modal) && !modal.classList.contains("hidden");
}

function chip(text, extraClass = "", onClick = null) {
  const span = document.createElement("span");
  span.className = `chip ${extraClass}`.trim();
  setLabel(span, text);
  // An interactive chip must be reachable and operable by keyboard, not just
  // the mouse. Passing onClick makes it a real button in the a11y tree.
  if (onClick) {
    span.classList.add("chip-interactive");
    span.setAttribute("role", "button");
    span.setAttribute("tabindex", "0");
    span.addEventListener("click", onClick);
    span.addEventListener("keydown", (event) => {
      if (event.key === "Enter" || event.key === " ") {
        event.preventDefault();
        onClick(event);
      }
    });
  }
  return span;
}

// The one reusable "something is loading" mark (ROADMAP Priority 0 #14), 
// asked for directly, since before this every call site (re-evaluate, per-
// card AI work) built its own one-off spinner chip by hand. The .spinner
// CSS class (01-forms-settings.css, beside .chip-busy which it was
// extracted from) carries the animation and the prefers-reduced-motion
// fallback; aria-hidden because this is a visual accent only, the loading
// state itself belongs in a visible/aria-live status line at the call site,
// the same pattern #meeting-status and its siblings already use.
function spinnerEl() {
  const el = document.createElement("span");
  el.className = "spinner";
  el.setAttribute("aria-hidden", "true");
  return el;
}

// The `.unlink` "×" spans (detach/remove/dismiss) predate chip()'s own
// keyboard support and never got it retrofitted, mouse-only, same gap
// chip() already closed once this session for the "Go to note" chip.
// Dispatches a real click rather than duplicating each call site's own
// handler, so this stays a one-line addition wherever a `.unlink` span
// already has its click listener attached.
function makeUnlinkAccessible(span) {
  span.setAttribute("role", "button");
  span.setAttribute("tabindex", "0");
  span.addEventListener("keydown", (event) => {
    if (event.key === "Enter" || event.key === " ") {
      event.preventDefault();
      span.click();
    }
  });
}

// A <select> from [value, label] pairs, with one option preselected.
function buildSelect(options, selected) {
  const select = document.createElement("select");
  select.className = "small-select";
  for (const [value, label] of options) {
    const option = document.createElement("option");
    option.value = value;
    option.textContent = label;
    if (value === selected) option.selected = true;
    select.appendChild(option);
  }
  return select;
}

// --- asking before something irreversible (§35F) ----------------------------------
//
// `window.confirm` is not dependable in the shell this app also runs in.
// pywebview's backends vary in whether they implement it at all, and one that
// does not returns `undefined`, which every `if (!confirm(...)) return;` in
// this file reads as "the user said no". The button then does nothing, says
// nothing, and looks broken. That is the reported shape of "the recycle bin
// empty now button doesn't work either": the endpoint behind it is fine, and
// the click never got past the gate.
//
// A promise-based dialog fixes that and is better in the browser too, it is
// styled like the app, it says what the action is in a heading rather than a
// system font, and the dangerous option can be marked as dangerous.
//: `checkbox` adds one optional decision to the same dialog, `{label, title,
//: checked}`, and the promise then resolves to `{ok, checked}` instead of a
//: bare boolean. Added for "also take this picture out of the notes that show
//: it", which is a second, *different* act from deleting the file: a
//: second dialog for it would be a second modal to dismiss, and doing it
//: silently would be the app editing someone's notes without being asked.
//:
//: Callers that pass no checkbox still get a plain boolean, because thirty of
//: them read the result directly and widening that contract for all of them
//: would be a rewrite in service of one feature.
function confirmDialog(message, options = {}) {
  const { confirmLabel = "OK", cancelLabel = "Cancel", danger = true, checkbox = null } = options;
  return new Promise((resolve) => {
    const overlay = document.createElement("div");
    overlay.className = "modal-overlay confirm-overlay";
    overlay.setAttribute("role", "dialog");
    overlay.setAttribute("aria-modal", "true");

    const card = document.createElement("div");
    card.className = "card modal-card confirm-card";
    const text = document.createElement("p");
    text.className = "confirm-text";
    // Blank lines in these messages are deliberate paragraphs, the second is
    // usually the consequence ("This cannot be undone"), which is the part
    // worth reading, so it is not run together with the first.
    for (const part of String(message).split(/\n{2,}/)) {
      const line = document.createElement("span");
      line.textContent = part;
      text.append(line, document.createElement("br"));
    }
    const row = document.createElement("div");
    row.className = "row confirm-actions";

    //: Built before `close`, which reads it.
    let extra = null;
    if (checkbox) {
      const label = document.createElement("label");
      label.className = "checkbox-label confirm-extra";
      extra = document.createElement("input");
      extra.type = "checkbox";
      extra.checked = Boolean(checkbox.checked);
      const caption = document.createElement("span");
      caption.textContent = checkbox.label;
      label.append(extra, caption);
      if (checkbox.title) label.title = checkbox.title;
      card.appendChild(label);
    }

    let settled = false;
    const close = (answer) => {
      if (settled) return;
      settled = true;
      document.removeEventListener("keydown", onKey, true);
      overlay.remove();
      returnFocus?.focus?.();
      resolve(checkbox ? { ok: answer, checked: answer && Boolean(extra?.checked) } : answer);
    };
    const onKey = (event) => {
      // Escape cancels and Enter confirms, but only while this dialog is up, 
      // captured, so a keyboard shortcut elsewhere can't fire underneath it.
      if (event.key === "Escape") {
        event.stopPropagation();
        close(false);
      } else if (event.key === "Enter" && event.target.tagName !== "BUTTON") {
        event.stopPropagation();
        close(true);
      }
    };

    const returnFocus = document.activeElement;
    const cancel = smallButton(cancelLabel, cancelLabel, () => close(false));
    const go = smallButton(confirmLabel, confirmLabel, () => close(true), false);
    if (danger) go.classList.add("danger");
    row.append(cancel, go);
    //: `insertBefore`, because the checkbox above was appended to the card
    //: already and the buttons belong under it.
    card.insertBefore(text, card.firstChild);
    card.appendChild(row);
    overlay.appendChild(card);
    // Clicking the backdrop cancels, the way every other overlay here behaves.
    wireBackdropClose(overlay, () => close(false));
    document.addEventListener("keydown", onKey, true);
    document.body.appendChild(overlay);
    // Cancel takes focus, not the dangerous one: a stray Enter or Space
    // arriving with the dialog must not be the thing that deletes the notes.
    cancel.focus();
  });
}

// `confirmDialog`'s other missing sibling: show a whole piece of text with
// no decision to make, just a way to close it. Asked for directly: "longer
// logs get truncated with no way to expand or collapse and view the whole
// log", the Library's Activity cards show a clipped preview (server-side,
// `ACTIVITY_DETAIL_CHARS`) so the grid stays scannable, and this is what a
// click on one opens instead of doing nothing.
function showDetailDialog(title, text) {
  return new Promise((resolve) => {
    const overlay = document.createElement("div");
    overlay.className = "modal-overlay confirm-overlay";
    overlay.setAttribute("role", "dialog");
    overlay.setAttribute("aria-modal", "true");
    overlay.setAttribute("aria-label", title);

    const card = document.createElement("div");
    card.className = "card modal-card confirm-card detail-dialog-card";
    const heading = document.createElement("h3");
    heading.textContent = title;
    const body = document.createElement("p");
    body.className = "confirm-text detail-dialog-text";
    body.textContent = text;
    const row = document.createElement("div");
    row.className = "row confirm-actions";

    let settled = false;
    const close = () => {
      if (settled) return;
      settled = true;
      document.removeEventListener("keydown", onKey, true);
      overlay.remove();
      returnFocus?.focus?.();
      resolve();
    };
    const onKey = (event) => {
      if (event.key === "Escape" || event.key === "Enter") {
        event.stopPropagation();
        close();
      }
    };

    const returnFocus = document.activeElement;
    const ok = smallButton("Close", "Close", close, false);
    row.append(ok);
    card.append(heading, body, row);
    overlay.appendChild(card);
    wireBackdropClose(overlay, () => close());
    document.addEventListener("keydown", onKey, true);
    document.body.appendChild(overlay);
    ok.focus();
  });
}

// `confirmDialog`'s missing sibling: ask for a line of text.
//
// DESIGN.md bans `window.confirm` because the desktop shell does not reliably
// implement it, and a button gated behind one that returns `undefined`
// silently does nothing. `window.prompt` is the same trap with the same shell,
// and the app has been calling it for every rename, so this is not a new
// dialog for a new feature, it is the one the rule always implied.
//
// Resolves to the trimmed text, or "" for cancel/empty. "" rather than null so
// every caller's guard is the same shape as the confirm one.
//: `segment`, when given, adds **one** segmented control under the field:
//: `{label, options: [{value, label, title}], value}`. The dialog then
//: resolves `{text, choice}` instead of a bare string.
//:
//: One extra control in the dialog that already exists, rather than a second
//: dialog after this one. CLAUDE.md records why in as many words: bookmark URL
//: editing was reported broken five times while working end-to-end every time,
//: and the fault was never the handler, "a second modal that only appears
//: *after* you commit the first is a bad way to expose a second field". Naming
//: a new board and saying what kind of board it is are one decision.
function promptDialog(message, initial = "", { confirmLabel = "Save", segment = null } = {}) {
  return new Promise((resolve) => {
    const overlay = document.createElement("div");
    overlay.className = "modal-overlay confirm-overlay";
    overlay.setAttribute("role", "dialog");
    overlay.setAttribute("aria-modal", "true");

    const card = document.createElement("div");
    card.className = "card modal-card confirm-card prompt-card";
    //: **A title row, not a sentence above a field.** Reported as one of two
    //: dialogs off the modal recipe: this card's first child was a `<p>`, so
    //: the "New board" dialog had no heading at all while every other dialog
    //: in the app leads with one. Every `promptDialog` message is a short
    //: prompt ("Name the new board:", "Rename this chat:", "Tag to add to the
    //: selected notes:"), which is a title, so all twenty-odd callers are
    //: right to promote it rather than only this one.
    //:
    //: `confirmDialog`'s message stays a `<p>`: that one really is a
    //: sentence, often two, and a question is body copy.
    const head = document.createElement("div");
    head.className = "row confirm-head";
    const text = document.createElement("h3");
    text.className = "confirm-title";
    text.textContent = message;
    head.appendChild(text);
    const input = document.createElement("input");
    input.type = "text";
    input.value = initial;
    input.setAttribute("aria-label", message);

    //: The optional segmented control. `.seg`, the app's own recipe: the
    //: same one the Library's Cards/Rows switch and the dashboard's range
    //: pickers use: so this is a control the user has already met.
    let chosen = segment?.value ?? segment?.options?.[0]?.value ?? null;
    let segRow = null;
    let segField = null;
    if (segment?.options?.length) {
      //: **The choice is named, and the two options fill their track.**
      //: Reported: "also redesign that whiteboard and mindmap toggle in the
      //: popup, its ugly", with a screenshot of the New board dialog. Two
      //: things were wrong in it and both are about the track. `.seg` is
      //: `display: inline-flex`, which in this card (a flex column that
      //: stretches its children) makes the *track* full width while the two
      //: buttons keep their content width: the right half of the pill was
      //: empty, so the control read as a stray bar with two words in it. And
      //: nothing on screen said what the choice was for, because
      //: `segment.label` only ever reached `aria-label`, which a sighted
      //: reader cannot see.
      //:
      //: The label is now drawn, the buttons share the track equally (the CSS
      //: in 06-timeline-dialogs.css), and each option can carry an icon
      //: through `setLabel`'s "ph:name Label" contract, so Board and Mind map
      //: are told apart by shape before they are read.
      segField = document.createElement("div");
      segField.className = "confirm-seg-field";
      if (segment.label) {
        const segLabel = document.createElement("span");
        segLabel.className = "confirm-seg-label";
        segLabel.textContent = segment.label;
        segField.appendChild(segLabel);
      }
      segRow = document.createElement("div");
      segRow.className = "seg seg-compact confirm-seg";
      segRow.setAttribute("role", "group");
      segRow.setAttribute("aria-label", segment.label || message);
      segField.appendChild(segRow);
      for (const option of segment.options) {
        const button = document.createElement("button");
        button.type = "button";
        setLabel(button, option.label);
        button.dataset.value = option.value;
        if (option.title) button.title = option.title;
        button.classList.toggle("active", option.value === chosen);
        button.setAttribute("aria-pressed", option.value === chosen ? "true" : "false");
        button.addEventListener("click", () => {
          chosen = option.value;
          for (const sibling of segRow.querySelectorAll("button")) {
            const on = sibling.dataset.value === chosen;
            sibling.classList.toggle("active", on);
            sibling.setAttribute("aria-pressed", on ? "true" : "false");
          }
          // Straight back to the name: choosing the kind is a detour on the
          // way to typing, not the end of the interaction.
          input.focus();
        });
        segRow.appendChild(button);
      }
    }

    let settled = false;
    const close = (answer) => {
      if (settled) return;
      settled = true;
      document.removeEventListener("keydown", onKey, true);
      overlay.remove();
      returnFocus?.focus?.();
      // The shape changes only when a segment was asked for, so every existing
      // caller keeps the bare string it has always awaited.
      resolve(segment ? { text: answer, choice: chosen } : answer);
    };
    const onKey = (event) => {
      // Captured, so a shortcut elsewhere cannot fire underneath the dialog, 
      // the same reason confirmDialog captures.
      //
      // **preventDefault, not just stopPropagation.** Reported: pressing
      // Enter after typing a title looked like it "did nothing" - the title
      // was in fact saved (a real POST fired), but the dialog immediately
      // reopened empty, so the user only ever saw a blank prompt sitting
      // there. `close()` below returns focus to whatever triggered the
      // dialog - here, the "+ New document" button - synchronously, *while
      // this Enter keypress is still in flight*. Stopping propagation keeps
      // the keydown from reaching the input as a target, but the browser
      // still owes this physical key its native activation behaviour, and
      // now that behaviour lands on the button that just regained focus:
      // its own "Enter activates the focused button" default action fires,
      // clicking it again and opening a second, blank dialog. preventDefault
      // is what tells the browser this key press is spoken for.
      if (event.key === "Escape") {
        event.preventDefault();
        event.stopPropagation();
        close("");
      } else if (event.key === "Enter") {
        event.preventDefault();
        event.stopPropagation();
        close(input.value.trim());
      }
    };

    const returnFocus = document.activeElement;
    const row = document.createElement("div");
    row.className = "row confirm-actions";
    row.append(
      smallButton("Cancel", "Cancel", () => close("")),
      smallButton(confirmLabel, confirmLabel, () => close(input.value.trim()), false)
    );
    card.append(head, input);
    if (segField) card.append(segField);
    card.append(row);
    overlay.appendChild(card);
    wireBackdropClose(overlay, () => close(""));
    document.addEventListener("keydown", onKey, true);
    document.body.appendChild(overlay);
    // The text, selected: a rename usually replaces the name rather than
    // editing it, and a caret at position 0 makes you clear it by hand first.
    input.focus();
    input.select();
  });
}

//: Shared by every overlay's backdrop-click-to-close.
//:
//: Reported directly: "when I try to highlight text in text boxes in popup
//: displays, the popup often just closes." `click` fires wherever the mouse
//: went *up*, not where it went down, so starting a text selection inside
//: the card and releasing outside it (a completely normal way to select the
//: last word or two) fires a click whose target is the backdrop, which every
//: one of these listeners used to read as "the backdrop was clicked" and
//: close on. Recording where the *mousedown* started tells the two apart: a
//: real backdrop click starts and ends on the backdrop; a selection drag
//: starts inside the card.
//: `alsoBackdrop` is a selector for elements that *look* like empty space
//: even though they are not the overlay itself, a full-width layout column
//: whose own box extends well past the thing it is centring.
//:
//: Reported: "I cant click off the documents or images to close the lightbox
//: and the close button doesnt work all the time." Measured with the viewer
//: open on a 1440x900 window: `.lightbox-column` is **1396px wide and 134px
//: tall**, so the whole horizontal band either side of the picture belongs to
//: the column, not the backdrop. The four screen edges did close it, which is
//: why this reads as intermittent rather than broken: whether a click "off
//: the image" works depends on whether it landed above or beside it.
//:
//: The elements named by the caller are the ones with no content of their
//: own. `e.target === el` still has to hold for each: a click that lands on
//: the picture, the caption, a button or any other real child is a click on
//: that child, and closes nothing.
function wireBackdropClose(overlay, close, alsoBackdrop = "") {
  const isBackdrop = (target) =>
    target === overlay || (alsoBackdrop && target instanceof Element && target.matches(alsoBackdrop));
  let downOnBackdrop = false;
  overlay.addEventListener("mousedown", (e) => {
    downOnBackdrop = isBackdrop(e.target);
  });
  overlay.addEventListener("click", (e) => {
    if (isBackdrop(e.target) && downOnBackdrop) close();
  });
}

function smallButton(label, title, onClick, ghost = true) {
  // (Wave I) icon-only buttons need a name for screen readers, the
  // title doubles as one.
  const button = document.createElement("button");
  button.className = ghost ? "ghost small" : "small";
  setLabel(button, label);
  // **A button whose whole content is one glyph is square, without the caller
  // having to remember `.icon-only`.** Reported: "the backup x buttons arent
  // square" -- `smallButton("x", ...)` inherits `button.small`'s text padding
  // (0 0.8rem) and comes out a rectangle. CSS cannot see text, so this is the
  // one place that can decide it: setLabel has just told us whether a label
  // followed the icon (it emits `.ph-text` only then), and a bare character
  // label leaves one character of text behind. Everything with real words is
  // untouched.
  if (!button.querySelector(".ph-text") && button.textContent.trim().length <= 1) {
    button.classList.add("icon-only");
  }
  button.title = title;
  if (title) button.setAttribute("aria-label", title);
  button.addEventListener("click", onClick);
  return button;
}

// --- one map chip and one map preview, used everywhere ----------------------
//
//: MINDMAP_PLAN.md §5 item 12, and the sentence in it that is the whole
//: reason this exists: *"One `mapChip()` and one `mapPreview()`, used by all
//: of them: the app's recurring failure is the same object drawn five
//: ways."*
//:
//: It had already happened twice before this was written. The Library's board
//: card (`renderLibraryBoardsGallery`, whiteboard.js) drew the minimap with
//: edges, labels, a sketch squiggle and an edge-aware label side; the
//: dashboard's boards widget (`dashBoardThumb`, dashboard.js) drew the *same*
//: `preview_items` at a different scale with **no edges at all**, so the one
//: fact that distinguishes a map from a board was missing from one of the two
//: places a map appears. Neither was wrong on its own; they were two opinions
//: of one picture.
//:
//: Lives in app.js because five files draw these, whiteboard.js, dashboard.js,
//: the timeline and the note renderer here, and the chat transcript, and
//: app.js is the one loaded before all of them (see index.html's script
//: order).

//: The sizes a preview is ever drawn at. A named size rather than a pair of
//: numbers per call site: "the Library card's minimap" and "the dashboard
//: row's thumbnail" are the two real cases, and letting each caller pass its
//: own geometry is how the two drifted apart in the first place.
//:
//: `labels` is off at row size deliberately. Sixteen characters beside a 9×6
//: block is a legible texture in a 100×56 card; the same text in a 40×40
//: thumbnail is a smear.
//:
//: `w`/`h` are the *box the picture is letterboxed into*, not the viewBox:
//: since the drawing is now made at the board's own ratio, the two are the
//: same only for a board that happens to be shaped like the card. Everything
//: else here (`pad`, `blockW`, `blockH`, `font`) is a size in that box, and
//: `mapPreview` divides each of them by the scale the browser is about to
//: apply, so a node in a tall map is drawn the same number of pixels across
//: as a node in a wide one. Without that division the block sizes are in
//: viewBox units and a square board's nodes come out 44% smaller than a wide
//: board's, for no reason a reader could see.
const MAP_PREVIEW_SIZES = {
  card: { w: 100, h: 56, pad: 3, blockW: 9, blockH: 6, labels: true, font: 4.2 },
  row: { w: 40, h: 40, pad: 3, blockW: 4, blockH: 3, labels: false, font: 0 },
};

//: The long side of the board's own box, in viewBox units. Arbitrary: only
//: the *ratio* of the viewBox is meaningful, since `preserveAspectRatio`
//: scales it into the card either way. 100 keeps the numbers in the DOM
//: readable when someone inspects a thumbnail.
const MAP_PREVIEW_BASE = 100;

//: How round a node is, as a fraction of its short side. A node on the canvas
//: is a rounded card, not a dot and not a pill, and the miniature says the
//: same thing at a twentieth of the size.
const MAP_PREVIEW_NODE_ROUNDING = 0.35;

//: The floor on a block's drawn size, as a multiple of the size every block
//: used to be. A small object on a large board is a fraction of a viewBox
//: unit once it is drawn to scale, and a preview whose smallest things are
//: invisible is a preview of the big ones only.
const MAP_PREVIEW_MIN_BLOCK = 0.5;

//: A character's width as a fraction of the type size, for deciding whether a
//: label fits inside its own shape. Rough on purpose: the alternative is
//: measuring text in the DOM, which means laying out every thumbnail twice.
const MAP_PREVIEW_CHAR_WIDTH = 0.55;

//: **Which ink a label takes when it sits on a coloured node.** Measured
//: with `scratchpad/ui-sweeps/preview.js` the day inside labels landed: a
//: map's branch nodes are drawn at full strength in their branch colour, and
//: the app's own ink on a mid-tone blue is 3.82:1, under the 4.5 the rest of
//: the app is held to. White on that same blue is 4.9:1. The rule is the
//: usual one: pick whichever of the two the colour is further from, and
//: return the name of the class that paints it (see 10-responsive.css).
//:
//: Only for a label *inside* a coloured block. A label beside one sits on the
//: paper and keeps `--ink` from the stylesheet, which is where the theme
//: belongs.
function mapPreviewOnColour(colour) {
  const hex = String(colour || "").trim();
  const m = /^#?([0-9a-f]{6})$/i.exec(hex);
  if (!m) return null;
  const value = parseInt(m[1], 16);
  const channel = (c) => {
    const v = c / 255;
    return v <= 0.03928 ? v / 12.92 : ((v + 0.055) / 1.055) ** 2.4;
  };
  const luminance =
    0.2126 * channel((value >> 16) & 255) +
    0.7152 * channel((value >> 8) & 255) +
    0.0722 * channel(value & 255);
  // 0.18 is where white and black are equally far in WCAG terms.
  return luminance > 0.18 ? "dark" : "light";
}

//: The shortest label worth putting inside a shape. Below this the block is
//: too small to hold a word and the label goes beside it, where it has the
//: whole margin to run into: "M…" on a node says less than nothing.
const MAP_PREVIEW_MIN_INSIDE_CHARS = 5;

//: How much of the card's width the letterboxed board has to fill before its
//: labels are worth drawing, as a fraction. See where it is used.
const MAP_PREVIEW_LABEL_FLOOR = 0.6;

//: Two decimals, as a number. Every coordinate in a thumbnail is now a
//: division by a scale factor, so without this the DOM fills with
//: `x="17.142857142857142"`: bytes, and unreadable when someone inspects a
//: card to work out what it drew.
function round2(value) {
  return Math.round(value * 100) / 100;
}

//: **One parent→child edge, as a curve.** Straight lines were what the first
//: version drew, and a tree of straight segments at thumbnail size reads as a
//: bar chart: the canvas draws cubic curves (`wbMapEdgePathD`), so the
//: miniature draws them too, and the two pictures of one map agree.
//:
//: The control points follow the dominant axis rather than the board's
//: `layout`: a `tree-right` map curves out sideways and a `tree-down` map
//: curves downward, and asking each segment which way it actually runs gets
//: both right, including the nodes someone dragged off the layout by hand.
//: The caller says how the curve is coloured, because the two ways of doing it
//: cannot both come from a class: an edge in its branch colour carries a
//: `stroke` *attribute*, and a presentation attribute loses to any class that
//: declares `stroke`. So `.board-minimap-edge` is geometry only, and an
//: uncoloured edge takes `.board-minimap-edge-accent` on top of it. The
//: alternative, `el.style.stroke`, writes a `style` attribute, which this
//: app's CSP drops and `mindmap3.js` asserts the absence of.
function mapPreviewEdge(NS, px, py, blockW, blockH, edge) {
  const curve = document.createElementNS(NS, "path");
  curve.setAttribute("class", "board-minimap-edge");
  // Half a block: a line should meet the centre of what it joins, and a block
  // is drawn from its top-left corner.
  const x1 = px(edge.x1) + blockW / 2;
  const y1 = py(edge.y1) + blockH / 2;
  const x2 = px(edge.x2) + blockW / 2;
  const y2 = py(edge.y2) + blockH / 2;
  const dx = x2 - x1;
  const dy = y2 - y1;
  const d = Math.abs(dx) >= Math.abs(dy)
    ? `M${round2(x1)} ${round2(y1)} C${round2(x1 + dx / 2)} ${round2(y1)} ${round2(x2 - dx / 2)} ${round2(y2)} ${round2(x2)} ${round2(y2)}`
    : `M${round2(x1)} ${round2(y1)} C${round2(x1)} ${round2(y1 + dy / 2)} ${round2(x2)} ${round2(y2 - dy / 2)} ${round2(x2)} ${round2(y2)}`;
  curve.setAttribute("d", d);
  return curve;
}

//: A miniature of what is actually on a board, from `preview_items` /
//: `preview_edges`, positions already normalised into 0..1 against the
//: board's own bounds by `routes_whiteboard._board_preview`, so this draws the
//: real layout without the client ever loading the board.
//:
//: **An empty board draws the empty state, not nothing.** It used to return
//: null and each caller improvised: the Library's card mode drew no picture
//: at all, its rows mode drew a dashed rail so the rows would still line up,
//: and the dashboard skipped the thumbnail, so three surfaces disagreed about
//: what an empty map looks like and two of them lost their left edge. The
//: empty state is drawn here, once, in the same language as a real preview: a
//: ghost of a three-node map on the same paper, which says "a map goes here"
//: where a blank box said nothing.
//:
//: Built with SVG attributes and never an inline `style` string: this app's
//: CSP drops those outright, and thirty-five of them once shipped as silently
//: dead markup (CLAUDE.md, "a policy silently refusing the work").
function mapPreview(board, { size = "card" } = {}) {
  const geo = MAP_PREVIEW_SIZES[size] || MAP_PREVIEW_SIZES.card;
  const items = Array.isArray(board?.preview_items) ? board.preview_items : [];
  const NS = "http://www.w3.org/2000/svg";
  const svg = document.createElementNS(NS, "svg");
  svg.setAttribute("class", `board-minimap board-minimap-${size}`);
  svg.setAttribute("aria-hidden", "true");

  //: **The board's own shape, letterboxed into the card's box.** The viewBox
  //: is drawn at `preview_aspect` (the board's width/height, which
  //: normalising the positions into 0..1 threw away) and `meet` fits it
  //: inside the element rather than stretching it to fill: a map that runs
  //: down the page used to come back as the same wide rectangle as one that
  //: runs across, and every board in the Library was the same shape as every
  //: other, which is a picture of the card, not of the board.
  const aspect = Number(board?.preview_aspect) > 0 ? Number(board.preview_aspect) : 1;
  const vw = aspect >= 1 ? MAP_PREVIEW_BASE : MAP_PREVIEW_BASE * aspect;
  const vh = aspect >= 1 ? MAP_PREVIEW_BASE / aspect : MAP_PREVIEW_BASE;
  svg.setAttribute("viewBox", `0 0 ${round2(vw)} ${round2(vh)}`);
  svg.setAttribute("preserveAspectRatio", "xMidYMid meet");
  // The scale `meet` is about to apply, so every fixed size below can be
  // expressed in the box's units and divided back out: see MAP_PREVIEW_SIZES.
  const scale = Math.min(geo.w / vw, geo.h / vh);
  const unit = 1 / scale;
  const pad = geo.pad * unit;
  const blockW = geo.blockW * unit;
  const blockH = geo.blockH * unit;
  // The drawable box, inset by the padding on both sides so an item at the
  // extreme edge of the board lands inside the thumbnail rather than half
  // outside it. Floored at zero: an extreme ratio can leave less room than
  // one block needs, and a negative span would mirror the whole picture.
  const spanX = Math.max(0, vw - pad * 2 - blockW);
  const spanY = Math.max(0, vh - pad * 2 - blockH);
  //: **Labels need width, and a letterboxed tall board has not got it.**
  //: Measured on the first run of the redesigned card: a board half as wide as
  //: it is tall draws its paper 82px across inside a 293px card, and the
  //: sixteen-character labels that read as a texture at 293px overlapped each
  //: other and the nodes they belonged to ("First branchRoot"). Below
  //: `MAP_PREVIEW_LABEL_FLOOR` of the box's width the labels come off and the
  //: shape carries the card, which is what the row size already does.
  const labels = geo.labels && vw * scale >= geo.w * MAP_PREVIEW_LABEL_FLOOR;
  const px = (x) => pad + (Number(x) || 0) * spanX;
  const py = (y) => pad + (Number(y) || 0) * spanY;

  //: **The paper.** The frame and fill used to belong to the `<svg>` element
  //: itself, which is the card's box, so the border said "this is the shape
  //: of the board" while being the shape of the card. Drawn as a rect inside
  //: the viewBox instead, it is the letterboxed board, and it is the thing a
  //: sweep can measure: its rendered width/height *is* `preview_aspect`.
  const paper = document.createElementNS(NS, "rect");
  paper.setAttribute("class", "board-minimap-paper");
  paper.setAttribute("x", "0");
  paper.setAttribute("y", "0");
  paper.setAttribute("width", String(round2(vw)));
  paper.setAttribute("height", String(round2(vh)));
  paper.setAttribute("rx", String(round2(2 * unit)));
  svg.appendChild(paper);

  if (!items.length) {
    // The one designed empty state, in the same language as a real preview:
    // three nodes and two curves, ghosted. See the header comment.
    paper.classList.add("board-minimap-paper-empty");
    const ghost = document.createElementNS(NS, "g");
    ghost.setAttribute("class", "board-minimap-ghost");
    const shape = [
      { x: 0.04, y: 0.5 },
      { x: 0.72, y: 0.16 },
      { x: 0.72, y: 0.84 },
    ];
    for (const child of shape.slice(1)) {
      ghost.appendChild(
        mapPreviewEdge(NS, px, py, blockW, blockH, {
          x1: shape[0].x,
          y1: shape[0].y,
          x2: child.x,
          y2: child.y,
        })
      );
    }
    for (const node of shape) {
      const block = document.createElementNS(NS, "rect");
      block.setAttribute("x", String(round2(px(node.x))));
      block.setAttribute("y", String(round2(py(node.y))));
      block.setAttribute("width", String(round2(blockW)));
      block.setAttribute("height", String(round2(blockH)));
      block.setAttribute("rx", String(round2(Math.min(blockW, blockH) * MAP_PREVIEW_NODE_ROUNDING)));
      ghost.appendChild(block);
    }
    svg.appendChild(ghost);
    return svg;
  }

  //: **The tree, drawn first so the lines sit under the blocks** rather than
  //: across their labels. `preview_edges` is the parent→child segments in the
  //: same normalised space as the items (§9.1); an ordinary board ships an
  //: empty list and this loop does nothing, which is exactly the difference
  //: between the two kinds that a scatter of dots cannot show.
  for (const edge of Array.isArray(board.preview_edges) ? board.preview_edges : []) {
    const curve = mapPreviewEdge(NS, px, py, blockW, blockH, edge);
    // The branch's colour, from the server (`_map_branch_colors`), so the
    // thumbnail is the same picture as the canvas rather than a grey diagram
    // of it.
    if (edge.color) curve.setAttribute("stroke", edge.color);
    else curve.classList.add("board-minimap-edge-accent");
    svg.appendChild(curve);
  }

  //: **How big this thing is on the board**, in the viewBox's units, from the
  //: `w`/`h` the server now ships as fractions of the same span `x` and `y`
  //: were normalised into (INBOX 68).
  //:
  //: This is the difference between a picture of the board and a picture of
  //: the renderer. Measured before it: every block in every preview came back
  //: at one size (29.1x21.8 in the dashboard, 26.4x17.6 in the Library), so a
  //: banner across the top of a board, the column beside it and a sticky note
  //: were three identical grey rectangles, which is the owner's "grey blobs"
  //: exactly. A board's own shapes are most of what tells two boards apart.
  //:
  //: Floors, not raw values: a small object on a large board is a fraction of
  //: a viewBox unit and would vanish, and something has to be visible for the
  //: preview to be a preview. The ceiling is the drawable span, so one huge
  //: object cannot spill outside the paper it is drawn on. An older payload
  //: (a cached list from before the server sent sizes) has no `w`, and falls
  //: back to the uniform block, which is what this drew for everything.
  const sizeOf = (item) => {
    const w = Number(item.w);
    const h = Number(item.h);
    if (!(w > 0) || !(h > 0)) return { w: blockW, h: blockH };
    return {
      w: Math.min(spanX + blockW, Math.max(blockW * MAP_PREVIEW_MIN_BLOCK, w * spanX)),
      h: Math.min(spanY + blockH, Math.max(blockH * MAP_PREVIEW_MIN_BLOCK, h * spanY)),
    };
  };

  for (const item of items) {
    const nx = px(item.x);
    const ny = py(item.y);
    const size = sizeOf(item);
    if (item.kind === "sketch") {
      // A sketch is strokes, and the thumbnail does not have them, stroke
      // data is the one thing `preview_items` deliberately does not ship. A
      // squiggle says "something drawn here", which is the fact that was
      // missing entirely: a sketch-only board previewed as an empty rectangle
      // beside a line reading "2 sketches".
      const mark = document.createElementNS(NS, "path");
      mark.setAttribute("class", "board-minimap-sketch");
      const wave = blockW / 1.8;
      mark.setAttribute("d", `M${round2(nx)} ${round2(ny + blockH * 0.8)} q${round2(wave / 2)} ${round2(-wave)} ${round2(wave)} 0 t${round2(wave)} 0`);
      svg.appendChild(mark);
      continue;
    }
    const dot = document.createElementNS(NS, "rect");
    const grey = item.kind === "card" ? "board-minimap-card" : "board-minimap-object";
    // A branch node takes its own class rather than the grey one, for the
    // reason on `mapPreviewEdge`: the fill arrives as an attribute, and the
    // grey classes declare `fill`, which would win.
    dot.setAttribute("class", item.color ? "board-minimap-branch" : grey);
    dot.setAttribute("x", String(round2(nx)));
    dot.setAttribute("y", String(round2(ny)));
    dot.setAttribute("width", String(round2(size.w)));
    dot.setAttribute("height", String(round2(size.h)));
    // Rounded like the node it stands for, and rounded by its own size rather
    // than by a fixed 1.5: the block is drawn at a different number of viewBox
    // units on every board shape now, so a constant radius was a sharp corner
    // on one card and a pill on the next.
    dot.setAttribute("rx", String(round2(Math.min(size.w, size.h) * MAP_PREVIEW_NODE_ROUNDING)));
    // The grey blocks are faded because an unlabelled box is texture; a
    // coloured node is carrying which branch it belongs to, so it is drawn at
    // full strength (`.board-minimap-branch`).
    if (item.color) dot.setAttribute("fill", item.color);
    svg.appendChild(dot);
    if (!labels || !item.label) continue;
    //: **What the item says**, which is why this stopped being a list of bare
    //: points. Reported as "the whiteboard preview is poor", and the
    //: screenshot was three boards named "Cloud computing" showing three
    //: identical arrangements of blank grey rectangles, a picture that could
    //: not tell them apart, which is what a preview is for.
    const text = document.createElementNS(NS, "text");
    text.setAttribute("class", "board-minimap-label");
    //: **Which side of the block the label sits on.** Drawn always to the
    //: right in the first version, and looking at the result showed the
    //: problem immediately: an item at the far right of a board is at nx ≈ 91
    //: in a 100-wide viewBox, so its label ran off the edge and came out
    //: sliced mid-word ("Cloud computi"). Past halfway it hangs off the left
    //: instead, which is the same amount of room from the other direction.
    //: **Inside the shape when the shape can hold it**, beside it when it
    //: cannot. Reported as the text "sitting off its shapes", and measured
    //: before this: six of six labels on a map card were drawn outside every
    //: block, because a block was a fixed 9x6 units whatever it stood for and
    //: nothing could ever contain a word. Now that a topic is drawn at its own
    //: size, a 200x56 node has room for its own name, which is where a person
    //: reading a map expects to find it.
    //:
    //: The test is the text's own width against the block's: `font` units per
    //: character is the same approximation the ellipsis below uses, and a
    //: character is about half the type size in this family.
    const fontUnits = geo.font * unit;
    const perChar = fontUnits * MAP_PREVIEW_CHAR_WIDTH;
    //: How many characters the block itself can hold, with a character's
    //: width of padding at each end. A node is usually wider than it is long
    //: in words, so this is normally the whole label; when it is not, the
    //: label is cut to fit *inside* rather than being pushed outside, because
    //: a name on its own node reads as that node's name and the same name
    //: floating between two edges reads as a third thing on the board.
    const roomFor = Math.floor((size.w - perChar * 2) / perChar);
    const tall = size.h >= fontUnits * 1.6;
    const fits = tall && roomFor >= MAP_PREVIEW_MIN_INSIDE_CHARS;
    const budget = fits ? Math.min(roomFor, 16) : 16;
    const shown = item.label.length > budget
      ? `${item.label.slice(0, Math.max(1, budget - 1)).trimEnd()}…`
      : item.label;
    const rightHalf = nx > vw / 2;
    const gap = 1.5 * unit;
    if (fits) {
      text.setAttribute("x", String(round2(nx + size.w / 2)));
      text.setAttribute("y", String(round2(ny + size.h / 2 + fontUnits * 0.36)));
      text.setAttribute("text-anchor", "middle");
      text.classList.add("board-minimap-label-inside");
      //: A class, not a `fill` attribute, and this is the trap the blocks
      //: above already carry a note about: `.board-minimap-label` declares
      //: `fill` in the stylesheet, and a CSS declaration beats a presentation
      //: attribute however specific the attribute looks. Setting the
      //: attribute changed nothing at all, measured: 3.82:1 before and after.
      const onColour = item.color ? mapPreviewOnColour(item.color) : null;
      if (onColour) text.classList.add(`board-minimap-label-${onColour}`);
    } else {
      text.setAttribute("x", String(round2(rightHalf ? nx - gap : nx + size.w + gap)));
      text.setAttribute("y", String(round2(ny + size.h * 0.73)));
    }
    // The type size, in the box's units divided back out, for the same reason
    // the blocks are: a fixed CSS `font-size` here is in viewBox units, so the
    // labels on a square board came out half the size of the labels on a wide
    // one. The stylesheet keeps the colour and the family; only the size,
    // which depends on the board's shape, is set here.
    text.setAttribute("font-size", String(round2(fontUnits)));
    if (!fits && rightHalf) text.setAttribute("text-anchor", "end");
    // An ellipsis rather than a bare slice: "Connections prob" reads as
    // broken, "Connections pro…" reads as shortened.
    text.textContent = shown;
    svg.appendChild(text);
  }
  return svg;
}

//: How many things are on a board, as the sentence a person reads. On a map
//: the objects *are* the nodes, so calling them "images", which every surface
//: did before maps existed, is simply the wrong noun for the only thing on
//: the board.
function mapCountLabel(board) {
  const isMap = board?.type === "map";
  const nodes = board?.node_count || 0;
  const sketches = board?.sketch_count || 0;
  const objects = board?.object_count || 0;
  const parts = [];
  if (nodes) parts.push(`${nodes} card${nodes === 1 ? "" : "s"}`);
  if (sketches) parts.push(`${sketches} sketch${sketches === 1 ? "" : "es"}`);
  if (objects) {
    //: **"items", not "images", on a board.** `object_count` is
    //: `count(WhiteboardObject)` with no filter on `kind`
    //: (`routes_whiteboard.py`, the `/whiteboard/boards` listing), and a
    //: board's objects are text, images, notes, documents, files and links.
    //: A board seeded with five text boxes read "5 images" in the dashboard
    //: widget and in the Library, which is the same class of wrong noun §5
    //: item 12 fixed for a map's nodes and missed here.
    parts.push(isMap
      ? `${objects} node${objects === 1 ? "" : "s"}`
      : `${objects} item${objects === 1 ? "" : "s"}`);
  }
  return parts.length ? parts.join(" · ") : isMap ? "Empty map" : "Empty board";
}

//: **A map as a chip**: its icon, its title and how many nodes it holds, and
//: pressing it opens the map. The one control every surface uses to refer to a
//: map in passing: a note body, the timeline, a dashboard row, the chat
//: transcript.
//:
//: A `<button>`, not a link: opening a map is a tab switch plus a board load
//: (`openWhiteboardBoard` does both), not a navigation this app has a URL for.
//: `.map-chip` sits on `.chip`, the app's own recipe, so it inherits the chip
//: height, radius and hover state rather than inventing a fourth pill shape.
//:
//: `board` may be as little as `{id, title}`, the chat transcript has an id
//: and a label and nothing else. The count line is simply omitted then, rather
//: than the chip refusing to draw or claiming "0 nodes".
//:
//: **`interactive: false` draws the same chip as a `<span>` with no handler**,
//: for the one context where the thing around it is already the control: the
//: dashboard's board rows are `role="button"` list items, and a `<button>`
//: inside one is a nested interactive control, two tab stops that do the same
//: thing, which is worse for a keyboard user than no chip at all. The chip is
//: identical to look at either way; only the element and the listener differ.
function mapChip(board, { onOpen = null, count = true, interactive = true } = {}) {
  const chip = document.createElement(interactive ? "button" : "span");
  if (interactive) chip.type = "button";
  chip.className = "chip map-chip";
  const isMap = board?.type !== "board";
  const title = board?.title || "Untitled map";
  setLabel(chip, `${isMap ? "ph:tree-structure" : "ph:squares-four"} ${title}`);
  const known = board && (board.object_count != null || board.node_count != null);
  if (count && known) {
    const meta = document.createElement("span");
    meta.className = "map-chip-count";
    meta.textContent = mapCountLabel(board);
    chip.appendChild(meta);
  }
  chip.title = known
    ? `${title}: ${mapCountLabel(board)}${interactive ? ". Press to open it." : ""}`
    : interactive
      ? `Open “${title}”`
      : title;
  if (interactive) {
    chip.addEventListener("click", (event) => {
      event.stopPropagation();
      if (onOpen) onOpen(board);
      else if (typeof openWhiteboardBoard === "function") openWhiteboardBoard(board?.id ?? null);
    });
  }
  return chip;
}

//: Every board the notebook has, by id, for the surfaces that are handed an
//: *entry* id and have to find out whether it is a board.
//:
//: One shared cache rather than a fetch per surface: the timeline paints a
//: hundred dots and the note list paints a chip per wiki link, and neither can
//: afford a request each. `apiJson`'s own `cacheMs` does the de-duplication: 
//: this only holds the id→row index built from it, which is the part that
//: would otherwise be rebuilt per dot.
let mapBoardIndexCache = null;
//: When that cache was last filled. It used to be `apiJson`'s own `cacheMs`
//: doing this, and that stopped working when `GET /whiteboard/boards` became
//: paged: `apiPagedList` walks pages through `api`, which has no read cache,
//: and one first page is not an index of every board anyway. So the eight
//: seconds moved here, onto the thing it was really protecting, which is the
//: index rather than the response.
let mapBoardIndexAt = 0;
const MAP_BOARD_INDEX_MS = 8000;

async function loadMapBoardIndex() {
  if (mapBoardIndexCache && Date.now() - mapBoardIndexAt < MAP_BOARD_INDEX_MS) return mapBoardIndexCache;
  const rows = await apiPagedList("/whiteboard/boards", 200, { silent: true }).catch(() => null);
  if (!rows) return mapBoardIndexCache || new Map();
  mapBoardIndexAt = Date.now();
  mapBoardIndexCache = new Map(rows.filter((b) => b.id != null).map((b) => [b.id, b]));
  return mapBoardIndexCache;
}

//: The board behind an entry id, or null, synchronous, because the callers
//: are inside a render loop. Returns null until `loadMapBoardIndex` has run
//: once, which is a surface that has not asked for boards yet rather than an
//: error: it degrades to the plain note rendering it had before.
function mapBoardById(id) {
  return mapBoardIndexCache?.get(id) || null;
}

//: The board whose title is `needle` (already lower-cased), or null.
//:
//: One matcher for the `[[wiki]]` resolver and the editor's `@` picker, so
//: the link the picker inserts and the link the renderer resolves cannot
//: drift apart. A board's own row carries `title` with the `# ` already
//: stripped; the raw `# My map` form is matched too, because that is what
//: the picker inserted before it learned better and those links are in real
//: notes now.
function mapBoardTitled(needle) {
  if (!needle || !mapBoardIndexCache) return null;
  for (const board of mapBoardIndexCache.values()) {
    const title = String(board.title || "").trim().toLowerCase();
    if (!title) continue;
    if (title === needle || `# ${title}` === needle) return board;
  }
  return null;
}

//: Every board the notebook has, newest-looking order preserved from
//: `/whiteboard/boards`, the editor's `@`/`[[` picker's own source. Empty
//: until `loadMapBoardIndex` has run once, which is the same "a surface that
//: has not asked for boards yet" degradation `mapBoardById` documents.
function mapBoardRows() {
  return mapBoardIndexCache ? [...mapBoardIndexCache.values()] : [];
}

//: **The star that says a note is a favourite, in both states.**
//:
//: Reported with a screenshot: the active one rendered as an **empty circle**
//:, no glyph at all. The cause is worth stating because it is a whole class
//: of bug, not one icon: the off state asked for `ph:star` and the on state
//: for `ph:star-slash`, and **`star-slash` is not in this app's vendored
//: Phosphor subset.** A missing glyph in an icon font is not an error, the
//: character simply has nothing to draw, so it fails silently, looks like a
//: styling problem, and nothing in the suite could see it. One icon name out
//: of 176 was wrong and there was no way to know. `tests/test_icon_names.py`
//: now checks every one against the font.
//:
//: The fix is also the better design. A slashed star means "remove", which is
//: a *verb* on a control whose job is to show *state*; every app the user has
//: ever used shows a favourite as a star that has changed colour. So both
//: states draw `ph:star` and the difference is `is-favourite`, plus
//: `aria-pressed`, which is what makes the state readable without the colour.
function favouriteButton(entry) {
  const button = smallButton(
    "ph:star",
    entry.pinned ? "Remove from Favourites" : "Add to Favourites (also floats it to the top)",
    async () => {
      const was = Boolean(entry.pinned);
      await api(`/entries/${entry.id}`, {
        method: "PUT",
        body: JSON.stringify({ pinned: !was }),
      });
      //: On the global stack, because a mis-click here is silent: the star
      //: changes shape and the note moves to the top of the list, and there
      //: was nothing that put it back. Reported as the undo stack being
      //: "significantly outdated and dont register a lot of actions".
      pushEntryPutUndo(
        entry.id,
        was ? "Removed a favourite" : "Added a favourite",
        { pinned: was },
        { pinned: !was }
      );
      await loadEntries();
    }
  );
  button.classList.toggle("is-favourite", Boolean(entry.pinned));
  button.setAttribute("aria-pressed", String(Boolean(entry.pinned)));
  return button;
}

// One entry card, shared by the browse list, chat results, and the bin.
// "2 hours ago" style, with the exact date kept for the hover tooltip
// (Wave J). Anything older than a week just shows the date.

function entryItem(entry, options = {}) {
  const li = document.createElement("li");
  li.dataset.id = entry.id;
  if (entry.id === linkSource) li.classList.add("link-source");
  // An opened-out row renders as the full card, see `expandedRows`. The
  // class does nothing in card view, where every note is already this shape.
  if (expandedRows.has(entry.id)) li.classList.add("row-expanded");

  if (editingId === entry.id && options.actions) {
    renderEditForm(li, entry);
    return li;
  }

  // The row's own open/close control. Rendered always but only *shown* in
  // rows view (CSS), rather than branched on `notesViewMode` here: the
  // view can change without a re-render, and a control that exists only in
  // the mode it was rendered in would go missing on the toggle.
  //
  // A direct child of `<li>` now, not of `.entry-meta`, direct instruction:
  // *"move the note collapse button on the compact rows view to the
  // permanent left, make sure the button keeps its position even when
  // expanded."* `.entry-meta` sits in the row's third grid column while
  // collapsed (title/content/meta side by side) and becomes a bottom-of-card
  // block once expanded (`li.row-expanded` drops the grid for `block`), so a
  // button living inside it visibly jumped from the row's right edge to the
  // card's bottom on every expand. Pinned absolutely to the card's own
  // top-left corner instead (`.row-expand` in 01-forms-settings.css), which
  // neither of those two layouts moves, it is positioned against `<li>`
  // itself, not against whichever of its children currently holds it.
  {
    const open = expandedRows.has(entry.id);
    const expand = document.createElement("button");
    expand.type = "button";
    expand.className = "ghost small icon-only row-expand";
    setLabel(expand, open ? "ph:caret-up" : "ph:caret-down");
    expand.title = open ? "Show less of this note" : "Show the whole note here";
    expand.setAttribute("aria-label", expand.title);
    expand.setAttribute("aria-expanded", String(open));
    expand.addEventListener("click", (event) => {
      event.stopPropagation();
      toggleRowExpanded(entry.id);
    });
    li.appendChild(expand);
  }

  // Click anywhere on a collapsed/expanded row's own body to toggle it,
  // same as the button, direct instruction: "if the user clicks on the
  // main body of the note and not an element on the collapsed row view, it
  // will expand or collapse without the user having to click the button."
  // Scoped to rows view only (`.entry-list.is-rows`, checked live rather
  // than cached: the view can change after this card was built) and
  // skipped whenever the click landed on something that already has its
  // own job: a link, a button, an image, selectable text, the checkbox.
  // `closest("a, button, input, .chip, img")` is the same "don't swallow a
  // click meant for something else" guard the rest of this file already
  // uses for row-level handlers.
  li.addEventListener("click", (event) => {
    if (event.target.closest("a, button, input, textarea, .chip, img, .unlink")) return;
    if (window.getSelection()?.toString()) return; // a text selection, not a click
    // **In select mode the whole card is the checkbox.** Direct instruction:
    // "when I have selected on the 'select' button in the notes tab, I want
    // to be able to click on the whole body of the note to select it, not
    // the select radiobutton in the corner." Asking someone to hit a 16px
    // box in the corner of a card they are already pointing at is the
    // slowest possible way to tick twenty notes, and every list that has a
    // batch mode (Finder, Gmail, Photos) lets the row itself carry it.
    //
    // Checked before the rows-view guard below, and in every view: the
    // expand-on-click behaviour is a *rows* affordance, but selecting is
    // what the card means while this mode is on, so it takes precedence
    // wherever it is shown.
    if (selectMode && options.actions) {
      const check = li.querySelector(".select-check");
      if (check) {
        check.checked = !check.checked;
        // `change` does not fire for a programmatic `.checked`, and the
        // checkbox's own listener is the single place that owns the set.
        check.dispatchEvent(new Event("change", { bubbles: true }));
        li.classList.toggle("is-selected", check.checked);
      }
      return;
    }
    if (!li.closest(".entry-list.is-rows")) return;
    toggleRowExpanded(entry.id);
  });

  // Batch select mode (Wave M): a checkbox leads each card.
  if (options.actions && selectMode) {
    const check = document.createElement("input");
    check.type = "checkbox";
    check.className = "select-check";
    check.checked = selectedIds.has(entry.id);
    check.setAttribute("aria-label", "Select this note");
    check.addEventListener("change", () => {
      if (check.checked) selectedIds.add(entry.id);
      else selectedIds.delete(entry.id);
      // The card carries the selected look, so it has to follow the box
      // whichever of the two was actually clicked.
      li.classList.toggle("is-selected", check.checked);
      updateBatchCount();
    });
    li.appendChild(check);
    li.classList.add("selectable");
    li.classList.toggle("is-selected", check.checked);
  }

  // A note's own leading `# Heading` becomes its title (asked for directly).
  // Not a separate field to edit, the body below is shown with that line
  // taken out, so the title isn't just the same text shown twice.
  if (entry.title) {
    // A <p>, not <h3>, `.card h3` is this app's small-caps *section label*
    // treatment (DESIGN.md's hierarchy), which is the wrong voice for a
    // note's own title: it read as a muted, uppercase eyebrow instead of
    // the prominent heading a title should be. `.entry-title` below defines
    // its own look rather than inheriting one built for a different job.
    const titleEl = document.createElement("p");
    titleEl.className = "entry-title";
    titleEl.textContent = entry.title;
    li.appendChild(titleEl);
  }

  const content = document.createElement("p");
  content.className = "entry-content";
  // One long note used to push everything else off the screen, so the list
  // stopped being a list. Anything past this is clamped with a "Show more".
  //
  // The trigger is the character count, not a measured height: this list
  // renders inside a `display: none` sub-tab, where every measurement comes
  // back 0: the trap that has caught four separate features here already.
  const isLong =
    entry.content.length > LONG_NOTE_CHARS ||
    entry.content.split("\n").length > LONG_NOTE_LINES;
  if (isLong && !expandedNotes.has(entry.id)) content.classList.add("entry-clamped");
  // Mark the matched words while filtering, so it's obvious WHY a note is in
  // the list. Built with createElement/textContent rather than innerHTML, 
  // note text is user content and must never be parsed as markup.
  renderNoteText(
    content,
    entry.title ? bodyWithoutTitleLine(entry.content) : entry.content,
    searchHighlightTerms()
  );
  content.addEventListener("remove-inline-image", async (e) => {
    e.stopPropagation();
    if (!(await confirmDialog("Remove this image from the note?"))) return;
    entry.content = entry.content.replace(e.detail.originalText, "").replace(/\n{3,}/g, "\n\n").trim();
    try {
      await apiJson(`/entries/${entry.id}`, { method: "PUT", body: JSON.stringify({ content: entry.content }) });
      await loadEntries();
      flashEntry(entry.id);
      toast("Image removed.");
    } catch(err) {
      toast(err.message || "Failed to remove image", true);
    }
  });
  li.appendChild(content);
  if (isLong) {
    const toggle = document.createElement("button");
    toggle.type = "button";
    toggle.className = "entry-more";
    const label = () =>
      expandedNotes.has(entry.id) ? "Show less" : "Show more";
    toggle.textContent = label();
    toggle.addEventListener("click", () => {
      if (expandedNotes.has(entry.id)) expandedNotes.delete(entry.id);
      else expandedNotes.add(entry.id);
      content.classList.toggle("entry-clamped", !expandedNotes.has(entry.id));
      toggle.textContent = label();
    });
    li.appendChild(toggle);
    // **Then check whether it was actually needed.** Reported: "a show
    // more/less button appears when it isnt needed sometimes", and
    // "notes shouldnt be truncated".
    //
    // `isLong` above is a character and line count, not a measurement, and
    // the comment there explains why: this list renders inside a
    // `display: none` sub-tab where every measured height comes back 0, 
    // the trap that has caught four features in this codebase. But a count
    // is a guess, and it is wrong in both directions: a note of 700 short
    // words wrapped narrow really is long, while 700 characters of one
    // paragraph in a wide card is three lines that fit with room to spare,
    // and gets a "Show more" that expands nothing.
    //
    // So: guess first so the markup is right when it cannot be measured,
    // then measure on the next frame and take the control back off when the
    // text was never clipped. `requestAnimationFrame` is after layout, and
    // `clientHeight` of 0 (still hidden) fails the comparison and changes
    // nothing: which is exactly the conservative behaviour that trap
    // wants.
    requestAnimationFrame(() => {
      if (!content.isConnected || expandedNotes.has(entry.id)) return;
      if (content.clientHeight > 0 && content.scrollHeight <= content.clientHeight + 2) {
        content.classList.remove("entry-clamped");
        toggle.remove();
      }
    });
  }

  const meta = document.createElement("div");
  meta.className = "entry-meta";
  // A note saved with filing deferred is in its holding category, not its
  // real one, and saying "Uncategorised" for the second or two before the
  // background pass lands reads as the AI having failed. Say what is
  // actually happening instead.
  if (entry.filing_state === "pending") {
    const filing = chip("ph:circle-notch Filing…", "filing");
    filing.title = "The AI is deciding where this note goes. It's already saved.";
    meta.appendChild(filing);
  } else {
    meta.appendChild(chip(entry.category));
  }
  for (const tag of entry.tags) meta.appendChild(chip(tag, "tag"));

  // "AI 0%: check this" is a warning about the AI's filing, and it only makes
  // sense when the AI actually did some. On a note you filed yourself, or one
  // saved while no AI was running, it accused a perfectly good note of being
  // suspect: which is most notes if you don't run Ollama.
  const aiDidFile = entry.ai_confidence > 0 && !entry.user_filed;
  // Plain-language explanation on hover, "confidence" is jargon otherwise,
  // and the number alone doesn't say what it's confident *about*.
  const confidenceHint = "How sure the AI was when it picked this note's category.";
  const confidenceChip = aiDidFile
    ? entry.ai_confidence >= REVIEW_THRESHOLD
      ? chip(`AI ${entry.ai_confidence}%`, "confidence")
      : // Low confidence from a real attempt, worth a human look (Phase 3).
        chip(`AI ${entry.ai_confidence}%: check this`, "review")
    : null;
  if (confidenceChip) confidenceChip.title = confidenceHint;
  // Flash the badge once when this note's confidence just changed, so the
  // update after a re-evaluation is actually noticeable (user request).
  if (confidenceChip && entry.id === flashConfidenceId) {
    confidenceChip.classList.add("badge-flash");
    flashConfidenceId = null;
  }
  if (confidenceChip) meta.appendChild(confidenceChip);

  // The documents this note feeds. Notes and documents are separate things
  // on purpose; this is the one place that says they are about the same one.
  for (const doc of entry.documents || []) {
    const mark = chip(`ph:file-text ${doc.title}`, "tag", () => openDocumentFromNote(doc.id));
    mark.title = `Open “${doc.title}”`;
    if (options.actions) {
      // Detach from the note's side too. The document editor has had this
      // since the link existed; from here it took going and finding the
      // document first, which is the wrong way round when the note is what
      // you are already looking at.
      const unlink = document.createElement("span");
      unlink.className = "unlink";
      setLabel(unlink, "ph:x"); // raw "×" glyph vs Phosphor icon font mismatch mis-centers the icon
      unlink.title = `Detach from “${doc.title}”: the note stays`;
      unlink.addEventListener("click", async (event) => {
        event.stopPropagation(); // the chip itself opens the document
        await api(`/documents/${doc.id}/notes/${entry.id}`, { method: "DELETE" });
        await loadEntries();
        toast(`Detached from “${doc.title}”.`);
      });
      makeUnlinkAccessible(unlink);
      mark.appendChild(unlink);
    }
    meta.appendChild(mark);
  }

  // Where a web-reader clipping came from (BACKLOG §65's "source as
  // metadata"). Opens the real page, the note's own body already has the
  // same link inline, this is the at-a-glance version.
  if (entry.source_url) {
    const sourceChip = chip(
      `ph:globe ${entry.source_title || entry.source_url}`,
      "tag",
      () => window.open(entry.source_url, "_blank", "noopener,noreferrer")
    );
    sourceChip.title = `Open the source: ${entry.source_url}`;
    meta.appendChild(sourceChip);
  }

  // What this note's own "tomorrow" meant on the day it was written (§10A).
  // A chip rather than a mark inside the text: `renderNoteText` already
  // layers wiki links, inline markdown and filter highlighting through each
  // other, and a fourth pass over the same string is where that breaks.
  for (const when of entry.dates || []) {
    const day = new Date(`${when.at}T00:00:00`);
    const label =
      when.precision === "day"
        ? day.toLocaleDateString(undefined, { day: "numeric", month: "short" })
        : `${when.precision} of ${day.toLocaleDateString(undefined, { day: "numeric", month: "short" })}`;
    const mark = chip(`ph:clock ${when.phrase} → ${label}`, "when");
    mark.title =
      `“${when.phrase}” meant ${day.toLocaleDateString(undefined, {
        weekday: "long", day: "numeric", month: "long", year: "numeric",
      })}, worked out from the day this note was written.`;
    meta.appendChild(mark);
  }

  //: **Which space this note is actually filed in (INBOX 1a/38).** "Notes
  //: from a deleted space appear in All spaces" turned out to be
  //: unanswerable without this: there was no way to tell a survivor's real
  //: space apart from a note that always lived in Default Space, so a
  //: report and a non-bug looked identical. Shown whenever the picker at
  //: the top of the tab does not already say it: every card while "All
  //: spaces" is selected, or a card whose own space differs from the one
  //: picked. `spacesCache` is the same list the switcher menu reads, so a
  //: name/icon here can never disagree with the one shown there.
  //: **`spacesCache.length` is not decoration: an empty cache means "not
  //: loaded yet", not "there are no spaces".** `loadSpaces()` fills it from
  //: `GET /spaces` after boot, and the note list renders before that lands, so
  //: without this guard every card drew the chip below with the name it falls
  //: back to and said, of an ordinary note in the Default Space, that it was
  //: "filed in a space that no longer exists". Caught in a README screenshot,
  //: where fifty-seven cards said it at once. Saying nothing until the answer
  //: is known is the honest state; `loadSpaces` re-renders the list once it
  //: has it (see its own comment), so the chip appears a moment later rather
  //: than never.
  if (entry.workspace_id && spacesCache.length) {
    const active = activeSpaceId();
    if (active === SPACE_ALL || entry.workspace_id !== active) {
      const space = spacesCache.find((s) => s.id === entry.workspace_id);
      // Stored as "ph-house" (a full class name, see the switcher's own
      // `iconEl.className`), not the "ph:house" `setLabel` shorthand
      // expects; stripping the prefix once here is cheaper than a second
      // icon convention.
      const iconName = (space?.icon || "ph-circles-four").replace(/^ph-/, "");
      const spaceName = space ? space.name : "a space that no longer exists";
      const spaceChip = chip(`ph:${iconName} ${spaceName}`, "tag", () =>
        setActiveSpace(entry.workspace_id)
      );
      spaceChip.title = `Filed in ${spaceName}. Click to switch there.`;
      meta.appendChild(spaceChip);
    }
  }

  // While the AI is re-evaluating this note, show a live spinner chip so
  // it's obvious something is running on this specific card.
  if (entry.id === busyEntryId) {
    li.classList.add("entry-busy");
    const busy = chip("Re-evaluating…", "busy");
    busy.classList.add("chip-busy");
    // The shared spinner (ROADMAP Priority 0 #14) replaces this chip's own
    // one-off ring: .chip's own `gap` handles the spacing and vertical
    // centring, so no extra margin is needed.
    busy.prepend(spinnerEl());
    meta.appendChild(busy);
  }

  // The date and the action buttons share one right-aligned group. They used
  // to carry a `margin-left: auto` each, and two auto margins in a flex row
  // split the free space between them, which put the timestamp at a
  // different x on every card, depending on how wide its chips were.
  const metaEnd = document.createElement("span");
  metaEnd.className = "entry-meta-end";

  const date = document.createElement("span");
  date.className = "entry-date";
  const stamp = entry.created_at;
  date.textContent = relativeTime(stamp);
  date.title = new Date(stamp).toLocaleString(); // exact on hover
  metaEnd.appendChild(date);
  meta.appendChild(metaEnd);

  if (options.actions) {
    // Wave L rework: two everyday actions stay visible; the rest live in
    // one ⋯ menu: the old row of nine icons was unscannable noise.
    const actions = document.createElement("span");
    actions.className = "entry-actions";
    actions.appendChild(
      //: **Star, not pin, and "Favourites", not "pinned".** The flag does two
      //: things: floats a note to the top of a list *and* collects it into
      //: the Favourites row in the sidebar, and it was named for only the
      //: first, so the app showed one concept under two names with two icons.
      //: Asked for: "make sure the favourites feature is actually integrated
      //: everywhere." The tooltip keeps the sort behaviour, since that is the
      //: half a star does not imply on its own.
      favouriteButton(entry)
    );
    actions.appendChild(
      smallButton("ph:clipboard", "Copy this note's text", async () => {
        if (await copyToClipboard(entry.content)) toast("Note copied.");
      })
    );
    actions.appendChild(
      smallButton("ph:pencil-simple", "Edit this entry", () => {
        editingId = entry.id;
        renderEntries();
      })
    );
    // Publishing already worked via the "draft" chip below (click it to
    // clear is_draft): reported again anyway ("needs to be...a button for
    // editing a draft and publishing"), so the chip alone wasn't read as an
    // action. An explicit, always-visible button next to Edit for drafts
    // only (a published note has nothing to publish) says the same thing
    // the chip's tooltip already did, just as a button instead of a tag.
    if (entry.is_draft) {
      actions.appendChild(
        smallButton("ph:check-circle", "Publish this draft as a proper note", async () => {
          try {
            await apiJson(`/entries/${entry.id}`, {
              method: "PUT",
              body: JSON.stringify({ is_draft: false }),
            });
            entry.is_draft = false;
            await loadEntries();
            toast("Published.");
          } catch (error) {
            toast(error.message || "Couldn't publish that draft.", true);
          }
        })
      );
    }
    actions.appendChild(entryOverflowMenu(entry));
    metaEnd.appendChild(actions);
  }
  if (entry.is_private) meta.insertBefore(chip("ph:lock private"), meta.firstChild);
  if (entry.pinned) meta.insertBefore(chip("ph:star favourite"), meta.firstChild);
  // Set either by the text-selection popup's "Save as draft note" (not yet
  // looked at) or by the Writing Room's "Save as note" (drafted with the AI,
  // however much it was edited before saving), asked for directly: both
  // should be findable as drafts, not just marked in passing. The note stays
  // in its normal place in the list either way; the sidebar/Library Drafts
  // filter (renderSidebar, and the Library's Drafts chip: the old
  // `library-view-drafts` sub-tab it used to name is gone) is what makes them
  // findable as a group.
  //
  // **The chip is also how a draft becomes a real note**, and saying so is the
  // fix: it was labelled "draft" with the tooltip "click to clear the label",
  // which describes the mechanism and not the outcome, reported as "there is
  // no way to edit and finalise drafts, or to publish one as a proper note",
  // when publishing was one click away the whole time and simply unlabelled.
  if (entry.is_draft) {
    const draftChip = chip("ph:pencil-simple-line draft", "draft", async (event) => {
      event.stopPropagation();
      try {
        await apiJson(`/entries/${entry.id}`, {
          method: "PUT",
          body: JSON.stringify({ is_draft: false }),
        });
        entry.is_draft = false;
        await loadEntries();
      } catch (error) {
        toast(error.message || "Couldn't update that note.", true);
      }
    });
    draftChip.title =
      "This is a draft, click to publish it as a proper note. It stays where it is either way; only the Drafts filter changes.";
    meta.insertBefore(draftChip, meta.firstChild);
  }
  //: **Where an imported note came from.** A vault file has a name, the
  //: thing its `[[wiki links]]` use: and this app has no title field to put
  //: it in, so without this the name is invisible: the note shows its opening
  //: words like every other note, and nothing on screen says it is one of a
  //: thousand files someone imported from a folder.
  //:
  //: A chip rather than a heading written into the note: the importer must
  //: not rewrite the file it imported (see `_run_directory_import`, an
  //: earlier attempt did, and three tests caught it).
  if (entry.source_path) {
    const fileChip = chip(`ph:file-md ${entry.source_path.split("/").pop()}`, "source-path");
    fileChip.title = `Imported from ${entry.source_path}`;
    meta.appendChild(fileChip);
  }
  li.appendChild(meta);

  // "Why this result" is its own line under the note, not another chip in
  // the meta lane. Measured: in the compact rows view that lane is a
  // `fit-content(26rem)` track with `overflow-x: auto`, and a chip naming
  // two signals pushed the date and the actions strip out of the visible
  // box (57 to 84px past its right edge, `scratchpad/ui-sweeps/searchwhy.js`),
  // which is the exact crowding `.entry-meta`'s own comment says that track
  // was rebuilt to stop. A row of its own also says what it is: a reason for
  // this note being in *this* list, which appears with a query and goes with
  // it, rather than a permanent fact about the note like its category.
  const why = whyThisResultChip(entry);
  if (why) {
    const line = document.createElement("div");
    line.className = "entry-why";
    line.appendChild(why);
    li.appendChild(line);
  }

  // Attachments (Wave B; images become thumbnails in Wave M).
  if (entry.attachments.length > 0) {
    const fileRow = document.createElement("div");
    fileRow.className = "entry-links";
    for (const attachment of entry.attachments) {
      const removeButton = () => {
        const remove = document.createElement("span");
        remove.className = "unlink";
        setLabel(remove, "ph:x"); // raw "×" glyph vs Phosphor icon font mismatch mis-centers the icon
        remove.title = "Remove this file";
        remove.addEventListener("click", async (e) => {
          e.stopPropagation();
          if (!(await confirmDialog(`Remove ${attachment.filename}?`))) return;
          await api(`/files/${attachment.id}`, { method: "DELETE" });
          await loadEntries();
        });
        makeUnlinkAccessible(remove);
        return remove;
      };

      if (attachment.is_image) {
        // Show the picture itself, not a chip, click for full size.
        const wrap = document.createElement("span");
        wrap.className = "thumb-wrap";
        const img = document.createElement("img");
        img.className = "attachment-thumb";
        img.alt = attachment.filename;
        img.title = `${attachment.filename}: click to view full size`;
        attachmentObjectUrl(attachment)
          .then((url) => (img.src = url))
          .catch(() => wrap.remove());
        img.addEventListener("click", () => {
          const images = entry.attachments.filter((a) => a.is_image);
          openLightbox(
            images.map((a) => ({ filename: a.filename, getUrl: () => attachmentObjectUrl(a) })),
            images.indexOf(attachment)
          );
        });
        wrap.appendChild(img);
        if (options.actions) wrap.appendChild(removeButton());
        fileRow.appendChild(wrap);
      } else {
        // Opens the lightbox's document viewer, not a download, this used
        // to go straight to `downloadAttachment`, the one file surface that
        // never got the fileCard treatment §... unified everywhere else.
        // Reported directly: "I tried to open and view a file i attached to
        // a note, instead it just downloaded it." `mediaSrc()` already knows
        // how to token-gate a `/files/{id}` url the same way it does
        // `/media/{name}`; `show()` below is what learned to read one.
        const fileChip = chip(`ph:file-text ${attachment.filename}`, "link", () =>
          openLightbox(
            [{ filename: attachment.filename, getUrl: () => mediaSrc(`/files/${attachment.id}`) }],
            0
          )
        );
        fileChip.title = `${attachment.filename}: ${Math.max(1, Math.round(attachment.size / 1024))} KB`;
        const downloadBtn = document.createElement("span");
        downloadBtn.className = "unlink";
        setLabel(downloadBtn, "ph:download-simple");
        downloadBtn.title = `Save “${attachment.filename}” to disk`;
        downloadBtn.addEventListener("click", (e) => {
          e.stopPropagation();
          downloadAttachment(attachment);
        });
        makeUnlinkAccessible(downloadBtn);
        fileChip.appendChild(downloadBtn);
        if (options.actions) fileChip.appendChild(removeButton());
        fileRow.appendChild(fileChip);
      }
    }
    // Before `meta` (the category/date/pin/actions footer), not after, 
    // reported directly: a sketch or attached image sat below the note's
    // own metadata row, sandwiched between the footer and whatever came
    // after it, rather than reading as part of the note's own content.
    li.insertBefore(fileRow, meta);
  }

  // Inline add-context / continue-thought forms (Wave B).
  if (options.actions && inlineAction && inlineAction.id === entry.id) {
    li.appendChild(renderInlineAction(entry));
  }

  if (entry.links.length > 0) {
    const linkRow = document.createElement("div");
    linkRow.className = "entry-links";
    for (const link of entry.links) {
      // **A link is navigation, not content.** Measured on the busiest screen
      // in the app: a card was 25px of its own note, 23px of metadata and 21px
      // of link chips: and the chips were the loudest thing on it, filled and
      // bold, each carrying the *whole first line of another note*. On a
      // well-linked note the links were wider than the note and read first,
      // which is §36B.3's "everything at equal weight" with the weights
      // actually inverted.
      //
      // Clipped to a glanceable length, quiet by default, with the full text
      // on hover for when the clip is not enough.
      const label = link.preview || "";
      const short = label.length > LINK_CHIP_CHARS
        ? `${label.slice(0, LINK_CHIP_CHARS - 1).trimEnd()}…`
        : label;
      // chip() sets plain textContent, right for a tag or category name but
      // not here: `link.preview` is a clip of the *other* note's own text,
      // which can carry the same **bold**/`code` a reader would expect to
      // see rendered, the way the note's own body already does.
      //
      // The click handler is built first and passed into chip()'s own
      // onClick param: every sibling chip() call site in this file does
      // the same and gets keyboard support (Enter/Space, role="button",
      // tabindex) for free. This one used to build a bare chip and attach a
      // plain `click` listener after the fact instead, which quietly opted
      // this specific "Go to note" chip out of keyboard operability while
      // every other chip stayed reachable (Web Interface Guidelines pass).
      const goToLinkedNote = (e) => {
        if (e.target.classList.contains("unlink")) return;
        flashEntry(link.entry_id);
      };
      const linkChip = chip("", "link", goToLinkedNote);
      // **Which way the link points.** Every link used to draw the same
      // bidirectional glyph, because the API merged both directions into one
      // list and never said which was which, so a note could show what it
      // was connected to and never whether it had reached out or been
      // reached for. Those are different facts, and telling them apart is
      // most of what a Connections list is for (asked for by way of
      // Kortex's own, which arrows every row).
      const outgoing = link.direction !== "in";
      linkChip.classList.add(outgoing ? "link-out" : "link-in");
      linkChip.appendChild(
        setLabel(
          document.createElement("span"),
          outgoing ? "ph:arrow-up-right" : "ph:arrow-down-left"
        )
      );
    linkChip.appendChild(document.createTextNode(" "));
      const linkPreview = document.createElement("span");
      renderInlineMarkdown(linkPreview, short, [], true);
      linkChip.appendChild(linkPreview);
      const reasonNote = link.reason
        ? link.reason_confidence != null
          ? `${link.reason} (${Math.round(link.reason_confidence * 100)}% confidence, deduced)`
          : link.reason
        : null;
      const wayRound = outgoing ? "This note links to" : "Links to this note";
      linkChip.title = reasonNote
        ? `${wayRound}: ${label}\nReason: ${reasonNote}`
        : `${wayRound}: ${label}`;
      if (options.actions) {
        const editReason = document.createElement("span");
        editReason.className = "unlink reason-edit";
        setLabel(editReason, "ph:pencil-simple");
        editReason.title = link.reason ? "Edit this link's reason" : "Add a reason for this link";
        editReason.addEventListener("click", async (e) => {
          e.stopPropagation();
          // promptDialog resolves "" for both Cancel and an empty Save, so it
          // can only ever *set* a reason here, clearing one that already
          // exists goes through the ⊘ below instead, where the intent is
          // unambiguous.
          const next = await promptDialog(
            "Why are these notes connected?",
            link.reason || ""
          );
          if (!next) return;
          await api(`/entries/${entry.id}/links/${link.link_id}/reason`, {
            method: "PUT",
            body: JSON.stringify({ reason: next }),
          });
          await loadEntries();
        });
        linkChip.appendChild(editReason);

        if (link.reason) {
          const clearReason = document.createElement("span");
          clearReason.className = "unlink reason-clear";
          // A Phosphor icon, not the "⊘" character: that glyph comes from
          // the system font and sits at a different vertical offset than
          // Phosphor's: .ph's `vertical-align: -0.12em` tuning (and the
          // flex centring around it) only lines up glyphs sharing one font.
          // Mixing "⊘"/"×" with a Phosphor pencil icon here is exactly what
          // made these three actions look vertically staggered.
          setLabel(clearReason, "ph:prohibit");
          clearReason.title = "Remove this link's reason";
          clearReason.addEventListener("click", async (e) => {
            e.stopPropagation();
            await api(`/entries/${entry.id}/links/${link.link_id}/reason`, {
              method: "PUT",
              body: JSON.stringify({ reason: null }),
            });
            await loadEntries();
          });
          linkChip.appendChild(clearReason);
        }

        const unlink = document.createElement("span");
        unlink.className = "unlink";
        // Phosphor's "x", not the "×" character: see the reason-clear icon
        // above for why: a mixed-font row of action icons never lines up,
        // no matter how the flex box around each one is centred.
        setLabel(unlink, "ph:x");
        unlink.title = "Remove this link";
        unlink.addEventListener("click", async () => {
          const otherId = link.entry_id;
          const reason = link.reason;
          let liveLinkId = link.link_id;
          await api(`/entries/${entry.id}/links/${liveLinkId}`, { method: "DELETE" });
          await loadEntries();
          pushUndo(
            "Removed a link between notes",
            async () => {
              const updated = await apiJson(`/entries/${entry.id}/links`, {
                method: "POST",
                body: JSON.stringify({ target_id: otherId, reason }),
              });
              liveLinkId = updated.links.find((l) => l.entry_id === otherId)?.link_id ?? liveLinkId;
              await loadEntries();
            },
            async () => {
              await api(`/entries/${entry.id}/links/${liveLinkId}`, { method: "DELETE" });
              await loadEntries();
            }
          );
        });
        makeUnlinkAccessible(unlink);
        linkChip.appendChild(unlink);
      }
      linkRow.appendChild(linkChip);
    }
    li.appendChild(linkRow);
  }
  return li;
}

function inlineActionIs(id, kind) {
  return inlineAction && inlineAction.id === id && inlineAction.kind === kind;
}

// Close every open ⋯ menu (shared by outside-click and Esc, Wave L).
// A kebab menu that stays where it opened while the list scrolls under it
// ends up beside the wrong note (reported: "they stay sticky on the screen
// even when I scroll putting the note I clicked it for off the page"). Any
// scroll outside the open menu closes it; a scroll inside a long menu is
// the menu's own and is left alone.
function closeActionMenusOnScroll(event) {
  const open = document.querySelector(".action-menu:not(.hidden)");
  if (!open) return;
  if (event.target instanceof Node && open.contains(event.target)) return;
  closeActionMenus();
}
window.addEventListener("scroll", closeActionMenusOnScroll, true);

function closeActionMenus() {
  for (const menu of document.querySelectorAll(".action-menu:not(.hidden)")) {
    menu.classList.add("hidden");
    restoreEscapedMenu(menu);
    // `menu._escapedOpener` (set by wireEscapedActionMenu) wins when
    // present: a menu reparented to <body> has no useful `.parentElement`
    // to search: `document.body.querySelector` would find the *first*
    // `[aria-haspopup]` anywhere on the page, not this menu's own opener,
    // and set the wrong button's aria-expanded. Undefined for every other
    // menu, so this changes nothing for them.
    const opener = menu._escapedOpener || menu.parentElement.querySelector("[aria-haspopup]");
    if (opener) opener.setAttribute("aria-expanded", "false");
  }
  for (const strip of document.querySelectorAll(".menu-open")) {
    strip.classList.remove("menu-open");
  }
}

// Opening one, shared by the note cards and the sidebar kebabs so the two
// cannot drift apart.
//
// **`menu-open` is the fix for a reported bug, and it is not cosmetic.** On a
// note card, `.entry-actions` is `position: absolute; z-index: 1`, which
// makes it a *stacking context*, so the menu's own `z-index: 30` is resolved
// inside it and counts for nothing outside it. Every other note's action strip
// is also `z-index: 1`, and later in the document, so it paints on top of an
// open menu. Reported as "the other buttons in notes go over the popup options
// from above notes", and measured: with the first note's menu open, the topmost
// element at three separate points *inside* the menu was a button belonging to
// a different note. So it was not only a menu with buttons drawn over it, it
// was a menu whose items clicked the wrong note's controls.
//
// Raising the owning strip lifts the whole context, menu included. 5 rather
// than something larger because the only thing it has to beat is the 1 on its
// siblings; the page's own chrome is a different context and a big number here
// would only be a number waiting to collide with one.
// The nearest ancestor that actually clips overflow, walking up past plain
// flow containers. `.action-menu` is `position: absolute` inside a `.menu-wrap`
// that is itself absolutely positioned on the row, it never escapes an
// `overflow: auto` ancestor the way a portal would, so a row near the bottom
// of a scrolling list grows that ancestor's scrollHeight by however far the
// menu spills past it, and the menu itself is clipped at the same edge.
// Reported on the Documents subtab: the last row's ⋯ menu appeared cut off
// *and* a scrollbar showed up in a panel that fit without one a moment
// before opening it.
function nearestScrollParent(el) {
  let node = el.parentElement;
  while (node && node !== document.body) {
    if (/(auto|scroll)/.test(getComputedStyle(node).overflowY)) return node;
    node = node.parentElement;
  }
  return document.documentElement;
}

// **One help popover, for every "?" in the app.** Reported directly, with a
// screenshot of Settings' own Search-relevance hint: "the search relevance
// '?' popup tooltip is completely different from all other tooltips like it,
// same with the 'keep the ai on this machine' tooltip… all the ui and ux
// needs to be consistent in how it looks, how it functions, and where it is
// placed."
//
// It genuinely was three different things wearing the same "?" icon:
//   1. `.graph-help-panel`, a floating glass card (Graph, Timeline, three
//      Library sub-tabs).
//   2. the same class inside `.settings-section`, where a CSS override made
//      it `position: static`, so it was not a popover at all, it was a
//      bordered paragraph that shoved the rest of the form down the page.
//      That is the "just text in a box" in the screenshot.
//   3. `.setting-hint`, Settings' own long hints, which expanded inline
//      with no surface, border or shadow whatsoever.
//
// This makes all three the same control: a real popover, lifted to <body> so
// no card's `overflow` or `backdrop-filter` can clip it (the same escape
// `wireEscapedActionMenu` above makes, for the same reason), anchored under
// its own trigger with a caret pointing back at it, and closed the three
// ways every other popover here closes.
function placeHelpPopover(panel, trigger, retry = true) {
  const margin = 8;
  const anchor = trigger.getBoundingClientRect();
  //: **The other half of the flicker, which this function did not have.**
  //: Reported again after the dropdowns were fixed: "the flickering popup
  //: panels and dropdown panels are still happening", "still happen on some
  //: tooltips". `wireEscapedActionMenu`'s `place` already refuses an
  //: all-zero anchor rect (what a trigger inside a `display: none` or
  //: not-yet-laid-out ancestor reports, which collapses every sum below to
  //: the margin and puts the panel in the top corner); this one measured
  //: the same way and trusted it. Same guard, same shape: one retry on the
  //: next frame, held invisible rather than painted in the corner while it
  //: waits, and out of retries it places as best it can rather than
  //: flashing. A "?" whose trigger is genuinely at the origin also has zero
  //: width and height, so the three-way test cannot mistake a real corner
  //: trigger for an unmeasured one.
  if (!anchor.width && !anchor.height && !anchor.top) {
    if (retry) {
      panel.style.visibility = "hidden";
      requestAnimationFrame(() => placeHelpPopover(panel, trigger, false));
      return;
    }
  }
  // Measured while invisible: the panel is shown at 0,0 for the measure
  // and only then moved, which painted one frame in the top-left corner
  // (reported: "they flicker somewhere else on the screen for a split
  // second"). visibility keeps layout and geometry, so the measure is the
  // same, and nothing paints until the position is set.
  panel.style.visibility = "hidden";
  panel.style.left = "0px";
  panel.style.top = "0px";
  const box = panel.getBoundingClientRect();
  // Centred on the trigger, then pulled inside the window, a "?" sitting in
  // a right-hand control cluster would otherwise open half off-screen.
  //: **Clamped to the surface the trigger lives on, not to the window.**
  //: Reported with a screenshot of the search-relevance help hanging off the
  //: right edge of the Settings dialog and over the page behind it: a modal is
  //: narrower than the viewport, so "inside the window" let the popover leave
  //: the thing it belongs to while still being technically on screen. The
  //: window is the fallback for a "?" that is not inside a dialog at all.
  const surface = trigger.closest(".modal-card, .card") || null;
  const bounds = surface ? surface.getBoundingClientRect() : null;
  const minLeft = bounds ? Math.max(margin, bounds.left + margin) : margin;
  const maxLeft = bounds
    ? Math.min(window.innerWidth - margin - box.width, bounds.right - margin - box.width)
    : window.innerWidth - margin - box.width;
  let left = anchor.left + anchor.width / 2 - box.width / 2;
  left = Math.min(Math.max(left, minLeft), Math.max(minLeft, maxLeft));
  let top = anchor.bottom + 10;
  let above = false;
  if (top + box.height > window.innerHeight - margin) {
    const room = anchor.top - 10 - box.height;
    if (room >= margin) {
      top = room;
      above = true;
    } else {
      top = Math.max(margin, window.innerHeight - margin - box.height);
    }
  }
  panel.style.left = `${Math.round(left)}px`;
  panel.style.top = `${Math.round(top)}px`;
  panel.style.visibility = "";
  panel.classList.toggle("help-popover-above", above);
  // The caret is positioned against the panel, but it has to point at the
  // trigger: which is only the panel's own centre when nothing clamped it.
  const caretX = Math.min(Math.max(anchor.left + anchor.width / 2 - left, 14), Math.max(box.width - 14, 14));
  panel.style.setProperty("--help-caret-x", `${Math.round(caretX)}px`);
}

//: Every open popover this session, so a second one closes the first and
//: nothing is left stranded at <body> after a tab switch.
const openHelpPopovers = new Set();

function closeHelpPopovers() {
  for (const entry of [...openHelpPopovers]) entry.close();
}

function wireHelpPopover(trigger, panel) {
  if (!trigger || !panel || panel.dataset.helpPopover) return;
  panel.dataset.helpPopover = "1";
  let homeParent = null;
  let homeNext = null;
  const entry = {
    close() {
      if (!openHelpPopovers.has(entry)) return;
      openHelpPopovers.delete(entry);
      panel.classList.add("hidden");
      panel.classList.remove("help-popover", "help-popover-above");
      panel.style.left = "";
      panel.style.top = "";
      if (homeParent) homeParent.insertBefore(panel, homeNext);
      trigger.setAttribute("aria-expanded", "false");
    },
  };
  const open = () => {
    closeHelpPopovers();
    homeParent = panel.parentElement;
    homeNext = panel.nextSibling;
    document.body.appendChild(panel);
    panel.classList.remove("hidden");
    // `.setting-hint`'s own collapsed state is a max-height animation, not a
    // `hidden` class: an inline hint has to be un-collapsed as well, or the
    // popover opens at zero height.
    panel.classList.remove("is-collapsed");
    panel.classList.add("help-popover");
    trigger.setAttribute("aria-expanded", "true");
    openHelpPopovers.add(entry);
    placeHelpPopover(panel, trigger);
  };
  trigger.addEventListener("click", (event) => {
    // These triggers live inside <label>s often enough that a bare click
    // would toggle the setting they explain.
    event.preventDefault();
    event.stopPropagation();
    if (openHelpPopovers.has(entry)) entry.close();
    else open();
  });
  panel.addEventListener("click", (event) => event.stopPropagation());
  document.addEventListener("click", (event) => {
    if (!openHelpPopovers.has(entry)) return;
    if (panel.contains(event.target) || trigger.contains(event.target)) return;
    entry.close();
  });
  document.addEventListener("keydown", (event) => {
    if (event.key === "Escape") entry.close();
  });
  window.addEventListener("resize", () => {
    if (openHelpPopovers.has(entry)) placeHelpPopover(panel, trigger);
  }, { passive: true });
  // A popover is anchored to a rect that scrolls away underneath it; every
  // other floating thing in this app closes rather than chasing it.
  window.addEventListener("scroll", () => entry.close(), true);
}
window.wireHelpPopover = wireHelpPopover;

function openActionMenu(menu, opener) {
  closeActionMenus(); // only one open at a time
  //: **Measured while invisible, revealed once.** Reported alongside the
  //: collapsed menu above: "the popup sitll has the left corner screen flicker
  //: before it shows in the right place". Everything below this line needs the
  //: menu laid out to do its job (the flip test reads its rect, and
  //: `escapeMenuIfClipped` reparents it to `<body>` and writes a `top` only
  //: after measuring), and `hidden` is `display: none`, so the menu has to be
  //: shown before any of it can run. That leaves at least one painted frame
  //: where a menu about to be moved is visible where it started, which for an
  //: escaped menu is wherever `<body>` puts an unpositioned child.
  //:
  //: `visibility: hidden` is the difference: the box is laid out and
  //: measurable, and it paints nothing until the last line puts it back. The
  //: same two-step `showSelectionPopupAt` uses, and for the same reason.
  const wasVisibility = menu.style.visibility;
  menu.style.visibility = "hidden";
  menu.classList.remove("hidden", "action-menu-flip");
  opener.setAttribute("aria-expanded", "true");
  // Whichever ancestor is the stacking context this menu is trapped in. On a
  // note card that is `.entry-actions` (positioned, z-index 1); on a Library
  // card it is the card itself, because `backdrop-filter` creates a stacking
  // context too: which is why the same "menu behind the next card" bug turned
  // up again on a surface with no z-index in sight.
  menu.closest(".entry-actions, .library-card")?.classList.add("menu-open");
  // Opens downward by default; flip upward only when that would spill past
  // the nearest clipping ancestor, so a menu near the top of a short list
  // still opens the normal way.
  const bound = nearestScrollParent(opener).getBoundingClientRect();
  if (menu.getBoundingClientRect().bottom > bound.bottom) {
    menu.classList.add("action-menu-flip");
  }
  //: **And if flipping is not enough, leave the box entirely.** Asked for
  //: app-wide: "make sure the popup menus dont get clipped or go off the
  //: screen." Measured on the live app: **21** absolutely-positioned menus sit
  //: inside an ancestor with `overflow` set: every enhanced `<select>` inside
  //: a scrolling panel, the document dock's own list, the whiteboard's menus.
  //: Flipping upward only helps when the spill is downward and the clipper is
  //: tall enough; sideways, or in a short panel, the menu is simply cut.
  //:
  //: `wireEscapedActionMenu` has solved this since the Library's kebab was
  //: reported: but only for the callers that remembered to ask for it, one at
  //: a time. This makes it the default *when it is needed*: nothing changes for
  //: a menu that fits, and a menu that does not gets the same reparent-to-body
  //: treatment rather than being clipped.
  escapeMenuIfClipped(menu, opener);
  //: Placed, so it can be seen. Restored rather than cleared, in case a caller
  //: had its own reason to hide this menu.
  menu.style.visibility = wasVisibility;
  focusMenuItem(menu.querySelector("button"), menu);
}

//: **Focusing the first row of a menu must never scroll the page behind it.**
//:
//: Measured, not reasoned. The reader picker at the top of the OCR workspace
//: (`#ocr-reader`) would not open at all: one real Chromium click produced,
//: in order, `openActionMenu` (the menu unhides and escapes to <body>), a
//: `focusin` on the chosen row, a `scroll` event on `.ocr-toolbar`, and then
//: `closeActionMenusOnScroll` shutting the menu it had just opened, 3 option
//: rows built and 0 visible. `.ocr-toolbar` is `overflow-x: auto` (it scrolls
//: sideways rather than wrapping, by design), the menu is still a child of
//: that toolbar at the moment the focus lands, and a plain `.focus()` asks
//: the browser to scroll every ancestor until the focused element is in view.
//: So the open *caused* the scroll, and the scroll-away rule, which exists
//: for a real one (a kebab left beside the wrong note while its list scrolls
//: under it), could not tell the two apart.
//:
//: The fix is at the cause rather than at that rule: this app positions its
//: own menus, from the opener's rect, escaping to <body> when they would be
//: clipped, so an ancestor scrolling to "reveal" a menu item is never what is
//: wanted and is the browser undoing the placement. `preventScroll` says
//: exactly that, with no timer for anyone to tune.
//:
//: What it must not lose is the scrolling that *is* wanted: a long menu (the
//: model picker, a 30-option select) whose chosen row is below its own fold
//: has to bring that row into view. So the menu scrolls itself, by the two
//: lines below, and nothing above it moves.
function focusMenuItem(item, menu) {
  if (!item) return;
  item.focus({ preventScroll: true });
  const box = menu || item.closest(".action-menu");
  if (!box || box.scrollHeight <= box.clientHeight) return;
  const top = item.offsetTop;
  const bottom = top + item.offsetHeight;
  if (top < box.scrollTop) box.scrollTop = top;
  else if (bottom > box.scrollTop + box.clientHeight) box.scrollTop = bottom - box.clientHeight;
}

//: The nearest ancestor that would clip this menu, `overflow` anything but
//: `visible` makes a box a clipping context, and `clip` and `hidden` clip
//: without even offering a scrollbar to reach what they cut off.
function menuClippingAncestor(el) {
  let node = el?.parentElement;
  while (node && node !== document.body) {
    const cs = getComputedStyle(node);
    const clips = (value) => value === "auto" || value === "scroll" || value === "hidden" || value === "clip";
    if (clips(cs.overflowX) || clips(cs.overflowY)) return node;
    node = node.parentElement;
  }
  return null;
}

//: The placement `wireEscapedActionMenu` has always used, factored out so the
//: automatic path and the hand-wired one cannot drift into placing the same
//: menu differently. Right-aligned to the opener, flipped above when the whole
//: box fits there, and clamped to the viewport on both axes, which is the
//: "or go off the screen" half of the same report.
//:
//: **This is deliberately not `place()`'s vertical rule** (see
//: `wireEscapedActionMenu` below), and the difference was measured rather
//: than assumed, on the note cards' own kebab menus, which are the automatic
//: path's largest population. `place()` decides between the room above the
//: trigger and the room below it and scrolls inside whichever is larger; this
//: one is allowed to span *across* the trigger and use the whole window. For
//: a menu taller than either side, that is the difference between showing all
//: of it and showing part of it: at 1280x640 a 375px menu opened from a card
//: at y=313 sits 257 to 632 here and needs no scrollbar at all, while
//: `place()`'s rule caps it to the 301px above the card and makes it scroll;
//: at 1280x360 the same menu shows 294px of itself against `place()`'s 207px,
//: with 143px of empty window left under it. A kebab covering its own three
//: dots for as long as it is open costs nothing. A `<select>` dropdown
//: covering the field you are choosing a value in is a different matter,
//: which is why `place()`, whose callers are that shell and the wrap kebabs,
//: keeps the trigger clear and takes the scrollbar instead.
//:
//: What is shared is everything else: the horizontal clamp, the 8px margin,
//: the 4px gap, and the rule that the whole box lands inside the window.
//: Neither can run past the bottom, because `07-whiteboard-misc.css` caps
//: every `.action-menu` at `calc(100vh - var(--space-9) * 2)` with
//: `overflow-y: auto`, measured as 576px in a 640px window and 296px in a
//: 360px one, so a menu is never taller than the window it is placed in.
function placeEscapedMenu(menu, opener) {
  const margin = 8;
  const anchor = opener.getBoundingClientRect();
  // Same reason as placeHelpPopover: no frame at 0,0 before the move.
  menu.style.visibility = "hidden";
  menu.style.left = "0px";
  menu.style.top = "0px";
  const box = menu.getBoundingClientRect();
  let left = anchor.right - box.width;
  let top = anchor.bottom + 4;
  if (left < margin) left = margin;
  if (left + box.width > window.innerWidth - margin) {
    left = Math.max(margin, window.innerWidth - margin - box.width);
  }
  if (top + box.height > window.innerHeight - margin) {
    const above = anchor.top - 4 - box.height;
    //: **Both edges, not just the top.** This branch used to accept `above`
    //: on `above >= margin` alone, which is only half the question: with a
    //: trigger below the fold (a card the list has scrolled past, a menu
    //: opened from script), "above the trigger" is itself off the bottom of
    //: the window. Measured at 1280x360 on the third note card, whose kebab
    //: sits at y=405: the menu landed at top 105, bottom 401, with 41px of it
    //: past the window and nothing able to bring that back. The fallback
    //: below, which pins the box to the last position that fits, was always
    //: the right answer for that case.
    const fits = above >= margin && above + box.height <= window.innerHeight - margin;
    top = fits ? above : Math.max(margin, window.innerHeight - margin - box.height);
  }
  menu.style.left = `${Math.round(left)}px`;
  menu.style.top = `${Math.round(top)}px`;
  menu.style.visibility = "";
}

function escapeMenuIfClipped(menu, opener) {
  //: A menu that already has its own escape wiring is left alone: two
  //: mechanisms reparenting the same node would fight over where home is.
  if (menu._escapeWired || menu._escapedHome) return;
  const clipper = menuClippingAncestor(menu);
  if (!clipper) return;
  const box = menu.getBoundingClientRect();
  const bound = clipper.getBoundingClientRect();
  //: A pixel of tolerance, because a menu whose edge lands exactly on its
  //: container's is not clipped and reparenting it would be a visible jump for
  //: no reason.
  const spills =
    box.right > bound.right + 1 ||
    box.left < bound.left - 1 ||
    box.bottom > bound.bottom + 1 ||
    box.top < bound.top - 1;
  if (!spills) return;
  menu._escapedHome = { parent: menu.parentElement, next: menu.nextSibling };
  //: Read by `closeActionMenus`, which otherwise looks for the opener among
  //: the menu's siblings: and once the menu is a child of <body> that search
  //: finds the first `[aria-haspopup]` on the page, which is the wrong button.
  menu._escapedOpener = opener;
  document.body.appendChild(menu);
  menu.classList.add("action-menu-escaped");
  //: `action-menu-flip` pins `bottom`; `placeEscapedMenu` sets `top`. Both at
  //: once over-constrains an auto-height box, which reproduced as the menu
  //: collapsing to its own padding, see `wireEscapedActionMenu`'s note.
  menu.classList.remove("action-menu-flip");
  placeEscapedMenu(menu, opener);
}

function restoreEscapedMenu(menu) {
  const home = menu._escapedHome;
  if (!home) return;
  //: Put back rather than left in <body>: a page that never restores an
  //: escaped menu accumulates stray fixed nodes forever, and the next
  //: `openActionMenu` expects to find it where it was built.
  home.parent.insertBefore(menu, home.next);
  menu.classList.remove("action-menu-escaped");
  menu.style.left = "";
  menu.style.top = "";
  menu._escapedHome = null;
}

//: **Escape a clipping ancestor, then cap to the room really left below.**
//: The second of this file's two menu recipes, and the one for a menu whose
//: ordinary position comes from the stylesheet rather than from us:
//: `details.dock-menu`'s panel (INBOX 31) and the whiteboard's five top-bar
//: menus (INBOX 43). It was written twice, once in each place, with the same
//: margin, the same floor and the same order; the second copy's own comment
//: said it was "the same recipe ... not a third scheme", which is exactly the
//: state in which a reader improves one of them and leaves the other behind.
//: Measured identical before and after on the whiteboard's own menus at
//: 1440x900, 1280x640 and 1024x560 (View: escaped at the two smaller sizes,
//: capped to 576px and 496px, 20px and 100px of scroll inside it).
//:
//: **Not** folded into `wireEscapedActionMenu`'s `place()`, this file's other
//: recipe, and the difference is not a detail: `place()` *positions* the menu
//: itself, fixed and right-aligned under its opener, every time it opens,
//: because the `.action-menu` it is wired to has no position of its own once
//: it is a child of <body>. These menus do have one. A dock menu that nothing
//: clips is still anchored by CSS under its own summary, and a whiteboard menu
//: under its own toolbar button, so running them through `place()` would move
//: menus that were never in the wrong place to satisfy a shared function. Here
//: the escape stays conditional (a no-op when nothing clips) and only the
//: height is decided.
function escapeAndCapMenu(menu, opener) {
  //: **Measured with every cap off, not just this function's own.**
  //: The inline cap is cleared before the measurement rather than after the
  //: close: the `top` read below has to be this open's real one, and a cap
  //: left over from the last open changes it (a menu that would have flipped
  //: above no longer needs to) as well as hiding the fact that the menu wants
  //: more room.
  //:
  //: `none` rather than empty, because clearing the inline value only hands
  //: the menu back to the *stylesheet's* cap, and that is the same lie one
  //: level down. Measured on the map's View menu at 1440x760 (INBOX 114, "the
  //: view dropdown menu in the whiteboard and mindmap is still broken", with
  //: "Snap to grid" cut in half and a scrollbar): 714px of content, held to
  //: 616 by `.wb-board-menu`'s own `calc(100vh - 9rem)`, so `placeEscapedMenu`
  //: measured 616, found that it fitted under the opener, and left the menu at
  //: top 56. It was then capped to the 696px of room under *that* line and
  //: scrolled 18px of content it had the window height to show: placed at the
  //: top of the window instead, all 714 fit. A menu is moved up by how tall it
  //: really is, or it is moved for the wrong reason.
  menu.style.maxHeight = "none";
  escapeMenuIfClipped(menu, opener);
  const margin = 8;
  //: After the escape, so the number is measured against wherever the menu
  //: has ended up: `placeEscapedMenu` may have flipped it above the opener or
  //: clamped it to the top of the window, and a cap computed from the old top
  //: would be the wrong one for the new position.
  const box = menu.getBoundingClientRect();
  //: **Anchor on the opener, not on the menu, and never on a rect that was
  //: not laid out.** Measured while the whiteboard tab was hidden: every
  //: `.wb-board-menu` reported `top: 0` and this wrote a 892px cap from it,
  //: on a viewport of 900. A rect read from an element inside a
  //: `display: none` ancestor is all zeroes, and the arithmetic below
  //: cannot tell that from a menu genuinely sitting at the top of the
  //: window: it just produces a number, which is how a cap ends up either
  //: meaningless or, when the stale `top` is large, small enough to read as
  //: the reported "overly short" menu.
  //:
  //: The opener is by definition laid out (it was just clicked), so its own
  //: bottom edge is the honest answer to "where does this menu start".
  //: The menu's own top is the fallback for a caller that has no opener,
  //: and if neither is laid out the stylesheet's cap is left alone rather
  //: than replaced with a number derived from zeroes.
  //: **But where it was actually put beats where it would have gone.**
  //: `placeEscapedMenu` measures the menu *uncapped* and, when that height
  //: does not fit below the opener, pins the box higher up the window. The cap
  //: was still being computed from the opener's bottom, so a menu that had
  //: been moved up got the height of the room under the *opener* while sitting
  //: in the larger room under its own top, and scrolled with empty window
  //: below it. Measured on a board at 1440x700 (INBOX 107c, "the arrange
  //: dropdown is also very short"): the View menu was placed at top 96 with
  //: 604px of room under it and capped to 507, scrolling 594px of content
  //: through a 505px port with 89px of window to spare; at 600 it wasted 137.
  //:
  //: `placeEscapedMenu` only ever writes `top` (never `bottom`, the
  //: over-constraint note there says why), so the menu grows downward from
  //: exactly this edge in every one of its branches, and the room under that
  //: edge is the honest answer. The opener stays as the fallback for a menu
  //: the stylesheet placed and for one whose own rect is not laid out.
  const anchor = opener ? opener.getBoundingClientRect() : null;
  const laidOut = (rect) => rect && (rect.width || rect.height || rect.top);
  const top = laidOut(box) ? box.top : laidOut(anchor) ? anchor.bottom + margin : null;
  //: Nothing measurable to cap against: the stylesheet's own cap is the right
  //: thing to fall back to, and `none` above must not be what is left behind.
  if (top === null) {
    menu.style.maxHeight = "";
    return;
  }
  //: The floor keeps a menu opened near the bottom edge a menu rather than a
  //: slit; under it, scrolling inside the panel is the affordance.
  menu.style.maxHeight = `${Math.max(120, Math.round(window.innerHeight - top - margin))}px`;
}

// **Escapes a `kebabMenu()` dropdown from a clipping scroll ancestor.**
// Reported live, with a screenshot: "the documents popup menu in the
// library subtab gets cut off." `.library-view-section` is
// `overflow-y: auto`, and `.action-menu` is `position: absolute`, the
// same shape as the gallery kebab menu's own clipping bug earlier this
// session (`section.card.glass`'s `backdrop-filter`, there), fixed the
// same way: reparent to `<body>` and position from the opener's own rect,
// which is the only thing that actually escapes an ancestor's `overflow`.
//
// Deliberately **not** folded into `openActionMenu`/`closeActionMenus`
// themselves: `.action-menu` is shared by every note card, the chat
// dock, the selection popup and nested submenus, none of which are
// clipped, and none of which this session re-verified live. Rewriting
// what they all depend on to fix one clipped caller is a bigger, riskier
// change than watching that one caller's own open/close state and acting
// on it: which is what this does, via a MutationObserver on the menu's
// own `hidden` class, so `openActionMenu`'s existing flip logic keeps
// running unmodified underneath it.
//
// Call once, right after building a `kebabMenu()` wrap, for any menu
// known to live inside a scrolling ancestor.
function wireEscapedActionMenu(wrap) {
  const menu = wrap.querySelector(".action-menu");
  const opener = wrap.querySelector("[aria-haspopup]");
  if (!menu || !opener) return;
  // Read by closeActionMenus() in place of a DOM-parent lookup, which
  // would otherwise search the whole <body> for the first [aria-haspopup]
  // it finds, the wrong button, once this menu is no longer a
  // descendant of its own opener's wrapper.
  menu._escapedOpener = opener;
  //: Claimed, so `escapeMenuIfClipped` (the automatic path) does not also try
  //: to reparent this one, two mechanisms with two ideas of "home" would put
  //: it back in the wrong place.
  menu._escapeWired = true;
  let homeParent = null;
  let homeNext = null;
  const place = (retry = true) => {
    const margin = 8;
    const anchor = opener.getBoundingClientRect();
    //: **Never place against a rect that was not laid out.** Reported:
    //: dropdowns and tooltips "flicker into the top corner for a second
    //: then appear in the right place". Reproduced by measuring an open
    //: menu frame by frame: with the opener unmeasurable (all-zero rect,
    //: which is what an element inside a `display: none` or
    //: not-yet-laid-out ancestor reports) the arithmetic below resolves to
    //: the margin in both axes and the menu lands at 8,4: the top corner,
    //: exactly as described. A later pass then places it properly, which
    //: is the "and then it appears in the right place" half.
    //:
    //: So: one retry on the next frame, the same shape `clampToolbarMenu`
    //: already uses, and the menu is held invisible rather than painted in
    //: the corner while it waits. `visibility`, not `.hidden`: the class is
    //: the open/closed state that this observer is driven by, and writing
    //: it here would re-enter.
    if (!anchor.width && !anchor.height && !anchor.top) {
      if (retry) {
        menu.style.visibility = "hidden";
        requestAnimationFrame(() => place(false));
        return;
      }
      //: Out of retries: show it where the stylesheet puts it rather than
      //: never, and rather than in a corner of our own choosing.
      menu.style.visibility = "";
      return;
    }
    // Reset first: a stale left/top from the last open would otherwise
    // seed the width/height measurement below at the wrong size on some
    // browsers' layout of a `position: fixed` element mid-transition.
    menu.style.left = "0px";
    menu.style.top = "0px";
    //: **Measure the menu at its full height, not at whatever a stylesheet
    //: last capped it to.** Written in response to the whiteboard's View
    //: menu (INBOX 57, then 105), but the correction belongs here in the
    //: retest, not in the fix: this `place()` is `wireEscapedActionMenu`'s
    //: own, wired only to `enhanceSelect`'s dropdown shell and `kebabMenu`'s
    //: wrap (this file's own two call sites) -- the whiteboard's
    //: `.wb-board-menu` (Insert, Edit, Arrange, View, Board) never calls it.
    //: It goes through the file's other recipe, `escapeAndCapMenu` above,
    //: which leaves a menu the stylesheet has already anchored where it is
    //: and caps `max-height` to the room below its own final `top`. Read that
    //: function's comment before moving anything between the two: they differ
    //: because one owns the menu's position and the other does not.
    //: Retested directly on the real View menu, board and mind map, at
    //: 1440 and 820 wide, 900/700/640 tall: it already holds up (see INBOX
    //: 105's own retest note for the numbers), which is why this fix stayed
    //: scoped to the surfaces that actually call it rather than being
    //: ported into a second implementation that was not shown to need it.
    //: Whichever rule caps it, an inline `max-height: none` for the
    //: duration of the measurement is what makes `box.height` the height this
    //: menu actually wants, so the choice below is made on the real number.
    //:
    //: **And the cap below is not `placeEscapedMenu`'s job, deliberately.**
    //: Sharing it was tried and measured: giving the automatic path this rule
    //: made a 375px note-card menu that fitted whole at 1280x640 into a 301px
    //: scrolling one, and cost 87px of visible menu at 1280x360, because that
    //: path is allowed to span across its trigger and use the window while
    //: this one keeps the trigger clear. The numbers are at
    //: `placeEscapedMenu`, which is the site a reader is more likely to reach
    //: first.
    menu.style.maxHeight = "none";
    const box = menu.getBoundingClientRect();
    let left = anchor.right - box.width;
    let top = anchor.bottom + 4;
    if (left < margin) left = margin;
    if (left + box.width > window.innerWidth - margin) {
      left = Math.max(margin, window.innerWidth - margin - box.width);
    }
    //: The room on each side of the trigger, which is the only honest cap:
    //: a fixed figure is either smaller than the window (the reported bug) or
    //: larger than it (a menu running off the bottom).
    const roomBelow = window.innerHeight - margin - (anchor.bottom + 4);
    const roomAbove = anchor.top - 4 - margin;
    if (box.height <= roomBelow) {
      top = anchor.bottom + 4;
      //: **`none`, not `""`.** Clearing the inline cap hands the menu back to
      //: the *stylesheet's* cap, and that is the same lie one level down that
      //: `escapeAndCapMenu` was fixed for in 8b92164: the menu is then placed
      //: by a height it is not drawn at. Downwards that only wastes room;
      //: upwards, the branch below, it is the reported bug. The height was
      //: measured a few lines up with every cap off and found to fit in the
      //: room on this side, so keeping it is exactly what "it fits" meant.
      menu.style.maxHeight = "none";
      menu.style.overflowY = "";
    } else if (box.height <= roomAbove) {
      //: Upwards only when the whole menu fits there. Opening up and *then*
      //: scrolling puts the first row at the bottom of the panel, furthest
      //: from the button that opened it, which reads as a different menu.
      //:
      //: **This is where the cap mattered** (INBOX 119, the owner: "the let
      //: the ai decide button popup is a massive gap above the picker").
      //: Reproduced on :8895, 1440x900 dark, with nine categories in the
      //: notebook (scratchpad/ui-sweeps/notesmenugap3.js): the File under menu
      //: wanted 410.8px, `.select-menu`'s own `max-height: 18rem` drew it at
      //: 288, and `top` was computed from the 410.8, so the menu opened at
      //: y=99 and its bottom landed 127.1px above the opener at y=514.1, with
      //: the gap covering the formatting toolbar and the note body. The
      //: owner's screenshot measures the same 127. Eight categories gave 91px
      //: of gap, ten 163, eleven 199: exactly `wants - drawn + 4` every time,
      //: which is the signature of placing a box by a height something else
      //: then takes away.
      top = anchor.top - 4 - box.height;
      menu.style.maxHeight = "none";
      menu.style.overflowY = "";
    } else {
      //: Taller than both sides: take the larger side and scroll inside it,
      //: with the cut row visible rather than sliced, which is the
      //: affordance. `--space-*` is not reachable from here, so the eight
      //: pixels are the same `margin` the placement already uses.
      const takeBelow = roomBelow >= roomAbove;
      const room = Math.max(120, takeBelow ? roomBelow : roomAbove);
      top = takeBelow ? anchor.bottom + 4 : margin;
      menu.style.maxHeight = `${Math.round(room)}px`;
      menu.style.overflowY = "auto";
    }
    menu.style.left = `${Math.round(left)}px`;
    menu.style.top = `${Math.round(top)}px`;
    //: Placed, so it may be seen (see the guard at the top of this
    //: function for what this is undoing).
    menu.style.visibility = "";
  };
  //: **A `<select>` inside a native `<dialog>` escapes to the dialog, not to
  //: `<body>`.** Reported directly, on the documents dictionary dialog's
  //: spelling picker: "the dictionary preferences dropdown appears behind
  //: the panel." A `showModal()` dialog paints in the browser's top layer,
  //: which is *always* above the regular document regardless of z-index;
  //: `<body>` is the regular document, so a menu reparented there is behind
  //: every open dialog by construction, not by any z-index this file could
  //: raise. The dialog element itself is still the top-layer root, so
  //: appending inside it keeps the menu in the same painting layer as its
  //: own opener.
  const escapeTarget = () => opener.closest("dialog[open]") || document.body;
  const observer = new MutationObserver(() => {
    const open = !menu.classList.contains("hidden");
    const target = escapeTarget();
    if (open && menu.parentElement !== target) {
      homeParent = menu.parentElement;
      homeNext = menu.nextSibling;
      target.appendChild(menu);
      menu.classList.add("action-menu-escaped");
      // openActionMenu() may have already set `.action-menu-flip` (`bottom:
      // calc(100% + 4px)`) based on the menu's *pre-escape* position. `place()`
      // below sets its own inline `top` to open up-or-down as needed, left
      // together, an element with both `top` and `bottom` pinned and
      // `height: auto` is over-constrained, and reproduced live as the menu's
      // box collapsing to ~15px (just its padding+border) while the buttons
      // still rendered past that line, which is what "background doesn't
      // fill the dropdown, looks transparent" actually was. `place()` makes
      // this class redundant once escaped, so drop it rather than fight it.
      menu.classList.remove("action-menu-flip");
      place();
    } else if (!open && menu.parentElement !== homeParent && homeParent) {
      // Restored on close, not left wherever it escaped to (`<body>` or an
      // open dialog): closeActionMenus() and any future openActionMenu()
      // call both expect to find this menu where it started, and a page
      // that never puts an escaped menu back accumulates stray
      // position:fixed nodes at the end of whichever element it escaped to.
      homeParent.insertBefore(menu, homeNext);
      menu.classList.remove("action-menu-escaped");
      menu.style.left = "";
      menu.style.top = "";
      menu.style.visibility = "";
      // The height decisions are the escape's, not the menu's own: left
      // behind they would cap it in its home position too.
      menu.style.maxHeight = "";
      menu.style.overflowY = "";
    }
  });
  observer.observe(menu, { attributes: true, attributeFilter: ["class"] });
  window.addEventListener(
    "resize",
    () => {
      if (!menu.classList.contains("hidden")) place();
    },
    { passive: true }
  );
}

// The Connections block (REDESIGN.md §R7.3 item 1), for a note or a document.
//
// `kind` is "entries" or "documents", the two API prefixes, used verbatim
// as the path segment rather than mapped through a lookup, because a third
// kind would need a third endpoint anyway and a two-entry map is a place for
// them to disagree.
//
// Direction is the whole point of the first two groups. `links_for_entry`
// has always returned both directions merged, so a note could show what it
// was connected to and never which way round, and "this note points at that
// one" and "that one points at this" are different facts. Everything else on
// this dialog is a join that existed in the database and was surfaced
// nowhere: the boards a note is a card on, and the uploads its markdown
// embeds.
async function openConnections(kind, id, subject) {
  const overlay = $("connections-overlay");
  const list = $("connections-list");
  const status = $("connections-status");
  status.classList.remove("error");
  status.textContent = "Loading…";
  list.replaceChildren();
  $("connections-subject").textContent = subject || "";
  overlay.classList.remove("hidden");
  $("connections-close").focus();

  let data;
  try {
    data = await apiJson(`/${kind}/${id}/connections`);
  } catch (error) {
    status.classList.add("error");
    status.textContent = error.message;
    return;
  }
  status.textContent = "";

  // Each group is [heading, rows, how to open one]. Built as data rather
  // than five near-identical blocks of DOM code: the groups differ only in
  // their label field and their click target, and writing that out five
  // times is how one of them quietly loses its keyboard handling.
  const groups =
    kind === "entries"
      ? [
          ["ph:arrow-up-right This note links to", data.outgoing, noteRow],
          ["ph:arrow-down-left Notes that link here", data.incoming, noteRow],
          ["ph:file-text In these documents", data.documents, docRow],
          ["ph:squares-four On these boards", data.boards, boardRow],
          ["ph:image Files it uses", data.files, fileRow],
        ]
      : [
          ["ph:note Notes attached", data.notes, noteRow],
          ["ph:bookmark-simple References", data.bookmarks, bookmarkRow],
          ["ph:image Files it uses", data.files, fileRow],
        ];

  function row(label, title, onOpen) {
    const item = smallButton(label, title, () => {
      overlay.classList.add("hidden");
      onOpen();
    });
    item.classList.add("connection-row");
    return item;
  }
  function noteRow(link) {
    // A private note contributes the fact of the connection and not its
    // words: the server sends "Private note" as the preview, and the flag
    // is what lets this say so rather than showing a label that reads like
    // a real (empty-looking) note title.
    const label = link.is_private ? "ph:lock Private note" : `ph:note ${link.preview}`;
    const why = link.reason ? `\nWhy: ${link.reason}` : "";
    return row(label, `Open this note${why}`, () => flashEntry(link.id));
  }
  function docRow(doc) {
    return row(`ph:file-text ${doc.title}`, `Open “${doc.title}”`, () =>
      openDocumentFromNote(doc.id)
    );
  }
  function boardRow(board) {
    return row(`ph:squares-four ${board.title}`, `Open “${board.title}”`, () =>
      openWhiteboardBoard(board.id ?? null)
    );
  }
  function bookmarkRow(mark) {
    return row(`ph:bookmark-simple ${mark.title || mark.url}`, `Open ${mark.url}`, () =>
      window.open(mark.url, "_blank", "noopener,noreferrer")
    );
  }
  function fileRow(file) {
    const name = file.original_name || file.name;
    // `focusLibraryFile` (library.js) rather than the three steps this used
    // to take inline: the media view is two sub-tabs now, so which one to
    // click depends on whether the file is an image, and that decision
    // belongs in one place.
    return row(`ph:image ${name}`, `Find “${name}” in the Library`, () =>
      focusLibraryFile(name, file.url || file.name)
    );
  }

  let shown = 0;
  for (const [heading, rows, build] of groups) {
    if (!rows || !rows.length) continue;
    shown += rows.length;
    const section = document.createElement("div");
    section.className = "connection-group";
    const head = document.createElement("p");
    head.className = "muted connection-heading";
    setLabel(head, `${heading} (${rows.length})`);
    section.appendChild(head);
    const holder = document.createElement("div");
    holder.className = "connection-rows";
    for (const item of rows) holder.appendChild(build(item));
    section.appendChild(holder);
    list.appendChild(section);
  }
  if (!shown) {
    const empty = document.createElement("p");
    empty.className = "muted";
    empty.textContent =
      kind === "entries"
        ? "Nothing is joined to this note yet. Link it to another note, attach it to a document, or drop it on a whiteboard."
        : "Nothing is joined to this document yet. Attach a note or a reference to it.";
    list.appendChild(empty);
  }
}

$("connections-close")?.addEventListener("click", () =>
  $("connections-overlay").classList.add("hidden")
);

// The ⋯ overflow menu on each note card (Wave L rework).
// Everything that ever happened to one note, with a way back to any of it.
//
// The rows are the event log (Brief 7): every write through the managers
// records one event with an actor and the whole value of each field it set,
// so a row can say who changed the note, what it became, and put it back by
// replaying the log to that point. `revisions` is the older per-edit snapshot
// list, still written and still restorable, and it is what a note whose
// history predates the event log has instead of rows.
const HISTORY_ACTION_WORDS = {
  created: "Written",
  edited: "Edited",
  restored: "Restored",
  deleted: "Moved to the bin",
  archived: "Archived",
  unarchived: "Taken out of the archive",
  linked: "Linked",
  unlinked: "Unlinked",
  purged: "Deleted for good",
};

function historyActorLabel(actor) {
  // "ai:summarise" and "system:auto-file" carry the half worth reading after
  // the colon; "user" is everything a person did and needs no chip at all.
  if (!actor || actor === "user") return "";
  const [kind, rest] = [actor.slice(0, actor.indexOf(":")), actor.slice(actor.indexOf(":") + 1)];
  if (kind === "ai") return `AI: ${rest}`;
  if (kind === "system") return `Background: ${rest}`;
  return actor;
}

async function openEntryHistory(entry) {
  const overlay = $("history-overlay");
  const list = $("history-list");
  $("history-status").textContent = "";
  $("history-status").classList.remove("error");
  list.replaceChildren();
  overlay.classList.remove("hidden");
  $("history-close").focus();

  let history;
  try {
    history = await apiJson(`/entries/${entry.id}/history`);
  } catch (error) {
    $("history-status").classList.add("error");
    $("history-status").textContent = error.message;
    return;
  }
  const events = history?.items || [];
  const revisions = history?.revisions || [];
  if (!events.length && !revisions.length) {
    const p = document.createElement("p");
    p.className = "muted";
    p.textContent = "Nothing has happened to this note yet, so there's nothing to go back to.";
    list.appendChild(p);
    return;
  }

  const restoreTo = async (url, message) => {
    if (!(await confirmDialog("Replace the note with this version?\n\nThe current text is kept in the history, so this is undoable."))) return;
    try {
      await apiJson(url, { method: "POST" });
      overlay.classList.add("hidden");
      toast(message);
      await loadEntries();
      flashEntry(entry.id);
    } catch (error) {
      $("history-status").classList.add("error");
      $("history-status").textContent = error.message;
    }
  };

  // The current text first, so you can see what you'd be replacing.
  const current = document.createElement("div");
  current.className = "history-entry history-current";
  const currentHead = document.createElement("p");
  currentHead.className = "muted";
  currentHead.textContent = "Now";
  const currentBody = document.createElement("p");
  currentBody.textContent = notePreviewText(entry.content);
  current.append(currentHead, currentBody);
  list.appendChild(current);

  // The row every event renders as. A function rather than a loop body
  // because a second page of events is rendered by the same code, below.
  const eventRow = (item) => {
    const row = document.createElement("div");
    row.className = "history-entry";
    const head = document.createElement("p");
    head.className = "muted";
    head.textContent = `${HISTORY_ACTION_WORDS[item.action] || item.action} ${relativeTime(item.created_at)}`;
    const actor = historyActorLabel(item.actor);
    if (actor) {
      const chip = document.createElement("span");
      chip.className = "chip";
      chip.textContent = actor;
      head.append(" ", chip);
    }
    row.appendChild(head);
    if (item.compacted) {
      // The event is still a fact, its text is not kept: `events.compact`
      // drops the values behind changes older than the history window so the
      // log stops growing by a copy of the note on every edit. Saying that in
      // the row is the difference between a history with a gap and a history
      // that looks broken.
      const gone = document.createElement("p");
      gone.className = "muted";
      gone.textContent = "The text from this change is no longer kept.";
      row.appendChild(gone);
    } else if (item.content) {
      const body = document.createElement("p");
      body.textContent = notePreviewText(item.content);
      row.appendChild(body);
      // Only a version that differs from what is on screen is worth putting
      // back: offering "restore" on the state the note is already in reads as
      // a broken button rather than a safe one.
      if (item.content !== entry.content) {
        row.appendChild(
          smallButton("ph:arrow-u-up-left Put this back", "Restore this version", () =>
            restoreTo(`/entries/${entry.id}/restore/${item.id}`, "Earlier version restored.")
          )
        );
      }
    }
    return row;
  };

  // **Paging, and saying what is on screen.** `GET /entries/{id}/history`
  // returns at most `HISTORY_PAGE` (fifty) events and a `next_cursor` for
  // what is older than the oldest of them. This sheet used to read the first
  // page and drop the cursor, so a note edited more than fifty times showed
  // its newest fifty and looked like the whole history: silent truncation,
  // which is worse than a short list, because nothing on screen says the
  // rest exists and a version that is still there reads as lost. The row
  // below is both halves of the fix: it counts what is shown and it fetches
  // the next page.
  let shown = 0;
  let paged = false;  // whether "load older" has been pressed at least once
  let cursor = history?.next_cursor || null;

  // The control sits at the bottom of the events and stays there: the pages
  // that follow are inserted above it, so the list stays in newest-first
  // order however many times it is pressed.
  const more = document.createElement("div");
  more.className = "history-entry";

  const addEvents = (items) => {
    for (const item of items) {
      list.insertBefore(eventRow(item), more);
      shown += 1;
    }
  };

  const loadOlder = async () => {
    if (!cursor) return;
    const at = cursor;
    cursor = null;  // so a second press while this one is in flight is a no-op
    renderMore(true);
    let page;
    try {
      page = await apiJson(`/entries/${entry.id}/history?before=${at}`);
    } catch (error) {
      cursor = at;
      renderMore();
      $("history-status").classList.add("error");
      $("history-status").textContent = error.message;
      return;
    }
    addEvents(page?.items || []);
    paged = true;
    cursor = page?.next_cursor || null;
    renderMore();
  };

  const renderMore = (loading = false) => {
    more.replaceChildren();
    // A history that fits in one page says nothing extra: the row exists to
    // answer "is this all of it?", and on a note with a dozen changes the
    // list already answers that by ending.
    more.classList.toggle("hidden", !cursor && !loading && !paged);
    const note = document.createElement("p");
    note.className = "muted";
    if (cursor || loading) {
      // Plain about what it is: the count is what is on screen, not a
      // guess at the total, which the route does not send and which
      // counting would cost a second query to know.
      note.textContent = `Showing the ${shown} most recent changes to this note.`;
    } else if (paged) {
      note.textContent = `That is all ${shown} changes to this note.`;
    }
    more.appendChild(note);
    if (cursor) {
      more.appendChild(
        smallButton("ph:clock-counter-clockwise Load older changes", "Load the next page of this note's history", loadOlder)
      );
    } else if (loading) {
      const wait = document.createElement("p");
      wait.className = "muted";
      wait.textContent = "Loading older changes.";
      more.appendChild(wait);
    }
  };

  list.appendChild(more);
  addEvents(events);
  renderMore();

  // The snapshots are the same versions the events already show, one row
  // earlier, so they are only worth rendering for a note whose edits predate
  // the event log: measured on a note edited twice, both lists said "version
  // one of the note" and the sheet showed it twice.
  const snapshotsOnly = !events.some((item) => item.content);
  for (const revision of snapshotsOnly ? revisions : []) {
    const item = document.createElement("div");
    item.className = "history-entry";
    const head = document.createElement("p");
    head.className = "muted";
    head.textContent = `Before ${new Date(revision.created_at).toLocaleString()}`;
    const body = document.createElement("p");
    body.textContent = notePreviewText(revision.content);
    const restore = smallButton("ph:arrow-u-up-left Put this back", "Restore this version", () =>
      restoreTo(`/entries/${entry.id}/history/${revision.id}/restore`, "Earlier version restored.")
    );
    item.append(head, body, restore);
    list.appendChild(item);
  }
}

async function toggleEntryPrivacy(entry) {
  const makingPrivate = !entry.is_private;
  if (makingPrivate) {
    const ok = (await confirmDialog(
      "Make this note private?\n\n" +
        "It gets encrypted with a key derived from your password, so it stays " +
        "unreadable in the database, in backups, and to anyone without that " +
        "password.\n\n" +
        "It also stops appearing in search and stops being given to the AI.\n\n" +
        "There is no recovery: if you forget your password this note is gone."
    ));
    if (!ok) return;
  }
  try {
    await apiJson(`/entries/${entry.id}/privacy`, {
      method: "POST",
      body: JSON.stringify({ private: makingPrivate }),
    });
    toast(makingPrivate ? "Note encrypted." : "Note is readable again.");
    await loadEntries();
  } catch (error) {
    toast(error.message, true);
  }
}

// Reported: no popup shows when a title is regenerated.
//
// There WAS a toast, and it was being swallowed. `toast()` drops anything
// that is not an error while notifications are muted, which is right for
// background chatter and wrong here: this is the result of a button the user
// just pressed, and a direct action that reports nothing reads as a broken
// button. Muting is about noise you did not ask for.
//
// The "Generating…" toast is also worth keeping distinct from the settled one:
// this call waits on the model, so it can take seconds, and a control that
// looks inert for seconds gets pressed again.
async function generateEntryTitle(entry) {
  const regenerating = Boolean(entry.title);
  try {
    toast(regenerating ? "Regenerating the title…" : "Generating a title…", false, {
      exempt: true,
    });
    const updated = await apiJson(`/entries/${entry.id}/generate-title`, { method: "POST" });
    await loadEntries();
    flashEntry(entry.id);
    const title = updated && updated.title;
    toast(title ? `Titled “${title}”.` : "Titled.", false, { exempt: true });
    // And in the notification centre, so the result survives the 5.5 seconds
    // the toast lives for, the model can finish while you are on another tab.
    recordNotification({
      kind: "task",
      title: regenerating ? "Title regenerated" : "Title generated",
      detail: title ? `“${title}”` : `Note #${entry.id}`,
    });
  } catch (error) {
    toast(error.message || "Couldn't generate a title.", true);
  }
}

async function removeEntryTitle(entry) {
  try {
    await apiJson(`/entries/${entry.id}/remove-title`, { method: "POST" });
    await loadEntries();
    flashEntry(entry.id);
    // Said out loud for the same reason as above: it was silent, so the only
    // feedback was noticing the title had gone.
    toast("Title removed.", false, { exempt: true });
  } catch (error) {
    toast(error.message || "Couldn't remove the title.", true);
  }
}

// Arrow-key navigation, as the `role="menu"` contract implies. ↑/↓ move
// between *top-level* items (wrapping): `:scope >` so a hidden submenu's own
// items (handled by their own keydown handler) never get mixed into this list,
// which would desync Home/End and let arrow keys land on an item the user
// can't currently see. Home/End jump to the ends, Esc closes and returns focus
// to the opener.
//
// **Shared, because it used to belong to one menu.** This was written inline
// inside `entryOverflowMenu`, so the note card's ⋯ had full keyboard
// navigation and every menu built by `kebabMenu`, the conversation list, the
// sidebar kebabs, and now the text-selection menu, had none: Tab still
// stepped through the items (they are buttons), but ↑/↓ did nothing, which is
// the one thing a person who has just opened a menu will try. Found by
// driving the new selection menu from the keyboard and watching ArrowDown
// leave focus where it was.
function wireMenuKeyboard(menu, opener) {
  menu.addEventListener("keydown", (event) => {
    const menuItems = [
      ...menu.querySelectorAll(
        ':scope > [role="menuitem"], :scope > .menu-group > [role="menuitem"]'
      ),
    ];
    if (!menuItems.length) return;
    const current = menuItems.indexOf(document.activeElement);
    if (event.key === "ArrowDown") {
      event.preventDefault();
      focusMenuItem(menuItems[(current + 1) % menuItems.length], menu);
    } else if (event.key === "ArrowUp") {
      event.preventDefault();
      focusMenuItem(menuItems[(current - 1 + menuItems.length) % menuItems.length], menu);
    } else if (event.key === "Home") {
      event.preventDefault();
      focusMenuItem(menuItems[0], menu);
    } else if (event.key === "End") {
      event.preventDefault();
      focusMenuItem(menuItems[menuItems.length - 1], menu);
    } else if (event.key === "Escape") {
      event.preventDefault();
      closeActionMenus();
      opener.focus();
    }
  });
}

// A single `role="menuitem"` button: shared by the top-level menu and every
// submenu, so a click behaves identically (close everything, then run) no
// matter how deep the item is nested.
function buildMenuItemButton(item) {
  const button = document.createElement("button");
  button.setAttribute("role", "menuitem");
  button.className = "menu-item" + (item.danger ? " menu-danger" : "");
  setLabel(button, item.label);
  if (item.title) button.title = item.title;
  button.addEventListener("click", () => {
    closeActionMenus();
    item.run();
  });
  return button;
}

// At most one grouped flyout (AI actions / Connect / Add) is ever open at
// once, on any note card: `openActionMenu` already guarantees at most one
// top-level kebab is open on the page, and only one of its own groups can
// be expanded at a time. A single reference here is enough to close a
// sibling group's flyout when another opens, without a DOM search that
// escaping the flyout to `<body>` below has already made impossible (see
// `buildMenuGroupButton`'s own note).
let openGroupSubmenu = null;

// A grouped trigger ("AI AI actions ›") that opens a side flyout of its own
// items: asked for directly, to cut a 15-item flat list down to something
// scannable. Hover opens it on a device that has hover; click/tap opens it
// everywhere, which is the only way in on a touchscreen. Below
// `--menu-submenu-stack-width` (phone-width) there is nowhere for a flyout
// to go without running off-screen, so it drops the side-popup positioning
// entirely and expands in place instead, an accordion, not a flyout, which
// is what "compatible with small screens like iPhones" actually means here.
function buildMenuGroupButton(label, subItems) {
  const groupWrap = document.createElement("div");
  groupWrap.className = "menu-group";

  const trigger = document.createElement("button");
  trigger.setAttribute("role", "menuitem");
  trigger.setAttribute("aria-haspopup", "menu");
  trigger.setAttribute("aria-expanded", "false");
  trigger.className = "menu-item has-submenu";
  const labelSpan = document.createElement("span");
  // setLabel, not textContent: these three group triggers ("AI actions",
  // "Connect", "Add") were the one label sink the sweep missed, so the note
  // kebab menu rendered the literal text "ph:magic-wand AI actions".
  setLabel(labelSpan, label);
  const arrow = document.createElement("span");
  arrow.className = "menu-submenu-arrow";
  arrow.setAttribute("aria-hidden", "true");
  arrow.textContent = "›";
  trigger.append(labelSpan, arrow);

  const submenu = document.createElement("div");
  submenu.className = "action-menu submenu hidden";
  submenu.setAttribute("role", "menu");
  for (const item of subItems) submenu.appendChild(buildMenuItemButton(item));

  // **Reparented to `<body>` while open, like `escapeMenuIfClipped` does for
  // the top-level kebab.** Reported: a submenu opened from a kebab near the
  // bottom or right of the viewport (a note card low in the list, or the
  // last card in a row) drew past the window edge with nothing but a
  // scrollbar to show for it. `.action-menu.submenu` was `position:
  // absolute` against its own `.menu-group`, which only ever checked the
  // *horizontal* edge (`submenu-left`, below); there was no vertical check
  // at all, and once the parent kebab is itself escaped (also `position:
  // fixed`, also reparented to `<body>`) the submenu's containing block
  // moves with it, so a flyout that fit its note card could still miss the
  // actual browser window. Reusing `.action-menu-escaped` (`position:
  // fixed`, the same z-index tier) plus this menu's own placement, computed
  // from the trigger's rect and clamped on both axes, fixes both at once:
  // this is why `openSubmenu`/`closeSubmenuState` below write the same
  // `_escapedHome`/`_escapedOpener` fields `restoreEscapedMenu` already
  // knows how to put back, rather than inventing a second bookkeeping
  // scheme `closeActionMenus`' own document-wide sweep would not see.
  const placeSubmenu = () => {
    const margin = 8;
    const anchor = trigger.getBoundingClientRect();
    submenu.style.marginLeft = "0";
    submenu.style.left = "0px";
    submenu.style.top = "0px";
    const box = submenu.getBoundingClientRect();
    let left = anchor.right + 8;
    let onLeft = false;
    if (left + box.width > window.innerWidth - margin) {
      left = anchor.left - 8 - box.width;
      onLeft = true;
    }
    left = Math.max(margin, left);
    let top = anchor.top;
    if (top + box.height > window.innerHeight - margin) {
      top = Math.max(margin, window.innerHeight - margin - box.height);
    }
    submenu.style.left = `${Math.round(left)}px`;
    submenu.style.top = `${Math.round(top)}px`;
    submenu.classList.toggle("submenu-left", onLeft);
  };

  const openSubmenu = () => {
    // Only one flyout open at a time, at this level or any sibling group;
    // a DOM search under `groupWrap.parentElement` cannot find a sibling's
    // flyout once it may live at `<body>`, so this is tracked directly.
    if (openGroupSubmenu && openGroupSubmenu !== submenu) closeSubmenuState(openGroupSubmenu);
    submenu.classList.remove("hidden");
    trigger.setAttribute("aria-expanded", "true");
    submenu.classList.remove("submenu-left");
    // Below phone-width the flyout positioning is dropped for an in-place
    // accordion (CSS media query); escaping it there would strand it at a
    // fixed viewport position while its own trigger scrolls underneath.
    if (window.innerWidth > 720) {
      submenu._escapedHome = { parent: submenu.parentElement, next: submenu.nextSibling };
      submenu._escapedOpener = trigger;
      document.body.appendChild(submenu);
      submenu.classList.add("action-menu-escaped");
      placeSubmenu();
    }
    openGroupSubmenu = submenu;
  };
  function closeSubmenuState(target) {
    target.classList.add("hidden");
    target._escapedOpener?.setAttribute("aria-expanded", "false");
    restoreEscapedMenu(target);
    target.style.marginLeft = "";
    target.classList.remove("submenu-left");
    if (openGroupSubmenu === target) openGroupSubmenu = null;
  }
  const closeSubmenu = () => closeSubmenuState(submenu);

  let hoverTimer = null;
  groupWrap.addEventListener("mouseenter", () => {
    clearTimeout(hoverTimer);
    hoverTimer = setTimeout(openSubmenu, 120); // brief delay: a mouse crossing the item isn't a request to open it
  });
  groupWrap.addEventListener("mouseleave", () => {
    clearTimeout(hoverTimer);
    hoverTimer = setTimeout(closeSubmenu, 200); // outlives the diagonal move from the trigger into the flyout
  });
  // Once escaped, the submenu is a sibling of `groupWrap` at `<body>`, not
  // its descendant, so `groupWrap`'s own `mouseleave` above fires the
  // instant the pointer crosses onto the (still open) flyout: measured
  // live, the submenu closed under the cursor before a hovering mouse user
  // could ever reach a second-level item. These two mirror the pair above
  // so hovering the flyout itself also keeps it open.
  submenu.addEventListener("mouseenter", () => clearTimeout(hoverTimer));
  submenu.addEventListener("mouseleave", () => {
    hoverTimer = setTimeout(closeSubmenu, 200);
  });
  trigger.addEventListener("click", (event) => {
    event.stopPropagation();
    if (submenu.classList.contains("hidden")) openSubmenu();
    else closeSubmenu();
  });
  submenu.addEventListener("keydown", (event) => {
    const subItems = [...submenu.querySelectorAll(':scope > [role="menuitem"]')];
    const current = subItems.indexOf(document.activeElement);
    if (event.key === "ArrowDown") {
      event.preventDefault();
      subItems[(current + 1) % subItems.length]?.focus();
    } else if (event.key === "ArrowUp") {
      event.preventDefault();
      subItems[(current - 1 + subItems.length) % subItems.length]?.focus();
    } else if (event.key === "ArrowLeft" || event.key === "Escape") {
      event.preventDefault();
      event.stopPropagation(); // don't also close the whole menu on ArrowLeft
      closeSubmenu();
      trigger.focus();
    }
  });
  trigger.addEventListener("keydown", (event) => {
    if (event.key === "ArrowRight" || event.key === "Enter" || event.key === " ") {
      event.preventDefault();
      openSubmenu();
      submenu.querySelector('[role="menuitem"]')?.focus();
    }
  });

  groupWrap.append(trigger, submenu);
  return groupWrap;
}

function entryOverflowMenu(entry) {
  const wrap = document.createElement("span");
  wrap.className = "menu-wrap";

  const menu = document.createElement("div");
  menu.className = "action-menu hidden";
  menu.setAttribute("role", "menu");

  //: Same square-kebab rule as `kebabMenu` below: this is the *other* ⋯
  //: builder (note cards, built lazily on first open), and a rule applied to
  //: one of two implementations of the same control is how they drift.
  //:
  //: **And they had.** Reported: "the ellipse kebab icons in the notes on the
  //: your notes tab are not centred." `kebabMenu` draws `ph:dots-three`; this
  //: one drew the literal character `⋯` (U+22EF), and a text glyph is placed
  //: on the *font's* baseline inside a 19.2px line box centred in a 28px
  //: button: U+22EF sits at the em box's midline, which is above the line
  //: box's optical centre, so the dots rode high. No amount of flex centring
  //: fixes that: the box is centred correctly and the glyph is not centred
  //: within the box. The icon font's own glyph is drawn to fill its box, so
  //: using the same icon as the other builder fixes the centring and the
  //: drift in one go.
  const opener = smallButton("ph:dots-three", "More actions", () => {
    const willOpen = menu.classList.contains("hidden");
    if (willOpen) {
      fillMenu();
      openActionMenu(menu, opener);
    } else closeActionMenus();
  });
  opener.classList.add("icon-only");
  opener.setAttribute("aria-haspopup", "menu");
  opener.setAttribute("aria-expanded", "false");

  // **Built on first open, not on render, and that is a scale fix rather than
  // a micro-optimisation.** This menu is 19 items across four groups, call it
  // 45-60 DOM nodes once the submenu wrappers, icon `<i>`s and label `<span>`s
  // are counted: and `entryItem()` builds one of these for *every* note card.
  // The Notes list renders the whole notebook (there is no windowing), so a
  // 2,500-note notebook built well over a hundred thousand permanently-hidden
  // nodes, and rebuilt all of them on every `renderEntries()`, which runs on
  // every search keystroke, every sort change, every filter and every save.
  //
  // Almost none of it is ever looked at: a person opens the ⋯ menu on one note
  // at a time, if at all. Deferring the items costs one function call on the
  // first open and nothing after.
  //
  // The opener itself still renders eagerly, deliberately, it carries the
  // `aria-haspopup`/`aria-expanded` state and it occupies a place in the tab
  // order, so making *it* lazy would change focus behaviour. Only the contents
  // are deferred, and `openActionMenu` is called after `fillMenu()` so it still
  // finds a first item to focus.
  let filled = false;
  function fillMenu() {
    if (filled) return;
    filled = true;
    // Kept flat: the three actions used often enough, or serious enough (a
    // delete), that burying them a level down would cost more than the
    // grouping below saves. Everything else groups into three side flyouts, 
    // asked for directly, to cut what had grown into a 15-item flat list.
    const topLevel = [
      // Direct instruction: a way into multi-select from the row itself,
      // not only the toolbar's own "Select" button: which is real and
      // already works, but requires knowing it exists and is above the
      // list rather than on the note someone actually wants to start
      // selecting from. Reuses that exact same mode (`enterSelectMode`,
      // `selectedIds`) rather than inventing a second one, and seeds it
      // with this note already checked, so choosing "Select" here is a
      // head start rather than an empty selection identical to the
      // toolbar button's own.
      {
        label: "ph:check-square Select",
        title: "Start selecting multiple notes, beginning with this one",
        run: () => {
          enterSelectMode();
          selectedIds.add(entry.id);
          updateBatchCount();
          renderEntries();
        },
      },
      {
        label: entry.is_private ? "ph:lock-open Make readable" : "ph:lock Make private",
        title: entry.is_private
          ? "Decrypt this note so search and the AI can use it again"
          : "Encrypt this note at rest, and keep it out of search and the AI",
        run: () => toggleEntryPrivacy(entry),
      },
      {
        // Sits above History because it is the more common question by far:
        // "what else is this about?" is asked of a note every time it is
        // read, and "what did it used to say?" only when something looks
        // wrong.
        label: "ph:graph Connections",
        title: "Everything this note is joined to, links both ways, documents, boards and files",
        // The note's own title when it wrote one, and its first words
        // otherwise: `notePreviewText` alone hands back both lines of a
        // titled note ("Probe A\nrelates to sourdough"), which reads as
        // two sentences jammed together on one line of the dialog.
        run: () =>
          openConnections(
            "entries",
            entry.id,
            entry.title || notePreviewText(entry.content).split("\n")[0].slice(0, 80)
          ),
      },
      {
        label: "ph:clock-counter-clockwise History",
        title: "See earlier versions of this note, and put one back",
        run: () => openEntryHistory(entry),
      },
      // BACKLOG.md §95 item D.14: "Full export exists. There is no way to
      // hand one note to someone." Same route shape and same "download,
      // not navigate" pattern the Documents kebab's own "Download .md"
      // already uses (library.js).
      {
        label: "ph:download-simple Download .md",
        title: "Save a copy of this note as a markdown file",
        run: () => window.open(`/entries/${entry.id}/export.md`, "_blank"),
      },
    ];

    const aiItems = [
      {
        label: "ph:arrows-clockwise Re-evaluate",
        title: "Refresh this note's AI confidence and suggest tags & links",
        run: () => reevaluateEntry(entry),
      },
      {
        label: "ph:magic-wand Improve writing",
        title: "Proofread or rewrite this note with AI",
        run: () => {
          editingId = entry.id;
          renderEntries();
          // The edit textarea now exists, improve it in place.
          const box = document.querySelector(`#entry-list li[data-id="${entry.id}"] textarea`);
          if (box) openImprove(box);
        },
      },
      {
        // Recognising a title the note already wrote (a leading `# Heading`)
        // is free; writing one costs a real model call, so it's this
        // separate, on-request action rather than something automatic.
        label: entry.title ? "ph:magic-wand Regenerate title" : "ph:magic-wand Generate title",
        title: "Write a short title for this note with AI",
        run: () => generateEntryTitle(entry),
      },
      ...(entry.title
        ? [
            {
              label: "✕ Remove title",
              title: "Take the title back out, the note's text is unchanged",
              run: () => removeEntryTitle(entry),
            },
          ]
        : []),
    ];

    const connectItems = [
      {
        label: "ph:file-text Add to a document",
        title: "Attach this note to a document you have already started",
        run: () => {
          inlineAction = inlineActionIs(entry.id, "document")
            ? null
            : { id: entry.id, kind: "document" };
          renderEntries();
        },
      },
      {
        label: "ph:file-text Expand into a document",
        title: "Start a document from this note, the note stays where it is",
        run: () => expandNoteIntoDocument(entry),
      },
      { label: "ph:link Link to another", run: () => beginOrCompleteLink(entry) },
      { label: "≈ Similar notes", run: () => toggleRelated(entry) },
    ];

    const addItems = [
      {
        label: "ph:copy Duplicate",
        title: "Make a copy of this note, opens ready to edit",
        run: async () => {
          closeActionMenus();
          try {
            const copy = await apiJson("/entries", {
              method: "POST",
              body: JSON.stringify({
                content: entry.content,
                title: entry.title ? `${entry.title} (Copy)` : undefined,
                category: entry.category,
                tags: entry.tags || [],
              }),
            });
            await loadEntries();
            // Open the new note in edit mode straight away.
            if (copy && copy.id) {
              editingId = copy.id;
              renderEntries();
              flashEntry(copy.id);
            }
            toast("Note duplicated.");
          } catch (err) {
            toast(err.message || "Couldn't duplicate note.", true);
          }
        },
      },
      {
        label: "ph:plus Add context",
        title: "Append detail: the AI may refile it",
        run: () => {
          inlineAction = inlineActionIs(entry.id, "context") ? null : { id: entry.id, kind: "context" };
          renderEntries();
        },
      },
      {
        label: "⤵ Continue thought",
        title: "Start or extend a thread from this note",
        run: () => {
          inlineAction = inlineActionIs(entry.id, "continue") ? null : { id: entry.id, kind: "continue" };
          renderEntries();
        },
      },
      {
        label: "ph:alarm Remind me",
        run: () => {
          inlineAction = inlineActionIs(entry.id, "remind") ? null : { id: entry.id, kind: "remind" };
          renderEntries();
        },
      },
      { label: "ph:paperclip Attach a file", run: () => attachFileTo(entry) },
      { label: "ph:images-square Attach from Library", run: () => attachFromLibrary(entry) },
    ];

    // Not destructive, so not grouped with "danger" below: but visually
    // adjacent to it (asked for directly: a way to keep a note but get it
    // out of the way, distinct from binning it) so the two "get this off my
    // list" actions sit together rather than one being buried in a group.
    const archive = entry.archived_at
      ? {
          label: "ph:arrow-u-up-left Unarchive",
          title: "Bring this note back into your notebook",
          run: async () => {
            await apiJson(`/entries/${entry.id}/unarchive`, { method: "POST" });
            await loadEntries();
            toast("Unarchived.");
          },
        }
      : {
          label: "ph:archive Archive",
          title: "Keep it, but out of the way, not the bin",
          run: async () => {
            await apiJson(`/entries/${entry.id}/archive`, { method: "POST" });
            await loadEntries();
            toast("Archived.");
          },
        };

    const danger = {
      label: "ph:trash Move to bin",
      danger: true,
      // Instant + one-click Undo, soft delete underneath (Wave J). Also on the
      // global undo stack (status bar / Ctrl+Z), so it survives past the
      // toast's own timeout.
      run: async () => {
        await api(`/entries/${entry.id}`, { method: "DELETE" });
        await loadEntries();
        const restoreIt = async () => {
          await api(`/entries/${entry.id}/restore`, { method: "POST" });
          await loadEntries();
        };
        const binIt = async () => {
          await api(`/entries/${entry.id}`, { method: "DELETE" });
          await loadEntries();
        };
        const action = pushUndo("Moved a note to the bin", restoreIt, binIt);
        toastAction("Moved to the recycle bin.", "Undo", async () => {
          settleUndoFromToast(action);
          await restoreIt();
          toast("Note restored.");
        });
      },
    };

    for (const item of topLevel) menu.appendChild(buildMenuItemButton(item));
    menu.appendChild(buildMenuGroupButton("ph:magic-wand AI actions", aiItems));
    menu.appendChild(buildMenuGroupButton("ph:link Connect", connectItems));
    menu.appendChild(buildMenuGroupButton("ph:plus Add", addItems));
    menu.appendChild(buildMenuItemButton(archive));
    menu.appendChild(buildMenuItemButton(danger));
  }

  wireMenuKeyboard(menu, opener);

  wrap.append(opener, menu);
  return wrap;
}

// The Add context / continue / remind boxes inside an entry card.
// Ask the AI to re-evaluate one note, then show its suggestions inline.
async function reevaluateEntry(entry) {
  closeActionMenus();
  toast("Re-evaluating with AI…");
  // Show a spinner on this exact card while the AI works.
  busyEntryId = entry.id;
  renderEntries();
  try {
    const result = await apiJson(`/entries/${entry.id}/reevaluate`, { method: "POST" });
    // If the confidence actually changed, flash the badge on the next render.
    const newConfidence = result.entry ? result.entry.ai_confidence : null;
    if (newConfidence !== null && newConfidence !== entry.ai_confidence) {
      flashConfidenceId = entry.id;
    }
    inlineAction = { id: entry.id, kind: "reevaluate", data: result };
    busyEntryId = null;
    await loadEntries(); // reflect the refreshed confidence/category, then show suggestions
  } catch (error) {
    busyEntryId = null;
    renderEntries();
    toast(error.message || "Re-evaluate failed.", true);
  }
}

// The inline result of a re-evaluate: new confidence, plus tag and link
// suggestions the user applies with a click (nothing is applied on its own).
function renderReevaluateResult(entry, wrap) {
  const data = inlineAction.data;
  const confidence = data.entry ? data.entry.ai_confidence : entry.ai_confidence;

  const head = document.createElement("p");
  head.className = "muted";
  head.textContent = data.recategorised_to
    ? `Re-evaluated: confidence ${confidence}%, moved to “${data.recategorised_to}”.`
    : `Re-evaluated: confidence now ${confidence}%.`;
  wrap.appendChild(head);

  // Drop suggestions the user already applied (the card re-renders after each).
  const haveTags = new Set(entry.tags);
  const linkedIds = new Set((entry.links || []).map((l) => l.entry_id));
  const tags = (data.suggested_tags || []).filter((t) => !haveTags.has(t));
  const links = (data.suggested_links || []).filter((l) => !linkedIds.has(l.id));

  if (tags.length) {
    const tagRow = document.createElement("div");
    tagRow.className = "recent";
    const label = document.createElement("span");
    label.className = "muted";
    label.textContent = "Add tags:";
    tagRow.appendChild(label);
    for (const tag of tags) {
      const tagChip = chip(`＋ ${tag}`, "tag", async () => {
        try {
          await api(`/entries/${entry.id}`, {
            method: "PUT",
            body: JSON.stringify({ tags: [...entry.tags, tag] }),
          });
          tagChip.remove();
          toast(`Tagged “${tag}”.`);
          loadEntries();
        } catch (error) {
          toast(error.message, true);
        }
      });
      tagChip.title = `Add the “${tag}” tag`;
      tagRow.appendChild(tagChip);
    }
    wrap.appendChild(tagRow);
  }

  if (links.length) {
    const label = document.createElement("p");
    label.className = "muted";
    label.textContent = "Link to related notes:";
    wrap.appendChild(label);
    for (const link of links) {
      const row = document.createElement("div");
      row.className = "row space-between reevaluate-link";
      const preview = document.createElement("span");
      renderInlineMarkdown(preview, link.preview, [], true);
      row.appendChild(preview);
      row.appendChild(
        smallButton("ph:link Link", "Link these two notes", async () => {
          try {
            const updated = await apiJson(`/entries/${entry.id}/links`, {
              method: "POST",
              body: JSON.stringify({ target_id: link.id }),
            });
            row.remove();
            toast("Notes linked.");
            loadEntries();
            let liveLinkId = updated.links.find((l) => l.entry_id === link.id)?.link_id;
            pushUndo(
              "Linked two notes",
              async () => {
                if (liveLinkId == null) return;
                await api(`/entries/${entry.id}/links/${liveLinkId}`, { method: "DELETE" });
                await loadEntries();
              },
              async () => {
                const redone = await apiJson(`/entries/${entry.id}/links`, {
                  method: "POST",
                  body: JSON.stringify({ target_id: link.id }),
                });
                liveLinkId = redone.links.find((l) => l.entry_id === link.id)?.link_id ?? liveLinkId;
                await loadEntries();
              }
            );
          } catch (error) {
            toast(error.message, true);
          }
        })
      );
      wrap.appendChild(row);
    }
  }

  if (!tags.length && !links.length) {
    const none = document.createElement("p");
    none.className = "muted";
    none.textContent = "No new tags or links to suggest right now.";
    wrap.appendChild(none);
  }

  wrap.appendChild(
    smallButton("Done", "Close", () => {
      inlineAction = null;
      renderEntries();
    })
  );
}

function renderInlineAction(entry) {
  const wrap = document.createElement("div");
  wrap.className = "inline-action";

  if (inlineAction.kind === "reevaluate") {
    renderReevaluateResult(entry, wrap);
    return wrap;
  }

  if (inlineAction.kind === "document") {
    renderAttachToDocument(entry, wrap);
    return wrap;
  }

  if (inlineAction.kind === "remind") {
    const preview = entry.content.length > 40 ? entry.content.slice(0, 39) + "…" : entry.content;
    const textInput = document.createElement("input");
    textInput.type = "text";
    textInput.value = `Follow up: ${preview}`;
    const dueInput = document.createElement("input");
    dueInput.type = "datetime-local";
    dueInput.value = defaultDueValue();
    const row = document.createElement("div");
    row.className = "row";
    row.appendChild(
      smallButton("Set reminder", "", async () => {
        if (await addReminder(textInput.value.trim(), dueInput.value, entry.id)) {
          inlineAction = null;
          renderEntries();
        }
      }, false)
    );
    row.appendChild(
      smallButton("Cancel", "", () => {
        inlineAction = null;
        renderEntries();
      })
    );
    wrap.append(textInput, dueInput, row);
    setTimeout(() => textInput.focus(), 0);
    return wrap;
  }

  const isContext = inlineAction.kind === "context";

  const textarea = document.createElement("textarea");
  textarea.rows = 2;
  textarea.placeholder = isContext
    ? "Add detail: the AI re-reads the whole note and may refile it…"
    : "Continue this train of thought…";
  wrap.appendChild(textarea);

  const row = document.createElement("div");
  row.className = "row";
  row.appendChild(
    smallButton(
      isContext ? "Add context" : "Add to thread",
      "",
      async () => {
        const text = textarea.value.trim();
        if (!text) return;
        try {
          if (isContext) {
            const updated = await apiJson(`/entries/${entry.id}/context`, {
              method: "POST",
              body: JSON.stringify({ text }),
            });
            toast(
              updated.category === entry.category
                ? `Context added: still filed under “${updated.category}”.`
                : `Context added: refiled under “${updated.category}”.`
            );
          } else {
            await apiJson("/entries", {
              method: "POST",
              body: JSON.stringify({ content: text, parent_id: entry.id }),
            });
            toast("Thread continued.");
          }
          inlineAction = null;
          await loadEntries();
        } catch (error) {
          toast(error.message, true);
        }
      },
      false
    )
  );
  row.appendChild(
    smallButton("Cancel", "", () => {
      inlineAction = null;
      renderEntries();
    })
  );
  wrap.appendChild(row);
  setTimeout(() => textarea.focus(), 0);
  return wrap;
}

function attachFileTo(entry) {
  const input = document.createElement("input");
  input.type = "file";
  // The backend already accepts one attachment per POST and a note already
  // renders any number of them, the only thing missing was the picker
  // itself only ever taking `files[0]`, silently dropping a multi-select.
  input.multiple = true;
  input.addEventListener("change", async () => {
    const files = [...input.files];
    if (!files.length) return;
    let failures = 0;
    for (const file of files) {
      const form = new FormData();
      form.append("file", file);
      // Raw fetch: multipart must NOT get the JSON content-type header.
      const response = await fetch(`/entries/${entry.id}/files`, {
        method: "POST",
        // X-Workspace-ID alongside X-Auth-Token: a raw fetch (multipart body,
        // so it cannot go through api()/apiJson()) does not get either header
        // for free the way every JSON call in this file does.
        headers: { "X-Auth-Token": authToken(), "X-Workspace-ID": activeSpaceId() },
        body: form,
      });
      if (!response.ok) {
        failures++;
        const detail = await response.json().catch(() => ({}));
        toast(detail.detail || `${file.name}: upload failed (${response.status})`, true);
      }
    }
    const attached = files.length - failures;
    if (attached > 0) {
      toast(attached === 1 ? `Attached ${files[0].name}.` : `Attached ${attached} files.`);
    }
    await loadEntries();
  });
  input.click();
}

// The Library's other half of "upload directly, attach later", asked for
// directly. `attachFileTo` above always opens a fresh disk picker; this
// instead offers whatever already lives in the Library's image/PDF gallery
// (MediaUpload: GET /media), so an image uploaded once doesn't need
// re-uploading onto every note that wants it. Note attachments (Attachment,
// PDFs, docs, audio: attachFileTo's own domain) have no "floating, not yet
// attached to anything" state to pick from, so this is images/PDFs only,
// same as the Library gallery itself.
async function attachFromLibrary(entry) {
  const images = await apiJson("/media", { silent: true }).catch(() => null);
  if (!images) {
    toast("Couldn't load the Library gallery.", true);
    return;
  }
  if (!images.length) {
    toast("Nothing in the Library gallery yet, upload one from Library → Files & Images first.", true);
    return;
  }

  const overlay = document.createElement("div");
  overlay.className = "modal-overlay library-attach-overlay";
  overlay.setAttribute("role", "dialog");
  overlay.setAttribute("aria-modal", "true");
  overlay.setAttribute("aria-label", "Attach from Library");

  const card = document.createElement("div");
  card.className = "card modal-card";
  const head = document.createElement("div");
  head.className = "row space-between library-head";
  const title = document.createElement("h2");
  title.textContent = "Attach from Library";
  const close = document.createElement("button");
  close.type = "button";
  close.className = "ghost small";
  close.setAttribute("aria-label", "Close");
  setLabel(close, "ph:x");
  head.append(title, close);
  const hint = document.createElement("p");
  hint.className = "muted";
  hint.textContent = "Pick an image or PDF already in the Library to attach it to this note.";
  const grid = document.createElement("div");
  grid.className = "library-image-grid library-attach-grid";

  const done = () => {
    document.removeEventListener("keydown", onKey, true);
    overlay.remove();
  };
  const onKey = (event) => {
    if (event.key === "Escape") {
      event.stopPropagation();
      done();
    }
  };
  close.addEventListener("click", done);
  wireBackdropClose(overlay, () => done());
  document.addEventListener("keydown", onKey, true);

  const isPdf = (url) => /\.pdf$/i.test(url);
  for (const image of images) {
    const fig = document.createElement("figure");
    fig.className = "library-image-tile";
    const button = document.createElement("button");
    button.type = "button";
    button.className = "library-attach-pick";
    button.title = `Attach “${image.original_name}”`;
    if (isPdf(image.url)) {
      const icon = document.createElement("i");
      icon.className = "ph ph-file-pdf";
      icon.setAttribute("aria-hidden", "true");
      button.appendChild(icon);
    } else {
      const img = document.createElement("img");
      img.src = mediaSrc(image.url);
      img.alt = "";
      img.loading = "lazy";
      button.appendChild(img);
    }
    button.addEventListener("click", async () => {
      const markdown = isPdf(image.url)
        ? `[${image.original_name}](${image.url})\n`
        : `![${image.original_name}](${image.url})\n`;
      const nextContent = `${entry.content.trim()}\n\n${markdown}`.trim();
      try {
        await apiJson(`/entries/${entry.id}`, {
          method: "PUT",
          body: JSON.stringify({ content: nextContent }),
        });
        toast(`Attached ${image.original_name}.`);
        done();
        await loadEntries();
        pushEntryPutUndo(
          entry.id,
          `Attached ${image.original_name}`,
          { content: entry.content },
          { content: nextContent }
        );
      } catch (error) {
        toast(error.message || "Couldn't attach that file.", true);
      }
    });
    const cap = document.createElement("figcaption");
    cap.textContent = image.original_name;
    cap.title = image.original_name;
    fig.append(button, cap);
    grid.appendChild(fig);
  }

  card.append(head, hint, grid);
  overlay.appendChild(card);
  document.body.appendChild(overlay);
  close.focus();
}

// Thumbnails need the auth header, which <img src> can't send: fetch
// the bytes once per attachment and cache an object URL (Wave M).
const thumbUrlCache = new Map();

async function attachmentObjectUrl(attachment) {
  if (thumbUrlCache.has(attachment.id)) return thumbUrlCache.get(attachment.id);
  const response = await api(`/files/${attachment.id}`);
  const url = URL.createObjectURL(await response.blob());
  thumbUrlCache.set(attachment.id, url);
  return url;
}

// Full-size image viewer: click anywhere or press Esc to close (Wave M).
// `items` is every image this click can page through, e.g. all the image
// attachments on the same note, as `{filename, getUrl}`, `getUrl` being a
// (possibly async) thunk so unopened images aren't fetched until reached.
// `startIndex` is which one was clicked; a single image is just a one-item
// list. Reported directly: click-anywhere-to-close alone isn't discoverable,
// so there's now an explicit close button too, both still work.
//: `opts.focusReading` opens the dialog *at the reading* rather than at the
//: top of the file, Phase 7.5's "an 'Open reading' action that opens the
//: lightbox at the reading". On a tall document the info panel is below the
//: fold, so a plain open lands the reader on a page and leaves them to find
//: the text they asked for.
function openLightbox(items, startIndex = 0, opts = {}) {
  let index = startIndex;
  const overlay = document.createElement("div");
  overlay.className = "lightbox";
  // Not decoration: this is what puts the lightbox inside `activeOverlay()`'s
  // reach (see its comment), and it is what a screen reader needs to announce
  // the thing as a dialog rather than as a stray region.
  overlay.setAttribute("role", "dialog");
  overlay.setAttribute("aria-modal", "true");
  overlay.setAttribute("aria-label", "Image viewer");
  overlay.setAttribute("role", "dialog");
  overlay.setAttribute("aria-label", "Image preview");

  const closeBtn = document.createElement("button");
  closeBtn.type = "button";
  closeBtn.className = "lightbox-close";
  closeBtn.setAttribute("aria-label", "Close");
  // A raw "×" character, not an icon-font glyph, reported live as still
  // off-centre even inside the `display:grid;place-items:center` box that
  // fixed every *padding*-driven case of this: `place-items` centres the
  // line box, not necessarily where a font renders that specific character's
  // ink within it, and that varies by system font. Every other close button
  // in the app already uses the ph:x icon glyph for exactly this reason, 
  // matching it here fixes the centring and the inconsistency together.
  setLabel(closeBtn, "ph:x");

  const img = document.createElement("img");
  const broken = document.createElement("p");
  broken.className = "lightbox-broken hidden";
  const meta = document.createElement("div");
  meta.className = "lightbox-meta";

  // What the app knows *about* the picture, shown with the picture. Asked for
  // directly: "if clicking on an image to view expand it in the lightbox…can
  // the captions and ocr accompany it somehow??", before this, the caption a
  // vision model wrote and the text it read off the page existed only on the
  // Library tile, which is the one view too small to read them in. Optional
  // per item (`caption`, `text`, and their bylines): every other caller
  // passes only `{filename, getUrl}` and gets exactly what it got before.
  // Mirrors `syncCaptionBadge` on the Library tile (library.js) exactly, so
  // the same picture says the same thing in both places: which model wrote
  // the description, and whether a person has since changed it.
  const captionBylineFor = (row) => {
    if (!row || !row.caption) return "";
    const parts = [];
    if (row.caption_model) parts.push(`Described by ${row.caption_model}`);
    if (row.caption_edited) parts.push(row.caption_model ? "edited" : "typed by hand");
    return parts.join(" · ");
  };

  const info = document.createElement("div");
  info.className = "lightbox-info hidden";
  const infoCaption = document.createElement("p");
  infoCaption.className = "lightbox-caption";
  // Who wrote the caption. Reported directly: "there is also no 'text read
  // by' line in the lightbox for the image captions, only the ocr", the
  // Library tile has carried a caption byline (`captionBadge`, library.js)
  // since captions could be edited by hand, and only the lightbox was
  // missing its half, so the same picture named its transcriber but not its
  // describer.
  const infoCaptionByline = document.createElement("p");
  infoCaptionByline.className = "lightbox-byline";
  const infoText = document.createElement("p");
  infoText.className = "lightbox-text";
  const infoByline = document.createElement("p");
  infoByline.className = "lightbox-byline";
  // Dimensions, when it was added, the filename, the "other info about it"
  // half of the request. First, because it is the line that says *which*
  // picture this is; the readings below it are about what is in it.
  const infoFacts = document.createElement("p");
  infoFacts.className = "lightbox-facts";
  //: **What only a document has** (UI_MODERNISATION_PLAN Phase 7.1). Reported:
  //: "the lightbox needs improving for file and pdf previews, no sections or
  //: info are below it really compared to the images." An image already got
  //: facts, caption, reading and bylines under it; a PDF got the pages and
  //: nothing else: and the three things a *document* can say that a
  //: photograph cannot (how many pages it has, which of them have been read,
  //: and which one you are looking at) had nowhere to be said.
  //:
  //: One row of `.chip`s, one per page, in the panel that already exists, 
  //: not a second info block. A chip is a page: it says whether that page has
  //: a stored reading, and clicking it scrolls the pages column to it, which
  //: is also what makes "open the reader at *this* page" a meaningful offer.
  const infoPages = document.createElement("div");
  infoPages.className = "row lightbox-pages hidden";
  info.append(infoFacts, infoPages, infoCaption, infoCaptionByline, infoText, infoByline);
  // Clicking the panel must not dismiss the dialog, someone selecting a line
  // of transcribed text to copy is the whole reason it is here.
  info.addEventListener("click", (e) => e.stopPropagation());

  const prevBtn = document.createElement("button");
  prevBtn.type = "button";
  prevBtn.className = "lightbox-nav lightbox-prev";
  prevBtn.setAttribute("aria-label", "Previous image");
  setLabel(prevBtn, "ph:caret-left");

  const nextBtn = document.createElement("button");
  nextBtn.type = "button";
  nextBtn.className = "lightbox-nav lightbox-next";
  nextBtn.setAttribute("aria-label", "Next image");
  setLabel(nextBtn, "ph:caret-right");

  // **The arrows are centred by the layout now, not by a measurement.**
  //
  // They used to be `position: fixed` at `top: 50%`, which is the viewport's
  // centre and not the image's; a previous fix measured the image's rendered
  // box on every `show()` and wrote a `top` back. That worked while the
  // lightbox was one centred stack, and stopped working the moment it grew a
  // scrollable info panel: reported with a screenshot of both arrows sitting
  // level with the top edge of the picture.
  //
  // The fix is structural: the image and the two arrows share a positioned
  // wrapper, so `top: 50%; translateY(-50%)` is the middle of the *image*, at
  // every size, at every scroll offset, with no JS and nothing to keep in
  // sync. `positionNav`, its `resize` listener and its two callers are gone.
  const stage = document.createElement("div");
  stage.className = "lightbox-stage";

  // **The actions bar.** Asked for directly: "improve on and expand the
  // capabilities and features at the bottom of the lightbox". Until now the
  // lightbox was purely an *information* surface, filename, dimensions,
  // caption, OCR text: with no action on it at all, which meant the one
  // place you are actually looking at a picture was the one place you could
  // not do anything to it.
  //
  // Everything here works from what `openLightbox` already receives, so it
  // lights up for **every** caller (notes, chat, graph, dashboard, library)
  // rather than only the Library's richer items. Actions that need a media
  // id, describe with AI, re-run OCR, rename, delete, are deliberately
  // not here: no caller passes one today, and inventing a half-working row
  // that only the Library populates is the "two buttons guaranteed to fail"
  // shape this project has already rejected once on the whiteboard menu.
  const actions = document.createElement("div");
  actions.className = "lightbox-actions";
  actions.addEventListener("click", (e) => e.stopPropagation());

  // Zoom is the gap that mattered most: a lightbox that cannot magnify is
  // just a bigger thumbnail, and the OCR panel below is often the only way
  // to read text in a picture precisely because you could not zoom into it.
  let zoom = 1;
  const ZOOM_MIN = 1;
  const ZOOM_MAX = 6;
  const zoomLabel = document.createElement("span");
  zoomLabel.className = "muted lightbox-zoom-label";
  // A single image is the usual target; a PDF shown as pages (pdfPages,
  // below) is a second one, added when PDFs stopped being AI-text-only, 
  // "or zoom. a lot of controls are missing," reported live once pages
  // started rendering. Same zoom state and the same three buttons drive
  // both; only which element the transform lands on, and which container's
  // scroll resets on "Fit", differ.
  const zoomTarget = () => (!pdfPages.classList.contains("hidden") ? pdfPages : img);
  const scrollTarget = () => (!pdfPages.classList.contains("hidden") ? doc : stage);
  const applyZoom = () => {
    const target = zoomTarget();
    target.style.transform = zoom === 1 ? "" : `scale(${zoom})`;
    // Set on the stage too, a multi-page column has no single element
    // whose own hover state would otherwise flip the grab cursor.
    target.classList.toggle("zoomed", zoom > 1);
    stage.classList.toggle("zoomed", zoom > 1);
    zoomLabel.textContent = `${Math.round(zoom * 100)}%`;
    // Only grab-able once there is something to pan to.
    if (zoom === 1) scrollTarget().scrollTo({ left: 0, top: 0 });
  };
  const setZoom = (next) => {
    zoom = Math.min(ZOOM_MAX, Math.max(ZOOM_MIN, Math.round(next * 100) / 100));
    applyZoom();
  };
  const actionBtn = (label, title, fn) => {
    const b = document.createElement("button");
    b.type = "button";
    b.className = "ghost small lightbox-action";
    b.title = title;
    setLabel(b, label);
    b.addEventListener("click", (e) => {
      e.stopPropagation();
      fn(b);
    });
    actions.appendChild(b);
    return b;
  };

  const zoomOutBtn = actionBtn("ph:magnifying-glass-minus", "Zoom out", () => setZoom(zoom - 0.5));
  actions.appendChild(zoomLabel);
  const zoomInBtn = actionBtn("ph:magnifying-glass-plus", "Zoom in", () => setZoom(zoom + 0.5));
  const resetBtn = actionBtn("ph:arrows-in Fit", "Back to fit", () => setZoom(1));

  //: **The page stepper**: Phase 7.1's "a way to say which page you are on".
  //:
  //: The pages column already scrolls, and scrolling is the right way to read
  //: a document; what it could not do is *name* the page under your eye, which
  //: is the one fact everything else here hangs off, the read/unread chip that
  //: is current, and which page "open the reader here" opens. So this is a
  //: readout with two buttons, not a pager that replaces scrolling: both
  //: directions still work and they stay in sync (the scroll listener wired in
  //: `wireDocPageTracking` below writes the label back).
  //:
  //: Built here rather than further down because `actionBtn` appends in
  //: creation order and "where you are" belongs beside the zoom controls,
  //: which are the other thing that answers "what am I looking at".
  let docPageCount = 0;
  let docPage = 0;
  const docPagesRead = new Set();
  //: page index -> `{text, model, caption, caption_model}`, from the same
  //: `page-reads` response the chips are built from. **Per page** is the whole
  //: point (Phase 7.3): one caption under a whole PDF describes none of its
  //: pages, and the joined reading of every page is not what you are looking
  //: at when page 4 is on screen.
  const docPageRows = new Map();
  const pagePrevBtn = actionBtn("ph:caret-left", "Previous page", () => setDocPage(docPage - 1));
  const pageLabel = document.createElement("span");
  pageLabel.className = "muted lightbox-page-label";
  //: `role="status"`, matching the OCR workspace's own page label: the page
  //: changes without focus moving, so a screen reader is otherwise never told.
  pageLabel.setAttribute("role", "status");
  actions.appendChild(pageLabel);
  const pageNextBtn = actionBtn("ph:caret-right", "Next page", () => setDocPage(docPage + 1));
  const pageControls = [pagePrevBtn, pageLabel, pageNextBtn];
  const showPageControls = (on) =>
    pageControls.forEach((el) => el.classList.toggle("hidden", !on));
  showPageControls(false);

  //: Whichever box actually scrolls the pages. In the plain document view that
  //: is `.lightbox-doc`; once the reading is showing beside the pages
  //: (`lightbox-doc-split`) the pages column becomes its own scroller. Asking
  //: the DOM rather than tracking the mode: the split is toggled in three
  //: places and a fourth would silently scroll the wrong box.
  const pageScroller = () =>
    pdfPages.scrollHeight > pdfPages.clientHeight + 1 ? pdfPages : doc;

  function syncPageChips() {
    for (const chip of infoPages.querySelectorAll(".lightbox-page-chip")) {
      chip.classList.toggle("is-current", Number(chip.dataset.page) === docPage);
      chip.setAttribute("aria-current", Number(chip.dataset.page) === docPage ? "true" : "false");
    }
    pageLabel.textContent = docPageCount ? `Page ${docPage + 1} of ${docPageCount}` : "";
    pagePrevBtn.disabled = docPage <= 0;
    pageNextBtn.disabled = docPage >= docPageCount - 1;
    //: The panel below is about *this* page, its reading, its figures, so
    //: it is redrawn with the number, not only when the file changes.
    if (lightboxInfoItem) renderInfo(lightboxInfoItem, true);
    //: The workspace button opens at the page named here, so it has to say so
    //:, a button whose behaviour depends on invisible state is the affordance
    //: problem this app keeps fixing elsewhere.
    readWithAiBtn.title = docPageCount
      ? `Open the page reader at page ${docPage + 1}: the page beside what it says`
      : "Open the page reader: see each page beside what it says";
  }

  //: Set the current page *and* scroll to it. `setDocPage` is the user asking
  //: for a page; `noteDocPage` (below) is the scroll position telling us which
  //: one arrived: they must not call each other, or a scroll would fight the
  //: scroll it triggered.
  function setDocPage(next) {
    if (!docPageCount) return;
    docPage = Math.max(0, Math.min(docPageCount - 1, next));
    const target = pdfPages.children[docPage];
    if (target) {
      const scroller = pageScroller();
      //: Rects rather than `offsetTop`: `offsetTop` is measured against the
      //: nearest *positioned* ancestor, which is not the scroller in either
      //: of the two layouts this has to work in.
      scroller.scrollTop += target.getBoundingClientRect().top
        - scroller.getBoundingClientRect().top;
    }
    syncPageChips();
  }

  //: One chip per page, marked with whether that page has a stored reading.
  //: This is Phase 7.1's "which pages have been read", and it is deliberately
  //: the same `.chip` recipe the rest of the app uses rather than a bespoke
  //: badge: a page is a thing you can pick, which is what a chip is for.
  function renderDocPages() {
    infoPages.replaceChildren();
    infoPages.classList.toggle("hidden", docPageCount < 1);
    if (docPageCount < 1) return;
    const lead = document.createElement("span");
    lead.className = "muted text-sm lightbox-pages-lead";
    lead.textContent = docPagesRead.size
      ? `${docPagesRead.size} of ${docPageCount} pages read`
      : `${docPageCount} page${docPageCount === 1 ? "" : "s"} · none read yet`;
    infoPages.appendChild(lead);
    for (let i = 0; i < docPageCount; i++) {
      const chip = document.createElement("button");
      chip.type = "button";
      chip.className = "chip chip-interactive lightbox-page-chip";
      chip.classList.toggle("is-read", docPagesRead.has(i));
      chip.dataset.page = String(i);
      chip.textContent = String(i + 1);
      //: The number alone is not a label, "3" tells a screen reader nothing
      //: about what it is or what pressing it does.
      chip.setAttribute(
        "aria-label",
        docPagesRead.has(i) ? `Page ${i + 1}, already read` : `Page ${i + 1}, not read yet`
      );
      chip.title = chip.getAttribute("aria-label");
      chip.addEventListener("click", (e) => {
        e.stopPropagation();
        setDocPage(i);
      });
      infoPages.appendChild(chip);
    }
    syncPageChips();
  }

  //: Back to "this is not a document", called wherever the lightbox changes
  //: what it is showing, so a photograph never inherits the previous file's
  //: page count and a stale stepper never offers page 7 of an image.
  function resetDocPages() {
    docPageCount = 0;
    docPage = 0;
    docPagesRead.clear();
    docPageRows.clear();
    showPageControls(false);
    infoPages.replaceChildren();
    infoPages.classList.add("hidden");
  }

  //: Which pages already have a stored reading (`PageRead`, see the model's
  //: own docstring). Best-effort and never throws: the pages themselves render
  //: with no AI in the loop at all, and this panel must not be the thing that
  //: makes a document unviewable when the store cannot answer.
  async function loadDocPageReads(attachmentId, name, item) {
    let base = attachmentId ? `/files/${attachmentId}` : "";
    if (!base) {
      //: A `/media/` upload is addressed by *id* here and by *stored name*
      //: everywhere else in this function. The Library gallery is the one
      //: caller that already holds the id; every other one has a url, so the
      //: id is looked up the same way `hydrate` looks up the rest of the
      //: metadata rather than leaving the panel empty for eight of nine
      //: callers.
      let id = item.id;
      if (!id && name) {
        const row = await apiJson(`/media/meta/${encodeURIComponent(name)}`).catch(() => null);
        id = row?.id;
      }
      if (!id) return;
      //: Now that the id is known the workspace can be addressed too, the
      //: same button previously fell back to the flat inline reading for
      //: exactly this case.
      if (!lightboxOcrTarget) {
        lightboxOcrTarget = {
          id,
          _isAttachment: false,
          original_name: item.filename || name,
          //: See the note beside the other place this target is built: the
          //: page images are addressed by stored name, so leaving `url` off
          //: opens the workspace on a stage that 404s.
          url: `/media/${name}`,
        };
      }
      base = `/media/${id}`;
    }
    const body = await apiJson(`${base}/page-reads`).catch(() => null);
    for (const page of body?.pages || []) {
      const index = Number(page.page) || 0;
      if ((page.text || "").trim()) docPagesRead.add(index);
      docPageRows.set(index, {
        text: (page.text || "").trim(),
        model: page.model || "",
        caption: (page.caption || "").trim(),
        caption_model: page.caption_model || "",
      });
    }
    renderDocPages();
    //: The facts line carries the same count, so it has to be redrawn with the
    //: chips or the panel says "none read yet" above a row of read pages.
    renderInfo(item, true);
  }

  function noteDocPage() {
    if (!docPageCount) return;
    const scroller = pageScroller();
    const top = scroller.getBoundingClientRect().top;
    let nearest = 0;
    let best = Infinity;
    for (let i = 0; i < pdfPages.children.length; i++) {
      //: The page whose top edge is closest to the top of the viewport, from
      //: either side: a page scrolled half off the top is still the page you
      //: are reading, so `Math.abs` rather than "the first one still below".
      const distance = Math.abs(pdfPages.children[i].getBoundingClientRect().top - top);
      if (distance < best) {
        best = distance;
        nearest = i;
      }
    }
    if (nearest === docPage) return;
    docPage = nearest;
    syncPageChips();
  }
  //: **"Open this in the editor", from the preview.** Asked for directly: "add
  //: an edit document button to previewed documents in the lightbox." The
  //: Library's own kebab offers Preview *and* Open, but once you are in the
  //: preview and have decided you want to change something, the only route
  //: back was to close the lightbox, find the row again and pick the other
  //: menu item: three steps to answer a question the preview itself raised.
  //:
  //: Only for a *document*: the lightbox also shows attachments and uploaded
  //: files, which have their own in-place edit (`editFileBtn`) and no row in
  //: the Documents tab to open. `item.documentId` is what says which is which,
  //: set by the one caller that previews a document.
  const openDocBtn = actionBtn("ph:pencil-simple Edit document", "Open this in the document editor", () => {
    const target = items[index];
    if (!target || !target.documentId) return;
    close();
    switchTab("documents");
    openDocument(target.documentId);
  });
  openDocBtn.classList.add("hidden");
  // Zoom is an image control. A document scrolls and reflows instead, so
  // showing a disabled-in-spirit 100% beside a page of text is three
  // controls that do nothing, the same "only show what this can do"
  // reasoning the whiteboard context menu already settled.
  const zoomControls = [zoomOutBtn, zoomLabel, zoomInBtn, resetBtn];
  const showZoomControls = (on) =>
    zoomControls.forEach((el) => el.classList.toggle("hidden", !on));

  // Wheel-to-zoom, because that is what every image viewer does and a person
  // who has zoomed once will try it. Non-passive so the page behind cannot
  // scroll out from under the picture mid-zoom.
  //
  // **Only while an image is actually showing.** Reported live, from a real
  // multi-page PDF: "it crashed when I tried to view a pdf and i couldnt
  // scroll." Not a crash: `stage` is the shared container for both the
  // picture view and `.lightbox-doc` (text, and now PDF pages), and this
  // handler used to call `preventDefault()` on every wheel event over it
  // unconditionally, regardless of which one was showing. Over a scrolling
  // multi-page PDF that blocked the browser's own scroll on every tick
  // while doing nothing visible in return, `setZoom` only ever touches the
  // single `<img>` element's transform, which isn't part of the document
  // view at all. `doc.classList.contains("hidden")` is the same check
  // `show()` already uses to know which of the two is current.
  stage.addEventListener(
    "wheel",
    (e) => {
      // A browser reports a trackpad pinch gesture as a wheel event with
      // ctrlKey set: the same convention Chrome/Firefox use for
      // Maps/Docs/Figma-style pinch-to-zoom: so it still reaches zoom even
      // while the document view owns plain scroll below. Plain wheel/two-
      // finger scroll over a document (not pinch) is left alone entirely.
      if (!doc.classList.contains("hidden") && !e.ctrlKey) return;
      if (!doc.classList.contains("hidden") && pdfPages.classList.contains("hidden")) return; // plain text: nothing to zoom
      e.preventDefault();
      setZoom(zoom + (e.deltaY < 0 ? 0.25 : -0.25));
    },
    { passive: false }
  );

  // Drag to pan, once zoomed. The scrollbars already pan the stage, but a
  // magnified picture with `cursor: grab` on it that does not actually drag
  // is an affordance telling a lie, every image viewer drags here.
  //
  // Bound to both `img` and `pdfPages`, panning whichever container
  // `scrollTarget()` says actually scrolls (`stage` for the image, `doc`
  // for PDF pages): reported live: "when zooming in on docs or images etc
  // in the lightbox, i cant drag to adjust the zoom position." This only
  // ever panned `stage.scroll{Left,Top}` via listeners on `img` alone, the
  // same single-target gap `zoomTarget()`/`scrollTarget()` above already
  // exist to close for zoom and Fit; drag never got the same treatment when
  // PDF pages gained their own zoomable, independently-scrolling view.
  let panning = null;
  const startPan = (el) => (e) => {
    if (zoom === 1) return;
    e.preventDefault();
    const scroller = scrollTarget();
    panning = { x: e.clientX, y: e.clientY, left: scroller.scrollLeft, top: scroller.scrollTop };
    el.setPointerCapture(e.pointerId);
    el.style.cursor = "grabbing";
  };
  const movePan = (e) => {
    if (!panning) return;
    const scroller = scrollTarget();
    scroller.scrollLeft = panning.left - (e.clientX - panning.x);
    scroller.scrollTop = panning.top - (e.clientY - panning.y);
  };
  const endPan = (el) => (e) => {
    if (!panning) return;
    panning = null;
    el.style.cursor = "";
    if (e.pointerId !== undefined && el.hasPointerCapture(e.pointerId)) {
      el.releasePointerCapture(e.pointerId);
    }
  };
  // A drag that ends on the picture must not also read as a click on the
  // backdrop, which closes the dialog, panning to the edge of a picture
  // and having the whole thing vanish is the bug this prevents.
  //
  // `pdfPages` doesn't exist yet at this point in `openLightbox` (it's
  // built further down, alongside the rest of the document view), wiring
  // it up here throws a temporal-dead-zone ReferenceError the instant the
  // lightbox opens. `bindPan`, called once `pdfPages` is actually in scope.
  const bindPan = (el) => {
    el.addEventListener("pointerdown", startPan(el));
    el.addEventListener("pointermove", movePan);
    el.addEventListener("pointerup", endPan(el));
    el.addEventListener("pointercancel", endPan(el));
    el.addEventListener("click", (e) => e.stopPropagation());
  };
  bindPan(img);

  // Copy the text the app read out of the picture. Hidden unless this item
  // actually has some: an enabled button that copies "" is a lie.
  // Goes through the app's own `copyToClipboard` helper rather than the raw
  // browser clipboard call: caught by
  // test_every_copy_path_goes_through_the_fallback (whose naive string scan
  // would otherwise flag even *this comment* if it spelled the call out
  // literally, which is why it doesn't). The helper already covers what a
  // hand-rolled version here did not: a non-secure context, permission
  // refused, and a last-resort "here's the text, already selected" UI when
  // both fail, instead of this button just going silent.
  //: What the info panel is currently showing, which for a document is *one
  //: page's* reading rather than the file's joined one (see `renderInfo`).
  //: Copy has to hand over what is on screen: copying every page while the
  //: panel shows page 4 is the app disagreeing with itself about "this text".
  let lightboxShownText = "";
  const copyBtn = actionBtn("ph:copy Copy text", "Copy the text read from this image", async (b) => {
    const value = (lightboxShownText || items[index].text || "").trim();
    if (!value) return;
    await copyToClipboard(value, b);
  });

  // Save the original file. `download` needs a same-origin href to name the
  // file, which `mediaSrc()` gives us: it is this app's own /media route.
  actionBtn("ph:download-simple Save", "Save this file to your computer", async () => {
    try {
      const current = items[index];
      const href = await current.getUrl();
      const a = document.createElement("a");
      a.href = href;
      // **A document leaves `download` unset, an image sets it.** A
      // non-empty `download` attribute wins over the server's own
      // `Content-Disposition: filename="..."`, for
      // `/documents/{id}/export.md`, that header already carries the
      // right extension for the file's actual type (`.py`, `.json`,
      // `.md`, whatever `filetypes.get` picked), computed server-side.
      // Setting `download` to a bare title here would have downloaded a
      // "Quarterly Report" with no extension at all, silently discarding
      // that work: an image has no such header to defer to, so it keeps
      // naming itself.
      if (!current.kind) a.download = current.filename || "image";
      document.body.appendChild(a);
      a.click();
      a.remove();
    } catch {
      toast("Couldn't save that file.", true);
    }
  });

  // Only shown while a PDF is displayed as pages (see showDocument): swaps
  // to the AI-extracted-text view on demand, rather than automatically. A
  // PDF's *pages* render with zero AI involvement; reading its words with a
  // model is a deliberate, opt-in second step, not something a user has to
  // sit through just to look at their own document.
  //: **Which PDF the OCR workspace should open, or null.** Set by
  //: `showDocument`'s PDF branch, where the file's identity is actually
  //: known; cleared wherever the lightbox resets for a new file.
  let lightboxOcrTarget = null;

  const readWithAiBtn = actionBtn("ph:sparkle Read text with AI", "Open the page reader: see each page beside what it says", () => {
    //: **One reader, not two.** Reported: *"that panel is separate from the
    //: lightbox where you can select to read the text on the document, and I
    //: feel like that button should show the other text on page panel
    //: popup."* This button used to swap the lightbox to a flat blob of
    //: extracted text, while the OCR workspace, page rail, region boxes,
    //: per-page and now per-range reads, copy, save as note, was a separate
    //: window reachable only from a file card's menu. Two answers to "what
    //: does this document say", and the worse one was on the file you were
    //: looking at.
    //:
    //: Falls back to the old inline text when the workspace cannot be
    //: addressed (no id resolved, or library.js absent on this surface):
    //: degrading to the flat reading beats a button that does nothing.
    //: **At the page you are looking at, not at page 1.** Phase 7.1 asked for
    //: "a way into the OCR Workspace at that page", and the third argument is
    //: it: a fifteen-page scan opened at its first page from page nine is a
    //: navigation the reader has to redo by hand, every time.
    if (lightboxOcrTarget && typeof window.openOcrWorkspace === "function") {
      //: **The lightbox goes before the workspace arrives.** Reported: *"when
      //: I open a pdf file in the lightbox and press the read text with ai, it
      //: opens the ocr workspace but behind the lightbox so the lightbox needs
      //: to close when the workspace opens."* Measured: `.lightbox` is
      //: `z-index: 1020` (raised there to clear the CSS full-screen graph, see
      //: its own comment) and the workspace is a `.modal-overlay` at 1010, so
      //: the workspace really did open underneath and every click landed on
      //: the lightbox's zoom-out backdrop instead. The fix is the one the
      //: gallery kebab's "See text on the page" row already uses ten lines
      //: down, `close()` first: two stacked overlays leave the page behind
      //: unreachable whichever of them wins the stacking contest, so raising
      //: the workspace above the lightbox would answer the z-index and not the
      //: report. The target and the page are read into locals before the
      //: dismiss because `close()` empties the lightbox's own state.
      const target = lightboxOcrTarget;
      const atPage = docPageCount ? docPage : 0;
      close();
      window.openOcrWorkspace(target, [], atPage);
      return;
    }
    lightboxLoadExtractedText?.();
  });
  readWithAiBtn.classList.add("hidden");

  //: **Edit / Save / Cancel for a text file**, §R7.1 item 2. Set by
  //: `showDocument` for whichever file is open; null while the lightbox is
  //: showing a picture or a PDF's pages, which is what keeps these three
  //: buttons from acting on the file that happened to be open before.
  let lightboxEditTarget = null;

  function setLightboxEditing(on) {
    docEdit.classList.toggle("hidden", !on);
    docBody.classList.toggle("hidden", on);
    //: Find-in-document searches the *rendered* body, so it has nothing to
    //: work on while the source is showing, and leaving it up would offer a
    //: search that silently matches nothing.
    find.classList.toggle("hidden", on);
    findCount.classList.add("hidden");
    editFileBtn.classList.toggle("hidden", on);
    saveFileBtn.classList.toggle("hidden", !on);
    cancelEditBtn.classList.toggle("hidden", !on);
    //: Export hands back what was *saved*; while a draft is open in the box
    //: the two disagree, and a file exported mid-edit would silently be the
    //: version before the changes on screen.
    if (on) exportTextBtn.classList.add("hidden");
    else if (lightboxExtractedText) exportTextBtn.classList.remove("hidden");
    if (on) docEdit.focus();
  }

  const editFileBtn = actionBtn("ph:pencil-simple Edit", "Edit this file's text", () => {
    if (!lightboxEditTarget) return;
    docEdit.value = lightboxEditTarget.text;
    setLightboxEditing(true);
  });
  editFileBtn.classList.add("hidden");

  const saveFileBtn = actionBtn("ph:check Save changes", "Save this text back over the file", async (button) => {
    if (!lightboxEditTarget) return;
    button.disabled = true;
    try {
      const saved = await apiJson(lightboxEditTarget.url, {
        method: "PUT",
        body: JSON.stringify({ text: docEdit.value }),
      });
      //: Re-rendered from what the server wrote back, not from what was
      //: typed. They are the same today; if they ever differ, a normalised
      //: line ending, a file the OS rewrote, the reader should be looking at
      //: the file, not at the draft of it.
      lightboxEditTarget.text = saved.text || "";
      setLightboxEditing(false);
      lightboxLoadExtractedText?.();
      toast("Saved.");
    } catch (error) {
      //: A 409 is the server declining to overwrite (`docview.editability`),
      //: and its `detail` is written to be read by a person, so it is shown
      //: rather than replaced with a generic failure.
      toast(error.message || "Couldn't save that file.", true);
    } finally {
      button.disabled = false;
    }
  });
  saveFileBtn.classList.add("hidden");

  const cancelEditBtn = actionBtn("ph:x Cancel", "Discard these changes", () => {
    setLightboxEditing(false);
  });
  cancelEditBtn.classList.add("hidden");

  //: **Exporting the *text*, which is a different thing from Save** (§R7.1
  //: item 5, "export, per-format, from the same place the file is viewed").
  //: Save hands back the file as it is on disk, the .pdf, the .docx. This
  //: hands back what the viewer is showing, which for a scanned PDF or a Word
  //: file is the only readable form of it the app has, and until now could be
  //: reached only by selecting the whole pane and copying.
  //:
  //: The extension follows `kind`, not the source file's: markdown text saved
  //: as `report.pdf.md` is honest about being neither a PDF nor a plain
  //: transcript, and opens in the right thing.
  let lightboxExtractedText = null;
  const exportTextBtn = actionBtn("ph:export Export text", "Save the extracted text as a file", async (button) => {
    if (!lightboxExtractedText) return;
    button.disabled = true;
    try {
      const { name, kind, text } = lightboxExtractedText;
      const stem = (name || "document").replace(/\.[^./\\]+$/, "") || "document";
      const extension = kind === "markdown" ? "md" : "txt";
      await saveFile(`${stem}.${extension}`, new Blob([text], { type: "text/plain" }));
    } catch (error) {
      toast(error.message || "Couldn't export that text.", true);
    } finally {
      button.disabled = false;
    }
  });
  exportTextBtn.classList.add("hidden");

  //: Whether the preview frame is currently showing something.
  let docPreviewOn = false;

  function clearDocPreview() {
    docPreviewOn = false;
    docFrame.classList.add("hidden");
    //: `about:blank` rather than leaving the last file loaded: an iframe that
    //: still holds a document keeps rendering it, and paging to the next file
    //: would show the previous one's page for as long as the new fetch takes.
    docFrame.src = "about:blank";
    previewHtmlBtn.setAttribute("aria-pressed", "false");
    setLabel(previewHtmlBtn, "ph:browser Preview");
  }

  const previewHtmlBtn = actionBtn("ph:browser Preview", "Render this HTML file (scripts are not run)", () => {
    if (docPreviewOn) {
      clearDocPreview();
      docBody.classList.remove("hidden");
      find.classList.remove("hidden");
      return;
    }
    if (!lightboxPreviewSource) return;
    //: **A server URL, not a `blob:` from the text we already have.** The
    //: first version did the obvious thing and built a Blob, and a `blob:`
    //: document inherits its creator's CSP, so this app's `style-src 'self'`
    //: applied to the framed page and refused the page's *own* `<style>`
    //: block. Measured: "Refused to apply inline style", and a page setting
    //: `background:#eef` rendered transparent. `/files/{id}/html-preview`
    //: carries its own policy (`HTML_PREVIEW_CSP`, routes_files.py): 
    //: sandboxed, scriptless, and allowed to style itself.
    docFrame.src = mediaSrc(lightboxPreviewSource);
    docPreviewOn = true;
    docFrame.classList.remove("hidden");
    docBody.classList.add("hidden");
    //: Find-in-document reads the rendered *source* listing; the frame is a
    //: separate document this page deliberately cannot reach into.
    find.classList.add("hidden");
    findCount.classList.add("hidden");
    previewHtmlBtn.setAttribute("aria-pressed", "true");
    setLabel(previewHtmlBtn, "ph:code Show source");
  });
  previewHtmlBtn.classList.add("hidden");
  previewHtmlBtn.setAttribute("aria-pressed", "false");

  //: The URL the preview frame would load, set by `showDocument` only for a
  //: file that is actually HTML *and* is a real attachment (a `/media/`
  //: upload is never HTML, `MEDIA_SUFFIXES` is images and PDF, and a native
  //: document has no file behind it at all). Null the rest of the time, which
  //: is what keeps the button from framing the file viewed before this one.
  let lightboxPreviewSource = null;

  // **The AI/manage actions: gated on a media id, and only ever visible
  // when one is present.** Reported directly, and left open on purpose the
  // first time this bar was built: rename, describe with AI, read text (two
  // ways) and delete all need a real `MediaUpload` row, and of nine
  // `openLightbox` callers only the Library's own gallery has one to pass.
  // Every other caller (a note attachment, a chat image, a graph or
  // dashboard thumbnail, a whiteboard object) opens the lightbox from a bare
  // url, and a menu that 404s on click is worse than no menu, the same "two
  // buttons guaranteed to fail" shape this project already rejected once on
  // the whiteboard's own context menu.
  //
  // Reuses the endpoints and request shapes the gallery kebab already
  // established (library.js) rather than inventing a second idea of what
  // "describe with AI" does.
  let moreMenu = null;
  const buildMoreMenu = (item) => {
    //: **The job outlives the window that started it.**
    //:
    //: Reported: "if i close the lightbox as I am generating ocr, then it
    //: stops and I have to restart it again." The request never actually
    //: stopped: a `POST` keeps going and writes its result to the database
    //: whatever the browser does next, but every trace of it was inside the
    //: lightbox, so closing that window meant the work became invisible and
    //: then, on reopening, appeared not to have happened.
    //:
    //: Three changes make it true as well as visible: a progress toast that
    //: lives outside the lightbox, a re-render that is guarded rather than
    //: assumed (the panel may be gone by now, and writing to it threw), and a
    //: Library refresh so the gallery behind shows the new text either way.
    const run = (label, busyText, endpoint, applyTo) => async () => {
      const name = item.original_name || "this file";
      const progress = toastProgress(`${busyText} ${name}`);
      try {
        //: Registered with the OCR workspace's own in-flight map, so a read
        //: started here is still findable after this window closes, reported:
        //: "I close the lightbox, the ocr workspace is gone… it should be
        //: openable if an active ocr reading is going on."
        const updated = await (window.trackOcrRead || ((_i, _l, p) => p))(
          item,
          `${busyText} ${name}`,
          //: `force: true`, always. Reported: "the image captioning and ocr didnt
          //: work when I didnt like the output, deleted what was there and
          //: tried to do it again." A click on Describe / Read *is* the
          //: request to do it again, the server's "keep what exists" guard is
          //: for the automatic pass on upload, not for a person pressing the
          //: button a second time.
          apiJson(`/media/${item.id}${endpoint}`, { method: "POST", body: JSON.stringify({ force: true }) })
        );
        applyTo(item, updated);
        //: Only if this lightbox is still the one on screen. `renderInfo`
        //: writes into elements this closure captured, and they are detached
        //: once the overlay closes.
        if (overlay.isConnected && !overlay.classList.contains("hidden")) renderInfo(item, true);
        if (typeof loadLibrary === "function") loadLibrary();
        progress.done(`Finished reading ${name}.`, {
          actionLabel: "Show it",
          onAction: () => {
            switchTab("library");
            if (typeof renderLibrary === "function") renderLibrary();
          },
        });
      } catch (err) {
        progress.done(err.message || `Couldn't ${label.toLowerCase()}.`, { isError: true });
      }
    };
    const items = [
      {
        label: "ph:sparkle Describe with AI",
        title: "Generate a caption for this image",
        run: run("describe", "Describing…", "/caption", (it, u) => {
          it.caption = u.caption || "";
          it.captionByline = captionBylineFor(u);
        }),
      },
      {
        label: "ph:text-aa Read text with AI",
        title: "Read the text in this image with a vision model",
        run: run("read text", "Reading…", "/vision-ocr", (it, u) => {
          it.text = (u.vision_ocr_text || "").trim();
          it.byline = it.text ? `Text read by ${u.vision_ocr_model || "a model"}` : "";
        }),
      },
    ];
    // "the whole application is offline anyway with local models so that
    // title is confusing" (reported directly): renamed to name the actual
    // method (Tesseract) instead of a property ("offline") every reading
    // path in this app already shares. And: "the option should be disabled
    // or hidden if the user doesn't have pytesseract installed", `/models/
    // status`'s `tesseract_available` (routes_models.py) is a plain
    // `shutil.which` check, so this can just not offer a button that would
    // otherwise silently do nothing, matching how the model-pull panel
    // already hides itself on a backend that can't pull.
    //: And now it is *left out* rather than shown greyed, which is the
    //: second half of the same report: "make sure all the fila and document
    //: ocr worfs with ai ocr models, I dont use tesseract." A disabled row
    //: that can never become enabled (this app never installs the binary, by
    //: instruction) is a permanent piece of dead chrome in a menu that opens
    //: on every image: and it sat directly under the row that does the same
    //: job with a model, which is the one the reader wants. INSTALL.md still
    //: documents the offline reader for anyone who wants it.
    if (!modelStatus || modelStatus.tesseract_available !== false) {
      items.push({
        label: "ph:scan Read text (Tesseract OCR)",
        title: "Read the text in this image with Tesseract, a fast local tool, no AI model involved",
        run: run("read text", "Reading…", "/ocr", (it, u) => {
          it.text = (u.ocr_text || "").trim();
          it.byline = it.text ? "Text read with Tesseract OCR" : "";
        }),
      });
    }
    //: The other door into the OCR workspace (library.js). The gallery's own
    //: kebab has it too, and this is the same act from the other surface: the
    //: lightbox is where you are *looking* at the page, which is exactly when
    //: "where did that line come from" gets asked. Gated on a media id like
    //: every other row here, and on the row being an image the extractor can
    //: open: a menu row guaranteed to 415 is worse than a shorter menu.
    //: PDFs included since the workspace learned to rasterise a page
    //: (`_pdf_regions_for`, routes_files.py): reported as *"is the document
    //: ocr even working??"*, and it was not: this gate is what kept every
    //: document out of the one window built to read documents.
    if (/\.(png|jpe?g|gif|webp|bmp|pdf)$/i.test(item.filename || "")) {
      items.push({
        label: "ph:selection-all See text on the page",
        title: "Open this file beside the text read from it, page by page",
        run: async () => {
          //: `close` is this lightbox's own dismiss (defined further down in
          //: `openLightbox`, hoisted and initialised long before any menu row
          //: can run). The workspace is a modal too, and two stacked overlays
          //: leave the page behind unreachable.
          close();
          //: `_src`, not `url`: the lightbox item already carries a *tokened*
          //: src (`getUrl` runs it through `mediaSrc`), and letting the
          //: workspace token it a second time appends a second `?token=`.
          window.openOcrWorkspace?.(
            {
              id: item.id,
              _src: item.getUrl ? item.getUrl() : "",
              original_name: item.filename,
              _isImage: !/\.pdf$/i.test(item.filename || ""),
            },
            [],
          );
        },
      });
    }
    return kebabMenu(
      [
        ...items,
        {
          label: "ph:pencil-simple Rename",
          title: "Rename this image",
          run: async () => {
            const next = window.prompt("New name", item.filename || "");
            if (!next || !next.trim() || next === item.filename) return;
            try {
              const updated = await apiJson(`/media/${item.id}`, {
                method: "PUT",
                body: JSON.stringify({ original_name: next.trim() }),
              });
              item.filename = updated.original_name;
              renderInfo(item, true);
            } catch (err) {
              toast(err.message || "Couldn't rename that image.", true);
            }
          },
        },
        {
          label: "ph:trash Delete",
          title: "Delete this image",
          run: async () => {
            if (!(await confirmDialog(`Delete "${item.filename || "this image"}"?`))) return;
            try {
              await apiJson(`/media/${item.id}`, { method: "DELETE" });
              items.splice(index, 1);
              if (!items.length) {
                close();
                return;
              }
              show(index);
            } catch (err) {
              toast(err.message || "Couldn't delete that image.", true);
            }
          },
        },
      ],
      "More actions for this image"
    );
  };
  const syncMoreMenu = (item) => {
    moreMenu?.remove();
    // `!item.kind` matters here, not just belt-and-braces: a native
    // document preview item (below) also carries `item.id`, but that id
    // names a *document*, not a media upload, feeding it to
    // `/media/{id}/caption` or `/media/{id}` DELETE would act on whatever
    // media row happens to share that number, or 404. This menu is media-
    // actions only; `item.kind` is how a document identifies itself.
    moreMenu = item.id && !item.kind ? buildMoreMenu(item) : null;
    if (moreMenu) actions.appendChild(moreMenu);
  };


  // **The document half of the showcase.** Asked for directly: the lightbox
  // should be "a sort of document preview… for viewing pdfs, word documents,
  // spreadsheets, text files, code files etc but in a presentable way that
  // isn't editable".
  //
  // Read-only is not a shortcut here, `/media/text` returns *extracted*
  // text, so what is on screen has already stopped being a .docx and there
  // is nothing coherent to write back into. `core/docview.py`'s own module
  // docstring makes the same point.
  const doc = document.createElement("div");
  doc.className = "lightbox-doc hidden";
  const docBody = document.createElement("div");
  docBody.className = "lightbox-doc-body";
  const docNote = document.createElement("p");
  docNote.className = "muted lightbox-doc-note hidden";
  // A PDF's actual pages, rasterised server-side, direct instruction, after
  // the AI-extraction path alone left a scanned PDF stuck on "Reading…"
  // forever: "pdfs and documents should be viewable, accessible and
  // manageable without the ai, even if the ai cant read them." Plain
  // <img>s, one per page, in their own scrolling column so a PDF scrolls
  // like a PDF: no script, no PDF renderer, no AI in this path at all.
  const pdfPages = document.createElement("div");
  pdfPages.className = "lightbox-pdf-pages hidden";
  bindPan(pdfPages);
  //: Bound here rather than beside `noteDocPage` itself, and for the same
  //: reason `bindPan` exists: `doc` and `pdfPages` are created further down
  //: this function, so touching either from the block that defines the page
  //: stepper is a temporal-dead-zone ReferenceError the instant the lightbox
  //: opens. Bound once each, never rebound per document, a listener added on
  //: every `showDocument` is the unbounded accumulation
  //: `test_frontend_handlers.py` exists to catch.
  //:
  //: Both boxes, because which one scrolls depends on the layout (see
  //: `pageScroller`), and `noteDocPage` is a no-op when there are no pages.
  doc.addEventListener("scroll", noteDocPage, { passive: true });
  pdfPages.addEventListener("scroll", noteDocPage, { passive: true });
  //: **Editing a file in place** (REDESIGN.md §R7.1 item 2, and the request:
  //: *"all the files should be managable, viewable and editable in the
  //: library and document/file/text editor"*). A plain textarea over the
  //: file's own text, and only ever for the files where that text *is* the
  //: file: `docview.editability` decides, server-side, and the route
  //: re-checks rather than trusting the flag it sent.
  const docEdit = document.createElement("textarea");
  docEdit.className = "lightbox-doc-edit hidden";
  docEdit.spellcheck = false;
  docEdit.setAttribute("aria-label", "Edit this file's text");
  //: **The HTML preview pane** (§R7.1 item 4, from the odysseus comparison:
  //: *"viewing html and other code"*). An .html file is the one type where
  //: the source and the thing it describes are both worth looking at, and
  //: showing only the source is showing half the file.
  //:
  //: `sandbox` with **no** `allow-` tokens, and that is the whole security
  //: story: no scripts, no forms, no same-origin, no top-level navigation.
  //: The page renders as layout and can do nothing else, which is what makes
  //: it safe to point at a file nobody in this notebook wrote. `core/security`
  //: allows `frame-src blob:` for this; the sandbox is what bounds it.
  const docFrame = document.createElement("iframe");
  docFrame.className = "lightbox-doc-frame hidden";
  docFrame.setAttribute("sandbox", "");
  docFrame.setAttribute("title", "Preview of this HTML file");
  doc.append(docNote, docBody, docEdit, docFrame, pdfPages);
  doc.addEventListener("click", (e) => e.stopPropagation());
  stage.appendChild(doc);

  // Find within the document. Deliberately a filter over the rendered text
  // rather than the browser's own Ctrl+F: this panel scrolls inside a
  // dialog, and the native find has no idea the rest of the page is inert.
  const find = document.createElement("input");
  find.type = "search";
  find.className = "lightbox-find hidden";
  find.placeholder = "Find in document";
  find.setAttribute("aria-label", "Find in document");
  const findCount = document.createElement("span");
  findCount.className = "muted lightbox-find-count hidden";
  const clearFind = () => {
    find.value = "";
    findCount.textContent = "";
    docBody.querySelectorAll("mark.lightbox-hit").forEach((m) => {
      m.replaceWith(document.createTextNode(m.textContent));
    });
    docBody.normalize();
  };
  find.addEventListener("input", () => {
    // Unwrap previous hits before re-scanning, or each keystroke would
    // search text already split across <mark> boundaries.
    docBody.querySelectorAll("mark.lightbox-hit").forEach((m) => {
      m.replaceWith(document.createTextNode(m.textContent));
    });
    docBody.normalize();
    const needle = find.value.trim();
    if (!needle) {
      findCount.textContent = "";
      findCount.classList.add("hidden");
      return;
    }
    // Walk text nodes and wrap matches. Text-node surgery rather than an
    // innerHTML replace, which would corrupt the rendered markup and is the
    // classic way this feature introduces an injection bug.
    const lower = needle.toLowerCase();
    const walker = document.createTreeWalker(docBody, NodeFilter.SHOW_TEXT);
    const targets = [];
    let node;
    while ((node = walker.nextNode())) {
      if (node.nodeValue.toLowerCase().includes(lower)) targets.push(node);
    }
    let hits = 0;
    for (const textNode of targets) {
      const parts = textNode.nodeValue.split(new RegExp(`(${escapeForFind(needle)})`, "gi"));
      if (parts.length < 2) continue;
      const frag = document.createDocumentFragment();
      for (const part of parts) {
        if (part.toLowerCase() === lower) {
          const mark = document.createElement("mark");
          mark.className = "lightbox-hit";
          mark.textContent = part;
          frag.appendChild(mark);
          hits += 1;
        } else if (part) {
          frag.appendChild(document.createTextNode(part));
        }
      }
      textNode.replaceWith(frag);
    }
    findCount.textContent = hits ? `${hits} match${hits === 1 ? "" : "es"}` : "No matches";
    findCount.classList.remove("hidden");
    docBody.querySelector("mark.lightbox-hit")?.scrollIntoView({ block: "center" });
  });
  actions.append(find, findCount);

  // Which suffixes this viewer renders as a *picture*. Everything else that
  // reaches the lightbox is offered to the document reader instead.
  const IMAGE_SUFFIXES = /\.(png|jpe?g|gif|webp|avif|bmp|ico|svg)$/i;

  // Reassigned on every `showDocument` call: see `readWithAiBtn` above,
  // which is the only caller. A closure rather than a stored url string so
  // the "Read with AI" button always re-derives from whichever item and
  // text-endpoint are current, the same way `show(i)` already recomputes
  // everything else per item rather than caching it.
  let lightboxLoadExtractedText = null;

  async function showDocument(item, name, attachmentId) {
    img.classList.add("hidden");
    broken.classList.add("hidden");
    doc.classList.remove("hidden");
    docBody.replaceChildren();
    pdfPages.replaceChildren();
    pdfPages.classList.add("hidden");
    docNote.classList.add("hidden");
    readWithAiBtn.classList.add("hidden");
    //: A new file, so any half-finished edit of the previous one goes with
    //: it. Cleared *before* the fetch rather than after: the two buttons are
    //: on screen the whole time it is in flight, and Save on a stale target
    //: would write one file's text over another's.
    lightboxEditTarget = null;
    docEdit.value = "";
    setLightboxEditing(false);
    editFileBtn.classList.add("hidden");
    lightboxPreviewSource = null;
    lightboxExtractedText = null;
    lightboxOcrTarget = null;
    //: A new file, so the previous one's page count, stepper and read-chips go
    //: with it: the PDF branch below re-establishes them when there are pages.
    resetDocPages();
    exportTextBtn.classList.add("hidden");
    clearDocPreview();
    previewHtmlBtn.classList.add("hidden");
    clearFind();
    find.classList.remove("hidden");

    // A native MemoryMap document (the Documents list) or a real Attachment
    // row each has its own text/info endpoint; a `/media/` upload has a
    // third. All three converge on the same `AttachedFileTextOut` shape, so
    // everything past this point reads one variable rather than branching
    // three ways again and again.
    const textUrl = attachmentId
      ? `/files/${attachmentId}/text`
      : `/media/text/${encodeURIComponent(name)}`;
    const isPdf = /\.pdf$/i.test(item.filename || name || "");

    async function loadExtractedText() {
      // **The pages stay.** Reported directly: "when I select to read the
      // text from the document in a pdf, the pdf view disappears entirely. I
      // want the pdf view to be on one side, and the live extracted document
      // text and visuals on the right." Reading a scan *against* its pages is
      // the entire point: the text is a machine's reading of an image, and
      // hiding the image removes the only way to check it. So for a file
      // that has rendered pages, this becomes a split: pages left, text
      // right, both scrolling on their own. Anything without pages (a .docx,
      // a .txt) still gets the full width, because there is nothing to put
      // beside it.
      const hasPages = pdfPages.childElementCount > 0;
      doc.classList.toggle("lightbox-doc-split", hasPages);
      pdfPages.classList.toggle("hidden", !hasPages);
      docBody.classList.remove("hidden");
      find.classList.remove("hidden");
      showZoomControls(hasPages);
      if (!hasPages) setZoom(1);
      docBody.textContent = "Reading…";
      let payload = null;
      // See the doc-viewer comment block above `doc`'s own creation: a
      // native document already has its text, set by the Documents list's
      // "Preview" action: nothing to fetch.
      if (item.kind && item.text != null) {
        payload = { kind: item.kind, text: item.text, source: item.source || "file" };
      } else {
        try {
          payload = await apiJson(textUrl);
        } catch {
          payload = null;
        }
      }
      if (!payload) {
        docBody.textContent = "";
        docNote.textContent =
          "This file can't be previewed here. Use Save to open it in another app.";
        docNote.classList.remove("hidden");
        find.classList.add("hidden");
        return;
      }
      docBody.replaceChildren();
      const body = payload.text || "";
      //: **Decided before the empty-body return below, not after it.** A
      //: .docx on an install without markitdown extracts to nothing, so that
      //: return fires: and the read-only reason, which is exactly what such
      //: a file needs to say, used to be computed past it and never shown.
      //: Measured: the note read only "Importing documents needs the optional
      //: markitdown package", with no word about editing at all.
      //:
      //: **Preview is offered only for HTML**, and keyed off the *filename*
      //: rather than the extracted kind: docview reports `.html` as "code",
      //: which is right for how the source renders and says nothing about
      //: whether the file is a page. A .py is code too and has nothing to
      //: preview.
      if (body.trim()) {
        lightboxExtractedText = {
          name: item.filename || name || "document",
          kind: payload.kind,
          text: body,
        };
        exportTextBtn.classList.remove("hidden");
      }
      if (attachmentId && /\.html?$/i.test(item.filename || name || "") && body.trim()) {
        lightboxPreviewSource = `/files/${attachmentId}/html-preview`;
        previewHtmlBtn.classList.remove("hidden");
      }
      const editNotes = [];
      if (item.kind && item.text != null) {
        editFileBtn.classList.add("hidden");
      } else if (payload.editable) {
        lightboxEditTarget = { url: textUrl, text: body };
        editFileBtn.classList.remove("hidden");
      } else {
        editFileBtn.classList.add("hidden");
        if (payload.edit_message) editNotes.push(`Read-only: ${payload.edit_message}`);
      }
      if (!body.trim()) {
        docNote.textContent = [
          payload.message || "There's no readable text in this file.",
          ...editNotes,
        ].join(" · ");
        docNote.classList.remove("hidden");
        return;
      }
      if (payload.kind === "markdown") {
        // The same renderer documents and chat use, so a previewed .md
        // looks like the same app rather than a second idea of markdown.
        renderMarkdown(docBody, body);
      } else {
        // Code and plain text keep their own whitespace, which is most of
        // what makes them readable.
        const pre = document.createElement("pre");
        pre.className = "lightbox-doc-pre";
        const code = document.createElement("code");
        if (payload.kind === "code") {
          //: §R7.1 item 3. `highlightCodeInto` (editor.js) picks the language
          //: off the filename and builds spans with `textContent`, so a file
          //: cannot inject markup by being written to look like markup.
          highlightCodeInto(code, body, item.filename || name || "");
        } else {
          code.textContent = body;
        }
        pre.appendChild(code);
        docBody.appendChild(pre);
      }
      // `source` is shown, not just logged: text a vision model
      // transcribed off a scanned page is a *reading* of the file, and
      // presenting it identically to text read out of a .txt would state a
      // guess as fact.
      const notes = [];
      if (payload.source === "vision-ocr") notes.push("Text read off the page by a vision model");
      else if (payload.source === "converted") notes.push("Converted for preview");
      if (payload.truncated) notes.push("Long file: showing the beginning only");
      if (payload.message) notes.push(payload.message);
      //: **The reason a file cannot be edited, shown where it is read.** §R7.1
      //: item 2 asked for the honest reason in the UI rather than a control
      //: that quietly does nothing. Computed above, beside the button it
      //: belongs to; pushed here so it reads as one line with the rest.
      notes.push(...editNotes);
      docNote.textContent = notes.join(" · ");
      docNote.classList.toggle("hidden", !notes.length);
    }
    lightboxLoadExtractedText = loadExtractedText;

    // A native document is markdown from the database, there is no PDF
    // underneath it to rasterise, so it always takes the text path above.
    if (isPdf && !item.kind) {
      const infoUrl = attachmentId ? `/files/${attachmentId}/pdf-info` : `/media/pdf-info/${encodeURIComponent(name)}`;
      const pageUrl = (i) =>
        attachmentId ? `/files/${attachmentId}/pdf-page/${i}` : `/media/pdf-page/${encodeURIComponent(name)}/${i}`;
      let info = null;
      try {
        info = await apiJson(infoUrl);
      } catch {
        info = null;
      }
      if (info && info.available && info.pages > 0) {
        docBody.classList.add("hidden");
        find.classList.add("hidden"); // nothing here is text to search yet
        //: The identity the OCR workspace needs, built here because this is
        //: the one place that knows whether the open file is an attachment or
        //: a media upload. `original_name` rather than the stored name: the
        //: workspace's own `ocrIsPdf` tests the extension of exactly that.
        //: `url` matters as much as `id` for an upload: the workspace renders a
        //: page through `/media/pdf-page/{stored name}/{n}`, not by id, so a
        //: target without it asked for `/media/pdf-page//0` and got a 404, the
        //: workspace opened on an empty stage. Measured against the running app
        //: while wiring the "open at this page" route in; the attachment side
        //: has an id-addressed page endpoint and never hit it.
        lightboxOcrTarget = attachmentId
          ? { id: attachmentId, _isAttachment: true, original_name: item.filename || name }
          : item.id
          ? {
              id: item.id,
              _isAttachment: false,
              original_name: item.filename || name,
              url: `/media/${name}`,
            }
          : null;
        readWithAiBtn.classList.remove("hidden");
        pdfPages.classList.remove("hidden");
        // Zoom, same as the image view, reported live once pages actually
        // rendered: "or zoom. a lot of controls are missing." `setZoom(1)`
        // resets any leftover magnification from a previously viewed item;
        // `zoomTarget()`/`applyZoom` (above) already know to scale
        // `pdfPages` rather than `img` while this view is the one showing.
        showZoomControls(true);
        setZoom(1);
        for (let i = 0; i < info.pages; i++) {
          const pageImg = document.createElement("img");
          pageImg.className = "lightbox-pdf-page";
          pageImg.loading = "lazy";
          pageImg.alt = `Page ${i + 1} of ${info.pages}`;
          pageImg.src = mediaSrc(pageUrl(i));
          pdfPages.appendChild(pageImg);
        }
        //: **The document block** (Phase 7.1). The page count is known right
        //: here and nowhere else, so this is where the stepper, the chips and
        //: the facts line are told about it. The chips render immediately as
        //: "not read yet" and the stored readings fill them in when they
        //: arrive: a panel that waits for a request before showing the page
        //: count would leave the viewer blank for the one fact it already has.
        docPageCount = info.pages;
        docPage = 0;
        showPageControls(info.pages > 1);
        renderDocPages();
        //: `renderInfo`, not the inline copy in `show()`'s image path: a
        //: document reaches the early return below, so nothing else would ever
        //: draw the facts line for it. Reported as part of the same item, 
        //: "no sections or info are below it really compared to the images."
        renderInfo(item, true);
        loadDocPageReads(attachmentId, name, item).catch(() => {});
        return;
      }
      // pdfpages isn't installed, or this particular file can't be opened: 
      // `info.message` already says which. Fall through to the AI-text path
      // below, which gives the same honest message (docview.py's own
      // "couldn't be opened" vs. "probably a scan" split) rather than a
      // second, differently-worded dead end.
    }
    await loadExtractedText();
  }

  async function show(i) {
    index = (i + items.length) % items.length;
    const item = items[index];
    // **`Promise.resolve()`, not a bare `.catch()` on the call.** Found live,
    // not by reading: this crashed the entire lightbox, not just the new
    // document detection: for the Library's own gallery, whose `getUrl` is
    // `() => mediaSrc(i.url)`, a plain synchronous string return, not a
    // Promise. `.catch` does not exist on a string, so this threw
    // synchronously and no code past it in `show()` ever ran, including the
    // metadata panel that predates this change entirely. `await` on a
    // non-Promise already resolves fine (`show()`'s other two `getUrl()`
    // call sites never hit this); wrapping in `Promise.resolve()` first is
    // what makes `.catch()` safe to chain regardless of which shape a
    // caller returns.
    const rawUrl = await Promise.resolve(item.getUrl()).catch(() => "");
    const name = (/\/media\/([^/?#]+)/.exec(rawUrl || "") || [])[1] || "";
    // A note's own attached file (the `Attachment` model, `/files/{id}`), 
    // distinct from a `/media/{name}` upload, and until now the only file
    // shape the lightbox's document viewer could not read at all: it went
    // straight to a download instead. Same token-gated url shape `mediaSrc`
    // already handles; `showDocument` below is what learned to use it.
    const looksLikeImage =
      IMAGE_SUFFIXES.test(item.filename || "") || IMAGE_SUFFIXES.test(name);
    // A note's own attached file (the `Attachment` model, `/files/{id}`), 
    // distinct from a `/media/{name}` upload, and until now the only file
    // shape the lightbox's document viewer could not read at all: it went
    // straight to a download instead. Same token-gated url shape `mediaSrc`
    // already handles; `showDocument` below is what learned to use it.
    //
    // Gated on `!looksLikeImage`, matching the `name` case just below it, 
    // the comment here used to claim this was "only ever set for a
    // non-image /files/{id}", true only because nothing had ever opened an
    // *image* attachment through this lightbox yet. The Library gallery's
    // own Attachment rows (`renderLibraryImagesGallery`, library.js) changed
    // that: a photo attached to a note now reaches this same code path, and
    // without this guard it fell into the document viewer below, no PDF
    // pages, no image to show, `isPdf` false, straight to `loadExtractedText`
    // asking `/files/{id}/text` for a picture, "no readable text in this
    // file" for what should have been a plain zoomable image.
    const attachmentId = name || looksLikeImage
      ? ""
      : (/\/files\/(\d+)(?:[/?#]|$)/.exec(rawUrl || "") || [])[1] || "";
    // A native document (item.kind already set: see showDocument) has no
    // `/media/...` url to sniff at all; a caller that already declares
    // itself a document skips the filename guess entirely.
    if (item.kind || attachmentId || (name && !looksLikeImage)) {
      overlay.setAttribute("aria-label", item.filename || "Document preview");
      meta.textContent =
        items.length > 1
          ? `${item.filename || ""}, ${index + 1} of ${items.length}`
          : item.filename || "";
      actions.classList.remove("hidden");
      setZoom(1);
      showZoomControls(false);
      openDocBtn.classList.toggle("hidden", !item.documentId);
      syncMoreMenu(item);
      await showDocument(item, name, attachmentId);
      hydrate(index, item, true);
      return;
    }
    doc.classList.add("hidden");
    //: A picture is never a document, so paging from a previewed document to
    //: an image must take this away with the rest of the text controls.
    openDocBtn.classList.add("hidden");
    //: A picture has no text to edit, and leaving Edit/Save on the bar after
    //: paging from a .md to a .png would offer to write the note's markdown
    //: over an image. Cleared with the target, not just hidden.
    lightboxEditTarget = null;
    setLightboxEditing(false);
    editFileBtn.classList.add("hidden");
    lightboxPreviewSource = null;
    lightboxExtractedText = null;
    lightboxOcrTarget = null;
    //: A picture has no pages. Paging from a PDF to an image must take the
    //: stepper and the page chips with it, or the panel keeps offering "page 4
    //: of 9" for a photograph.
    resetDocPages();
    exportTextBtn.classList.add("hidden");
    clearDocPreview();
    previewHtmlBtn.classList.add("hidden");
    find.classList.add("hidden");
    findCount.classList.add("hidden");
    showZoomControls(true);
    img.alt = item.filename || "";
    img.src = rawUrl;
    // A failed decode used to be swallowed here, leaving a blank box with no
    // explanation: reported live as "the second page doesn't load" (an
    // image whose underlying file was gone, paged to from a gallery that
    // itself hides broken tiles, so the lightbox was the only place the
    // failure was ever visible, and it said nothing). Now it says so.
    const ok = await img.decode().then(
      () => true,
      () => false
    );
    img.classList.toggle("hidden", !ok);
    broken.classList.toggle("hidden", ok);
    if (!ok) broken.textContent = `Couldn't load "${item.filename || "this image"}", the file may have been deleted.`;
    overlay.setAttribute("aria-label", item.filename || "Image preview");
    meta.textContent =
      items.length > 1
        ? `${item.filename || ""}, ${index + 1} of ${items.length}`
        : item.filename || "";
    const caption = (item.caption || "").trim();
    const text = (item.text || "").trim();
    infoCaption.textContent = caption;
    infoCaption.classList.toggle("hidden", !caption);
    infoCaptionByline.textContent = caption ? item.captionByline || "" : "";
    infoCaptionByline.classList.toggle("hidden", !caption || !item.captionByline);
    infoText.textContent = text;
    infoText.classList.toggle("hidden", !text);
    infoByline.textContent = item.byline || "";
    infoByline.classList.toggle("hidden", !item.byline);
    info.classList.toggle("hidden", !caption && !text && !item.filename);
    // The picture's own facts, which the app knew and never showed. Asked
    // for: "maybe it can have the image information and other info about it
    // below the image with the caption and ocr text??" Dimensions come from
    // the decoded image rather than from the server, it is the one fact the
    // browser already has and the API does not carry.
    const facts = [];
    if (ok && img.naturalWidth) facts.push(`${img.naturalWidth} × ${img.naturalHeight}`);
    if (item.addedAt) {
      const when = new Date(item.addedAt);
      if (!Number.isNaN(when.valueOf())) facts.push(`Added ${when.toLocaleDateString()}`);
    }
    if (item.filename) facts.push(item.filename);
    infoFacts.textContent = facts.join("  ·  ");
    infoFacts.classList.toggle("hidden", !facts.length);
    // Paging to another picture starts it at fit, the same way opening one
    // does: carrying a 400% zoom onto the next image lands you somewhere
    // arbitrary in a picture you have not seen yet.
    setZoom(1);
    copyBtn.classList.toggle("hidden", !text);
    // Nothing to act on when the file itself failed to load.
    actions.classList.toggle("hidden", !ok);
    syncMoreMenu(item);

    // **Fill in whatever the caller did not know.** Reported directly: the
    // caption, OCR text and facts appeared in the Image Gallery and nowhere
    // else. The lightbox was never the problem, this metadata arrived as
    // *arguments*, and of nine callers only the gallery holds a full media
    // row to pass. Everywhere else (a note attachment, a chat image, a graph
    // or dashboard thumbnail, a whiteboard object) has a url and a name, so
    // the panel below the picture stayed empty on the same picture that
    // showed a full description one tab over.
    //
    // Asking the server closes that gap in one place instead of nine, and
    // covers callers added later without them having to know to pass
    // anything. Only ever *fills*: a caller that did pass a caption keeps
    // the one it passed, so the gallery's own (possibly just-edited,
    // not-yet-saved) values still win.
    hydrate(index, item, ok);
  }

  // Looked up once per filename per lightbox, then remembered: paging back
  // and forth across a gallery would otherwise refetch the same rows.
  const metaCache = new Map();
  async function hydrate(forIndex, item, ok) {
    if (item.caption && item.text && item.addedAt) return;
    let url;
    try {
      url = await item.getUrl();
    } catch {
      return;
    }
    // `/media/<stored name>`, possibly with the `?token=` mediaSrc() adds
    // for declarative loads, which is not part of the name.
    const match = /\/media\/([^/?#]+)/.exec(url || "");
    if (!match) return;
    const name = match[1];
    if (!metaCache.has(name)) {
      metaCache.set(
        name,
        apiJson(`/media/meta/${encodeURIComponent(name)}`).catch(() => null)
      );
    }
    const row = await metaCache.get(name);
    // Not an error worth surfacing: plenty of images in this app are not
    // `MediaUpload` rows at all (a sketch rendered straight to a data url,
    // a file whose row was deleted out from under a note that still links
    // it). No metadata simply means no panel, exactly as before.
    if (!row) return;
    // The picture may have been paged away from while this was in flight.
    if (forIndex !== index) return;

    if (!item.caption && row.caption) item.caption = row.caption;
    if (!item.text) item.text = (row.vision_ocr_text || row.ocr_text || "").trim();
    if (!item.addedAt && row.created_at) item.addedAt = row.created_at;
    if (!item.byline) {
      item.byline = row.vision_ocr_text
        ? `Text read by ${row.vision_ocr_model || "a model"}`
        : row.ocr_text
          ? "Text read with Tesseract OCR"
          : "";
    }
    if (!item.captionByline) item.captionByline = captionBylineFor(row);
    // The gallery passes `original_name`; a bare url caller passes the
    // stored name or nothing, and the human-readable one is better.
    if (row.original_name && (!item.filename || item.filename === name)) {
      item.filename = row.original_name;
    }
    renderInfo(item, ok);
  }

  // The half of `show()` that draws the panel, split out so `hydrate` can
  // redraw it once the answer arrives without re-running the image load.
  //: Which item the info panel was last drawn for, so a page change can redraw
  //: it without `show()` having to hand the item down through the stepper.
  let lightboxInfoItem = null;

  function renderInfo(item, ok) {
    lightboxInfoItem = item;
    //: **For a document, the panel is about the page on screen** (Phase 7.3).
    //: The file-level values are one caption for a whole PDF, which describes
    //: none of its pages, and the *joined* reading of every page, which is
    //: not what you are looking at when page 4 is up. `docPageRows` has both,
    //: per page, from the `PageRead` store; a page with neither falls back to
    //: the file's own values so nothing that used to show now disappears.
    const row = docPageCount ? docPageRows.get(docPage) : null;
    const perPage = Boolean(row && (row.text || row.caption));
    const caption = perPage ? row.caption : (item.caption || "").trim();
    const text = perPage ? row.text : (item.text || "").trim();
    const captionByline = perPage
      ? row.caption_model
        ? `Figures on page ${docPage + 1}, described by ${shortModelName(row.caption_model)}`
        : ""
      : item.captionByline || "";
    const byline = perPage
      ? row.model
        ? `Page ${docPage + 1}, read by ${shortModelName(row.model)}`
        : row.text
          ? `Page ${docPage + 1}`
          : ""
      : item.byline || "";
    //: What Copy hands over has to be what is on screen: copying every page's
    //: reading while the panel shows one page's is the app disagreeing with
    //: itself about what "this text" means.
    lightboxShownText = text;
    infoCaption.textContent = caption;
    infoCaption.classList.toggle("hidden", !caption);
    infoCaptionByline.textContent = caption ? captionByline : "";
    infoCaptionByline.classList.toggle("hidden", !caption || !captionByline);
    infoText.textContent = text;
    infoText.classList.toggle("hidden", !text);
    infoByline.textContent = byline;
    infoByline.classList.toggle("hidden", !byline);
    info.classList.toggle("hidden", !caption && !text && !item.filename);
    meta.textContent =
      items.length > 1
        ? `${item.filename || ""}, ${index + 1} of ${items.length}`
        : item.filename || "";
    const facts = [];
    //: A document's dimensions are its *pages*, and the picture's pixel size
    //: is meaningless for one, `docPageCount` is 0 for anything that is not a
    //: rendered PDF, so an image is unaffected.
    if (docPageCount) {
      facts.push(`${docPageCount} page${docPageCount === 1 ? "" : "s"}`);
      facts.push(
        docPagesRead.size
          ? `${docPagesRead.size} read`
          : "none read yet"
      );
    } else if (ok && img.naturalWidth) {
      facts.push(`${img.naturalWidth} × ${img.naturalHeight}`);
    }
    if (item.addedAt) {
      const when = new Date(item.addedAt);
      if (!Number.isNaN(when.valueOf())) facts.push(`Added ${when.toLocaleDateString()}`);
    }
    if (item.filename) facts.push(item.filename);
    infoFacts.textContent = facts.join("  ·  ");
    infoFacts.classList.toggle("hidden", !facts.length);
    copyBtn.classList.toggle("hidden", !text);
    copyBtn.title = perPage
      ? `Copy the text read from page ${docPage + 1}`
      : "Copy the text read from this image";
  }

  const close = () => {
    overlay.remove();
    document.removeEventListener("keydown", onKey);
  };
  const onKey = (e) => {
    if (e.key === "Escape") close();
    else if (e.key === "ArrowLeft" && items.length > 1) show(index - 1);
    else if (e.key === "ArrowRight" && items.length > 1) show(index + 1);
  };
  // Only empty space closes on click, the picture, the metadata and the
  // nav/close buttons all need to stay clickable without dismissing the
  // dialog they sit inside. The three layout boxes named here have no content
  // of their own: the column is full-window-width and only as tall as the
  // picture, so without them the entire band left and right of the image was
  // dead to a dismissing click. See `wireBackdropClose`.
  wireBackdropClose(overlay, close, ".lightbox-column, .lightbox-stage-wrap, .lightbox-stage");
  closeBtn.addEventListener("click", close);
  prevBtn.addEventListener("click", (e) => {
    e.stopPropagation();
    show(index - 1);
  });
  nextBtn.addEventListener("click", (e) => {
    e.stopPropagation();
    show(index + 1);
  });
  document.addEventListener("keydown", onKey);

  stage.append(img, broken);
  // **The arrows must not live inside the stage.** The stage scrolls now
  // (zoom needs it to, so a magnified picture can be panned to its edges),
  // and an absolutely-positioned child of a scrolling box scrolls with its
  // content: so the arrows drifted off-centre and away from the edges the
  // moment anything overflowed. Reported live: "completely off, different
  // distances from the edge of the screen, at different heights, and not
  // even aligned."
  //
  // A non-scrolling wrapper holds both: the stage scrolls inside it, the
  // arrows are positioned against it, and because the wrapper is exactly
  // the stage's box, `top: 50%` is still the middle of the picture, which
  // is the property the note on `.lightbox-nav` says two earlier attempts
  // lost.
  const stageWrap = document.createElement("div");
  stageWrap.className = "lightbox-stage-wrap";
  stageWrap.appendChild(stage);
  if (items.length > 1) stageWrap.append(prevBtn, nextBtn);
  const column = document.createElement("div");
  column.className = "lightbox-column";
  column.append(stageWrap, meta, actions, info);
  overlay.append(closeBtn, column);
  document.body.appendChild(overlay);
  closeBtn.focus();
  //: `.then`, not `await`: `openLightbox` is not async and its nine callers
  //: do not expect it to be. The dialog is already on screen and interactive
  //: by the time this resolves; all that is left is where to point the reader.
  Promise.resolve(show(startIndex)).then(() => {
    if (!opts.focusReading) return;
    //: Start on the first page that actually has a reading. Page 1 of a scan
    //: is often a cover, and "open the reading" landing on a page with none is
    //: the same disappointment as not opening it at all.
    if (docPageCount && docPagesRead.size) {
      setDocPage(Math.min(...docPagesRead));
    }
    //: `block: "end"` because the panel sits *under* the file: bringing its
    //: bottom into view is what puts the reading on screen, where "nearest"
    //: would decide it is already close enough and do nothing.
    info.scrollIntoView({ block: "end" });
    //: Focus follows the eye. `-1` so it is a destination rather than another
    //: stop on the way through the dialog's own controls.
    infoText.tabIndex = -1;
    infoText.focus();
  });
}

// A small kebab (⋯) near whatever the user just selected, anywhere in the
// app's actual content: a document, the graph, a web search result, a chat
// message, a note. Asked for directly: "if the user highlights an output or
// piece of text... the user can save it as a note, search the notebook for
// similar phrases or meaning/topics, ask the ai about it".
//
// **It used to be three flat buttons, and the shape was the problem.** Asked
// for directly, second time round: "a kebab 3-dot button which when clicked on
// shows the Popup buttons within the application window". Three things go
// wrong with a bar that is always open, and all three are fixed by a kebab:
//
//   1. **It ran off the screen.** The old clamp was
//      `Math.min(Math.max(margin, left), innerWidth - width - margin)`. When
//      the bar is wider than the viewport the upper bound is *smaller* than
//      the lower bound, so `Math.min` wins and `left` goes negative. The bar
//      could not wrap (`white-space: nowrap`, no `flex-wrap`) and its three
//      labels ran to ~50 characters, comfortably wider than a 360px phone.
//      The clamp below is written the other way round, so a box too wide to
//      fit pins to the margin instead of hanging off the left edge.
//   2. **It covered the thing you had just selected.** A 28px dot does not.
//   3. **Three actions was the ceiling.** The app's richest capture surface
//      offered less than a note card's own ⋯ menu. A menu has room, so this
//      is now where a selection can become a note, a draft, an addition to an
//      existing note, several linked notes, a reminder, or a question.
//
// Denylist rather than an allowlist of containers: excluding form fields
// (which already have their own selection/context-menu behaviour a popup
// stealing focus would fight) and the popup's own text is simpler than
// naming every readable surface in the app and it can't silently miss one
// that gets added later.
const SELECTION_POPUP_EXCLUDED = "input, textarea, [contenteditable], .selection-popup";

let selectionPopupEl = null;
let selectionPopupText = "";
let selectionPopupSource = null;

// Where the selected passage came from, when the app actually knows.
//
// Only the web reader can answer this today, and it can answer it exactly:
// `webReaderPage` already holds the url and title of the page on screen. This
// is the "capture surface" half of BACKLOG.md §65 (highlight/web-clip
// capture): the half that item calls small. Everywhere else in the app the
// honest answer is "no external source", and `null` says so rather than
// inventing one.
function selectionSource(node) {
  const el = node && (node.nodeType === 1 ? node : node.parentElement);
  if (!el || !el.closest("#web-reader")) return null;
  if (!webReaderPage?.url) return null;
  return { url: webReaderPage.url, title: webReaderPage.title || webReaderPage.domain || "" };
}

// A passage, quoted, with its origin attributed underneath.
//
// Markdown blockquote rather than a bare paste, because a clipping is somebody
// else's words and a notebook that cannot tell them from yours is worse than
// one that refuses the clipping. The source line is a real markdown link, so
// it stays clickable in the rendered note.
function clippingMarkdown(text, source) {
  const quoted = text
    .split("\n")
    .map((line) => `> ${line}`)
    .join("\n");
  if (!source) return quoted;
  const label = source.title || source.url;
  return `${quoted}\n\n: [${label}](${source.url})`;
}

async function saveSelectionAsNote(text, { draft = false, source = null } = {}) {
  const content = source ? clippingMarkdown(text, source) : text;
  // Real metadata alongside the body's own blockquote+link (BACKLOG §65's
  // "source as metadata, not just folded into body text"), the body copy
  // stays so the note is still a plain, portable markdown file with no app
  // behind it; the columns are what let a note card show a real badge or a
  // future "everything clipped from this site" filter without parsing it
  // back out.
  const sourceFields = source
    ? { source_url: source.url, source_title: source.title || "" }
    : {};
  try {
    const created = await apiJson("/entries", {
      method: "POST",
      body: JSON.stringify({ content, is_draft: draft, ...sourceFields }),
    });
    // Undoable, like every other create in this app (the global stack: 
    // see pushUndo). Saving a clipping by accident and having no way back
    // would be a worse experience than the old three-button bar's.
    pushUndo(
      draft ? "Saved a selection as a draft" : "Saved a selection as a note",
      async () => {
        await api(`/entries/${created.id}`, { method: "DELETE" });
        await loadEntries();
      },
      async () => {
        await apiJson("/entries", {
          method: "POST",
          body: JSON.stringify({ content, is_draft: draft, ...sourceFields }),
        });
        await loadEntries();
      }
    );
    toast(draft ? "Saved as a draft note." : "Saved as a note.");
    // Same fix as saveChatAnswerAsNote(): unconditional. A selection saved
    // from wherever the popup was invoked (not necessarily the Notes tab)
    // must not leave the in-memory `entries` list stale until something
    // else happens to refetch it.
    loadEntries();
  } catch (error) {
    toast(error.message || "Couldn't save that note.", true);
  }
}

// Append the selection to a note the user picks.
//
// Uses `pickEntryDialog` below rather than the chat dock's `#note-picker-panel`
//, that one is a multi-select bound to the chat composer, not a general
// chooser, and reusing it would mean it had two owners.
async function appendSelectionToNote(text) {
  const entry = await pickEntryDialog("Add the selected text to which note?");
  if (!entry) return;
  const before = entry.content;
  const after = `${before.trimEnd()}\n\n${text}`;
  try {
    await api(`/entries/${entry.id}`, {
      method: "PUT",
      body: JSON.stringify({ content: after }),
    });
    pushEntryPutUndo(entry.id, "Added text to a note", { content: before }, { content: after });
    toast("Added to the note.");
    await loadEntries();
    flashEntry(entry.id);
  } catch (error) {
    toast(error.message || "Couldn't add that to the note.", true);
  }
}

// A one-off "choose a note" dialog: search box, live list, Escape to cancel.
//
// Built on the same shape as `promptDialog` (overlay + card + captured
// keydown + returned focus) rather than beside it, so a dialog opened from a
// selection behaves identically to every other dialog in the app, 
// `activeOverlay()` picks it up from its `role="dialog"` and traps Tab inside
// it with no registration step.
function pickEntryDialog(message) {
  return new Promise((resolve) => {
    const overlay = document.createElement("div");
    overlay.className = "modal-overlay confirm-overlay";
    overlay.setAttribute("role", "dialog");
    overlay.setAttribute("aria-modal", "true");
    overlay.setAttribute("aria-label", message);

    const card = document.createElement("div");
    card.className = "card modal-card confirm-card entry-pick-card";
    const text = document.createElement("p");
    text.className = "confirm-text";
    text.textContent = message;
    const search = document.createElement("input");
    search.type = "text";
    search.placeholder = "Search your notes…";
    search.setAttribute("aria-label", "Search your notes");
    const list = document.createElement("div");
    list.className = "entry-pick-list";

    const returnFocus = document.activeElement;
    let settled = false;
    const close = (entry) => {
      if (settled) return;
      settled = true;
      document.removeEventListener("keydown", onKey, true);
      overlay.remove();
      returnFocus?.focus?.();
      resolve(entry);
    };
    const onKey = (event) => {
      if (event.key !== "Escape") return;
      event.stopPropagation();
      close(null);
    };

    // Drafts excluded: adding to a half-finished draft is not what "an
    // existing note" means, and the Notes tab already keeps them out of every
    // other list for the same reason.
    const paint = () => {
      const term = search.value.trim().toLowerCase();
      const matches = allEntries
        .filter((e) => !e.is_draft && !e.is_deleted)
        .filter((e) => !term || (e.content || "").toLowerCase().includes(term))
        .slice(0, 40);
      list.replaceChildren();
      if (!matches.length) {
        const empty = document.createElement("p");
        empty.className = "muted";
        empty.textContent = term ? "No notes match that." : "No notes yet.";
        list.appendChild(empty);
        return;
      }
      for (const entry of matches) {
        const button = document.createElement("button");
        button.type = "button";
        button.className = "entry-pick-row";
        button.textContent = entry.title || notePreviewText(entry.content).slice(0, 90);
        button.addEventListener("click", () => close(entry));
        list.appendChild(button);
      }
    };
    search.addEventListener("input", paint);
    paint();

    const row = document.createElement("div");
    row.className = "row confirm-actions";
    row.append(smallButton("Cancel", "Cancel", () => close(null)));
    card.append(text, search, list, row);
    overlay.appendChild(card);
    wireBackdropClose(overlay, () => close(null));
    document.addEventListener("keydown", onKey, true);
    document.body.appendChild(overlay);
    search.focus();
  });
}

//: **Choose any one thing the library holds**, a note, a document, a file or
//: a saved link: as `{kind, id, label}`.
//:
//: A fourth chooser only because the three that exist answer different
//: questions. `pickEntryDialog` above returns a *note* and nothing else;
//: `pickMediaDialog` below returns an upload; the chat dock's
//: `#note-picker-panel` is a multi-select bound to the composer's own
//: attachment lists, so borrowing it would give it two owners (its own
//: comment says as much). This one returns exactly one item and says which of
//: the four tables it came from, which is what a map's reference node needs:
//: `POST /whiteboard/boards/{id}/nodes` takes a `kind` and a `ref_id` and
//: resolves the label itself (MINDMAP_PLAN.md §9.2: a copied title goes
//: stale the moment the thing behind it is renamed).
//:
//: `kind` is deliberately the *server's* vocabulary: note / document / file
//: / link, `MAP_REFERENCE_KINDS` in routes_whiteboard.py: rather than a
//: display word, so a caller never has to translate between what the picker
//: says and what the endpoint accepts.
const LIBRARY_PICK_SOURCES = [
  { kind: "note", label: "Notes", icon: "ph:note", placeholder: "Search your notes…" },
  { kind: "document", label: "Documents", icon: "ph:file-text", path: "/documents", placeholder: "Search your documents…" },
  { kind: "file", label: "Files", icon: "ph:paperclip", path: "/files/gallery", placeholder: "Search your files…" },
  { kind: "link", label: "Links", icon: "ph:link-simple", path: "/bookmarks", placeholder: "Search your links…" },
];

//: One row's label per source, in one table for the reason `notePickerShape`
//: gives for its own: the renderer is the same list either way, and four
//: copies of it is how the four drift apart.
function libraryPickLabel(kind, row) {
  if (kind === "note") return noteLabel(row, 70);
  if (kind === "document") return row.title || "Untitled document";
  if (kind === "file") return row.original_name || row.filename || "File";
  return row.title || row.url || "Link";
}

//: Fetched once per dialog rather than per keystroke, and per source rather
//: than all four up front, the same two rules `notePickerRows` follows, and
//: for the same reason: three of these lists are never looked at by someone
//: who came to point at a note.
function pickLibraryItemDialog(message, { sources = null } = {}) {
  const available = LIBRARY_PICK_SOURCES.filter(
    (source) => !sources || sources.includes(source.kind)
  );
  return new Promise((resolve) => {
    const overlay = document.createElement("div");
    overlay.className = "modal-overlay confirm-overlay";
    overlay.setAttribute("role", "dialog");
    overlay.setAttribute("aria-modal", "true");
    overlay.setAttribute("aria-label", message);

    const card = document.createElement("div");
    card.className = "card modal-card confirm-card entry-pick-card";
    const text = document.createElement("p");
    text.className = "confirm-text";
    text.textContent = message;

    let active = available[0];
    const seg = document.createElement("div");
    seg.className = "seg seg-compact";
    seg.setAttribute("role", "tablist");
    seg.setAttribute("aria-label", "What to point at");

    const search = document.createElement("input");
    search.type = "search";
    search.placeholder = active.placeholder;
    search.setAttribute("aria-label", message);
    const list = document.createElement("div");
    list.className = "entry-pick-list";

    const returnFocus = document.activeElement;
    let settled = false;
    const close = (choice) => {
      if (settled) return;
      settled = true;
      document.removeEventListener("keydown", onKey, true);
      overlay.remove();
      returnFocus?.focus?.();
      resolve(choice);
    };
    const onKey = (event) => {
      if (event.key !== "Escape") return;
      event.stopPropagation();
      close(null);
    };

    //: Per-source, so switching tabs and back does not re-fetch. Notes are
    //: never in here: `allEntries` is already in memory and is kept current
    //: by every save, so a second copy would be the stale one.
    const cache = {};
    let token = 0;

    const rowsFor = async (kind) => {
      if (kind === "note") {
        //: Drafts, deleted notes, private notes and boards are all excluded.
        //: Drafts for the reason `pickEntryDialog` gives: "an existing note"
        //: does not mean a half-typed capture, and a board because it is
        //: usually the very thing this picker was opened *from*.
        return (typeof allEntries !== "undefined" ? allEntries : []).filter(
          (entry) => !entry.is_draft && !entry.is_deleted && !entry.is_board && !entry.is_private
        );
      }
      if (cache[kind]) return cache[kind];
      const source = available.find((s) => s.kind === kind);
      const rows = await apiJson(source.path, { silent: true }).catch(() => []);
      cache[kind] = Array.isArray(rows) ? rows : rows.documents || [];
      return cache[kind];
    };

    const paint = async () => {
      const mine = (token += 1);
      const kind = active.kind;
      const term = search.value.trim().toLowerCase();
      const rows = await rowsFor(kind);
      // A slow fetch that finished after the user moved on must not paint
      // over the tab they are actually looking at.
      if (mine !== token || active.kind !== kind) return;
      const matches = rows
        .map((row) => ({ row, label: libraryPickLabel(kind, row) }))
        .filter(({ label }) => !term || label.toLowerCase().includes(term))
        .slice(0, 40);
      list.replaceChildren();
      if (!matches.length) {
        const empty = document.createElement("p");
        empty.className = "muted";
        empty.textContent = term
          ? `No ${active.label.toLowerCase()} match that.`
          : `No ${active.label.toLowerCase()} yet.`;
        list.appendChild(empty);
        return;
      }
      for (const { row, label } of matches) {
        const button = document.createElement("button");
        button.type = "button";
        button.className = "entry-pick-row";
        setLabel(button, `${active.icon} ${label}`);
        button.title = label;
        button.addEventListener("click", () => close({ kind, id: row.id, label }));
        list.appendChild(button);
      }
    };

    for (const source of available) {
      const tab = document.createElement("button");
      tab.type = "button";
      tab.setAttribute("role", "tab");
      tab.dataset.pickKind = source.kind;
      tab.textContent = source.label;
      const on = source.kind === active.kind;
      tab.classList.toggle("active", on);
      tab.setAttribute("aria-selected", on ? "true" : "false");
      tab.addEventListener("click", () => {
        active = source;
        for (const sibling of seg.querySelectorAll("button")) {
          const chosen = sibling.dataset.pickKind === source.kind;
          sibling.classList.toggle("active", chosen);
          sibling.setAttribute("aria-selected", chosen ? "true" : "false");
        }
        search.placeholder = source.placeholder;
        paint();
        search.focus();
      });
      seg.appendChild(tab);
    }

    search.addEventListener("input", paint);
    paint();

    const row = document.createElement("div");
    row.className = "row confirm-actions";
    row.append(smallButton("Cancel", "Cancel", () => close(null)));
    card.append(text, seg, search, list, row);
    overlay.appendChild(card);
    wireBackdropClose(overlay, () => close(null));
    document.addEventListener("keydown", onKey, true);
    document.body.appendChild(overlay);
    search.focus();
  });
}

//: **Several notes at once**, which `pickLibraryItemDialog` above deliberately
//: cannot do: that one closes on the first click, because pointing a node at a
//: note is one choice and a confirm step would be a second click for nothing.
//: "Make a map of these notes" is the opposite shape, a list you assemble, so
//: the row is a checkbox and the dialog closes on a button.
//:
//: It draws the same `.entry-pick-*` recipe as its single-pick sibling rather
//: than a second look for the same job, and it reads `allEntries`, the
//: in-memory list every save keeps current, so there is no fetch and no second
//: copy of the notebook to go stale.
//:
//: Resolves with an array of `{id, label}` in the order they were ticked, or
//: null if the dialog was dismissed: the empty array is a real answer nobody
//: wants (a map of no notes), so the confirm button stays disabled until at
//: least one row is on.
function pickNotesDialog(message, { confirmLabel = "Continue", limit = 40 } = {}) {
  return new Promise((resolve) => {
    const overlay = document.createElement("div");
    overlay.className = "modal-overlay confirm-overlay";
    overlay.setAttribute("role", "dialog");
    overlay.setAttribute("aria-modal", "true");
    overlay.setAttribute("aria-label", message);

    const card = document.createElement("div");
    card.className = "card modal-card confirm-card entry-pick-card";
    const head = document.createElement("div");
    head.className = "row confirm-head";
    const title = document.createElement("h3");
    title.className = "confirm-title";
    title.textContent = message;
    head.appendChild(title);

    const search = document.createElement("input");
    search.type = "search";
    search.placeholder = "Search your notes…";
    search.setAttribute("aria-label", message);
    const list = document.createElement("div");
    list.className = "entry-pick-list";
    const count = document.createElement("p");
    count.className = "muted";

    //: The ticks live here and not in the DOM, so a note stays chosen when a
    //: search term hides its row: typing a second term to find the second note
    //: would otherwise silently unpick the first.
    const chosen = new Map();
    const returnFocus = document.activeElement;
    let settled = false;
    const close = (answer) => {
      if (settled) return;
      settled = true;
      document.removeEventListener("keydown", onKey, true);
      overlay.remove();
      returnFocus?.focus?.();
      resolve(answer);
    };
    const onKey = (event) => {
      if (event.key !== "Escape") return;
      event.preventDefault();
      event.stopPropagation();
      close(null);
    };

    const confirm = smallButton(confirmLabel, confirmLabel, () => {
      if (!chosen.size) return;
      close([...chosen.entries()].map(([id, label]) => ({ id, label })));
    }, false);

    const refreshCount = () => {
      count.textContent = chosen.size
        ? `${chosen.size} note${chosen.size === 1 ? "" : "s"} chosen${chosen.size >= limit ? ` (the most this can use is ${limit})` : ""}`
        : "Pick the notes this should be built from.";
      confirm.disabled = chosen.size === 0;
    };

    const paint = () => {
      const term = search.value.trim().toLowerCase();
      const rows = (typeof allEntries !== "undefined" ? allEntries : []).filter(
        (entry) => !entry.is_draft && !entry.is_deleted && !entry.is_board && !entry.is_private
      );
      const matches = rows
        .map((row) => ({ row, label: noteLabel(row, 70) }))
        .filter(({ label }) => !term || label.toLowerCase().includes(term))
        .slice(0, 60);
      list.replaceChildren();
      if (!matches.length) {
        const empty = document.createElement("p");
        empty.className = "muted";
        empty.textContent = term ? "No notes match that." : "No notes yet.";
        list.appendChild(empty);
        return;
      }
      for (const { row, label } of matches) {
        const line = document.createElement("label");
        line.className = "entry-pick-row entry-pick-check";
        const box = document.createElement("input");
        box.type = "checkbox";
        box.checked = chosen.has(row.id);
        box.addEventListener("change", () => {
          if (box.checked && chosen.size >= limit && !chosen.has(row.id)) {
            box.checked = false;
            toast(`That is the most this can use at once: ${limit} notes.`);
            return;
          }
          if (box.checked) chosen.set(row.id, label);
          else chosen.delete(row.id);
          refreshCount();
        });
        const text = document.createElement("span");
        text.textContent = label;
        line.append(box, text);
        line.title = label;
        list.appendChild(line);
      }
    };

    search.addEventListener("input", paint);
    paint();
    refreshCount();

    const row = document.createElement("div");
    row.className = "row confirm-actions";
    row.append(smallButton("Cancel", "Cancel", () => close(null)), confirm);
    card.append(head, search, list, count, row);
    overlay.appendChild(card);
    wireBackdropClose(overlay, () => close(null));
    document.addEventListener("keydown", onKey, true);
    document.body.appendChild(overlay);
    search.focus();
  });
}

// Pick something already uploaded rather than uploading it again, asked for
// directly: "I also want to be able to attach images that are already in the
// image library... to new notes in the capture subtab." `/media` (the same
// list the Image Gallery renders from) has no mime field, only a filename
// and an original name, reusing the gallery's own approach of just trying
// each as an <img> and dropping the tile on error, rather than guessing from
// a file extension.
function pickMediaDialog() {
  return new Promise((resolve) => {
    const overlay = document.createElement("div");
    overlay.className = "modal-overlay confirm-overlay";
    overlay.setAttribute("role", "dialog");
    overlay.setAttribute("aria-modal", "true");
    overlay.setAttribute("aria-label", "Choose from your library");

    const card = document.createElement("div");
    card.className = "card modal-card confirm-card entry-pick-card";
    const text = document.createElement("p");
    text.className = "confirm-text";
    text.textContent = "Choose an image already in your library";
    const search = document.createElement("input");
    search.type = "text";
    search.placeholder = "Search by filename…";
    search.setAttribute("aria-label", "Search your uploaded images");
    const grid = document.createElement("div");
    grid.className = "media-pick-grid";

    const returnFocus = document.activeElement;
    let settled = false;
    const close = (upload) => {
      if (settled) return;
      settled = true;
      document.removeEventListener("keydown", onKey, true);
      overlay.remove();
      returnFocus?.focus?.();
      resolve(upload);
    };
    const onKey = (event) => {
      if (event.key !== "Escape") return;
      event.stopPropagation();
      close(null);
    };

    let uploads = [];
    const paint = () => {
      const term = search.value.trim().toLowerCase();
      const matches = uploads
        .filter((u) => !term || u.original_name.toLowerCase().includes(term))
        .slice(0, 60);
      grid.replaceChildren();
      if (!matches.length) {
        const empty = document.createElement("p");
        empty.className = "muted";
        empty.textContent = uploads.length
          ? "No uploads match that."
          : "Nothing uploaded yet: attach a new file to start your library.";
        grid.appendChild(empty);
        return;
      }
      for (const upload of matches) {
        const tile = document.createElement("button");
        tile.type = "button";
        tile.className = "media-pick-tile";
        tile.title = upload.original_name;
        const img = document.createElement("img");
        img.src = mediaSrc(upload.url);
        img.alt = "";
        img.loading = "lazy";
        // Not every upload is an image (there's no mime field to check
        // first): a file that can't decode as one drops its own tile
        // rather than showing a broken-image glyph, same as the gallery.
        img.addEventListener("error", () => tile.remove());
        const name = document.createElement("span");
        name.textContent = upload.original_name;
        tile.append(img, name);
        tile.addEventListener("click", () => close(upload));
        grid.appendChild(tile);
      }
    };
    search.addEventListener("input", paint);

    const row = document.createElement("div");
    row.className = "row confirm-actions";
    row.append(smallButton("Cancel", "Cancel", () => close(null)));
    card.append(text, search, grid, row);
    overlay.appendChild(card);
    wireBackdropClose(overlay, () => close(null));
    document.addEventListener("keydown", onKey, true);
    document.body.appendChild(overlay);
    search.focus();

    apiJson("/media", { silent: true })
      .then((list) => {
        uploads = list || [];
        paint();
      })
      .catch(() => {
        grid.replaceChildren();
        const err = document.createElement("p");
        err.className = "muted";
        err.textContent = "Couldn't load your library.";
        grid.appendChild(err);
      });
  });
}

// Turn the selection into a reminder, through the same parser the Reminders
// tab's "magic add" box uses: not a second one.
async function remindFromSelection(text) {
  try {
    const reminder = await apiJson("/reminders/parse", {
      method: "POST",
      // Our clock, so "tomorrow evening" resolves against the time the user
      // can see rather than the server's UTC: same as magicAddReminder.
      body: JSON.stringify({ text, tz_offset_minutes: -new Date().getTimezoneOffset() }),
    });
    toast(`Reminder set: ${relativeWhen(reminder.due_at)}.`);
    askNotificationPermission();
    // Same fix as saveChatAnswerAsNote()/saveSelectionAsNote(): unconditional,
    // so a reminder created from wherever this popup was invoked doesn't sit
    // stale out of the Reminders tab's in-memory list.
    loadReminders();
  } catch (error) {
    toast(error.message || "Couldn't read a reminder from that.", true);
  }
}

// The actions the ⋯ offers. Rebuilt on every open rather than once, because
// two of them depend on state that changes between selections: whether the
// passage has a source to attribute, and whether the local model is running.
// The <textarea>/<input> a selection came from, or null when the selection is
// in rendered content. Kept separate from `selectionPopupText` because the
// field is what an edit action needs to write back into.
let selectionPopupField = null;

// A selection inside a text field, or null.
//
// This needs its own path because `window.getSelection()` does not see inside
// a <textarea>, the browser keeps that selection on the element itself, as
// `selectionStart`/`selectionEnd`. That is the real reason the popup never
// appeared while editing, and reading the DOM selection alone will always
// come back empty there no matter what the exclusion list says.
function fieldSelection() {
  const el = document.activeElement;
  if (!el || (el.tagName !== "TEXTAREA" && el.tagName !== "INPUT")) return null;
  // `selectionStart` is null on input types that do not support it (number,
  // email, colour…), which is exactly the set we should not offer this on.
  if (el.selectionStart == null || el.selectionStart === el.selectionEnd) return null;
  const text = el.value.slice(el.selectionStart, el.selectionEnd);
  return text.trim() ? { el, start: el.selectionStart, end: el.selectionEnd, text } : null;
}

// Replace a field's selected range, then put the caret back around the same
// passage. Dispatches `input` because everything downstream of typing, 
// draft autosave, the character counter, the live markdown preview, listens
// for it, and a programmatic value change fires nothing on its own.
function wrapFieldSelection(field, before, after) {
  const { el, start, end, text } = field;
  el.value = el.value.slice(0, start) + before + text + after + el.value.slice(end);
  el.dispatchEvent(new Event("input", { bubbles: true }));
  el.focus();
  el.setSelectionRange(start + before.length, start + before.length + text.length);
}

function selectionMenuItems() {
  const text = selectionPopupText;
  const source = selectionPopupSource;
  const aiOff = modelStatus ? modelStatus.ollama_running === false : false;

  const items = [];

  // **Where highlighting is discoverable from.** `==text==` renders as a
  // highlight, but a syntax nobody is told about may as well not exist, 
  // reported exactly that way ("I still dont know how to highlight text").
  // Selecting the words you want marked and picking a colour is the
  // affordance; the syntax it writes is still plain text in the note, so
  // nothing here is a second way of storing a highlight.
  if (selectionPopupField) {
    const field = selectionPopupField;
    items.push(
      makeMenuItem("ph:highlighter Highlight", "Mark this passage (yellow)", () =>
        wrapFieldSelection(field, "==", "==")
      ),
      makeMenuItem("ph:palette Highlight in a colour…", "Green, blue, pink, purple or orange", async () => {
        const colour = (await promptDialog(
          "Colour: green, blue, pink, purple or orange:", "green"
        )).trim().toLowerCase();
        if (!colour) return;
        if (!["yellow", "green", "blue", "pink", "purple", "orange"].includes(colour)) {
          toast("Pick one of: yellow, green, blue, pink, purple, orange.", true);
          return;
        }
        wrapFieldSelection(field, colour === "yellow" ? "==" : `==${colour}|`, "==");
      }),
      makeMenuItem("ph:text-b Bold", "Wrap this in **bold**", () =>
        wrapFieldSelection(field, "**", "**")
      ),
      makeMenuItem("ph:text-italic Italic", "Wrap this in *italic*", () =>
        wrapFieldSelection(field, "*", "*")
      )
    );
  }

  items.push(
    makeMenuItem("ph:note-pencil Save as a note", "File this straight into your notebook", () =>
      saveSelectionAsNote(text)
    ),
    makeMenuItem("ph:pencil-simple-line Save as a draft", "Keep it as an unfinished draft", () =>
      saveSelectionAsNote(text, { draft: true })
    ),
    makeMenuItem("ph:plus-circle Add to a note…", "Append this to a note you already have", () =>
      appendSelectionToNote(text)
    )
  );

  if (source) {
    items.push(
      makeMenuItem(
        "ph:quotes Save with its source",
        `Save as a quote, credited to ${source.title || source.url}`,
        () => saveSelectionAsNote(text, { source })
      )
    );
  }

  items.push(
    // Through the shared helper, not `navigator.clipboard` directly: it falls
    // back to a hidden textarea and then to showing the text pre-selected,
    // which is what makes copy work in the hardened webview the desktop build
    // runs in. (`tests/test_log_console.py` enforces this, and caught the
    // direct call that was here first.)
    makeMenuItem("ph:copy Copy", "Copy the selected text", async () => {
      if (await copyToClipboard(text)) toast("Copied.");
    }),
    makeMenuItem("ph:magnifying-glass Search the notebook", "Find notes that match this", () => {
      switchTab("notes");
      showNotesSection("browse");
      noteSearch = text;
      $("note-search").value = text;
      $("save-search").classList.remove("hidden");
      renderEntries();
      if ($("semantic-search-toggle")?.checked) loadEntries();
    }),
    makeMenuItem("ph:bell Set a reminder", "Read a reminder out of the selection", () =>
      remindFromSelection(text)
    )
  );

  // AI-only, and disabled rather than hidden when the model is off, the same
  // convention AI_ONLY_CONTROLS applies to every other AI action, so the
  // capability stays discoverable and the reason is on the item itself.
  // (`AI_ONLY_CONTROLS` itself keys off element ids, and these items are built
  // fresh on every open, so they carry the state directly instead.)
  items.push(
    makeMenuItem(
      "ph:scissors Extract notes…",
      aiOff
        ? "Extracting notes needs the local AI, start Ollama to use this."
        : "Split this into one or more linked notes, with a preview first",
      () => {
        if (aiOff) {
          toast("Extracting notes needs the local AI.", true);
          return;
        }
        openExtractPreview(text);
      }
    ),
    makeMenuItem("ph:chat-circle Ask the AI about this", "Start a chat about the selection", () => {
      switchTab("chat");
      const input = $("chat-input");
      input.value = `Tell me about this: "${text}"`;
      input.focus();
    })
  );
  return items;
}

function selectionPopup() {
  if (selectionPopupEl) return selectionPopupEl;
  const box = document.createElement("div");
  box.className = "selection-popup hidden";
  document.body.appendChild(box);
  selectionPopupEl = box;
  return box;
}

function hideSelectionPopup() {
  selectionPopupEl?.classList.add("hidden");
  selectionPopupText = "";
  selectionPopupSource = null;
}

// Keep the menu inside the window, the literal ask ("shows the Popup buttons
// within the application window").
//
// `.action-menu` is `position: absolute; right: 0; top: calc(100% + 4px)`,
// which is right for a kebab sitting in a card near the top of a page and
// wrong for one that can appear anywhere, including two lines above the
// footer. Measured after opening, the same way `buildMenuGroupButton` already
// decides which side a submenu flies out to, and using the same
// measure-then-classify shape rather than a second mechanism.
function clampSelectionMenu(menu) {
  menu.classList.remove("menu-flip-up", "menu-flip-left");
  //: **A menu that has left its box is already placed, and flipping it here
  //: collapses it.** Reported: "when I highlight text and the popup kebab
  //: button appears, the first time I click it, a little collapsed line
  //: appears below it, then I need to click the button to close the popup and
  //: reopen it for it to actually show".
  //:
  //: `openActionMenu` calls `escapeMenuIfClipped` first, which reparents a
  //: clipped menu to `<body>`, makes it `position: fixed` and writes an
  //: explicit `top`. `.menu-flip-up` is `top: auto; bottom: calc(100% + 4px)`,
  //: written for a menu positioned against its own offset parent; on an
  //: escaped menu that `100%` resolves against the viewport, so the rule asks
  //: for a box whose bottom edge is four pixels above the top of the screen
  //: and the auto-height box collapses to its own padding. That is the strip
  //: in the report, and it is the same over-constraint
  //: `escapeMenuIfClipped` already guards against for `action-menu-flip`,
  //: one line of which says so: "Both at once over-constrains an auto-height
  //: box, which reproduced as the menu collapsing to its own padding."
  //:
  //: The second click appears to fix it because by then `_escapedHome` is set,
  //: `escapeMenuIfClipped` returns early, and whichever branch runs next
  //: happens not to add the class.
  //:
  //: Nothing is lost by leaving early: `placeEscapedMenu` positions the menu
  //: against the viewport directly, which is strictly better than choosing
  //: between two fixed anchors, and it is what this function is trying to
  //: approximate.
  if (menu.classList.contains("action-menu-escaped") || menu._escapedHome) return;
  const margin = 8;
  let rect = menu.getBoundingClientRect();
  if (rect.bottom > window.innerHeight - margin) menu.classList.add("menu-flip-up");
  rect = menu.getBoundingClientRect();
  if (rect.left < margin) menu.classList.add("menu-flip-left");
}

function showSelectionPopupAt(rect, text, source, point) {
  const box = selectionPopup();
  //: Reported: "I have to click it twice for it to actually properly
  //: expand". The click on the ⋯ opener ends in a `selectionchange` (the
  //: selection is unchanged, the event still fires), which re-entered here
  //: and rebuilt the popup, closed, over the menu that had just opened. The
  //: same selection with its menu open is left exactly as it is.
  if (
    !box.classList.contains("hidden") &&
    selectionPopupText === text &&
    selectionPopupSource === source &&
    box.querySelector(".action-menu:not(.hidden)")
  ) {
    return;
  }
  selectionPopupText = text;
  selectionPopupSource = source;

  // Rebuilt per selection: the item list depends on whether this passage has
  // a source and on whether the model is up.
  box.replaceChildren();
  const kebab = kebabMenu(selectionMenuItems(), "Actions for the selected text");
  box.appendChild(kebab);
  const opener = kebab.querySelector("[aria-haspopup]");
  const menu = kebab.querySelector(".action-menu");
  // Clicking the opener must not clear the selection underneath it. The old
  // three-button bar did this per button for the same reason; the text itself
  // is already captured above, but keeping the visible selection is what makes
  // the menu feel attached to it rather than to nothing.
  opener?.addEventListener("mousedown", (e) => e.preventDefault());
  opener?.addEventListener("click", () => {
    if (!menu.classList.contains("hidden")) clampSelectionMenu(menu);
  });

  // Position *before* revealing. Removing `hidden` first: which is what this
  // used to do: paints one frame of a `position: fixed` element that has no
  // left/top yet, i.e. at the bottom of `<body>`, as a visible flash.
  box.style.visibility = "hidden";
  box.classList.remove("hidden");
  const margin = 8;
  const boxRect = box.getBoundingClientRect();
  // Note the bound order: `max(margin, min(wanted, limit))`. Written the other
  // way round (`min(max(...), limit)`) a box wider than the viewport produces
  // a limit below the floor, `min` wins, and the popup lands off-screen left.
  // Anchored to the selection's top-right corner, just clear of the last
  // character. Asked for directly ("appear to the top right of the selection
  // while still remaining within the screen/window"), and it is the better
  // anchor than the centre this used to use: centred, the kebab drifts as the
  // selection grows, so it is never in the same place twice and it sits over
  // the middle of what you just highlighted. The right-hand end is where the
  // cursor already is when a left-to-right drag finishes.
  //
  // Both clamps keep the bound order `max(margin, min(wanted, limit))`, see
  // the note below on why the other way round puts it off-screen.
  // The cursor when we have one, the selection's right-hand end when we do
  // not (keyboard selections, and any caller without a pointer event).
  const anchorX = point ? point.x : rect.right;
  const anchorY = point ? point.y : rect.top;
  const left = Math.max(
    margin,
    Math.min(anchorX + 4, window.innerWidth - boxRect.width - margin)
  );
  let wantedTop = anchorY - boxRect.height - margin;
  // No room above the anchor, drop below it instead.
  if (wantedTop < margin) wantedTop = (point ? point.y : rect.bottom) + margin;
  const top = Math.max(
    margin,
    Math.min(wantedTop, window.innerHeight - boxRect.height - margin)
  );
  box.style.left = `${left}px`;
  box.style.top = `${top}px`;
  box.style.visibility = "";
}

// Whether a selection is one this popup should offer to act on.
//
// Both ends are checked, not just `anchorNode`. A drag that starts in prose
// and ends inside a textarea (or the reverse) is one selection with two
// different homes, and testing only the anchor let the popup appear over a
// form field half the time, which is exactly the case the denylist exists
// to prevent.
function selectionIsActionable(selection) {
  const ends = [selection.anchorNode, selection.focusNode];
  for (const node of ends) {
    const el = node && (node.nodeType === 1 ? node : node.parentElement);
    if (!el || el.closest(SELECTION_POPUP_EXCLUDED)) return false;
  }
  return true;
}

// Where the pointer was when the selection finished, or null.
//
// Asked for directly: the kebab should appear off the top-right of the
// *cursor*, not of the highlighted text. Those differ a lot on a multi-line
// selection: the range's corner can be half a screen from where the user
// actually let go, which is the one place they are already looking.
//
// Only a pointer can answer this: a keyboard selection (Shift+Arrow) and a
// touch long-press dispatch `selectionchange` with no coordinates at all, so
// those keep the range-rectangle anchoring. Cleared on keydown so a mouse
// selection followed by Shift+Arrow does not keep using a stale point.
let selectionPointerPoint = null;

function syncSelectionPopup() {
  // Text fields first. Asked for twice ("the ellipse button doesnt appear
  // when I highlight text in textboxes"), the editor is a <textarea>, whose
  // selection lives on the element rather than in the DOM selection, so the
  // rendered-content path below can never see it.
  const field = fieldSelection();
  if (field) {
    selectionPopupField = field;
    // A textarea has no range rectangle to anchor to, the browser exposes no
    // geometry for a selection inside one, so the pointer is the anchor when
    // there is one, and the field's own box is the fallback for a keyboard
    // selection. Passing the field rect as `rect` keeps showSelectionPopupAt's
    // existing "top-right of the selection" logic working unchanged.
    showSelectionPopupAt(
      field.el.getBoundingClientRect(),
      field.text,
      null,
      selectionPointerPoint
    );
    return;
  }

  const selection = window.getSelection();
  const text = (selection?.toString() || "").trim();
  if (!text || selection.isCollapsed || !selectionIsActionable(selection)) {
    // Don't yank the popup away while its own menu is open, the selection is
    // often cleared as a side effect of interacting with the menu.
    if (!selectionPopupEl?.querySelector(".action-menu:not(.hidden)")) hideSelectionPopup();
    return;
  }
  selectionPopupField = null;
  showSelectionPopupAt(
    selection.getRangeAt(0).getBoundingClientRect(),
    text,
    selectionSource(selection.anchorNode),
    selectionPointerPoint
  );
}

function initSelectionPopup() {
  // **Three ways in, because there used to be one.** `mouseup` alone meant the
  // popup did not exist for anyone selecting by touch (a long-press drag on a
  // phone dispatches `selectionchange`, not a useful `mouseup`) or by keyboard
  // (Shift+Arrow dispatches neither): so the app's richest capture surface
  // was mouse-only, on an app that ships a PWA manifest and a mobile layout.
  //
  // `selectionchange` fires continuously *during* a drag, so it is debounced:
  // repositioning the popup on every intermediate range is both wasteful and
  // visually noisy. `mouseup` stays as the immediate path so a mouse selection
  // still feels instant rather than delayed by the debounce.
  document.addEventListener("mouseup", (event) => {
    if (event.target.closest(".selection-popup")) return;
    selectionPointerPoint = { x: event.clientX, y: event.clientY };
    syncSelectionPopup();
  });
  // Touch releases carry coordinates too, on the changedTouches list rather
  // than the event itself, a long-press drag should anchor to the finger for
  // the same reason a mouse selection anchors to the cursor.
  document.addEventListener("touchend", (event) => {
    const touch = event.changedTouches && event.changedTouches[0];
    if (touch) selectionPointerPoint = { x: touch.clientX, y: touch.clientY };
  });
  // A keyboard selection has no pointer, so fall back to the range rectangle
  // rather than anchoring to wherever the mouse happened to be last.
  document.addEventListener("keydown", (event) => {
    if (event.shiftKey || event.key === "Escape") selectionPointerPoint = null;
  });

  let selectionSettleTimer;
  document.addEventListener("selectionchange", () => {
    clearTimeout(selectionSettleTimer);
    selectionSettleTimer = setTimeout(syncSelectionPopup, 200);
  });

  document.addEventListener("mousedown", (event) => {
    if (!event.target.closest(".selection-popup")) hideSelectionPopup();
  });

  document.addEventListener("keydown", (event) => {
    if (event.key === "Escape") hideSelectionPopup();
  });
  window.addEventListener("scroll", hideSelectionPopup, true);
  window.addEventListener("resize", hideSelectionPopup);
}

// Open the selection menu from the keyboard, for a selection made with
// Shift+Arrow. Without this the whole feature is unreachable without a mouse:
// the popup can now *appear* from a keyboard selection (selectionchange fires
// for those too), but its menu still needed a pointer to open.
function openSelectionMenuFromKeyboard() {
  syncSelectionPopup();
  if (!selectionPopupText) {
    toast("Select some text first, then press this again.");
    return;
  }
  const opener = selectionPopupEl?.querySelector("[aria-haspopup]");
  const menu = selectionPopupEl?.querySelector(".action-menu");
  if (!opener || !menu) return;
  openActionMenu(menu, opener);
  clampSelectionMenu(menu);
}

async function downloadAttachment(attachment) {
  const response = await api(`/files/${attachment.id}`);
  await saveFile(attachment.filename, await response.blob());
}

let relatedOpenId = null; // entry currently showing its similar notes

async function toggleRelated(entry) {
  relatedOpenId = relatedOpenId === entry.id ? null : entry.id;
  renderEntries();
  if (relatedOpenId !== entry.id) return;
  const related = await apiJson(`/entries/${entry.id}/related`).catch(() => []);
  const card = document.querySelector(`#entry-list li[data-id="${entry.id}"]`);
  if (!card || relatedOpenId !== entry.id) return;
  const row = document.createElement("div");
  row.className = "entry-links";
  const label = document.createElement("span");
  label.className = "muted";
  label.textContent = related.length ? "Similar:" : "No similar notes found.";
  row.appendChild(label);
  for (const other of related) {
    row.appendChild(similarNoteRow(entry, other, () => {
      // Nothing else on this card changes, so re-rendering the whole list
      // would only cost the open panel its place.
      if (!row.querySelector(".entry-related-row")) {
        label.textContent = "All similar notes are linked.";
      }
    }));
  }
  card.appendChild(row);
}

// One similar note, with the button that turns it into a real link.
//
// Shared by both places this app shows "≈ Similar", the panel that stays
// open while a note is being edited, and the "≈ Similar notes" menu item on
// a note card. They were already two near-identical loops; adding an action
// to only one of them is exactly how the two would have drifted, and the
// ask named the card one specifically ("like in the similar notes shown in
// the notes tab").
//
// A button, not something either view does on its own: `≈` is a resemblance
// the embedding noticed, while a link is a claim the user makes. The reason
// is deduced server-side for a pair this similar (create_link's
// AUTO_REASON_THRESHOLD) and stays editable wherever links are shown, so
// nothing is asked for at this point.
function similarNoteRow(entry, other, onLinked) {
  const preview = other.content.length > 50 ? other.content.slice(0, 49) + "…" : other.content;
  const wrap = document.createElement("span");
  wrap.className = "entry-related-row";
  const relChip = chip("", "link", () => flashEntry(other.id));
  relChip.appendChild(document.createTextNode("≈ "));
  const previewSpan = document.createElement("span");
  renderInlineMarkdown(previewSpan, preview, [], true);
  relChip.appendChild(previewSpan);
  wrap.appendChild(relChip);

  const linkBtn = smallButton("ph:link Link", `Link this note to “${preview}”`, async () => {
    linkBtn.disabled = true;
    try {
      await apiJson(`/entries/${entry.id}/links`, {
        method: "POST",
        body: JSON.stringify({ target_id: other.id }),
      });
      toast("Linked.");
      wrap.remove();
      onLinked?.();
    } catch (error) {
      linkBtn.disabled = false;
      toast(error.message || "Couldn't link those notes.", true);
    }
  });
  linkBtn.classList.add("entry-related-link-btn");
  wrap.appendChild(linkBtn);
  return wrap;
}

//: **The formatting row the note edit form never had.**
//:
//: Editing an existing note is the most common editing action in a notebook,
//: and it was the app's poorest surface by a distance: a bare three-row
//: textarea with no toolbar, no "/" menu and no selection bar, while the
//: composer beside it and the document editor both had all three. That is
//: most of what *"the editors feel very fake and just rudimentary"* is about.
//:
//: The same `data-md` contract the other two toolbars use, wired here rather
//: than through `initMarkdownToolbars` (documents.js) because that runs once
//: over the markup at load and this row is built each time a note is opened.
//: The same set the document editor's strip carries (minus colours), in
//: the same groups: asked for: "the ui and features when editing a note
//: need to be updated with the new upgraded formatting toolbar". `null`
//: entries are group separators.
const NOTE_EDIT_TOOLBAR = [
  { md: "h1", label: "ph:text-h-one", title: "Heading 1 (Ctrl+1)" },
  { md: "h2", label: "ph:text-h-two", title: "Heading 2 (Ctrl+2)" },
  { md: "h3", label: "ph:text-h-three", title: "Heading 3 (Ctrl+3)" },
  null,
  { md: "bold", label: "ph:text-b", title: "Bold (Ctrl+B)" },
  { md: "italic", label: "ph:text-italic", title: "Italic (Ctrl+I)" },
  { md: "strike", label: "ph:text-strikethrough", title: "Strikethrough" },
  { md: "highlight", label: "ph:highlighter", title: "Highlight" },
  { md: "code", label: "ph:code", title: "Inline code (Ctrl+E)" },
  { md: "clearformat", label: "ph:eraser", title: "Clear highlight and colour" },
  null,
  { md: "ul", label: "ph:list-bullets", title: "Bulleted list" },
  { md: "ol", label: "ph:list-numbers", title: "Numbered list" },
  { md: "task", label: "ph:check-square", title: "Task list" },
  { md: "quote", label: "ph:quotes", title: "Quote" },
  null,
  { md: "link", label: "ph:link", title: "Link" },
  { md: "table", label: "ph:table", title: "Table (Tab moves between cells)" },
  { md: "codeblock", label: "ph:brackets-curly", title: "Code block" },
  { md: "hr", label: "ph:minus", title: "Divider" },
];

function noteEditToolbar(boxId) {
  //: **The same strip as the capture box, cloned**, reported: "the toolbar
  //: isn't the same as the note capture and documents". The capture strip
  //: (`#note-toolbar`) is the source of truth; a clone drops the extras the
  //: mount appended (their listeners do not survive cloning) and is wired
  //: fresh by `wireMarkdownToolbar`, which mounts them again. The hand-built
  //: list below is only the fallback for a page without that strip.
  const source = document.getElementById("note-toolbar");
  if (source && typeof wireMarkdownToolbar === "function") {
    const clone = source.cloneNode(true);
    clone.removeAttribute("id");
    //: `note-toolbar` is kept on the clone: it is what makes this the
    //: *composer's* strip rather than the full-page editor's, and dropping it
    //: gave a form inside a note card the document editor's own chrome padding
    //: (measured 91px against the composer's 88 at the same width, both above
    //: a small box). Reported with the capture strip beside it.
    clone.className = "doc-toolbar note-toolbar note-edit-toolbar";
    clone.setAttribute("aria-label", "Formatting");
    for (const extra of clone.querySelectorAll("[data-md-extra]")) extra.remove();
    //: **The Preview button stays in the strip.** It used to be cut out of
    //: the clone because the edit form carried a separate Write / Preview
    //: pill of its own -- which is precisely what the report was about:
    //: "if the formatting bar was the same, the preview button would be in
    //: it". Counted in the browser, the clone came out at 60 controls
    //: against the capture strip's 61, and Preview was the one missing. It
    //: is marked here because the id is stripped two lines down, and
    //: renderEditForm needs to find it again to wire it to *this* note's
    //: preview pane.
    clone.querySelector("#entry-preview-toggle")?.setAttribute("data-note-preview", "1");
    //: **Every id goes.** A clone carries the capture strip's ids, and two
    //: elements with one id means `document.getElementById` hands back the
    //: *capture* toolbar's control: so the edit form's dropdowns opened and
    //: then applied their formatting to the capture box instead of the note
    //: being edited (reported: "none of the toolbar dropdowns work"). Nothing
    //: in `wireMarkdownToolbar` needs an id; it walks elements.
    for (const el of clone.querySelectorAll("[id]")) el.removeAttribute("id");
    delete clone.dataset.mdExtras;
    clone.dataset.mdTarget = boxId;
    //: The wrap/collapse group is appended by `mountDocToolbarControls`, so a
    //: clone carries a *dead* copy of it -- two arrow buttons whose listeners
    //: did not survive cloning -- and, because it was cloned in place rather
    //: than appended, it sat mid-strip where the capture bar's sits last.
    //: Dropped and re-mounted, which is the same trick `data-md-extra` plays
    //: for the dropdown menus.
    clone.querySelector(".doc-toolbar-tools")?.remove();
    wireMarkdownToolbar(clone);
    if (typeof mountDocToolbarControlsFor === "function") mountDocToolbarControlsFor(clone);
    return clone;
  }
  const bar = document.createElement("div");
  bar.className = "doc-toolbar note-toolbar note-edit-toolbar";
  bar.setAttribute("role", "toolbar");
  bar.setAttribute("aria-label", "Formatting");
  for (const action of NOTE_EDIT_TOOLBAR) {
    if (!action) {
      const sep = document.createElement("span");
      sep.className = "doc-toolbar-sep";
      sep.setAttribute("aria-hidden", "true");
      bar.appendChild(sep);
      continue;
    }
    const button = document.createElement("button");
    button.type = "button";
    button.dataset.md = action.md;
    button.title = action.title;
    button.setAttribute("aria-label", action.title);
    setLabel(button, action.label);
    //: mousedown-preventDefault keeps the caret in the textarea, the same
    //: rule `initMarkdownToolbars` and the selection bar both follow, and for
    //: the same reason: a click moves focus first and the selection is gone.
    button.addEventListener("mousedown", (event) => event.preventDefault());
    button.addEventListener("click", () => applyMarkdown(action.md, boxId));
    bar.appendChild(button);
  }
  return bar;
}

function renderEditForm(li, entry) {
  const textarea = document.createElement("textarea");
  textarea.rows = 3;
  textarea.value = entry.content;
  //: A stable id, because three separate features key off one: the "/" menu
  //: and the `[[` autocomplete (EDITOR_SURFACES in editor.js), the selection
  //: bar, and this form's own toolbar. Safe to be a constant rather than a
  //: per-note id: `editingId` allows exactly one open edit form at a time.
  textarea.id = "entry-edit-content";
  textarea.className = "note-edit-box";
  //: Ctrl+B/Ctrl+I/Ctrl+Shift+S, same as the capture box (documents.js:
  //: `wireMdFormatShortcuts`). Passed the element itself, not its id: this
  //: textarea is not in the document yet, and a fresh one exists every
  //: time a note is opened for editing, so this runs on every open rather
  //: than once at boot.
  if (typeof wireMdFormatShortcuts === "function") wireMdFormatShortcuts(textarea);
  //: Three rows is a form field; a note is prose. Grows with its content the
  //: way the composer does, up to the same shared ceiling.
  textarea.addEventListener("input", () => autoGrow(textarea));
  //: `requestAnimationFrame`, not `queueMicrotask`: a microtask runs before
  //: the browser has laid anything out, and `autoGrow` reads `scrollHeight`,
  //: which is 0 on an element that is not yet in the document, measured, the
  //: box stayed at its three-row height with the note scrolling inside it.
  //: Also on focus, because a note opened while its list was hidden (a tab
  //: switch, a filter) is laid out only when it becomes visible.
  textarea.addEventListener("focus", () => autoGrow(textarea));
  requestAnimationFrame(() => autoGrow(textarea));

  const tagsInput = document.createElement("input");
  tagsInput.type = "text";
  tagsInput.placeholder = "Tags, comma separated";
  tagsInput.value = entry.tags.join(", ");

  const categorySelect = document.createElement("select");
  fillCategoryOptions(categorySelect, entry.category);

  const row = document.createElement("div");
  row.className = "row";
  row.appendChild(
    smallButton(
      "Save changes",
      "Save your corrections",
      async () => {
        const category = await resolveCategoryChoice(categorySelect);
        if (category === undefined) return; // user cancelled the prompt
        const before = { content: entry.content, category: entry.category, tags: entry.tags };
        const after = {
          content: textarea.value.trim() || entry.content,
          category,
          tags: tagsInput.value.split(",").map((t) => t.trim()).filter(Boolean),
        };
        await api(`/entries/${entry.id}`, { method: "PUT", body: JSON.stringify(after) });
        editingId = null;
        toast("Entry updated.");
        await loadEntries();
        pushEntryPutUndo(entry.id, "Edited a note", before, after);
      },
      false
    )
  );
  row.appendChild(
    smallButton("Cancel", "Discard changes", () => {
      editingId = null;
      renderEntries();
    })
  );

  //: One meta row, tags, category, then Save/Cancel at the right, instead
  //: of three stacked full-width rows under the text (reported with a
  //: screenshot: "better ui structure").
  const meta = document.createElement("div");
  meta.className = "note-edit-meta";
  row.classList.add("note-edit-actions");
  meta.append(tagsInput, categorySelect, row);
  const toolbarEl = noteEditToolbar(textarea.id);
  //: Preview: reported: "there is no preview", then, once there was one,
  //: "if the formatting bar was the same, the preview button would be in
  //: it". So there is no second Write / Preview control any more: the
  //: cloned strip's own Preview button is the switch, exactly as in the
  //: capture box and the document editor, and it renders the textarea's
  //: current text with the same renderer every note card uses.
  const previewBtn = toolbarEl.querySelector("[data-note-preview]");
  const preview = document.createElement("div");
  preview.className = "markdown-body note-edit-preview hidden";
  const setView = (mode) => {
    const showPreview = mode === "preview";
    if (showPreview) renderMarkdown(preview, textarea.value);
    preview.classList.toggle("hidden", !showPreview);
    textarea.classList.toggle("hidden", showPreview);
    if (previewBtn) {
      //: `is-active` is what the stylesheet paints a pressed toolbar toggle
      //: with (`.doc-toolbar-toggle.is-active`, 01-forms-settings.css) and what
      //: the capture strip's own button carries; `active` was a second name for
      //: the same state that nothing draws, so this button looked unpressed in
      //: preview while the capture one looked pressed. Both are written, since
      //: the clone can arrive carrying either.
      previewBtn.classList.toggle("is-active", showPreview);
      previewBtn.classList.toggle("active", showPreview);
      previewBtn.setAttribute("aria-pressed", String(showPreview));
    }
    if (!showPreview) textarea.focus();
  };
  previewBtn?.addEventListener("click", () => setView(previewBtn.getAttribute("aria-pressed") === "true" ? "write" : "preview"));
  //: **The clone carries the capture strip's state, including this button's.**
  //: This toolbar is a `cloneNode(true)` of `#note-toolbar` (see
  //: `noteEditToolbar`), so a form opened while the capture box is in preview
  //: arrives with Preview already pressed while showing the textarea, and the
  //: first click on it then reads as doing nothing. Measured while
  //: reproducing INBOX 119 on :8895: `aria-pressed="true"` on a form whose
  //: box was visible. The state is reset rather than `setView("write")` called:
  //: that would focus the textarea, and opening a note for editing does not
  //: otherwise move the caret into it.
  if (previewBtn?.getAttribute("aria-pressed") === "true") {
    previewBtn.classList.remove("is-active", "active");
    previewBtn.setAttribute("aria-pressed", "false");
  }
  //: Attachment cards for whatever this note already carries: rename its
  //: caption, generate one, or remove it, and removing takes the markdown
  //: with it, in the edit form exactly as in the capture box.
  const chipsHost = document.createElement("div");
  chipsHost.className = "row attachment-chips hidden";
  chipsHost.id = "entry-edit-attachment-chips";
  li.append(toolbarEl, textarea, preview, chipsHost, meta);
  // The same line-number gutter the capture box and the documents editor
  // carry (documents.js `mountGutterFor`); it follows the one remembered
  // choice, so a person who turned numbers on in Capture sees them here too.
  //: On the next frame, not now: this <li> is still detached (`entryItem`
  //: returns it to the list renderer), and `applyDocGutter` walks the
  //: document to set the strip button's pressed state: measured, the button
  //: opened with no state and no title until the first click without this.
  if (typeof mountGutterFor === "function") {
    mountGutterFor(textarea);
    requestAnimationFrame(applyDocGutter);
  }
  renderEntryAttachmentChips(textarea, chipsHost);
  textarea.addEventListener("input", () => renderEntryAttachmentChips(textarea, chipsHost));
  renderRelatedWhileEditing(li, entry);
  renderNoteBookmarksWhileEditing(li, entry);
}

// **A related-notes panel, live while a note is open for editing**, asked
// for as a competitor gap (Mem.ai's own "AI Thought Partner" pitch keeps a
// similar-notes rail visible continuously while writing, not behind a
// click). This app already had the same signal one click away
// (`toggleRelated`'s "≈ Similar notes" menu item, same `/entries/{id}/related`
// endpoint): the gap was that it stayed hidden until asked for, so it read
// as a lookup rather than a thing the app was already thinking about. Shown
// automatically the moment the edit form opens, not gated behind a second
// interaction; a note with nothing similar says so rather than leaving a
// blank space that looks broken.
async function renderRelatedWhileEditing(li, entry) {
  const panel = document.createElement("div");
  panel.className = "entry-related-live muted text-sm";
  panel.textContent = "Finding related notes…";
  li.appendChild(panel);
  let related;
  try {
    related = await apiJson(`/entries/${entry.id}/related`);
  } catch {
    panel.remove(); // a failed lookup says nothing rather than "no notes found"
    return;
  }
  // The form may have closed (Save/Cancel) or moved on to a different note
  // while this was in flight.
  if (editingId !== entry.id || !panel.isConnected) return;
  panel.replaceChildren();
  if (!related.length) {
    panel.textContent = "No related notes yet.";
    return;
  }
  const label = document.createElement("span");
  label.textContent = "Related: ";
  panel.appendChild(label);
  for (const other of related) {
    panel.appendChild(similarNoteRow(entry, other, () => {
      if (!panel.querySelector(".entry-related-row")) {
        panel.textContent = "All related notes are linked.";
      }
    }));
  }
}

// **A note's References** (§30, directly requested: "attach a bookmark to
// a note... show up in References"): the saved-links half of what a note
// can point at, alongside `entry.links`' [[wiki links]] to other notes.
// Its own small panel and its own endpoint (`/entries/{id}/bookmarks`),
// not folded into `entry.links`, a Bookmark isn't an Entry (see the
// Bookmark model's own docstring), so this is a second, parallel kind of
// reference rather than a variant of the first.
async function renderNoteBookmarksWhileEditing(li, entry) {
  const panel = document.createElement("div");
  panel.className = "entry-related-live muted text-sm";
  li.appendChild(panel);

  const attachButton = document.createElement("button");
  attachButton.type = "button";
  attachButton.className = "ghost small";
  setLabel(attachButton, "ph:link Attach a link");
  attachButton.addEventListener("click", () => openBookmarkAttachPicker(entry, panel));

  async function refresh() {
    let attached;
    try {
      attached = await apiJson(`/entries/${entry.id}/bookmarks`);
    } catch {
      return;
    }
    if (editingId !== entry.id || !panel.isConnected) return;
    panel.replaceChildren();
    if (attached.length) {
      const label = document.createElement("span");
      label.textContent = "References: ";
      panel.appendChild(label);
      for (const bookmark of attached) {
        const bmChip = chip(`ph:link ${bookmark.title || bookmark.url}`, "link", () =>
          window.open(bookmark.url, "_blank", "noopener,noreferrer")
        );
        bmChip.title = bookmark.url;
        const detach = document.createElement("span");
        detach.className = "unlink";
        setLabel(detach, "ph:x"); // raw "×" glyph vs Phosphor icon font mismatch mis-centers the icon
        detach.title = "Remove this reference";
        detach.setAttribute("aria-label", `Remove reference to ${bookmark.title || bookmark.url}`);
        detach.addEventListener("click", async (e) => {
          e.stopPropagation();
          await apiJson(`/entries/${entry.id}/bookmarks/${bookmark.id}`, { method: "DELETE" });
          refresh();
        });
        makeUnlinkAccessible(detach);
        bmChip.appendChild(detach);
        panel.appendChild(bmChip);
      }
    }
    panel.appendChild(attachButton);
  }
  await refresh();
}

async function openBookmarkAttachPicker(entry, panel) {
  let all;
  try {
    all = await apiJson("/bookmarks");
  } catch (error) {
    toast(error.message, true);
    return;
  }
  if (!all.length) {
    toast("No saved links yet, add one in Library → Links first.");
    return;
  }
  const select = document.createElement("select");
  select.className = "bookmark-attach-picker";
  const placeholder = document.createElement("option");
  placeholder.textContent = "Pick a saved link…";
  placeholder.value = "";
  select.appendChild(placeholder);
  for (const bookmark of all) {
    const option = document.createElement("option");
    option.value = String(bookmark.id);
    option.textContent = bookmark.title || bookmark.url;
    select.appendChild(option);
  }
  select.addEventListener("change", async () => {
    if (!select.value) return;
    await apiJson(`/entries/${entry.id}/bookmarks`, {
      method: "POST",
      body: JSON.stringify({ bookmark_id: Number(select.value) }),
    });
    select.remove();
    renderNoteBookmarksWhileEditing(panel.parentElement, entry);
  });
  panel.appendChild(select);
  //: `focusSelect`, not `select.focus()`: the native control is out of the tab
  //: order once `enhanceSelect` has replaced it, so the direct call focuses
  //: nothing and this picker opened with the focus on the page body.
  focusSelect(select);
}

// Category <select> shared by capture (guided mode) and the edit form.
function fillCategoryOptions(select, selected) {
  select.replaceChildren();
  const names = [...new Set(allEntries.map((e) => e.category))].sort();
  if (selected === null) {
    const auto = document.createElement("option");
    auto.value = "";
    auto.textContent = "Let the AI decide";
    select.appendChild(auto);
  }
  for (const name of names) {
    const option = document.createElement("option");
    option.value = name;
    option.textContent = name;
    if (name === selected) option.selected = true;
    select.appendChild(option);
  }
  const custom = document.createElement("option");
  custom.value = "__new__";
  custom.textContent = "+ New category…";
  select.appendChild(custom);
}

// "" → null (AI decides); "__new__" → ask for a name; else the value.
// Returns undefined when the user cancels the prompt.
async function resolveCategoryChoice(select) {
  if (select.value === "") return null;
  if (select.value !== "__new__") return select.value;
  // promptDialog resolves to trimmed text, or "" for cancel: one shape for
  // both, so there is no null to check the way window.prompt needed.
  const name = await promptDialog("Name for the new category:", "", { confirmLabel: "Create" });
  return name || undefined;
}

function beginOrCompleteLink(entry) {
  //: **A draft and a saved note cannot be connected**, asked for directly,
  //: and refused by `manager.create_link` whichever route asks. Caught here as
  //: well so the answer arrives before the click that would fail: starting a
  //: link from a draft and hunting for a target, only to be told no at the
  //: end, is the worst order to learn a rule in.
  //:
  //: Two drafts are still fine; the rule is that drafts stay separate from the
  //: notebook, not from each other.
  if (linkSource !== null && linkSource !== entry.id) {
    const source = allEntries.find((e) => e.id === linkSource);
    if (source && Boolean(source.is_draft) !== Boolean(entry.is_draft)) {
      const draftFirst = Boolean(source.is_draft);
      linkSource = null;
      renderEntries();
      toast(
        draftFirst
          ? "A draft can't be linked to a saved note. Save the draft first."
          : "A saved note can't be linked to a draft. Save the draft first.",
        true
      );
      return;
    }
  }
  if (linkSource === null) {
    linkSource = entry.id;
    toast("Now click Link on the entry you want to connect it to (Esc cancels).");
    renderEntries();
    return;
  }
  if (linkSource === entry.id) {
    linkSource = null; // clicked the same one again = cancel
    renderEntries();
    return;
  }
  const source = linkSource;
  const target = entry.id;
  linkSource = null;
  apiJson(`/entries/${source}/links`, {
    method: "POST",
    body: JSON.stringify({ target_id: target }),
  })
    .then((updated) => {
      toast("Linked!");
      let liveLinkId = updated.links.find((l) => l.entry_id === target)?.link_id;
      pushUndo(
        "Linked two notes",
        async () => {
          if (liveLinkId == null) return;
          await api(`/entries/${source}/links/${liveLinkId}`, { method: "DELETE" });
          await loadEntries();
        },
        async () => {
          const redone = await apiJson(`/entries/${source}/links`, {
            method: "POST",
            body: JSON.stringify({ target_id: target }),
          });
          liveLinkId = redone.links.find((l) => l.entry_id === target)?.link_id ?? liveLinkId;
          await loadEntries();
        }
      );
      return loadEntries();
    })
    .catch((error) => {
      toast(error.message, true);
      renderEntries();
    });
}

// Text filter (Wave J): match note content or any tag, case-insensitive.
// --- the notes filter ------------------------------------------------------------
// Same lesson as the server's keyword search: a single substring match means
// the words have to be typed in the order they appear, which nobody can guess.
// This one also understands a few operators, because narrowing by tag or
// category is the thing you actually want once you have more than a few
// hundred notes: and it needs no AI whatsoever.
//
//   tag:work            only notes tagged "work"
//   cat:recipes         only notes in that category (category: also works)
//   is:favourite        favourite (is:pinned too) / private / linked / untagged
//   tags:<2             fewer than 2 tags, also <=, >, >=, = (or bare N)
//   -picnic             notes that do NOT mention "picnic"
//   "exact phrase"      that phrase, verbatim
//
// Anything else is a plain word: all of them must appear, in any order.

// `tags:<2`, `tags:<=1`, `tags:0` and so on: "how many tags", not "which
// ones" (that's plain `tag:`). Asked for directly: a way to find the notes
// that only ever got the janitor's default filing and never a second look,
// since `is:untagged` alone only ever answered the zero case.
const TAG_COUNT_RE = /^tags:(<=|>=|<|>|=)?(\d+)$/;

function parseNoteQuery(raw) {
  const query = {
    words: [],
    phrases: [],
    exclude: [],
    tags: [],
    categories: [],
    flags: [],
    tagCount: null,
  };
  // Pull quoted phrases out first so their spaces don't become word breaks.
  const remainder = (raw || "").replace(/"([^"]+)"/g, (_, phrase) => {
    query.phrases.push(phrase.toLowerCase().trim());
    return " ";
  });
  for (const token of remainder.split(/\s+/)) {
    if (!token) continue;
    const lower = token.toLowerCase();
    const tagCountMatch = TAG_COUNT_RE.exec(lower);
    if (lower.startsWith("tag:")) query.tags.push(lower.slice(4));
    else if (lower.startsWith("category:")) query.categories.push(lower.slice(9));
    else if (lower.startsWith("cat:")) query.categories.push(lower.slice(4));
    else if (lower.startsWith("is:")) query.flags.push(lower.slice(3));
    else if (tagCountMatch) {
      query.tagCount = { op: tagCountMatch[1] || "=", n: Number(tagCountMatch[2]) };
    } else if (lower.startsWith("-") && lower.length > 1) query.exclude.push(lower.slice(1));
    else query.words.push(lower);
  }
  return query;
}

function noteQueryIsEmpty(query) {
  return (
    !query.words.length &&
    !query.phrases.length &&
    !query.exclude.length &&
    !query.tags.length &&
    !query.categories.length &&
    !query.flags.length &&
    !query.tagCount
  );
}

function matchesTagCount(tagCount, n) {
  switch (tagCount.op) {
    case "<":
      return n < tagCount.n;
    case "<=":
      return n <= tagCount.n;
    case ">":
      return n > tagCount.n;
    case ">=":
      return n >= tagCount.n;
    default:
      return n === tagCount.n;
  }
}

function matchesSearch(entry) {
  if (!noteSearch) return true;
  const query = parseNoteQuery(noteSearch);
  if (noteQueryIsEmpty(query)) return true;

  const content = (entry.content || "").toLowerCase();
  const tags = (entry.tags || []).map((t) => t.toLowerCase());
  const category = (entry.category || "").toLowerCase();
  const haystack = `${content} ${tags.join(" ")}`;

  // A tag: or cat: filter is a statement about which notes count at all.
  if (query.tags.length && !query.tags.every((t) => tags.some((tag) => tag.includes(t)))) {
    return false;
  }
  if (query.categories.length && !query.categories.some((c) => category.includes(c))) {
    return false;
  }
  for (const flag of query.flags) {
    //: `is:favourite` is the name the rest of the app now uses; `is:pinned` is
    //: kept because it is in this app's own help text, in saved filters people
    //: already have, and in muscle memory. Two spellings of one flag is a
    //: smaller cost than breaking a filter somebody saved.
    if ((flag === "pinned" || flag === "favourite" || flag === "favourites") && !entry.pinned) {
      return false;
    }
    if (flag === "private" && !entry.is_private) return false;
    if (flag === "linked" && !(entry.links || []).length) return false;
    if (flag === "untagged" && tags.length) return false;
  }
  if (query.tagCount && !matchesTagCount(query.tagCount, tags.length)) return false;
  if (query.exclude.some((word) => haystack.includes(word))) return false;
  if (!query.phrases.every((phrase) => content.includes(phrase))) return false;
  // Every word must appear somewhere, in any order.
  return query.words.every((word) => haystack.includes(word));
}

// Write `text` into `element`, wrapping each matched term in a <mark>.
// Never uses innerHTML: a note containing "<script>" is text, not markup.
// Render note text with [[wiki links]] as clickable chips and search terms
// marked. Splits on the links first so a highlight can't land inside one.
// Inline markdown in note text, and deliberately only the inline kind.
//
// Reported: notes show raw `**text**` while chat answers, documents and the
// dashboard digest all render markdown. They render it with renderMarkdown,
// which also does headings, tables, lists and fenced code, and a list of
// notes rendered that way gets very tall very fast, which is a worse problem
// than the one being fixed. What people actually type in a note is bold, a
// little italic, and the odd `code` span.
//
// Order matters: code spans are matched first and their contents are never
// looked at again, so `**not bold**` inside backticks stays literal.
// Underscore italics are left out on purpose, snake_case_names are common in
// notes and `_` italics would eat them.
//
// Images and links, added after the original four groups rather than before
// them, so existing callers keyed to `m[1]`–`m[4]` (`notePreviewText` below)
// keep working unchanged. This is what an uploaded image actually looks like
// once pasted/dropped/attached (`![name](/media/hash.ext)`, per
// `handleFileUpload`), and until now nothing in the note-card list rendered
// either form at all, so it showed as the literal markdown source, brackets
// and all. Both accept a same-origin relative URL as well as `https?://`:
// unlike `appendInline`'s own link pattern (chat/documents, which only ever
// links *out*), a note's images live at `/media/...` on this same server.
//
// **The two link/image alternatives are length-bounded, and that is not
// cosmetic.** `\[([^\]\n]+)\]\(...\)` against text with an unclosed `[`
// makes the engine consume to the end of the line and back off one
// character at a time looking for a `]` that isn't there: once per start
// position, so O(n²) on a note that is entirely user-controlled text. That
// is CodeQL's `js/polynomial-redos`, and this file's own `[[wiki link]]`
// pattern already bounds itself (`{1,120}`) for exactly this reason. The
// caps are far past any real link (200 characters of link text, 500 of
// URL) and turn the per-position work into a constant.
// `==highlighted text==`, asked for directly ("a highlighting text
// feature in notes and documents"). An inline markdown convention, not a
// new data model: the same choice every other bit of note formatting here
// already made (**bold**, ~~strike~~, [[wiki links]]): a highlight is
// still just characters in the note's own plain-text `content`, so it
// needs no new column, no span-range table, and works everywhere that
// content already goes (search, the AI's own reading of a note, export).
// Bounded the same way `~~…~~` is (excludes its own delimiter and `\n`
// inside the class) rather than the link/image alternatives' explicit
// length caps: the reason those need one (an unbounded `[^\]\n]+` against
// unclosed `[` is O(n²), CodeQL's js/polynomial-redos) doesn't apply to a
// class that already excludes its own closing character.
// The colour set here is the same eight the toolbars offer (MD_COLOURS in
// documents.js) and the same eight that have stylesheet rules. Keeping the
// three in step matters: this listed only six for a while, so picking Red or
// Grey from the highlight menu wrote `==red|text==`, the optional-colour group
// declined to match "red|", and the note rendered the literal text "red|text"
// in a yellow highlight. Adding a colour means all three, or the new one
// silently prints its own name. tests/test_highlight_colours.py pins them.
const INLINE_MD =
  /`([^`\n]+)`|\*\*([^*\n]+?)\*\*|~~([^~\n]+?)~~|==(?:(yellow|green|blue|pink|purple|orange|red|grey)\|)?([^=\n]+?)==|\+\+(yellow|green|blue|pink|purple|orange|red|grey)\|([^+\n]+?)\+\+|\*([^*\n]+?)\*|!\[([^\]\n]{0,200})\]\(([^)\n]{1,500})\)|\[([^\]\n]{1,200})\]\(([^)\n]{1,500})\)/g;

// `appendInline`'s own grammar, before it was merged into renderInlineMarkdown
// below: adds `__bold__`/`_italic_` and bare `https://…` autolinking, and its
// character classes don't stop at a newline. Kept as a **textually separate**
// pattern rather than folded into INLINE_MD behind an "underscore syntax"
// flag applied after matching, appendInline's callers (block-markdown
// lines, already split on "\n" and rejoined with spaces before this ever
// runs) never feed it a newline, so the missing `\n` exclusion is invisible
// in practice, but a shared superset pattern would make renderInlineMarkdown
// start matching `_word_`/bare URLs it doesn't today, splitting its plain
// prose runs differently and changing exactly what substring a caller that
// passes search `terms` ever hands to highlightInto. Two literal patterns,
// selected by `options.underscoreSyntax` below, guarantee neither caller's
// matching behaviour moves at all.
const INLINE_MD_LEGACY =
  /`([^`]+)`|\*\*([^*]+)\*\*|__([^_]+)__|~~([^~]+)~~|==(?:(yellow|green|blue|pink|purple|orange|red|grey)\|)?([^=]+?)==|\+\+(yellow|green|blue|pink|purple|orange|red|grey)\|([^+]+?)\+\+|\*([^*]+)\*|(?<![\w])_([^_]+)_(?![\w])|!\[([^\]]{0,200})\]\(([^)\s]{1,500})\)|\[([^\]]{1,200})\]\(([^)\s]{1,500})\)|(https?:\/\/[^\s)]+)/g;

// Same allowlist an <img src> or <a href> built from note text has to pass:
// an absolute http(s) URL, or a same-origin relative path (one leading
// slash, not two: `//evil.com/x` is also "one string starting with /" but
// is a protocol-relative link off this origin). Rejects `javascript:`,
// `data:`, and anything else a pasted note could contain.
function isRenderableUrl(url) {
  //: `staged:` is this app's own scheme for a picture whose bytes are still
  //: in the browser (see `captureStagedImages`), renderable, because the
  //: preview draws it from the Blob, and never saved, because the save path
  //: rewrites every one of them to a real url first.
  if (typeof url === "string" && url.startsWith(STAGED_URL_PREFIX)) return true;
  return /^https?:\/\//i.test(url) || (url.startsWith("/") && !url.startsWith("//"));
}

// A non-image attachment (handleFileUpload's link-syntax branch) previously
// rendered as a bare link, indistinguishable at a glance from an ordinary
// URL: BACKLOG §4's "genuinely still open" follow-up. Only applied to our
// own /media/ uploads, not arbitrary external links, since a random web
// page's URL extension says nothing reliable about its content.
const ATTACHMENT_ICONS = {
  pdf: "ph-file-pdf", doc: "ph-file-doc", docx: "ph-file-doc", rtf: "ph-file-doc",
  xls: "ph-file-xls", xlsx: "ph-file-xls", csv: "ph-file-csv",
  ppt: "ph-file-ppt", pptx: "ph-file-ppt",
  zip: "ph-file-archive", rar: "ph-file-archive", "7z": "ph-file-archive",
  mp3: "ph-file-audio", wav: "ph-file-audio", ogg: "ph-file-audio", m4a: "ph-file-audio", webm: "ph-file-audio",
  mp4: "ph-file-video", mov: "ph-file-video",
  txt: "ph-file-text", md: "ph-file-md", json: "ph-file-code",
  png: "ph-file-image", jpg: "ph-file-image", jpeg: "ph-file-image",
  gif: "ph-file-image", webp: "ph-file-image", heic: "ph-file-image", heif: "ph-file-image",
};

// `name` is optional and only matters for a `/files/{id}` URL: the
// note-attachment download endpoint, opaque and extension-less by design
// (unlike `/media/<filename>.ext`, which pasted/dropped inline images use).
// Without it, a note's attached PDF/docx/etc. had no extension anywhere in
// its URL to read a type from, so every non-image attachment fell through
// to nothing rendering at all wherever a caller built the URL that way.
function attachmentIconClass(url, name) {
  const source = name || (url.startsWith("/media/") ? url : "");
  if (!source) return null;
  const ext = source.split(".").pop().split(/[?#]/)[0].toLowerCase();
  return ATTACHMENT_ICONS[ext] || "ph-file";
}

//: Extensions the file card labels by name rather than by the generic
//: "File", the type is the second most useful thing about a file after
//: what it is called, and "PDF · Open" reads as a thing you can do where
//: "myfile.pdf" alone reads as text that happens to end in .pdf.
const FILE_KIND_LABELS = {
  pdf: "PDF", doc: "Word", docx: "Word", odt: "Document", rtf: "Document",
  xls: "Sheet", xlsx: "Sheet", ods: "Sheet", csv: "CSV",
  ppt: "Slides", pptx: "Slides", odp: "Slides",
  txt: "Text", md: "Markdown", markdown: "Markdown",
  json: "JSON", xml: "XML", yaml: "YAML", yml: "YAML",
  html: "HTML", htm: "HTML", css: "CSS",
  js: "Code", ts: "Code", jsx: "Code", tsx: "Code", py: "Code", java: "Code",
  c: "Code", h: "Code", cpp: "Code", hpp: "Code", cs: "Code", go: "Code",
  rs: "Code", rb: "Code", php: "Code", sh: "Code", sql: "SQL",
  swift: "Code", kt: "Code",
  zip: "Archive", mp3: "Audio", wav: "Audio", m4a: "Audio",
  mp4: "Video", mov: "Video", webm: "Video",
};

function fileKindLabel(url, name) {
  const source = name || url;
  const ext = source.split(".").pop().split(/[?#]/)[0].toLowerCase();
  return FILE_KIND_LABELS[ext] || "File";
}

/** A file attached to a note, rendered as something you can see and act on.
 *
 * Three affordances, and each one is a thing that was missing rather than a
 * flourish: **open** (the card itself, into the lightbox's document viewer: 
 * the fix for the 401 dead end described at the call site), **save** (the
 * only way to get the bytes out, since a plain link cannot authenticate),
 * and the **type and name**, so a note full of files reads as a list of
 * files instead of a paragraph of blue text.
 *
 * Deliberately not a `<a>` at all. An anchor to `/media/…` is the bug; an
 * anchor with a token in the query string would put an unlock credential
 * into anything that logs or copies a URL. A button that fetches with the
 * header, like every other call in this app, has neither problem.
 */
/** The one-line form of `fileCard`, for a surface too small for a card. */
function fileChip(name, url) {
  const label = name && name !== url ? name : url.split("/").pop();
  const chipEl = document.createElement("span");
  chipEl.className = "chip file-chip";
  setLabel(chipEl, `${(attachmentIconClass(url, name) || "ph-file").replace("ph-", "ph:")} ${label}`);
  chipEl.title = `${fileKindLabel(url, name)}: ${label}`;
  return chipEl;
}

function fileCard(name, url) {
  const label = name && name !== url ? name : url.split("/").pop();
  const card = document.createElement("span");
  card.className = "file-card";

  const open = document.createElement("button");
  open.type = "button";
  open.className = "file-card-open";
  open.title = `Open “${label}”`;
  const icon = document.createElement("i");
  icon.className = `ph ${attachmentIconClass(url, name) || "ph-file"} file-card-icon`;
  icon.setAttribute("aria-hidden", "true");
  const text = document.createElement("span");
  text.className = "file-card-text";
  const nameEl = document.createElement("span");
  nameEl.className = "file-card-name";
  nameEl.textContent = label;
  const kindEl = document.createElement("span");
  kindEl.className = "file-card-kind";
  kindEl.textContent = fileKindLabel(url, name);
  text.append(nameEl, kindEl);
  open.append(icon, text);
  open.addEventListener("click", () => {
    openLightbox([{ filename: label, getUrl: () => mediaSrc(url) }], 0);
  });

  const save = document.createElement("button");
  save.type = "button";
  save.className = "ghost small icon-only file-card-save";
  setLabel(save, "ph:download-simple");
  save.title = `Save “${label}” to disk`;
  save.setAttribute("aria-label", save.title);
  save.addEventListener("click", async (event) => {
    event.stopPropagation();
    try {
      const response = await api(url);
      await saveFile(label, await response.blob());
    } catch (error) {
      toast(error.message || `Couldn't save “${label}”.`, true);
    }
  });

  card.append(open, save);
  return card;
}

// LaTeX escapes that models reach for when they want a symbol (§35H).
//
// Screenshotted: a bullet reading "Jokes $\rightarrow$ Social Skills", with
// the LaTeX printed literally. That is not a markdown gap, the model was
// asked for an arrow and reached for the notation it saw most in training.
// Rendering a whole maths engine for this would be absurd; translating the
// dozen symbols that actually show up costs nothing and covers all of it.
//
// The prompt also asks for plain Unicode, which prevents most of these. This
// is the half that catches the model doing it anyway.
const LATEX_SYMBOLS = {
  rightarrow: "\u2192", to: "\u2192", longrightarrow: "\u27f6", Rightarrow: "\u21d2",
  leftarrow: "\u2190", gets: "\u2190", Leftarrow: "\u21d0",
  leftrightarrow: "\u2194", Leftrightarrow: "\u21d4", uparrow: "\u2191", downarrow: "\u2193",
  times: "\u00d7", div: "\u00f7", pm: "\u00b1", mp: "\u2213", cdot: "\u00b7",
  leq: "\u2264", le: "\u2264", geq: "\u2265", ge: "\u2265",
  neq: "\u2260", ne: "\u2260", approx: "\u2248", equiv: "\u2261", sim: "\u223c",
  ldots: "\u2026", dots: "\u2026", cdots: "\u22ef",
  infty: "\u221e", deg: "\u00b0", bullet: "\u2022", star: "\u2605",
  checkmark: "\u2713", surd: "\u221a", propto: "\u221d", therefore: "\u2234",
  alpha: "\u03b1", beta: "\u03b2", gamma: "\u03b3", delta: "\u03b4",
  lambda: "\u03bb", mu: "\u03bc", pi: "\u03c0", sigma: "\u03c3", omega: "\u03c9",
  Delta: "\u0394", Sigma: "\u03a3", Omega: "\u03a9",
};

function unlatex(text) {
  // The overwhelmingly common case: nothing to do, and not worth two regex
  // passes over every note and every streaming frame to find that out.
  if (!text || (!text.includes("\\") && !text.includes("$"))) return text;
  const swap = (s) =>
    s.replace(/\\([A-Za-z]+)/g, (whole, name) =>
      Object.prototype.hasOwnProperty.call(LATEX_SYMBOLS, name)
        ? LATEX_SYMBOLS[name]
        : whole
    );
  // Inline maths delimiters are dropped only when the span is actually maths
  // *and* everything in it became plain characters.
  //
  // Both halves are load-bearing. Without the first, "cost $5 and $10 today"
  // is a matching span containing no commands, and the dollars vanish, a
  // notebook full of prices is a much more likely thing than a notebook full
  // of LaTeX. Without the second, a span still holding \frac or \sum gets
  // stripped of its delimiters and left as half-translated notation, which is
  // worse than leaving it alone: the user can at least read the source.
  return swap(
    text.replace(/\$([^$\n]{1,200})\$/g, (whole, inner) => {
      if (!/\\[A-Za-z]/.test(inner)) return whole; // not maths: currency, prose
      const plain = swap(inner);
      return /\\[A-Za-z]/.test(plain) ? whole : plain;
    })
  );
}

// `compact`: skip the actual <img> and show the alt text instead, for a
// label-sized surface (a link chip, a document sidebar button) where a
// note's own image markdown would otherwise cram a thumbnail into a spot
// sized for a line of text. The note card's own body always gets the real
// image; everywhere smaller gets the same treatment `notePreviewText`
// already gives one to a plain-text preview.
//
// `options` is where appendInline's five real behavioural differences from
// the note-card grammar live, now that the two hand-rolled parsers (each
// with its own separately maintained `isRenderableUrl` call, per
// ROADMAP.md §0/§2) are one function:
//   - `dismissible` (default true): render an image with the note-card
//     delete/lightbox chrome. appendInline's callers (chat, documents, table
//     cells) pass false: there is no note markdown line for a "remove this
//     image" click to edit there, so they get a plain <img>.
//   - `autolinkBareUrls` (default false): turn a plain `https://…` run into
//     a real link. Off for note cards (unchanged), on for appendInline.
//   - `underscoreSyntax` (default false): also recognize `__bold__`/
//     `_italic_` and bare-URL autolinking, using INLINE_MD_LEGACY instead of
//     INLINE_MD: see that constant's comment for why this is a second
//     literal pattern rather than a superset with the extra alternatives
//     suppressed after matching.
//   - `strikeTag` (default "s"): appendInline's callers always used <del>,
//     not the note-card renderer's <s>; style.css has separate rules for
//     `.entry-content s` vs `.answer/.bubble-answer/.dash-body del`.
//   - `applyLatex` (default true): appendInline never ran unlatex() on its
//     text, so it stays off for that mode to keep behaviour unchanged.
// Every default matches renderInlineMarkdown's original, options-less
// behaviour exactly, so no existing call site needs to change.
// The allow-list for anything a note's own text can turn into an href:
// web links, mail, this app's own paths and in-page anchors. Everything
// else (javascript:, data:, vbscript:, file:) becomes a dead link rather
// than a live one. Kept beside the renderer that needs it.
function safeHref(url) {
  const value = String(url || "").trim();
  if (/^(https?:|mailto:|tel:)/i.test(value)) return value;
  if (/^[/#?.]/.test(value) || !/^[a-z][a-z0-9+.-]*:/i.test(value)) return value;
  return "#";
}

//: **CommonMark's angle-bracket autolink, `<https://example.com>`.** INBOX
//: 81: "Web search results in the Sources dropdown: links rendered as
//: Markdown links", with a screenshot of a model's table showing the raw
//: `<https://...>` text. Neither inline pattern here has ever matched that
//: form, so it fell through to plain prose and the reader saw the brackets.
//:
//: Rewritten to `[url](url)` *before* matching rather than added as another
//: alternative to `INLINE_MD`. That pattern's capture groups are addressed by
//: number in the renderer below, and its own comment records a bug where two
//: indices were off by two and every image in the app rendered "undefined":
//: adding a group in the middle of it is exactly how that happens again. A
//: pre-pass cannot move an index.
//:
//: Only http and https, which is the same allowlist `isRenderableUrl`
//: applies afterwards; the point of the check here is to leave anything else
//: (an HTML tag, `<3`, a generic like `Array<T>`) exactly as it was.
function expandAngleAutolinks(text) {
  return String(text || "").replace(
    /<(https?:\/\/[^\s<>]{1,500})>/g,
    (whole, url) => `[${url}](${url})`,
  );
}

function renderInlineMarkdown(element, text, terms, compact = false, options = {}) {
  const {
    dismissible = true,
    autolinkBareUrls = false,
    underscoreSyntax = false,
    strikeTag = "s",
    applyLatex = true,
  } = options;
  // appendInline never cleared `element`, it only ever appended into a
  // freshly created element, except the task-list-checkbox case, which
  // appends a <input type=checkbox> *before* calling appendInline on the
  // rest of the item text. A `replaceChildren()` here would delete that
  // checkbox out from under it, so the note-card renderer's clear-first
  // behaviour is kept only for its own (non-legacy) callers.
  if (!underscoreSyntax) element.replaceChildren();
  if (applyLatex) text = unlatex(text);
  text = expandAngleAutolinks(text);
  const pattern = new RegExp((underscoreSyntax ? INLINE_MD_LEGACY : INLINE_MD).source, "g");
  let cursor = 0;
  let match;
  while ((match = pattern.exec(text)) !== null) {
    if (match.index > cursor) {
      const chunk = text.slice(cursor, match.index);
      // Same reasoning as the clear-first skip above: appendInline appended
      // plain prose as a bare text node, never wrapped in a <span> (it never
      // had search terms to mark). Keeping that distinction means neither
      // mode's DOM shape moves for its own callers.
      if (underscoreSyntax) {
        element.appendChild(document.createTextNode(chunk));
      } else {
        const before = document.createElement("span");
        highlightInto(before, chunk, terms);
        element.appendChild(before);
      }
    }
    let code, bold, strike, markColour, mark, inkColour, ink, italic, imageAlt, imageUrl, linkText, linkUrl, bareUrl;
    if (underscoreSyntax) {
      let boldStar, boldUnderscore, italicStar, italicUnderscore;
      [
        , code, boldStar, boldUnderscore, strike, markColour, mark, inkColour, ink, italicStar, italicUnderscore,
        imageAlt, imageUrl, linkText, linkUrl, bareUrl,
      ] = match;
      bold = boldStar ?? boldUnderscore;
      italic = italicStar ?? italicUnderscore;
    } else {
      [, code, bold, strike, markColour, mark, inkColour, ink, italic, imageAlt, imageUrl, linkText, linkUrl] = match;
    }
    // Images and links are their own element kinds, not a wrap-in-a-tag like
    // the four above: built and appended directly rather than falling
    // through to the generic `tag`/`node` shape below, since neither one
    // takes searched-term highlighting inside it (an <img> has no text to
    // highlight, and a link's own text isn't split into marks any more than
    // a code span's is).
    if (imageUrl !== undefined) {
      if (compact) {
        element.appendChild(document.createTextNode(imageAlt || "Image"));
      } else if (isRenderableUrl(imageUrl)) {
        if (!dismissible) {
          const img = document.createElement("img");
          img.src = mediaSrc(imageUrl);
          img.alt = imageAlt || "";
          img.className = "entry-inline-image";
          img.loading = "lazy";
          element.appendChild(img);
          cursor = pattern.lastIndex;
          continue;
        }
        const wrapper = document.createElement("span");
        wrapper.className = "thumb-wrap";
        const img = document.createElement("img");
        img.src = mediaSrc(imageUrl);
        img.alt = imageAlt || "";
        img.className = "attachment-thumb";
        img.loading = "lazy";
        img.style.cursor = "zoom-in";
        img.addEventListener("click", (e) => {
          e.stopPropagation();
          openLightbox([{ filename: imageAlt || "Image", getUrl: () => mediaSrc(imageUrl) }], 0);
        });
        const dismissBtn = document.createElement("span");
        dismissBtn.className = "unlink";
        dismissBtn.title = "Remove image from note";
        setLabel(dismissBtn, "ph:x"); // raw "×" glyph vs Phosphor icon font mismatch mis-centers the icon
        // `match` is one `let` binding reused by every pass of the while
        // loop above (a `while` reassigns it, unlike a `for (let x of …)`'s
        // fresh-per-iteration binding): every dismiss button's closure
        // shared the same variable, and by the time anyone actually clicked
        // one, the loop had long since finished with `match` sitting at
        // `null` (the value that ends the `while` condition). Every click
        // threw `Cannot read properties of null (reading '0')` before the
        // confirm dialog could even open, reported as "the remove button
        // doesn't work". Capturing the text this match actually matched
        // into its own const, right here in the loop body, gives each
        // button's closure the value for *its own* image instead of
        // whatever `match` happened to hold after parsing ended.
        const originalText = match[0];
        dismissBtn.addEventListener("click", (e) => {
          e.stopPropagation();
          wrapper.dispatchEvent(new CustomEvent("remove-inline-image", {
            bubbles: true,
            detail: { originalText }
          }));
        });
        makeUnlinkAccessible(dismissBtn);
        wrapper.appendChild(img);
        wrapper.appendChild(dismissBtn);
        // Asked for directly: a deleted image left a broken-image glyph in
        // the note that referenced it, a closable "deleted" box instead.
        // Only dismisses the placeholder from this render; the note's own
        // markdown line is left alone; editing it back out is a further,
        // separate feature.
        img.addEventListener("error", () => {
          const placeholder = document.createElement("span");
          placeholder.className = "entry-inline-image-deleted";
          placeholder.append(document.createTextNode(`${imageAlt || "Image"} deleted`));
          const dismiss = document.createElement("span");
          dismiss.className = "unlink";
          dismiss.title = "Dismiss";
          setLabel(dismiss, "ph:x"); // raw "×" glyph vs Phosphor icon font mismatch mis-centers the icon
          dismiss.addEventListener("click", (e) => { e.stopPropagation(); placeholder.remove(); });
          makeUnlinkAccessible(dismiss);
          placeholder.appendChild(dismiss);
          wrapper.replaceWith(placeholder);
        });
        element.appendChild(wrapper);
      } else {
        element.appendChild(document.createTextNode(match[0]));
      }
      cursor = pattern.lastIndex;
      continue;
    }
    if (linkUrl !== undefined) {
      if (isRenderableUrl(linkUrl)) {
        const iconClass = attachmentIconClass(linkUrl);
        if (iconClass) {
          // **A file, not a link, and this fixes a dead end, not just the
          // looks.** Reported directly: "once I uploaded two files into a
          // note, they became hyperlinked text, I clicked on them, and it
          // took me to a black fode screen with some text about needing to
          // unlock first… there was no way for me to go back except for
          // closing the application entirely."
          //
          // That is exactly what an `<a href="/media/x.pdf">` does here. A
          // plain navigation carries no `X-Auth-Token` header: only
          // `apiJson` and `mediaSrc` attach one: so the browser leaves the
          // single-page app, gets the unlock guard's 401 JSON body, and
          // renders it with its own JSON viewer. The app is gone, and in the
          // desktop shell there is no back button to bring it back.
          //
          // The lightbox already reads this exact file: `show()` sniffs a
          // `/media/…` url that is not an image and hands it to the document
          // viewer, which renders PDFs, Office files, code and plain text
          // through `/media/text`. Nothing routed a note's own files to it, 
          // that missing wire is the whole bug.
          // `compact` is the same label-sized-surface case the image branch
          // above uses it for: a dashboard preview row or a link chip has
          // room for a line of text, not a two-line card with its own
          // buttons. The name and the type still say what it is.
          element.appendChild(
            compact ? fileChip(linkText, linkUrl) : fileCard(linkText, linkUrl)
          );
        } else {
          const a = document.createElement("a");
          // Only schemes a note may point at. A `[x](javascript:...)` link
          // would otherwise be a click-to-run script in a note that came
          // from an import or a shared file; the CSP blocks it today, and
          // this is the second lock in case the CSP is ever loosened.
          a.href = safeHref(linkUrl);
          if (/^https?:\/\//i.test(linkUrl)) {
            a.target = "_blank";
            a.rel = "noopener noreferrer";
          }
          highlightInto(a, linkText, terms);
          element.appendChild(a);
        }
      } else {
        element.appendChild(document.createTextNode(match[0]));
      }
      cursor = pattern.lastIndex;
      continue;
    }
    if (bareUrl !== undefined) {
      if (autolinkBareUrls) {
        const a = document.createElement("a");
        a.href = bareUrl;
        a.target = "_blank";
        a.rel = "noopener noreferrer";
        highlightInto(a, bareUrl, terms);
        element.appendChild(a);
      } else {
        const span = document.createElement("span");
        highlightInto(span, bareUrl, terms);
        element.appendChild(span);
      }
      cursor = pattern.lastIndex;
      continue;
    }
    const tag = code
      ? "code"
      : bold
        ? "strong"
        : strike
          ? strikeTag
          : mark
            ? "mark"
            : ink
              ? "span"
              : "em";
    const node = document.createElement(tag);
    // Distinguishes a `==highlight==` from highlightInto's own <mark> below
    // (used for search-term matches), same tag, different meaning, so they
    // need different styling or a highlighted note reads as "this matched
    // your search" with no search active.
    // `++red|text++`, a foreground colour, the counterpart to the highlight's
    // background one. The colour is part of a class name, never an inline
    // style: this app's CSP rejects inline styles outright (a whole batch of
    // them was found doing nothing once), and a closed allowlist means every
    // colour that can be typed has a theme-aware rule written for it.
    if (ink) node.className = `text-ink text-ink-${inkColour}`;
    if (mark) {
      // `==text==` is the plain (yellow) highlight; `==green|text==` picks one
      // of a small named set. An allowlist baked into the pattern itself, not
      // a free-form colour: the value lands in a class name, and every colour
      // that can appear here therefore has a stylesheet rule written for it
      // (05-sidebars-themes.css) that is theme-aware in both light and dark.
      node.className = markColour
        ? `text-highlight text-highlight-${markColour}`
        : "text-highlight";
    }
    // A code span is literal by definition, so it is never searched-highlighted
    // into pieces: the rest still is, or filtering would stop marking any
    // word that happened to sit inside emphasis.
    if (code) node.textContent = code;
    else highlightInto(node, bold || strike || mark || ink || italic, terms);
    element.appendChild(node);
    cursor = pattern.lastIndex;
  }
  if (cursor < text.length) {
    const rest = text.slice(cursor);
    if (underscoreSyntax) {
      element.appendChild(document.createTextNode(rest));
    } else {
      const restSpan = document.createElement("span");
      highlightInto(restSpan, rest, terms);
      element.appendChild(restSpan);
    }
  }
}

// Inline formatting: **bold**/__bold__, *italic*/_italic_, `code`, ~~strike~~,
// ==highlight==, [text](http…url), images, and bare http(s) URLs. Built with textContent
// only: note/answer text can never inject markup. Was its own ~90-line
// hand-rolled parser with its own `isRenderableUrl` gate call; now a thin
// wrapper over renderInlineMarkdown (ROADMAP.md §0/§2): see that function's
// `options` comment for exactly which behaviours these five overrides
// reproduce and why each one is there.
function appendInline(parent, text) {
  renderInlineMarkdown(parent, text, [], false, {
    dismissible: false,
    autolinkBareUrls: true,
    underscoreSyntax: true,
    // `.answer del`/`.bubble-answer del`/`.dash-body del` (style.css) style
    // this tag specifically: appendInline's own callers always used <del>,
    // not the note-card renderer's <s>, and the CSS was written for that.
    strikeTag: "del",
    applyLatex: false,
  });
}

// Mirrors manager.extract_title's own rule (the first non-blank line, and
// only that line) so the body shown under a title never repeats it, called
// only when the backend has already said this note has a title, so this
// never has to decide on its own whether a line "looks like" a heading.
function bodyWithoutTitleLine(content) {
  const lines = content.split("\n");
  let i = 0;
  while (i < lines.length && lines[i].trim() === "") i++;
  if (i >= lines.length) return content;
  lines.splice(i, 1);
  if (lines[i] !== undefined && lines[i].trim() === "") lines.splice(i, 1);
  return lines.join("\n");
}

// The note a [[wiki link]] names, or null.
//
// One resolver, because there were two: renderNoteText matched notes by the
// opening words and layerDocWikiLinks matched documents by exact title, so the
// same [[name]] meant different things depending on which pane rendered it.
// Notes are matched first and by prefix (that is what applyWikiSuggestion
// inserts: a note's opening words); documents fall back to an exact,
// case-insensitive title. Private notes are never a target: they cannot be
// linked, and resolving to one would leak that it exists.
function resolveWikiTarget(name) {
  const needle = String(name || "").trim().toLowerCase();
  if (!needle) return null;
  const entries = typeof allEntries !== "undefined" ? allEntries : [];
  //: **A vault's links name the file.** An imported note carries the path it
  //: came from, and Obsidian writes `[[Roadmap]]` for `Projects/Roadmap.md`, 
  //: so this is tried first, and matched exactly: a file called "Index"
  //: should not lose to a note that merely opens with the word "index". Same
  //: rule as `find_by_wiki_name` in entry/manager.py, which is what makes the
  //: link the backend stores and the link this pane draws point at one note.
  const vaultNote = entries.find((e) => {
    if (e.is_private || !e.source_path) return false;
    const stem = e.source_path.split("/").pop().replace(/\.(md|markdown)$/i, "");
    return stem.toLowerCase() === needle;
  });
  if (vaultNote) return { kind: "note", entry: vaultNote };
  //: **A board is a link target, and it is not a note.** MINDMAP_PLAN.md §5
  //: item 12 asks for a map chip in note bodies, and the `@`/`[[` picker in
  //: editor.js has offered boards as targets since it was written, so the
  //: link could already be *typed* and resolved to something. What it resolved
  //: to was `{kind: "note"}`, and the click called `flashEntry`, which scrolls
  //: the Notes tab to a row that is not there: a board is filtered out of
  //: every note list in the app. So the link worked, looked like a note, and
  //: went nowhere.
  //:
  //: Matched on the board's *title* with the `# ` stripped, and by prefix on
  //: the raw content underneath, because both forms exist in real notes: the
  //: picker used to insert the whole first line (`[[# My map]]`) and now
  //: inserts the title (`[[My map]]`).
  //:
  //: **Read from the board index, not from `allEntries`.** `GET /entries` is
  //: the notes list and no longer carries boards at all (see its `boards`
  //: parameter, a map called "test" was showing up as a note, reported), so
  //: this used to resolve against a list that will not have the board in it.
  //: `mapBoardIndexCache` is `/whiteboard/boards`, which is the list of
  //: boards by definition, and it is already loaded for the map chips.
  const board = mapBoardTitled(needle);
  if (board) return { kind: "board", entry: board };
  //: **Two ways a note's opening words can be written, and both resolve.** The
  //: `[[` picker inserts the note's first line *verbatim*, `# ` and all, so
  //: matching the content by prefix is what makes `[[# Girl with bell]]`
  //: resolve. Anybody typing a link by hand writes the title they can see,
  //: `[[Girl with bell]]`, and that matched nothing at all: the note's content
  //: starts with the hash, so the prefix test failed on the first character.
  //: Reported by the agent that built the document embeds, which had to avoid
  //: the shape in its own fixture.
  //:
  //: The second comparison strips a leading heading marker from the *content*
  //: rather than adding one to the needle, because the marker is one to six
  //: hashes and any amount of space, and the content is where that is known.
  const opening = (e) => (e.content || "").toLowerCase();
  const openingTitle = (e) => opening(e).replace(/^#{1,6}[ \t]*/, "");
  const notes = entries.filter((e) => !e.is_private && !e.is_board);
  const note =
    notes.find((e) => opening(e).startsWith(needle)) ||
    notes.find((e) => openingTitle(e).startsWith(needle));
  if (note) return { kind: "note", entry: note };
  const documents = typeof editorDocumentCache !== "undefined" ? editorDocumentCache : null;
  const docList = documents || [];
  const doc =
    docList.find((d) => (d.title || "").trim().toLowerCase() === needle) ||
    //: Reported directly: "still cant open note links from the document
    //: editor", on a link whose visible text ended mid-word ("...and
    //: progr"). Exact match only fails both plausible causes of that: a
    //: shorter string was written into the `[[...]]` than the document's
    //: current title (however that happened), or the document was
    //: retitled after the link was made. A prefix match is the same
    //: fallback `note` above already gets for exactly the same reason,
    //: and a link that is a genuine prefix of a longer title is a much
    //: likelier accident than two documents sharing one.
    docList.find((d) => (d.title || "").trim().toLowerCase().startsWith(needle));
  if (doc) return { kind: "document", doc };
  return null;
}

// A note card's text: block constructs first, then the inline pass.
//
// Notes deliberately do not go through renderMarkdown, this pass keeps
// search-term highlighting, which that renderer has no concept of. So the two
// block constructs the "/" menu can insert are handled here explicitly and
// everything else falls through to exactly the inline rendering this function
// always did. When a note contains neither, the DOM produced is identical to
// before, which is why the fall-through appends to `element` directly rather
// than wrapping runs in a container.
function renderNoteText(element, text, terms) {
  element.replaceChildren();
  const lines = String(text ?? "").replace(/\r\n/g, "\n").split("\n");
  let buffer = [];
  const flush = () => {
    if (!buffer.length) return;
    renderNoteInline(element, buffer.join("\n"), terms);
    buffer = [];
  };

  let i = 0;
  while (i < lines.length) {
    const line = lines[i];

    const embedded = line.match(/^\s*!\[\[([^[\]]{1,120})\]\]\s*$/);
    if (embedded) {
      flush();
      element.appendChild(mdEmbedElement(embedded[1].trim(), 0));
      i++;
      continue;
    }

    if (/^\s*>\s?/.test(line)) {
      const quoted = [];
      let j = i;
      while (j < lines.length && /^\s*>\s?/.test(lines[j])) {
        quoted.push(lines[j].replace(/^\s*>\s?/, ""));
        j++;
      }
      const box = mdCalloutElement(quoted, 0);
      if (box) {
        flush();
        element.appendChild(box);
        i = j;
        continue;
      }
      // An ordinary blockquote, not a callout: leave it to the inline pass
      // exactly as it was written, rather than eating the "> " markers.
    }

    buffer.push(line);
    i++;
  }
  flush();
}

// The inline half: [[wiki links]], emphasis, and search-term highlighting.
// Appends to `parent`; does not clear it.
function renderNoteInline(element, text, terms) {
  const pattern = /\[\[([^[\]]{1,120})\]\]/g;
  let cursor = 0;
  let match;
  while ((match = pattern.exec(text)) !== null) {
    if (match.index > cursor) {
      const span = document.createElement("span");
      renderInlineMarkdown(span, text.slice(cursor, match.index), terms);
      element.appendChild(span);
    }
    const name = match[1].trim();
    //: **A link that names a map draws as a map chip** (MINDMAP_PLAN.md §5
    //: item 12: "note bodies"). Resolved here rather than on click, which is
    //: what every other kind still does, because the *shape* of the control
    //: depends on the answer: a chip carries the map's icon and node count,
    //: and neither can be decided after the element is already on screen.
    //: One `find` over `allEntries` per wiki link, on a list that is already
    //: in memory: the same lookup the click handler was doing anyway.
    const mapTarget = resolveWikiTarget(name);
    if (mapTarget && mapTarget.kind === "board") {
      const board = mapBoardById(mapTarget.entry.id) || {
        id: mapTarget.entry.id,
        title: name,
        type: "map",
      };
      element.appendChild(mapChip(board));
      cursor = pattern.lastIndex;
      continue;
    }
    const link = document.createElement("button");
    link.type = "button";
    link.className = "wiki-link";
    const label = wikiLinkLabel(name);
    link.textContent = label;
    link.title = `Go to the note starting "${label}"`;
    link.addEventListener("click", (event) => {
      event.stopPropagation();
      const target = resolveWikiTarget(name);
      if (target && target.kind === "note") flashEntry(target.entry.id);
      else if (target && target.kind === "board") openWhiteboardBoard(target.entry.id);
      else if (target && target.kind === "document") openDocument(target.doc.id);
      // Nothing by that name yet, offer to make it rather than dead-ending.
      // A link you typed on purpose is the clearest possible statement that
      // the thing should exist; making the user go and create it by hand, then
      // come back, is the friction this removes.
      else offerToCreateWikiTarget(name);
    });
    element.appendChild(link);
    cursor = pattern.lastIndex;
  }
  if (cursor < text.length) {
    const span = document.createElement("span");
    renderInlineMarkdown(span, text.slice(cursor), terms);
    element.appendChild(span);
  }
}

//: `terms` is "the words to highlight", and **every caller that has nothing to
//: highlight passes something falsy rather than `[]`**, `chatSourcesPanel`
//: passes a literal `null`, which is what a snippet with no search behind it
//: honestly is. This read `terms.length` directly and threw
//: `Cannot read properties of null (reading 'length')`.
//:
//: The throw is worth recording because of where it landed rather than what it
//: was. `renderInlineMarkdown` is called while a saved conversation's Sources
//: panel is being built, which happens inside `openConversation`, so the
//: exception aborted the rest of that function, including the
//: `loadConversationList()` at its end that repaints the sidebar. Reported as
//: "I clicked on other chat conversations in the chat sidebar but the
//: conversations didnt visibly select in the sidebar": the click worked, the
//: fetch worked, and an unrelated null check three calls down stopped the row
//: from ever being marked. Nothing was logged where anyone would look.
//:
//: Normalised here, at the one place that reads it, rather than at each call
//: site: the next caller to pass `null` should not have to know either.
function highlightInto(element, text, terms) {
  element.replaceChildren();
  if (!terms || !terms.length) {
    element.textContent = text;
    return;
  }
  // One pass, longest terms first so "bread rolls" wins over "bread".
  const ordered = [...terms].sort((a, b) => b.length - a.length);
  const lower = text.toLowerCase();
  let cursor = 0;
  while (cursor < text.length) {
    let bestAt = -1;
    let bestTerm = "";
    for (const term of ordered) {
      const at = lower.indexOf(term, cursor);
      if (at !== -1 && (bestAt === -1 || at < bestAt)) {
        bestAt = at;
        bestTerm = term;
      }
    }
    if (bestAt === -1) {
      element.appendChild(document.createTextNode(text.slice(cursor)));
      return;
    }
    if (bestAt > cursor) {
      element.appendChild(document.createTextNode(text.slice(cursor, bestAt)));
    }
    const mark = document.createElement("mark");
    mark.textContent = text.slice(bestAt, bestAt + bestTerm.length);
    element.appendChild(mark);
    cursor = bestAt + bestTerm.length;
  }
}

// The words worth highlighting in a result, operators aren't text to find.
function searchHighlightTerms() {
  if (!noteSearch) return [];
  const query = parseNoteQuery(noteSearch);
  return [...query.phrases, ...query.words].filter((t) => t.length > 1);
}

// "Why this result", in words rather than a number, from the three scores the
// engine returns with every hit (`search/engine.py`). Asked for by Brief 11
// directly: the list says *matched the title*, *similar meaning*, *linked to
// the open note*, and the exact percentages sit in the tooltip for anyone who
// disagrees with the order. The chip recipe is the one the chat results
// already use (`.chip.result-reason-chip`), not a new look.
function whyThisResultChip(entry) {
  const hit = noteSearchWhy.get(entry.id);
  const words = hit?.explain?.join(" · ");
  if (!words) return null;
  const badge = chip(`ph:sparkle ${words}`, "result-reason-chip result-reason-why");
  const percent = (value) => Math.round((value || 0) * 100);
  badge.title =
    `Why this result: words ${percent(hit.scores?.bm25)}%, ` +
    `meaning ${percent(hit.scores?.cosine)}%, ` +
    `links ${percent(hit.scores?.graph)}%.`;
  return badge;
}

// One call per settled query, not per keystroke: the caller debounces, and a
// reply that arrives after the box has moved on is dropped rather than
// painting reasons for a query nobody is looking at any more.
async function refreshNoteSearchWhy() {
  const asked = noteSearch;
  if (!asked) {
    noteSearchWhy.clear();
    return;
  }
  // What the person is looking at, when that is unambiguous: one note opened
  // out in the list is the app's own "open note", and it is what makes the
  // third signal (distance over the links) mean anything. Two open rows, or
  // none, is not a context, and passing a guess would put "linked to the open
  // note" on a note linked to something nobody is reading.
  const open =
    editingId || (expandedRows.size === 1 ? [...expandedRows][0] : null);
  let body;
  try {
    // 50 is the endpoint's own ceiling (`routes_search.MAX_LIMIT`): a search
    // box shows a page, not a notebook, and a note past the fiftieth best
    // match simply carries no reason chip rather than a wrong one.
    body = await apiJson(
      `/search?q=${encodeURIComponent(asked)}&kind=note,board&limit=50` +
        (open ? `&entry_id=${open}` : "")
    );
  } catch {
    // The list is already rendered and already correct; the reasons are the
    // only thing missing, so a failed call leaves the notes alone.
    return;
  }
  if (noteSearch !== asked) return;
  noteSearchWhy.clear();
  for (const hit of body?.hits || []) noteSearchWhy.set(hit.id, hit);
  renderEntries();
}

// Sort comparator for the chosen mode (Wave J). Pinned always floats to
// the top first, matching the server's own ordering.
function sortEntries(entries) {
  const byPinned = (a, b) => Number(b.pinned) - Number(a.pinned);
  const modes = {
    newest: (a, b) => b.id - a.id,
    oldest: (a, b) => a.id - b.id,
    az: (a, b) => a.content.localeCompare(b.content),
    "most-used": (a, b) => b.access_count - a.access_count || b.id - a.id,
    //: The server's own fading order, by position rather than by a score
    //: recomputed here: `ai/resurface.py` weighs age, links and opens, and a
    //: second copy of those weights in the browser is the two-answers shape
    //: this app has paid for before. A note the ranking has not reached (it
    //: is capped, and a dismissed note is not in it) sorts after every note
    //: that is in it, rather than jumping to the top on a missing key.
    forgotten: (a, b) => {
      const far = forgottenOrder.size + 1;
      return (forgottenOrder.get(a.id) ?? far) - (forgottenOrder.get(b.id) ?? far) || b.id - a.id;
    },
  };
  const cmp = modes[noteSort] || modes.newest;
  return [...entries].sort((a, b) => byPinned(a, b) || cmp(a, b));
}

// --- incremental list rendering (ROADMAP §85.4 items 3 and 4) ---------------
//
// **The problem this solves, measured rather than assumed.** Four of this
// app's lists: the Notes list, the Library grid, the Timeline, the log
// console: built one DOM node per record for the *entire* collection, with
// no cap and no windowing. At 1,501 notes `renderEntries()` took ~533ms, and
// it re-runs on every search keystroke, sort change, filter and save.
//
// **Why chunk-on-scroll rather than true virtualisation.** Real
// virtualisation (absolute positioning against a scroll offset) needs to know
// each row's height before it renders one. Every list here has variable
// heights: a note card grows with its text, its tags, its attachments and
// whether its inline actions are open, so a virtualiser would either need
// measurement passes that cost what it saves, or fixed heights the design
// does not have. Rendering in chunks as the end of the list approaches keeps
// the DOM proportional to what has been *scrolled past* rather than to the
// notebook, needs no height information at all, and leaves the list one
// continuous scroll rather than turning it into pages, which is the
// distinction BACKLOG §77 draws and deliberately asks for.
//
// **The honest trade:** the browser's own Ctrl+F cannot find text in a chunk
// that has not rendered yet. That is a real loss, and it is why `initial` is
// generous rather than minimal, a screenful and change is always present , 
// and why it is applied to lists that have their own search box sitting
// directly above them. It is not applied anywhere that the browser's find is
// the only way through.
//
// `root: null` (the viewport) rather than the scroll container: an element
// inside the scrolled-away part of a *nested* scroller is not intersecting
// the viewport either, so one observer is correct for both a page-level and a
// container-level scroll, without having to find which one this list is in.
const listWindows = new WeakMap();

function renderIncrementally(container, items, buildItem, options = {}) {
  const { initial = 60, chunk = 40, afterChunk } = options;

  // Tear down the previous run first. Without this a re-render (a keystroke in
  // the search box) leaves the old observer alive, still holding the old
  // items, still appending them into a container that has moved on, the
  // "listener added without removal" shape, and the reason this is a
  // WeakMap rather than a local.
  listWindows.get(container)?.disconnect();
  listWindows.delete(container);

  const paint = (from, to) => {
    const fragment = document.createDocumentFragment();
    for (let i = from; i < to; i++) fragment.appendChild(buildItem(items[i], i));
    container.appendChild(fragment);
  };

  paint(0, Math.min(initial, items.length));
  afterChunk?.();
  if (items.length <= initial) return;

  let rendered = initial;
  // A zero-height marker after the last painted item. It is the *list's* own
  // last child rather than a sibling of the container, so it moves down as
  // chunks land and it inherits whatever scroller the list is in.
  const sentinel = document.createElement("li");
  sentinel.className = "list-window-sentinel";
  sentinel.setAttribute("aria-hidden", "true");
  container.appendChild(sentinel);

  const observer = new IntersectionObserver(
    (entries) => {
      if (!entries.some((entry) => entry.isIntersecting)) return;
      const next = Math.min(rendered + chunk, items.length);
      // Insert *before* the sentinel so it stays last and keeps observing.
      const fragment = document.createDocumentFragment();
      for (let i = rendered; i < next; i++) fragment.appendChild(buildItem(items[i], i));
      container.insertBefore(fragment, sentinel);
      rendered = next;
      afterChunk?.();
      if (rendered >= items.length) {
        observer.disconnect();
        listWindows.delete(container);
        sentinel.remove();
      }
    },
    // Start the next chunk while the sentinel is still a screen away, so the
    // list refills before the user reaches the bottom rather than after.
    { root: null, rootMargin: "600px 0px" }
  );
  observer.observe(sentinel);
  listWindows.set(container, observer);
}

// BACKLOG §77 item 1, the user-facing page-size control, deliberately kept
// separate from §86's scroll-chunking (renderIncrementally above): that stays
// one continuous scroll under "All notes" (the default, and this function's
// no-op path). A numeric size instead slices whatever list renderEntries was
// about to paint down to one page and updates the Prev/Next bar.
//
// Threads are the one place this is a known, accepted simplification: a
// thread and its children can, at a page boundary, split across two pages
// (part 2 of §77, routing a wiki-link click to the *right* page, depends
// on sort/filter state and is scoped separately, not solved here).
function paginateNotesForDisplay(items) {
  const bar = $("notes-pagination");
  if (notesPageSize === "all") {
    bar.classList.add("hidden");
    return items;
  }
  const pageSize = Number(notesPageSize);
  const totalPages = Math.max(1, Math.ceil(items.length / pageSize));
  notesCurrentPage = Math.min(Math.max(1, notesCurrentPage), totalPages);
  const start = (notesCurrentPage - 1) * pageSize;
  bar.classList.toggle("hidden", items.length === 0);
  $("notes-page-status").textContent = `Page ${notesCurrentPage} of ${totalPages}`;
  $("notes-page-prev").disabled = notesCurrentPage <= 1;
  $("notes-page-next").disabled = notesCurrentPage >= totalPages;
  return items.slice(start, start + pageSize);
}

// **The exact order the Notes list would paint, computed without painting
// it.** Split out of `renderEntries` (BACKLOG §77 item 2, routing a
// wiki-link click to the right *page*) so there is exactly one place that
// decides "what order do these notes render in", used both to actually
// render them and to answer "which page would note N land on" before a
// jump. Threads are the reason this can't be a plain sort-then-slice: a
// child's position depends on its parent's position, not on the child's own
// sort key, so `renderEntries`'s own thread-flattening (`ordered`,
// `addWithChildren`) is reproduced here rather than approximated.
//
// Reads the same module-level filter state `renderEntries` does
// (`draftsOnly`, `activeCategory`, `noteSearch`, `noteSort`), a caller that
// wants a *different* view's ordering (see `resolveNotePage` below) sets
// those first, the same way `flashEntry` already resets category/search/
// drafts before it ever draws anything.
function orderedNotesForCurrentView() {
  let visible = draftsOnly
    ? allEntries.filter((e) => e.is_draft)
    : favouritesOnly
      ? allEntries.filter((e) => e.pinned && !e.is_draft)
      : activeCategory
        ? allEntries.filter((e) => e.category === activeCategory && !e.is_draft)
        : allEntries.filter((e) => !e.is_draft);
  visible = visible.filter(matchesSearch);

  const flat = Boolean(noteSearch) || noteSort !== "newest";
  if (flat) return sortEntries(visible).map((entry) => [entry, 0]);

  const visibleIds = new Set(visible.map((e) => e.id));
  const childrenOf = new Map();
  for (const entry of visible) {
    if (entry.parent_id && visibleIds.has(entry.parent_id)) {
      if (!childrenOf.has(entry.parent_id)) childrenOf.set(entry.parent_id, []);
      childrenOf.get(entry.parent_id).push(entry);
    }
  }
  const ordered = [];
  const addWithChildren = (entry, depth) => {
    ordered.push([entry, depth]);
    const children = (childrenOf.get(entry.id) || []).slice().reverse();
    for (const child of children) addWithChildren(child, depth + 1);
  };
  for (const entry of visible) {
    const parentVisible = entry.parent_id && visibleIds.has(entry.parent_id);
    if (!parentVisible) addWithChildren(entry, 0);
  }
  return ordered;
}

// Which page (1-based) a note lands on in the Notes list's *current*
// filter/sort: the arithmetic half of BACKLOG §77 item 2. "All notes" (no
// pagination) always answers page 1, since there is only one. Returns null
// for a note the current filters would hide entirely (a category filter
// excluding it, say): a page number for a note that isn't in the list
// would be a lie, not an answer.
function resolveNotePage(id) {
  if (notesPageSize === "all") return 1;
  const order = orderedNotesForCurrentView();
  const index = order.findIndex(([entry]) => entry.id === id);
  if (index === -1) return null;
  return Math.floor(index / Number(notesPageSize)) + 1;
}

//: Rows or cards.
//:
//: **Cards is the default, by direct instruction**, "maybe make the cards
//: notes view default", after rows shipped as the default first. Rows
//: exist because a two-line note was a 111px card plus a 10px gap, so a
//: 900px window showed five notes; they fit twelve. But density is not the
//: only thing a list of notes is for, and a card shows the note rather than
//: a clipped line of it. Both are one click apart, and a row expands in
//: place (see `row-expanded` below), so the compact view is no longer a
//: view that *withholds* things.
//:
//: **The choice is remembered**, also asked for directly. localStorage
//: rather than a server preference: it is a property of this screen on this
//: machine, the same family as the expanded/collapsed sets above, and a
//: round trip to change how a list looks would be the wrong trade. Read as
//: "rows only if rows was explicitly chosen", so a profile that has never
//: touched the toggle gets cards.
let notesViewMode = localStorage.getItem("notesViewMode") === "rows" ? "rows" : "cards";

function applyNotesViewMode() {
  const list = $("entry-list");
  if (list) list.classList.toggle("is-rows", notesViewMode === "rows");
  $("notes-view-rows")?.classList.toggle("active", notesViewMode === "rows");
  $("notes-view-cards")?.classList.toggle("active", notesViewMode === "cards");
  $("notes-view-rows")?.setAttribute("aria-pressed", String(notesViewMode === "rows"));
  $("notes-view-cards")?.setAttribute("aria-pressed", String(notesViewMode === "cards"));
  updateExpandAllButton();
}

//: **Expand / collapse every row in the list you are looking at.** Asked for
//: directly ("on the collapsed note view mode there should be an expand
//: and/or collapse all button"). One button rather than two, because the
//: only two states it can be in each have exactly one useful next move.
//:
//: It reads the rendered `<li>`s rather than recomputing which notes are
//: visible. Filtering, sorting, threading and pagination all decide that
//: between them, and a second implementation of "which notes are on screen"
//: is a second thing to keep in step, the DOM already holds the answer.
function listedNoteIds() {
  return [...document.querySelectorAll("#entry-list > li[data-id]")].map((li) =>
    Number(li.dataset.id)
  );
}

function updateExpandAllButton() {
  const button = $("notes-expand-all");
  if (!button) return;
  // Cards view opens every note by definition, so the control would say
  // nothing there.
  button.classList.toggle("hidden", notesViewMode !== "rows");
  if (notesViewMode !== "rows") return;
  const ids = listedNoteIds();
  const anyCollapsed = ids.some((id) => !expandedRows.has(id));
  setLabel(
    button,
    anyCollapsed ? "ph:arrows-out-line-vertical Expand all" : "ph:arrows-in-line-vertical Collapse all"
  );
  button.title = anyCollapsed
    ? "Open every note in this list"
    : "Close every note back to a single line";
  button.setAttribute("aria-label", button.title);
  button.disabled = ids.length === 0;
}

function toggleExpandAllRows() {
  const ids = listedNoteIds();
  if (!ids.length) return;
  const anyCollapsed = ids.some((id) => !expandedRows.has(id));
  for (const id of ids) {
    if (anyCollapsed) expandedRows.add(id);
    else expandedRows.delete(id);
  }
  renderEntries();
}

function setNotesViewMode(mode) {
  notesViewMode = mode === "cards" ? "cards" : "rows";
  localStorage.setItem("notesViewMode", notesViewMode);
  applyNotesViewMode();
}

//: Which rows the reader has opened out. Asked for directly: "I think the
//: compact cards need to be expandable to show all the note details and
//: features."
//:
//: A row is a summary, it clips the body to one line and hides images, file
//: cards and link chips, which is what makes twelve of them fit. That is the
//: right default and the wrong dead end: wanting to *see* one of them should
//: not mean switching the whole list to cards and losing your place. An
//: expanded row drops back to the full card layout in place, so one note can
//: be open inside an otherwise compact list.
//:
//: Not persisted, deliberately. It is a reading position, not a preference, 
//: coming back to a list with six notes arbitrarily open would be worse than
//: coming back to a tidy one.
const expandedRows = new Set();

function toggleRowExpanded(id) {
  if (expandedRows.has(id)) expandedRows.delete(id);
  else expandedRows.add(id);
  renderEntries();
}

$("notes-expand-all")?.addEventListener("click", toggleExpandAllRows);
$("notes-view-rows")?.addEventListener("click", () => setNotesViewMode("rows"));
$("notes-view-cards")?.addEventListener("click", () => setNotesViewMode("cards"));

function renderEntries() {
  // A cleared box clears its reasons here rather than at each of the five
  // places that can clear the box: a reason for a query nobody typed is
  // worse than no reason at all.
  if (!noteSearch && noteSearchWhy.size) noteSearchWhy.clear();
  const list = $("entry-list");
  const empty = $("empty-message");
  const noMatch = $("no-match-message");
  list.replaceChildren();
  // Re-applied on every render, not just on a click: `replaceChildren`
  // above leaves the class alone, but a later render that rebuilt the <ul>
  // itself would not: and this failing silently would look like the
  // toggle not working rather than a class being dropped.
  applyNotesViewMode();

  // Drafts stay out of All/category views entirely, user-reported: they
  // should only show up in the Drafts filter until saved as a real note.
  let visible = draftsOnly
    ? allEntries.filter((e) => e.is_draft)
    : favouritesOnly
      ? allEntries.filter((e) => e.pinned && !e.is_draft)
      : activeCategory
        ? allEntries.filter((e) => e.category === activeCategory && !e.is_draft)
        : allEntries.filter((e) => !e.is_draft);
  visible = visible.filter(matchesSearch);

  // "Notes" everywhere else on this tab ("Your notes", "notebook", the
  // status-bar note count): this heading used to say "entries" (the API's
  // internal name, /entries), the one place on the tab that didn't match
  // (Part C terminology audit).
  const scope = draftsOnly
    ? "Drafts"
    : favouritesOnly
      ? "Favourites"
      : activeCategory
        ? `${activeCategory} notes`
        : "All notes";
  // Say how many matched out of how many there are. Without it a filter that
  // hides most of the notebook looks identical to a notebook that's nearly
  // empty, and there's no signal that a filter is even active.
  const total = draftsOnly
    ? allEntries.filter((e) => e.is_draft).length
    : favouritesOnly
      ? allEntries.filter((e) => e.pinned && !e.is_draft).length
      : activeCategory
        ? allEntries.filter((e) => e.category === activeCategory && !e.is_draft).length
        : allEntries.filter((e) => !e.is_draft).length;
  $("entries-heading-label").textContent =
    noteSearch && visible.length !== total
      ? `${scope}: ${visible.length} of ${total}`
      : scope;
  // Distinguish "empty notebook" from "filter matched nothing".
  const notebookEmpty = allEntries.length === 0;
  empty.classList.toggle("hidden", !notebookEmpty);
  noMatch.classList.toggle("hidden", notebookEmpty || visible.length > 0);

  // A search or a non-default sort means the user wants a flat, ordered
  // list: thread nesting only applies to the default newest view.
  const flat = Boolean(noteSearch) || noteSort !== "newest";
  if (flat) {
    renderIncrementally(
      list,
      paginateNotesForDisplay(sortEntries(visible)),
      (entry) => entryItem(entry, { actions: true }),
      { afterChunk: () => applyEntryListTabOrder(list) }
    );
    return;
  }

  // Threads (Wave B): children render indented under their parent. A
  // child whose parent isn't visible (filtered out) shows at top level.
  const visibleIds = new Set(visible.map((e) => e.id));
  const childrenOf = new Map();
  for (const entry of visible) {
    if (entry.parent_id && visibleIds.has(entry.parent_id)) {
      if (!childrenOf.has(entry.parent_id)) childrenOf.set(entry.parent_id, []);
      childrenOf.get(entry.parent_id).push(entry);
    }
  }

  // Flattened to `[entry, depth]` pairs *before* rendering, rather than
  // recursing straight into the DOM. A thread has to stay whole, a parent and
  // its continuations are one unit and must never be split across a chunk
  // boundary: so the recursion produces the order and the depth, and the
  // renderer below decides how much of that order to paint. Threads are the
  // reason this list cannot simply be sliced: position in `visible` is not
  // position on screen.
  const ordered = [];
  const addWithChildren = (entry, depth) => {
    ordered.push([entry, depth]);
    // Oldest continuation first: a thread reads top to bottom.
    const children = (childrenOf.get(entry.id) || []).slice().reverse();
    for (const child of children) addWithChildren(child, depth + 1);
  };

  for (const entry of visible) {
    const parentVisible = entry.parent_id && visibleIds.has(entry.parent_id);
    if (!parentVisible) addWithChildren(entry, 0);
  }

  renderIncrementally(
    list,
    paginateNotesForDisplay(ordered),
    ([entry, depth]) => {
      const li = entryItem(entry, { actions: true });
      if (depth > 0) {
        li.classList.add("thread-child");
        li.style.marginLeft = `${Math.min(depth, 4) * 1.4}rem`;
      }
      return li;
    },
    {
      afterChunk: () => {
        applyEntryListTabOrder(list);
        // After the list is in the DOM: drop the clamp from any note that
        // turned out to fit. No-op while the sub-tab is hidden;
        // showNotesSection re-runs it.
        settleNoteClamps();
        // Expand-all reads the rendered rows, and `applyNotesViewMode` runs
        // at the *top* of this function, right after `replaceChildren()`,
        // when the list is empty and the button would read "Expand all
        // (disabled)" forever. Refreshed here, once the rows exist.
        updateExpandAllButton();
      },
    }
  );
}

// --- note-list keyboard navigation (ROADMAP Tier 3 §30a / BACKLOG §16) ------------
// Named directly as "the one interaction pattern used constantly enough that
// its absence would be felt every session, not just noticed in an audit."
// A roving tabindex: only one <li> is ever a Tab stop, so the list is one
// stop in the page's tab order rather than one per note, matching the
// standard listbox/grid keyboard pattern.
// `li[data-id]`, not `list.children`: the incremental renderer parks a
// zero-height sentinel `<li>` at the end of the list to know when to paint the
// next chunk, and it is not a note. Left in `children` it would join the
// roving tabindex and the arrow-key walk below, so ArrowDown at the bottom of
// the list would focus an invisible element and appear to do nothing.
const entryListItems = (list) => Array.from(list.querySelectorAll(":scope > li[data-id]"));

function applyEntryListTabOrder(list) {
  const items = entryListItems(list);
  const current = document.activeElement;
  // Re-renders happen constantly (search-as-you-type, sort, edits): if the
  // previously-focused note is still present, keep it as the one Tab stop
  // instead of silently resetting focus back to the top of the list.
  const keepId = items.some((li) => li === current) ? current.dataset.id : null;
  items.forEach((li) => {
    li.tabIndex = keepId ? (li.dataset.id === keepId ? 0 : -1) : -1;
  });
  if (!keepId && items.length > 0) items[0].tabIndex = 0;
}

function initEntryListKeyboardNav() {
  const list = $("entry-list");
  list.addEventListener("keydown", (event) => {
    if (event.key !== "ArrowDown" && event.key !== "ArrowUp" && event.key !== "Enter") return;
    const items = entryListItems(list);
    const current = event.target.closest("li");
    const index = current ? items.indexOf(current) : -1;
    if (index === -1) return;

    if (event.key === "ArrowDown" || event.key === "ArrowUp") {
      event.preventDefault();
      const nextIndex = Math.min(
        Math.max(index + (event.key === "ArrowDown" ? 1 : -1), 0),
        items.length - 1
      );
      items.forEach((li, i) => { li.tabIndex = i === nextIndex ? 0 : -1; });
      items[nextIndex].focus();
      // .focus() alone scrolls in most browsers, but not predictably, 
      // explicit and consistent with the same fix on the command palette's
      // own arrow-key nav, which has no focus to lean on at all.
      items[nextIndex].scrollIntoView({ block: "nearest" });
    } else if (event.key === "Enter" && event.target === current) {
      // Only when the <li> itself has focus, not a button/link/textarea
      // inside it: those already handle their own Enter behaviour, and
      // this app has no separate "note view" to open: editing in place is
      // what opening a note means here.
      event.preventDefault();
      current.querySelector(".entry-actions [title='Edit this entry']")?.click();
    }
  });
}

// name -> {id, count}. Needed because renaming and deleting work on ids,
// while the sidebar itself is built from the entries already in memory.
let categoryMeta = new Map();

async function loadCategories() {
  const rows = await apiJson("/categories", { silent: true }).catch(() => []);
  categoryMeta = new Map(rows.map((c) => [c.name, c]));
  renderSidebar();
}

function renderSidebar() {
  // Categories + counts are derived from the loaded entries, the
  // simplest thing that works; no extra endpoint needed yet.
  // Drafts only belong in the Drafts row (user-reported: they were still
  // showing under All/category counts, undercutting the point of a
  // separate section): until saved as a real note, a draft doesn't count.
  const counts = new Map();
  for (const entry of allEntries) {
    if (entry.is_draft) continue;
    counts.set(entry.category, (counts.get(entry.category) || 0) + 1);
  }

  const ul = $("category-list");
  ul.replaceChildren();

  const addRow = (label, count, category) => {
    const li = document.createElement("li");
    if (category === activeCategory) li.classList.add("active");
    const name = document.createElement("span");
    name.className = "category-name";
    name.textContent = label;
    name.title = label;
    const badge = document.createElement("span");
    badge.className = "count";
    badge.textContent = count;
    li.append(name, badge);
    li.addEventListener("click", () => {
      activeCategory = category;
      draftsOnly = false; // exclusive with the Drafts filter below
      favouritesOnly = false; // and with Favourites, for the same reason
      // The list this filters lives in the "browse" sub-tab, and the sidebar
      // is visible from all four, so picking a category while writing a note
      // or asking a question filtered a list that was `display: none`, and the
      // click appeared to do nothing at all. Reported. The same fix
      // `flashEntry` already carries for jumping to a note, for the same
      // reason: a sidebar that is always on screen must be able to bring the
      // thing it controls on screen with it.
      showNotesSection("browse");
      renderSidebar();
      renderEntries();
    });

    // Rename/delete for real categories only, "All" is a filter, and
    // Uncategorised is where notes land when a category goes away.
    const meta = category ? categoryMeta.get(category) : null;
    if (meta && category !== "Uncategorised") {
      const actions = document.createElement("span");
      actions.className = "category-actions";
      actions.append(
        smallButton("ph:pencil-simple", `Rename ${category}`, (event) => {
          event.stopPropagation();
          renameCategory(meta, category);
        }),
        smallButton("ph:trash", `Delete ${category}`, (event) => {
          event.stopPropagation();
          deleteCategory(meta, category, count);
        })
      );
      li.appendChild(actions);
    }
    ul.appendChild(li);
  };

  addRow("All", allEntries.filter((e) => !e.is_draft).length, null);

  // A drafts count, not a category, asked for directly: a Drafts filter
  // findable in the same place categories are, so a note drafted with the
  // AI (Writing Room) or captured from a selection isn't only markable one
  // at a time via its own chip (entryItem). Always shown, even at 0, so it
  // stays discoverable rather than appearing only once something lands in it.
  const draftCount = allEntries.filter((e) => e.is_draft).length;
  const draftRow = document.createElement("li");
  draftRow.className = "category-drafts-row";
  if (draftsOnly) draftRow.classList.add("active");
  const draftName = document.createElement("span");
  draftName.className = "category-name";
  setLabel(draftName, "ph:pencil-simple-line Drafts");
  const draftBadge = document.createElement("span");
  draftBadge.className = "count";
  draftBadge.textContent = draftCount;
  draftRow.append(draftName, draftBadge);
  draftRow.addEventListener("click", () => {
    draftsOnly = !draftsOnly;
    favouritesOnly = false;
    activeCategory = null;
    showNotesSection("browse");
    renderSidebar();
    renderEntries();
  });

  // **Favourites.** Asked for as "a favourites folder or side parallel category
  // that isnt an actual category but could be treated as one if toggled", so
  // it is built exactly like Drafts directly above: a row where the categories
  // are, a count, a toggle, and mutually exclusive with the other two filters.
  // This app already has one pseudo-category, and a second that behaved
  // differently would be a second sign for the same idea.
  //
  // The notes it collects are the pinned ones (see `favouritesOnly`), no new
  // flag, no second place to star something.
  const favouriteCount = allEntries.filter((e) => e.pinned && !e.is_draft).length;
  const favouriteRow = document.createElement("li");
  favouriteRow.className = "category-drafts-row";
  if (favouritesOnly) favouriteRow.classList.add("active");
  const favouriteName = document.createElement("span");
  favouriteName.className = "category-name";
  setLabel(favouriteName, "ph:star Favourites");
  const favouriteBadge = document.createElement("span");
  favouriteBadge.className = "count";
  favouriteBadge.textContent = favouriteCount;
  favouriteRow.append(favouriteName, favouriteBadge);
  favouriteRow.title = "Notes you have starred, they also float to the top of every list";
  favouriteRow.addEventListener("click", () => {
    favouritesOnly = !favouritesOnly;
    draftsOnly = false;
    activeCategory = null;
    showNotesSection("browse");
    renderSidebar();
    renderEntries();
  });
  ul.appendChild(draftRow);
  ul.appendChild(favouriteRow);

  for (const [category, count] of [...counts.entries()].sort()) {
    addRow(category, count, category);
  }
}

async function renameCategory(meta, currentName) {
  const name = await promptDialog(`Rename "${currentName}" to:`, currentName);
  if (!name || name === currentName) return;

  // Renaming onto a category that already exists merges them, which is
  // usually the point: but it's destructive-looking, so it's confirmed.
  if (categoryMeta.has(name)) {
    const target = categoryMeta.get(name);
    const ok = (await confirmDialog(
      `"${name}" already exists. Merge "${currentName}" into it?\n\n` +
        `Its notes move across, nothing is deleted. "${name}" would then ` +
        `hold ${target.count + meta.count} notes.`
    ));
    if (!ok) return;
  }

  try {
    const result = await apiJson(`/categories/${meta.id}`, {
      method: "PUT",
      body: JSON.stringify({ name }),
    });
    if (activeCategory === currentName) activeCategory = name;
    toast(result.merged ? `Merged into "${name}".` : `Renamed to "${name}".`);
    await loadEntries();
    await loadCategories();
  } catch (error) {
    toast(error.message, true);
  }
}

async function deleteCategory(meta, name, count) {
  const ok = (await confirmDialog(
    `Delete the category "${name}"?\n\n` +
      (count
        ? `Its ${count} note${count === 1 ? "" : "s"} are kept and become ` +
          `Uncategorised: deleting a category never deletes notes.`
        : "It has no notes in it.")
  ));
  if (!ok) return;
  try {
    await apiJson(`/categories/${meta.id}`, { method: "DELETE" });
    if (activeCategory === name) activeCategory = null;
    toast(`Deleted "${name}". Its notes are in Uncategorised.`);
    await loadEntries();
    await loadCategories();
  } catch (error) {
    toast(error.message, true);
  }
}

// Loading skeletons (Wave I): shimmer placeholders instead of a blank
// list on the very first load, so a slow disk never looks broken.
function showEntrySkeletons() {
  const list = $("entry-list");
  if (list.children.length > 0) return; // only ever on a truly empty list
  for (let i = 0; i < 3; i++) {
    const li = document.createElement("li");
    li.className = "skeleton";
    li.setAttribute("aria-hidden", "true");
    list.appendChild(li);
  }
}

// A page of the plain list, matches the backend's own default
// (ENTRIES_PAGE_SIZE in routes_entries.py). Most real notebooks fit on one
// page; a notebook that has grown for years pages in the background below.
const ENTRIES_PAGE_SIZE = 1000;

async function loadEntries() {
  const generation = ++_entriesLoadGeneration;
  showEntrySkeletons();
  //: **What the note list needs to draw a `[[map]]` as a map chip**, filled
  //: here rather than per note card: `renderNoteInline` is synchronous and
  //: runs once per wiki link, so it cannot fetch. Deliberately not awaited: 
  //: the list paints now, and a chip drawn before this lands falls back to the
  //: link's own text without its node count rather than to nothing at all.
  //: `apiJson`'s `cacheMs` means a rapid sequence of loads costs one request.
  loadMapBoardIndex();

  const isSemantic = $("semantic-search-toggle")?.checked;
  if (isSemantic && noteSearch) {
    // Semantic search is already bounded server-side (SEMANTIC_LIST_LIMIT)
    //, nothing here needs paging.
    const results = await apiJson(
      `/entries?q=${encodeURIComponent(noteSearch)}&semantic=true`
    );
    if (generation !== _entriesLoadGeneration) return; // a newer load took over
    allEntries = results;
    entriesEverLoaded = true;
    renderStatusBar();
    renderSidebar();
    loadCategories();
    renderEntries();
    fillCategoryOptions($("entry-category"), null);
    refreshTagSuggestions();
    return;
  }

  // Paginated: GET /entries used to return the whole notebook in one
  // response, which is fine at a few hundred notes and a real risk of
  // timing out (or just feeling broken) at the size a "just works" notebook
  // reaches after years of use. The first page paints immediately, for
  // most notebooks that's everything, indistinguishable from before, and
  // any further pages fill in the background, so nothing downstream of
  // allEntries (search, keyboard nav, the sidebar, tag suggestions) had to
  // change: it still ends up exactly as complete as it always was.
  let offset = 0;
  let total = Infinity; // discovered from the first response's X-Total-Count
  let first = true;
  while (offset < total) {
    const response = await api(`/entries?limit=${ENTRIES_PAGE_SIZE}&offset=${offset}`);
    const page = await response.json();
    if (generation !== _entriesLoadGeneration) return; // superseded mid-load

    allEntries = first ? page : allEntries.concat(page);
    entriesEverLoaded = true;
    offset += page.length;
    const reported = Number(response.headers.get("X-Total-Count"));
    total = Number.isFinite(reported) ? reported : allEntries.length;

    renderStatusBar(); // the notebook's size changed, and the bar reads it here
    renderEntries();
    if (first || offset >= total) {
      renderSidebar();
      // Categories the AI has filed notes into since the last load need
      // their ids fetched before rename/delete can work on them.
      // Deliberately not awaited: the list renders now and the controls
      // light up a moment later.
      loadCategories();
      fillCategoryOptions($("entry-category"), null);
      refreshTagSuggestions();
    }
    first = false;
    if (page.length === 0) break; // safety: never loop forever on a stale total
  }
}

// --- capture -----------------------------------------------------------------

// Human explanations of how a note was filed ("visuals of what happened").
// A "go to it" link beside the save confirmation. Replaced each save, and
// cleared as soon as you start typing the next note.
function offerJumpToNewNote(saved, status) {
  if (!saved || !saved.id) return;
  const jump = document.createElement("button");
  jump.type = "button";
  jump.className = "ghost small jump-to-note";
  setLabel(jump, "ph:arrow-right Go to it");
  jump.title = "Open this note in your list";
  jump.addEventListener("click", () => flashEntry(saved.id));
  status.append(" ", jump);
}

// A deferred note's filing runs after its POST returns, so the composer has
// to find out where it landed some other way. It polls this one endpoint, 
// three fields, no joins, on a widening interval, because the answer
// arrives either in well under a second (a semantic match, no model call)
// or in however long the local model takes, and a fixed 250ms poll would
// spend most of its requests on the gap between those two.
//
// Giving up is deliberately quiet. The note is already saved and already in
// the list; the only thing a timeout costs is the toast, and a notebook
// whose model has gone away should not accumulate error messages for notes
// that saved perfectly well.
const FILING_POLL_STEPS = [400, 600, 900, 1400, 2000, 3000, 4000, 6000, 8000];

async function watchFiling(entry) {
  for (const wait of FILING_POLL_STEPS) {
    await new Promise((r) => setTimeout(r, wait));
    let status;
    try {
      status = await apiJson(`/entries/${entry.id}/filing`, { silent: true });
    } catch {
      return; // deleted, or the server went away, nothing to report
    }
    if (status.filing_state === "pending") continue;
    if (status.filing_state === "failed") {
      toast(`Saved, but the AI couldn't file it: it's in “${status.category}”.`, true);
    } else {
      toastAction(
        `Filed under “${status.category}” (${status.ai_confidence}% sure).`,
        "Go to it",
        () => flashEntry(entry.id)
      );
      // The near-duplicate search moved into the same background pass, so
      // this warning arrives here now rather than on the create response.
      // Still purely informational, still never blocking, the note saved.
      if (status.similar) {
        toast(`Heads up: this is close to an existing note, “${status.similar.preview}”`);
      }
    }
    // The card in the list still says "Filing…" and still shows the holding
    // category until something re-reads it.
    await loadEntries();
    return;
  }
}

function filedByText(saved) {
  if (saved.filing_state === "pending") {
    return "Saved. Filing it in the background, keep writing.";
  }
  switch (saved.filed_by) {
    case "semantic-match":
      return `Filed under “${saved.category}” (${saved.ai_confidence}% sure): matched by meaning, no AI call needed`;
    case "llm":
      return `Filed under “${saved.category}” (${saved.ai_confidence}% sure): decided by ${
        (modelStatus && modelStatus.chat_model) || "the chat model"
      }`;
    case "user":
      return `Filed under “${saved.category}”: your choice, the AI stayed out of it`;
    default:
      return `Saved as “${saved.category}”: the AI wasn't available to file it`;
  }
}

// --- notes ↔ documents ------------------------------------------------------
// Asked for directly: "a way to link documents to new notes I create in the
// capture tab… the documents and notes sections need to be more integrated".
// The picker adds; the chips are how you take one back off before saving.

const captureDocuments = new Set();

//: Files waiting to become attachments on a note that does not exist yet.
//: The long "why staging" explanation lives on `handleFileUpload`, which is
//: the only thing that fills this.
//:
//: **Declared here, ~19,000 lines before its first write, and that is the
//: fix for a real crash.** It was originally declared next to
//: `handleFileUpload`, near the end of the file, but `renderCaptureFiles`
//: reads it, and the draft-restore IIFE calls that at module load time, from
//: *earlier* in the file. `let` is hoisted into the temporal dead zone
//: rather than initialised, so that read threw `Cannot access
//: 'captureStagedFiles' before initialization`, which aborted the rest of
//: app.js: `initAuth` never ran, the splash never hid, and the app sat on
//: its loading screen forever. Reported exactly that way, and caught by the
//: boot guard added the same session, which is the only reason the cause was
//: visible at all rather than being a silent hang.
//:
//: `node --check` does not catch this: it is valid syntax and a runtime
//: ordering fault. The lesson for anything similar: module-level state read
//: during load must be declared above every path that runs at load.
let captureStagedFiles = [];

async function loadCaptureDocuments() {
  //: To the end, not the first page: the picker exists to file this note
  //: under *any* document, and a document past the server's page would be
  //: invisible with nothing on screen saying so (`agent-remaining/
  //: list-paging.md`). `apiPagedList` is one request at any realistic size.
  const documents = await apiPagedList("/documents", 200).catch(() => []);
  renderCaptureDocuments(documents);
}

// The picker's value for "one that doesn't exist yet". A string, so it can
// never collide with a document id.
const NEW_DOCUMENT = "new";

// Ask for a title and start an empty document. Shared by the capture box and
// the note card's "Add to a document", so both offer the same thing.
async function createDocumentNamed(suggestion = "") {
  const title = await promptDialog("Title for the new document:", suggestion, { confirmLabel: "Create" });
  if (!title) return null;
  try {
    const doc = await apiJson("/documents", {
      method: "POST",
      body: JSON.stringify({ title, content: `# ${title}\n\n` }),
    });
    return doc; // the documents tab refetches on switch, so nothing to sync
  } catch (error) {
    toast(error.message, true);
    return null;
  }
}

let captureDocumentTitles = new Map();
// The last list the server gave us, so removing a chip can put that document
// back in the adder's menu without a second round trip.
let captureDocumentList = [];

function renderCaptureDocuments(documents) {
  if (documents) {
    captureDocumentList = documents;
    captureDocumentTitles = new Map(documents.map((d) => [String(d.id), d.title]));
  }
  const box = $("entry-document-chips");
  box.replaceChildren();
  for (const id of captureDocuments) {
    const chipEl = chip(`ph:file-text ${captureDocumentTitles.get(String(id)) || id} ✕`, "tag", () => {
      captureDocuments.delete(id);
      renderCaptureDocuments();
    });
    chipEl.title = "Don't attach this note to that document after all";
    box.appendChild(chipEl);
  }
  renderCaptureDocumentAdder();
}

//: **The picked documents are chips; the control that adds one is an adder.**
//:
//: Reported by the owner (INBOX 116) as "the add to document combobox not
//: changing", and it was not a bug in the handler: the handler wrote
//: `event.target.value = ""` on every pick *on purpose*, because a note can
//: go onto several documents and the select could only ever show one. So the
//: box snapped back to "None" the instant you chose something and the choice
//: appeared as a chip beside it. A select that refuses to hold the value you
//: just gave it reads as broken however correct its reasons are.
//:
//: The decision (recorded in UI_MODERNISATION_PLAN, "Decisions made"): a
//: thing you pick and it *acts* is a menu, and the recipe for a menu behind a
//: worded button is `labelledMenu` (DESIGN.md's recipe index). That is also
//: the shape "Attach" and "From library" already have on this same row, so
//: the three now read as one family of adders rather than one dropdown and
//: two buttons.
//:
//: Rebuilt rather than mutated on every render: the menu's contents depend on
//: which documents are already chips, and a five-item list is cheaper to
//: rebuild than to diff.
function renderCaptureDocumentAdder() {
  const slot = $("entry-document-adder");
  if (!slot) return;
  const items = [];
  for (const doc of captureDocumentList) {
    if (captureDocuments.has(doc.id)) continue;
    items.push(
      makeMenuItem(`ph:file-text ${doc.title}`, `Attach this note to “${doc.title}”`, () => {
        captureDocuments.add(doc.id);
        renderCaptureDocuments();
      }),
    );
  }
  // Asked for: "the add to document should have the option for a new document
  // as well". Wanting to file a note under something that does not exist yet
  // is the normal case at the start of a project, and leaving to make the
  // document loses the note you were in the middle of writing.
  items.push(
    makeMenuItem("ph:plus New document…", "Start a document and attach this note to it", async () => {
      const doc = await createDocumentNamed($("entry-content").value.trim().slice(0, 60));
      if (!doc) return;
      captureDocuments.add(doc.id);
      await loadCaptureDocuments(); // so the new one is in the list to remove
    }),
  );
  const adder = labelledMenu("ph:file-plus Add to document", items, "Add this note to a document", "ghost");
  slot.replaceChildren(adder);
}

// The other direction, asked for straight after the capture-time picker:
// "what about adding a document to a note??". A note you wrote weeks ago
// turns out to belong to something you are writing now, and the capture box
// is long gone by then.
async function renderAttachToDocument(entry, wrap) {
  const status = document.createElement("p");
  status.className = "muted";
  status.textContent = "Loading documents…";
  wrap.appendChild(status);

  //: To the end, same reason as `loadCaptureDocuments`.
  const documents = await apiPagedList("/documents", 200).catch(() => null);
  if (!documents) {
    status.classList.add("error");
    status.textContent = "Couldn't load your documents.";
    return;
  }
  const already = new Set((entry.documents || []).map((doc) => doc.id));
  const free = documents.filter((doc) => !already.has(doc.id));

  status.textContent = free.length
    ? "Add this note to:"
    : documents.length
      ? "This note is on all of your documents, or start a new one:"
      : "No documents yet: start one:";
  const picker = document.createElement("select");
  for (const doc of free) {
    const option = document.createElement("option");
    option.value = String(doc.id);
    option.textContent = doc.title || "Untitled";
    picker.appendChild(option);
  }
  // Same offer as the capture box: the document this note belongs to often
  // does not exist until the note makes you realise you want it.
  const fresh = document.createElement("option");
  fresh.value = NEW_DOCUMENT;
  fresh.textContent = "＋ New document…";
  picker.appendChild(fresh);

  const row = document.createElement("div");
  row.className = "row";
  row.appendChild(
    smallButton(
      "Attach",
      "Add this note to the chosen document",
      async () => {
        let id = picker.value;
        let title = picker.selectedOptions[0]?.textContent || "that document";
        if (id === NEW_DOCUMENT) {
          const made = await createDocumentNamed(entry.content.trim().slice(0, 60));
          if (!made) return;
          id = String(made.id);
          title = made.title;
        }
        try {
          await apiJson(`/documents/${id}/notes`, {
            method: "POST",
            body: JSON.stringify({ entry_id: entry.id }),
          });
          inlineAction = null;
          await loadEntries();
          toastAction(`Added to “${title}”.`, "Open", () =>
            openDocumentFromNote(Number(id))
          );
        } catch (error) {
          toast(error.message, true);
        }
      },
      false
    )
  );
  row.appendChild(
    smallButton("Cancel", "", () => {
      inlineAction = null;
      renderEntries();
    })
  );
  wrap.append(picker, row);
  //: `picker` is a `<select>`, so the same trap: see `focusSelect`. The
  //: `setTimeout` was there to wait for the element to be in the document;
  //: `focusSelect` waits for the frame that gives it its opener, which is the
  //: later of the two events and the one that actually matters.
  focusSelect(picker);
}

function openDocumentFromNote(documentId) {
  switchTab("documents");
  // The tab's own loader races us otherwise, and opens the last document.
  setTimeout(() => openDocument(documentId), 150);
}

// ROADMAP.md Tier 2 §16d, asked for directly: an optional title field
// where a note is created. Not a second stored field, it writes the same
// leading `# heading` line `manager.extract_title` already reads on every
// note (§43), so a title typed here reads back identically to one typed
// as the note's own first line. Only prepended when the title box actually
// has something in it, so a note with no title is unchanged from today.
function withTitle(content, title) {
  const trimmed = (title || "").trim();
  return trimmed ? `# ${trimmed}\n\n${content}` : content;
}

// Shared by saveEntry and saveEntryAsDraft: clear the capture box and every
// field that goes with it once the content has actually been saved
// somewhere. Pulled out rather than left duplicated, both paths need
// exactly this, and it drifting between two copies is how one of them ends
// up leaving a stale category or template selected after a save.
function resetCaptureForm(contentBox, titleBox) {
  contentBox.value = "";
  if (titleBox) titleBox.value = "";
  renderEntryAttachmentChips();
  autoGrow(contentBox); // the box shrinks back with its content
  localStorage.removeItem("captureDraft"); // it's saved for real now
  $("entry-count").textContent = "0 characters";
  $("entry-tags").value = "";
  $("entry-category").value = "";
  captureDocuments.clear();
  renderCaptureDocuments();
  $("entry-template").value = "";
  clearCaptureTagSuggestions();
  // NOT cleared here: `captureStagedFiles`. `saveEntry` hands the list to
  // `uploadStagedFiles`, which takes ownership of it and empties it itself.
  // Clearing here as well would race that and silently drop the attachments
  // on every save: the composer resets before the uploads finish, by
  // design. `saveEntryAsDraft` clears it explicitly instead, below.
  renderCaptureFiles();
}

// **Tag suggestions while composing, not just after saving.** Reported
// directly: "the ai and application doesnt suggest tags either before
// creating a new note or after", "after" already existed
// (renderReevaluateResult, above), buried in a saved note's own kebab menu;
// "before" had nothing at all. `/entries/suggest-tags` needs only the
// draft's own text, so this can run on the Capture box itself, debounced the
// same way autosave-to-localStorage already is elsewhere in this file.
let captureTagSuggestTimer = null;
let captureTagSuggestSeq = 0; // invalidated on every keystroke, a slow reply
// to an earlier, shorter draft must never overwrite what a newer one asked for.

function clearCaptureTagSuggestions() {
  captureTagSuggestSeq++;
  clearTimeout(captureTagSuggestTimer);
  const row = $("entry-tag-suggestions");
  row.replaceChildren();
  row.classList.add("hidden");
}

function renderCaptureTagSuggestions(tags) {
  const row = $("entry-tag-suggestions");
  row.replaceChildren();
  if (!tags.length) {
    row.classList.add("hidden");
    return;
  }
  const label = document.createElement("span");
  label.className = "muted";
  label.textContent = "Suggested tags:";
  row.appendChild(label);
  for (const tag of tags) {
    const tagChip = chip(`＋ ${tag}`, "tag", () => {
      const box = $("entry-tags");
      const have = box.value.split(",").map((t) => t.trim()).filter(Boolean);
      if (!have.includes(tag)) box.value = [...have, tag].join(", ");
      tagChip.remove();
      if (!row.querySelector(".chip")) row.classList.add("hidden");
    });
    tagChip.title = `Add the "${tag}" tag`;
    row.appendChild(tagChip);
  }
  row.classList.remove("hidden");
}

function scheduleCaptureTagSuggestions() {
  clearTimeout(captureTagSuggestTimer);
  const content = $("entry-content").value.trim();
  // Not worth a round trip for a fragment this short, nothing useful to
  // label yet, and it would just relabel itself a few keystrokes later.
  if (content.length < 20) {
    clearCaptureTagSuggestions();
    return;
  }
  captureTagSuggestTimer = setTimeout(async () => {
    const seq = ++captureTagSuggestSeq;
    const tags = $("entry-tags").value.split(",").map((t) => t.trim()).filter(Boolean);
    let suggested;
    try {
      const result = await apiJson("/entries/suggest-tags", {
        method: "POST",
        body: JSON.stringify({ content, tags }),
      });
      suggested = result.suggested_tags || [];
    } catch {
      suggested = [];
    }
    if (seq !== captureTagSuggestSeq) return; // superseded by a later keystroke
    renderCaptureTagSuggestions(suggested);
  }, 1200);
}

//: Wipes the composer's error line as soon as the person answers it. Bound
//: once per complaint rather than at startup, so a composer that never
//: errored carries no listener at all, and `{ once: true }` means the pair
//: cannot accumulate over a session of near-misses.
function clearCaptureStatusOnInput() {
  const status = $("save-status");
  const clear = () => {
    if (!status.classList.contains("error")) return;
    status.textContent = "";
    status.classList.remove("error");
  };
  $("entry-content")?.addEventListener("input", clear, { once: true });
  $("entry-title")?.addEventListener("input", clear, { once: true });
}

async function saveEntry() {
  const contentBox = $("entry-content");
  const titleBox = $("entry-title");
  const status = $("save-status");
  const button = $("save-btn");

  const content = withTitle(contentBox.value.trim(), titleBox?.value);
  if (!content) {
    //: No exclamation mark (the copy rule), and it clears itself the moment
    //: anything is typed. Reported on 2026-09-09: "the words 'write something
    //: first' is at the bottom of the note capture tab when I didnt do
    //: anything?? maybe I fumbled a button." Nothing ever cleared this line,
    //: so one press of Save (or of Ctrl+S, which reaches the same button) on
    //: an empty box left an error sitting under the composer for the rest of
    //: the session, long after it had stopped being true.
    status.textContent = "Write something first, then save.";
    status.classList.add("error");
    clearCaptureStatusOnInput();
    return;
  }
  const tags = $("entry-tags").value.split(",").map((t) => t.trim()).filter(Boolean);
  const category = await resolveCategoryChoice($("entry-category"));
  if (category === undefined) return;

  // Filing in the background is the default, and the reason is the whole
  // point of the preference: filing asks a local model, so on a small
  // machine this form used to sit disabled behind "Filing…" for seconds
  // per note: reported as "the making of new notes was slow and annoying…
  // I feel like the note panels should disappear while filing and
  // continuing in the backend with a popup notification so I dont have to
  // wait twiddling my thumbs". Choosing a category yourself skips it
  // either way: there is nothing to wait for.
  const deferFiling = !category && (prefsCache.background_filing ?? true);

  button.disabled = true;
  status.classList.remove("error");
  status.textContent = category
    ? "Saving…"
    : deferFiling
      ? "Saving…"
      : modelStatus && !modelStatus.embedding_ready
        ? "Filing… (the search AI is still warming up, this first one can take longer)"
        : "Filing… (the AI is reading and categorising your note)";
  try {
    //: **The pictures go up before the note does.** They were staged as
    //: `staged:<key>` urls while the note had no id (see `captureStagedImages`);
    //: this is the moment the user commits, so the bytes are uploaded and every
    //: placeholder in the text is replaced with the url the upload returned.
    //: A failure throws out of here and the save stops with the reason, a note
    //: saved with a dead `staged:` url in it would be a broken picture forever,
    //: and dropping the picture silently would be worse.
    const stagedUrls = await commitCaptureImages();
    const body = rewriteStagedUrls(content, stagedUrls);
    const saved = await apiJson("/entries", {
      method: "POST",
      body: JSON.stringify({
        content: body,
        tags,
        category,
        document_ids: [...captureDocuments],
        defer_filing: deferFiling,
      }),
    });
    clearStagedImages();
    status.textContent = filedByText(saved);
    if (saved.filing_state === "pending") watchFiling(saved);
    // The note finally has an id, which is the only thing the staged files
    // were ever waiting for. Not awaited: the composer is already clear and
    // the toasts report per file, making Save wait on N uploads would put
    // back exactly the blocking this session removed from filing.
    uploadStagedFiles(saved.id);
    if (saved.similar) {
      // Duplicate detection (Wave B): informational, never blocking.
      toast(
        `Heads up: this is ${Math.round(saved.similar.similarity * 100)}% similar ` +
          `to an existing note, “${saved.similar.preview}”`
      );
    }
    resetCaptureForm(contentBox, titleBox);
    await loadEntries();
    loadSuggestions(); // new categories → fresher recommended questions
    pushUndo(
      "Created a note",
      async () => {
        await api(`/entries/${saved.id}`, { method: "DELETE" });
        await loadEntries();
      },
      async () => {
        await api(`/entries/${saved.id}/restore`, { method: "POST" });
        await loadEntries();
      }
    );
    // Saving from Capture leaves you on Capture, with the note you just wrote
    // now somewhere in a list on another sub-tab. Offer to go to it rather
    // than making you switch tabs and hunt (user request). An offer, not a
    // jump: capturing several thoughts in a row is the common case, and
    // teleporting away after each one would fight that.
    offerJumpToNewNote(saved, status);
  } catch (error) {
    status.textContent = error.message;
    status.classList.add("error");
  } finally {
    button.disabled = false;
  }
}

// "No option to save a note as a draft in the capture section" (user-
// reported). is_draft already existed as a note field, the text-selection
// popup, the Writing Room, and "save this answer as a draft note" in chat
// all set it: but the primary capture box had no path to it. Deliberately
// skips category resolution: a draft is "save this fast, decide later", the
// same reasoning the other three draft-creating call sites already use, 
// none of them file a category either.
async function saveEntryAsDraft() {
  const contentBox = $("entry-content");
  const titleBox = $("entry-title");
  const status = $("save-status");
  const button = $("save-draft-btn");

  const content = withTitle(contentBox.value.trim(), titleBox?.value);
  if (!content) {
    //: No exclamation mark (the copy rule), and it clears itself the moment
    //: anything is typed. Reported on 2026-09-09: "the words 'write something
    //: first' is at the bottom of the note capture tab when I didnt do
    //: anything?? maybe I fumbled a button." Nothing ever cleared this line,
    //: so one press of Save (or of Ctrl+S, which reaches the same button) on
    //: an empty box left an error sitting under the composer for the rest of
    //: the session, long after it had stopped being true.
    status.textContent = "Write something first, then save.";
    status.classList.add("error");
    clearCaptureStatusOnInput();
    return;
  }
  const tags = $("entry-tags").value.split(",").map((t) => t.trim()).filter(Boolean);

  button.disabled = true;
  status.classList.remove("error");
  status.textContent = "Saving as draft…";
  try {
    //: Same commit-then-write order as a full save, a draft is a note with
    //: an id, so its pictures are real from the same moment.
    const stagedUrls = await commitCaptureImages();
    const saved = await apiJson("/entries", {
      method: "POST",
      body: JSON.stringify({
        content: rewriteStagedUrls(content, stagedUrls),
        tags,
        document_ids: [...captureDocuments],
        is_draft: true,
      }),
    });
    clearStagedImages();
    status.textContent = "Saved as a draft, find it later under Drafts in the sidebar.";
    resetCaptureForm(contentBox, titleBox);
    // A draft is still a note with an id, so staged files attach to it the
    // same way. Doing this here rather than in `resetCaptureForm` is what
    // keeps that function from having to know which of its two callers has
    // already taken the list, see its own comment.
    uploadStagedFiles(saved.id);
    await loadEntries();
  } catch (error) {
    status.textContent = error.message;
    status.classList.add("error");
  } finally {
    button.disabled = false;
  }
}

// --- ask ----------------------------------------------------------------------

// Follow-up memory (Round 1): the running conversation, sent back so the
// model can handle "and what about…". Capped so requests stay small.
let conversation = [];
const MAX_CLIENT_HISTORY = 4;
let askController = null; // AbortController for the in-flight stream
let lastQuestion = ""; // powers the Retry button

// Honest label for how the matching notes were found.
const SEARCH_MODE_LABELS = {
  // Both searches ran and their rankings were fused, which is the normal case
  // whenever an embedding backend is up. Named for what it is: "semantic
  // search" would now be a half-truth, and the label is the app's own account
  // of how it found what it is showing you.
  hybrid: "meaning + keywords",
  semantic: "semantic search",
  keyword: "keyword search",
  recent: "recent notes", // broad question → showing recent entries
  // These two were missing and rendered raw, so the panel said "dated", the
  // internal name, in a strip whose whole job is telling you in plain words how
  // the app found what it is showing you.
  dated: "by date",
  none: "nothing searched",
  // Matched the subject, not the stated time, see the note above
  // renderChatMeta's empty-results branch for the reasoning (§38 bug report:
  // a joke tagged joke/jokes/funny, asked about as "two weeks ago", was
  // actually three).
  outside_range: "matched, wrong time",
};

// Say something to a screen reader without putting anything on screen. Used
// for changes whose only visible signal is colour or position.
function announce(message) {
  const region = $("live-region");
  if (!region) return;
  // Clearing first guarantees the change is seen as new even when the same
  // message is announced twice in a row.
  region.textContent = "";
  requestAnimationFrame(() => (region.textContent = message));
}

// Jump to an entry in the Notes tab and flash it, shared by search
// results, most-used, and related-notes chips.
function flashEntry(id) {
  switchTab("notes");
  // The Notes tab is split into sub-tabs, and the note list lives in "browse".
  // Without this the card is found and scrolled to while its whole section is
  // display:none: so jumping to a note from a search result, the graph, or a
  // wiki link silently did nothing (user-reported).
  showNotesSection("browse");
  activeCategory = null;
  // A draft target needs the Drafts filter ON now that drafts are excluded
  // from every other view (user-reported): otherwise jumping to one from
  // Library's "Open" button would find nothing.
  draftsOnly = allEntries.some((e) => e.id === id && e.is_draft);
  // Same reason as the line above and the search reset below: a note that is
  // not pinned is filtered out of Favourites, so jumping to one while that
  // filter is on would scroll to nothing.
  favouritesOnly = false;
  // Clear any active filter too: a note that doesn't match the current search
  // is filtered out of the list, so there'd be nothing to scroll to.
  noteSearch = "";
  const searchBox = $("note-search");
  if (searchBox) searchBox.value = "";
  // **BACKLOG §77 item 2, the page half of "jump to a note."** Everything
  // above already resets category/drafts/search to whatever view actually
  // contains the target (the design question that item scoped: a jump
  // always lands in that reset default view, never in whatever filter the
  // *origin*, Chat, the graph, a document, happened to have active,
  // since most origins have no Notes-tab filter state to preserve at all).
  // With that view now fixed, `resolveNotePage` answers the one thing that
  // reset alone didn't: which *page* of it. Set before `renderEntries()` so
  // the list paints the right page the first time, not the first page
  // followed by a jump.
  const targetPage = resolveNotePage(id);
  if (targetPage) notesCurrentPage = targetPage;
  renderSidebar();
  renderEntries();
  requestAnimationFrame(() => {
    const card = document.querySelector(`#entry-list li[data-id="${id}"]`);
    if (!card) return;
    const reduced = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
    card.scrollIntoView({ behavior: reduced ? "auto" : "smooth", block: "center" });
    // Restart the animation even when the same note is jumped to twice in a
    // row: without the reflow the class is already there and nothing replays.
    card.classList.remove("flash");
    void card.offsetWidth;
    card.classList.add("flash");
    // Announce it too: a colour change alone tells a screen-reader user
    // nothing about where they've just been sent.
    // Just the note's own text: card.textContent would drag in the category
    // chip, every tag, and the confidence badge.
    const body = card.querySelector(".entry-content")?.textContent || "";
    announce(`Showing note: ${body.trim().slice(0, 80)}`);
    clearTimeout(flashEntry.timer);
    flashEntry.timer = setTimeout(() => card.classList.remove("flash"), 2700);
  });
}

// ROADMAP.md Tier 2 §13: changeRow's View button only ever reached notes and
// documents: reminders and categories had no navigation target at all, on
// top of having no backend id/name resolver. Same shape as flashEntry above.
async function flashReminder(id) {
  switchTab("reminders");
  // The change that brought us here (setting or completing a reminder) may
  // not match whatever filter was last active, "open" is the default, and
  // completing one is exactly the case where it would just have vanished.
  reminderFilter = "all";
  for (const b of document.querySelectorAll("#reminder-filter button")) {
    b.classList.toggle("active", b.dataset.filter === "all");
  }
  await loadReminders();
  requestAnimationFrame(() => {
    const item = document.querySelector(`#reminder-groups li[data-id="${id}"]`);
    if (!item) return;
    const reduced = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
    item.scrollIntoView({ behavior: reduced ? "auto" : "smooth", block: "center" });
    item.classList.remove("flash");
    void item.offsetWidth;
    item.classList.add("flash");
    announce(`Showing reminder: ${(item.textContent || "").trim().slice(0, 80)}`);
    clearTimeout(flashReminder.timer);
    flashReminder.timer = setTimeout(() => item.classList.remove("flash"), 2700);
  });
}

// Categories have no single note to scroll to, "View" means "show me what's
// in it", the same job the sidebar's own category filter already does.
function flashCategory(name) {
  switchTab("notes");
  showNotesSection("browse");
  activeCategory = name;
  draftsOnly = false;
  noteSearch = "";
  const searchBox = $("note-search");
  if (searchBox) searchBox.value = "";
  renderSidebar();
  renderEntries();
}

// A raw search result the user can click to open the note (Wave C).
function clickableResult(entry) {
  const li = entryItem(entry);
  li.classList.add("clickable-result");
  li.title = "Open this note in the Notes tab";
  li.addEventListener("click", () => flashEntry(entry.id));
  return li;
}

// ROADMAP.md item 36: which retrieved note backs which sentence of a direct
// Q&A answer: surfaced the same understated way `match_info`'s own badges
// already are (a strip of small chips, not a rewrite of the answer's own
// text). One chip per *note* (not per sentence: several grounded sentences
// often share a note, and a chip per sentence would repeat itself), the
// chip's title carrying the actual sentence(s) it backs. Clicking a chip
// opens that note, same as a search result row already does.
// **Numbered citations in the answer itself.** Asked for directly: "inline
// referencing with hyperlinks in ai chat messages would be amazing."
//
// The data for this already existed and only ever reached a chip row *under*
// the answer: `ground_answer_sentences` (ai/grounding.py) returns
// {sentence, note_id} pairs, scored by word overlap against the notes that
// were actually retrieved: so the app already knows, per sentence, which
// note backs it. What it did not do was say so where the sentence is, which
// is the only place the claim and its source are read together.
//
// Deliberately conservative about *where* a marker may go: it walks real text
// nodes and only places one where a grounded sentence is found whole inside a
// single node. A sentence split across an <em> or a link is skipped rather
// than reassembled: a citation attached to the wrong half of a sentence is
// worse than no citation, and the chip row below still lists every source
// either way, so nothing is lost by skipping.
//: **`answerEl` is every prose block of the turn, latest first, not one
//: element.** Reported: an agent answer and a skill run showed no markers at
//: all, while a plain Ask answer showed them. The cause is one word:
//: `querySelector`. A skill run's timeline writes each step's prose into its
//: own `.bubble-answer` node (`startAnswer`, called again after every `step`
//: event), so the *first* one is step 1's narration and the run's real answer
//: is the last. The backend grounds the turn's whole prose as one string, so
//: every sentence it returned came from the final answer, and every one of
//: them was hunted for in the wrong paragraph.
//:
//: Latest first because a run repeats itself: a sentence the closing summary
//: and an intermediate step both contain belongs on the summary, which is
//: what a reader takes away. A step's own unique sentence still gets its
//: marker where it is, which is what walking all of them buys over simply
//: picking the last.
//: `orderedSources` is the Sources panel's own list, in the order it numbers
//: them. INBOX 81's second half asks that "the sources list numbers web
//: results after the notes so [5] resolves to a site", and reading the two
//: numberings side by side showed a wider problem than that: the panel counts
//: its rows from 1 in list order (notes, then what the turn touched, then
//: what it read off the web), while the block below counted from 1 in
//: *order first cited* among the grounded sentences. Those are two unrelated
//: sequences, so [2] in the prose and 2 in the panel were only ever the same
//: source by luck, with no web results involved at all.
//:
//: Passed rather than recomputed here, because the panel builds the list from
//: three inputs this function does not have, and two functions deriving "the
//: same" order independently is how they drift apart again. Optional, so the
//: Ask box's own call keeps its existing behaviour until it grows a panel to
//: agree with.
function addInlineCitations(answerEl, sentences, rawResults, orderedSources = null) {
  const targets = [
    ...(answerEl && !answerEl.nodeType ? [...answerEl] : answerEl ? [answerEl] : []),
  ].reverse();
  if (!targets.length || !sentences || !sentences.length) return;
  const byId = new Map((rawResults || []).map((entry) => [entry.id, entry]));
  // One number per note, in the order they are first cited, the numbering a
  // reader expects, rather than note ids, which mean nothing to anyone.
  const numberFor = new Map();
  if (orderedSources && orderedSources.length) {
    //: The panel's numbering, so a marker and a row that carry the same digit
    //: are the same source. A note the panel did not list (it caps its rows)
    //: keeps a number after the listed ones rather than none at all: an
    //: unnumbered citation is worse than one whose row needs scrolling to.
    orderedSources.forEach((source, index) => {
      if (source && source.kind === "note") numberFor.set(source.id, index + 1);
    });
    let next = orderedSources.length + 1;
    for (const g of sentences) {
      if (!numberFor.has(g.note_id)) numberFor.set(g.note_id, next++);
    }
  } else {
    for (const g of sentences) {
      if (!numberFor.has(g.note_id)) numberFor.set(g.note_id, numberFor.size + 1);
    }
  }
  // Longest first: when one grounded sentence is a prefix of another, marking
  // the short one first would leave the long one unmatchable.
  const wanted = [...sentences]
    .filter((g) => (g.sentence || "").trim().length > 12)
    .sort((a, b) => (b.sentence || "").length - (a.sentence || "").length);
  const placed = new Set();
  //: One queue over all of them, and one `placed` set, so a sentence gets
  //: exactly one marker across the whole turn rather than one per block.
  const queue = [];
  for (const target of targets) {
    const walker = document.createTreeWalker(target, NodeFilter.SHOW_TEXT);
    while (walker.nextNode()) queue.push(walker.currentNode);
  }

  // A queue rather than a plain loop, because placing a marker *splits* the
  // text node it was found in. The remainder is a new node that the tree
  // walker never saw, and a paragraph routinely carries several grounded
  // sentences: measured: two sentences in one <p> produced exactly one
  // marker before this, because the first placement ended the node's turn.
  // Pushing the tail back on is what lets the rest of the paragraph be
  // scanned for the sentences that are still unplaced.
  while (queue.length) {
    const node = queue.shift();
    if (!node.parentNode || node.parentNode.closest?.(".answer-citation")) continue;
    for (const g of wanted) {
      const key = `${g.note_id}:${g.sentence}`;
      if (placed.has(key)) continue;
      const text = node.textContent;
      const at = text.indexOf(g.sentence.trim());
      if (at === -1) continue;
      const end = at + g.sentence.trim().length;
      const tail = node.splitText(end);
      // Both halves go back on. The tail is the rest of the paragraph, and
      // the head still holds everything *before* this match, which is where
      // an earlier sentence in the same paragraph lives. Measured: with only
      // the tail re-queued, a paragraph whose second sentence was the longer
      // one (so matched first) never got a marker on its first sentence.
      queue.unshift(tail);
      queue.unshift(node);
      const marker = document.createElement("sup");
      marker.className = "answer-citation";
      const link = document.createElement("button");
      link.type = "button";
      link.className = "answer-citation-link";
      const entry = byId.get(g.note_id);
      // A note a tool read mid-turn is not in `rawResults`; the backend
      // sends its opening words on the entry itself for exactly this case.
      const name = noteLabel({ content: entry?.content || g.label || "" }, 40);
      link.textContent = String(numberFor.get(g.note_id));
      link.title = `Open the note this came from: ${name}`;
      link.setAttribute("aria-label", `Source ${numberFor.get(g.note_id)}: ${name}`);
      link.addEventListener("click", (event) => {
        event.stopPropagation();
        flashEntry(g.note_id);
      });
      marker.appendChild(link);
      tail.parentNode.insertBefore(marker, tail);
      placed.add(key);
      break; // this node is now split; its tail is at the head of the queue
    }
  }
}

// The "nothing in your notes, but…" row. Sent only on the empty path (see
// `_related_elsewhere`, routes_chat.py): a question whose answer lives in a
// document, a saved chat or a reminder used to end at "I couldn't find any
// saved notes matching that question", which is true and a dead end.
//
// Chips, matching every other "here is something to open" row in this app,
// each landing on the thing itself rather than on a search for it.
function renderRelatedElsewhere(target, items) {
  if (!target || !items || !items.length) return;
  const row = document.createElement("div");
  row.className = "answer-related";
  const label = document.createElement("span");
  label.className = "muted answer-grounding-label";
  label.textContent = "Elsewhere in your notebook:";
  row.appendChild(label);
  const icons = { document: "ph:file-text", chat: "ph:chat-circle", reminder: "ph:bell" };
  for (const item of items) {
    const button = document.createElement("button");
    button.type = "button";
    button.className = "chip chip-interactive answer-related-chip";
    setNoteLabel(button, icons[item.kind] || "ph:link", item.label || item.kind, 120);
    button.title = `Open this ${item.kind}`;
    button.addEventListener("click", () => {
      if (item.kind === "document") {
        switchTab("documents");
        openDocument(item.id);
      } else if (item.kind === "chat") {
        switchTab("chat");
        openConversation?.(item.id);
      } else if (item.kind === "reminder") {
        switchTab("reminders");
      }
    });
    row.appendChild(button);
  }
  target.appendChild(row);
}

//: `question`, when the caller knows it, is what turns a click into a
//: correction: opening the third source after asking something is the one
//: signal the search has that its own order was wrong (WORLD_CLASS_PLAN I7,
//: and `search_manager._learned_order`, which has been reading these
//: corrections since Brief 23 while nothing in the browser wrote one). Left
//: optional because the third caller rebuilds an old chat from storage, and
//: a click on a source from last week is not evidence about today's ranking.
function renderAnswerGrounding(target, sentences, rawResults, answerEl = null, question = "") {
  if (!target) return;
  // The markers go in the answer itself; the chip row below is their key.
  // Both are built from the same `sentences`, so they cannot disagree about
  // which note is number 2.
  addInlineCitations(answerEl, sentences, rawResults);
  target.replaceChildren();
  if (!sentences || !sentences.length) {
    target.classList.add("hidden");
    return;
  }
  const byId = new Map((rawResults || []).map((entry) => [entry.id, entry]));
  const byNote = new Map(); // note_id -> sentences[]
  const labelFor = new Map(); // note_id -> backend label, for touched notes
  for (const g of sentences) {
    if (!byNote.has(g.note_id)) byNote.set(g.note_id, []);
    byNote.get(g.note_id).push(g.sentence);
    if (g.label && !labelFor.has(g.note_id)) labelFor.set(g.note_id, g.label);
  }
  const label = document.createElement("span");
  label.className = "muted answer-grounding-label";
  label.textContent = "Grounded in:";
  target.appendChild(label);
  let n = 0;
  for (const [noteId, forSentences] of byNote) {
    const entry = byId.get(noteId);
    n += 1;
    const chip = document.createElement("button");
    chip.type = "button";
    chip.className = "chip result-reason-chip result-reason-connected answer-grounding-chip";
    // Numbered to match the markers `addInlineCitations` puts in the answer, 
    // the row is the key to those, so the two have to count the same way.
    // `setNoteLabel`, not `setLabel`: the second half of this string is the
    // note's own Markdown, and the number is app-written, so they cannot go
    // through the renderer as one string (`1. ` is an ordered-list marker).
    setNoteLabel(chip, `ph:file-text ${n}.`, entry?.content || labelFor.get(noteId) || "", 30);
    chip.title = forSentences.join(" ");
    chip.addEventListener("click", () => {
      if (question) {
        apiJson("/learned/corrections", {
          method: "POST",
          silent: true,
          body: JSON.stringify({
            kind: "open_after_ask",
            subject: { question, entry_id: noteId },
          }),
        }).catch(() => {});
      }
      flashEntry(noteId);
    });
    target.appendChild(chip);
  }
  target.classList.remove("hidden");
}

// The Ask box's "that isn't a question about your notes" card (§35A).
//
// Deliberately not rendered as an answer. Reported after the first version:
// a paragraph of instructions where the answer goes, next to a results panel
// saying "No matching records", reads as the app having broken rather than as
// guidance. Here the examples are buttons, a way forward from the same place,
// which also teaches the shape of a question that works.
function renderAskHint(box, hint) {
  box.replaceChildren();
  const card = document.createElement("div");
  card.className = "ask-hint";
  const text = document.createElement("p");
  text.className = "ask-hint-text";
  text.textContent = hint.text;
  card.appendChild(text);
  const row = document.createElement("div");
  row.className = "row ask-hint-examples";
  for (const example of hint.examples || []) {
    row.appendChild(
      smallButton(example, `Ask: ${example}`, () => {
        $("question").value = example;
        askQuestion(example);
      })
    );
  }
  if (row.childElementCount) card.appendChild(row);
  box.appendChild(card);
}

//: **The badge in the answer head, and the sentence behind it.**
//: The chip ellipsises now rather than wrapping the head onto a second line
//: (01-forms-settings.css, `.answer-model`, records the measurements), and an
//: ellipsis cuts the end off a model id, which is where the useful part of one
//: lives: `…Qwen2.5-14B-Instruct-GGUF:Q4_K_M`. So the full phrase always goes
//: on the `title` even when the visible text is complete, and the visible text
//: is as short as the fact allows: "answered by" spent about 100px of a 356px
//: column saying what a chip beside the words "AI answer" already says.
function setAnsweredBy(text, full) {
  const chip = $("answered-by");
  chip.textContent = text;
  //: Removed rather than emptied: an empty `title` is still a title, and a
  //: tooltip that opens blank reads as a broken one.
  if (full) chip.title = full;
  else chip.removeAttribute("title");
}

function renderChatMeta(meta) {
  $("search-mode").textContent = SEARCH_MODE_LABELS[meta.search_mode] || meta.search_mode;
  // "offline" only when Ollama is genuinely down, not merely because a
  // question found nothing to answer from.
  if (meta.answered_by) setAnsweredBy(meta.answered_by, `Answered by ${meta.answered_by}`);
  else if (meta.ollama_running === false) {
    setAnsweredBy("chat model offline", "The chat model is not running, so nothing answered this");
  } else setAnsweredBy("", "");
  const rawList = $("raw-results");
  rawList.replaceChildren();
  if (meta.raw_results.length === 0 && meta.search_mode === "none") {
    // Nothing was searched for, the message was not a question about the
    // notes. "No matching records" would report a failed search that never
    // happened, which is the half of the greeting case that read as broken.
    $("chat-results").classList.remove("hidden");
  $("ask-idle")?.classList.add("hidden");
    document.querySelector(".chat-half:last-child")?.classList.add("hidden");
    return;
  }
  document.querySelector(".chat-half:last-child")?.classList.remove("hidden");
  if (meta.search_mode === "outside_range" && meta.raw_results.length) {
    // Matched what was asked about, not when it was asked about, the note
    // is real, the stated time was just wrong (reported directly: a joke
    // asked about as "two weeks ago" that was actually three). Said before
    // the results, not folded silently into them, so this never reads as a
    // date-scoped answer it isn't.
    const li = document.createElement("li");
    li.className = "muted";
    li.textContent = meta.when_phrase
      ? `Nothing about this in “${meta.when_phrase}”: here's what matched from another time:`
      : "Nothing in that time range, here's what matched from another time:";
    rawList.appendChild(li);
  }
  if (meta.raw_results.length === 0) {
    const li = document.createElement("li");
    li.className = "muted";
    // A dated question that found nothing has *two* facts to report, and only
    // saying the first is what makes an empty result look like a broken
    // search: nothing matched, **and** the window you named is why it was
    // looking so narrowly. Naming the phrase is also the fastest route to the
    // fix, because the next thing to try is asking again without it.
    li.textContent =
      meta.search_mode === "dated" && meta.when_phrase
        ? `Nothing matching “${meta.when_phrase}”. Try asking without it.`
        : "No matching records.";
    rawList.appendChild(li);
  }
  // Notes that came along because they are *connected* to a match are labelled
  // as such. Without it the panel shows notes about something else with no
  // explanation, which reads as the search having misfired, and the whole
  // point of pulling them in is that the person can see the connection.
  const connected = new Set(meta.connected_ids || []);
  const matchInfo = meta.match_info || {};
  for (const entry of meta.raw_results) {
    const row = clickableResult(entry);
    const badge = matchReasonBadge(matchInfo[entry.id]);
    if (badge) {
      if (connected.has(entry.id)) row.classList.add("result-connected");
      if (matchInfo[entry.id]?.type === "connected_2hop") row.classList.add("result-connected-2hop");
      row.appendChild(badge);
    }
    rawList.appendChild(row);
  }
  $("chat-results").classList.remove("hidden");
  $("ask-idle")?.classList.add("hidden");
}

// Why a result showed up, as a badge, not a footnote. Reported directly:
// the one existing explanation ("Link linked to a match") was a muted chip
// easy to miss, and every *other* result, the actual matches, carried no
// reason at all, so "why is this here?" only had an answer for the minority
// of rows that arrived by connection rather than by matching. `match_info`
// (search/search_manager.py's `_retrieve`) now carries real provenance for
// the rest: a cosine similarity score for a semantic hit, the words that
// matched for a keyword hit, both for a hybrid one.
const MATCH_REASON_LABEL = {
  // `info.reason` is the link's own reason, when whoever made the link gave
  // one ("both about scheduling"), asked for directly: does a link's
  // reason show up here too, not just on the graph and in Trace. It does
  // now (search_manager.graph_expansion carries it through).
  connected: (info) => ({
    text: info.reason ? `ph:link Linked (${info.reason})` : "ph:link Linked to a match",
    title: info.reason
      ? `This note didn't match your question, it's here because it's linked to one that did: ${info.reason}.`
      : "This note didn't match your question, it's here because it is linked to one that did.",
  }),
  // ROADMAP.md item 33: an opt-in second hop, linked to something linked
  // to a match, not to the match itself. Real evidence, weaker evidence;
  // its own badge text says so rather than reading identically to a direct
  // connection, and `.result-connected-2hop` (style.css) renders it dimmer.
  connected_2hop: (info) => ({
    text: info.reason ? `ph:link Two steps away (${info.reason})` : "ph:link Two steps from a match",
    title: info.reason
      ? `This note is linked to a note that's linked to a match, not to the match itself: ${info.reason}.`
      : "This note is linked to a note that's linked to a match, not to the match itself, weaker evidence than a direct connection.",
  }),
  semantic: (info) => ({
    text: `ph:target ${Math.round(info.score * 100)}% similar`,
    title: `Matched by meaning, not exact words, ${Math.round(info.score * 100)}% cosine similarity to your question.`,
  }),
  keyword: (info) => ({
    text: `ph:magnifying-glass Matched “${info.terms.join("”, “")}”`,
    title: `Matched the word(s) “${info.terms.join(", ")}” in your question.`,
  }),
  hybrid: (info) => ({
    text: `ph:target ${Math.round(info.score * 100)}% similar · “${info.terms.join("”, “")}”`,
    title: `Matched both by meaning (${Math.round(info.score * 100)}% similarity) and by the word(s) “${info.terms.join(", ")}”.`,
  }),
};

function matchReasonBadge(info) {
  if (!info || !MATCH_REASON_LABEL[info.type]) return null;
  const { text, title } = MATCH_REASON_LABEL[info.type](info);
  const badge = document.createElement("span");
  badge.className = `chip result-reason-chip result-reason-${info.type}`;
  setLabel(badge, text);
  badge.title = title;
  return badge;
}

// Longer than the backend's own 120s per-chunk Ollama timeout (see the
// idle-read guard inside streamChat below) so a real "offline" answer from
// that always has time to arrive first.
const STREAM_IDLE_TIMEOUT_MS = 150_000;

// The one NDJSON stream reader, shared by the Notes quick-ask and the
// Chat tab (Wave C). Callers own all rendering via the handlers.
async function streamChat({
  question,
  history,
  persona,
  mode,
  useTools,
  noteIds,
  imageMediaIds,
  documentIds,
  fileIds,
  boardIds,
  skill,
  skillInputs,
  skillFromStep,
  skillManual,
  skillManualNote,
  plan,
  notesOnly,
  attachedNotesOnly,
  answeringAgent,
  signal,
  onMeta,
  onPlan,
  onStep,
  onResult,
  onLimit,
  onThinking,
  onAnswer,
  onTool,
  onConfirm,
  onAsk,
  onRunSkill,
  onRunPlan,
  onCompressReview,
  onHint,
  onStats,
  onGrounding,
  onRelated,
}) {
  const body = { question, history: history || [] };
  if (persona) body.persona = persona;
  // Per-turn, not a setting: one quick answer shouldn't change the default
  // for every answer after it.
  if (mode) body.mode = mode;
  if (typeof useTools === "boolean") body.use_tools = useTools;
  if (notesOnly) body.notes_only = true;
  // The deliberately-closed-set case (Trace's "Generate story from path"):
  // retrieval must not add notes beyond the ones the caller attached.
  if (attachedNotesOnly) body.attached_notes_only = true;
  // A reply to the agent's own question ("yes", "ok") reads as small talk to
  // intent.classify, correctly, in isolation, which would otherwise route
  // it to the tool-less conversational path and strand whatever the model
  // was asking about (Tier 1 §4). The caller already knows this reply is
  // answering a pending `ask` event, so it says so rather than making the
  // classifier guess from three letters.
  if (answeringAgent) body.answering_agent = true;
  if (noteIds && noteIds.length) body.note_ids = noteIds;
  // Vision-capable models (ROADMAP.md's largest open item): ids from
  // /media/upload, the same endpoint the note/document editors already use
  // for drag-and-drop images: see `_resolve_chat_images` (routes_chat.py)
  // for how an id becomes a data URI the provider actually sends.
  if (imageMediaIds && imageMediaIds.length) body.image_media_ids = imageMediaIds;
  //: **Documents and files were staged, drawn, persisted -- and never sent
  //: here.** `streamChat` took `noteIds` and `imageMediaIds` and nothing else,
  //: so an attached document reached `/chat` (the non-streaming path, used by
  //: Ask) and never `/chat/stream`, which is the path the Chat tab actually
  //: uses. The chip appeared on the message, the id was saved on the
  //: conversation, and the model was never given a word of it -- the same
  //: failure `document_ids` shipped once before, one layer further out.
  if (documentIds && documentIds.length) body.document_ids = documentIds;
  if (fileIds && fileIds.length) body.file_ids = fileIds;
  //: A mind map attached by hand (MINDMAP_PLAN.md §5 item 11). Its own
  //: field, not folded into `note_ids`, because a board's `content` is the
  //: single line `# My map`, sent as a note the model would get a heading
  //: and be told it was a map. `_attached_boards` (routes_chat.py) turns the
  //: id into the outline instead.
  if (boardIds && boardIds.length) body.board_ids = boardIds;
  // Running a skill sends its name, not its prompt: the server owns what a
  // skill is, the steps, the values, the tools it may use, so the two
  // definitions can't drift apart.
  if (skill) {
    body.skill = skill;
    if (skillInputs && Object.keys(skillInputs).length) body.skill_inputs = skillInputs;
    // Resuming: the steps before this one ran in an earlier attempt and are
    // not repeated. Sent as an index rather than as a list of what to skip,
    // so the server stays the one place that knows what the steps are.
    if (skillFromStep) body.skill_from_step = skillFromStep;
  }
  // A plan the model just made. Carries its own steps because nothing saved
  // it: that is the only way it differs from a skill run, here and on the
  // server.
  const hasPlan = plan && plan.steps && plan.steps.length;
  if (hasPlan) body.plan = plan;
  // Manual (step-through) mode: a pause after every completed step. Applies
  // equally to a saved skill or a plan the model just drew, both run
  // through the same step-by-step runner server-side. Sent on every call for
  // this run, resume included, since a run started manual stays manual.
  if (skill || hasPlan) {
    if (skillManual) body.skill_manual = true;
    if (skillManualNote) body.skill_manual_note = skillManualNote;
  }
  // NDJSON over a plain POST, deliberately, not a WebSocket. A WebSocket was
  // tried here and reverted: it needed the session on a second thread (a
  // SQLAlchemy Session is not thread-safe), it had to be mounted outside the
  // `locked` dependency and re-implement auth by hand, and a WS handshake is
  // exempt from the same-origin policy that protects this `fetch`, any page
  // the user had open could have opened it. `fetch` + a reader gives the same
  // token-by-token delivery with none of that.
  const response = await fetch("/chat/stream", {
    method: "POST",
    headers: {
      "Content-Type": "application/json",
      "X-Auth-Token": authToken(),
      // Missing here, this fetch is hand-rolled rather than going through
      // api()/apiJson() (it needs the raw streaming body, which those don't
      // expose): and every one of the app's *other* fetches gets this
      // header automatically, so it was easy to not notice this one never
      // did. Reported directly: a space hidden from "All spaces" still
      // surfaced its notes from Ask's semantic search. The real bug was
      // wider than that one symptom, with no X-Workspace-ID at all,
      // get_session() never populates session.info["workspace_id"], so
      // database.py's workspace filter never runs, and *every* chat or Ask
      // turn searched every space regardless of which one was active,
      // hidden or not.
      "X-Workspace-ID": activeSpaceId(),
    },
    body: JSON.stringify(body),
    signal,
  });
  if (response.status === 401) {
    showLockScreen(false);
    throw new Error("Locked");
  }
  if (!response.ok) {
    const detail = await response.json().catch(() => ({}));
    throw new Error(detail.detail || `Request failed (${response.status})`);
  }

  const reader = response.body.getReader();
  const decoder = new TextDecoder();
  let buffered = "";
  while (true) {
    // **No timeout on the stream** (reported: "the AI fails to respond
    // while still saying it is writing"). The backend's own read against
    // Ollama times out and turns into a real "offline" line on the wire, 
    // but only for a hang *inside that one socket call*. Anything that
    // stalls the backend before or between chunks (retrieval, a stuck
    // lock, a dead process) has nothing to catch it, and `reader.read()`
    // then waits forever with no sign of life. `STREAM_IDLE_TIMEOUT_MS` is
    // comfortably longer than the backend's own 120s per-chunk timeout, so
    // a real recovery message from *that* always wins the race; this is
    // only for the case where nothing, not even an error, ever arrives.
    const chunk = await Promise.race([
      reader.read(),
      new Promise((_, reject) =>
        setTimeout(
          () => reject(new Error("stream_idle_timeout")),
          STREAM_IDLE_TIMEOUT_MS
        )
      ),
    ]).catch((err) => {
      if (err.message === "stream_idle_timeout") {
        reader.cancel().catch(() => {}); // stop the underlying fetch too
        throw new Error(
          "The model stopped responding. It may still be loading a large " +
            "model, or Ollama may have stalled, try again, or check " +
            "Settings → Models."
        );
      }
      throw err;
    });
    const { done, value } = chunk;
    if (done) break;
    buffered += decoder.decode(value, { stream: true });
    const lines = buffered.split("\n");
    buffered = lines.pop(); // last piece may be a partial line
    for (const line of lines) {
      if (!line.trim()) continue;
      let event;
      // One malformed line must not abort a whole answer. Before this, a
      // single bad frame threw out of the read loop and the user saw a
      // half-written reply with no error.
      try {
        event = JSON.parse(line);
      } catch (parseErr) {
        recordBrowserLog("WARN", [`[Chat stream] Unparseable line: ${line.slice(0, 80)}`]);
        continue;
      }
      if (event.type === "meta") onMeta(event);
      else if (event.type === "plan" && onPlan) onPlan(event);
      else if (event.type === "step" && onStep) onStep(event);
      else if (event.type === "result" && onResult) onResult(event);
      else if (event.type === "limit" && onLimit) onLimit(event);
      else if (event.type === "thinking") onThinking(event.delta);
      else if (event.type === "answer") onAnswer(event.delta);
      else if (event.type === "tool" && onTool) onTool(event);
      else if (event.type === "confirm" && onConfirm) onConfirm(event);
      else if (event.type === "ask" && onAsk) onAsk(event);
      else if (event.type === "run_skill" && onRunSkill) onRunSkill(event);
      else if (event.type === "run_plan" && onRunPlan) onRunPlan(event);
      else if (event.type === "compress_review" && onCompressReview) onCompressReview(event);
      else if (event.type === "hint" && onHint) onHint(event);
      else if (event.type === "stats" && onStats) onStats(event);
      // ROADMAP.md item 36: which retrieved note backs which sentence of a
      // direct-Q&A answer. Only ever sent for that path (routes_chat.py).
      else if (event.type === "grounding" && onGrounding) onGrounding(event);
      // Sent only when a question found no notes at all, the notebook is
      // more than its notes, so the answer names what else mentions it
      // (routes_chat.py's `_related_elsewhere`).
      else if (event.type === "related" && onRelated) onRelated(event);
      else if (event.type === "error") {
        // The server caught something mid-stream and said so. Surfacing it
        // beats the silent truncation this used to be.
        throw new Error(event.message || "The answer stopped early.");
      }

      if (event.type === "tool" && event.ok === false) {
        recordBrowserLog("WARN", [
          `[Agent tool error] ${event.label || event.name || "?"}: ${event.error || "unknown error"}`,
        ]);
      }
    }
  }
}

// Live markdown while streaming. Re-parsing the WHOLE accumulated answer on
// every animation frame is what made long answers feel laggy (each frame
// rebuilt the entire DOM). We now coalesce updates to ~15fps and skip the
// work entirely when the text hasn't changed: smooth, and far less main-
// thread churn, so other animations (the typing dots) don't stutter.
const LIVE_RENDER_INTERVAL_MS = 66;
function liveMarkdownRenderer(box) {
  let latest = "";
  let rendered = null;
  let timer = null;
  let lastRun = 0;

  const flush = () => {
    timer = null;
    lastRun = performance.now();
    if (latest === rendered) return; // nothing new since last paint
    rendered = latest;
    renderMarkdown(box, latest);
  };

  const render = (text) => {
    latest = text;
    if (timer) return;
    const wait = Math.max(0, LIVE_RENDER_INTERVAL_MS - (performance.now() - lastRun));
    timer = setTimeout(flush, wait);
  };
  //: **The last paint has to be cancellable, or it lands after the turn is
  //: over.** Measured while fixing INBOX 40: a skill run's citation markers
  //: were placed correctly and then vanished within a frame or two, and this
  //: is what removed them. Every delta schedules a paint up to
  //: `LIVE_RENDER_INTERVAL_MS` in the future; the stream then ends,
  //: `finalise()` re-renders each step from its raw markdown and the caller
  //: puts the markers in, and *then* the timer that was already armed fires
  //: and repaints the box from `latest`, throwing them away again. Nothing
  //: about it is visible: the prose is identical, only the markers are gone,
  //: which is why it read as "citations do not work in a skill run" rather
  //: than as a race.
  render.stop = () => {
    if (timer) clearTimeout(timer);
    timer = null;
    rendered = latest; // so a later call cannot decide it still owes a paint
  };
  return render;
}

// Ask ⇄ Stop while a stream is in flight.
function setAsking(active) {
  $("ask-btn").classList.toggle("hidden", active);
  $("stop-btn").classList.toggle("hidden", !active);
  $("question").disabled = active;
}

function stopAnswer() {
  if (askController) askController.abort();
}

function newChat() {
  conversation = [];
  lastQuestion = "";
  $("chat-results").classList.add("hidden");
  $("ask-idle")?.classList.remove("hidden");
  $("new-chat-btn").classList.add("hidden");
  $("ask-status").textContent = "";
  $("question").value = "";
  loadSuggestions();
}

// Echo the question above its answer. Without it, an answer that has been on
// screen a while, or one you scrolled back to, is a paragraph with no
// subject.
function renderAskedQuestion(question) {
  const holder = $("asked-question");
  if (!holder) return;
  holder.replaceChildren();
  if (!question) {
    holder.classList.add("hidden");
    return;
  }
  const label = document.createElement("span");
  label.className = "asked-label";
  label.textContent = "You asked: ";
  const text = document.createElement("span");
  text.className = "asked-text";
  text.textContent = question;
  holder.append(label, text);
  holder.classList.remove("hidden");
}

async function askQuestion(preset) {
  const status = $("ask-status");
  const questionBox = $("question");

  const question = (preset ?? questionBox.value).trim();
  if (!question) {
    status.textContent = "Type a question first!";
    status.classList.add("error");
    return;
  }
  lastQuestion = question;

  // A new answer is coming, hide the suggestion/recent chips and the
  // per-answer action buttons until it lands.
  $("suggested-questions").classList.add("hidden");
  hide("retry-btn", "copy-btn", "speak-btn");
  setAsking(true);
  status.classList.remove("error");
  status.textContent =
    modelStatus && modelStatus.embedding_ready
      ? "Searching your notes by meaning…"
      : "Searching your notes…";

  // Reset the output areas for the new answer.
  const answerBox = $("ai-answer");
  const thinkingBox = $("thinking-box");
  const thinkingText = $("ai-thinking");
  renderAskedQuestion(question);
  answerBox.textContent = "";
  answerBox.appendChild(typingDots()); // until the first token arrives
  $("ai-answer-grounding").replaceChildren();
  $("ai-answer-grounding").classList.add("hidden");
  thinkingText.textContent = "";
  thinkingBox.classList.add("hidden");
  thinkingBox.open = false;

  let answerRaw = "";
  let stopped = false;
  let groundingRawResults = []; // set by onMeta, read by onGrounding
  //: Kept beyond the callback that receives them, because the answer element
  //: is rebuilt after the stream ends and the markers have to be put back.
  let groundedSentences = [];
  // The box explained itself instead of answering, so the final markdown
  // pass, the saved turn and the answer actions all sit this one out.
  let hinted = false;
  const renderLive = liveMarkdownRenderer(answerBox);
  askController = new AbortController();
  try {
    // Stream: raw results arrive first, then thinking/answer tokens live.
    await streamChat({
      question,
      history: conversation.slice(-MAX_CLIENT_HISTORY),
      // Sent per turn now that this box has its own picker. It always obeyed
      // the *saved* mode via the server's fallback; carrying it explicitly is
      // what makes changing the box's dropdown affect the very next answer
      // rather than only the one after the preference round-trips.
      mode: $("ask-mode-select")?.value || null,
      useTools: false, // the quick-ask box is pure Q&A; actions live in the Chat tab
      // This box interrogates the notebook and nothing else (§35A). Sent as a
      // flag rather than left to the classifier, which is right about "hey"
      // being small talk: it is this surface that doesn't want small talk.
      notesOnly: true,
      signal: askController.signal,
      onMeta: (meta) => {
        renderChatMeta(meta);
        groundingRawResults = meta.raw_results || [];
        status.textContent = "The model is writing…";
      },
      onThinking: (delta) => {
        answerBox.querySelector(".typing-dots, .typing-label")?.remove();
        // Auto-expand while the model reasons (user request).
        thinkingBox.classList.remove("hidden");
        thinkingBox.open = true;
        thinkingText.textContent += delta;
        keepAtBottom(thinkingText); // follow the reasoning, unless scrolled away
        status.textContent = "The model is thinking…";
      },
      onAnswer: (delta) => {
        //: The first answer token is the moment "waiting" becomes "writing",
        //: so the indicator changes with it. `setPhase` is idempotent, so
        //: calling it on every delta costs nothing.
        answerBox.querySelector(".typing-dots")?.setPhase?.("writing");
        if (thinkingBox.open) thinkingBox.open = false; // reasoning done → tuck away
        answerRaw += delta;
        // Same caret the Chat tab's timeline gets, for the same reason, see
        // `.is-streaming` in 01-forms-settings.css. Set here rather than
        // before the request because the dots own the "nothing yet" state.
        answerBox.classList.add("is-streaming", "is-generating");
        renderLive(answerRaw); // markdown renders AS it streams (user request)
        status.textContent = "The model is writing…";
      },
      onHint: (event) => {
        // Not an answer, so it does not go through the markdown renderer or
        // into the conversation: it is the box explaining itself.
        hinted = true;
        renderAskHint(answerBox, event);
        status.textContent = "";
      },
      onRelated: (event) => {
        renderRelatedElsewhere($("ai-answer-grounding"), event.items);
      },
      onGrounding: (event) => {
        //: Remembered as well as rendered, see the re-application after the
        //: final markdown pass below, which is why the inline markers were
        //: never visible.
        groundedSentences = event.sentences || [];
        renderAnswerGrounding(
          $("ai-answer-grounding"),
          event.sentences,
          groundingRawResults,
          answerBox,
          question
        );
      },
    });

    // Final render (catches anything after the last animation frame).
    if (!hinted) renderMarkdown(answerBox, answerRaw);
    //: **And the citations go back in.** Reported: *"in the ask tab, no inline
    //: or grounding links to the notes viewed and referenced appear."* The
    //: markers were being inserted, `onGrounding` fires during the stream and
    //: `addInlineCitations` writes them straight into the answer, and then
    //: the line above rebuilt the whole answer element from the raw markdown
    //: and threw every one of them away. The grounding event arrives *before*
    //: `done`, so this was true of every answer that had any: the feature ran,
    //: correctly, and its output survived for a few milliseconds.
    //:
    //: Re-applied rather than moved, because the live render during streaming
    //: is what makes the answer readable as it arrives; the markers simply
    //: have to be the last thing written.
    if (!hinted && groundedSentences.length) {
      addInlineCitations(answerBox, groundedSentences, groundingRawResults);
    }
    if (!hinted) {
      conversation.push({ question, answer: answerRaw });
      show("retry-btn", "copy-btn", "speak-btn", "new-chat-btn");
    }
    status.textContent = "";
    // Asking changes both quick-access lists, and, for a real (non-hint)
    // answer: the browsable history too.
    loadRecentQuestions();
    loadMostUsed();
    if (!hinted) {
      loadAskHistoryBadge();
      if (askHistoryOpen) loadAskHistoryPage(true);
    }
  } catch (error) {
    if (error.name === "AbortError") {
      stopped = true;
      renderMarkdown(answerBox, answerRaw); // keep what streamed so far
      status.textContent = "Stopped.";
      show("retry-btn", "copy-btn", "speak-btn");
    } else {
      status.textContent = error.message;
      status.classList.add("error");
    }
  } finally {
    // Every exit path, including Stop and an error: a caret still blinking on
    // an answer that stopped arriving is worse than never showing one.
    answerBox.classList.remove("is-streaming", "is-generating");
    askController = null;
    setAsking(false);
    // The question used to be cleared here, which left an answer on screen with
    // nothing saying what it answered (user-reported). It stays in the box, 
    // ready to refine and re-ask, and is echoed above the answer so the pair
    // reads together even after you start typing the next one.
    if (!stopped) questionBox.select();
  }
}

function retryAnswer() {
  if (lastQuestion) askQuestion(lastQuestion);
}

async function copyAnswer() {
  if (await copyToClipboard($("ai-answer").textContent)) toast("Answer copied.");
}

// --- suggested questions (Round 1) ----------------------------------------------

async function loadSuggestions() {
  const box = $("suggested-questions");
  // Only meaningful before the first answer of a conversation.
  if (!$("chat-results").classList.contains("hidden")) return;
  const picks = await apiJson("/chat/suggestions").catch(() => []);
  box.replaceChildren();
  box.classList.toggle("hidden", picks.length === 0);
  if (picks.length === 0) return;
  const label = document.createElement("span");
  label.className = "muted";
  label.textContent = "Try asking:";
  box.appendChild(label);
  for (const question of picks) {
    const chipEl = chip(question, "", () => askQuestion(question));
    box.appendChild(chipEl);
  }
}

// --- Ask history: browse back through every notes-only question, not just
// the last five as reask chips. Requested directly: "I want the ask feature
// to be basically a personal notes browser." Every turn behind this panel
// was already written server-side by chat_stream (routes_ask_history.py);
// this is read, search, pin, delete and "reopen" only. ---------------------

let askHistoryOpen = false;
let askHistoryOffset = 0;
let askHistoryTotal = 0;
const ASK_HISTORY_PAGE = 20;

async function loadAskHistoryBadge() {
  const badge = $("ask-history-badge");
  if (!badge) return;
  const stats = await apiJson("/ask-history/stats").catch(() => null);
  if (!stats || !stats.total) {
    badge.classList.add("hidden");
    return;
  }
  badge.textContent = stats.total > 99 ? "99+" : String(stats.total);
  badge.classList.remove("hidden");
}

function askHistoryRow(turn) {
  const li = document.createElement("li");
  li.className = "ask-history-item";
  li.dataset.id = turn.id;
  li.tabIndex = 0;
  li.setAttribute("role", "button");
  li.title = "Open this question and its answer";

  const head = document.createElement("div");
  head.className = "ask-history-item-head";
  const question = document.createElement("span");
  question.className = "ask-history-question";
  question.textContent = turn.question;
  head.appendChild(question);

  const actions = document.createElement("span");
  actions.className = "ask-history-actions";
  const pinBtn = document.createElement("button");
  pinBtn.type = "button";
  pinBtn.className = "icon-btn ask-history-pin" + (turn.pinned ? " active" : "");
  pinBtn.title = turn.pinned ? "Unpin" : "Pin so this survives Clear";
  pinBtn.setAttribute("aria-label", turn.pinned ? "Unpin question" : "Pin question");
  setLabel(pinBtn, turn.pinned ? "ph:push-pin-slash" : "ph:push-pin");
  pinBtn.addEventListener("click", (e) => {
    e.stopPropagation();
    toggleAskHistoryPin(turn.id, !turn.pinned);
  });
  const delBtn = document.createElement("button");
  delBtn.type = "button";
  delBtn.className = "icon-btn ask-history-delete";
  delBtn.title = "Delete this question";
  delBtn.setAttribute("aria-label", "Delete question");
  delBtn.innerHTML = '<i class="ph ph-trash" aria-hidden="true"></i>';
  delBtn.addEventListener("click", (e) => {
    e.stopPropagation();
    deleteAskHistoryTurn(turn.id);
  });
  actions.append(pinBtn, delBtn);
  head.appendChild(actions);
  li.appendChild(head);

  const meta = document.createElement("div");
  meta.className = "ask-history-meta muted";
  const parts = [relativeTime(turn.created_at)];
  if (turn.result_count) {
    parts.push(`${turn.result_count} note${turn.result_count === 1 ? "" : "s"}`);
  }
  meta.textContent = parts.join(" · ");
  li.appendChild(meta);

  if (turn.answer_preview) {
    const preview = document.createElement("p");
    preview.className = "ask-history-preview";
    preview.textContent = turn.answer_preview;
    li.appendChild(preview);
  }

  const open = () => viewAskHistoryTurn(turn.id);
  li.addEventListener("click", open);
  li.addEventListener("keydown", (e) => {
    if (e.key === "Enter" || e.key === " ") {
      e.preventDefault();
      open();
    }
  });
  return li;
}

async function loadAskHistoryPage(reset) {
  if (reset) askHistoryOffset = 0;
  const list = $("ask-history-list");
  const params = new URLSearchParams({
    limit: String(ASK_HISTORY_PAGE),
    offset: String(askHistoryOffset),
  });
  const q = $("ask-history-search")?.value.trim();
  if (q) params.set("q", q);
  if ($("ask-history-pinned-only")?.checked) params.set("pinned_only", "true");
  const body = await apiJson(`/ask-history?${params}`).catch(() => null);
  if (!body) return;
  askHistoryTotal = body.total;
  if (reset) list.replaceChildren();
  for (const turn of body.turns) list.appendChild(askHistoryRow(turn));
  askHistoryOffset += body.turns.length;
  $("ask-history-empty").classList.toggle("hidden", askHistoryOffset > 0);
  $("ask-history-more").classList.toggle("hidden", askHistoryOffset >= askHistoryTotal);
}

function toggleAskHistoryPanel() {
  askHistoryOpen = !askHistoryOpen;
  $("ask-history-panel").classList.toggle("hidden", !askHistoryOpen);
  $("ask-history-toggle").setAttribute("aria-expanded", String(askHistoryOpen));
  if (askHistoryOpen) loadAskHistoryPage(true);
}

// Reopen a past turn exactly where a live answer renders, no re-asking the
// model, which is the whole point of this being a browser and not a search
// box that happens to remember your last five questions.
async function viewAskHistoryTurn(id) {
  const turn = await apiJson(`/ask-history/${id}`).catch(() => null);
  if (!turn) {
    toast("That question is no longer in your history.", true);
    return;
  }
  $("suggested-questions").classList.add("hidden");
  $("question").value = turn.question;
  lastQuestion = turn.question;
  renderAskedQuestion(turn.question);
  const answerBox = $("ai-answer");
  renderMarkdown(answerBox, turn.answer);
  $("ai-answer-grounding").replaceChildren();
  $("ai-answer-grounding").classList.add("hidden");
  $("thinking-box").classList.add("hidden");
  $("ai-thinking").textContent = "";
  //: A remembered turn says *when* rather than *what by*: the model that
  //: answered it may not even be installed any more. The tooltip carries the
  //: same fact spelled out, since the chip is ellipsised.
  setAnsweredBy(`asked ${relativeTime(turn.created_at)}`, `Asked ${relativeTime(turn.created_at)}`);
  $("search-mode").textContent = SEARCH_MODE_LABELS[turn.search_mode] || turn.search_mode;
  const rawList = $("raw-results");
  rawList.replaceChildren();
  // Same badges as a live Ask answer: this turn's own match_info/connected_ids
  // were saved alongside it (routes_chat.py's _save_ask_turn) for exactly
  // this reason: browsing back shouldn't lose the "why" a result showed up.
  const connected = new Set(turn.connected_ids || []);
  const matchInfo = turn.match_info || {};
  for (const entry of turn.raw_results) {
    const row = clickableResult(entry);
    const badge = matchReasonBadge(matchInfo[entry.id]);
    if (badge) {
      if (connected.has(entry.id)) row.classList.add("result-connected");
      if (matchInfo[entry.id]?.type === "connected_2hop") row.classList.add("result-connected-2hop");
      row.appendChild(badge);
    }
    rawList.appendChild(row);
  }
  if (turn.omitted_results) {
    const li = document.createElement("li");
    li.className = "muted";
    li.textContent =
      turn.omitted_results === 1
        ? "1 note from this answer is no longer available (deleted or made private since)."
        : `${turn.omitted_results} notes from this answer are no longer available (deleted or made private since).`;
    rawList.appendChild(li);
  }
  document.querySelector(".chat-half:last-child")?.classList.remove("hidden");
  $("chat-results").classList.remove("hidden");
  $("ask-idle")?.classList.add("hidden");
  $("ask-status").textContent = "";
  show("retry-btn", "copy-btn", "speak-btn", "new-chat-btn");
}

async function toggleAskHistoryPin(id, pinned) {
  await apiJson(`/ask-history/${id}/pin?pinned=${pinned}`, { method: "PUT" }).catch(() => null);
  loadAskHistoryPage(true);
}

async function deleteAskHistoryTurn(id) {
  // Permanent: no restore endpoint behind this one, unlike a note's bin.
  // "Clear all" right next to this already confirms; a single turn deleted
  // by the same one-click miss deserves the same guard, not less.
  if (!(await confirmDialog("Delete this question and answer?"))) return;
  await apiJson(`/ask-history/${id}`, { method: "DELETE" }).catch(() => null);
  loadAskHistoryPage(true);
  loadAskHistoryBadge();
}

async function clearAskHistory() {
  const ok = await confirmDialog(
    "Clear your question history?\n\nPinned questions are kept. This cannot be undone for the rest.",
    { confirmLabel: "Clear history", danger: true }
  );
  if (!ok) return;
  await apiJson("/ask-history", { method: "DELETE" }).catch(() => null);
  loadAskHistoryPage(true);
  loadAskHistoryBadge();
}

// --- chat tab (Wave C) ------------------------------------------------------------

let chatConv = { id: null, turns: [] }; // the open conversation
let chatController = null;
let lastChatQuestion = ""; // powers Regenerate / Edit & resend
// Set while an `ask` card (renderAgentQuestion) is on screen waiting for a
// reply. Covers typing a free-text answer into the composer, not just
// clicking one of the option buttons, both are "answering the agent's
// question" and both need answering_agent set (Tier 1 §4), or a typed "yes"
// reads as small talk and strands the thing it was actually answering.
// Consumed (read once, then reset) by the very next sendChatMessage call.
let chatAwaitingAgentAnswer = false;

// A summary standing in for the first `covered` turns when this conversation
// is sent to the model (§35I). Deliberately *beside* the turns rather than
// replacing them: the transcript on screen and the saved conversation are
// untouched, so this narrows what the model reads and loses nothing. Undo is
// therefore setting this back to null.
let chatSummary = null; // { text, covered }

// What the model is given as history: the summary in place of the turns it
// covers, then everything since, capped as before.
//
// Without a summary the tail is all the model gets, `context.fit_history`
// drops whole pairs from the oldest end to fit, so a long conversation does
// not overflow, it silently forgets its own beginning. A few hundred
// characters carrying the gist of ten turns is strictly better than the whole
// of one.
function chatHistoryToSend() {
  const turns = chatConv.turns;
  if (!chatSummary || chatSummary.covered <= 0) {
    return turns.slice(-MAX_CLIENT_HISTORY);
  }
  const since = turns.slice(chatSummary.covered).slice(-MAX_CLIENT_HISTORY);
  return [
    {
      question: "What have we covered so far?",
      answer: `Summary of the first ${chatSummary.covered} messages:\n${chatSummary.text}`,
    },
    ...since,
  ];
}

// The persona name to label assistant bubbles with (falls back to "Assistant").
function assistantLabel() {
  const select = $("persona-select");
  return (select && select.value) || "Assistant";
}

// A hover-reveal row of small actions under a chat bubble. Each action is
// { label, title, onClick }. onClick gets the click event so buttons can
// give inline feedback (e.g. a copy tick).
//: How many actions a message row shows before the rest fold into a ⋯. Five is
//: what fits beside the shortest message this app produces without the row
//: being wider than the bubble it belongs to.
const MSG_ACTIONS_VISIBLE = 5;

function chatMessageActions(actions) {
  const row = document.createElement("div");
  row.className = "msg-actions";
  const make = (action) => {
    const button = document.createElement("button");
    button.type = "button";
    button.className = "msg-action";
    setLabel(button, action.label);
    button.title = action.title;
    button.setAttribute("aria-label", action.title);
    button.addEventListener("click", action.onClick);
    return button;
  };
  //: **The row grew past what a row can hold.** An assistant message now
  //: offers ten things (copy, regenerate from here, rewrite shorter, explain
  //: simpler, fork from here, read aloud, save as note, remind me, edit,
  //: delete): the Odysseus footer's set plus this app's own capture actions.
  //: Ten buttons over a two-line answer is not a control row, it is a toolbar
  //: that happens to be under a message, so the rest go behind the same ⋯ the
  //: app uses everywhere else for "more actions on this object".
  for (const action of actions.slice(0, MSG_ACTIONS_VISIBLE)) row.appendChild(make(action));
  const overflow = actions.slice(MSG_ACTIONS_VISIBLE);
  if (overflow.length) {
    row.appendChild(
      kebabMenu(
        overflow.map((action) => ({
          label: `${action.label} ${action.title}`,
          title: action.title,
          danger: action.danger,
          run: () => action.onClick({ currentTarget: null }),
        })),
        "More actions for this message"
      )
    );
  }
  return row;
}

//: **One action list for an assistant message, wherever it was built.**
//:
//: There were two: the live stream's and the reopened-conversation path's, and
//: they had already drifted, the replayed one had Edit and no Read aloud, the
//: live one the reverse, and a bug fixed in one stayed in the other. This is
//: the same "two implementations of one control" lesson the Library kebab
//: taught, applied before it costs another round.
//:
//: The order is Odysseus's footer order, with this app's own capture actions
//: after it: what you do to the *answer* first, what you do with it second.
//: **Copy copies the whole turn, not the last paragraph of it.** The owner:
//: "when I copy text from a chat or assistant message bubble, it only shows
//: the last agent section of the message, I want it to capture everything
//: in the whole chat and assistant messages, including thinking processes
//: (if toggled), tool calls, and everything in the chat." The bubble is
//: walked in document order: a thinking step is included only while it is
//: open (the toggle is the person's say on whether it is part of the
//: message), a plan step as its text, each tool chip as one "Tool:" line
//: with its arguments and result when they are shown, and every answer body
//: as its text. `text` is the raw Markdown of the final answer, used in
//: place of the last body's rendered text so headings and links survive.
function chatTurnTranscript(bubble, text) {
  const parts = [];
  const seen = new Set();
  const nodes = bubble
    ? [...bubble.querySelectorAll(".agent-step, .tool-chip, .msg-body")]
    : [];
  const bodies = nodes.filter((n) => n.classList.contains("msg-body"));
  for (const node of nodes) {
    if ([...seen].some((s) => s.contains(node))) continue;
    seen.add(node);
    if (node.classList.contains("step-thinking")) {
      if (!node.open) continue;
      const body = node.querySelector(".thinking")?.innerText.trim();
      if (body) parts.push(`Thinking:\n${body}`);
    } else if (node.classList.contains("step-plan")) {
      const body = node.innerText.replace(/^\s*Plan\s*/i, "").trim();
      if (body) parts.push(`Plan:\n${body}`);
    } else if (node.classList.contains("tool-chip")) {
      const label = node.querySelector("summary")?.innerText.trim() || node.innerText.trim();
      const args = node.querySelector(".tool-chip-args")?.textContent.trim();
      const result = node.querySelector(".tool-chip-result")?.textContent.trim();
      let line = `Tool: ${label}`;
      if (args) line += `\n${args}`;
      if (result) line += `\nResult: ${result}`;
      parts.push(line);
    } else if (node.classList.contains("msg-body")) {
      const last = node === bodies[bodies.length - 1];
      const body = last && text ? text : node.innerText.trim();
      if (body) parts.push(body);
    } else {
      const body = node.innerText.trim();
      if (body) parts.push(body);
    }
  }
  return parts.length ? parts.join("\n\n") : text || "";
}

function assistantMessageActions({ bubble, text, question, onEdit }) {
  return chatMessageActions([
    {
      label: "ph:copy",
      title: "Copy message",
      onClick: (e) => copyToClipboard(chatTurnTranscript(bubble, text), e.currentTarget),
    },
    {
      label: "ph:arrow-clockwise",
      title: "Regenerate from here",
      onClick: () => regenerateFromBubble(bubble),
    },
    {
      label: "ph:scissors",
      title: "Rewrite this shorter",
      onClick: () =>
        rewriteAnswerWith(
          "Rewrite your last answer to be shorter, keep every fact, cut the padding."
        ),
    },
    {
      label: "ph:student",
      title: "Explain it more simply",
      onClick: () =>
        rewriteAnswerWith(
          "Explain your last answer again in plain language, short sentences, no jargon."
        ),
    },
    {
      label: "ph:git-branch",
      title: "Fork the conversation from here",
      onClick: () => forkFromBubble(bubble),
    },
    { label: "ph:speaker-high", title: "Read aloud", onClick: () => speakText(text) },
    {
      label: "ph:note-pencil",
      title: "Save this answer as a draft note",
      onClick: () => saveChatAnswerAsNote(question, text),
    },
    { label: "ph:alarm", title: "Set a reminder from this answer", onClick: () => reminderFromChatAnswer(text) },
    ...(onEdit ? [{ label: "ph:pencil-simple", title: "Edit this answer", onClick: onEdit }] : []),
    {
      label: "ph:trash",
      title: "Delete this message",
      danger: true,
      onClick: () => deleteChatTurn(bubble),
    },
  ]);
}

// One-click capture from a chat answer. The text-selection popup's "Save as
// draft note" already reaches chat bubbles, but only for whatever's
// highlighted: this needs no selection at all, so the whole answer is one
// press away instead of a select-then-click.
async function saveChatAnswerAsNote(question, answer) {
  try {
    const content = question ? `${question}\n\n${answer}` : answer;
    await apiJson("/entries", {
      method: "POST",
      body: JSON.stringify({ content, tags: ["chat"], is_draft: true }),
    });
    toast("Saved as a draft note.");
    // Unconditional, not gated on the Notes tab being the one currently
    // open. Reported: a note saved from Chat "didn't show up in the
    // drafts" - it *was* saved, but `entries` (the in-memory list Notes
    // renders from) was never refetched, since switchTab("notes") doesn't
    // reload it either. The stale list only caught up whenever something
    // else happened to call loadEntries() next. refreshAfterToolChanges()
    // already calls this with no such guard, for the same reason.
    loadEntries();
  } catch (error) {
    toast(error.message || "Couldn't save that note.", true);
  }
}

// Same one-click idea for reminders. No AI parse and no due-date prompt, 
// either would need a round trip or a decision before anything is saved,
// which is exactly what "one click" was asked to avoid, so this picks a
// plain default (tomorrow, 9am) and creates the reminder right away; the
// toast's "Edit" action jumps straight to it in the Reminders tab for
// anyone who wants a different time.
async function reminderFromChatAnswer(answer) {
  const text = answer.length > 100 ? answer.slice(0, 97).trim() + "…" : answer;
  const due = new Date();
  due.setDate(due.getDate() + 1);
  due.setHours(9, 0, 0, 0);
  try {
    const reminder = await apiJson("/reminders", {
      method: "POST",
      body: JSON.stringify({
        text: `Follow up: ${text}`,
        due_at: due.toISOString(),
        priority: "normal",
        recurring: "none",
      }),
    });
    askNotificationPermission();
    loadReminders();
    toastAction("Reminder set for tomorrow, 9am.", "Edit", () => {
      editingReminderId = reminder.id;
      return flashReminder(reminder.id);
    });
  } catch (error) {
    toast(error.message || "Couldn't set a reminder.", true);
  }
}

// The offer to carry on, shown under a turn that stopped before it was done.
//
// Reported twice in the same breath: *"the agent struggles with long tasks
// like skills then cuts out half way through and has to restart, or it hits a
// limit for tool calls."* Both ended in a paragraph telling the user to ask it
// to continue: so continuing meant typing the request out again from memory,
// and resuming a six-step skill meant re-running the three steps that had
// already changed the notebook. This is one button for each case.
function continueRunControls({ label, hint, onClick }) {
  const row = document.createElement("div");
  row.className = "run-continue";
  const button = document.createElement("button");
  button.type = "button";
  button.className = "small";
  // continueRunControls is called with "ph:arrow-clockwise Resume from step N".
  setLabel(button, label);
  button.addEventListener("click", () => {
    // One press only: a second would start a duplicate run over the same
    // notes, and every step of it writes.
    button.disabled = true;
    onClick();
  });
  row.appendChild(button);
  if (hint) {
    const why = document.createElement("span");
    why.className = "muted";
    why.textContent = hint;
    row.appendChild(why);
  }
  return row;
}

// Manual (step-through) mode's pause card: a text box to add what the agent
// missed or answer a question it raised, and a Continue button, the answer
// to "a manual mode" asked for directly, and the single most-requested
// unbuilt thing on the roadmap. `onContinue(note)` gets whatever was typed,
// or an empty string if nothing was.
function manualPauseControls({ onContinue }) {
  const row = document.createElement("div");
  row.className = "run-continue run-continue-manual";
  const note = document.createElement("input");
  note.type = "text";
  note.placeholder = "Add anything before the next step (optional)…";
  note.maxLength = 500;
  const button = document.createElement("button");
  button.type = "button";
  button.className = "small";
  setLabel(button, "ph:play Continue");
  button.addEventListener("click", () => {
    button.disabled = true;
    note.disabled = true;
    onContinue(note.value.trim());
  });
  note.addEventListener("keydown", (e) => {
    if (e.key === "Enter") button.click();
  });
  const why = document.createElement("span");
  why.className = "muted";
  why.textContent = "Paused: step by step mode.";
  row.append(why, note, button);
  return row;
}

// A small "what this answer cost" line under an assistant bubble: which model
// answered, how long it took, and, when Ollama reports them, token counts
// and generation speed.
// One fact on the metadata line. Its own element rather than a slice of one
// long string, which is what "modular" buys: each item carries its own
// tooltip, can be styled by what it *is* rather than by where it sits, and a
// new field added later cannot silently change the meaning of the separator
// beside it.
function metaItem(text, { title = "", kind = "", icon = "" } = {}) {
  const item = document.createElement("span");
  item.className = `msg-meta-item${kind ? ` msg-meta-${kind}` : ""}`;
  if (icon) {
    const mark = document.createElement("span");
    mark.className = "msg-meta-icon";
    // setLabel, not textContent. This was the last function in the app still
    // assigning an icon string straight to textContent, so the one caller that
    // passes a marker rendered the literal text "ph:wrench 1" in the metadata
    // line under every answer that used a tool. Exactly the miss the setLabel
    // comment warns about: the icon is a string literal at the call site, not
    // markup in index.html, so no template search finds it.
    setLabel(mark, icon);
    mark.setAttribute("aria-hidden", "true");
    item.appendChild(mark);
  }
  item.appendChild(document.createTextNode(text));
  if (title) item.title = title;
  return item;
}

// §35K: *"the chat bubble's metadata line is not visually appealing. It has
// grown a field at a time, model, elapsed, tokens, rounds, context percent,
// whether the count was estimated, and never had a pass."*
//
// The pass, and the rule behind it: **a metadata line is read at a glance or
// not at all.** Six equal facts joined by dots is a sentence you have to
// parse, so the fields are ranked instead, what the turn *cost you* (time,
// and how full the window got) reads first, what it *was* (model, tools) sits
// quieter beside it, and the numbers only a debugging session wants (exact
// tokens, tokens/second) are one hover away rather than on screen.
//
// Nothing was removed: every field is still here, and the ones that moved into
// tooltips moved because they answer a question nobody asks mid-conversation.
function messageMetaLine({ model, elapsedMs, stats, toolCount = 0, rounds = 0, usedTools = null }) {
  const row = document.createElement("div");
  row.className = "msg-meta muted";

  // 1. What it cost. First, because it is the only field anyone looks for
  //    while actually using the app.
  if (elapsedMs != null) {
    row.appendChild(
      metaItem(
        elapsedMs < 1000 ? `${elapsedMs} ms` : `${(elapsedMs / 1000).toFixed(1)}s`,
        { title: "How long this answer took, end to end", kind: "time" }
      )
    );
  }

  // 2. How full the model's window got: a meter, not a percentage in prose.
  //    A raw token count never answered the question anyone has, which is
  //    whether the *next* turn is the one that starts dropping the top of its
  //    own prompt.
  let fill = null;
  const inTok = stats ? stats.prompt_tokens : null;
  const outTok = stats ? stats.output_tokens : null;
  if (stats && inTok != null && stats.context_tokens) {
    fill = Math.min(100, Math.round((inTok / stats.context_tokens) * 100));
    const approx = stats.usage_source === "estimated" ? "~" : "";
    // §88.4 item 4 / BACKLOG's "per-chat token meter": where this turn's
    // prompt actually went, not just how full the window got. Estimated
    // (chars/4, same as the backend's own approximation), and only on the
    // turns that have it, older saved turns, from before this shipped,
    // simply don't add the section rather than showing zeroes.
    const c = stats.composition;
    const compositionLines = c
      ? "\n\n" +
        `System prompt: ~${compactTokens(c.system)} tok\n` +
        `Tool schemas: ~${compactTokens(c.tool_schemas)} tok\n` +
        `History: ~${compactTokens(c.history)} tok\n` +
        `Notes + question: ~${compactTokens(c.notes)} tok`
      : "";
    const meter = metaItem(`${fill}%`, {
      title:
        `${approx}${compactTokens(inTok)} of this model's ${compactTokens(stats.context_tokens)} ` +
        "context window was used by this turn." +
        (fill >= 80
          ? "\n\nPast about 80%, the next turn is the one that starts dropping " +
            "the oldest part of its own prompt, Compress in the header " +
            "summarises the conversation so far instead."
          : "") +
        compositionLines,
      kind: "window",
    });
    //: **Where the prompt went, drawn rather than described.** Asked for: "in
    //: chat I want more details in features, including model attributes, token
    //: expense distribution, more features". The distribution has been
    //: computed on the server since §88.4 and sent on every `stats` event: 
    //: and the only place it appeared was inside a tooltip, which is a number
    //: nobody finds. A single bar answers "how full" and says nothing about
    //: *what filled it*, which is the question you have when the answers start
    //: getting worse.
    //:
    //: One segment per part of the prompt, each one hoverable and each one
    //: named. The remainder is the room the next turn has left, drawn as
    //: nothing at all: a fifth coloured band would read as a fifth cost.
    const bar = document.createElement("span");
    bar.className = "msg-meta-bar";
    const parts = c
      ? [
          ["system", c.system, "The instructions the model is given every turn"],
          ["tools", c.tool_schemas, "The descriptions of the tools it can call"],
          ["history", c.history, "Earlier messages in this conversation"],
          ["notes", c.notes, "Your notes and the question itself"],
        ]
      : [["all", inTok, "This turn's whole prompt"]];
    for (const [kind, tokens, why] of parts) {
      const amount = Number(tokens) || 0;
      if (amount <= 0) continue;
      const segment = document.createElement("span");
      segment.className = `msg-meta-bar-level msg-meta-bar-${kind}`;
      //: Measured against the *window*, not against the prompt: the point of
      //: the bar is how much of the model's memory this turn is spending, and
      //: normalising to the prompt would draw a full bar on every turn.
      segment.style.width = `${Math.min(100, (amount / stats.context_tokens) * 100)}%`;
      segment.title = `${why}: about ${compactTokens(amount)} tokens`;
      bar.appendChild(segment);
    }
    meter.insertBefore(bar, meter.firstChild);
    row.appendChild(meter);
  }

  // 3. What answered, and what it did. Quieter: this is the same for every
  //    turn in a conversation, so it is context rather than news.
  // §89.4: a conversation can span mode switches, so each past turn needs to
  // say which mode actually answered it, not what the live toggle shows now.
  // Same icons/labels as the segmented control (#chat-mode-seg) so this reads
  // as the same idea rather than a second vocabulary for it.
  if (usedTools != null) {
    row.appendChild(
      metaItem(usedTools ? "Agent" : "Ask", {
        icon: usedTools ? "ph:robot" : "ph:chat-circle",
        title: usedTools
          ? "Answered in Agent mode, the Librarian could use tools."
          : "Answered in Ask mode, read-only, no tools used.",
        kind: "mode",
      })
    );
  }
  if (model) {
    row.appendChild(
      metaItem(model, { title: "The model that answered", kind: "model" })
    );
  }
  if (toolCount) {
    row.appendChild(
      metaItem(String(toolCount), {
        icon: "ph:wrench",
        title:
          `${toolCount} tool call${toolCount === 1 ? "" : "s"}` +
          (rounds > 1 ? ` over ${rounds} rounds` : "") +
          ". The steps above show which.",
        kind: "tools",
      })
    );
  }

  // 4. The numbers a debugging session wants, and nobody else. On the row's
  //    own tooltip rather than in it, this is where the line had grown to
  //    three lines of digits on a narrow window.
  const detail = [];
  if (inTok != null || outTok != null) {
    const approx = stats && stats.usage_source === "estimated" ? "~" : "";
    detail.push(`${approx}${inTok ?? "?"} tokens in → ${outTok ?? "?"} out`);
  }
  if (outTok && stats && stats.eval_ms) {
    detail.push(`${(outTok / (stats.eval_ms / 1000)).toFixed(1)} tokens/second`);
  }
  if (rounds > 1) detail.push(`${rounds} rounds`);
  if (stats && stats.usage_source === "estimated") {
    detail.push("~ means the server didn't report counts, so these are estimated");
  }
  if (detail.length) row.title = detail.join("\n");

  // Past ~80% the next turn of the same conversation is the one that starts
  // dropping things, so the warning belongs on the turn *before* it happens
  // rather than after the model has already lost the plot.
  if (fill != null && fill >= 80) row.classList.add("msg-meta-tight");
  return row;
}

// "8192" is a number you have to read; "8k" is one you can glance at. Under a
// thousand stays exact, because rounding 900 to "1k" would be a lie in the
// direction that matters when the window is nearly full.
function compactTokens(n) {
  if (n == null) return "?";
  return n >= 1000 ? `${(n / 1000).toFixed(n >= 10000 ? 0 : 1)}k` : String(n);
}

// Remove a message from the live transcript. A saved conversation stores
// question/answer pairs, so deleting either half drops the whole exchange, 
// otherwise the missing half would reappear on reopening the chat.
// Deleting from a user bubble drops the same exchange as deleting from the
// answer below it, so both buttons route through one implementation.
function removeChatBubble(bubble) {
  const assistant = bubble.classList.contains("user")
    ? bubble.nextElementSibling
    : bubble;
  if (!assistant?.classList.contains("assistant")) return;
  return deleteChatTurn(assistant);
}

// Copying has to actually work, in three descending steps.
//
// `navigator.clipboard` is only defined in a SECURE CONTEXT. On
// http://localhost that is satisfied, which is why this looked fine, but the
// moment the app is reached at http://192.168.1.20:8000, over a tunnel, or
// through anything that is not localhost, the whole API is simply `undefined`
// and every copy button in the app becomes a no-op that says "couldn't copy".
// That is worst on the Logs screen, where the thing being copied is the error
// you are trying to report to somebody.
//
// So: the modern API, then the old `execCommand` path that works on plain
// http, and finally, if even that is refused, hand the text to the user in a
// selected textarea so Ctrl+C still gets it out. The last step is the one that
// makes "you can always copy this" a true statement rather than a hope.
function copyViaTextarea(text) {
  const staging = document.createElement("textarea");
  staging.value = text;
  // Off-screen rather than hidden: a display:none element cannot be selected,
  // and the selection is the whole mechanism here.
  staging.setAttribute("readonly", "");
  staging.style.position = "fixed";
  staging.style.top = "-1000px";
  staging.style.opacity = "0";
  document.body.appendChild(staging);
  staging.select();
  staging.setSelectionRange(0, text.length);
  let copied = false;
  try {
    copied = document.execCommand("copy");
  } catch {
    copied = false;
  }
  staging.remove();
  return copied;
}

function flashCopied(button) {
  if (!button) return;
  // innerHTML, not textContent: an icon-only button (setLabel(el, "ph:...")
  // with no trailing text) renders as a bare <i> with empty textContent, so
  // saving/restoring textContent silently wiped the icon back to blank once
  // the checkmark's timeout fired instead of putting it back.
  const original = button.innerHTML;
  button.textContent = "✓";
  setTimeout(() => (button.innerHTML = original), 1200);
}

async function copyToClipboard(text, button) {
  if (!text) return false;
  try {
    if (navigator.clipboard && window.isSecureContext) {
      await navigator.clipboard.writeText(text);
      flashCopied(button);
      return true;
    }
  } catch {
    // Permission refused or the context is not what it claimed, fall through
    // rather than reporting failure while a working path is still untried.
  }
  if (copyViaTextarea(text)) {
    flashCopied(button);
    return true;
  }
  showCopyFallback(text);
  return false;
}

// The last resort: show the text, already selected, and say what to press.
// Reached when the browser refuses both copy mechanisms, usually a hardened
// or embedded webview. The text is still on screen and still selectable, so
// the answer to "how do I get this error out" is never "you can't".
function showCopyFallback(text) {
  const existing = $("copy-fallback");
  if (existing) existing.remove();

  const overlay = document.createElement("div");
  overlay.id = "copy-fallback";
  overlay.className = "modal-overlay";
  overlay.setAttribute("role", "dialog");
  overlay.setAttribute("aria-label", "Copy this text");

  const card = document.createElement("div");
  card.className = "modal-card copy-fallback-card";

  const heading = document.createElement("h3");
  heading.textContent = "Copy this";

  const note = document.createElement("p");
  note.className = "muted";
  note.textContent =
    "This browser wouldn't let the app write to the clipboard, it's already " +
    "selected below, so press Ctrl+C (⌘C on a Mac).";

  const box = document.createElement("textarea");
  box.className = "copy-fallback-text";
  box.value = text;
  box.setAttribute("readonly", "");
  box.rows = 12;

  const close = document.createElement("button");
  close.className = "small";
  close.textContent = "Done";
  const dismiss = () => overlay.remove();
  close.addEventListener("click", dismiss);
  wireBackdropClose(overlay, () => dismiss());
  overlay.addEventListener("keydown", (event) => {
    if (event.key === "Escape") dismiss();
  });

  card.append(heading, note, box, close);
  overlay.appendChild(card);
  document.body.appendChild(overlay);
  box.focus();
  box.select();
}

// Put a question back in the input so it can be tweaked and re-sent.
// Edit a question in place, the way you'd expect a chat to work.
//
// The old version just copied the text into the input box: the original
// question and its answer stayed put, and re-sending appended a second
// exchange below them. So a small correction left the thread showing the typo,
// the answer to the typo, and then the fix, which is the opposite of editing.
//
// Now the bubble itself becomes a textarea. Saving rewrites that question,
// drops every exchange after it (they were answers to the old wording), and
// asks again from that point.
function editAndResend(bubble, text) {
  if (chatController) return; // not mid-stream
  if (bubble.querySelector(".msg-edit")) return; // already editing
  const body = bubble.querySelector(".msg-body");
  const actions = bubble.querySelector(".msg-actions");
  const original = text;

  const editor = document.createElement("div");
  editor.className = "msg-edit";
  const box = document.createElement("textarea");
  box.value = original;
  box.rows = Math.min(8, Math.max(2, original.split("\n").length + 1));
  box.setAttribute("aria-label", "Edit your question");

  const hint = document.createElement("p");
  hint.className = "muted msg-edit-hint";
  hint.textContent =
    "Saving replaces this question and clears the replies that came after it.";

  const row = document.createElement("div");
  row.className = "row msg-edit-actions";
  const save = document.createElement("button");
  save.className = "small";
  save.textContent = "Save & resend";
  const cancel = document.createElement("button");
  cancel.className = "ghost small";
  cancel.textContent = "Cancel";
  row.append(save, cancel);
  editor.append(box, hint, row);

  const close = () => {
    editor.remove();
    body.classList.remove("hidden");
    actions?.classList.remove("hidden");
  };
  cancel.addEventListener("click", close);
  box.addEventListener("keydown", (event) => {
    if (event.key === "Escape") {
      event.preventDefault();
      close();
    } else if ((event.ctrlKey || event.metaKey) && event.key === "Enter") {
      event.preventDefault();
      save.click();
    }
  });
  save.addEventListener("click", async () => {
    const edited = box.value.trim();
    if (!edited) return;
    if (edited === original) return close();

    const bubbles = [...$("chat-messages").querySelectorAll(".msg")];
    const turnIndex = Math.floor(bubbles.indexOf(bubble) / 2);

    // Server first: if this fails, nothing on screen has been thrown away yet.
    if (chatConv.id !== null) {
      try {
        const result = await apiJson(`/conversations/${chatConv.id}/truncate`, {
          method: "POST",
          body: JSON.stringify({ from_turn: turnIndex }),
        });
        if (result.conversation_deleted) chatConv.id = null;
      } catch (error) {
        toast(`Couldn't edit that: ${error.message}`, true);
        return;
      }
    }
    // Drop this bubble and everything after it, then ask again.
    for (const later of bubbles.slice(bubbles.indexOf(bubble))) later.remove();
    chatConv.turns = chatConv.turns.slice(0, turnIndex);
    close();
    loadConversationList();
    sendChatMessage(edited);
  });

  body.classList.add("hidden");
  actions?.classList.add("hidden");
  bubble.appendChild(editor);
  box.focus();
  box.setSelectionRange(box.value.length, box.value.length);
}

// Re-run the most recent question and REPLACE the previous answer in place
// (user request: a redo shouldn't stack a second answer below the old one).
// The original "you" bubble stays; only the assistant bubble is swapped.
//: **The question a bubble is the answer to.** Walks back through the
//: transcript rather than trusting an index: bubbles are deleted, edited and
//: re-ordered, and any stored position goes stale the first time somebody uses
//: the ⋯ on a message in the middle.
function questionForBubble(bubble) {
  let node = bubble;
  while (node) {
    node = node.previousElementSibling;
    if (node && node.classList.contains("msg") && node.classList.contains("user")) {
      return { bubble: node, text: (node.querySelector(".msg-body")?.textContent || "").trim() };
    }
  }
  return null;
}

//: **Regenerate from *this* answer, not just the last one.**
//:
//: Odysseus's message footer has had this since it shipped, and it is the one
//: that matters on a long thread: the answer you want re-done is rarely the
//: newest. Everything after the question is removed first, an answer
//: regenerated in the middle of a thread that keeps the turns built on the old
//: one is a transcript that contradicts itself.
function regenerateFromBubble(bubble) {
  if (chatController) return toast("Wait for the current answer to finish.");
  const asked = questionForBubble(bubble);
  if (!asked) return toast("There is no question above this answer to re-ask.");
  const host = $("chat-messages");
  const kept = [...host.children];
  const from = kept.indexOf(asked.bubble);
  //: The question stays; everything after it goes, including this answer.
  for (const node of kept.slice(from + 1)) node.remove();
  sendChatMessage(asked.text, { skipUserBubble: true, replaceLast: true });
}

//: **Rewrite the last answer under a standing instruction**, Odysseus's
//: "shorter" and "simpler" footer actions.
//:
//: Sent as a *visible* user turn rather than a hidden system nudge, which is
//: the one design choice worth stating: this app's whole premise is that you
//: can read what the model was asked. A hidden instruction that changes an
//: answer is exactly the thing a local-first notebook should not do.
function rewriteAnswerWith(instruction) {
  if (chatController) return toast("Wait for the current answer to finish.");
  sendChatMessage(instruction);
}

//: **Fork from this point in the conversation.** The server already copies a
//: conversation up to a turn (`POST /conversations/{id}/fork`, `up_to`), this
//: is the door to it from the message you are actually looking at, which is
//: where "try a different direction from here" is decided.
async function forkFromBubble(bubble) {
  if (!chatConv || chatConv.id === null) {
    return toast("Nothing to fork yet, ask something first.");
  }
  //: Which turn this is: count the assistant bubbles before it. `up_to` is a
  //: turn index on the server, and a turn is one question and its answer.
  const bubbles = [...$("chat-messages").querySelectorAll(".msg.assistant")];
  const index = bubbles.indexOf(bubble);
  if (index === -1) return;
  try {
    const fork = await apiJson(`/conversations/${chatConv.id}/fork`, {
      method: "POST",
      body: JSON.stringify({ up_to: index + 1 }),
    });
    await loadConversationList();
    toastAction(`Forked at this message → “${fork.title}”.`, "Open it", () =>
      openConversation(fork.id)
    );
  } catch (error) {
    toast(error.message || "Couldn't fork from here.", true);
  }
}

function regenerateLastAnswer() {
  if (!lastChatQuestion || chatController) return;
  const assistantBubbles = $("chat-messages").querySelectorAll(".msg.assistant");
  const lastAssistant = assistantBubbles[assistantBubbles.length - 1];
  if (lastAssistant) lastAssistant.remove(); // clear the old answer first
  sendChatMessage(lastChatQuestion, {
    skipUserBubble: true,
    replaceLast: true,
    noteIds: lastChatAttachments,
    imageMediaIds: lastChatImageAttachments.map((img) => img.id),
    documentIds: lastChatDocumentAttachments.map((d) => d.id),
  });
}

// The welcome shown in an empty chat so the page isn't a blank box.
function renderChatEmptyState() {
  const box = $("chat-messages");
  if (box.querySelector(".msg") || box.querySelector(".chat-empty")) return;
  const empty = document.createElement("div");
  empty.className = "chat-empty";
  const emblem = document.createElement("div");
  emblem.id = "chat-empty-emblem";
  emblem.className = "emblem emblem-centred";
  emblem.setAttribute("aria-hidden", "true");
  const title = document.createElement("p");
  title.className = "empty-title";
  // Personas already voice the AI's replies and the dashboard greeting
  // (librarian.resolve_persona_prompt's own docstring: "the voice the user
  // picked is used consistently everywhere"), this was the one place left
  // that stayed generic regardless of which persona was active, so opening
  // a new chat under "Coach" or a custom persona still greeted you as
  // nobody in particular (ROADMAP Tier 3 §21).
  const activePersona = (prefsCache && prefsCache.active_persona) || "Librarian";
  title.textContent =
    activePersona === "Librarian" ? "Chat with your notebook" : `Chat with your ${activePersona}`;
  const blurb = document.createElement("p");
  blurb.className = "muted";
  blurb.textContent =
    "Ask a question and the AI answers from your saved notes. Turn on “AI can " +
    "make changes” and it can create, tag, link, and organise notes for you too.";
  empty.append(emblem, title, blurb);
  //: **The starters belong in the empty state, not in a strip above the
  //: composer.** Measured at 1440px: the welcome was a 326px column of centred
  //: text in a 1062px pane with four suggestion chips jammed against the
  //: composer 550px below it, two halves of one invitation, as far apart as
  //: the layout allowed. `#chat-suggest` still exists and is still filled by
  //: `loadChatSuggestions`; it is *moved here* while the pane is empty and
  //: goes back to the dock the moment a message arrives, so nothing else has
  //: to know where it lives.
  const suggest = $("chat-suggest");
  if (suggest && !suggest.classList.contains("hidden")) {
    empty.appendChild(suggest);
  }
  box.appendChild(empty);
  // Animated like the ai-mark: a new chat is the AI waiting, and the slow
  // turn says so. Stills itself under Settings → Appearance → reduced motion.
  renderEmblem(emblem, 52, { animate: true }); // after insertion: see addAssistantBubble
}

function clearChatEmptyState() {
  const empty = $("chat-messages").querySelector(".chat-empty");
  if (!empty) return;
  //: The chips are on loan from the dock (see `chatEmptyState`), so they go
  //: home before the welcome is thrown away, removing them with it would
  //: lose the element every other caller still holds by id.
  const suggest = empty.querySelector("#chat-suggest");
  if (suggest) {
    suggest.classList.add("hidden");
    document.querySelector(".chat-dock")?.prepend(suggest);
  }
  empty.remove();
}

// --- web panel: search + reader view ----------------------------------------
// Deliberately not an embedded browser. Pages are fetched and stripped to
// text by the backend, so nothing from a third-party site ever executes here.

let webReaderPage = null; // the page currently open in the reader

function toggleWebPanel(force) {
  const panel = $("web-panel");
  const show = force ?? panel.classList.contains("hidden");
  panel.classList.toggle("hidden", !show);
  if (show) {
    $("web-reader").classList.add("hidden");
    // Say up front when searching cannot work, rather than after a search has
    // failed. Web access is off by default, this is a local-first app and
    // that is the right default, so the commonest first experience of this
    // panel is typing a query into a box that was never going to answer. The
    // switch is one click away, and naming where it lives is the difference
    // between a dead end and a setting.
    const status = $("web-status");
    if (prefsCache && !prefsCache.web_search_enabled) {
      status.replaceChildren();
      status.classList.remove("error");
      status.appendChild(
        document.createTextNode("Web access is off. Turn it on in ")
      );
      const link = document.createElement("button");
      link.type = "button";
      link.className = "link-button";
      link.textContent = "Settings → Web search";
      link.addEventListener("click", () => {
        toggleWebPanel(false);
        openSettingsModal("websearch");
      });
      status.appendChild(link);
      status.appendChild(document.createTextNode(" to search from here."));
    } else if (!$("web-results").childElementCount) {
      status.textContent = "";
    }
    refreshWebSearxngStrip();
    renderWebSearchHistory();
    $("web-query").focus();
  } else {
    clearTimeout(webSearxngTimer);
  }
}

// Feedforward for whether the private, local SearXNG instance is actually
// running: not just the after-the-fact "answered by SearXNG" a result
// already carries (renderAnswerGrounding-adjacent code, search below).
// Asked for directly: a way to see and toggle it without leaving the Chat
// tab for Settings → Web search, three clicks and a tab-switch away.
// Deliberately far lighter than that page's full management UI (install
// progress, port diagnostics, reinstall), this is only "is it on, turn it
// on/off", the two things worth knowing before typing a query.
let webSearxngTimer = null;

async function refreshWebSearxngStrip() {
  const strip = $("web-searxng-strip");
  const provider = (prefsCache && prefsCache.search_provider) || "auto";
  if (provider === "duckduckgo") {
    // This provider never touches SearXNG, a toggle here would control
    // nothing a search actually uses.
    strip.classList.add("hidden");
    clearTimeout(webSearxngTimer);
    return;
  }
  const info = await apiJson("/websearch/searxng/status").catch(() => null);
  if (!info || !info.backend) {
    // No usable backend (Docker or a virtualenv) to run it at all, Settings
    // → Web search explains why; there's nothing this strip can offer.
    strip.classList.add("hidden");
    clearTimeout(webSearxngTimer);
    return;
  }
  strip.classList.remove("hidden");
  const chip = $("web-searxng-chip");
  const toggle = $("web-searxng-toggle");

  if (info.installing) {
    chip.textContent = "SearXNG: installing…";
    chip.className = "chip";
    toggle.disabled = true;
    setLabel(toggle, "ph:play Start");
    clearTimeout(webSearxngTimer);
    webSearxngTimer = setTimeout(refreshWebSearxngStrip, 2000);
    return;
  }

  const running = info.state === "running" && info.responding;
  chip.textContent = running
    ? "SearXNG: running"
    : info.state === "stopped"
      ? "SearXNG: stopped"
      : "SearXNG: not installed";
  chip.className = `chip ${running ? "confidence" : ""}`.trim();
  toggle.disabled = false;
  setLabel(
    toggle,
    //: "Install & start" wrapped onto its own line in a 318px panel, so a
    //: two-word chip sat above a full-width button before you had searched
    //: anything. "Install" says the same thing in the width available, what
    //: it starts afterwards is not a decision anyone is making here.
    running ? "ph:stop-circle Stop" : info.state === "absent" ? "ph:play Install" : "ph:play Start"
  );
  toggle.title = running
    ? "Stop the local SearXNG instance"
    : info.state === "absent"
      ? "Install SearXNG locally and start it, searches then never leave this machine"
      : "Start the local SearXNG instance";
  toggle.onclick = async () => {
    toggle.disabled = true;
    try {
      await apiJson(`/websearch/searxng/${running ? "stop" : "start"}`, { method: "POST" });
      toast(
        running
          ? "Stopping SearXNG."
          : "Starting SearXNG… the first run pulls the image, so give it a minute."
      );
    } catch (error) {
      toast(error.message, true);
    }
    refreshWebSearxngStrip();
  };
  // Keep polling while it settles, same as Settings' own richer view: 
  // otherwise "Starting…" can stick with no way to tell it's still moving.
  if (info.state === "running" && !info.responding) {
    clearTimeout(webSearxngTimer);
    webSearxngTimer = setTimeout(refreshWebSearxngStrip, 3000);
  }
}

// One search result row, split out so the initial batch and the "Show
// more" reveal (below) build identical rows from one code path.
function buildWebResultRow(result) {
  const row = document.createElement("div");
  row.className = "web-result";

  //: **Source first, then the headline.** Reported bluntly: "the web search
  //: features and ui and ux are horrible." Half of that was reading order.
  //: Every search surface the user compares this to, Google, Perplexity,
  //: Odysseus's own: puts where a result came from *above* its title,
  //: because deciding whether to trust a result starts with the domain. This
  //: had the title first and the domain under it, so the eye landed on
  //: fifteen words of headline before learning it was from a forum.
  const meta = document.createElement("div");
  meta.className = "web-result-meta muted";
  const host = document.createElement("span");
  host.className = "web-result-host";
  host.textContent = result.domain || "";
  meta.appendChild(host);
  // SearXNG is a metasearch engine, so "via SearXNG" says where the query
  // was assembled rather than who answered it. Naming the upstream engines
  // is what makes a self-hosted instance legible rather than a black box.
  // textContent throughout: these names come from a third party.
  if (Array.isArray(result.via) && result.via.length) {
    const via = document.createElement("span");
    via.className = "web-result-via";
    via.textContent = result.via.join(" · ");
    via.title = `Found by ${result.via.join(", ")}`;
    meta.append(document.createTextNode(" · "), via);
  }
  row.appendChild(meta);

  const title = document.createElement("button");
  title.type = "button";
  title.className = "web-result-title";
  title.textContent = result.title || result.url;
  title.title = `Read “${result.title || result.url}” here, without opening a browser`;
  title.addEventListener("click", () => openWebReader(result.url));
  row.appendChild(title);

  if (result.snippet) {
    const snippet = document.createElement("div");
    snippet.className = "web-result-snippet muted";
    snippet.textContent = result.snippet;
    row.appendChild(snippet);
  }

  //: **One kebab, not a stacked column of icons.** The other half of
  //: "horrible", and it was measurable: the actions column was `opacity: 0`
  //: rather than removed, so its width was reserved on *every* row whether or
  //: not you were hovering, two stacked buttons' worth of it, and every
  //: title in a 318px panel wrapped to three lines around a column showing
  //: nothing. Measured at 115px per result, so five fitted in a full-height
  //: panel.
  //:
  //: A kebab is 28px, always visible (so it is reachable by touch and by
  //: keyboard without a hover), and it is what every other list in this app
  //: uses. It also has room for words, which is how Bookmark and Save could
  //: be added at all: as a fourth and fifth icon they would have been two
  //: more glyphs nobody could tell apart.
  const actions = document.createElement("div");
  actions.className = "web-result-actions";
  const label = result.title || result.domain || result.url;
  actions.appendChild(
    kebabMenu(
      [
        {
          label: "ph:book-open-text Read here",
          title: "Read this page as text, inside MemoryMap",
          run: () => openWebReader(result.url),
        },
        {
          label: "ph:arrow-square-out Open in browser",
          title: "Open this page in your own browser",
          run: () => window.open(result.url, "_blank", "noopener,noreferrer"),
        },
        {
          label: "ph:chat-circle Ask the AI about this",
          title: "Let the AI fetch this page and answer about it",
          run: () => askAboutPage(result.url, result.title),
        },
        {
          //: The one integration this panel never had, and the obvious one:
          //: the app already keeps bookmarks, and "I found something worth
          //: keeping" is what a search result *is*. Without this the only way
          //: to keep a result was to copy its URL out and paste it into
          //: another tab of the same app.
          label: "ph:bookmark-simple Save as bookmark",
          title: "Keep this link in your bookmarks",
          run: () => bookmarkWebResult(result),
        },
      ],
      `Actions for “${label}”`
    )
  );
  row.appendChild(actions);
  return row;
}

//: Saves a web result straight into the app's own bookmarks. Reports the
//: duplicate case rather than silently making a second row: the endpoint
//: already tells us (`duplicate_of`), and "saved" for something that was
//: already saved is a small lie that makes the list look wrong later.
async function bookmarkWebResult(result) {
  try {
    const saved = await apiJson("/bookmarks", {
      method: "POST",
      body: JSON.stringify({
        url: result.url,
        title: (result.title || "").slice(0, 200),
        note: (result.snippet || "").slice(0, 2000),
      }),
    });
    toast(
      saved && saved.duplicate_of
        ? "Already in your bookmarks."
        : `Bookmarked “${saved.title || saved.url}”.`
    );
  } catch (error) {
    toast(error.message || "Couldn't save that bookmark.", true);
  }
}

// Last few distinct web queries, newest first, asked for directly ("missing
// features... history"). Client-side only: these are the person's own past
// searches, same privacy tier as the search itself (already opt-in, already
// logged locally via manager.log_action), nothing new leaves the machine.
const WEB_SEARCH_HISTORY_KEY = "webSearchHistory";
const WEB_SEARCH_HISTORY_MAX = 8;
// Results already fetched for the current query but not yet shown, "Show
// more" reveals from here rather than re-searching, since the backend
// already returns up to 20 in one call (routes_websearch.py).
let webSearchPending = [];

function loadWebSearchHistory() {
  try {
    const raw = JSON.parse(localStorage.getItem(WEB_SEARCH_HISTORY_KEY) || "[]");
    return Array.isArray(raw) ? raw.filter((q) => typeof q === "string") : [];
  } catch {
    return [];
  }
}

function pushWebSearchHistory(query) {
  const trimmed = query.trim();
  if (!trimmed) return;
  const history = [trimmed, ...loadWebSearchHistory().filter((q) => q !== trimmed)].slice(
    0,
    WEB_SEARCH_HISTORY_MAX
  );
  try {
    localStorage.setItem(WEB_SEARCH_HISTORY_KEY, JSON.stringify(history));
  } catch {
    /* storage full or blocked, the search itself still worked */
  }
}

// Shown only while the query box is empty: recent searches are a way *in*,
// not chrome that sits above every result list.
function renderWebSearchHistory() {
  const box = $("web-search-history");
  if (!box) return;
  const history = loadWebSearchHistory();
  box.replaceChildren();
  if ($("web-query").value.trim() || !history.length) {
    box.classList.add("hidden");
    return;
  }
  box.classList.remove("hidden");
  for (const query of history) {
    const chip = document.createElement("button");
    chip.type = "button";
    chip.className = "chip chip-interactive tag";
    setLabel(chip, `ph:clock-counter-clockwise ${query}`);
    chip.title = `Search again: ${query}`;
    chip.addEventListener("click", () => {
      $("web-query").value = query;
      runWebSearch();
    });
    box.appendChild(chip);
  }
}

async function runWebSearch() {
  const query = $("web-query").value.trim();
  if (!query) return;
  const status = $("web-status");
  const box = $("web-results");
  $("web-reader").classList.add("hidden");
  box.replaceChildren();
  webSearchPending = [];
  status.classList.remove("error");
  status.textContent = "Searching the web…";
  let body;
  try {
    // Asks for the route's full cap in one call, both providers already
    // fetch one page and slice it, so this costs nothing extra over asking
    // for 8, and "Show more" below can reveal the rest without a second
    // request (or a second hit against a rate limit).
    body = await apiJson(`/websearch?q=${encodeURIComponent(query)}&limit=20`);
  } catch (error) {
    status.classList.add("error");
    status.textContent = error.message;
    return;
  }
  pushWebSearchHistory(query);
  renderWebSearchHistory();
  const results = body.results || [];
  // Name the engine that ANSWERED, which under "Automatic" is not
  // necessarily the one configured, and say what that means for privacy.
  // The person chose an engine in Settings for a reason; without this the
  // choice is invisible at the one moment it applies. Said on an empty result
  // too: "nothing found" and "nothing found *by DuckDuckGo*" are different
  // facts, and the second is the one you can act on.
  const answered = body.answered_by || { label: body.provider || "", detail: "" };
  status.replaceChildren();
  const summary = document.createElement("span");
  summary.textContent = results.length
    ? `${results.length} result${results.length === 1 ? "" : "s"} via ${answered.label}`
    : `No results from ${answered.label}: try different words.`;
  status.appendChild(summary);
  if (answered.detail) {
    //: Its own line, not " · " glued onto the count. In a narrow panel the
    //: joined version wrapped mid-phrase, so the sentence that explains where
    //: the query went broke across the fold at an arbitrary word.
    const detail = document.createElement("span");
    detail.className = "web-answered-detail muted";
    detail.textContent = answered.detail;
    status.appendChild(detail);
  }

  const INITIAL_SHOWN = 8;
  for (const result of results.slice(0, INITIAL_SHOWN)) {
    box.appendChild(buildWebResultRow(result));
  }
  webSearchPending = results.slice(INITIAL_SHOWN);
  if (webSearchPending.length) {
    const more = document.createElement("button");
    more.type = "button";
    more.className = "ghost small web-show-more";
    setLabel(more, `ph:caret-down Show ${webSearchPending.length} more`);
    more.addEventListener("click", () => {
      for (const result of webSearchPending) box.insertBefore(buildWebResultRow(result), more);
      webSearchPending = [];
      more.remove();
    });
    box.appendChild(more);
  }
}

// "Ask about this" used to drop `About <url>, ` into the chat box and stop
// there. The model cannot open a URL, so it answered from the address text, 
// which is why this read as simply not working (user-reported). It now closes
// the web panel, writes a question naming the page, and lets the agent's
// read_url tool fetch it. The tool needs web search on, so that is checked
// first and offered rather than failing silently.
async function askAboutPage(url, title) {
  if (!(prefsCache && prefsCache.web_search_enabled)) {
    toast("Turn on Web search first, reading a page needs it.", true);
    return;
  }
  // Reading a page is a tool call, so agent mode has to be on for this turn.
  const input = $("chat-input");
  const label = (title || "").trim() || url;
  input.value = `Read ${url} and tell me about it, "${label}".`;
  toggleWebPanel(false);
  input.focus();
  // Sent with tools forced on, whatever the toggle says: the request is
  // meaningless without the one tool that can fetch the page.
  await sendChatMessage(undefined, { useTools: true });
}

async function openWebReader(url) {
  const status = $("web-status");
  status.classList.remove("error");
  status.textContent = "Opening…";
  let page;
  try {
    page = await apiJson(`/websearch/read?url=${encodeURIComponent(url)}`);
  } catch (error) {
    status.classList.add("error");
    status.textContent = error.message;
    return;
  }
  webReaderPage = page;
  status.textContent = "";
  $("web-reader-title").textContent = page.title || page.domain;
  const length = page.read_minutes
    ? ` · ${page.words.toLocaleString()} words, about ${page.read_minutes} min`
    : "";
  $("web-reader-source").textContent = `${page.domain}${length}`;

  // Lay the page out as headings, paragraphs and lists rather than one wall
  // of text. Built with createElement/textContent: never innerHTML, since
  // the page is untrusted by definition.
  const box = $("web-reader-text");
  box.replaceChildren();
  const blocks = page.blocks && page.blocks.length ? page.blocks : null;
  if (!blocks) {
    const fallback = document.createElement("p");
    fallback.textContent = page.text || "(Nothing readable on that page.)";
    box.appendChild(fallback);
  } else {
    let list = null;
    for (const block of blocks) {
      if (block.type === "li") {
        if (!list) {
          list = document.createElement("ul");
          box.appendChild(list);
        }
        const li = document.createElement("li");
        li.textContent = block.text;
        list.appendChild(li);
        continue;
      }
      list = null;
      // Headings keep the page's own depth. Rendering every h1..h6 as one
      // size threw away the outline, which is what tells you where you are
      // in a long article.
      const tag =
        block.type === "heading"
          ? `h${Math.min(6, Math.max(3, (block.level || 2) + 1))}`
          : block.type === "pre"
            ? "pre"
            : block.type === "blockquote"
              ? "blockquote"
              : "p";
      const el = document.createElement(tag);
      if (block.type === "heading") el.className = "reader-heading";
      el.textContent = block.text;
      box.appendChild(el);
    }
  }
  box.scrollTop = 0;
  $("web-reader").classList.remove("hidden");
}

async function saveWebPageAsNote() {
  if (!webReaderPage) return;
  // Prefer the structured read, it drops the nav/cookie chrome.
  const readable = (webReaderPage.blocks || [])
    .map((b) =>
      b.type === "heading"
        ? `\n${"#".repeat(Math.min(6, (b.level || 2) + 1))} ${b.text}`
        : b.type === "li"
          ? `- ${b.text}`
          : b.text
    )
    .join("\n")
    .trim();
  const excerpt = (readable || webReaderPage.text || "").slice(0, 1200);
  const content = `${webReaderPage.title}\n${webReaderPage.url}\n\n${excerpt}`;
  try {
    await apiJson("/entries", {
      method: "POST",
      body: JSON.stringify({ content, tags: ["web"] }),
    });
    toast("Saved as a note.");
    loadEntries().catch(() => {});
  } catch (error) {
    toast(error.message, true);
  }
}

// What the backend says about the model in use. Fetched when the Models
// screen is drawn rather than polled: none of it changes while the app runs.
async function renderModelSpec(modelName) {
  const box = $("model-spec");
  if (!box) return;
  const spec = await apiJson(`/models/spec?name=${encodeURIComponent(modelName || "")}`, {
    silent: true,
  }).catch(() => null);
  if (!spec) {
    box.classList.add("hidden");
    return;
  }
  // Tri-state, and the third state is the point: null means "this backend
  // doesn't report capabilities", which is not the same as "no". Saying "no"
  // about a model that works fine would send someone chasing a problem that
  // isn't there.
  // `== null`, not `=== null`: the whole point of this helper is that "not
  // declared" must never render as a confident "no" (§35C), and a *missing*
  // key is exactly as unknown as an explicit null. With `===` an absent field
  // fell through to the falsy branch and printed "no", the reported bug,
  // surviving in the one case nobody checked.
  const canDo = (value) => (value == null ? "not reported" : value ? "yes" : "no");
  const rows = [
    ["Size", spec.parameters],
    ["Quantisation", spec.quantisation],
    ["Family", spec.family],
    // Two windows, deliberately. A 128k model is *run* at less because the KV
    // cache scales with the window, without both numbers the percentage on
    // each message looks wrong to anyone who knows what the model can hold.
    [
      "Context window",
      spec.context_length
        ? `${compactTokens(spec.usable_context)} in use` +
          (spec.context_length > spec.usable_context
            ? ` (of ${compactTokens(spec.context_length)} it can hold)`
            : "")
        : null,
    ],
    ["Loaded at", spec.loaded_context_length ? compactTokens(spec.loaded_context_length) : null],
    ["Can use tools", canDo(spec.supports_tools)],
    // "Can think: no" was reported for a model that visibly thinks (§35C),
    // and the label was the lie rather than the value: this is the *declared*
    // capability, whether the backend supports a thinking toggle, and a
    // model can still emit inline <think> tags without declaring it, which
    // `split_thinking` picks up and shows. Saying "declared" makes the two
    // facts distinguishable instead of contradictory.
    ["Thinking mode declared", canDo(spec.supports_thinking)],
    ["Can see images", canDo(spec.supports_vision)],
  ].filter(([, value]) => value != null && value !== "");

  box.replaceChildren();
  for (const [label, value] of rows) {
    const dt = document.createElement("dt");
    dt.textContent = label;
    const dd = document.createElement("dd");
    dd.textContent = String(value);
    box.append(dt, dd);
  }
  box.classList.toggle("hidden", rows.length === 0);

  renderModelHealthNote(spec);
}

// A model health card: every number above already existed, but nothing said
// what it *means*: "this model has an 8k window" doesn't answer "will it
// forget what I said earlier in a long chat" (BACKLOG.md §95 item A.2).
// Mirrors ai/context.py's own shares (CHARS_PER_TOKEN, OUTPUT_RESERVE_SHARE,
// HISTORY_SHARE) rather than asking the backend, since this is explicitly a
// rough estimate: context.py's own docstring: "approximately right on every
// model beats being exactly right on one", and an average exchange length
// is itself a guess, so a precise-looking number here would be a false
// promise the actual conversation could contradict either way.
function renderModelHealthNote(spec) {
  const note = $("model-spec-health");
  if (!note) return;
  const usable = spec && spec.usable_context;
  if (!usable) {
    note.classList.add("hidden");
    return;
  }
  const CHARS_PER_TOKEN = 4;
  const OUTPUT_RESERVE_SHARE = 0.15;
  const HISTORY_SHARE = 0.15;
  const AVG_CHARS_PER_EXCHANGE = 500; // a short question + a real answer
  const historyChars =
    usable * CHARS_PER_TOKEN * (1 - OUTPUT_RESERVE_SHARE) * HISTORY_SHARE;
  const roughTurns = Math.round(historyChars / AVG_CHARS_PER_EXCHANGE / 5) * 5;

  if (roughTurns < 5) {
    note.textContent =
      "A small window: a back-and-forth chat will start losing earlier messages within a few exchanges. Notes and documents are unaffected; only the conversation itself is short-lived.";
  } else if (roughTurns <= 40) {
    note.textContent = `What this means for you: a long chat will start dropping its earliest messages after roughly ${roughTurns} exchanges. The AI can still recall anything from further back by re-reading the note or asking again, it just won't be sitting in view.`;
  } else {
    note.textContent =
      "A large window: a normal conversation is very unlikely to ever run out of room.";
  }
  note.classList.remove("hidden");
}

// Both pickers for the response preset: the Chat toolbar's and the Notes
// quick-ask box's. Two controls, one stored preference, the quick-ask box
// always obeyed the saved mode and simply had no way to set it, so this is a
// second way in rather than a second setting. Listed rather than found by
// class so a stray `.small-select` can never join by accident.
const RESPONSE_MODE_SELECTS = ["response-mode-select", "ask-mode-select"];

// The response presets, fetched once. Served by /chat/modes rather than
// listed here so adding a fourth is a change to `ai/presets.py` alone (§11).
async function loadResponseModes() {
  const selects = RESPONSE_MODE_SELECTS.map((id) => $(id)).filter(Boolean);
  if (!selects.length) return;
  const body = await apiJson("/chat/modes", { silent: true }).catch(() => null);
  if (!body || !body.modes) return;
  const active = body.modes.find((m) => m.id === body.active);
  for (const select of selects) {
    select.replaceChildren();
    for (const mode of body.modes) {
      const option = document.createElement("option");
      option.value = mode.id;
      option.textContent = mode.label;
      option.title = mode.description;
      if (mode.id === body.active) option.selected = true;
      select.appendChild(option);
    }
    if (active) select.title = active.description;
  }
}

// Picking in one picker moves the other. Without this the two would drift
// apart the moment either was touched, and the one you weren't looking at
// would be lying about what the next answer will do.
async function setResponseMode(chosen) {
  for (const id of RESPONSE_MODE_SELECTS) {
    const select = $(id);
    if (!select) continue;
    select.value = chosen;
    const option = select.selectedOptions[0];
    select.title = (option && option.title) || "";
  }
  // Changing the picker changes the default too, otherwise someone who works
  // in Quick would re-pick it on every reload. The *request* still carries the
  // mode per turn, so this is "remember what I chose" rather than a second
  // setting that can disagree with the dropdown.
  await apiJson("/preferences", {
    method: "PUT",
    body: JSON.stringify({ response_mode: chosen }),
  }).catch(() => {});
}

function personaOptions() {
  // Built-ins + the user's custom personas (deduped: an edited built-in
  // is stored under the same name); the active one pre-selected.
  const select = $("persona-select");
  const custom = (prefsCache && prefsCache.personas) || [];
  const active = (prefsCache && prefsCache.active_persona) || "Librarian";
  const names = [
    ...new Set(["Librarian", "Coach", "Analyst", ...custom.map((p) => p.name)]),
  ];
  // name -> its prompt, so the dropdown can describe each persona on hover.
  const overrides = new Map(custom.map((p) => [p.name, p]));
  const describe = (name) => {
    const prompt = (overrides.get(name) || {}).prompt || BUILTIN_PERSONAS[name] || "";
    return prompt.length > 200 ? prompt.slice(0, 199) + "…" : prompt;
  };
  select.replaceChildren();
  for (const name of names) {
    const option = document.createElement("option");
    option.value = name;
    option.textContent = name;
    option.title = describe(name); // hover shows what this persona does
    if (name === active) option.selected = true;
    select.appendChild(option);
  }
  // Also surface the active persona's description on the closed select itself.
  select.title = describe(active);
  // The full prompt, not the hover excerpt: the preview panel exists precisely so
  // the instructions the model is given aren't a 200-character preview.
  const fullPrompt = (name) =>
    (overrides.get(name) || {}).prompt || BUILTIN_PERSONAS[name] || "";
  const showPrompt = (name) => {
    $("persona-prompt-text").textContent =
      fullPrompt(name) || "This persona adds no instructions of its own.";
  };
  showPrompt(active);
  select.onchange = () => {
    select.title = describe(select.value);
    showPrompt(select.value);
  };
}

// You could choose a persona but never read what it told the model to do, 
// which makes the choice a guess. This shows the actual system prompt.
function togglePersonaPrompt() {
  const panel = $("persona-peek-panel");
  const showing = panel.classList.toggle("hidden");
  $("persona-peek").setAttribute("aria-expanded", String(!showing));
}

// A running total for the whole conversation. Per-message counts can't tell
// you when a thread has grown heavy enough to be worth starting over.
function renderChatUsage(tokens) {
  const el = $("chat-usage");
  if (!el) return;
  const total = Number(tokens) || 0;
  el.hidden = total === 0;
  el.textContent = total ? `${formatTokens(total)} tokens` : "";
  renderChatTurnCount();
}

//: **The conversation-level context meter.**
//:
//: Fed from the last turn's `stats` (prompt tokens against the window the turn
//: was budgeted for: `context_tokens`, which `ollama_client` has always sent).
//: Thresholds are Odysseus's: quiet under 70%, a warning at 70, a real alarm
//: at 85, because past about 85 the next turn starts losing the oldest part of
//: its own prompt and the answer quietly gets worse with nothing on screen
//: saying why.
function renderChatContextMeter(stats) {
  const pill = $("chat-context");
  if (!pill) return;
  const used = stats && Number(stats.prompt_tokens);
  const window = stats && Number(stats.context_tokens);
  if (!used || !window) {
    pill.hidden = true;
    return;
  }
  const pct = Math.min(100, Math.round((used / window) * 100));
  pill.hidden = false;
  // INBOX 77: "text wrong ... the badge shows 'used / window'". A raw
  // percentage answered "how full", which the colour already says at a
  // glance; the two counts answer the question a percentage cannot, how
  // much room is actually left to work with.
  pill.textContent = `${compactTokens(used)} / ${compactTokens(window)}`;
  pill.classList.toggle("is-warn", pct >= 70 && pct < 85);
  pill.classList.toggle("is-danger", pct >= 85);
  const approx = stats.usage_source === "estimated" ? "about " : "";
  pill.title =
    `This thread's last turn used ${approx}${compactTokens(used)} of the model's ` +
    `${compactTokens(window)} context window.` +
    (pct >= 70
      ? "\n\nPast ~85% the next turn starts dropping the oldest part of its own " +
        "prompt. Click to summarise the earlier messages instead."
      : "\n\nClick to summarise the earlier messages.");
}

//: How long the thread is, beside what it has cost. Asked for with the header
//: redesign ("the metadata, model used, chat functions, token usage data and
//: more"), and it is the fact the two controls next to it are actually about:
//: Compress and Fork are both answers to "this conversation has got long", and
//: a token count alone does not say that in a unit anyone thinks in.
function renderChatTurnCount() {
  const el = $("chat-turns");
  if (!el) return;
  const turns = (chatConv && chatConv.turns && chatConv.turns.length) || 0;
  el.hidden = turns === 0;
  el.textContent = turns === 1 ? "1 exchange" : `${turns} exchanges`;
}

//: **The ⋯ that holds everything you do to a whole conversation.**
//:
//: Reported: the header "feels fake, with features and ui elements like
//: buttons just slapped on there with no design thought". Four ghost buttons
//: of equal weight, one of them a red Delete, sat opposite the title on
//: every conversation, so the most destructive action in the tab was also one
//: of its most prominent controls, and the row read as a pile rather than as
//: a header.
//:
//: The rows *click the original buttons*, which is the pattern the Library's
//: own kebab already uses (library.js): every handler, confirm dialog and
//: disabled state stays exactly where it was, and this file learns nothing new
//: about what Export or Delete actually do.
function mountChatActionsMenu() {
  const host = $("chat-actions-menu");
  if (!host || host.childElementCount) return;
  const click = (id) => () => $(id)?.click();
  host.appendChild(
    kebabMenu(
      [
        { label: "ph:pencil-simple Rename this chat", run: () => renameCurrentConversation() },
        { label: "ph:git-branch Fork this chat", title: $("chat-fork")?.title, run: click("chat-fork") },
        {
          label: "ph:arrows-in Compress the earlier messages",
          title: $("chat-compress")?.title,
          run: click("chat-compress"),
        },
        { label: "ph:download-simple Export as Markdown", run: click("chat-export") },
        {
          //: Odysseus's "Save to Documents", which lands better here than it
          //: does there: this app *has* a Documents tab, and a conversation
          //: worth keeping is usually worth keeping beside the notes it drew
          //: on rather than as a file in a downloads folder.
          label: "ph:file-text Save this chat as a document",
          run: () => saveChatAsDocument(),
        },
        {
          label: "ph:copy Copy the whole transcript",
          run: async () => {
            const text = chatTranscriptText();
            if (!text) return toast("There is nothing to copy yet.");
            copyToClipboard(text);
          },
        },
        { label: "ph:trash Delete this chat", danger: true, run: click("chat-delete") },
      ],
      "More actions for this conversation"
    )
  );
}

//: **A conversation, kept as a document.**
//:
//: The transcript already exports as a file (`#chat-export`); this keeps it
//: *inside* the notebook, where it is searchable, linkable and editable like
//: everything else. Titled after the conversation so the Documents list reads
//: as a list of conversations rather than of dated blobs.
async function saveChatAsDocument() {
  const text = chatTranscriptText();
  if (!text) return toast("There is nothing to save yet.");
  const title = ($("chat-title")?.textContent || "Chat").trim();
  try {
    const doc = await apiJson("/documents", {
      method: "POST",
      body: JSON.stringify({
        title: `${title}: chat`,
        content: `# ${title}\n\n${text}\n`,
      }),
    });
    toastAction("Saved to your documents.", "Open it", () => {
      switchTab("documents");
      if (typeof openDocument === "function") openDocument(doc.id);
    });
  } catch (error) {
    toast(error.message || "Couldn't save that document.", true);
  }
}

//: The transcript as text, the thing a person actually wants when they say
//: "copy this chat", and previously only reachable by exporting a file.
function chatTranscriptText() {
  const parts = [];
  for (const msg of $("chat-messages")?.querySelectorAll(".msg") || []) {
    const who = msg.classList.contains("user") ? "You" : assistantLabel();
    const body = msg.querySelector(".msg-body, .bubble-answer");
    const text = (body?.innerText || "").trim();
    if (text) parts.push(`**${who}:** ${text}`);
  }
  return parts.join("\n\n");
}

// --- compressing this conversation's context (§35I) --------------------------
//
// Asked for directly: *"there should be a tool as well as a manual command or
// something to be able to compress chat context on longer chats so the AI can
// better continue."* This is the manual half, which §35I says ships first
// because it cannot misfire: you press it, you read what it produced, and only
// then does the model see it instead of the turns it replaces.
//
// Nothing is deleted. The transcript on screen and the saved conversation keep
// every turn: `chatSummary` only changes what `chatHistoryToSend` hands the
// model, so Undo is one assignment.

// How many turns to leave alone at the end. Compressing the exchange you are
// still in the middle of is how a summary loses the thing you are talking
// about right now.
const KEEP_RECENT_TURNS = 2;

async function compressChatContext() {
  const covered = chatConv.turns.length - KEEP_RECENT_TURNS;
  if (covered < 2) {
    toast("There isn't enough conversation to compress yet.", true);
    return;
  }
  const button = $("chat-compress");
  button.disabled = true;
  const previous = button.textContent;
  button.textContent = "Summarising…";
  try {
    const result = await apiJson("/chat/compress", {
      method: "POST",
      body: JSON.stringify({ history: chatConv.turns.slice(0, covered) }),
    });
    showCompressReview(result, covered);
  } finally {
    button.disabled = false;
    button.textContent = previous;
  }
}

// The summary, before it is used, editable, because a summary you cannot
// correct is one you have to trust blindly, and this one is about to be the
// model's only memory of the first half of the conversation.
function showCompressReview(result, covered) {
  const panel = $("chat-compress-panel");
  const box = $("chat-compress-text");
  box.value = result.summary;
  $("chat-compress-stats").textContent =
    `${covered} messages → ${Math.round(result.chars_after / 10) / 100}k characters ` +
    `(was ${Math.round(result.chars_before / 10) / 100}k). Edit it if it missed something.`;
  panel.classList.remove("hidden");
  panel.dataset.covered = String(covered);
  box.focus();
}

function applyCompression() {
  const text = $("chat-compress-text").value.trim();
  const covered = Number($("chat-compress-panel").dataset.covered || 0);
  if (!text || covered < 1) return;
  chatSummary = { text, covered };
  $("chat-compress-panel").classList.add("hidden");
  renderCompressionState();
  toast(`Using a summary in place of the first ${covered} messages.`);
}

// The badge that says the model is reading a summary rather than the thread,
// with the way back. A compression the user cannot see is a conversation
// quietly answering from something they never read.
function renderCompressionState() {
  const badge = $("chat-compressed");
  if (!badge) return;
  badge.classList.toggle("hidden", !chatSummary);
  if (chatSummary) {
    setLabel(badge.firstElementChild, `ph:arrows-in first ${chatSummary.covered} summarised`);
  }
}

// Three-dot "the model is about to speak" indicator (Wave D).
// "The model is working." Under reduced motion the bouncing dots are frozen by
// the blanket animation rules, three motionless dots say nothing at all, and
// read as a rendering fault rather than as progress. So when motion is off,
// this becomes a word instead of a gesture. Silence is not an acceptable
// substitute for either.
function reducedMotionWanted() {
  return (
    window.matchMedia("(prefers-reduced-motion: reduce)").matches ||
    document.documentElement.dataset.motion === "reduced"
  );
}

// `label` is the reduced-motion fallback: with animations off the dots can't
// convey "working", so a word has to. Callers that already print their own
// sentence beside the indicator pass theirs in, the weekly digest used to
// append " Thinking about your week…" next to the default, and it rendered as
// "Thinking… Thinking about your week…" (user-reported).
//: **Progress is feedback, not decoration, and it gets its own switch.**
//:
//: Reported three times, the last with a screenshot of a frozen italic
//: "Thinking…": *"the thinking and writing animation is completely broken,
//: doesn't move"*, and then the instruction that settles the design, 
//: *"make them happen even if animations are stalled, or make them paused
//: separately to the rest like the background art."*
//:
//: The background art already has exactly that shape (`bg-motion`: auto /
//: moving / still), so this follows it rather than inventing a second idea.
//: The difference is the **default**: the art defaults to `auto` because it
//: is decoration, and this defaults to `always` because a progress indicator
//: that has stopped is indistinguishable from an app that has hung. Turning
//: off "animations and transitions" is a statement about chrome; it was
//: never a request to be left unable to tell whether the model is working.
//:
//: The OS's own `prefers-reduced-motion` is still honoured under `auto`, and
//: `alive()` below is what stops that meaning *dead*, see its own comment.
function progressMotionWanted() {
  const choice = document.documentElement.dataset.progressMotion || "always";
  if (choice === "still") return false;
  //: **"Always" means always, including through the platform setting**, by
  //: direct instruction: *"make sure the animations run even with prefer
  //: reduced motion on, like the rotating generated logos."* My first pass
  //: exempted the OS setting on accessibility grounds and was overruled, it
  //: is the user's own app, the choice is theirs, and it is one select away
  //: from `auto`, which does respect the platform. The CSS counter-rule in
  //: 02-chat-graph.css carries the same decision for the same reason.
  if (choice === "always") return true;
  return !reducedMotionWanted();
}

// `label` is the reduced-motion fallback: with animations off the dots can't
// convey "working", so a word has to. Callers that already print their own
// sentence beside the indicator pass theirs in, the weekly digest used to
// append " Thinking about your week…" next to the default, and it rendered as
// "Thinking… Thinking about your week…" (user-reported).
//: The writing motif: three nodes and the edge being drawn between them, 
//: the same node-and-edge vocabulary the graph, the concept maps and the app's
//: own mark are built from. Inline SVG with attributes rather than a `style`
//: string, because this app's CSP drops inline styles (CLAUDE.md, "a policy
//: silently refusing the work"); everything that moves is done in CSS.
//: **An interval that belongs to a node, and survives that node being moved.**
//:
//: The pattern this replaces was `if (!node.isConnected) return
//: clearInterval(timer)`, correct about the leak it was guarding (an interval
//: that outlives its element grows with every turn of a long conversation) and
//: wrong about what "gone" means. **A node that is being re-parented is
//: disconnected for an instant**, and this app re-parents the streaming
//: indicator on purpose: `reattachStreamingTurn` appends every node of the
//: live turn back into `#chat-messages` whenever the pane is rebuilt, and
//: `clearPending` moves the pending line to the end of the steps.
//:
//: One tick landing inside one of those windows killed the timer for good.
//: The node came back, the animation did not, and it froze mid-cycle showing
//: its three dots standing still, reported as "the text streaming animation
//: stops moving and just shows as 3 lines", and again as "I scrolled up while
//: still streaming the response and the generating and animation disappeared",
//: which is the same timer dying during the re-render that scrolling caused.
//:
//: So: skip the work while detached, and only give up once the node has stayed
//: gone for `GRACE_TICKS` in a row. A re-parent is one frame; ten ticks is
//: several seconds, which is far longer than any re-render and still bounded,
//: so the leak the original guard was written for cannot come back.
const LIVING_INTERVAL_GRACE_TICKS = 10;

function livingInterval(node, fn, ms) {
  let missing = 0;
  const timer = setInterval(() => {
    if (!node.isConnected) {
      missing += 1;
      if (missing >= LIVING_INTERVAL_GRACE_TICKS) clearInterval(timer);
      return;
    }
    missing = 0;
    fn();
  }, ms);
  return timer;
}

function aiWritingTrace() {
  const NS = "http://www.w3.org/2000/svg";
  const svg = document.createElementNS(NS, "svg");
  svg.setAttribute("class", "ai-writing-trace");
  svg.setAttribute("viewBox", "0 0 34 12");
  svg.setAttribute("aria-hidden", "true"); // the container already announces itself
  const line = document.createElementNS(NS, "path");
  line.setAttribute("class", "ai-writing-edge");
  line.setAttribute("d", "M4 8 L17 4 L30 8");
  svg.append(line);
  const nodes = [
    [4, 8],
    [17, 4],
    [30, 8],
  ];
  nodes.forEach(([cx, cy], index) => {
    const dot = document.createElementNS(NS, "circle");
    dot.setAttribute("class", `ai-writing-node ai-writing-node-${index + 1}`);
    dot.setAttribute("cx", String(cx));
    dot.setAttribute("cy", String(cy));
    dot.setAttribute("r", "2");
    svg.append(dot);
  });
  return svg;
}

//: **Two phases, because waiting and writing are not the same event.**
//:
//: Asked for directly: *"make the 3-dot animation change to something cool and
//: app specific when the model is writing, and when it is thinking or waiting
//: for a response it goes back to the 3-dot button, and make the transition
//: between animations smooth as well."*
//:
//: `thinking` keeps the dots: they are the universal "waiting" idiom and
//: everyone already reads them. `writing` swaps to this app's own motif: a
//: short run of nodes with a line drawing itself between them, which is a
//: notebook writing a new thought into its graph. Every other indicator in
//: here (`Loading…`, `Generating caption…`) simply never leaves `thinking`,
//: so nothing else changes shape.
//:
//: Both live in the same box at the same time and cross-fade, so the swap
//: cannot cause a layout jump mid-stream, the container is sized once and
//: the two children are stacked in it.
//:
//: The SVG is appended *after* the three dot spans on purpose:
//: `.typing-dots span:nth-child(2)`/`(3)` address those dots by position, and
//: putting anything before them would silently re-time the bounce.
//: **A mouse wheel must scroll a horizontal strip.** Reported: "if the tabs
//: bar becomes scrollable, I cant do it with mouse, only with touch or my
//: trackpad."
//:
//: That is the browser's behaviour, not a bug in the strip: a wheel emits
//: `deltaY`, and an element that only overflows on X ignores it, so a
//: trackpad (which emits real `deltaX` on a two-finger swipe) and a
//: touchscreen work while a wheel does nothing at all. Every app with a tab
//: strip translates the axis by hand; this is that, once, for all of them.
//:
//: Three conditions before it takes over, so it never steals a gesture that
//: meant something else: the element must actually overflow horizontally, the
//: gesture must be vertical-only (`deltaX === 0`, a trackpad's own horizontal
//: swipe is left alone), and the scroll must have somewhere to go in that
//: direction, so at either end the page scrolls normally instead of the strip
//: swallowing the wheel.
//:
//: `passive: false` because it calls `preventDefault`; that is the whole
//: point, and it is scoped to elements that pass the test above.
function wheelScrollsHorizontally(element) {
  if (!element || element.dataset.wheelX === "1") return;
  element.dataset.wheelX = "1";
  element.addEventListener(
    "wheel",
    (event) => {
      if (event.deltaX !== 0 || event.shiftKey) return;
      const room = element.scrollWidth - element.clientWidth;
      if (room <= 1) return;
      const atStart = element.scrollLeft <= 0 && event.deltaY < 0;
      const atEnd = element.scrollLeft >= room - 1 && event.deltaY > 0;
      if (atStart || atEnd) return;
      element.scrollLeft += event.deltaY;
      event.preventDefault();
    },
    { passive: false }
  );
}
window.wheelScrollsHorizontally = wheelScrollsHorizontally;

//: Every horizontal strip in the app, in one list. A strip added later gets
//: this by being added here, which is cheaper than each surface remembering.
function wireHorizontalWheelScrolling() {
  const strips = [
    "#tab-bar",
    "#notes-subtabs",
    "#library-subtabs",
    ".doc-toolbar",
    ".seg.edge-fade",
    ".edge-fade",
  ];
  for (const selector of strips) {
    for (const element of document.querySelectorAll(selector)) {
      wheelScrollsHorizontally(element);
    }
  }
}
window.wireHorizontalWheelScrolling = wireHorizontalWheelScrolling;

function typingDots(label = "Thinking…") {
  const dots = document.createElement("span");
  //: `typing-dots` is kept as the class even though this is now two
  //: indicators: existing CSS keys off it, and so does the code that removes
  //: the indicator when the first token lands
  //: (`querySelector(".typing-dots, .typing-label")`). Renaming it would have
  //: been a silent breakage in surfaces this change never meant to touch.
  dots.className = "typing-dots";
  dots.dataset.phase = "thinking";
  dots.setAttribute("role", "status");
  dots.setAttribute("aria-label", label);
  dots.setStatus = (next) => {
    dots.setAttribute("aria-label", next);
  };
  if (progressMotionWanted()) {
    for (let i = 0; i < 3; i++) dots.appendChild(document.createElement("span"));
    dots.appendChild(aiWritingTrace());
    //: Idempotent, because the streaming callbacks that drive this fire on
    //: every delta: setting the same phase again must not restart the
    //: cross-fade or the line would stutter on each token.
    dots.setPhase = (phase) => {
      const next = phase === "writing" ? "writing" : "thinking";
      if (dots.dataset.phase !== next) dots.dataset.phase = next;
    };
    return dots;
  }

  //: **INBOX 36: stepping a dot's colour once a second did not read as
  //: alive.** The previous fix here (a class moving from dot to dot) was
  //: reasoned, not observed, and the owner's desktop shell still showed a
  //: flat row of dots: `.typing-dots-stepped span.is-on` swapped `--border`
  //: for `--accent`, a colour change with no size, position or brightness
  //: cue big enough to notice out of the corner of an eye while reading an
  //: answer. Reported again, unchanged: "the streaming indicator still does
  //: not animate."
  //:
  //: A word that changes is unambiguous in a way three near-identical dots
  //: never were, and a *slow* opacity pulse is movement of the one kind
  //: `prefers-reduced-motion` guidance treats as safe: no translation, no
  //: scaling, nothing that can trigger vestibular symptoms, just a fade
  //: between two brightness levels over several seconds. The word itself
  //: still changes with the phase, the same "value changing is information"
  //: reasoning the old stepped dots were built on, just legible this time.
  dots.classList.add("typing-dots-stepped");
  const word = document.createElement("span");
  word.className = "typing-word";
  word.textContent = "Thinking";
  dots.appendChild(word);
  dots.setPhase = (phase) => {
    const next = phase === "writing" ? "writing" : "thinking";
    if (dots.dataset.phase === next) return;
    dots.dataset.phase = next;
    word.textContent = next === "writing" ? "Writing" : "Thinking";
  };
  return dots;
}

// **A working signal that says what it is working on.**
//
// Reported repeatedly, and finally with two screenshots: "there is no cycling
// or rotating thinking or generating animations", over a bubble reading a
// motionless italic "Thinking…". Two separate things produce that:
//
//  - **Reduced motion.** `typingDots` above swaps every animation for one
//    static word when the OS asks for less motion, and the desktop shell
//    inherits Windows' own "show animations" setting, which is off on a lot
//    of machines. The honest fix is not to animate anyway; it is to stop the
//    non-animated state being *dead*. Changing text is information, not
//    motion, so it is allowed where a bounce is not.
//  - **One label for the whole turn.** Even animating, three dots that mean
//    the same thing from the first millisecond to the last say nothing about
//    a turn that took eleven seconds and did four different things.
//
// So this pairs the indicator with a label that the stream updates as real
// events arrive: what it is doing now, in the app's own words. Nothing here
// invents a stage: every string it is given comes from an event that
// actually happened (see `sendChatMessage`), because a progress line that
// guesses is worse than one that repeats itself.
//: **Short lines shown while you wait, and every one of them is true.**
//:
//: Asked for: *"add some generated short sentence musings while the thinking
//: dots are showing."* The obvious reading is flavour text, and the obvious
//: implementation is a model writing whimsy about what it is doing. This
//: file's own rule forbids that, and the rule is right: `progressLine` must
//: never invent a stage, because a progress line that guesses is worse than
//: one that repeats itself. A cheerful invented sentence next to a real
//: status label is precisely a guess wearing a status label's clothes.
//:
//: So these are the honest version of the same idea, and they are better than
//: whimsy would have been: facts about *this app* that a person waiting for a
//: local model has time to read and reason to want. A wait is the one moment
//: the interface has someone's attention with nothing to do, spending it on
//: the thing the app most needs to teach (what it is doing with your notes,
//: and where they are going, which is nowhere) is worth more than a joke.
//:
//: They are deliberately not model-generated: a fixed list cannot hallucinate
//: a claim about privacy, and privacy claims are the one kind this app must
//: never get wrong.
const PROGRESS_MUSINGS = [
  "Everything here runs on your machine, nothing is sent anywhere.",
  "Your notes are plain markdown on disk. You can read them without this app.",
  "Searching uses meaning and keywords together, then merges the two rankings.",
  "A note you never tagged is still findable, the links between notes count too.",
  "Private notes are held back from the AI, even when it asks for them.",
  "Ask mode reads. Agent mode can change things, and says so before it does.",
  "Long answers are slower on a small model, not stuck.",
  "Every tool call the AI makes is listed under the answer, with what it touched.",
  "Type [[ in any note to link to another one.",
  "Select text anywhere you can edit and ask the AI about just that passage.",
];

//: How long to wait before showing one. A turn that finishes in a second
//: should never flash a sentence nobody had time to read.
const MUSING_DELAY_MS = 2500;
//: And how long each stays. Long enough to read twice, short enough that a
//: minute-long wait is not one sentence.
const MUSING_ROTATE_MS = 7000;

function progressLine(initial = "Thinking…") {
  const wrap = document.createElement("span");
  wrap.className = "progress-line";
  const indicator = typingDots(initial);
  wrap.appendChild(indicator);
  //: Forwarded rather than reached for: callers hold the `progressLine`, not
  //: the dots inside it, and a caller poking at `.querySelector(".typing-dots")`
  //: would break the moment this component changed shape.
  wrap.setPhase = (phase) => indicator.setPhase?.(phase);
  //: The dots are always dots now, stepped rather than bouncing when motion
  //: is off: so the label is always its own node. It used to be *replaced*
  //: by the indicator under reduced motion, which is how the digest widget
  //: once rendered "Thinking… Thinking about your week…", and is also how
  //: the whole indicator became one frozen italic word.
  const label = document.createElement("span");
  label.className = "progress-line-label";
  label.textContent = initial;
  wrap.appendChild(label);
  //: The musing sits under the status, in its own quieter voice, and never
  //: replaces it: the label says what is happening, this says something true
  //: about the app. Two separate claims, drawn differently on purpose.
  const musing = document.createElement("span");
  musing.className = "progress-musing";
  musing.hidden = true;
  wrap.appendChild(musing);
  let at = Math.floor(Math.random() * PROGRESS_MUSINGS.length);
  const showMusing = () => {
    //: Skipped, not fatal: `livingInterval` below decides when this indicator
    //: is actually finished with, and a node mid-re-parent is not.
    if (!wrap.isConnected) return;
    //: **They cross-fade rather than cutting.** Reported: *"the thinking
    //: bubble animation and generating messages that alternate can be better
    //: designed."* One sentence being replaced by another between two frames
    //: reads as a glitch, the eye catches the change without reading the
    //: line. Removing the class, forcing a reflow and adding it back is what
    //: restarts a CSS transition on an element that is already on screen;
    //: without the reflow the browser coalesces both writes and nothing
    //: animates at all.
    musing.classList.remove("is-shown");
    void musing.offsetWidth;
    musing.textContent = PROGRESS_MUSINGS[at % PROGRESS_MUSINGS.length];
    musing.hidden = false;
    musing.classList.add("is-shown");
    at += 1;
  };
  //: Both timers stop themselves once the node is gone, the caller removes
  //: the progress line, it does not know these exist. Same discipline as the
  //: stepped dots' own interval.
  const first = setTimeout(() => {
    showMusing();
    livingInterval(wrap, showMusing, MUSING_ROTATE_MS);
  }, MUSING_DELAY_MS);
  wrap.addEventListener("remove", () => clearTimeout(first));

  wrap.setStatus = (next) => {
    if (!next || next === label.textContent) return;
    //: The status changes far more often than the musing does, a tool
    //: finishing, prose starting: so it gets the same treatment for the same
    //: reason, one step quieter.
    label.classList.remove("is-shown");
    void label.offsetWidth;
    label.textContent = next;
    label.classList.add("is-shown");
    indicator.setStatus?.(next);
  };
  label.classList.add("is-shown");
  return wrap;
}

// "⋯ Thinking about your week…" as one node: animated dots plus the sentence
// when motion is allowed, and the sentence alone when it isn't: never both
// the default label and a caller's, which is what produced the doubled
// "Thinking… Thinking about your week…" in the digest widget.
function typingLine(label) {
  const wrap = document.createElement("span");
  wrap.appendChild(typingDots(label));
  wrap.append(` ${label}`);
  return wrap;
}

// Coalesce scroll-to-end into one write per animation frame. It used to run
// on every streamed token, forcing a synchronous reflow each time, a big
// source of jank on long answers.
let chatScrollQueued = false;
// --- following a stream without fighting the reader -------------------------------
//
// Asked for directly: the chat and the thinking box should scroll themselves
// as the model writes, "but if the user tries to scroll up it will release the
// lock". Both halves matter: a pane that does not follow makes a long answer
// look frozen, and one that follows unconditionally yanks you back to the
// bottom the moment you try to read what scrolled past.
//
// No "is this scroll programmatic?" flag is needed, which is the usual way
// this gets complicated. Distance from the bottom answers it on its own: a
// scroll we caused lands at zero and stays stuck, and a scroll the reader
// caused moves away from zero and unsticks. Scrolling back down re-sticks,
// so getting the follow behaviour back is the obvious gesture rather than a
// button.
const SCROLL_STICK_SLACK = 40; // px: a scrollbar rarely lands exactly at 0

function followBottom(element) {
  if (!element || element.dataset.followBound === "1") return;
  element.dataset.followBound = "1";
  element.dataset.stuck = "1";
  element.addEventListener(
    "scroll",
    () => {
      const distance =
        element.scrollHeight - element.scrollTop - element.clientHeight;
      element.dataset.stuck = distance <= SCROLL_STICK_SLACK ? "1" : "0";
      //: The chat pane is the one place this flag has a visible consequence
      //:, see `syncChatJumpLatest`. Guarded by id rather than wired at the
      //: chat's own call site because `followBottom` is what owns the flag,
      //: and a second listener would have to duplicate the same maths.
      if (element.id === "chat-messages") syncChatJumpLatest();
    },
    { passive: true }
  );
}

// Scroll to the bottom, unless the reader has scrolled away from it.
function keepAtBottom(element) {
  if (!element) return;
  followBottom(element);
  if (element.dataset.stuck !== "0") element.scrollTop = element.scrollHeight;
}

//: **The "still writing" pill, for when the writing is off-screen.**
//:
//: Reported: "I also scrolled up while still streaming the response and the
//: generating and animation disappeared." Nothing had broken: the indicator
//: lives at the end of the transcript, and scrolling back through a long
//: answer puts the end of the transcript below the fold. `followBottom`
//: already records that the reader has taken over, as `data-stuck="0"` on the
//: pane, and deliberately stops auto-scrolling when it happens; what was
//: missing is any way for the app to keep saying "still working" once the
//: place it was saying it has scrolled away.
//:
//: So the pill is shown by exactly that flag, wears the app's own indicator
//: while a turn is live, and falls back to a plain jump-to-latest the rest of
//: the time: which is a control a long transcript wants anyway and this one
//: never had. `chatStreaming` is the same state the stop button reads, so the
//: two cannot disagree about whether a turn is running.
function syncChatJumpLatest() {
  const button = $("chat-jump-latest");
  const pane = $("chat-messages");
  if (!button || !pane) return;
  //: INBOX 34: this used to trust `pane.dataset.stuck`, which only the
  //: `scroll` listener in `followBottom` ever writes. `newChatConversation`
  //: clears the pane with `replaceChildren()`, which fires no scroll event,
  //: so a reader who had scrolled away in the *previous* conversation left
  //: `dataset.stuck === "0"` behind, and this pill read that stale flag as
  //: "still scrolled away" on a brand-new, empty transcript with nothing to
  //: scroll to. Re-derived from the live rect on every call instead, so a
  //: cleared or shrunk pane can never leave the pill (or, before this
  //: change, the reused down-arrow, see NO_SCROLL_TOP_TABS) showing for a
  //: transcript that has nothing left below the fold. Also keeps
  //: `dataset.stuck` itself current for `keepAtBottom`'s own check.
  const distance = pane.scrollHeight - pane.scrollTop - pane.clientHeight;
  const scrolledAway = distance > SCROLL_STICK_SLACK;
  pane.dataset.stuck = scrolledAway ? "0" : "1";
  const overflowing = pane.scrollHeight - pane.clientHeight > SCROLL_STICK_SLACK;
  button.classList.toggle("hidden", !(scrolledAway && overflowing));
  const streaming = Boolean(chatStreaming);
  button.classList.toggle("is-generating-pill", streaming);
  const label = $("chat-jump-latest-label");
  if (label) label.textContent = streaming ? "Still writing" : "Jump to latest";
  const dots = $("chat-jump-latest-dots");
  if (!dots) return;
  //: Rebuilt only when the phase actually changes: `typingDots` starts an
  //: interval (and, with motion on, CSS animations), and replacing it on every
  //: scroll event would restart both several times a second.
  if (streaming && !dots.firstChild) dots.appendChild(typingDots("Writing"));
  if (!streaming) dots.replaceChildren();
}

function chatScrollToEnd() {
  if (chatScrollQueued) return;
  chatScrollQueued = true;
  requestAnimationFrame(() => {
    chatScrollQueued = false;
    keepAtBottom($("chat-messages"));
    //: Called here as well as on scroll: a turn starting or ending changes
    //: what the pill says, and neither of those is a scroll event.
    syncChatJumpLatest();
  });
}

// The files a message carried, under the message that carried them.
//
// Reported directly: "images and files uploaded into a chat conversation
// arent rendered with the chat messages, the captions arent viewable…and they
// arent previewable or quick navigatable to their stored location in the
// library or documents etc or viewable in a better environment". All of that
// was true: the composer showed a thumbnail chip until you pressed send, and
// then the picture vanished from the conversation entirely, the ids were
// stored (for the model and for media_gc) and nothing ever drew them again.
//
// `attachments` comes hydrated from `GET /conversations/{id}` on reload and is
// built locally on a live send, so both paths render the same thing.
function chatAttachmentStrip(attachments) {
  if (!attachments || !attachments.length) return null;
  const strip = document.createElement("div");
  strip.className = "msg-attachments";
  const images = attachments.filter((a) => a.kind === "image");

  for (const item of attachments) {
    if (item.kind === "image") {
      const figure = document.createElement("figure");
      figure.className = "msg-attachment msg-attachment-image";
      const img = document.createElement("img");
      img.src = mediaSrc(item.url);
      img.alt = item.caption || item.name || "";
      img.loading = "lazy";
      img.title = "Click to view it full size";
      // An upload deleted from the Library long after this message was sent
      // resolves to a row that no longer has a file. Hiding the broken tile
      // is what the gallery does; saying so is better than a grey box.
      img.addEventListener("error", () => {
        figure.classList.add("msg-attachment-missing");
        img.remove();
        const gone = document.createElement("p");
        gone.className = "muted text-sm";
        gone.textContent = `“${item.name}” isn't in your library any more.`;
        figure.prepend(gone);
      });
      img.addEventListener("click", () =>
        openLightbox(
          images.map((i) => ({
            filename: i.name,
            getUrl: () => mediaSrc(i.url),
            caption: i.caption || "",
            text: i.text || "",
          })),
          images.indexOf(item)
        )
      );
      figure.appendChild(img);

      // The caption, which is the half the report names twice. Shown under
      // the thumbnail rather than only in the lightbox: a picture in a
      // conversation is often referred to by what it shows.
      if (item.caption) {
        const caption = document.createElement("figcaption");
        caption.className = "muted text-sm";
        caption.textContent = item.caption;
        figure.appendChild(caption);
      }

      //: **The other half nothing said out loud.** Asked for directly: "in
      //: the chat, when an image and/or document is captioned and ocr is
      //: used it should be tagged under the image in the chat bubble." The
      //: caption was already shown above; `item.text` (the vision-OCR or
      //: Tesseract reading) was resolved by the backend the whole time
      //: (`_hydrate_attachments` in routes_conversations.py) and handed to
      //: the lightbox on click, but nothing in the bubble itself said a
      //: reading existed at all, so the only way to learn one was there was
      //: to open the picture and look.
      //:
      //: A badge, not the text itself: this app has already learned that
      //: lesson once (`ai/embeddings.py`'s `MAX_MEDIA_TEXT_CHARS` note on why
      //: a whole page of transcription does not belong inline in a note), and
      //: a chat bubble is an even worse place for a page of OCR text to land
      //: uninvited. Same "Read · N words" shape the Files sub-tab's reading
      //: list already uses, so the same fact reads the same way everywhere it
      //: appears.
      if (item.text) {
        const words = item.text.trim().split(/\s+/).length;
        const badge = document.createElement("button");
        badge.type = "button";
        badge.className = "chip msg-attachment-read-badge";
        setLabel(badge, `ph:scan Read · ${words.toLocaleString()} words`);
        badge.title = "Text was found in this picture, click it to see the page";
        //: Same lightbox call the thumbnail itself uses, so "click the
        //: picture" and "click the badge that says there is text on it" land
        //: on the same place rather than becoming two different doors.
        badge.addEventListener("click", () =>
          openLightbox(
            images.map((i) => ({
              filename: i.name,
              getUrl: () => mediaSrc(i.url),
              caption: i.caption || "",
              text: i.text || "",
            })),
            images.indexOf(item)
          )
        );
        figure.appendChild(badge);
      }

      const actions = document.createElement("div");
      actions.className = "msg-attachment-actions";
      actions.appendChild(
        smallButton("ph:image Library", `Find “${item.name}” in your library`, () =>
          // One helper, because the media view is two sub-tabs now and a PDF
          // has to land on Files rather than on Images. See
          // `focusLibraryFile` in library.js.
          focusLibraryFile(item.name, item.url || item.name)
        )
      );
      figure.appendChild(actions);
      strip.appendChild(figure);
      continue;
    }

    if (item.kind === "note") {
      // A note: the chip carries its first line and opens it in Notes. Same
      // shape as the document chip below and for the same reason, the note's
      // full text is already one click away and repeating it in the bubble
      // would bury the question that was asked about it.
      const noteChip = document.createElement("button");
      noteChip.type = "button";
      noteChip.className = "chip msg-attachment msg-attachment-note";
      setLabel(noteChip, `ph:paperclip ${item.name}`);
      noteChip.title = `Open this note (#${item.id})`;
      // `flashEntry` is the app's one "take me to this note" path: it also
      // switches sub-tab, clears the filters that would hide the card, and
      // announces the jump. Re-implementing three of those here is how they
      // drift apart.
      noteChip.addEventListener("click", () => flashEntry(item.id));
      strip.appendChild(noteChip);
      continue;
    }

    if (item.kind === "map") {
      // A mind map attached to the question (MINDMAP_PLAN.md §5 item 11).
      // `mapChip` is the app's one map chip, so a map in a sent bubble reads
      // exactly as it does in a note, on the timeline and in a dashboard row
      //, the whole point of §5 item 12. `msg-attachment` on top of it so it
      // sits in the strip like every other kind.
      const board = mapBoardById(item.id) || { id: item.id, title: item.name, type: "map" };
      const chipEl = mapChip(board);
      chipEl.classList.add("msg-attachment");
      strip.appendChild(chipEl);
      continue;
    }

    if (item.kind === "file") {
      // A Library file. Same shape as the document chip below, and the same
      // reason -- its text may be a hundred pages -- but it opens in the
      // Library's Files sub-tab rather than in the Documents editor, because
      // that is where an Attachment row actually lives.
      const fileChip = document.createElement("button");
      fileChip.type = "button";
      fileChip.className = "chip msg-attachment msg-attachment-doc";
      setLabel(fileChip, `ph:paperclip ${item.name}`);
      fileChip.title = `Find “${item.name}” in your library`;
      fileChip.addEventListener("click", () => focusLibraryFile(item.name, `/files/${item.id}`));
      strip.appendChild(fileChip);
      continue;
    }

    // A document: there is nothing to preview inline (its text may be a
    // hundred pages), so the chip is the navigation.
    const chip = document.createElement("button");
    chip.type = "button";
    chip.className = "chip msg-attachment msg-attachment-doc";
    setLabel(chip, `ph:file-text ${item.name}`);
    chip.title = `Open “${item.name}” in Documents`;
    chip.addEventListener("click", () => {
      switchTab("documents");
      openDocument(item.id);
    });
    strip.appendChild(chip);
  }
  return strip;
}

function addBubble(role, text, attachments = null) {
  clearChatEmptyState();
  const bubble = document.createElement("div");
  bubble.className = `msg ${role}`;

  const label = document.createElement("div");
  label.className = "msg-role";
  // **The user gets an avatar too.** Asked for directly: "I feel like the
  // user needs a little icon in the theme of the application in the chat as
  // well." The assistant has had one since `addAssistantBubble` started
  // drawing the app's emblem; a one-sided transcript reads as though only
  // one participant is really there. Same `.msg-avatar` box, so the two
  // columns line up down the thread, the app's own accent and glyph rather
  // than a photo, since this app has no accounts and never asks who you are.
  if (role === "user") {
    const avatar = document.createElement("span");
    avatar.className = "msg-avatar msg-avatar-user";
    avatar.setAttribute("aria-hidden", "true");
    setLabel(avatar, "ph:user");
    const name = document.createElement("span");
    name.textContent = "You";
    label.append(avatar, name);
  } else {
    label.textContent = assistantLabel();
  }
  const body = document.createElement("div");
  body.className = "msg-body";
  body.textContent = text;
  bubble.append(label, body);
  const strip = chatAttachmentStrip(attachments);
  if (strip) bubble.appendChild(strip);

  if (role === "user") {
    bubble.appendChild(
      chatMessageActions([
        { label: "ph:copy", title: "Copy", onClick: (e) => copyToClipboard(text, e.currentTarget) },
        { label: "ph:pencil-simple", title: "Edit this question", onClick: () => editAndResend(bubble, text) },
        { label: "ph:trash", title: "Delete this message", onClick: () => removeChatBubble(bubble) },
      ])
    );
  }
  $("chat-messages").appendChild(bubble);
  chatScrollToEnd();
  return bubble;
}

// --- the agent's run, as an ordered timeline --------------------------------------
// A turn used to render into three fixed slots, thinking, then every tool chip,
// then the answer: regardless of when those things actually happened. For a
// multi-step agent run that destroys the one thing worth seeing: the order. A
// model that thought, searched, thought again and then answered looked
// identical to one that answered immediately.
//
// So steps are appended as the events arrive. Consecutive deltas of the same
// kind extend the current step; a different kind starts a new one, which is
// what produces the thinking → tool → tool → answer chain the user follows.
function agentTimeline(holder) {
  let current = null; // the step still being written into
  const answerSteps = []; // every prose step, in order
  const thinkingSteps = [];
  const record = []; // a serialisable copy, for persistence

  //: **The step group: Perplexity's "Finished 5 steps", in this app's own
  //: words.** Asked for directly: *"I want the steps of the ai to show like
  //: perplexity's steps."*
  //:
  //: Before this, every tool call was a chip appended straight into the
  //: bubble, so a turn that made six calls pushed its own answer six rows
  //: down and the transcript read as a pile of machinery with prose
  //: somewhere in it. Grouping them behind one line that says how many
  //: there were: open while they are happening, closed once the answer
  //: starts: inverts that: the work is visible as it happens, and
  //: afterwards it is one line you can open.
  //:
  //: A *new* group starts after each answer, rather than one group per turn.
  //: Order is the point of a timeline: calls the model made after writing a
  //: paragraph belong under that paragraph, and folding them back into the
  //: first group would claim they happened before it.
  let group = null;

  const groupSummary = (entry) => {
    const n = entry.count;
    const word = n === 1 ? "step" : "steps";
    setLabel(
      entry.summary,
      entry.done ? `ph:check-circle Finished ${n} ${word}` : `ph:circle-notch Working: ${n} ${word}`,
    );
  };

  const ensureGroup = () => {
    if (group) return group;
    const el = document.createElement("details");
    el.className = "agent-step agent-step-group";
    el.open = true;
    const summary = document.createElement("summary");
    summary.className = "agent-step-group-summary";
    const body = document.createElement("div");
    body.className = "agent-step-group-body";
    el.append(summary, body);
    holder.appendChild(el);
    group = { el, summary, body, count: 0, done: false };
    groupSummary(group);
    return group;
  };

  //: Closed and relabelled, not removed. The steps stay reachable, that is
  //: the difference between a summary and a spinner that ate the evidence.
  const closeGroup = () => {
    if (!group) return;
    group.done = true;
    groupSummary(group);
    group.el.open = false;
    group = null;
  };

  const foldEarlierThinking = () => {
    // Reasoning that has produced output is finished, collapse it so the
    // answer isn't buried under it, but leave it there to reopen.
    for (const step of thinkingSteps) step.el.open = false;
  };

  const startThinking = () => {
    const el = document.createElement("details");
    el.className = "agent-step step-thinking";
    el.open = true;
    const summary = document.createElement("summary");
    summary.textContent = "Thinking";
    const body = document.createElement("div");
    body.className = "thinking";
    el.append(summary, body);
    holder.appendChild(el);
    current = { kind: "thinking", el, body, raw: "" };
    thinkingSteps.push(current);
    return current;
  };

  const startAnswer = () => {
    //: **Only the step being written wears the caret.** Reported with a
    //: screenshot of an agent run: "the blinking cursor bubbles at the end of
    //: the text stayed at the end of each paragraph and didnt disappear" --
    //: every finished answer step in the run still carried one, so a five-step
    //: run showed five carets and only the last of them meant anything.
    //:
    //: `finalise()` cleared them, but only once the whole run ended. A step is
    //: finished the moment the next one starts, which is here.
    for (const step of answerSteps) step.el.classList.remove("is-streaming", "is-generating");
    foldEarlierThinking();
    //: The steps that led here fold up as the prose begins, which is exactly
    //: what Perplexity does and why its answers read as answers rather than
    //: as logs. Anything the model does *after* this opens a fresh group.
    closeGroup();
    const el = document.createElement("div");
    // **`is-streaming` is the only thing on screen that says the answer is
    // still arriving.** Reported directly: "there are no animations for chat
    // generation." The typing dots that run before the first token are
    // removed the moment one arrives (`clearPending`), and from then until
    // the turn ends the text simply grows, no caret, no cursor, nothing.
    // Every chat interface has this affordance because without it a slow
    // local model producing a token a second is indistinguishable from a
    // finished short answer.
    //
    // A class plus a CSS `::after`, not an appended element: the answer body
    // is re-rendered from scratch on every frame by `liveMarkdownRenderer`,
    // so a real node would be destroyed and recreated ~30 times a second (and
    // would land inside whatever block the markdown happened to end with).
    // A pseudo-element is untouched by that and is removed by `finalise`.
    //: **No `is-generating` on the answer itself.** Reported: "the text is
    //: right up against the overly animated borders as well", with a
    //: screenshot of an answer inside a pulsing ring *inside* a bubble
    //: already wearing one. Two rings around one sentence is one too many,
    //: and the inner one is the redundant one: the bubble's rail says the
    //: turn is working and the caret says this answer is still arriving.
    //: `is-streaming` stays, because that is the caret.
    el.className = "agent-step step-answer bubble-answer is-streaming";
    holder.appendChild(el);
    current = {
      kind: "answer",
      el,
      body: el,
      raw: "",
      render: liveMarkdownRenderer(el),
    };
    answerSteps.push(current);
    return current;
  };

  // The plan a skill declared, drawn before anything runs. The timeline has
  // always shown what happened; a skill is the first thing that knows what is
  // *meant* to happen, so it says so up front (roadmap §18).
  const plans = [];
  const startPlan = (plan) => {
    const el = document.createElement("details");
    el.className = "agent-step step-plan";
    el.open = true;
    const summary = document.createElement("summary");
    // A saved skill and a plan the model drew for this one request run through
    // the same code, so the card has to say which it is, "Skill Weekly review" is
    // a job the user set up, "Plan fix my categories" is one the model worked out
    // just now, and confusing the two makes the skill list look like it has
    // entries nobody added.
    setLabel(summary, `${plan.kind === "plan" ? "ph:compass" : "ph:lightning"} ${plan.skill}`);
    el.appendChild(summary);
    const items = [];
    if (plan.steps && plan.steps.length) {
      const list = document.createElement("ol");
      list.className = "plan-steps";
      for (const step of plan.steps) {
        const item = document.createElement("li");
        item.textContent = step;
        list.appendChild(item);
        items.push(item);
      }
      el.appendChild(list);
    }
    if (plan.tools && plan.tools.length) {
      const line = document.createElement("div");
      line.className = "plan-tools";
      line.textContent = `Tools for this run: ${plan.tools.join(", ")}`;
      el.appendChild(line);
    }
    holder.appendChild(el);
    const entry = { el, items, plan: { ...plan, states: plan.states || {} } };
    plans.push(entry);
    // Replaying a finished run: paint the states it ended with.
    for (const [index, state] of Object.entries(entry.plan.states)) {
      markStep(entry, Number(index), state.state, state.reason, state);
    }
    current = null;
    return el;
  };

  // A step's state, shown on the plan itself. The timeline records what
  // happened; this is the only place that says how far through it got.
  const markStep = (entry, index, state, reason, event = {}) => {
    const item = entry.items[index];
    if (!item) return;
    //: `attempt`/`of` ride along with the state so a replayed run shows the
    //: same "attempt 2 of 3" a live one did. They are only present on a
    //: `retrying` event, and an older saved run has neither, which
    //: `stepStateWords` renders as attempt 1 of 1 rather than as a crash.
    entry.plan.states[index] = {
      state,
      reason,
      attempt: event.attempt,
      of: event.of,
      //: The rewritten step travels with the state so a replayed run shows the
      //: instruction that actually ran, not the one that failed.
      text: state === "replanned" ? event.text : entry.plan.states[index]?.text,
    };
    item.className = `plan-step plan-step-${state}`;
    item.dataset.state = state;
    const note = item.querySelector(".plan-step-reason");
    if (note) note.remove();
    //: **A re-planned step is a different step, so the checklist says so.**
    //: The runner rewrites a step it could not finish and runs it again at
    //: the same index; leaving the old wording on screen would make the next
    //: `running` look like a repeat of a step that had already failed, with
    //: no sign that anything changed. `textContent`, never markup: this is
    //: model-written text.
    if (state === "replanned" && event.text) {
      item.textContent = event.text;
      entry.plan.steps = entry.plan.steps.map((old, i) => (i === index ? event.text : old));
    }
    //: **`retrying` says why, in the same words the activity panel uses.**
    //: Phase A's runner re-prompts a step whose contract was not met and emits
    //: this state for each attempt; without the sentence, a step being
    //: re-prompted for the third time is indistinguishable on screen from one
    //: quietly running, which is the "it ran no tools and moved on" report all
    //: over again one layer up. `stalled` gets it for the same reason: it is
    //: the state that *ends* a run, and "why did this stall?" should not need
    //: a second click.
    if (
      (state === "failed" ||
        state === "stalled" ||
        state === "retrying" ||
        state === "replanned" ||
        state === "paging") &&
      (reason || state === "retrying" || state === "replanned" || state === "paging")
    ) {
      const why = document.createElement("span");
      why.className = "plan-step-reason";
      why.textContent =
        state === "retrying" || state === "replanned" || state === "paging"
          ? `, ${stepStateWords(state, { ...event, reason })}`
          : `, ${reason}`;
      item.appendChild(why);
    }
  };

  return {
    holder,
    plan(event) {
      startPlan(event);
    },
    step(event) {
      const entry = plans.at(-1);
      if (entry) markStep(entry, event.index, event.state, event.reason, event);
      // Each step's prose is its own block. Without this, step 2's first
      // sentence lands on the end of step 1's paragraph ("…with no tags.Read
      // them.") because nothing between them closed the step.
      current = null;
    },
    failRunningStep(reason) {
      const entry = plans.at(-1);
      if (!entry) return;
      for (const [index, state] of Object.entries(entry.plan.states)) {
        if (state.state === "running") markStep(entry, Number(index), "failed", reason);
      }
    },
    // What the run actually changed, with the call that puts each one back.
    // Prose claiming something happened is exactly what this replaces.
    result(event, options = {}) {
      const changes = event.changes || [];
      //: **The verification is shown even when nothing changed**, which is
      //: most of the time: half the shipped skills are reports, and "this run
      //: changed nothing" is exactly the claim their verify block checks
      //: (Brief 13). A read-only run used to render nothing at all here, so
      //: the only evidence it had done its job was its own prose.
      const check = event.verification || null;
      if (!changes.length && !check) return;
      const box = document.createElement("div");
      box.className = "skill-result";
      box.dataset.changes = JSON.stringify(changes);
      if (check) box.dataset.verification = JSON.stringify(check);
      if (changes.length) {
        const title = document.createElement("div");
        title.className = "skill-result-title";
        title.textContent = `What changed (${changes.length})`;
        box.appendChild(title);
        for (const change of changes) box.appendChild(changeRow(change, options));
      }
      if (check) box.appendChild(verificationRow(check));
      holder.appendChild(box);
      current = null;
    },
    thinking(delta) {
      const step = current?.kind === "thinking" ? current : startThinking();
      step.raw += delta;
      step.body.textContent = step.raw;
      // The pane has its own max-height and scrollbar, so following the chat
      // is not enough: reasoning would scroll out of sight inside it.
      keepAtBottom(step.body);
    },
    answer(delta) {
      const step = current?.kind === "answer" ? current : startAnswer();
      step.raw += delta;
      step.render(step.raw);
    },
    // A tool call is a row inside the current step group, see `ensureGroup`.
    tool(node) {
      foldEarlierThinking();
      const entry = ensureGroup();
      entry.body.appendChild(node);
      entry.count += 1;
      groupSummary(entry);
      current = null; // whatever comes next begins a fresh step
    },
    //: The turn is over: whatever group is still open stops saying "Working".
    //: Called from the stream's `finally`, so it runs on an error and an
    //: abort too: a group left mid-sentence is how a stopped turn ends up
    //: looking like a running one forever.
    finish() {
      closeGroup();
      //: Any trailing progress line still in this holder goes with it. The
      //: turn's own `pending` node is removed by the stream, but a skill run
      //: replayed into a rebuilt bubble can leave one behind, and a "Writing
      //: the answer…" under a finished answer is the exact thing reported.
      for (const stale of holder.querySelectorAll(".step-pending")) stale.remove();
    },
    // Replay a saved run (reopening a conversation).
    replay(steps) {
      for (const step of steps || []) {
        if (step.kind === "plan") {
          startPlan(step);
          if (plans.at(-1)) plans.at(-1).el.open = false;
        } else if (step.kind === "result") {
          this.result(step);
        } else if (step.kind === "thinking" && step.text) {
          this.thinking(step.text);
          if (current) current.el.open = false;
          current = null;
        } else if (step.kind === "answer" && step.text) {
          const node = startAnswer();
          node.raw = step.text;
          renderMarkdown(node.body, step.text);
          //: A replayed answer has already finished. `startAnswer` builds the
          //: node in its live, mid-stream state, so without this a reloaded
          //: conversation blinks a caret at the end of every answer in it, 
          //: and, now that the two travel together, pulses the generating ring
          //: around all of them forever.
          node.el.classList.remove("is-streaming", "is-generating");
          current = null;
        } else if (step.kind === "tool") {
          //: `step` is passed through, so a replayed tool row keeps the
          //: arguments/result disclosure the live one had. Without it a
          //: reloaded conversation silently lost what each call actually did
          //:, the same turn showed less of itself the second time you looked
          //: at it, which is the shape behind "tools render fine in the chat
          //: initially but then I come back to them after reloading".
          this.tool(toolChip(step.label, step.ok !== false, step));
        }
      }
    },
    noteStep(entry) {
      record.push(entry);
    },
    // Everything the model actually said, for copying, reading aloud and the
    // history sent with the next question.
    text() {
      return answerSteps.map((s) => s.raw).join("\n\n").trim();
    },
    thinkingText() {
      return thinkingSteps.map((s) => s.raw).join("\n\n").trim();
    },
    // Re-render each prose step properly once streaming has finished.
    finalise() {
      //: The live renderer's armed paint is cancelled first: see its own
      //: `stop`. Anything the caller adds to this prose afterwards (the
      //: citation markers) would otherwise be wiped by a timer that was
      //: scheduled before the turn ended.
      for (const step of answerSteps) step.render?.stop?.();
      for (const step of answerSteps) renderMarkdown(step.body, step.raw);
      // The caret goes out with the stream that justified it. Called from
      // every exit path this timeline has, a finished turn, an error, and
      // Stop: because a caret left blinking on an answer that stopped
      // arriving is a worse lie than never having shown one.
      for (const step of answerSteps) step.el.classList.remove("is-streaming", "is-generating");
      foldEarlierThinking();
    },
    // The box to put a message into when the model produced nothing at all.
    ensureAnswerBox() {
      const step = answerSteps.at(-1) || startAnswer();
      //: **Whatever goes in here is already finished.**
      //:
      //: Reported: *"the blinker animation still shows at the end of finished
      //: responses"*, with a screenshot of the caret blinking after "The
      //: model finished without writing anything." That message is written by
      //: the app, after `finalise()` has already run, and `startAnswer` builds
      //: its node in the live, mid-stream state: a caret on a sentence that
      //: was never streaming and no later pass to take it down.
      step.el.classList.remove("is-streaming", "is-generating");
      return step.body;
    },
    // Editing an answer replaces the model's prose with the user's own, so the
    // separate prose steps collapse into the one block they typed. The
    // reasoning and tool steps around them are left alone, those record what
    // actually happened and aren't the user's to rewrite.
    replaceAnswer(markdown) {
      // Same race as `finalise`: an armed paint would put the model's prose
      // back over the text the user just typed.
      for (const step of answerSteps) step.render?.stop?.();
      for (const step of answerSteps.slice(1)) step.el.remove();
      answerSteps.length = Math.min(answerSteps.length, 1);
      const step = answerSteps[0] || startAnswer();
      step.raw = markdown;
      renderMarkdown(step.body, markdown);
      current = null;
      return step.body;
    },
    // The element answer-editing hides while its textarea is open.
    answerElement() {
      return (answerSteps.at(-1) || startAnswer()).el;
    },
    hasAnswer() {
      return answerSteps.some((s) => s.raw.trim());
    },
    // The timeline in the order it happened, for saving with the turn.
    serialise() {
      const out = [];
      //: **Groups are walked into, not over.** Tool rows used to be direct
      //: children of the holder; they are inside a `<details>` now, and a
      //: loop over `holder.children` alone would have silently stopped
      //: saving every tool call, the exact shape of the `.tool-chip-wrap`
      //: regression this function's own comment below already records.
      const walk = (parent) => {
      for (const node of parent.children) {
        if (node.classList.contains("agent-step-group")) {
          walk(node.querySelector(".agent-step-group-body") || node);
          continue;
        }
        if (node.classList.contains("step-plan")) {
          const entry = plans.find((p) => p.el === node);
          // The states go with it, so reopening a chat shows how far the run
          // got rather than an untouched plan.
          if (entry) out.push({ kind: "plan", ...entry.plan });
        } else if (node.classList.contains("skill-result")) {
          out.push({
            kind: "result",
            changes: JSON.parse(node.dataset.changes || "[]"),
            verification: JSON.parse(node.dataset.verification || "null"),
          });
        } else if (node.classList.contains("step-thinking")) {
          const step = thinkingSteps.find((s) => s.el === node);
          if (step?.raw) out.push({ kind: "thinking", text: step.raw });
        } else if (node.classList.contains("step-answer")) {
          const step = answerSteps.find((s) => s.el === node);
          if (step?.raw) out.push({ kind: "answer", text: step.raw });
        } else if (node.toolStep) {
          //: **Anything that carried its own saved form is saved**, whatever
          //: it is drawn as. The class checks below only know the shapes that
          //: existed when they were written, and a card added later, a
          //: confirmation, a proposal, a question, was silently dropped from
          //: the saved turn, which is one half of "a lot of the steps and
          //: agent process disappears when I come back to it".
          out.push(node.toolStep);
        } else if (node.classList.contains("tool-chip") || node.classList.contains("tool-chip-wrap")) {
          //: `.tool-chip-wrap` has to be matched as well as `.tool-chip`:
          //: `classList.contains` is an exact token match, so once a row that
          //: touched something got wrapped with its chips, this branch stopped
          //: seeing it at all and the call vanished from the reopened chat.
          out.push(
            node.toolStep || {
              kind: "tool",
              label: node.textContent,
              ok: !node.classList.contains("tool-chip-error"),
            },
          );
        }
      }
      };
      walk(holder);
      return out;
    },
  };
}

// An assistant bubble: an avatar, the step timeline, and a matching-records slot.
function addAssistantBubble() {
  clearChatEmptyState();
  const bubble = document.createElement("div");
  bubble.className = "msg assistant";

  // The app's own emblem stands in as the assistant's avatar.
  const label = document.createElement("div");
  label.className = "msg-role msg-role-assistant";
  const avatar = document.createElement("span");
  avatar.className = "msg-avatar";
  avatar.setAttribute("aria-hidden", "true");
  const name = document.createElement("span");
  name.textContent = assistantLabel();
  label.append(avatar, name);
  bubble.appendChild(label);
  // NB: the emblem is drawn after the bubble is in the DOM, p5 can't size a
  // canvas inside a detached element, which left the avatar blank until some
  // later render happened to redraw it.

  // Every step, reasoning, tool calls, prose, lands here in event order.
  const stepsHolder = document.createElement("div");
  stepsHolder.className = "agent-steps";

  const recordsHolder = document.createElement("div");
  // Same "grounded in" chip strip the Ask tab shows (renderAnswerGrounding): 
  // that function only ever wrote to the Ask tab's single fixed element, so a
  // Chat-tab notes question got the "grounding" SSE event from the backend
  // (it's emitted for any non-conversational /chat/stream call, not just the
  // Ask box) but nothing ever rendered it. One holder per bubble, since Chat
  // has many turns where Ask has one answer.
  const groundingHolder = document.createElement("div");
  groundingHolder.className = "answer-grounding hidden";

  bubble.append(stepsHolder, recordsHolder, groundingHolder);
  $("chat-messages").appendChild(bubble);
  renderEmblem(avatar, 20); // now attached, so p5 can measure and draw
  chatScrollToEnd();
  const timeline = agentTimeline(stepsHolder);
  return { bubble, stepsHolder, recordsHolder, groundingHolder, timeline };
}

// One "the AI did something" chip in a bubble (Wave G).
// One line of a skill's result: what changed, a way to see it, and, where
// an inverse exists: a way to put it back. The undo is a tool call the
// server handed us, run through the same endpoint the confirm button uses.
function changeRow(change, options = {}) {
  const row = document.createElement("div");
  row.className = "skill-change";
  const label = document.createElement("span");
  label.className = "skill-change-label";
  // `setLabel`, not `.textContent`: a tool's own `label` carries this app's
  // "ph:icon-name Rest of the text" convention (see `_merge_categories` and
  // friends in ai/tools/categories.py, which write exactly that shape), and
  // assigning it raw printed the icon spec as visible text, reported with
  // a screenshot of three agent rows all reading "ph:folder Merged …".
  setLabel(label, change.label || change.tool);
  row.appendChild(label);

  if (change.note_id && change.tool === "delete_note") {
    // A binned note is not in the browse list flashEntry looks in, it is
    // reachable only through the Library's own Bin filter until it is
    // cleared or restored. See flashLibraryItem's own comment.
    row.appendChild(
      smallButton("View in bin", "Show this note in the recycle bin", () =>
        flashLibraryItem("archived", change.note_id)
      )
    );
  } else if (change.note_id) {
    row.appendChild(
      smallButton("View", "Show this note", () => {
        switchTab("notes");
        showNotesSection("browse"); // focusing inside a hidden section does nothing
        flashEntry(change.note_id);
      })
    );
  }
  // The other half of "take me to the thing the agent just changed", the
  // groundwork (`agent._change_document_id`) has resolved a document's real
  // id on every write since §21, but this was the one place that data never
  // reached a button: `create_document`'s own change events carried it and
  // nothing here ever read it.
  if (change.document_id) {
    row.appendChild(
      smallButton("View", "Open this document", () => openDocumentFromNote(change.document_id))
    );
  }
  // ROADMAP.md Tier 2 §13: the same View button, extended to the two kinds
  // that never had a `_change_*_id` resolver at all: a reminder set or
  // completed this turn, and a category a note landed in.
  if (change.reminder_id) {
    row.appendChild(
      smallButton("View", "Show this reminder", () => flashReminder(change.reminder_id))
    );
  }
  if (change.category_name) {
    row.appendChild(
      smallButton("View", "Show this category", () => flashCategory(change.category_name))
    );
  }
  if (change.undo) {
    const undo = smallButton("Undo", "Put this back the way it was", async () => {
      undo.disabled = true;
      try {
        const result = await apiJson("/chat/tools/execute", {
          method: "POST",
          body: JSON.stringify({
            name: change.undo.tool,
            arguments: change.undo.arguments,
          }),
        });
        if (result && result.error) throw new Error(result.error);
        row.classList.add("skill-change-undone");
        setLabel(label, `${change.label || change.tool}, undone`);
        undo.remove();
        loadEntries();
      } catch (error) {
        undo.disabled = false;
        toast(error.message || "Couldn't undo that.", true);
      }
    });
    row.appendChild(undo);
  }
  return row;
}

//: **The live action line: which notes a tool call actually reached for.**
//:
//: Asked for: "is it also possible to have live action lines show on the chat
//: ui, to show and visually show as the ai accesses specific notes, files and
//: stuff??"
//:
//: The transcript already said *that* a tool ran, and hid what it returned in
//: a JSON disclosure. What it could not say is *which note*, and an id inside
//: a blob of JSON is not something a person can act on, which is the same
//: complaint that produced the command palette's note links.
//:
//: The backend reads these from the tool's own result rather than from the
//: arguments it was called with, so this row says what happened rather than
//: what the model asked for. Chips open the note, like every other note chip
//: in this app; nothing renders when a call touched nothing.
// Notes and documents share an id space only by accident, id 12 is a
// different object in each table, so the chip has to carry the kind the
// backend decided (`_touched_kind`) and route on it. Clicking a document
// chip through `flashEntry` would open an unrelated note, or nothing.
const TOUCHED_KINDS = {
  note: { icon: "ph:note", title: "Open this note", open: (id) => flashEntry(id) },
  document: {
    icon: "ph:file-text",
    title: "Open this document",
    open: (id) => openDocumentFromNote(id),
  },
  //: A mind map the turn read or built (MINDMAP_PLAN.md §5 item 12: "the chat
  //: transcript"). Deliberately a row in *this* table rather than a new panel:
  //: the four map tools already report what they touched through the same
  //: `touched` channel every other tool uses, so a map becomes a chip in the
  //: line that already exists. `preview: false` because a map's preview is a
  //: picture, not markdown: `toolPreviewBody` fetches `/entries/{id}` and
  //: renders it, which for a board would render the string "# My map".
  map: {
    icon: "ph:tree-structure",
    title: "Open this mind map",
    open: (id) => openWhiteboardBoard(id),
    preview: false,
  },
};

//: **A tool result as things with actions, one renderer per kind** (PLAN.md
//: §4 A1). `TOUCHED_KINDS` above covers the two kinds the backend's `touched`
//: list has ever carried; `cards.py` now sends five, because a file, a board
//: and a reminder are equally openable and had no representation at all, a
//: `search_files` result was a JSON blob behind a disclosure, and every
//: reminder the agent set was a sentence.
//:
//: Deliberately the *same* chip-opens-a-card interaction the touched row
//: already had, rather than a second strip beside it: the chip is the handle
//: and the panel it opens is the card, with that kind's real actions under
//: it. `toolTouchedRow` is now a thin adapter onto this, so an old saved
//: transcript (which has only `touched`) renders through exactly one code
//: path, not a fork that ages differently.
//:
//: Nothing here interpolates user text into markup, every label goes through
//: `setLabel`/`textContent`, and the note and document bodies go through the
//: app's own markdown renderer, the same as everywhere else.
const CARD_KINDS = {
  note: {
    icon: "ph:note",
    title: "Open this note",
    open: (item) => flashEntry(item.id),
    actions: (item) => [
      smallButton("ph:pencil-simple Edit", "Open this note with the editor on", () => {
        //: The same two steps the note list's own Edit does, in the order that
        //: works from here: `flashEntry` switches tab and re-renders, and
        //: `editingId` is what that render reads to open the editor. Set it
        //: first and the jump would clear it.
        flashEntry(item.id);
        editingId = item.id;
        renderEntries();
      }),
    ],
  },
  document: {
    icon: "ph:file-text",
    title: "Open this document",
    open: (item) => openDocumentFromNote(item.id),
  },
  file: {
    icon: "ph:paperclip",
    title: "Find this file in the Library",
    //: `focusLibraryFile` (library.js) picks Images or Files from the url and
    //: searches for the name, the three steps this would otherwise be.
    open: (item) => focusLibraryFile(item.label, item.url || item.label),
    actions: (item) =>
      isImageCardUrl(item.url)
        ? [
            smallButton("ph:image View", "Open the full-size image", () =>
              openLightbox([{ filename: item.label, getUrl: () => mediaSrc(item.url) }], 0),
            ),
          ]
        : [],
    //: No fetch: a file's own reading is already on the card as `snippet`
    //: (the OCR/caption line `search_files` returned), and re-reading a
    //: scanned PDF to show one line of it would be the expensive way to say
    //: the same thing. An image gets the lightbox instead, which is the real
    //: full-size view rather than a thumbnail.
    preview: (item, holder) => cardTextPreview(item, holder, "Nothing was read out of this file."),
  },
  board: {
    icon: "ph:squares-four",
    title: "Open this board",
    //: `id` is genuinely nullable here and that is not sloppiness: `null` is
    //: the default board, which is what every whiteboard tool means when it
    //: is given no `board_id` (see `_whiteboard_board_filter` in
    //: ai/tools/whiteboard.py). `?? null` keeps that meaning intact.
    open: (item) => openWhiteboardBoard(item.id ?? null),
    preview: (item, holder) => cardTextPreview(item, holder, "An empty board."),
  },
  //: A mind map the turn read or built (MINDMAP_PLAN.md §5 item 12). Opens
  //: the board; its "preview" is one line, because a board's Entry content is
  //: the single line `# My map` and rendering that as the map would look like
  //: an empty map. `cards.py` sends these as `board`, this entry covers the
  //: `touched` fallback, which names the kind `map`.
  map: {
    icon: "ph:tree-structure",
    title: "Open this mind map",
    open: (item) => openWhiteboardBoard(item.id ?? null),
    preview: (item, holder) => cardTextPreview(item, holder, "A mind map: open it to see the tree."),
  },
  reminder: {
    icon: "ph:alarm",
    title: "Go to Reminders",
    open: () => switchTab("reminders"),
    actions: (item) =>
      item.done
        ? []
        : [
            smallButton("ph:check-circle Mark done", "Complete this reminder", async () => {
              try {
                await apiJson(`/reminders/${item.id}`, {
                  method: "PUT",
                  body: JSON.stringify({ done: true }),
                });
                item.done = true;
                toast("Reminder marked done.");
                //: Only when the tab is actually showing them, `loadReminders`
                //: re-renders a list that is not on screen otherwise, and the
                //: dashboard's own poll will pick the change up regardless.
                if (localStorage.getItem("activeTab") === "reminders") loadReminders();
              } catch (error) {
                toast(error?.message || "That reminder could not be updated.");
              }
            }),
          ],
    preview: (item, holder) => {
      holder.replaceChildren();
      const line = document.createElement("div");
      line.className = "tool-preview-body";
      const due = item.due_at ? new Date(item.due_at) : null;
      line.textContent = due && !Number.isNaN(due.valueOf())
        ? `${item.done ? "Done" : "Due"} ${due.toLocaleString()}`
        : item.done
          ? "Done"
          : "No due date.";
      holder.appendChild(line);
    },
  },
};

//: Which file urls have a full-size view worth offering. A local test rather
//: than library.js's `isImageUrl`, which is not on `window`, duplicating one
//: regex is cheaper than widening another file's surface, and this list only
//: has to be right about what the lightbox can show.
function isImageCardUrl(url) {
  return /\.(png|jpe?g|jfif|gif|webp|bmp|svg|avif|heic|heif|tiff?)$/i.test(String(url || ""));
}

//: The preview for a kind whose text the card already carries. `empty` is
//: said out loud rather than left blank: a panel that opens on nothing reads
//: as a failure to load, which is a different fact from "this file had no
//: text in it".
function cardTextPreview(item, holder, empty) {
  holder.replaceChildren();
  const body = document.createElement("div");
  body.className = "tool-preview-body";
  body.textContent = item.snippet || empty;
  if (!item.snippet) body.classList.add("muted");
  holder.appendChild(body);
}

//: **What the tool touched, shown rather than named.** Asked for: "the chat
//: and agent should be the ultimate notebook handler, drafting and previewing
//: notes … showing rendered note previews then user can edit".
//:
//: A chip alone could only take you away from the conversation: press it and
//: you are in the Notes tab, having lost the answer you were reading. So the
//: chip *opens the thing in place*, rendered with the app's own markdown
//: renderer, with Open and Edit under it, and pressing it again closes it.
//: Leaving is now a decision rather than the only option.
//:
//: Fetched on demand, never carried in the tool event: a replayed transcript
//: (a conversation reopened days later) then previews the note as it is now,
//: not as it was, and a turn that touched six notes does not put six note
//: bodies into the message that stores it.
async function toolPreviewBody(item, holder) {
  holder.replaceChildren(typingDots("Loading…"));
  try {
    if (item.kind === "document") {
      const doc = await apiJson(`/documents/${item.id}`);
      holder.replaceChildren();
      const title = document.createElement("strong");
      title.textContent = doc.title || `Document #${item.id}`;
      const body = document.createElement("div");
      body.className = "tool-preview-body";
      renderMarkdown(body, doc.content || "");
      holder.append(title, body);
    } else {
      const entry = await apiJson(`/entries/${item.id}`);
      holder.replaceChildren();
      const body = document.createElement("div");
      body.className = "tool-preview-body";
      renderMarkdown(body, entry.content || "");
      holder.appendChild(body);
    }
  } catch (error) {
    holder.replaceChildren();
    const failed = document.createElement("p");
    failed.className = "muted";
    //: The real reason, not a euphemism: a deleted note and an unreachable
    //: backend are different problems and only one of them is worth retrying.
    failed.textContent = error?.message || "That note could not be loaded.";
    holder.appendChild(failed);
  }
}

//: One card. `spec` is the `CARD_KINDS` entry for its kind, so the actions
//: under it are that kind's own: Open plus Edit for a note, Open plus View
//: for an image, Open plus Mark done for a reminder. Open is the one every
//: kind has, which is why it is built here rather than in each entry.
function toolPreviewPanel(item, spec) {
  const panel = document.createElement("div");
  panel.className = "tool-preview";
  const holder = document.createElement("div");
  holder.className = "tool-preview-content";
  const actions = document.createElement("div");
  actions.className = "row tool-preview-actions";
  actions.appendChild(
    smallButton("ph:arrow-square-out Open", spec.title, () => spec.open(item)),
  );
  for (const button of spec.actions?.(item) || []) actions.appendChild(button);
  panel.append(holder, actions);
  //: A kind with no `preview` of its own is one whose body has to be fetched
  //:, notes and documents, which are read fresh so a conversation reopened
  //: days later previews the note as it is *now*.
  (spec.preview || toolPreviewBody)(item, holder);
  return panel;
}

//: The chip strip under a tool call. Takes card items that already carry
//: their `kind`, so both callers: the typed `cards` envelopes and an old
//: transcript's `touched` list: end up in the same renderer.
function toolCardChips(items) {
  const row = document.createElement("div");
  row.className = "tool-touched-wrap";
  const chips = document.createElement("div");
  chips.className = "row tool-touched";
  const previews = document.createElement("div");
  previews.className = "tool-previews";
  for (const item of items) {
    // Older transcripts (stored before `kind` existed) have notes only.
    const spec = CARD_KINDS[item.kind] || CARD_KINDS.note;
    const chip = document.createElement("button");
    chip.type = "button";
    chip.className = "chip result-reason-chip result-reason-connected tool-touched-chip";
    //: The label is the thing's own first words, straight off the tool event,
    //: so it is Markdown and is rendered as such. 120 rather than a tight cut:
    //: the strip already ellipsises in CSS, and cutting here would flatten
    //: every label long enough to need it.
    setNoteLabel(chip, spec.icon, item.label || `#${item.id}`, 120);
    //: A kind with `preview: false` opens rather than expands, because there
    //: is nothing sensible to inline. A map's content as an Entry is the
    //: single line `# My map`, so the in-place preview every other kind gets
    //: would show that string and call it the map, worse than no preview,
    //: because it looks like the map is empty.
    if (spec.preview === false) {
      chip.title = spec.title;
      chip.addEventListener("click", (clickEvent) => {
        clickEvent.stopPropagation();
        spec.open(item.id);
      });
      chips.appendChild(chip);
      continue;
    }
    chip.setAttribute("aria-expanded", "false");
    chip.title = `${spec.title}: press to preview it here`;
    let panel = null;
    chip.addEventListener("click", (clickEvent) => {
      clickEvent.stopPropagation();
      if (panel) {
        panel.remove();
        panel = null;
        chip.setAttribute("aria-expanded", "false");
        chip.classList.remove("active");
        return;
      }
      panel = toolPreviewPanel(item, spec);
      previews.appendChild(panel);
      chip.setAttribute("aria-expanded", "true");
      chip.classList.add("active");
    });
    chips.appendChild(chip);
  }
  row.append(chips, previews);
  return row;
}

//: The typed envelopes `ai/cards.py` sends: `[{kind, items:[…]}]`, already in
//: kind order and already capped per kind. Flattened onto one strip on
//: purpose: a tool call that touched a note, its board and a reminder is one
//: action, and three headed sections would make it read as three.
function toolCardsRow(cards) {
  if (!Array.isArray(cards)) return null;
  const items = [];
  for (const group of cards) {
    if (!group || !Array.isArray(group.items)) continue;
    for (const item of group.items) {
      if (item && (item.id !== undefined || group.kind === "board")) {
        items.push({ ...item, kind: group.kind });
      }
    }
  }
  return items.length ? toolCardChips(items) : null;
}

function toolTouchedRow(touched) {
  if (!Array.isArray(touched) || !touched.length) return null;
  return toolCardChips(touched);
}

//: What `serialise` needs to write this row back out, parked on the node
//: itself. The transcript is rebuilt by walking the DOM, and a chip's
//: arguments, result summary and touched items have no representation there, 
//: scraping `textContent` recovered the label and lost everything else, so a
//: reopened conversation showed less of itself the second time you looked at
//: it. Stored as a property rather than a `data-` attribute because a result
//: summary runs to 4000 characters and does not belong in an attribute.
function markToolStep(node, step) {
  node.toolStep = step;
  return node;
}

function toolChip(label, ok = true, event = null) {
  const step = {
    kind: "tool",
    label,
    ok,
    arguments: event?.arguments || null,
    result_summary: event?.result_summary || null,
    touched: event?.touched || null,
    //: Saved with the turn, so a reopened conversation gets its cards back, 
    //: the same reason `touched` is here. Both are kept: a transcript written
    //: before `cards` existed still has `touched`, and `cardsRow` below falls
    //: back to it rather than showing a call that touched things as one that
    //: touched nothing.
    cards: event?.cards || null,
  };
  //: **Cards first, `touched` as the fallback.** They describe the same call,
  //: so drawing both would list every note twice; `cards` is the superset
  //: (five kinds against two), and `touched` is what an old saved turn has.
  const cardsRow = () => toolCardsRow(event?.cards) || toolTouchedRow(event?.touched);
  if (event && (event.arguments || event.result_summary)) {
    const details = document.createElement("details");
    details.className = `tool-chip ${ok ? "" : "tool-chip-error"}`.trim();
    
    const summary = document.createElement("summary");
    setLabel(summary, label);
    details.appendChild(summary);

    const body = document.createElement("div");
    body.className = "tool-chip-body";
    if (event.arguments && Object.keys(event.arguments).length > 0) {
      const argsPre = document.createElement("pre");
      argsPre.className = "tool-chip-args";
      argsPre.textContent = JSON.stringify(event.arguments, null, 2);
      body.appendChild(argsPre);
    }
    if (event.result_summary) {
      const resPre = document.createElement("pre");
      resPre.className = "tool-chip-result";
      resPre.textContent = event.result_summary;
      body.appendChild(resPre);
    }
    details.appendChild(body);
    //: Outside the disclosure on purpose: the whole point is that it is
    //: visible while the call is happening, without a click.
    const touched = cardsRow();
    if (touched) {
      const wrap = document.createElement("div");
      wrap.className = "tool-chip-wrap";
      wrap.append(details, touched);
      return markToolStep(wrap, step);
    }
    return markToolStep(details, step);
  }

  const item = document.createElement("div");
  item.className = `tool-chip ${ok ? "" : "tool-chip-error"}`.trim();
  setLabel(item, label);
  const touched = cardsRow();
  if (touched) {
    const wrap = document.createElement("div");
    wrap.className = "tool-chip-wrap";
    wrap.append(item, touched);
    return markToolStep(wrap, step);
  }
  return markToolStep(item, step);
}

// A destructive tool call parked for approval (Wave G). Nothing has
// happened yet: Confirm actually runs it via /chat/tools/execute.
function renderToolConfirm(holder, event) {
  const card = document.createElement("div");
  card.className = "tool-confirm";
  const text = document.createElement("p");
  setLabel(text, `ph:warning The AI wants to: ${event.label || event.name}`);
  
  const contentArea = document.createElement("div");
  
  if (event.name === "edit_note" && event.arguments.content) {
    // async fetch for diff
    apiJson(`/entries/${event.arguments.note_id}`).then(res => {
      const oldContent = res.content || "";
      const newContent = event.arguments.content;
      if (oldContent !== newContent) {
        contentArea.innerHTML = `<div class="diff-viewer">
          <div class="diff-removed">- ${escapeHtml(oldContent)}</div>
          <div class="diff-added">+ ${escapeHtml(newContent)}</div>
        </div>`;
      }
    }).catch(() => {});
  }

  const row = document.createElement("div");
  row.className = "row";
  row.appendChild(
    smallButton(
      "Confirm",
      "Run this action",
      async () => {
        try {
          const result = await apiJson("/chat/tools/execute", {
            method: "POST",
            body: JSON.stringify({ name: event.name, arguments: event.arguments }),
          });
          card.replaceWith(toolChip(`ph:check-circle ${result.label || event.label || event.name}`));
          toast("Done: check Activity for the audit trail.");
          refreshAfterToolChanges();
        } catch (error) {
          toast(error.message, true);
        }
      },
      false
    )
  );
  row.appendChild(
    smallButton("Cancel", "Don't do this", () => {
      card.replaceWith(toolChip("ph:x Cancelled: nothing was changed."));
    })
  );
  card.append(text, contentArea, row);
  holder.appendChild(card);
  chatScrollToEnd();
}

// The model would like to remember something about you (§39B).
//
// This card is the whole point of the change behind it. `save_user_preference`
// used to write a standing instruction straight into every future system
// prompt: no confirmation, no notice, and the only trace was a list in
// Settings nobody had a reason to open. A model that over-read one sentence
// ("use British English for this one, actually") gave itself a permanent rule
// its user never agreed to, and would then keep obeying it for weeks.
//
// So the tool now *proposes*: the row is written inactive and flagged, it is
// excluded from the prompt, and this card is where it becomes real. Declining
// keeps the row (switched off) on purpose, the tool's duplicate check reads
// every preference, so a kept "no" is what stops the model suggesting the same
// thing again an hour later.
function renderMemoryProposal(holder, proposal) {
  const card = document.createElement("div");
  card.className = "tool-confirm memory-proposal";

  const text = document.createElement("p");
  setLabel(text, "ph:brain Remember this for next time?");

  const quote = document.createElement("blockquote");
  quote.className = "memory-proposal-text";
  quote.textContent = proposal.content;

  const note = document.createElement("p");
  note.className = "muted";
  note.textContent =
    "Saved preferences are added to the AI's instructions in every later " +
    "conversation. Nothing is in force until you say yes.";

  const row = document.createElement("div");
  row.className = "row";

  let answered = false;
  const answer = async (accept) => {
    if (answered) return;
    answered = true;
    try {
      await apiJson(`/memory/${proposal.id}/answer`, {
        method: "POST",
        body: JSON.stringify({ accept }),
      });
    } catch (error) {
      answered = false;
      toast(error.message, true);
      return;
    }
    card.replaceWith(
      toolChip(
        accept
          ? `ph:check-circle Remembered: “${proposal.content}”`
          : "ph:x Not remembered."
      )
    );
    // The Settings list is the other view of the same row; if it happens to
    // be open behind the chat, leaving it stale shows a pending question the
    // user has already answered.
    if (typeof renderMemorySettings === "function") renderMemorySettings().catch(() => {});
  };

  row.appendChild(
    smallButton("Remember it", "Add this to the AI's standing instructions", () => answer(true), false)
  );
  row.appendChild(smallButton("No thanks", "Don't save this preference", () => answer(false)));

  card.append(text, quote, note, row);
  holder.appendChild(card);
  chatScrollToEnd();
}

// The agent stopped to ask something. Its options become buttons, and picking
// one sends that text as the next message, so the answer travels through the
// ordinary conversation history rather than through any parked server state.
// Nothing to expire, nothing lost on a reload, and the exchange reads back in
// the saved chat like the short question-and-answer it was.
function renderAgentQuestion(holder, event) {
  const card = document.createElement("div");
  card.className = "tool-confirm agent-ask";
  const text = document.createElement("p");
  setLabel(text, `ph:question ${event.question}`);
  const row = document.createElement("div");
  row.className = "row agent-ask-options";

  let answered = false;
  const answer = (choice) => {
    if (answered) return; // double-click, or Enter on a focused button
    answered = true;
    // Replace the card rather than leave dead buttons: the exchange is
    // already about to appear as a normal user message below.
    card.replaceWith(toolChip(`ph:question ${event.question} → ${choice}`));
    sendChatMessage(choice);
  };

  for (const option of event.options || []) {
    row.appendChild(smallButton(option, `Answer: ${option}`, () => answer(option), false));
  }
  const note = document.createElement("p");
  note.className = "muted";
  note.textContent = "Or type your own answer below.";
  card.append(text, row, note);
  holder.appendChild(card);
  chatScrollToEnd();
}

// After the AI changes data, every list on screen may be stale.
function refreshAfterToolChanges() {
  loadEntries().catch(() => {});
  loadReminders().catch(() => {});
  loadMostUsed();
}

//: **One Sources panel, the way every serious answer surface has one.**
//:
//: Reported: *"semantic search and other used notes dont show up in the chat
//: and are not accessible"*, and, of the retrieval line, *"if it says read
//: 9 notes or smth, it should probably show as a better log."*
//:
//: The evidence was there and scattered. Retrieved notes went into a
//: `<details>` whose summary was a sentence; files the agent opened went
//: nowhere at all, because `search_files`/`read_file` are tools and tool rows
//: are a log of *actions*, not a list of *sources*; web pages the same. So a
//: turn that read four files and two notes showed two of the six, under a
//: heading that did not say the word "sources".
//:
//: This is the one place that answers "what is this based on", grouped by
//: kind with a count per group, every row openable. Perplexity's panel is the
//: reference and the reason is not fashion: a reader checking an answer wants
//: the *set* of things it drew on, and a chronological log of calls is the
//: wrong shape for that question even when it contains the same facts.
//:
//: It is built from what already arrived, nothing here re-fetches, and
//: nothing is invented: a source appears because an event named it.
const CHAT_SOURCE_GROUPS = [
  { key: "note", icon: "ph:note", one: "note", many: "notes" },
  { key: "document", icon: "ph:file-text", one: "document", many: "documents" },
  { key: "file", icon: "ph:paperclip", one: "file", many: "files" },
  //: A map the turn read or wrote (MINDMAP_PLAN.md §5 item 12). Its icon has
  //: to be listed here as well as in `TOUCHED_KINDS`, because the Sources
  //: panel reads *this* table for the glyph and the count line, a kind
  //: missing from it falls back to `ph:note`, which is how a new kind ends up
  //: looking like it works while calling itself a note.
  { key: "map", icon: "ph:tree-structure", one: "mind map", many: "mind maps" },
  { key: "web", icon: "ph:globe", one: "web page", many: "web pages" },
];

//: Which tools produce a *source* rather than a change, and what kind each
//: one yields. Read off the tool name because that is the only thing the
//: event carries that says what was consulted, the label is prose and the
//: result is bounded (§R5 item 4), so neither can be parsed for this.
const SOURCE_TOOLS = {
  search_files: "file",
  read_file: "file",
  read_url: "web",
  web_search: "web",
};

//: Turn every control inside a rendered fragment into inert markup, keeping
//: its text and its classes. Used where a rendered preview is placed inside a
//: card that is itself clickable: the preview should still *look* like the
//: note, and must not contain a second thing to press.
function deactivateControls(root) {
  for (const node of root.querySelectorAll("a, button, input, [tabindex]")) {
    if (node.tagName === "INPUT") {
      node.disabled = true;
      node.tabIndex = -1;
      continue;
    }
    const flat = document.createElement("span");
    flat.className = node.className;
    while (node.firstChild) flat.appendChild(node.firstChild);
    node.replaceWith(flat);
  }
}

function chatSourcesFrom({ meta, toolEvents, touched }) {
  const seen = new Set();
  const sources = [];
  const add = (source) => {
    const key = `${source.kind}:${source.id}`;
    if (!source.label || seen.has(key)) return;
    seen.add(key);
    sources.push(source);
  };
  //: One line of the note itself, so a card says what it *is* rather than
  //: only what it is called. Asked for: "dropdown previews".
  const preview = (text) => {
    const flat = String(text || "").replace(/\s+/g, " ").trim();
    return flat.length > 180 ? `${flat.slice(0, 180)}…` : flat;
  };
  for (const entry of meta?.raw_results || []) {
    const label = noteLabel(entry, 60);
    //: A note has no title, so its label *is* its opening words, which means
    //: the preview has to start where the label stopped, or the card prints
    //: the same sentence twice (measured: it did).
    const flat = String(entry.content || "").replace(/\s+/g, " ").trim();
    const head = label.replace(/…$/, "");
    //: The label is elided at 60 characters, which usually lands mid-word, so
    //: the remainder starts mid-word too, and the card read "ling and why it
    //: matters for gradients." (measured, in a screenshot). Dropping the
    //: partial first word costs nothing and is the difference between a
    //: preview and a typo.
    const rest = flat.startsWith(head)
      ? flat.slice(head.length).replace(/^\S*\s+/, "")
      : flat;
    add({
      kind: "note",
      id: entry.id,
      label,
      snippet: preview(rest),
      //: The note itself rides along, so the card can show its picture and its
      //: attached files rather than only a line of its text. Reported: "the
      //: sources in the chat responses dont render inline md, images or files."
      entry,
      open: () => flashEntry(entry.id),
    });
  }
  for (const item of touched || []) {
    const opener = TOUCHED_KINDS[item.kind] || TOUCHED_KINDS.note;
    //: A touched row carries an id and a label and nothing else, but the note
    //: behind it is already loaded, so the card need not be the poorer for it.
    //: A map is excluded from that lookup along with a document: its Entry
    //: content is the single line `# My map`, so "one line of the thing
    //: itself" would print the title a second time as its own preview.
    const known =
      item.kind === "document" || item.kind === "map"
        ? null
        : (typeof allEntries !== "undefined" ? allEntries : []).find(
            (row) => row.id === item.id
          ) || null;
    add({
      //: The kind is carried through rather than collapsed to note/document,
      //: so a map's source card gets the map icon and opens the board. It used
      //: to be a two-way ternary, which meant every kind added later silently
      //: became a note: the shape that makes a new kind look like it works.
      kind: item.kind === "document" || item.kind === "map" ? item.kind : "note",
      id: item.id,
      label: item.label,
      snippet: known ? preview(String(known.content || "").replace(/\s+/g, " ")) : "",
      entry: known,
      open: () => opener.open(item.id),
    });
  }
  for (const event of toolEvents || []) {
    const kind = SOURCE_TOOLS[event?.tool || event?.name];
    if (!kind || event.ok === false) continue;
    //: **The real rows, when the backend sent them.** `event.sources`
    //: (agent.py's `_tool_sources`) carries a title, an address and a line of
    //: the page for every result a read tool actually consulted, which is
    //: what a card, a preview and a working link all need and what the prose
    //: label alone could never provide.
    const rows = Array.isArray(event.sources) ? event.sources : [];
    if (rows.length) {
      for (const row of rows) {
        add({
          kind,
          id: row.url || `${event.tool}-${row.title}`,
          label: row.title || row.url,
          snippet: preview(row.snippet),
          url: row.url || "",
        });
      }
      continue;
    }
    //: The fallback for a tool that named no rows: its own label, minus the
    //: icon token. Still better than dropping the source entirely, it says
    //: the answer read *something* outside the notebook.
    const label = String(event.label || "").replace(/^ph:[\w-]+\s*/, "");
    add({ kind, id: `${event.tool || event.name}-${sources.length}`, label, snippet: "" });
  }
  return sources;
}

//: The address a card shows under its title, the host, not the whole URL.
//: "arxiv.org" is what tells a reader whether to trust a source; the path is
//: forty characters saying the same thing less legibly.
function sourceHost(url) {
  try {
    return new URL(url).hostname.replace(/^www\./, "");
  } catch {
    return "";
  }
}

//: **The Sources panel: cards, previews and real links.**
//:
//: Reported twice: *"improve the ui of the sources as well in the chat"* and
//: then, specifically, *"ui and usability, what is shown about the sources,
//: dropdown previews, hyperlinks etc."*
//:
//: It was a list of one-line strings: no preview, no address, and, for
//: anything off the web, nothing clickable at all, because the tool events
//: never carried a URL to click (fixed in agent.py's `_tool_sources`). What a
//: reader wants from this panel is the same three things every search result
//: in the world shows: what it is, where it came from, and enough of it to
//: judge whether to open it.
//:
//: Numbered, because the numbers are what make a citation mean something: a
//: card is "[3] arxiv.org", so an answer that says "[3]" has somewhere to
//: point. A web card is a real `<a href>`, middle-click, copy link address
//: and open-in-new-tab all work, which no button can offer.
function chatSourcesPanel(input) {
  //: `input.sources` when the caller has already built the list, so the
  //: numbers on these rows are the same numbers the inline citations used.
  //: Two derivations of "the same" order is how they drift apart, which is
  //: what INBOX 81's second half is about.
  const sources = input.sources || chatSourcesFrom(input);
  if (!sources.length) return null;
  const details = document.createElement("details");
  details.className = "chat-sources";
  const summary = document.createElement("summary");
  summary.className = "chat-sources-summary";
  //: The heading counts by kind, "4 notes · 2 files", rather than saying
  //: "6 sources". A reader deciding whether to open this wants to know what
  //: is in it, and the breakdown is the same length as the total was.
  const counts = CHAT_SOURCE_GROUPS.map((g) => {
    const n = sources.filter((s) => s.kind === g.key).length;
    return n ? `${n} ${n === 1 ? g.one : g.many}` : null;
  }).filter(Boolean);
  const mode = input.meta?.search_mode;
  const how = mode && mode !== "none" ? ` · ${SEARCH_MODE_LABELS[mode] || mode}` : "";
  setLabel(summary, `ph:books Sources: ${counts.join(" · ")}${how}`);
  summary.title = "What this answer drew on, click to see each source";
  details.appendChild(summary);

  const body = document.createElement("div");
  body.className = "chat-sources-body";
  const grid = document.createElement("div");
  grid.className = "chat-sources-grid";
  const icons = Object.fromEntries(CHAT_SOURCE_GROUPS.map((g) => [g.key, g.icon]));
  sources.forEach((source, index) => {
    //: Three shapes, one card. A web source is an anchor, a local one that
    //: can be opened is a button, and one that can be neither is a plain
    //: block: because a control that does nothing when pressed is worse
    //: than no control, which this app has been told before.
    let card;
    if (source.url) {
      card = document.createElement("a");
      card.href = source.url;
      card.target = "_blank";
      //: `noopener` is not optional on a target=_blank link to a page this
      //: app did not write: without it the opened page gets a handle on this
      //: window and can navigate it.
      card.rel = "noopener noreferrer";
      card.title = source.url;
    } else if (source.open) {
      card = document.createElement("button");
      card.type = "button";
      card.title = "Open this";
      card.addEventListener("click", source.open);
    } else {
      card = document.createElement("div");
    }
    card.className = `chat-source-card${source.url || source.open ? " is-openable" : ""}`;
    const head = document.createElement("span");
    head.className = "chat-source-head";
    const number = document.createElement("span");
    number.className = "chat-source-index";
    number.textContent = String(index + 1);
    const title = document.createElement("span");
    title.className = "chat-source-title";
    setLabel(title, `${icons[source.kind] || "ph:note"} ${source.label}`);
    head.append(number, title);
    card.appendChild(head);
    //: **A source card is a note preview, and every other note preview in this
    //: app renders.** Reported: *"the sources in the chat responses dont render
    //: inline md, images or files etc."*, the snippet was `textContent`, so a
    //: note reading `**Due Friday**: see ![](/media/x.png)` printed its own
    //: asterisks and the literal text of an image it was holding.
    //:
    //: Three things, in the order the eye wants them: the picture (embedded or
    //: attached: `noteRowImage`, dashboard.js, which exists because an
    //: attached image appears nowhere in the note's markdown), the text with
    //: its markdown rendered, and a chip per non-image attachment so a note
    //: that is really a wrapper around a PDF says so.
    const image = source.entry ? noteRowImage(source.entry) : null;
    if (image) {
      const thumb = document.createElement("img");
      thumb.className = "chat-source-thumb";
      thumb.src = mediaSrc(image.url);
      thumb.alt = image.alt || "";
      thumb.loading = "lazy";
      card.classList.add("has-thumb");
      card.appendChild(thumb);
    }
    if (source.snippet) {
      const snippet = document.createElement("p");
      snippet.className = "chat-source-snippet";
      //: `compact` because this is a two-line preview inside a card, not a
      //: note body: it is the same flag the timeline and widget previews pass.
      //: Wiki links are unwrapped first, renderInlineMarkdown is inline-only
      //: and does not know `[[…]]`, so without this a linked note printed its
      //: own brackets.
      renderInlineMarkdown(
        snippet,
        source.snippet.replace(/\[\[([^[\]]{1,120})\]\]/g, "$1"),
        null,
        true
      );
      //: **The card is itself a control**, so nothing inside it may be one.
      //: renderInlineMarkdown emits real `<a>`s and file chips for links, and
      //: an anchor nested inside this card's own `<a>`/`<button>` is both
      //: invalid and unreachable by keyboard, the outer control swallows it.
      //: The formatting is what was asked for; the second click target was not.
      deactivateControls(snippet);
      card.appendChild(snippet);
    }
    const files = (source.entry?.attachments || []).filter((file) => !file.is_image);
    if (files.length) {
      const strip = document.createElement("span");
      strip.className = "chat-source-files";
      for (const file of files.slice(0, 3)) {
        const chip = document.createElement("span");
        chip.className = "chip chat-source-file";
        setLabel(chip, `ph:paperclip ${file.filename || "file"}`);
        chip.title = file.filename || "";
        strip.appendChild(chip);
      }
      if (files.length > 3) {
        const more = document.createElement("span");
        more.className = "chip chat-source-file muted";
        more.textContent = `+${files.length - 3}`;
        strip.appendChild(more);
      }
      card.appendChild(strip);
    }
    const foot = document.createElement("span");
    foot.className = "chat-source-foot muted";
    const group = CHAT_SOURCE_GROUPS.find((g) => g.key === source.kind);
    foot.textContent = source.url ? sourceHost(source.url) || "the web" : group?.one || source.kind;
    card.appendChild(foot);
    grid.appendChild(card);
  });
  body.appendChild(grid);
  details.appendChild(body);
  return details;
}

function renderRecordsDetails(holder, meta) {
  if (!meta.raw_results.length) return;
  const details = document.createElement("details");
  const summary = document.createElement("summary");
  summary.className = "muted";
  const label = SEARCH_MODE_LABELS[meta.search_mode] || meta.search_mode;
  summary.textContent = `${meta.raw_results.length} matching note${
    meta.raw_results.length === 1 ? "" : "s"
  } (${label}): click one to open it`;
  // The tune-sensitivity shortcut used to live here too, repeated on every
  // single message's own disclosure. Reported directly: it belongs as one
  // persistent control (`#chat-tune-search`, wired near the Chat dock's
  // other "how it answers" settings) instead of message metadata.
  details.appendChild(summary);
  const list = document.createElement("ul");
  list.className = "entry-list";
  // Same provenance badges as the Ask tab (matchReasonBadge / renderRawResults
  // above): the backend's "meta" SSE event already carries match_info and
  // connected_ids for a chat turn, same shape as an Ask turn's; this just
  // hadn't been wired up here, so a chat search result showed no reason at
  // all while the identical Ask result did.
  const connected = new Set(meta.connected_ids || []);
  const matchInfo = meta.match_info || {};
  for (const entry of meta.raw_results) {
    const row = clickableResult(entry);
    const badge = matchReasonBadge(matchInfo[entry.id]);
    if (badge) {
      if (connected.has(entry.id)) row.classList.add("result-connected");
      if (matchInfo[entry.id]?.type === "connected_2hop") row.classList.add("result-connected-2hop");
      row.appendChild(badge);
    }
    list.appendChild(row);
  }
  details.appendChild(list);
  holder.appendChild(details);
}

// --- the writing room: thoughts in, a note out -----------------------------------
// The draft is deliberately kept in the browser (and localStorage) rather than
// in the database. A half-finished draft isn't a note, and quietly filling the
// notebook with them would be worse than occasionally losing one.

const DRAFT_STORE = "writingRoomDraft";

function saveDraftLocally() {
  try {
    localStorage.setItem(
      DRAFT_STORE,
      JSON.stringify({
        thoughts: $("draft-thoughts").value,
        draft: $("draft-text").value,
        tags: $("draft-tags").value,
      })
    );
  } catch {
    /* storage full or blocked, the draft is still on screen */
  }
}

function restoreDraftLocally() {
  try {
    const saved = JSON.parse(localStorage.getItem(DRAFT_STORE) || "null");
    if (!saved) return;
    $("draft-thoughts").value = saved.thoughts || "";
    $("draft-text").value = saved.draft || "";
    $("draft-tags").value = saved.tags || "";
    updateDraftCount();
  } catch {
    /* unreadable: start clean rather than throwing on load */
  }
}

function updateDraftCount() {
  const text = $("draft-text").value.trim();
  const words = text ? text.split(/\s+/).length : 0;
  $("draft-count").textContent = words ? `${words} word${words === 1 ? "" : "s"}` : "";
}

// Every AI pass is undoable. "Draft it" replaces the draft AND clears the
// thoughts box, so without this a revision you didn't like destroyed both your
// previous wording and the notes you wrote it from, with nothing to go back
// to. Handing your writing to the AI should never be a one-way door.
const draftUndoStack = [];
const MAX_DRAFT_UNDO = 20;

function pushDraftUndo() {
  draftUndoStack.push({
    thoughts: $("draft-thoughts").value,
    draft: $("draft-text").value,
  });
  if (draftUndoStack.length > MAX_DRAFT_UNDO) draftUndoStack.shift();
  updateDraftUndoButton();
}

function updateDraftUndoButton() {
  const button = $("draft-undo");
  button.disabled = draftUndoStack.length === 0;
  button.title = draftUndoStack.length
    ? `Go back to the version before the last AI pass (${draftUndoStack.length} available)`
    : "Nothing to undo yet";
}

function undoDraft() {
  const previous = draftUndoStack.pop();
  if (!previous) return;
  $("draft-thoughts").value = previous.thoughts;
  // Stepping back past a pass means those thoughts were not folded in after
  // all: otherwise the next Draft would skip them and silently drop an idea.
  foldedThoughts = "";
  $("draft-text").value = previous.draft;
  updateDraftCount();
  updateDraftUndoButton();
  saveDraftLocally();
  $("draft-status").classList.remove("error");
  $("draft-status").textContent = "Went back to the previous version.";
  announce("Restored the draft from before the last AI pass.");
}

// One-shot AI calls (drafting, document edits) had no way out: press the
// button by mistake or watch it stall, and the only options were waiting or
// reloading the page. Each now runs against an AbortController so it can be
// cancelled, and shows that it's working while it does.
let draftController = null;

function setDraftBusy(busy) {
  $("draft-compose").classList.toggle("hidden", busy);
  $("draft-cancel").classList.toggle("hidden", !busy);
  $("draft-undo").disabled = busy || draftUndoStack.length === 0;
}

function cancelDraft() {
  draftController?.abort();
}

// What was last folded into the draft. Kept so a second pass doesn't resend
// thoughts the model has already used, which is the problem clearing the box
// was solving, at the cost of destroying the user's own writing.
let foldedThoughts = "";

async function composeDraft() {
  const written = $("draft-thoughts").value;
  // Only the part they've added since the last pass. If they edited earlier
  // text, the prefix no longer matches and everything is sent again, the
  // safe direction: the model repeats itself rather than losing a thought.
  const thoughts = written.startsWith(foldedThoughts)
    ? written.slice(foldedThoughts.length).trim()
    : written.trim();
  const draft = $("draft-text").value;
  const status = $("draft-status");
  if (!thoughts && !draft.trim()) {
    status.classList.add("error");
    status.textContent = "Write a thought first.";
    return;
  }
  status.classList.remove("error");
  setLabel(status, draft.trim() ? "ph:magic-wand Revising…" : "ph:magic-wand Drafting…");
  draftController = new AbortController();
  setDraftBusy(true);
  try {
    const body = await apiJson("/drafts/compose", {
      method: "POST",
      signal: draftController.signal,
      body: JSON.stringify({
        thoughts,
        draft,
        instruction: $("draft-instruction").value.trim(),
      }),
    });
    // Only record an undo point once the model has actually returned
    // something: a failed call shouldn't add a step that changes nothing.
    if (body.draft !== draft) pushDraftUndo();
    $("draft-text").value = body.draft;
    updateDraftCount();
    // The thoughts have been folded in, remember that, but never delete what
    // they wrote. Clearing the box was reported twice as the app eating the
    // user's text, and it is: the raw thoughts are often the only copy of an
    // idea, and the draft is a rewrite of them, not a replacement.
    if (body.ollama_running && thoughts) foldedThoughts = written;
    $("draft-instruction").value = "";
    const thinking = $("draft-thinking");
    thinking.classList.toggle("hidden", !body.thinking);
    $("draft-thinking-text").textContent = body.thinking || "";
    if (body.message) {
      status.classList.add("error");
      status.textContent = body.message;
    } else {
      status.textContent = thoughts
        ? "Folded your thoughts into the draft, your notes above are untouched."
        : "Draft updated: edit it, or add more thoughts.";
      announce("The draft has been updated.");
    }
    saveDraftLocally();
  } catch (error) {
    if (error.name === "AbortError") {
      // Nothing was written, so nothing is lost, say so rather than
      // showing it as a failure.
      status.textContent = "Stopped. Your thoughts and draft are untouched.";
    } else {
      status.classList.add("error");
      status.textContent = error.message;
    }
  } finally {
    draftController = null;
    setDraftBusy(false);
  }
}

async function saveDraftAsNote() {
  const content = $("draft-text").value.trim();
  const status = $("draft-status");
  if (!content) {
    status.classList.add("error");
    status.textContent = "There's no draft to save yet.";
    return;
  }
  status.classList.remove("error");
  status.textContent = "Saving…";
  const tags = $("draft-tags")
    .value.split(",")
    .map((t) => t.trim())
    .filter(Boolean);
  try {
    // Marked as a draft on the way in, same as the text-selection popup's
    // "Save as draft note", asked for directly, so a note drafted here is
    // just as findable in the Drafts filter (sidebar, Library) as one
    // captured that way, not silently indistinguishable from a note typed
    // straight into Notes.
    const entry = await apiJson("/entries", {
      method: "POST",
      body: JSON.stringify({ content, tags, is_draft: true }),
    });
    foldedThoughts = "";
    $("draft-thoughts").value = "";
    $("draft-text").value = "";
    $("draft-tags").value = "";
    $("draft-thinking").classList.add("hidden");
    updateDraftCount();
    saveDraftLocally();
    status.textContent = "Saved as a note.";
    toast("Draft saved as a note.");
    await loadEntries();
    flashEntry(entry.id); // show them where it landed
  } catch (error) {
    status.classList.add("error");
    status.textContent = error.message;
  }
}

// --- extract notes (BACKLOG.md §62) ---------------------------------------------
// Select a block of writing, the Writing Room's draft, a Document's body, or
// several notes' content selected on the whiteboard, and split it into one
// or more AI-drafted notes, auto-linked with real reasons. Always a preview
// first, matching Draft AI edit's own "read it, then accept" shape: nothing
// is saved until "Save notes" is pressed, since this can silently multiply
// one piece of writing into several permanent notes.

// The last preview response, kept so commit can look up each kept note's
// server-decided category and each kept link's server-generated reason: 
// the DOM only holds what the user is allowed to edit (title, content, tags,
// keep/drop), not those.
let extractProposal = null;

async function openExtractPreview(text, { sourceEntryIds = [], sourceDocumentId = null } = {}) {
  const trimmed = (text || "").trim();
  if (!trimmed) {
    toast("Select some text to extract notes from first.");
    return;
  }
  extractProposal = { source_document_id: sourceDocumentId };
  const panel = $("extract-panel");
  panel.classList.remove("hidden");
  $("extract-notes-list").innerHTML = "";
  $("extract-links-list").innerHTML = "";
  $("extract-commit").disabled = true;
  const status = $("extract-status");
  status.classList.remove("error");
  setLabel(status, "ph:magic-wand Reading it over…");
  try {
    const body = await apiJson("/entries/extract/preview", {
      method: "POST",
      body: JSON.stringify({ text: trimmed, source_entry_ids: sourceEntryIds }),
    });
    extractProposal = { ...body, source_document_id: sourceDocumentId };
    renderExtractPreview(body);
  } catch (error) {
    status.classList.add("error");
    status.textContent = error.message;
  }
}

// What a link's `kind` (from `ai.extractor`) reads as in the preview.
const EXTRACT_LINK_KIND_LABEL = { sibling: "new note", source: "source", related: "related" };

function extractRefLabel(ref, notes) {
  if (ref.startsWith("existing:")) return "an existing note";
  const note = notes.find((n) => n.ref === ref);
  return note ? note.title || note.content.slice(0, 30) : ref;
}

function renderExtractPreview(body) {
  const status = $("extract-status");
  status.classList.remove("error");
  status.textContent =
    body.message ||
    `${body.notes.length} note${body.notes.length === 1 ? "" : "s"} proposed: review, then save.`;

  // Built with createElement, not an `innerHTML` template per iteration.
  // The old version escaped everything correctly, so this is not a security
  // fix: it is this file's own rule (see the header comment: "All DOM nodes
  // are built with createElement/textContent, never innerHTML"), and the rule
  // exists because an `innerHTML` assignment inside a loop re-invokes the HTML
  // parser once per proposed note, and because the next person to add a field
  // here is one forgotten `escapeHtml` away from an injection.
  const field = (type, className, { placeholder, label, value } = {}) => {
    const input = document.createElement("input");
    input.type = type;
    input.className = className;
    if (placeholder) input.placeholder = placeholder;
    if (label) input.setAttribute("aria-label", label);
    if (value !== undefined) input.value = value;
    return input;
  };

  const list = $("extract-notes-list");
  list.replaceChildren();
  for (const note of body.notes) {
    const card = document.createElement("div");
    card.className = "extract-note-card";
    card.dataset.ref = note.ref;

    const keepLabel = document.createElement("label");
    keepLabel.className = "row align-center checkbox-label";
    const keep = field("checkbox", "extract-note-keep");
    keep.checked = true;
    keepLabel.append(keep, document.createTextNode(" Keep this note"));

    const title = field("text", "extract-note-title", {
      placeholder: "Title (optional)",
      label: "Note title",
      value: note.title || "",
    });

    const content = document.createElement("textarea");
    content.className = "extract-note-content";
    content.rows = 6;
    content.setAttribute("aria-label", "Note content");
    content.value = note.content;

    const meta = document.createElement("div");
    meta.className = "row extract-note-meta";
    const category = document.createElement("span");
    category.className = "muted extract-note-category";
    category.textContent = `Filed under: ${note.category}`;
    meta.append(
      category,
      field("text", "extract-note-tags", {
        placeholder: "Tags, comma separated",
        label: "Tags for this note",
      })
    );

    card.append(keepLabel, title, content, meta);
    list.appendChild(card);
  }

  const linksBox = $("extract-links-list");
  linksBox.replaceChildren();
  if (body.links.length) {
    const heading = document.createElement("p");
    heading.className = "muted";
    heading.textContent = "Links";
    linksBox.appendChild(heading);
  }
  for (const link of body.links) {
    const row = document.createElement("label");
    row.className = "row align-center extract-link-row checkbox-label";
    row.dataset.sourceRef = link.source_ref;
    row.dataset.targetRef = link.target_ref;
    const kindLabel = EXTRACT_LINK_KIND_LABEL[link.kind] || "note";
    // Raw, not escaped: this now goes into a text node, where escaping would
    // render the entities literally ("A &amp; B" on screen).
    const target = link.target_preview || extractRefLabel(link.target_ref, body.notes);
    const keep = document.createElement("input");
    keep.type = "checkbox";
    keep.className = "extract-link-keep";
    keep.checked = true;
    const desc = document.createElement("span");
    desc.className = "extract-link-desc";
    const why = document.createElement("span");
    why.className = "muted";
    why.textContent = `(${kindLabel}: ${link.reason})`;
    desc.append(
      document.createTextNode(
        `${extractRefLabel(link.source_ref, body.notes)} → ${target} `
      ),
      why
    );
    row.append(keep, desc);
    linksBox.appendChild(row);
  }

  $("extract-commit").disabled = body.notes.length === 0;
}

function closeExtractPreview() {
  $("extract-panel").classList.add("hidden");
  extractProposal = null;
}

async function commitExtractPreview() {
  if (!extractProposal) return;
  const keptRefs = new Set();
  const notes = [];
  for (const card of $("extract-notes-list").querySelectorAll(".extract-note-card")) {
    if (!card.querySelector(".extract-note-keep").checked) continue;
    const ref = card.dataset.ref;
    const original = extractProposal.notes.find((n) => n.ref === ref);
    if (!original) continue;
    const content = card.querySelector(".extract-note-content").value.trim();
    if (!content) continue; // an edited-down-to-nothing note is dropped, not saved empty
    keptRefs.add(ref);
    notes.push({
      ref,
      title: card.querySelector(".extract-note-title").value.trim(),
      content,
      category: original.category,
      tags: card
        .querySelector(".extract-note-tags")
        .value.split(",")
        .map((t) => t.trim())
        .filter(Boolean),
    });
  }
  if (!notes.length) {
    toast("Keep at least one note to save.");
    return;
  }

  const links = [];
  for (const row of $("extract-links-list").querySelectorAll(".extract-link-row")) {
    if (!row.querySelector(".extract-link-keep").checked) continue;
    const sourceRef = row.dataset.sourceRef;
    const targetRef = row.dataset.targetRef;
    if (!keptRefs.has(sourceRef)) continue; // its source note was dropped
    if (!targetRef.startsWith("existing:") && !keptRefs.has(targetRef)) continue; // its sibling was dropped
    const original = extractProposal.links.find(
      (l) => l.source_ref === sourceRef && l.target_ref === targetRef
    );
    if (original) links.push({ source_ref: sourceRef, target_ref: targetRef, reason: original.reason });
  }

  $("extract-commit").disabled = true;
  const status = $("extract-status");
  status.classList.remove("error");
  status.textContent = "Saving…";
  try {
    const result = await apiJson("/entries/extract/commit", {
      method: "POST",
      body: JSON.stringify({
        notes,
        links,
        source_document_id: extractProposal.source_document_id || null,
      }),
    });
    closeExtractPreview();
    toast(`Saved ${result.notes.length} note${result.notes.length === 1 ? "" : "s"}.`);
    await loadEntries();
  } catch (error) {
    status.classList.add("error");
    status.textContent = error.message;
    $("extract-commit").disabled = false;
  }
}

// --- attaching notes to a chat message ------------------------------------------
// "Use this note, specifically" is a stronger signal than any similarity
// score, so attached notes are sent to the model ahead of whatever retrieval
// finds. The picker searches the notes already loaded in memory, no request
// per keystroke, and it works the moment it's opened.

let attachedNoteIds = [];
// The set sent with the most recent message, so regenerate can reuse it.
let lastChatAttachments = [];

// --- attaching images to a chat message (vision-capable models) ----------------
// Same shape as note attachments just above, uploaded through the existing
// /media/upload (the note/document editors' own drag-and-drop endpoint) so
// there is one upload path in the app, not two. `attachedImages` holds
// {id, url}: the id is what the server needs, the url is what renders the
// thumbnail without a second round trip.
let attachedImages = [];
let lastChatImageAttachments = [];

function renderImageAttachments() {
  const box = $("chat-image-attachments");
  if (!box) return;
  box.replaceChildren();
  box.classList.toggle("hidden", attachedImages.length === 0);
  $("attach-image")?.classList.toggle("has-attachments", attachedImages.length > 0);
  for (const image of attachedImages) {
    const chipEl = document.createElement("span");
    // Reuses the note-composer's own image-attachment look
    // (04-chat-dock-appearance.css) rather than inventing a second one.
    chipEl.className = "chip attachment-chip attachment-chip-image";
    const thumb = document.createElement("img");
    // A staged image has no server url yet, its bytes are local, so the
    // object URL is what draws it. `mediaSrc` is still right for one already
    // uploaded: a plain <img> never attaches X-Auth-Token.
    thumb.src = image.objectUrl || mediaSrc(image.url);
    thumb.alt = "";
    const remove = document.createElement("button");
    remove.className = "attachment-remove";
    remove.type = "button";
    remove.textContent = "✕";
    remove.title = "Remove this image";
    remove.setAttribute("aria-label", remove.title);
    remove.addEventListener("click", async () => {
      attachedImages = attachedImages.filter((img) => img.key !== image.key);
      // An object URL is a document-lifetime reference to a Blob: dropping the
      // array entry alone leaks the image's bytes for as long as the tab is
      // open.
      if (image.objectUrl) URL.revokeObjectURL(image.objectUrl);
      renderImageAttachments();
      announce(`Removed image. ${attachedImages.length} image(s) attached.`);
      // Nothing to tell the server about: a staged image has never been
      // uploaded (see `attachImageFiles`). The delete call that used to live
      // here existed because attaching uploaded immediately, so removing had
      // to clean up after it, staging removes the need rather than the
      // symptom. An image that *is* already on the server (a regenerate
      // re-using an earlier message's attachments) keeps its id and is left
      // alone, because the sent message still references it.
    });
    chipEl.append(thumb, remove);
    box.appendChild(chipEl);
  }
}

async function attachImageFiles(files) {
  // Small and silent per-file, deliberately: a picker with several photos
  // selected shouldn't abort the whole batch because one was too big or the
  // wrong type: the same "drop what's wrong, keep what's fine" the note
  // picker already does with unresolved wiki-links.
  const room = 4 - attachedImages.length;
  for (const file of Array.from(files).slice(0, Math.max(0, room))) {
    // **Staged, not uploaded.** REDESIGN.md R7.2, asked for directly: "files
    // should only be staged and not permanently saved while uploaded to a
    // note that hasnt been saved yet, or chat messages that havent been sent
    // yet."
    //
    // Attaching used to `POST /media/upload` immediately, so an image
    // attached to a message that was never sent stayed on disk and in the
    // Library gallery forever. Removing the chip cleaned up after itself, but
    // *abandoning* the draft: closing the tab, switching conversation,
    // walking away: did not, and that is the common case rather than the
    // rare one.
    //
    // The bytes stay in the browser until `commitStagedImages()` runs on
    // send. The thumbnail renders from an object URL, so the preview costs no
    // round trip and the server learns nothing about a message that may never
    // exist.
    attachedImages.push({
      key: `staged-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`,
      file,
      objectUrl: URL.createObjectURL(file),
      name: file.name,
    });
  }
  renderImageAttachments();
}

//: Upload whatever is still staged, and return the attachment list with real
//: ids. Called at the moment a message is actually sent, the point where the
//: user has committed to it and the server needs to know.
//:
//: A failure here has to stop the send rather than drop the picture quietly:
//: a message that arrives without the image it was written about is worse
//: than one that refuses to send and says why.
async function commitStagedImages() {
  for (const image of attachedImages) {
    if (image.id) continue; // already on the server (a regenerate re-uses these)
    const form = new FormData();
    form.append("file", image.file);
    // No explicit Content-Type: the browser sets its own multipart boundary
    // for a FormData body, and `api()`'s default JSON header would be wrong
    // here: the same reason the editor's own image-drop upload overrides
    // headers rather than merging.
    const uploaded = await apiJson("/media/upload", {
      method: "POST",
      headers: { "X-Auth-Token": authToken() },
      body: form,
    });
    image.id = uploaded.id;
    image.url = uploaded.url;
    image.name = uploaded.filename || image.name;
  }
  return attachedImages;
}

// --- one attach button, two destinations ---------------------------------------
//
// Asked for directly: the chat's image button should attach *any* file, 
// "images should appear in the image gallery (any image format), and the
// others should probably go in the documents subtab".
//
// The split is by what the file *is*, not by what was clicked, because the
// picker takes both at once and a person selecting four things does not expect
// to have sorted them first:
//
// - An image goes where images already went: uploaded to the gallery and
//   staged on this message, so a vision model can look at it.
// - Anything else is imported as a document (`POST /documents/import`, which
//   extracts its text via core/docview.py). It is then a real document in the
//   Documents sub-tab, which the AI can reach with its own list_documents /
//   get_document tools: rather than a file the app had nowhere to put.
//
// Failures are per-file and quiet, the same rule attachImageFiles already
// followed: a picker with four files selected must not lose three because one
// was a .mp4.
function isImageFile(file) {
  // The type the browser reports, falling back to the extension, a file
  // dragged from some archives arrives with an empty `type`.
  if ((file.type || "").startsWith("image/")) return true;
  return /\.(png|jpe?g|gif|webp|bmp|avif|ico|tiff?|heic|heif|svg)$/i.test(file.name || "");
}

async function attachChatFiles(files) {
  const all = Array.from(files);
  const images = all.filter(isImageFile);
  const documents = all.filter((f) => !isImageFile(f));
  if (images.length) await attachImageFiles(images);
  if (documents.length) await importChatDocuments(documents);
}

//: The suffixes `/media/upload` accepts (`MEDIA_SUFFIXES`, routes_files.py).
//: Kept as a literal rather than fetched: it is a fallback path that must not
//: itself need a round trip to decide whether it can run.
const MEDIA_FALLBACK_SUFFIXES = /\.(png|jpe?g|gif|webp|avif|bmp|ico|pdf)$/i;

async function keepUnreadableChatFile(file, error) {
  if (!MEDIA_FALLBACK_SUFFIXES.test(file.name || "")) return false;
  const form = new FormData();
  form.append("file", file);
  form.append("direct", "true");
  try {
    await apiJson("/media/upload", {
      method: "POST",
      headers: { "X-Auth-Token": authToken() },
      body: form,
    });
  } catch {
    return false;
  }
  //: Both halves, because either alone is misleading: "saved to your Library"
  //: without the reason looks like the import worked, and the reason without
  //: the destination looks like the file was lost.
  toastAction(
    `Kept “${file.name}” in your Library, ${error?.message || "its text could not be read"}`,
    "Show it",
    () => {
      switchTab("library");
      if (typeof renderLibrary === "function") renderLibrary();
    },
  );
  return true;
}

async function importChatDocuments(files) {
  const made = [];
  for (const file of files) {
    const form = new FormData();
    form.append("file", file);
    try {
      // Same header handling as attachImageFiles: a FormData body needs the
      // browser to set its own multipart boundary, so apiJson's JSON default
      // has to be overridden rather than merged.
      const document = await apiJson("/documents/import", {
        method: "POST",
        headers: { "X-Auth-Token": authToken() },
        body: form,
      });
      made.push(document);
    } catch (error) {
      //: **A file the app cannot read is still a file worth keeping.**
      //:
      //: Reported: *"make sure the file upload and staging as chips works
      //: because I tried to upload two pdf files and nothing showed up."*
      //: Nothing showed up because `/documents/import` answers 422 for a PDF
      //: whose text cannot be extracted, which on an install without
      //: markitdown is *every* PDF, and a 422 became one toast that expired.
      //: So the paperclip advertised PDFs, refused them, and left no trace.
      //:
      //: REDESIGN.md §R7.2's reversal is the rule here and it is explicit:
      //: PDFs and documents must be viewable, downloadable and manageable
      //: **without any AI model in the loop**. Failing to read a PDF's words
      //: is not a reason to throw the PDF away. So the bytes go to
      //: `/media/upload`, the Library's own store, which takes PDFs, and
      //: the user is told where it went and why the text is missing.
      const kept = await keepUnreadableChatFile(file, error);
      if (!kept) toast(error.message || `Couldn't read "${file.name}".`, true);
    }
  }
  if (!made.length) return;
  // **Staged on the message, not just imported and announced.** The toast
  // below still says where the file went, but a toast is a moment and the
  // report was about what is left behind: "images and files uploaded into a
  // chat conversation arent rendered with the chat messages". An imported
  // document is now an attachment of the message being written, exactly as
  // an image is: a chip in the composer, then a chip in the bubble, then a
  // way back to the document.
  for (const document of made) {
    if (attachedDocuments.length >= MAX_CHAT_DOCUMENTS) break;
    attachedDocuments.push({ id: document.id, name: document.title });
  }
  renderDocumentAttachments();

  const first = made[0];
  const label =
    made.length === 1
      ? `Added “${first.title}” to your documents.`
      : `Added ${made.length} files to your documents.`;
  toastAction(label, made.length === 1 ? "Open it" : "Show them", () => {
    switchTab("documents");
    if (made.length === 1) openDocument(first.id);
  });
}

//: Documents staged on the message being written. Same shape and same
//: lifecycle as `attachedImages` above: cleared on send, snapshotted for a
//: regenerate: because a person attaching a photo and a spreadsheet in one
//: go should not find the app treating them as two different kinds of act.
//:
//: Unlike an image, removing one of these does *not* delete the document:
//: `/documents/import` created a real document in the Documents tab and the
//: toast said so, so deleting it out from under that promise would be the
//: app taking back something it already told the user it had done.
let attachedDocuments = [];
let lastChatDocumentAttachments = [];

//: Four, matching the ceiling the import path already enforced inline. A
//: local model's context is the scarce thing here, and four whole documents
//: is already more than most of them can hold alongside a conversation.
const MAX_CHAT_DOCUMENTS = 4;

//: **Files from the Library, staged on the message.** Asked for directly: "I
//: want to be able to attach not just existing notes to a chat for context,
//: but also already uploaded files, documents, and images."
//:
//: A third list rather than folding files into `attachedDocuments`, because
//: they are a third table: a Library file is an Attachment row, a document is
//: a Document row, and the chat request carries `file_ids` and `document_ids`
//: separately for exactly that reason (routes_chat.py). Removing one never
//: deletes the file -- it was in the Library before this message and stays
//: there after it, the same promise `attachedDocuments` makes.
let attachedFiles = [];
let lastChatFileAttachments = [];

//: Four, matching `MAX_CHAT_DOCUMENTS` and the server's own `max_length=4`.
//: A file's text is capped at 12k characters server-side, so four of them is
//: already a large fraction of a small local model's context.
const MAX_CHAT_FILES = 4;

function attachLibraryFile(id, name) {
  if (attachedFiles.some((f) => f.id === id)) return true;
  if (attachedFiles.length >= MAX_CHAT_FILES) return false;
  attachedFiles.push({ id, name: name || "File" });
  renderFileAttachments();
  announce(`Attached “${name || "file"}”. ${attachedFiles.length} file(s) attached.`);
  return true;
}

function renderFileAttachments() {
  const box = $("chat-file-attachments");
  if (!box) return;
  box.replaceChildren();
  box.classList.toggle("hidden", attachedFiles.length === 0);
  for (const file of attachedFiles) {
    const chipEl = document.createElement("span");
    chipEl.className = "chip attachment-chip";
    const label = document.createElement("span");
    setLabel(label, `ph:paperclip ${file.name}`);
    const remove = document.createElement("button");
    remove.className = "attachment-remove";
    remove.type = "button";
    remove.textContent = "\u2715";
    remove.title = `Don't send “${file.name}” with this message`;
    remove.setAttribute("aria-label", remove.title);
    remove.addEventListener("click", () => {
      attachedFiles = attachedFiles.filter((f) => f.id !== file.id);
      renderFileAttachments();
      announce(`Removed attachment. ${attachedFiles.length} file(s) attached.`);
    });
    chipEl.append(label, remove);
    box.appendChild(chipEl);
  }
}

//: **Mind maps staged on the message** (MINDMAP_PLAN.md §5 item 11: "a map
//: can be attached to … a chat message, exactly as a file can today").
//:
//: A fourth list rather than folding maps into `attachedNotes`, even though a
//: board *is* an Entry and `note_ids` would have carried it. That is precisely
//: why it must not: a board's `content` is the single line `# My map`, so
//: attaching one as a note sends the model a heading and calls it a map. The
//: request carries `board_ids` separately (routes_chat.py) so the server can
//: send the map's *outline* instead.
let attachedBoards = [];
let lastChatBoardAttachments = [];

//: Four, matching `MAX_CHAT_DOCUMENTS`/`MAX_CHAT_FILES` and the server's own
//: `max_length=4`. An outline is capped at 3,000 characters server-side, so
//: four maps is ~12k, the same ceiling one attached file already has.
const MAX_CHAT_BOARDS = 4;

function attachBoardToChat(id, name) {
  if (!id) return false;
  if (attachedBoards.some((b) => b.id === id)) {
    renderBoardAttachments();
    return true;
  }
  if (attachedBoards.length >= MAX_CHAT_BOARDS) return false;
  attachedBoards.push({ id, name: name || "Mind map" });
  renderBoardAttachments();
  announce(`Attached “${name || "mind map"}”. ${attachedBoards.length} map(s) attached.`);
  return true;
}

function renderBoardAttachments() {
  const box = $("chat-board-attachments");
  if (!box) return;
  box.replaceChildren();
  box.classList.toggle("hidden", attachedBoards.length === 0);
  for (const board of attachedBoards) {
    const chipEl = document.createElement("span");
    chipEl.className = "chip attachment-chip";
    const label = document.createElement("span");
    setLabel(label, `ph:tree-structure ${board.name}`);
    const remove = document.createElement("button");
    remove.className = "attachment-remove";
    remove.type = "button";
    remove.textContent = "✕";
    remove.title = `Don't send “${board.name}” with this message`;
    remove.setAttribute("aria-label", remove.title);
    remove.addEventListener("click", () => {
      attachedBoards = attachedBoards.filter((b) => b.id !== board.id);
      renderBoardAttachments();
      announce(`Removed attachment. ${attachedBoards.length} map(s) attached.`);
    });
    chipEl.append(label, remove);
    box.appendChild(chipEl);
  }
}

//: **Stage one document on the message being written.**
//:
//: The composer has staged documents as removable chips since files could be
//: dropped into chat, but the only way in was that import path, so every
//: *other* surface that wanted to ask the AI about a document had to paste its
//: text into the box instead. Reported about the Documents tab's own button:
//: "the 'check with ai' button in the documents should attach a link to the
//: document or an excerpt from the document to read but in a little attached
//: badge that can be removed so the document text isnt just pasted below."
//:
//: Returns false rather than throwing when it cannot: no id (an unsaved
//: document), or the four-attachment ceiling already reached. The caller
//: decides what to do about it, `docAiReview` falls back to pasting, because
//: silently asking a question about nothing is the worse failure.
function attachDocumentToChat(id, name) {
  if (!id) return false;
  if (attachedDocuments.some((d) => d.id === id)) {
    renderDocumentAttachments();
    return true; // already staged: the badge the caller wanted is on screen
  }
  if (attachedDocuments.length >= MAX_CHAT_DOCUMENTS) return false;
  attachedDocuments.push({ id, name: name || "Document" });
  renderDocumentAttachments();
  announce(`Attached “${name || "document"}”. ${attachedDocuments.length} document(s) attached.`);
  return true;
}

function renderDocumentAttachments() {
  const box = $("chat-doc-attachments");
  if (!box) return;
  box.replaceChildren();
  box.classList.toggle("hidden", attachedDocuments.length === 0);
  for (const document_ of attachedDocuments) {
    const chipEl = document.createElement("span");
    chipEl.className = "chip attachment-chip";
    const label = document.createElement("span");
    setLabel(label, `ph:file-text ${document_.name}`);
    const remove = document.createElement("button");
    remove.className = "attachment-remove";
    remove.type = "button";
    remove.textContent = "✕";
    remove.title = `Don't send “${document_.name}” with this message`;
    remove.setAttribute("aria-label", remove.title);
    remove.addEventListener("click", () => {
      attachedDocuments = attachedDocuments.filter((d) => d.id !== document_.id);
      renderDocumentAttachments();
      announce(`Removed attachment. ${attachedDocuments.length} document(s) attached.`);
    });
    chipEl.append(label, remove);
    box.appendChild(chipEl);
  }
}

//: **The passage the user is looking at**, carried from an editing surface to
//: the chat composer. REDESIGN.md §R7.1 item 1, and the request behind it:
//: *"able to highlight text and say something in the chat and the agent gets
//: the context of what is highlighted and cursor position."*
//:
//: One at a time, replaced rather than appended, and that is the difference
//: between this and the three attachment lists above. A selection is *where
//: you are*, not a thing you collect: selecting a second passage means you
//: changed your mind about the first, and a stack of them would send the
//: model four regions of four documents to reconcile.
let attachedSelection = null;

//: What `askAboutSelection` (editor.js) calls. Attaching switches to the chat
//: and puts the caret in the box, because the whole gesture is "select, ask", 
//: leaving the user on the note with a chip they cannot see would be the same
//: number of clicks as before with an extra step of confusion.
function attachSelectionContext(context) {
  attachedSelection = context;
  renderSelectionAttachment();
  switchTab("chat");
  const input = $("chat-input");
  if (input) {
    input.focus();
    autoGrow(input);
  }
  announce(`Selection from ${context.title} attached to your next message.`);
}

function clearSelectionAttachment() {
  attachedSelection = null;
  renderSelectionAttachment();
}

function renderSelectionAttachment() {
  const box = $("chat-selection-attachment");
  if (!box) return;
  box.replaceChildren();
  box.classList.toggle("hidden", !attachedSelection);
  if (!attachedSelection) return;
  const chipEl = document.createElement("span");
  chipEl.className = "chip attachment-chip";
  //: The full passage on hover. A chip can only show a few words of it, and
  //: "which selection is this?" is the one question it has to answer.
  chipEl.title = attachedSelection.text;
  const label = document.createElement("span");
  const words = attachedSelection.text.replace(/\s+/g, " ").trim();
  const shown = words.length > 42 ? `${words.slice(0, 41)}…` : words;
  setLabel(label, `ph:text-aa ${attachedSelection.title} · line ${attachedSelection.line}: “${shown}”`);
  const remove = document.createElement("button");
  remove.className = "attachment-remove";
  remove.type = "button";
  remove.textContent = "✕";
  remove.title = "Don't send this selection with your message";
  remove.setAttribute("aria-label", remove.title);
  remove.addEventListener("click", () => {
    clearSelectionAttachment();
    announce("Selection removed.");
  });
  chipEl.append(label, remove);
  box.appendChild(chipEl);
}

//: **Re-validated at send, not trusted from when it was attached.** This is
//: the part of odysseus's `getSelectionContext()` worth porting exactly
//: (`static/js/document.js`, AGPL: this project is AGPL-3.0, see
//: ANALYSIS.md): between selecting a passage and pressing send, the user can
//: type above it, undo, or edit the note entirely, and stored offsets then
//: point at *different words*. Sending those would hand the model text from a
//: region the user is no longer looking at, attributed to a line number that
//: is now someone else's line: wrong in the most confusing possible way.
//:
//: Three outcomes, and each is said plainly to the model rather than papered
//: over: the offsets still hold; the passage moved (found elsewhere, so the
//: line number is recomputed); or the passage is gone from the surface, in
//: which case the text is still sent, the user asked about it, but with no
//: position claimed at all.
function revalidateSelection(context) {
  const surface = document.getElementById(context.surfaceId);
  if (!(surface instanceof HTMLTextAreaElement)) {
    //: The note was closed or the document navigated away from. Nothing to
    //: check against, so nothing is claimed.
    return { ...context, position: "unknown" };
  }
  const value = surface.value;
  if (value.slice(context.start, context.end) === context.text) {
    return { ...context, position: "exact" };
  }
  const found = value.indexOf(context.text);
  if (found === -1) return { ...context, position: "gone" };
  const upToCaret = value.slice(0, found + context.text.length);
  return {
    ...context,
    start: found,
    end: found + context.text.length,
    line: upToCaret.split("\n").length,
    column: upToCaret.length - (upToCaret.lastIndexOf("\n") + 1) + 1,
    position: "moved",
  };
}

//: What the model is actually told. Terse on purpose: it rides on every
//: message that carries a selection, and the tool schemas are already the
//: dominant fixed cost of a round (§R5 item 1).
function selectionContextBlock(context) {
  const where =
    context.position === "gone" || context.position === "unknown"
      ? `${context.title} (the user has since edited it, so this passage may no longer be there)`
      : `${context.title}, line ${context.line}, column ${context.column}`;
  const parts = [`The user has selected this passage in ${where}:`, "", context.text, ""];
  const around = [context.before, context.after].some((t) => (t || "").trim());
  if (around) {
    parts.push(
      "Immediately around it, for context only, do not treat it as the question:",
      "",
      `…${context.before}⟦selection⟧${context.after}…`
    );
  }
  return parts.join("\n");
}

function attachedNotes() {
  return attachedNoteIds
    .map((id) => allEntries.find((e) => e.id === id))
    .filter(Boolean);
}

function noteLabel(entry, length = 40) {
  const text = notePreviewText(entry.content).replace(/\s+/g, " ").trim();
  return text.length > length ? `${text.slice(0, length - 1)}…` : text || "(empty note)";
}

//: **A note's own words are Markdown, and a badge is not a source view.**
//:
//: Reported (INBOX 35 and 40) with a screenshot of chat badges reading
//: `**Ice Breakers:**` and `# CAB432`. The label a badge carries is the
//: note's opening words as they are stored, markers and all: the backend
//: sends it that way on a `grounding` row and on every `touched` item, and
//: `setLabel` writes it with `textContent`, so the reader gets the syntax
//: instead of what it means. The answer directly above renders the same
//: markup properly, which is what makes it read as a bug rather than as a
//: convention.
//:
//: One block-level pass first, for both helpers below. A label is one line,
//: so a heading marker, a quote marker and a bullet have nothing to say in
//: it, and links and images are flattened to their own text: these labels
//: live inside `<button>` chips, where `renderInlineMarkdown`'s real `<a>`
//: would be invalid markup and a click that navigates away from the chat.
//: `safeHref` guards the anchors this app does want; a badge simply does not
//: want one.
function flattenNoteMarkdown(md) {
  return String(md ?? "")
    .replace(/^\s{0,3}(?:#{1,6}\s+|>\s?|[-*+]\s+|\d+[.)]\s+)/gm, "")
    .replace(/!?\[([^\]]{0,300})\]\([^)]{0,500}\)?/g, "$1")
    .replace(/\[\[([^[\]]{1,120})\]\]/g, "$1")
    .replace(/\s+/g, " ")
    .trim();
}

//: Plain characters, for anywhere only characters land: a `title`, an
//: `aria-label`, a string handed to the model. Built on `stripMarkdownPreview`
//: because that one already handles the case a truncated label always hits, a
//: slice landing inside `**bold te`, by deleting delimiters outright rather
//: than matching pairs.
function plainText(md) {
  return stripMarkdownPreview(flattenNoteMarkdown(md)).replace(/\s+/g, " ").trim();
}

//: A badge whose text is a note's own words. `label` follows `setLabel`'s
//: grammar (an optional leading `ph:` marker, then any app-written words such
//: as a citation number); `md` is the note text, rendered rather than printed.
//:
//: **A chip's own `max-width` does most of the cutting now, not a character
//: count** (chat-b.md items 2-3, INBOX 35/40). The old rule rendered only
//: when the text fit inside `length` plain characters and fell back to
//: flattened, unrendered text otherwise, because a naive character cut can
//: land inside `**bold**` and leave a stray delimiter on screen -- which is
//: exactly why a long note's opening words, the common case at a tight
//: budget like the grounding chip's 30, showed as raw markup instead of what
//: the answer directly above already renders. The render path is taken up to
//: a much more generous margin (`length * 4`: a chip's *display* width, not
//: its character count, is what a reader actually sees truncated, so CSS --
//: `.ph-text`, styled per caller, `.result-reason-chip` in
//: 03-dashboard-widgets.css measures its own -- does the truncating and can
//: only ever cut between whole rendered characters, never inside a token).
//: Only a genuinely pathological length (a multi-thousand-character note
//: with no chip wide enough to need rendering that much of it) still falls
//: back to `plainText`'s plain character cut: parsing that much Markdown
//: into one badge's DOM buys nothing nobody scrolls to see.
function setNoteLabel(el, label, md, length = 40) {
  const text = String(label ?? "");
  const match = PH_LABEL.exec(text);
  const prefix = (match ? text.slice(match[0].length) : text).trim();
  const flat = flattenNoteMarkdown(md) || "(empty note)";
  const generousBudget = length * 4;
  const plain = plainText(flat) || "(empty note)";
  const holder = document.createElement("span");
  if (plain.length > generousBudget) {
    holder.textContent = `${plain.slice(0, generousBudget - 1)}…`;
  } else {
    // `compact`, so an image becomes its alt text rather than a thumbnail
    // inside a chip; `dismissible: false` for the same reason, there is no
    // room for a remove affordance on a badge.
    renderInlineMarkdown(holder, flat, null, true, { dismissible: false });
  }
  el.replaceChildren();
  if (match) {
    const icon = document.createElement("i");
    icon.className = `ph ph-${match[1]} ph-lead`;
    icon.setAttribute("aria-hidden", "true");
    holder.className = "ph-text";
    el.append(icon);
  }
  // Its own element now, not text prepended into `holder` (chat-b.md item
  // 2): the two need to survive a chip's ellipsis differently. The ordinal
  // ("1.") has to stay fully visible always, or a truncated "5. Some not…"
  // reads as "some note starting with 5", not "note five"; `flex-shrink: 0`
  // on `.note-label-prefix` is what the CSS side of that is. `holder` keeps
  // the `.ph-text` class and stays the ellipsis target every existing
  // per-chip rule (`.answer-related-chip > .ph-text` and its siblings) is
  // already keyed on, so the prefix element is additive, not a rename.
  if (prefix) {
    const prefixEl = document.createElement("span");
    prefixEl.className = "note-label-prefix";
    prefixEl.textContent = prefix;
    el.append(prefixEl);
  }
  if (match) el.append(holder);
  else el.append(...holder.childNodes);
  return el;
}

function renderAttachments() {
  const box = $("chat-attachments");
  box.replaceChildren();
  const notes = attachedNotes();
  box.classList.toggle("hidden", notes.length === 0);
  $("attach-note").classList.toggle("has-attachments", notes.length > 0);
  for (const entry of notes) {
    const chipEl = document.createElement("span");
    chipEl.className = "chip attachment-chip";
    chipEl.title = entry.content;
    const label = document.createElement("span");
    setLabel(label, `ph:paperclip ${noteLabel(entry)}`);
    const remove = document.createElement("button");
    remove.className = "attachment-remove";
    remove.type = "button";
    remove.textContent = "✕";
    remove.title = `Remove "${noteLabel(entry, 24)}"`;
    remove.setAttribute("aria-label", remove.title);
    remove.addEventListener("click", () => {
      attachedNoteIds = attachedNoteIds.filter((id) => id !== entry.id);
      renderAttachments();
      renderNotePickerList();
      announce(`Removed attachment. ${attachedNoteIds.length} note(s) attached.`);
    });
    chipEl.append(label, remove);
    box.appendChild(chipEl);
  }
}

//: **Which of the four stores the picker is showing.** Asked for directly:
//: "I want to be able to attach not just existing notes to a chat for
//: context, but also already uploaded files, documents, and images." The
//: paperclip beside this button uploads something new; this picker is for
//: what the notebook already holds, and until now it could only reach one of
//: the four tables that hold it.
let notePickerSource = "notes";

//: Fetched once per opening rather than per keystroke, and per source rather
//: than all four up front: a notebook can hold thousands of files, and three
//: of these lists are never looked at in a session that only wanted a note.
const notePickerCache = { documents: null, files: null, images: null, maps: null };

async function notePickerRows(source) {
  if (source === "notes") return null; // notes come from allEntries, already in memory
  if (notePickerCache[source]) return notePickerCache[source];
  //: **Maps come from `/whiteboard/boards?type=map`**, not from `allEntries`.
  //: A map is a board, which is an Entry, so it *is* in `allEntries`, but
  //: what a chip has to say about one is its node count, and that lives only
  //: on `BoardOut`. `?type=map` also does the filtering server-side, which is
  //: the one caller §9.3 says that parameter was for: this list wants maps and
  //: no counts of the other kinds.
  if (source === "maps") {
    //: To the end, like the other three sources below: the filter is
    //: server-side but the list is a page now, and a picker that cannot offer
    //: a map is the one bug this picker must not have.
    const boards = await apiPagedList("/whiteboard/boards?type=map", 200, { silent: true }).catch(() => []);
    notePickerCache.maps = (Array.isArray(boards) ? boards : []).filter((b) => b.id != null);
    return notePickerCache.maps;
  }
  const path = source === "documents" ? "/documents" : source === "files" ? "/files/gallery" : "/media";
  //: `/documents` and `/media` are paged; `/files/gallery` is not, and reading
  //: to the end through `apiPagedList` is correct either way (an unpaged
  //: endpoint returns everything on the first request and the loop stops).
  //: A picker that silently cannot reach half the library is worse than a
  //: slow one.
  const rows = await apiPagedList(path, 200).catch(() => []);
  let list = Array.isArray(rows) ? rows : rows.documents || [];
  //: **Files means files, and a sketch is a picture.** Reported: "sketches
  //: show in the files section". `/files/gallery` is every attachment
  //: regardless of type -- it is the Library's own source for *both* its
  //: Images and its Files sub-tabs, which split it on the mime the same way
  //: here. Without that split a .png appeared under Files and again under
  //: Images, which makes the four sources look like they overlap arbitrarily.
  if (source === "files") list = list.filter((row) => !(row.mime || "").startsWith("image/"));
  //: And the other half of the same split: an image attached to a note is an
  //: Attachment row, so the Images source has to reach both tables or the
  //: picker's Images list silently omits every picture that arrived through a
  //: note rather than through an upload.
  if (source === "images") {
    const attachments = await apiJson("/files/gallery").catch(() => []);
    list = [
      ...list,
      ...(Array.isArray(attachments) ? attachments : []).filter((row) =>
        (row.mime || "").startsWith("image/")
      ),
    ];
  }
  notePickerCache[source] = list;
  return notePickerCache[source];
}

//: One row's identity, label and "is it attached" test, per source. Written as
//: a table rather than four branches inside the renderer because the renderer
//: is the same list either way -- a checkbox, a label and a chip -- and four
//: copies of it is how the four drift apart.
function notePickerShape(source) {
  if (source === "documents") {
    return {
      id: (row) => row.id,
      label: (row) => row.title || "Untitled document",
      note: () => "Document",
      search: (row) => `${row.title || ""} ${row.content || ""}`,
      isOn: (row) => attachedDocuments.some((d) => d.id === row.id),
      add: (row) => attachDocumentToChat(row.id, row.title || "Document"),
      remove: (row) => {
        attachedDocuments = attachedDocuments.filter((d) => d.id !== row.id);
        renderDocumentAttachments();
      },
      empty: "No documents yet.",
    };
  }
  if (source === "maps") {
    return {
      id: (row) => row.id,
      label: (row) => row.title || "Untitled map",
      //: The count is what the row adds over its title, and it is the reason
      //: this list comes from `/whiteboard/boards` rather than `allEntries`.
      note: (row) => mapCountLabel(row),
      search: (row) => row.title || "",
      isOn: (row) => attachedBoards.some((b) => b.id === row.id),
      add: (row) => attachBoardToChat(row.id, row.title || "Mind map"),
      remove: (row) => {
        attachedBoards = attachedBoards.filter((b) => b.id !== row.id);
        renderBoardAttachments();
      },
      empty: "No mind maps yet.",
    };
  }
  if (source === "files") {
    return {
      id: (row) => row.id,
      label: (row) => row.original_name || "File",
      note: (row) => (row.mime || "").split("/").pop() || "file",
      search: (row) => `${row.original_name || ""} ${row.caption || ""}`,
      isOn: (row) => attachedFiles.some((f) => f.id === row.id),
      add: (row) => attachLibraryFile(row.id, row.original_name || "File"),
      remove: (row) => {
        attachedFiles = attachedFiles.filter((f) => f.id !== row.id);
        renderFileAttachments();
      },
      empty: "No files yet.",
    };
  }
  return {
    id: (row) => row.id,
    label: (row) => row.filename || row.original_name || "Image",
    //: **No chip at all on an image row.** It used to read "captioned" or
    //: "image", which was the only fact on the row besides a generated
    //: filename and answered a question nobody asks; now that the caption
    //: itself is on the row (`caption` below) a badge announcing one exists is
    //: noise. The obvious replacement, the kind of file the way the Files
    //: source chips it, would print "png" seventeen times down a list whose
    //: every row already ends in `.png`. The renderer drops an empty chip
    //: rather than drawing a pill with nothing in it.
    note: () => "",
    //: The picture itself, token-gated: an `<img src>` cannot send the auth
    //: header, and `mediaSrc` is how every other image surface in the app
    //: (the Library gallery, the OCR rail, a note's own thumbnails) puts a
    //: `/media/…` or `/files/{id}` url on an element. A `MediaUpload` row
    //: carries its url; an `Attachment` row's url is `/files/{id}`, which is
    //: why this reads `row.url` first and only falls back to the name.
    thumb: (row) => mediaSrc(row.url || `/media/${row.filename}`),
    //: The second line of the row, and the reason this source has one at all:
    //: a caption is a sentence about the picture, which is exactly what a
    //: filename like `WallpaperEngineOverride_randomODWVLK.jpg` is not. An
    //: uncaptioned image falls back to where it is used, which for a picture
    //: that arrived on a note is often the better identifier of the two ("in
    //: Weekly review" places it; "screenshot_20260114_113052.png" does not),
    //: and `used_by` is already on both of the row shapes this source merges.
    //: Failing both, the renderer says so rather than leaving the line out, so
    //: every row in the list stays one height.
    caption: (row) => {
      if (row.caption) return row.caption;
      const used = Array.isArray(row.used_by) ? row.used_by : [];
      const first = used[0]?.label;
      if (!first) return "";
      return used.length > 1 ? `In ${first} and ${used.length - 1} more` : `In ${first}`;
    },
    search: (row) => `${row.filename || ""} ${row.caption || ""}`,
    isOn: (row) => attachedImages.some((i) => i.id === row.id),
    //: An already-uploaded image is attached by *id*, with no staging step and
    //: no object URL: the bytes are already on the server, which is the whole
    //: difference between this and dropping a photo on the composer.
    add: (row) => {
      if (attachedImages.length >= 4) return false;
      attachedImages.push({
        id: row.id,
        url: row.url || `/media/${row.filename}`,
        name: row.filename || "Image",
      });
      renderImageAttachments();
      return true;
    },
    remove: (row) => {
      attachedImages = attachedImages.filter((i) => i.id !== row.id);
      renderImageAttachments();
    },
    empty: "No images yet.",
  };
}

async function renderNotePickerList() {
  const query = $("note-picker-search").value.trim().toLowerCase();
  const list = $("note-picker-list");
  if (notePickerSource !== "notes") {
    await renderNotePickerOtherSource(query, list);
    return;
  }
  list.replaceChildren();

  // Attached notes stay at the top even when the search wouldn't match them,
  // so ticking one never makes it vanish from under the pointer.
  const matches = allEntries.filter((entry) => {
    if (attachedNoteIds.includes(entry.id)) return true;
    if (!query) return true;
    const haystack = `${entry.content} ${(entry.tags || []).join(" ")} ${entry.category}`;
    return haystack.toLowerCase().includes(query);
  });
  matches.sort((a, b) => {
    const aSel = attachedNoteIds.includes(a.id) ? 0 : 1;
    const bSel = attachedNoteIds.includes(b.id) ? 0 : 1;
    return aSel - bSel;
  });

  if (!matches.length) {
    const empty = document.createElement("li");
    empty.className = "muted note-picker-empty";
    empty.textContent = query ? "No notes match that." : "No notes yet.";
    list.appendChild(empty);
  }

  for (const entry of matches.slice(0, 50)) {
    const li = document.createElement("li");
    const label = document.createElement("label");
    const box = document.createElement("input");
    box.type = "checkbox";
    box.checked = attachedNoteIds.includes(entry.id);
    box.addEventListener("change", () => {
      if (box.checked) {
        if (!attachedNoteIds.includes(entry.id)) attachedNoteIds.push(entry.id);
      } else {
        attachedNoteIds = attachedNoteIds.filter((id) => id !== entry.id);
      }
      renderAttachments();
      updateNotePickerCount();
    });
    const text = document.createElement("span");
    text.className = "note-picker-text";
    text.textContent = noteLabel(entry, 70);
    const cat = document.createElement("span");
    cat.className = "chip";
    cat.textContent = entry.category;
    label.append(box, text, cat);
    li.appendChild(label);
    list.appendChild(li);
  }
  updateNotePickerCount();
}

async function renderNotePickerOtherSource(query, list) {
  const source = notePickerSource;
  const shape = notePickerShape(source);
  const rows = (await notePickerRows(source)) || [];
  // The source can have been switched while the fetch was in flight.
  if (notePickerSource !== source) return;
  list.replaceChildren();
  const matches = rows.filter(
    (row) => shape.isOn(row) || !query || shape.search(row).toLowerCase().includes(query)
  );
  matches.sort((a, b) => (shape.isOn(a) ? 0 : 1) - (shape.isOn(b) ? 0 : 1));
  if (!matches.length) {
    const empty = document.createElement("li");
    empty.className = "muted note-picker-empty";
    empty.textContent = query ? "Nothing matches that." : shape.empty;
    list.appendChild(empty);
  }
  for (const row of matches.slice(0, 50)) {
    const li = document.createElement("li");
    const label = document.createElement("label");
    const box = document.createElement("input");
    box.type = "checkbox";
    box.checked = shape.isOn(row);
    box.addEventListener("change", () => {
      if (box.checked) {
        // Refused rather than silently dropped: the caps exist because four
        // whole files is already more than most local models can hold, and a
        // tick that comes straight back off with no explanation reads as a
        // broken checkbox.
        if (shape.add(row) === false) {
          box.checked = false;
          toast("That's as many as one message can carry.", true);
        }
      } else {
        shape.remove(row);
      }
      updateNotePickerCount();
    });
    const text = document.createElement("span");
    text.className = "note-picker-text";
    text.textContent = shape.label(row);
    const kind = document.createElement("span");
    kind.className = "chip";
    kind.textContent = shape.note(row);
    //: **A row that shows the thing, for the sources where the name is not the
    //: thing.** Reported with a screenshot of this list's Images tab: "images
    //: just show as their names but the user might not be able to tell what
    //: those images are from their names so they need to be rendered in some
    //: way". A camera or a wallpaper tool names a file for its own reasons, so
    //: five rows of `…_randomODWVLK.jpg` are five rows you cannot choose
    //: between.
    //:
    //: Offered by the shape table rather than branched on the source here, the
    //: same reason that table exists: `thumb` and `caption` are optional, and a
    //: source that has neither (a note, a document, a map) renders exactly the
    //: single-line row it rendered before. The `<img>` is the app's ordinary
    //: thumbnail machinery, a `mediaSrc`-signed url on a lazily loaded element,
    //: not a second way of showing a picture.
    const thumbUrl = shape.thumb?.(row);
    if (thumbUrl) {
      const thumb = document.createElement("span");
      thumb.className = "note-picker-thumb";
      const img = document.createElement("img");
      //: Empty alt, not the filename: the name is already the row's own text
      //: one element away, and a screen reader reading it twice per row is
      //: worse than the picture being announced at all. The picture is
      //: decoration *of that label*.
      img.alt = "";
      img.loading = "lazy";
      //: A file that has been deleted out from under the row leaves the frame
      //: rather than drawing the browser's torn-page glyph inside the list: the
      //: frame keeps the rows one height, which is the whole reason it is a
      //: wrapper and not a bare `<img>`.
      img.addEventListener("error", () => {
        img.remove();
        thumb.classList.add("is-missing");
      });
      img.src = thumbUrl;
      thumb.appendChild(img);
      label.append(box, thumb);
    } else {
      label.append(box);
    }
    const caption = shape.caption?.(row);
    if (caption !== undefined) {
      //: Two lines in one column so the caption wraps under the name and not
      //: under the checkbox, and so the chip stays on the row's own centre line
      //: rather than beside the first of the two lines.
      const lines = document.createElement("span");
      lines.className = "note-picker-lines";
      const cap = document.createElement("span");
      cap.className = "note-picker-caption";
      //: An uncaptioned image says so instead of collapsing to a one-line row:
      //: the list is scanned down the left edge, and rows of two different
      //: heights break that scan. It is also true, and this app can write one
      //: (the Library's caption action), so it reads as a thing to do rather
      //: than as missing data.
      cap.textContent = caption || "No caption yet";
      cap.classList.toggle("is-empty", !caption);
      if (caption) cap.title = caption;
      lines.append(text, cap);
      label.append(lines);
    } else {
      label.append(text);
    }
    //: A chip with nothing in it is a pill of empty space at the end of the
    //: row, so a source that has no one-word fact to add (Images, whose fact
    //: is the picture itself) simply does not get one.
    if (kind.textContent) label.append(kind);
    li.appendChild(label);
    list.appendChild(li);
  }
  updateNotePickerCount();
}

function updateNotePickerCount() {
  // Every source, not just notes: the panel is one picker over four stores
  // now, and a count that only ever mentioned notes would say "Nothing
  // attached yet" with three files ticked in front of you.
  const parts = [];
  if (attachedNoteIds.length) parts.push(`${attachedNoteIds.length} note${attachedNoteIds.length === 1 ? "" : "s"}`);
  if (attachedDocuments.length) parts.push(`${attachedDocuments.length} document${attachedDocuments.length === 1 ? "" : "s"}`);
  if (attachedFiles.length) parts.push(`${attachedFiles.length} file${attachedFiles.length === 1 ? "" : "s"}`);
  if (attachedImages.length) parts.push(`${attachedImages.length} image${attachedImages.length === 1 ? "" : "s"}`);
  if (attachedBoards.length) parts.push(`${attachedBoards.length} mind map${attachedBoards.length === 1 ? "" : "s"}`);
  $("note-picker-count").textContent = parts.length ? `${parts.join(", ")} attached` : "Nothing attached yet";
}

function openNotePicker() {
  $("note-picker-panel").classList.remove("hidden");
  $("attach-note").setAttribute("aria-expanded", "true");
  renderNotePickerList();
  $("note-picker-search").focus();
}

function closeNotePicker() {
  $("note-picker-panel").classList.add("hidden");
  $("attach-note").setAttribute("aria-expanded", "false");
}

function notePickerOpen() {
  return !$("note-picker-panel").classList.contains("hidden");
}

// The answer-length/persona disclosure (§37C): same open/close shape as the
// note picker above, just for a settings pair instead of a list.
function chatDockMoreOpen() {
  return !$("chat-dock-more-panel").classList.contains("hidden");
}

function openChatDockMore() {
  $("chat-dock-more-panel").classList.remove("hidden");
  $("chat-dock-more-btn").setAttribute("aria-expanded", "true");
}

function closeChatDockMore() {
  $("chat-dock-more-panel").classList.add("hidden");
  $("chat-dock-more-btn").setAttribute("aria-expanded", "false");
}

async function sendChatMessage(preset, opts = {}) {
  const input = $("chat-input");
  const status = $("chat-status");
  const typed = (preset ?? input.value).trim();
  if (!typed) return;

  // Plan mode is applied here, on the way out, rather than by whatever control
  // was pressed: so Send, Enter and a suggestion chip all get planned when the
  // mode is on. `opts.plan` means this message IS a plan already (the plan
  // runner re-sends through here), so it must not be planned again.
  //
  // The user's own words go in the bubble; the planning instruction is appended
  // for the model only. `displayText` already exists for exactly this.
  const planned = opts.plan || opts.skipPlanMode ? null : applyPlanMode(typed);
  let question = planned || typed;
  if (planned && !opts.displayText) opts = { ...opts, displayText: typed };
  //: **The selection joins the question here, and only for the model.** It is
  //: appended after Plan mode's own rewrite for the same reason that rewrite
  //: exists at all: `displayText` is what the user said, and showing them a
  //: block of their own note quoted back at them under their question would
  //: read as the app putting words in their mouth. The chip above the box is
  //: what tells them it is going.
  //:
  //: Re-validated at this moment rather than reused from when it was attached
  //:, see `revalidateSelection` for what changes in between and why sending
  //: stale offsets is the worst of the three outcomes.
  const sentSelection = attachedSelection ? revalidateSelection(attachedSelection) : null;
  if (sentSelection) {
    if (!opts.displayText) opts = { ...opts, displayText: typed };
    question = `${question}\n\n${selectionContextBlock(sentSelection)}`;
  }
  lastChatQuestion = question;

  // Consumed once: this send, button click or free-typed reply alike, is
  // the answer to whatever question was pending, and the next one after it
  // is an ordinary message again.
  const answeringAgent = opts.answeringAgent ?? chatAwaitingAgentAnswer;
  chatAwaitingAgentAnswer = false;

  // **Staged images become real uploads here**, at the moment the message is
  // actually committed: see `attachImageFiles` for why nothing was uploaded
  // when they were attached.
  //
  // Before the snapshot below, because that snapshot reads `img.id` and a
  // staged image has none until this runs. A failure stops the send and says
  // so: a message arriving without the picture it was written about is worse
  // than one that refuses and explains.
  if (!opts.imageMediaIds) {
    try {
      await commitStagedImages();
    } catch (error) {
      toast(error.message || "Couldn't upload the attached image.", true);
      return;
    }
  }

  // Snapshot the attachments for this message. A regenerate re-uses the same
  // ones; a fresh send clears them, so they don't silently ride along on
  // every later question.
  const sentAttachments = opts.noteIds || attachedNoteIds.slice();
  const sentImages = opts.imageMediaIds || attachedImages.map((img) => img.id);
  const sentDocuments = opts.documentIds || attachedDocuments.map((d) => d.id);
  const sentFiles = opts.fileIds || attachedFiles.map((f) => f.id);
  const sentBoards = opts.boardIds || attachedBoards.map((b) => b.id);
  // What the bubble will draw. Built here, while the composer still knows the
  // names and urls: after the clear below there is nothing left to build it
  // from, and a round trip to re-fetch what we already had would show the
  // message without its pictures for as long as that took.
  const sentAttachmentCards = opts.attachmentCards || [
    ...attachedImages.map((img) => ({
      kind: "image",
      id: img.id,
      url: img.url,
      name: img.name || "Attached image",
      // A just-uploaded image has no caption yet, captioning runs in the
      // background once the message commits it. Reopening the chat picks the
      // caption up from `GET /conversations/{id}`, which is where it lands.
      caption: "",
      text: "",
    })),
    ...attachedDocuments.map((d) => ({ kind: "document", id: d.id, name: d.name })),
    // Library files: the same card list as the other kinds, so the bubble
    // shows every reference the question was given rather than three of four.
    ...attachedFiles.map((f) => ({ kind: "file", id: f.id, name: f.name })),
    // A mind map, same card list again, the bubble has to show every
    // reference the question was given, and a map is the one whose absence
    // would be least obvious (its outline is invisible in the transcript).
    ...attachedBoards.map((b) => ({ kind: "map", id: b.id, name: b.name })),
    // The paperclip's own attachments. Same card list as the other two kinds
    // so the bubble shows every reference this question was given, not two of
    // the three.
    ...attachedNotes().map((entry) => ({
      kind: "note",
      id: entry.id,
      name: noteLabel(entry, 60),
    })),
  ];
  if (!opts.replaceLast) {
    // Remembered so a regenerate re-runs with the same references, by then
    // the picker has been cleared.
    lastChatAttachments = sentAttachments;
    lastChatImageAttachments = attachedImages.slice();
    lastChatDocumentAttachments = attachedDocuments.slice();
    lastChatFileAttachments = attachedFiles.slice();
    lastChatBoardAttachments = attachedBoards.slice();
    // The staged bytes are on the server now, so the local Blob references
    // are dead weight: an object URL lives as long as the document unless it
    // is revoked, and a chat session sending several images would hold every
    // one of them in memory for the life of the tab. The upload's real url is
    // what the sent bubble draws from, so nothing on screen depends on these.
    for (const image of attachedImages) {
      if (image.objectUrl) URL.revokeObjectURL(image.objectUrl);
      image.objectUrl = null;
    }
    attachedNoteIds = [];
    attachedImages = [];
    attachedDocuments = [];
    attachedFiles = [];
    attachedBoards = [];
    //: Cleared with the rest, and for the same stated reason: a selection that
    //: rode along on every later question would be the app answering about a
    //: paragraph the user stopped talking about three messages ago.
    attachedSelection = null;
    renderAttachments();
    renderImageAttachments();
    renderDocumentAttachments();
    renderFileAttachments();
    renderBoardAttachments();
    renderSelectionAttachment();
    closeNotePicker();
  }

  //: Same loan as in `openConversation`: `chatEmptyState` can have moved this
  //: element inside `#chat-messages`, and a caller that cleared the pane first
  //: would find it gone.
  $("chat-suggest")?.classList.add("hidden");
  input.value = "";
  autoGrow(input); // a cleared box must not keep the height of what was in it
  // The draft is gone, so the suggestions about it are too, including the
  // ones that were dismissed, which belonged to that draft and not to the
  // next one.
  resetChatNudge();
  input.disabled = true;
  hide("chat-send");
  show("chat-stop");
  status.classList.remove("error");
  status.textContent = "Searching your notes…";
  startChatTimer();

  // Regenerate re-runs the same question without adding a duplicate "you".
  //
  // `displayText` is what the *user* said when the message carries an
  // instruction they did not type, Plan Plan appends one. Showing the appended
  // sentence back to them would read as the app putting words in their mouth,
  // and hiding the request entirely would leave the plan looking as though it
  // came from nowhere; the button they pressed is the explanation.
  const userBubble = opts.skipUserBubble
    ? null
    : addBubble("user", opts.displayText || question, sentAttachmentCards);
  const { bubble, stepsHolder, recordsHolder, groundingHolder, timeline } = addAssistantBubble();
  // The live counter rides in the bubble it is timing, and leaves with it.
  mountChatTimer(bubble);
  // A newer answer exists, so the previous one's chips stop being the end of
  // the thread: this bubble is, and it has none yet.
  refreshFollowupVisibility();
  // A placeholder until the first event arrives; the first real step evicts it.
  const pending = document.createElement("div");
  pending.className = "agent-step step-pending";
  const pendingLine = progressLine("Thinking…");
  pending.appendChild(pendingLine);
  stepsHolder.appendChild(pending);
  // **The placeholder trails the work instead of vanishing at the first
  // event.** It used to `.remove()` itself the moment anything arrived, 
  // including `meta`, which this app emits almost immediately, so on a turn
  // that then spent eleven seconds thinking there was nothing left moving
  // anywhere in the bubble. Moving it to the end of the steps list keeps one
  // live "still working" line under whatever has happened so far, and the
  // `finally` that ends the stream is what actually takes it away.
  //: **The trailing line cannot come back once the turn is over**, and that
  //: is the whole of this flag.
  //:
  //: Reported with two screenshots: *"'writing the answer' gets stuck below
  //: the message once finished"*, including on a bubble whose own timer had
  //: stopped, so the turn had genuinely ended. `clearPending` *appends* the
  //: node, and appending a node that has already been removed **puts it
  //: back**. The `finally` at the end of the stream removes it; any callback
  //: still queued behind that, a last answer delta, a trailing tool event , 
  //: then re-attached it, with nothing left to take it down a second time.
  //:
  //: A flag rather than a re-check of `pending.isConnected`: the point is
  //: that the turn is over, not that the node happens to be detached right
  //: now, and saying so is what stops the next person re-introducing it.
  let turnEnded = false;
  const clearPending = () => {
    if (turnEnded) return;
    //: **Only when it is not already last**, and that guard is a bug fix, not
    //: a micro-optimisation.
    //:
    //: Reported: *"while generating the output, the 3 dot animation speeds up
    //: and freezes."* `onAnswer` calls this on **every streamed delta**, tens
    //: of times a second, and `appendChild` on a node that is already the
    //: last child still *removes and re-inserts* it. Blink restarts every CSS
    //: animation in a re-inserted subtree, so the three dots were being reset
    //: to frame zero on every token: they never got far enough through their
    //: 1.4s cycle to look like a cycle, which reads as a stutter that speeds
    //: up with the token rate and stalls whenever the stream pauses.
    //:
    //: Nothing else changes: the node still trails the steps, because the
    //: only case that actually needs a move is a *new* step having been
    //: appended after it.
    if (stepsHolder.lastElementChild === pending) return;
    stepsHolder.appendChild(pending);
  };
  // Every string this is given comes from an event that really happened, 
  // see `progressLine` on why it must never invent a stage.
  const say = (text) => pendingLine.setStatus?.(text);
  //: **The indicator's shape has to change with the stage, not just its
  //: words.** Reported, with a screenshot: *"it is still the 3-dot animation
  //: when the model is actively streaming text"*, beside the label "Writing
  //: the answer…", which is the tell. The label was being updated and the
  //: animation was not, because `say()` is the only thing this turn ever
  //: called: `progressLine` has exposed `setPhase` since the writing trace was
  //: built, and the *ask box* was wired to it (see `onAnswer` there) while the
  //: chat tab, the surface almost everyone uses, was not. A feature that
  //: only runs on one of its two call sites is this repo's "never executed"
  //: failure shape, one branch over.
  const phase = (name) => pendingLine.setPhase?.(name);
  // **The turn is marked as generating for its whole length, not just until
  // the first event.** Reported as "none of the generating animations work",
  // and this is the mechanism: `clearPending` above runs on the first event
  // of *any* kind: including `meta`, which this app emits almost
  // immediately, well before the model has produced a word. So the dots
  // appeared for a few hundred milliseconds and then the bubble sat
  // completely still for however long the model actually took, which reads
  // as nothing happening at all.
  //
  // A class on the bubble, cleared in the `finally` that ends the stream, is
  // the state that genuinely lasts as long as the work does, every step
  // that arrives can still evict its own placeholder without taking the
  // "still working" signal down with it.
  bubble.classList.add("is-generating");
  let meta = null;
  //: This turn's row in the Agent Activity panel, or null while the turn has
  //: done nothing worth a row. **Created lazily, on the first plan or the
  //: first tool call**, and that is deliberate: a plain question with a plain
  //: answer is not a "run", and a row per chat message would rebuild the wall
  //: of text this panel was just taken apart to stop being.
  let activityRun = null;
  let toolsActed = false;
  let stats = null;
  // Captured so the final save below can persist it. Reported directly: the
  // "Grounded in" chips under a direct Q&A answer only ever existed for the
  // live stream: reopening the chat, or leaving the tab and coming back,
  // showed an answer with no sources at all. Same unfixed-until-now shape as
  // raw_results/search_mode/match_info a few lines below, which got exactly
  // this treatment already for the same reported-missing-on-reload reason.
  let groundingSentences = null;
  // Whether the user pressed Stop. An empty answer they asked for needs no
  // explanation; one they didn't ask for does.
  let stopped = false;
  // Set when the agent ends its turn by handing the job to a saved skill.
  // The run can't start from inside the stream, this turn is still holding
  // the input box and the conversation, so it is remembered and started
  // once everything below has run.
  let handoff = null;
  // Set when the turn stopped because it ran out of rounds, and, for a skill
  // run: the step it did not get past. Both become a button at the end of the
  // bubble rather than a sentence asking the user to type "carry on".
  let ranOutOfRounds = false;
  let stoppedAtStep = null;
  let pausedForManual = false;
  const startedAt = performance.now();
  const toolEvents = []; // {label, ok}: persisted so chips survive a reload
  //: Everything this turn opened, deduped on kind+id, for the Sources panel.
  //: A Map rather than an array because a turn that reads the same note twice
  //: has one source, not two, and `touched` arrives per tool call.
  const touchedItems = new Map();
  chatController = new AbortController();
  const controller = chatController;

  // --- the turn owns its conversation ----------------------------------------
  //
  // Reported live: *"I clicked a suggested next response, then instantly
  // switched to a different chat and switched back. The latest input message
  // and the generating bubble disappeared, it still said the model is writing,
  // but nothing showed."*
  //
  // The visible half is the smaller half. `chatConv` is module-level and
  // **reassigned** (not mutated) by openConversation and newChatConversation,
  // and every save below used to read it *live*, at each checkpoint and again
  // when the turn finished, seconds or minutes after the send. So switching
  // conversations mid-stream did not just wipe the bubbles off the screen
  // (`replaceChildren`), it silently wrote the finished answer into **whichever
  // conversation happened to be open when it landed**, appending A's turn to
  // thread B, or, if the user had pressed "+ New", creating a fresh
  // conversation out of it. Nothing errored, and the turn really did appear
  // "later, after switching away and back", because by then it had been saved
  // somewhere.
  //
  // Pinning the object reference fixes both: `convRef` keeps pointing at the
  // conversation that asked the question no matter what the pane switches to,
  // and `viewing()` is then the honest test for "is this turn's own
  // conversation still the one on screen?", the only condition under which
  // this turn may touch the header, the usage meter, the composer, or the
  // transcript.
  const convRef = chatConv;
  const viewing = () => chatConv === convRef;

  // The live nodes, kept rather than abandoned.
  //
  // Reported after the first fix: switching away and back left the bubble
  // gone, the answer appearing only once it had finished, and an empty bubble
  // in its place. All three are the same cause, `openConversation` rebuilds
  // the transcript with `replaceChildren()`, so the nodes this turn is
  // streaming into are detached, and what the reader comes back to is the
  // thread as the *server* has it: without the unsaved turn, or with the
  // half-written checkpoint row, which is the empty bubble.
  //
  // Holding the elements means coming back can re-attach the very same ones,
  // still being written into, so the answer continues in front of the reader
  // instead of arriving all at once at the end.
  //
  // Set here, once, and never reassigned by a switch: the earlier version
  // recorded it inside `releaseChatComposer`, which runs on *every* switch, so
  // returning to the original chat relabelled the stream as belonging to
  // whichever thread had just been left. That is why the notice named the
  // wrong conversation.
  chatStreaming = {
    conv: convRef,
    title: $("chat-title").textContent || "that chat",
    nodes: [userBubble, bubble].filter(Boolean),
    announced: false,
  };

  // --- checkpointing a long turn --------------------------------------------
  // A row for this turn already exists, so the save at the end has to update
  // it rather than append a second copy of the same exchange.
  let checkpointed = false;
  let checkpointInFlight = false;

  // Write what the turn has so far. Called at each agent round boundary, so a
  // ten-minute run that dies at minute nine leaves nine minutes of work in the
  // conversation instead of nothing.
  //
  // One in flight at a time: rounds can finish close together, and two
  // creates racing each other would make two conversations out of one thread.
  async function checkpointTurn() {
    if (checkpointInFlight) return;
    checkpointInFlight = true;
    try {
      const partial = {
        question,
        answer: timeline.text(),
        thinking: timeline.thinkingText() || null,
        tools: toolEvents.length ? toolEvents : null,
        steps: timeline.serialise(),
        // No stats or elapsed yet, the turn is not over, and a half-turn's
        // numbers reported as final would be wrong rather than incomplete.
        image_media_ids: sentImages.length ? sentImages : null,
        document_ids: sentDocuments.length ? sentDocuments : null,
        file_ids: sentFiles.length ? sentFiles : null,
        note_ids: sentAttachments.length ? sentAttachments : null,
      };
      if (convRef.id === null) {
        const created = await apiJson("/conversations", {
          method: "POST",
          body: JSON.stringify(partial),
          silent: true,
        });
        convRef.id = created.id;
        if (viewing()) $("chat-title").textContent = created.title;
        applyPendingChatTitle(created.id, viewing());
        loadConversationList();
      } else if (checkpointed || opts.replaceLast) {
        await apiJson(`/conversations/${convRef.id}/turns/last`, {
          method: "PUT",
          body: JSON.stringify(partial),
          silent: true,
        });
      } else {
        await apiJson(`/conversations/${convRef.id}/turns`, {
          method: "POST",
          body: JSON.stringify(partial),
          silent: true,
        });
      }
      checkpointed = true;
    } catch {
      // Deliberately silent. This is insurance running behind a live answer;
      // a toast here would interrupt the thing it exists to protect, and the
      // save at the end of the turn reports its own failure.
    } finally {
      checkpointInFlight = false;
    }
  }

  // Captured once, not re-read at save time: the toggle can move on to the
  // next message while this one is still streaming, and the meta line and
  // the saved turn must both say what actually answered *this* question.
  const effectiveUseTools = opts.useTools ?? $("tools-toggle").checked;

  let slowLoadTimeout;
  try {
    slowLoadTimeout = setTimeout(() => {
      if (!meta && !stopped) {
        status.textContent = "Loading model… (this may take a moment)";
      }
    }, 5000);
    await streamChat({
      question,
      history: chatHistoryToSend(),
      persona: $("persona-select").value || null,
      mode: $("response-mode-select").value || null,
      useTools: effectiveUseTools,
      noteIds: sentAttachments,
      imageMediaIds: sentImages,
      documentIds: sentDocuments,
      fileIds: sentFiles,
      boardIds: sentBoards,
      skill: opts.skill,
      skillInputs: opts.skillInputs,
      skillFromStep: opts.skillFromStep,
      // Read live rather than captured at launch: a run that started
      // straight-through and is now being Resumed can still be switched to
      // step-by-step, and vice versa.
      skillManual: opts.skillManual ?? Boolean($("skill-manual-toggle")?.checked),
      skillManualNote: opts.skillManualNote,
      plan: opts.plan,
      attachedNotesOnly: opts.attachedNotesOnly,
      answeringAgent,
      signal: controller.signal,
      onMeta: (m) => {
        meta = m;
        status.textContent = "The model is writing…";
        const found = m?.raw_results?.length || 0;
        say(found ? `Read ${found} note${found === 1 ? "" : "s"}, writing…` : "Writing…");
      },
      onRelated: (event) => {
        renderRelatedElsewhere(groundingHolder, event.items);
      },
      onGrounding: (event) => {
        groundingSentences = event.sentences;
        renderAnswerGrounding(
          groundingHolder,
          event.sentences,
          meta?.raw_results || [],
          //: Every prose block of this turn, not the first: see
          //: `addInlineCitations`. A skill run has one per step.
          bubble.querySelectorAll(".bubble-answer"),
          //: The turn's own question, so opening a source here teaches the
          //: search the same thing it learns from the Ask tab.
          question
        );
      },
      onPlan: (event) => {
        clearPending();
        timeline.plan(event);
        // …and the same run as one row in the activity panel. Both are drawn
        // from this one event, so they cannot disagree about how many steps
        // there are or what the run is called.
        activityRun = addAgentRun({
          kind: event.kind === "plan" ? "plan" : "skill",
          name: event.skill || "Run",
          icon: event.kind === "plan" ? "ph:compass" : "ph:lightning",
          steps: event.steps || [],
        });
        openPanelForRun(activityRun);
        status.textContent =
          event.kind === "plan"
            ? `Working through ${(event.steps || []).length} steps…`
            : `Running “${event.skill}”…`;
        chatScrollToEnd();
      },
      onStep: (event) => {
        clearPending();
        timeline.step(event);
        agentRunStep(activityRun, event);
        if (event.state === "running") {
          status.textContent = `Step ${event.index + 1}: ${event.text}`;
        }
        chatScrollToEnd();
      },
      onResult: (event) => {
        clearPending();
        timeline.result(event);
        // Where the run stopped, if it did. A number here means the steps
        // after it never ran.
        stoppedAtStep = typeof event.stopped_at === "number" ? event.stopped_at : null;
        pausedForManual = Boolean(event.paused);
        // A skill that changed notes has just made the list on screen stale.
        if ((event.changes || []).length) loadEntries();
        chatScrollToEnd();
      },
      onLimit: () => {
        // Out of rounds with tools still in flight. Only remembered here: the
        // offer to continue belongs beneath the answer that says it stopped,
        // and that answer has not been written yet.
        ranOutOfRounds = true;
      },
      onThinking: (delta) => {
        clearPending();
        timeline.thinking(delta);
        //: Reasoning is still waiting, as far as the reader is concerned:
        //: nothing of the answer exists yet. Set explicitly rather than left
        //: alone, so a turn that thinks *after* writing goes back to dots.
        phase("thinking");
        status.textContent = "The model is thinking…";
        chatScrollToEnd();
      },
      onAnswer: (delta) => {
        clearPending();
        timeline.answer(delta);
        phase("writing");
        status.textContent = "The model is writing…";
        say("Writing the answer…");
        chatScrollToEnd();
      },
      onTool: (event) => {
        clearPending();
        //: The fallback strips the failed call's own icon token before
        //: prefixing the warning one. `setLabel` only resolves a token at the
        //: start of the string, so `ph:warning ph:books Listed notes` renders
        //: one warning glyph and then prints "ph:books" as literal text: 
        //: the same defect reported in the palette's status line, one branch
        //: over and only reachable when a tool fails.
        const label = event.ok
          ? event.label
          : `ph:warning ${(event.error || event.label || "").replace(/^ph:[\w-]+\s*/, "")}`;
        timeline.tool(toolChip(label, event.ok, event));
        //: The same call, filed in the panel under the step that made it. A
        //: second `toolChip` rather than the same node: one element cannot be
        //: in two places, and the panel's copy has to survive the chat being
        //: cleared or the conversation being closed.
        if (!activityRun) {
          // An agent turn with no plan is still a run, it is what the report
          // called "agent model activity", and its first tool call is the
          // moment it becomes one.
          activityRun = addAgentRun({
            kind: "agent",
            name: agentRunTitle(question),
            icon: "ph:robot",
          });
          openPanelForRun(activityRun);
        }
        agentRunTool(activityRun, toolChip(label, event.ok, event));
        toolEvents.push(event); // remember for persistence
        for (const item of event.touched || []) {
          touchedItems.set(`${item.kind}:${item.id}`, item);
        }
        if (event.proposal) {
          // Asked where it was suggested, not in a settings page nobody opens.
          const card = document.createElement("div");
          renderMemoryProposal(card, event.proposal);
          timeline.tool(card.firstElementChild || card);
        }
        if (event.ok) toolsActed = true;
        status.textContent = "The model is making changes…";
        // The tool's own label, so the line under the timeline names the
        // step that is running rather than a generic "working".
        say((event.label || "Working…").replace(/^ph:[\w-]+\s*/, ""));
        chatScrollToEnd();
      },
      onConfirm: (event) => {
        clearPending();
        const card = document.createElement("div");
        renderToolConfirm(card, event);
        timeline.tool(card.firstElementChild || card);
        status.textContent = "Waiting for your confirmation…";
      },
      onAsk: (event) => {
        clearPending();
        //: **The question is output, not a step.**
        //:
        //: Reported: *"the question the agent asked me appeared in the step
        //: and not the actual output."* A step group folds itself shut into
        //: "Finished 1 step" the moment prose starts (`startAnswer`), so a
        //: question filed there is a question that disappears while it is
        //: still waiting to be answered, and the answer box underneath then
        //: says the model wrote nothing, which is the screenshot.
        //:
        //: `recordsHolder` is the bubble's own output area, under the steps
        //: and above the sources, where everything else the turn is waiting
        //: on (a confirmation, a memory proposal's outcome) already lands.
        const card = document.createElement("div");
        renderAgentQuestion(card, event);
        recordsHolder.appendChild(card.firstElementChild || card);
        status.textContent = "Waiting for your answer…";
        chatAwaitingAgentAnswer = true;
      },
      onRunSkill: (event) => {
        // The model picked a saved skill for this job (§33). Its turn is over;
        // the run starts below, once this one has finished tidying up.
        clearPending();
        timeline.tool(toolChip(event.label, true));
        toolEvents.push({ label: event.label, ok: true });
        status.textContent = `Starting “${event.skill}”…`;
        handoff = event;
        chatScrollToEnd();
      },
      onRunPlan: (event) => {
        // The model decided the job has several parts and planned it (§35K).
        // Same handover as a skill: the turn is over and the steps run one at
        // a time below, so nothing is left half-done.
        clearPending();
        timeline.tool(toolChip(event.label, true));
        toolEvents.push({ label: event.label, ok: true });
        status.textContent = "Working out the steps…";
        handoff = event;
        chatScrollToEnd();
      },
      onCompressReview: (event) => {
        // The model asked to compress the chat (§37I). Unlike run_skill/
        // run_plan this isn't a run to start, it opens the same review
        // panel the manual Compress button fills in, and the summary is
        // used only if the user presses Apply there. Not set on `handoff`:
        // that path always starts something; this one waits for a person.
        clearPending();
        const label = "ph:arrows-in Suggested compressing the earlier messages";
        timeline.tool(toolChip(label, true));
        toolEvents.push({ label, ok: true });
        showCompressReview(event, event.turns);
        status.textContent = "Waiting for you to review the summary…";
        chatScrollToEnd();
      },
      onStats: (event) => {
        // A round finished. Asked for directly: *"a new chat should be saved
        // after agent turns as well, not after the whole response is
        // complete."* Correct, and the reason is that an agent turn is minutes
        // of work on a local model, closing the window, a stall, or the
        // server going away halfway through used to lose **the entire
        // conversation**, because nothing was written until the last round
        // returned. A checkpoint per round means the worst case is losing the
        // round in progress rather than the thread.
        //
        // Fire-and-forget, and silent: a checkpoint that interrupts the answer
        // to complain about the network would be worse than the data loss it
        // is preventing. The turn's real save still happens at the end and
        // overwrites this with the finished version.
        if (event.round) checkpointTurn();
        //: The header's context meter, updated live rather than at the end of
        //: the turn: on a long agent run the window fills round by round, and
        //: the number is only useful while there is still a decision to make
        //: about it.
        renderChatContextMeter(event);
        // An agent turn reports once per round, so these accumulate: output
        // tokens and generation time add up, while the prompt size is the
        // largest context the model was given rather than the sum.
        if (!stats) {
          stats = { ...event };
          return;
        }
        stats.model = event.model || stats.model;
        stats.prompt_tokens = Math.max(stats.prompt_tokens || 0, event.prompt_tokens || 0);
        stats.output_tokens = (stats.output_tokens || 0) + (event.output_tokens || 0);
        stats.eval_ms = (stats.eval_ms || 0) + (event.eval_ms || 0);
        // The agent tags each round; the highest is how many it took.
        stats.round = Math.max(stats.round || 0, event.round || 0);
        // The window doesn't change between rounds, but the peak prompt does, 
        // and the peak is the one worth reporting, because it is the round
        // that came closest to overflowing.
        stats.context_tokens = event.context_tokens || stats.context_tokens;
        // One estimated round makes the whole total an estimate. Reporting a
        // mixed figure as measured would be the dishonest way round.
        if (event.usage_source === "estimated") stats.usage_source = "estimated";
      },
    });
    if (viewing()) status.textContent = "";
  } catch (error) {
    if (error.name === "AbortError") {
      stopped = true;
      if (viewing()) status.textContent = "Stopped.";
    } else {
      // The timeline is this turn's own, detached or not, so it is always
      // marked failed; only the shared status line is conditional.
      timeline.failRunningStep("Failed due to error");
      if (viewing()) {
        status.textContent = error.message;
        status.classList.add("error");
      }
    }
  } finally {
    clearTimeout(slowLoadTimeout);
    // Whatever happened, answered, stopped, errored, the turn is no longer
    // generating, so the signal that says it is has to come down here rather
    // than on any one success path.
    bubble.classList.remove("is-generating");
    // The one place the trailing progress line is taken down, the turn is
    // genuinely over here, whether it ended, errored or was aborted. The flag
    // goes up *first*: see `clearPending` for the callback that used to run
    // after this line and put the node straight back.
    turnEnded = true;
    pending.remove();
    //: **Every visual "still working" state comes down here, on every exit.**
    //:
    //: Reported with a screenshot of a finished skill run still showing both
    //: the streaming caret and "Writing the answer…". `finalise()` was called
    //: on the success path only, so a turn that ended any other way, an
    //: error, a stop, the round limit, kept the caret blinking on prose that
    //: had stopped arriving. It is idempotent, so calling it here as well
    //: costs nothing and closes every path at once, which is the property the
    //: success-path-only version could never have.
    timeline.finalise?.();
    //: Whatever step group is still open stops saying "Working", see
    //: `agentTimeline.finish`.
    timeline.finish?.();
    //: …and the same for this turn's row in the activity panel, on the same
    //: every-exit reasoning: a row still saying "Running" after the turn
    //: errored or was stopped is the panel telling a lie for the rest of the
    //: session. `stoppedAtStep`/`pausedForManual` come from the `result`
    //: event, so the row can say *how* it ended rather than only that it did.
    endAgentRun(activityRun, {
      state: stopped
        ? "stalled"
        : pausedForManual
          ? "paused"
          : typeof stoppedAtStep === "number"
            ? activityRun?.steps?.[stoppedAtStep]?.state === "failed"
              ? "failed"
              : "stalled"
            : "done",
    });
    // Only if it is still ours. Switching away and sending a second message
    // installs a new controller, and this line firing late would null it, 
    // leaving Stop wired to nothing while a stream was genuinely running.
    if (chatController === controller) {
      chatController = null;
      stopChatTimer();
      // The turn is over: it is saved (or about to be) and a reload of this
      // thread will render it like any other. Re-attaching these nodes after
      // that point would show it twice.
      if (chatStreaming && chatStreaming.conv === convRef) chatStreaming = null;
    }
    // The composer belongs to whatever conversation is on screen. A turn that
    // finishes after the reader has moved on must not re-enable, refocus or
    // re-label the box they are now typing into, releaseChatComposer already
    // put it back when they switched.
    if (viewing()) {
      input.disabled = false;
      show("chat-send");
      hide("chat-stop");
      input.focus();
    }
  }

  clearPending();
  timeline.finalise();
  //: **The citations go back in after the final render.** Same defect as the
  //: Ask box's, one surface over and for the same reason: `onGrounding` writes
  //: the markers straight into the answer during the stream, and `finalise()`
  //: re-renders every prose step from its raw markdown, throwing all of them
  //: away a few milliseconds later. The grounding event always arrives before
  //: `done`, so this was true of every answer that had any.
  //: Built once, here, and handed to both the citation pass and the panel,
  //: so the digit in the prose and the digit on the row are the same number
  //: by construction rather than by two functions agreeing about order.
  const turnSources = chatSourcesFrom({
    meta,
    toolEvents,
    touched: [...touchedItems.values()],
  });
  if (groundingSentences?.length) {
    addInlineCitations(
      bubble.querySelectorAll(".bubble-answer"),
      groundingSentences,
      meta?.raw_results || [],
      turnSources
    );
  }
  const answerRaw = timeline.text();
  const thinkingRaw = timeline.thinkingText();
  //: **The Sources panel replaces the old "N matching notes" disclosure here.**
  //: It is a superset, it carries the same retrieved notes and adds the
  //: files and pages the turn read and the things it opened, which had no
  //: home at all. `renderRecordsDetails` stays for the Ask tab, which has one
  //: answer rather than a thread and no tool events to fold in.
  const sourcesPanel = chatSourcesPanel({
    meta,
    toolEvents,
    touched: [...touchedItems.values()],
    sources: turnSources,
  });
  if (sourcesPanel) recordsHolder.appendChild(sourcesPanel);
  // What this answer cost: model, wall-clock time, tokens, speed.
  const elapsedMs = Math.round(performance.now() - startedAt);
  // A turn that only ran tools still cost time and tokens, so it gets a meta
  // line too: previously an agent turn with no prose showed nothing at all.
  if (answerRaw || toolEvents.length) {
    bubble.appendChild(
      messageMetaLine({
        model: (stats && stats.model) || (meta && meta.answered_by),
        elapsedMs,
        stats,
        toolCount: toolEvents.length,
        rounds: (stats && stats.round) || 0,
        usedTools: effectiveUseTools,
      })
    );
  }
  // A turn that stopped short offers the way onward, in the two shapes it can
  // take. Not shown when the user pressed Stop, they know why it ended, and
  // not when a skill run finished every step it had.
  // A run that stopped early is exactly the kind of thing you find out about
  // ten minutes later, having walked away from a long job (§36E). The Resume
  // button below is the fix in the moment; this is the record afterwards.
  // A deliberate manual-mode pause is not a failure and not something to
  // notify about ten minutes later, the person is sitting right here
  // waiting for the Continue button, which is the whole point of asking for
  // it. Only an *unplanned* stop (a real failure, or running out of rounds)
  // earns the notification.
  if (!stopped && !pausedForManual && (stoppedAtStep !== null || ranOutOfRounds)) {
    recordNotification({
      kind: "run",
      title: opts.skill ? `“${opts.skill}” stopped early` : "A long answer stopped early",
      detail:
        stoppedAtStep !== null
          ? `Got as far as step ${stoppedAtStep + 1}. Reopen the chat to resume.`
          : "It ran out of rounds. Reopen the chat to continue.",
      key: `run:${opts.skill || "answer"}:${Date.now()}`,
      action: { tab: "chat" },
    });
  }
  //: **A run you stopped can be picked up again.** Reported: "cant continue
  //: canceled skills??", and it was exactly that, every resume control below
  //: was guarded by `!stopped`. The guard belongs on the *notification* above
  //: (nobody wants to be told ten minutes later about a stop they chose) and
  //: never belonged on the button: pressing Stop means "not right now", not
  //: "throw away the six steps that already ran". Resuming a stopped run is
  //: the same call as resuming one that hit the round limit, and the step it
  //: reached was already being tracked for the other case.
  if (stopped && stoppedAtStep !== null && opts.skill) {
    bubble.appendChild(
      continueRunControls({
        label: `ph:play Resume from step ${stoppedAtStep + 1}`,
        hint: "You stopped this. Earlier steps are not repeated.",
        onClick: () =>
          sendChatMessage(`${opts.skill}: from step ${stoppedAtStep + 1}`, {
            skill: opts.skill,
            skillInputs: opts.skillInputs || {},
            skillFromStep: stoppedAtStep,
            skipPlanMode: true,
          }),
      })
    );
  } else if (stopped && (opts.skill || toolEvents.length)) {
    //: A stopped run with no step to name, a plain agent turn, or a skill
    //: stopped before its first step finished. It still did work worth not
    //: repeating, so the offer is the same one the round limit gets.
    bubble.appendChild(
      continueRunControls({
        label: "ph:play Resume",
        hint: "Picks up from what it had already done.",
        onClick: () =>
          sendChatMessage(
            "Continue from where you stopped. Don't redo what you have " +
              "already done: carry on with what is left, and say when it is " +
              "all finished.",
            { useTools: true }
          ),
      })
    );
  } else if (!stopped && stoppedAtStep !== null && opts.skill && pausedForManual) {
    bubble.appendChild(
      manualPauseControls({
        onContinue: (note) =>
          sendChatMessage(`${opts.skill}: from step ${stoppedAtStep + 1}`, {
            skill: opts.skill,
            skillInputs: opts.skillInputs || {},
            skillFromStep: stoppedAtStep,
            skillManual: true,
            skillManualNote: note,
            skipPlanMode: true,
          }),
      })
    );
  } else if (!stopped && stoppedAtStep !== null && opts.skill) {
    bubble.appendChild(
      continueRunControls({
        label: `ph:arrow-clockwise Resume from step ${stoppedAtStep + 1}`,
        hint: "Earlier steps are not repeated.",
        onClick: () =>
          sendChatMessage(`${opts.skill}: from step ${stoppedAtStep + 1}`, {
            skill: opts.skill,
            skillInputs: opts.skillInputs || {},
            skillFromStep: stoppedAtStep,
            skipPlanMode: true,
          }),
      })
    );
  } else if (!stopped && ranOutOfRounds) {
    bubble.appendChild(
      continueRunControls({
        label: "→ Continue",
        hint: "Picks up from what it had already done.",
        onClick: () =>
          sendChatMessage(
            "Continue from where you stopped. Don't redo what you have " +
              "already done: carry on with what is left, and say when it is " +
              "all finished.",
            { useTools: true }
          ),
      })
    );
  }
  chatScrollToEnd();
  if (toolsActed) refreshAfterToolChanges(); // the AI changed real data
  if (handoff) {
    // Start the run as its own message, down the same path the Skill dropdown
    // uses: so the plan, the ticked steps, the change list and every Undo
    // work here exactly as they do when the user picks the skill themselves.
    // Deferred by a task because this turn is still finishing: it re-enables
    // the input box in `finally`, and the run needs to disable it again.
    const start =
      handoff.type === "run_plan"
        ? () => startPlannedRun(handoff.goal, handoff.steps)
        : () => startSkill({ name: handoff.skill }, handoff.inputs || {});
    setTimeout(start, 0);
  }
  if (!answerRaw) {
    // The model returned nothing. This used to return early and leave the
    // bubble sitting there with the notes disclosure, no answer, no error and
    // no buttons: a dead end with nothing to click and nothing explaining it.
    if (opts.replaceLast) {
      // A regenerate already removed the old answer; don't leave a blank in
      // its place, since the previous one is gone either way.
      bubble.remove();
      toast("The model returned nothing that time. Try again.", true);
      return;
    }
    // A turn that ended by starting a skill said nothing on purpose, the run
    // below is the answer. Complaining that the model wrote nothing would be
    // wrong, and the retry button would re-run the choosing turn rather than
    // the skill.
    if (!stopped && !handoff) {
      const note = document.createElement("p");
      note.className = "muted";
      note.textContent =
        "The model finished without writing anything. That usually means it ran " +
        "out of context or the model is struggling with this question, try again, " +
        "or rephrase it.";
      timeline.ensureAnswerBox().replaceChildren(note);
      // Retry and delete at minimum, so there's always a way forward.
      bubble.appendChild(
        chatMessageActions([
          { label: "ph:arrow-clockwise", title: "Try again", onClick: () => regenerateLastAnswer() },
          { label: "ph:trash", title: "Delete this message", onClick: () => removeChatBubble(bubble) },
        ])
      );
      chatScrollToEnd();
    }
    return;
  }
  // Per-message actions: one shared list with the reopened-conversation path,
  // see `assistantMessageActions` for why that matters.
  bubble.appendChild(
    assistantMessageActions({ bubble, text: answerRaw, question })
  );

  // Regenerate replaces the last turn; a normal send appends a new one.
  if (opts.replaceLast && convRef.turns.length) {
    convRef.turns[convRef.turns.length - 1] = { question, answer: answerRaw };
  } else {
    convRef.turns.push({ question, answer: answerRaw });
  }
  // Persist the finished turn so the chat survives restarts.
  try {
    const payload = {
      question,
      answer: answerRaw,
      thinking: thinkingRaw || null,
      tools: toolEvents.length ? toolEvents : null,
      // The run in the order it happened, so reopening the chat shows the
      // same step-by-step process rather than a flattened summary.
      steps: timeline.serialise(),
      // What this turn cost, so the conversation can show a running total.
      // Prompt + output, because both were sent through the model.
      tokens: stats
        ? (stats.prompt_tokens || 0) + (stats.output_tokens || 0)
        : null,
      // The whole metadata line, not just its total. `tokens` above is a sum,
      // which is right for the conversation's running total and useless for
      // rebuilding "3.9k/8k window · 12 tok/s · llama3.2", so on reload the
      // line used to vanish and the answer looked like it came from nowhere.
      stats: stats || null,
      // §89.4: which mode actually answered this turn (Ask vs. Agent): a
      // conversation can span mode switches, so this has to be per-turn, not
      // read off the toggle's current state on reload.
      used_tools: effectiveUseTools,
      // How long the answer took, measured here because the client is the only
      // thing that saw the whole turn: the server reports per-round timings,
      // and an agent turn is several rounds plus the tool calls between them.
      elapsed_ms: elapsedMs,
      // The "N matching notes" disclosure's own data. Reported: "semantic
      // search results in chat messages keep disappearing" - true on every
      // reload, since none of this was ever saved. Only meaningful for a
      // grounded (non-conversational) turn that actually searched, so
      // omitted rather than sent empty when there's nothing to show.
      raw_results: meta?.raw_results?.length ? meta.raw_results : null,
      search_mode: meta?.search_mode || null,
      match_info: meta?.match_info && Object.keys(meta.match_info).length ? meta.match_info : null,
      connected_ids: meta?.connected_ids?.length ? meta.connected_ids : null,
      // The "Grounded in" chips' own data: same reasoning as raw_results
      // just above. Only meaningful alongside raw_results (renderAnswerGrounding
      // looks note content up in it), so there's nothing to persist without it.
      sentence_grounding: groundingSentences?.length ? groundingSentences : null,
      // Which uploads this turn actually used, asked for directly: without
      // this, a sent chat image had no record anywhere that anything still
      // used it, so the Library's "Clean orphaned media" tool (which can
      // only check notes, documents and whiteboard content for `/media/…`
      // references) would delete a real, sent attachment's file the moment
      // someone ran it. Persisting the ids here is what lets media_gc.py
      // recognise them as still in use.
      image_media_ids: sentImages.length ? sentImages : null,
      // Same reason as the ids above, one kind over: a document attached to a
      // message is what lets the bubble draw its chip again on reopen.
      document_ids: sentDocuments.length ? sentDocuments : null,
      file_ids: sentFiles.length ? sentFiles : null,
      // And the notes clipped with the paperclip, which until now were used to
      // build one prompt and then forgotten, the bubble showed no sign the
      // answer had been given a note to read.
      note_ids: sentAttachments.length ? sentAttachments : null,
    };
    if (convRef.id === null) {
      const created = await apiJson("/conversations", {
        method: "POST",
        body: JSON.stringify(payload),
      });
      convRef.id = created.id;
      if (viewing()) {
        $("chat-title").textContent = created.title;
        renderChatUsage(created.tokens);
      }
      // A name typed before the first message was sent beats both the
      // question-derived title and the model's. See `renameCurrentConversation`.
      const namedByHand = applyPendingChatTitle(created.id, viewing());
      // Let the AI name the thread once there's something to name. Silent
      // best-effort: the question-derived title stays if the model can't.
      if (!namedByHand) {
        apiJson(`/conversations/${created.id}/retitle`, { method: "POST", silent: true })
          .then((named) => {
            if (chatConv.id === created.id) $("chat-title").textContent = named.title;
            loadConversationList();
          })
          .catch(() => {});
      }
    } else if (opts.replaceLast || checkpointed) {
      // `checkpointed` matters as much as `replaceLast` here: a long agent
      // turn has already written a row for this exchange (see checkpointTurn),
      // so appending would leave the conversation holding the same question
      // twice: once half-finished and once complete.
      const saved = await apiJson(`/conversations/${convRef.id}/turns/last`, {
        method: "PUT",
        body: JSON.stringify(payload),
      });
      if (viewing()) renderChatUsage(saved.tokens);
    } else {
      const saved = await apiJson(`/conversations/${convRef.id}/turns`, {
        method: "POST",
        body: JSON.stringify(payload),
      });
      if (viewing()) renderChatUsage(saved.tokens);
    }
    loadConversationList();
  } catch {
    toast("Couldn't save this chat turn.", true);
  }
  loadRecentQuestions();
  loadMostUsed();
  // Last, and deliberately not awaited: the answer is already on screen and
  // saved, and this is a second model call. See offerFollowups.
  offerFollowups(bubble, question, answerRaw);
}

// --- "what to ask next" chips under a finished answer -------------------------
//
// The empty-state chips (loadChatSuggestions) taught the feature for the first
// question and then went away, which left every turn after it ending on a blank
// box. These are the same idea for the turn you just read.
//
// Three things this must not do, all of which are why it lives out here rather
// than inside the streaming loop:
//
// - **Delay the answer.** It fires after the turn is rendered and saved, and
//   nothing awaits it.
// - **Show an error.** `/chat/followups` returns [] on every failure path
//   including the AI being off, and [] renders nothing at all. A row that says
//   "couldn't suggest anything" is worse than no row.
// - **Attach to the wrong bubble.** The reply can land after the reader has
//   sent another message or opened a different conversation, so the bubble it
//   was asked for has to still be on screen when it does.
async function offerFollowups(bubble, question, answer) {
  if (!bubble || !question || !answer) return;
  let picks = [];
  try {
    picks = await apiJson("/chat/followups", {
      method: "POST",
      silent: true,
      body: JSON.stringify({ question, answer }),
    });
  } catch {
    return; // no honest error state for a suggestion, see the module note
  }
  if (!Array.isArray(picks) || !picks.length) return;
  // `isConnected` is the check that matters: a deleted turn, a cleared chat or
  // a switched conversation all detach the bubble, and appending to a detached
  // node is an invisible leak rather than a visible bug.
  if (!bubble.isConnected) return;
  renderFollowups(bubble, picks);
  // Saved, so they are still there next time. Reported directly: "suggested
  // repsponse continuation prompts in chat doesnt persist and disappears once
  // I switch chat sessions or quit the app", they never persisted because
  // nothing stored them; they lived only on this DOM node.
  //
  // Not awaited and silent, for the same reason the request above is: this is
  // bookkeeping behind a suggestion, and a failed save must not put an error
  // on screen over an answer that is fine.
  saveFollowups(bubble, picks);
}

// The strip itself, shared by the live path above and the reopen path in
// `openConversation`, two renderers would be two chances for a saved chip to
// look unlike a fresh one.
function renderFollowups(bubble, picks) {
  if (!bubble || !Array.isArray(picks) || !picks.length) return;
  // Remembered on the bubble rather than only drawn on it. Reported: *"the
  // suggested next responses on chat messages should only persist for the
  // latest chat message… if the user deletes the latest message they sent,
  // then new suggested responses should show for the now latest message"*, 
  // the second half is the reason this is stored instead of discarded. The
  // chips for an older turn are still the right chips for it; they are simply
  // not shown while a newer turn exists, and deleting that newer turn has to
  // bring them back without a second round trip to the model.
  bubble.dataset.followups = JSON.stringify(picks);
  refreshFollowupVisibility();
}

// Exactly one strip in the thread, on the last answer in it.
//
// Chips under an older answer are an invitation to fork the conversation
// backwards: clicking one sends its question as a *new* message at the end, so
// the suggestion and the place the reply lands are three exchanges apart. Only
// the newest answer is still the end of the thread, so only it gets them.
function refreshFollowupVisibility() {
  const bubbles = [...$("chat-messages").querySelectorAll(".msg.assistant")];
  const last = bubbles.at(-1);
  for (const bubble of bubbles) {
    const strip = bubble.querySelector(".chat-followups");
    if (bubble !== last) {
      strip?.remove();
      continue;
    }
    if (strip) continue; // already showing this turn's chips
    let picks = [];
    try {
      picks = JSON.parse(bubble.dataset.followups || "[]");
    } catch {
      picks = [];
    }
    if (picks.length) buildFollowupStrip(bubble, picks);
  }
}

function buildFollowupStrip(bubble, picks) {
  const strip = document.createElement("div");
  strip.className = "chat-followups";
  const label = document.createElement("span");
  label.className = "muted";
  label.textContent = "Next:";
  strip.appendChild(label);
  for (const pick of picks) {
    // chip()'s second argument is a class, not a tooltip, passing prose there
    // would put a sentence into `className`.
    strip.appendChild(chip(pick, "", () => sendChatMessage(pick)));
  }
  bubble.appendChild(strip);
  chatScrollToEnd();
}

async function saveFollowups(bubble, picks) {
  if (chatConv.id === null) return; // an unsaved chat has no turn to attach to
  // Which turn this bubble is: its index among the assistant bubbles, which is
  // exactly how every other per-turn endpoint in this file addresses one.
  const bubbles = [...$("chat-messages").querySelectorAll(".msg.assistant")];
  const index = bubbles.indexOf(bubble);
  if (index === -1) return;
  const conversationId = chatConv.id;
  await apiJson(`/conversations/${conversationId}/turns/${index}/followups`, {
    method: "PUT",
    silent: true,
    body: JSON.stringify({ followups: picks }),
  }).catch(() => {});
}

// Delete one Q&A exchange: its assistant bubble AND the user bubble just
// above it, from the screen, memory, and the saved conversation.
async function deleteChatTurn(assistantBubble) {
  if (chatController) return; // don't edit a chat mid-stream
  const bubbles = [...$("chat-messages").querySelectorAll(".msg.assistant")];
  const index = bubbles.indexOf(assistantBubble);
  if (index === -1) return;
  if (!(await confirmDialog("Delete this message?"))) return;

  if (chatConv.id !== null) {
    try {
      const result = await apiJson(`/conversations/${chatConv.id}/turns/${index}`, {
        method: "DELETE",
      });
      if (result.conversation_deleted) {
        newChatConversation();
        loadConversationList();
        return;
      }
    } catch {
      toast("Couldn't delete that message.", true);
      return;
    }
  }
  // The user bubble is the one immediately before this assistant bubble.
  const userBubble = assistantBubble.previousElementSibling;
  if (userBubble && userBubble.classList.contains("user")) userBubble.remove();
  assistantBubble.remove();
  chatConv.turns.splice(index, 1);
  // The turn below is the end of the thread now, so its saved chips come back.
  refreshFollowupVisibility();
  if (!$("chat-messages").querySelector(".msg")) renderChatEmptyState();
  loadConversationList();
}

// --- leaving a conversation while it is still answering ------------------------
//
// The stream is pinned to the conversation that started it (see `convRef` in
// sendChatMessage), so switching away no longer misfiles the answer. What is
// left is the composer, which is shared: it was disabled with Stop showing for
// a turn that is no longer on screen, and the conversation being switched *to*
// inherited that state: the reported *"it still said the model is writing, but
// nothing showed"*.
//
// So the composer is handed back to whatever is on screen now, while the stream
// keeps running underneath. Deliberately NOT an abort: the reader asked a
// question and is owed the answer, and it will be saved to the thread that
// asked it and appear there. Saying so once is the difference between a
// background job and a lost message.
//
// `chatStreaming` below holds the live nodes as well as the identity, because
// the pane can be switched back long before the turn finishes, and the useful
// thing to do then is put the same still-streaming elements back, not describe
// them.
//: The turn currently being streamed, if any: which conversation it belongs
//: to, that conversation's title *at the time it was sent*, and the live DOM
//: nodes it is being written into. Set once in sendChatMessage and cleared
//: when the stream ends, never reassigned by a switch, which is what made an
//: earlier version name the wrong conversation.
let chatStreaming = null;

// --- how long this answer has been coming --------------------------------------
//
// Asked for directly: "can there be an active timer on responses in chatg
// messages as well??" The finished time was already in each message's metadata
// line; what was missing was the *live* one, and that is the one that matters
//, a local model on a long question can be silent for a minute, and "The
// model is writing…" is equally true at two seconds and at two minutes.
//
// Ticked from a timer rather than from stream events on purpose: the seconds
// have to keep moving while the model is thinking and sending nothing, which
// is exactly the stretch that makes someone wonder if it has hung.
//
// Where it is drawn changed after a second report: *"the time of response
// stays below the chat input bar and doesnt disappear, I want the timer to
// appear on the chat bubble while it is responding until the response is
// finished."* Both halves are the same mistake, the counter lived in the
// composer, which is not where the answer is being written and is not
// unmounted when the answer ends, so it sat under the input box afterwards
// reading as the age of something that had already arrived. It now rides in
// the bubble it is timing and is removed when that bubble is finished; the
// metadata line under the answer keeps the final duration permanently, so
// nothing is lost by taking the live one away.
let chatTimerInterval = null;
let chatTimerStartedAt = 0;
//: The live counter's node, mounted inside the assistant bubble being
//: streamed. Null between turns: `paintChatTimer` is a no-op then.
let chatTimerBox = null;

// Put the counter in the bubble this turn is being written into.
function mountChatTimer(bubble) {
  if (!bubble) return;
  chatTimerBox?.remove();
  const box = document.createElement("span");
  box.className = "msg-timer";
  box.setAttribute("aria-hidden", "true"); // the status line already says it aloud
  chatTimerBox = box;
  // Beside the role label, which is the bubble's own header row, it reads as
  // "LIBRARIAN · 4s" rather than as a number floating in the answer.
  (bubble.querySelector(".msg-role") || bubble).appendChild(box);
  paintChatTimer();
}

function paintChatTimer() {
  const box = chatTimerBox;
  if (!box) return;
  const seconds = Math.floor((performance.now() - chatTimerStartedAt) / 1000);
  // Plain seconds under a minute, m:ss above it, "97s" is a number you have
  // to convert, and by then it is the interesting case.
  box.textContent =
    seconds < 60
      ? `${seconds}s`
      : `${Math.floor(seconds / 60)}:${String(seconds % 60).padStart(2, "0")}`;
}

function startChatTimer() {
  // Started before the bubble exists, the clock has to include the wait for
  // the first byte, which on a cold local model is most of it. `mountChatTimer`
  // gives it somewhere to draw a moment later.
  clearInterval(chatTimerInterval);
  chatTimerStartedAt = performance.now();
  chatTimerInterval = setInterval(paintChatTimer, 1000);
}

function stopChatTimer() {
  clearInterval(chatTimerInterval);
  chatTimerInterval = null;
  // Taken off screen, not left showing: the answer is finished, and its
  // metadata line already carries the final duration. A live-looking counter above a
  // finished answer is the bug this replaced.
  chatTimerBox?.remove();
  chatTimerBox = null;
}

function releaseChatComposer({ announce = true } = {}) {
  if (!chatController || !chatStreaming) return;
  const input = $("chat-input");
  input.disabled = false;
  show("chat-send");
  hide("chat-stop");
  const status = $("chat-status");
  status.textContent = "";
  status.classList.remove("error");
  // The timer belongs to the composer, which has just been handed back to a
  // different conversation: leaving it ticking would time this chat's turn
  // against the next chat's empty box.
  chatTimerBox?.remove();
  chatTimerBox = null;
  $("chat-elapsed")?.classList.add("hidden"); // legacy composer slot, kept hidden
  // Once per stream, not once per switch. Reported: leaving and returning
  // repeatedly repeated the notice, and named whichever chat had just been
  // left rather than the one actually being answered. The title is the one
  // captured when the message was sent, for the same reason.
  if (announce && !chatStreaming.announced) {
    chatStreaming.announced = true;
    toast(
      `Still answering in “${chatStreaming.title}”: the reply will appear there.`
    );
  }
}

//: True when the conversation being opened is the one still being written to.
function isStreamingConversation(id) {
  return Boolean(chatController && chatStreaming && chatStreaming.conv.id === id);
}

//: Put the in-flight turn back on screen, still streaming.
//:
//: The nodes were never destroyed, `openConversation` detached them with
//: `replaceChildren()` and this re-appends the same elements, so whatever the
//: stream has written since is already in them and whatever it writes next
//: lands in front of the reader. That is the difference between the reported
//: "the response only shows after it is completed" and watching it arrive.
function reattachStreamingTurn() {
  if (!chatStreaming) return false;
  const host = $("chat-messages");
  clearChatEmptyState();
  for (const node of chatStreaming.nodes) host.appendChild(node);
  chatScrollToEnd();
  return true;
}

function newChatConversation() {
  releaseChatComposer();
  recordTabVisit("chat", "new");
  chatConv = { id: null, turns: [] };
  chatPendingTitle = null;
  // A summary belongs to the conversation it summarised (§35I).
  chatSummary = null;
  renderCompressionState();
  lastChatQuestion = "";
  // A pending question belongs to the conversation that asked it, starting
  // a new one must not silently answering_agent-tag whatever gets typed first.
  chatAwaitingAgentAnswer = false;
  // batch-a.md's "left open" item, its actual cause: `#chat-suggest` is on
  // loan to `.chat-empty` (see `openConversation`'s own long comment below)
  // whenever the pane it is leaving was itself empty with suggestions
  // already shown. A bare `replaceChildren()` throws the loaned element away
  // with the rest of `.chat-empty` rather than sending it home the way
  // `clearChatEmptyState` already knows how to; a `loadChatSuggestions()`
  // call still in flight for the *old* pane then resolves onto an id that no
  // longer exists anywhere in the document. `clearChatEmptyState` is a no-op
  // when there is no `.chat-empty` to begin with, so this costs nothing on
  // the common path (a chat that already had messages).
  clearChatEmptyState();
  $("chat-messages").replaceChildren();
  $("chat-title").textContent = "New chat";
  renderChatUsage(0);
  //: A fresh pane has no turn to measure, so the meter goes away rather than
  //: keeping the last conversation's number over an empty one.
  renderChatContextMeter(null);
  renderChatEmptyState();
  loadChatSuggestions();
  //: INBOX 34: `replaceChildren()` above fires no scroll event, so without
  //: this the jump-to-latest pill (and, before NO_SCROLL_TOP_TABS below,
  //: the reused down-arrow button) kept whatever visibility the *previous*
  //: conversation left them in, both correctly hidden on the tab's own
  //: first load but stale, and wrongly showing, the moment "+ New" was
  //: clicked from a conversation you had scrolled away in. Both controls
  //: re-check the actual (now empty) pane immediately instead of waiting
  //: for a scroll or resize that a brand-new chat may never get.
  syncChatJumpLatest();
  scrollTopUpdate?.();
}

// Delete the conversation open in the main pane, saved or not.
//
// Saved chats already had a delete (sidebar kebab menu) and deleting a
// conversation's last turn deletes the conversation with it (deleteChatTurn
// above). What was missing was the chat you're actually looking at: a
// brand-new, never-sent pane had no affordance but "+ New", which resets it
// without saying so. So: nothing saved yet (no id, no turns) just resets
// silently, there is nothing to lose and nothing to confirm, and anything
// that made it to the server asks first, the same confirm the sidebar uses.
async function deleteCurrentChat() {
  if (chatConv.id === null && !chatConv.turns.length) {
    newChatConversation();
    return;
  }
  if (!(await confirmDialog("Delete this chat?"))) return;
  if (chatConv.id !== null) {
    try {
      await apiJson(`/conversations/${chatConv.id}`, { method: "DELETE" });
    } catch {
      toast("Couldn't delete this chat.", true);
      return;
    }
    // Document delete already confirms this way; chat delete silently reset
    // the pane instead, the same success-feedback gap in miniature.
    toast("Chat deleted.");
  }
  newChatConversation();
  loadConversationList();
}

// Download the open conversation as clean Markdown (questions + answers).
async function exportChatMarkdown() {
  if (!chatConv.turns.length) {
    toast("Nothing to export yet, ask something first.");
    return;
  }
  const title = $("chat-title").textContent || "Chat";
  let md = `# ${title}\n\n`;
  for (const turn of chatConv.turns) {
    md += `**You:** ${turn.question}\n\n${turn.answer}\n\n---\n\n`;
  }
  const slug =
    title.toLowerCase().replace(/[^\w]+/g, "-").replace(/^-+|-+$/g, "").slice(0, 40) ||
    "chat";
  await saveFile(`${slug}.md`, new Blob([md], { type: "text/markdown" }));
}

// --- resizable sidebars ----------------------------------------------------------
// Both sidebars were a fixed 230px. In the chat list that left about four
// characters of a conversation's name visible, which is no name at all, and
// how much room a sidebar deserves depends on your screen and your titles,
// not on a number picked once.
//
// Drag the edge to resize. The width is remembered per sidebar, and there's a
// keyboard path because a mouse-only control is one that some people simply
// cannot use.

const SIDEBAR_MIN = 170;
const SIDEBAR_MAX = 520;
// Per-sidebar starting widths. The chat list carries the most text per row, 
// a title, then a date/turns/tokens line, so it starts wider than a list of
// one-word category names.
const SIDEBAR_DEFAULTS = { "chat-sidebar": 300, sidebar: 260, "doc-sidebar": 260 };
const sidebarDefault = (id) => SIDEBAR_DEFAULTS[id] || 260;

function sidebarWidth(id, fallback = 260) {
  const saved = Number(localStorage.getItem(`sidebarWidth:${id}`));
  return Number.isFinite(saved) && saved >= SIDEBAR_MIN ? saved : fallback;
}

// Below this the layout stacks into one column and there is no column to size.
//
// **Moved from 720 to 820** (UI_MODERNISATION_PLAN.md Phase 9, band 3: an
// iPad in portrait is 768 or 810 CSS px). The number has to move here and in
// the stylesheet together, and this is the half that is easy to forget:
// `applySidebarWidth` writes an inline `grid-template-columns` when the
// layout is *not* stacked, and an inline style beats a media query, so a CSS
// breakpoint at 820 with this constant left at 720 would have left every
// width from 721 to 819 silently two-column with a stylesheet that said
// otherwise. Verified at 721, 780 and 819 after the move.
const STACKED_LAYOUT = "(max-width: 819.98px)";

function layoutIsStacked() {
  return window.matchMedia(STACKED_LAYOUT).matches;
}

//: The most of the window a sidebar may take. Reported directly: "the ui
//: needs to seemlessly adapt and perfect itself on any resolution and not
//: just be squashed but still fit somehow."
//:
//: Measured before this existed: the sidebar was its saved pixel width at
//: *every* viewport: 260px at 1920 (14% of the window, fine) and 260px at
//: 820 (32%, leaving the notes column 459px). The sidebar never gave up a
//: pixel, so the content absorbed the entire difference. That is the
//: "squashed but still fit somehow" feeling, and its cause is a stored
//: absolute width applied to a relative space.
//:
//: A stylesheet `clamp()` cannot fix it: the width is written as an inline
//: `grid-template-columns` on the parent (below), and an inline style beats
//: every rule. So the cap belongs here, where the number is decided.
const SIDEBAR_VIEWPORT_SHARE = 0.24;

//: The iPad-landscape band (UI_MODERNISATION_PLAN.md Phase 9, 820-1100).
//:
//: The share above is a ratio, and a ratio alone gets this band wrong in
//: both directions: 24% of 1024 is 246px, which is a desktop sidebar on a
//: tablet, and 24% of 820 is 197px, which is a different sidebar again on
//: the same device held the other way. A band is supposed to look like one
//: design, so this one names an absolute ceiling instead: 12rem, the width
//: at which a category name and a conversation title still read.
//:
//: It has to live here rather than in the stylesheet. The sidebar's width is
//: written as an inline `grid-template-columns` on the parent (see
//: applySidebarWidth below), and an inline style beats every rule in every
//: file, media query or not. A `clamp()` in CSS would have looked correct,
//: passed review, and done nothing at all.
const SIDEBAR_TABLET_MAX = 192;
const SIDEBAR_TABLET_BAND = "(min-width: 820px) and (max-width: 1099.98px)";

function layoutIsTablet() {
  return window.matchMedia(SIDEBAR_TABLET_BAND).matches;
}

//: What the sidebar may actually occupy right now, the user's own width
//: where there is room for it, less where there is not, never below the
//: floor a category name needs to stay readable.
function sidebarFittedWidth(saved) {
  const cap = Math.max(SIDEBAR_MIN, Math.round(window.innerWidth * SIDEBAR_VIEWPORT_SHARE));
  const banded = layoutIsTablet() ? Math.min(cap, SIDEBAR_TABLET_MAX) : cap;
  return Math.min(saved, banded);
}

function applySidebarWidth(aside, width, { remember = true } = {}) {
  const clamped = Math.min(Math.max(Math.round(width), SIDEBAR_MIN), SIDEBAR_MAX);
  // **The user's choice is stored, the fitted width is applied**, and the
  // split matters: storing the fitted one would mean dragging a window
  // narrow permanently shrank a preference the user set on a wide screen,
  // with no way to notice it had happened. Widening the window restores it.
  // `remember: false` is for the re-fit on resize, which is the app
  // reacting rather than the user choosing.
  if (remember) localStorage.setItem(`sidebarWidth:${aside.id}`, String(clamped));
  aside.style.setProperty("--saved-width", `${clamped}px`);

  if (layoutIsStacked()) {
    aside.parentElement.style.removeProperty("grid-template-columns");
    return clamped;
  }

  if (aside.classList.contains("sidebar-collapsed")) {
    aside.parentElement.style.gridTemplateColumns = `48px minmax(0, 1fr)`;
  } else {
    aside.parentElement.style.gridTemplateColumns = `${sidebarFittedWidth(clamped)}px minmax(0, 1fr)`;
  }
  return clamped;
}

//: Re-fit every sidebar as the window changes size, not only when it crosses
//: the one stacking breakpoint below. Without this the cap above would apply
//: at load and then go stale the moment anyone resized a window, which is
//: the normal way a desktop app is used, and exactly the case the report was
//: about. `remember: false`: this is not the user choosing a width.
let sidebarRefitTimer = null;
window.addEventListener("resize", () => {
  clearTimeout(sidebarRefitTimer);
  sidebarRefitTimer = setTimeout(() => {
    for (const id of ["sidebar", "chat-sidebar", "doc-sidebar"]) {
      const aside = document.getElementById(id);
      if (aside?.dataset.resizable) {
        applySidebarWidth(aside, sidebarWidth(id, sidebarDefault(id)), { remember: false });
      }
    }
  }, 120);
});

// Rotating a phone, or dragging a desktop window narrow, crosses the
// threshold without reloading: so re-decide then too.
// Rotating a phone, or dragging a desktop window narrow, crosses a band
// boundary without reloading, so both boundaries re-decide the width. The
// tablet band is listed with the stacking one because forgetting it is
// exactly the failure the band exists to prevent: an iPad turned from
// portrait to landscape would come back with the portrait sheet's width.
for (const query of [STACKED_LAYOUT, SIDEBAR_TABLET_BAND]) {
  window.matchMedia(query).addEventListener("change", () => {
    applySidebarSheetMode(layoutIsStacked());
    for (const id of SIDEBAR_IDS) {
      const aside = document.getElementById(id);
      if (aside?.dataset.resizable) {
        applySidebarWidth(aside, sidebarWidth(id, sidebarDefault(id)), { remember: false });
      }
    }
  });
}

// --- the sidebars, as sheets (Phase 9, bands 3 and 4) -------------------------
// Stacked, a sidebar used to sit *above* the content: at 390 the Notes
// categories card was 48px of chrome before the first note and the chat list
// was 99px before the first message, and on a tablet in portrait it is worse
// because there is more of it. A panel you are not using should not cost the
// panel you are using any height at all.
//
// So below 820 the three sidebars leave the flow and become sheets that slide
// in from the left, over the content, with a rail left showing that carries
// the collapse toggle they already have. No new control, no new gesture: the
// button that opens and closes a sidebar on a desktop opens and closes the
// sheet on a tablet.
//
// The state is a class of its own rather than a reuse of `.sidebar-collapsed`,
// and the reason is worth writing down. `.sidebar-collapsed` means something
// specific on a desktop, a 48px rail with a hover-peek, and it carries
// `width: 48px !important` plus a `:hover` rule at higher specificity that
// re-expands it. Reusing it here would mean fighting two `!important`
// declarations from a later block, and a touch-hold would have triggered the
// hover-peek. Instead the desktop classes are taken off while stacked and put
// back on the way out, so none of those rules apply and there is nothing to
// fight.
const SIDEBAR_IDS = ["sidebar", "chat-sidebar", "doc-sidebar"];

function eachSidebar(fn) {
  for (const id of SIDEBAR_IDS) {
    const aside = document.getElementById(id);
    if (aside) fn(aside, id);
  }
}

function applySidebarSheetMode(stacked) {
  eachSidebar((aside) => {
    if (stacked) {
      // Remember the desktop state exactly once, so a second call inside the
      // band cannot record "not collapsed" over the user's real preference.
      if (aside.dataset.deskCollapsed === undefined) {
        aside.dataset.deskCollapsed = aside.classList.contains("sidebar-collapsed") ? "1" : "";
      }
      aside.classList.remove("sidebar-collapsed");
      aside.parentElement?.classList.remove("layout-sidebar-collapsed");
      // A sheet opens closed. Arriving with the content already covered is
      // the failure a sheet exists to avoid.
      aside.classList.remove("sidebar-sheet-open");
    } else {
      aside.classList.remove("sidebar-sheet-open");
      if (aside.dataset.deskCollapsed) {
        aside.classList.add("sidebar-collapsed");
        aside.parentElement?.classList.add("layout-sidebar-collapsed");
      }
      delete aside.dataset.deskCollapsed;
    }
  });
}

// Escape closes an open sheet, and a tap on the content behind it does too.
// Both are what a sheet means; without them the only way back is the rail,
// which is the half of the panel the sheet is covering.
function initSidebarSheetDismissal() {
  document.addEventListener("keydown", (event) => {
    if (event.key !== "Escape") return;
    const open = document.querySelector(".sidebar-sheet-open");
    if (!open) return;
    open.classList.remove("sidebar-sheet-open");
    open.querySelector(".sidebar-collapse-toggle")?.focus();
  });
  document.addEventListener("pointerdown", (event) => {
    const open = document.querySelector(".sidebar-sheet-open");
    if (!open || open.contains(event.target)) return;
    open.classList.remove("sidebar-sheet-open");
  }, true);
}

function makeSidebarResizable(aside) {
  if (!aside || aside.dataset.resizable) return;
  aside.dataset.resizable = "1";
  applySidebarWidth(aside, sidebarWidth(aside.id, sidebarDefault(aside.id)));

  const handle = document.createElement("div");
  handle.className = "sidebar-resize";
  // A real slider: screen readers announce it, and arrows resize it.
  handle.setAttribute("role", "separator");
  handle.setAttribute("aria-orientation", "vertical");
  handle.setAttribute("tabindex", "0");
  handle.setAttribute("aria-label", "Resize the sidebar: arrow keys, or drag");
  aside.appendChild(handle);

  const collapseBtn = document.createElement("button");
  collapseBtn.className = "sidebar-collapse-toggle";
  collapseBtn.title = "Toggle Sidebar";
  collapseBtn.innerHTML = `
    <svg class="icon-expanded" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">
      <rect x="3" y="3" width="18" height="18" rx="2" ry="2"></rect>
      <line x1="9" y1="3" x2="9" y2="21"></line>
    </svg>
    <svg class="icon-collapsed" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">
      <rect x="3" y="3" width="18" height="18" rx="2" ry="2"></rect>
      <line x1="15" y1="3" x2="15" y2="21"></line>
    </svg>
    <svg class="icon-peek" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">
      <line x1="12" y1="17" x2="12" y2="22"></line>
      <path d="M5 17h14v-1.5c0-1.5-1.5-2-1.5-4v-3c0-3-2-5-5.5-5S6.5 5.5 6.5 8.5v3c0 2-1.5 2.5-1.5 4V17z"></path>
    </svg>
  `;
  collapseBtn.addEventListener("click", () => {
    // Stacked, this same button is the sheet's opener. The desktop classes
    // are not applied in that band (applySidebarSheetMode takes them off), so
    // toggling them here would put back exactly the rules the sheet was built
    // to avoid fighting.
    if (layoutIsStacked()) {
      const open = aside.classList.toggle("sidebar-sheet-open");
      collapseBtn.setAttribute("aria-expanded", String(open));
      return;
    }
    aside.classList.toggle("sidebar-collapsed");
    aside.parentElement.classList.toggle("layout-sidebar-collapsed");
    
    // We update the grid column based on whether it is now collapsed or not
    if (aside.classList.contains("sidebar-collapsed")) {
      aside.parentElement.style.gridTemplateColumns = `48px minmax(0, 1fr)`;
    } else {
      const saved = Number(localStorage.getItem(`sidebarWidth:${aside.id}`)) || sidebarDefault(aside.id);
      aside.parentElement.style.gridTemplateColumns = `${saved}px minmax(0, 1fr)`;
    }
  });
  aside.appendChild(collapseBtn);

  const startDrag = (event) => {
    event.preventDefault();
    const startX = event.clientX;
    const startWidth = aside.getBoundingClientRect().width;
    document.body.classList.add("resizing-sidebar");

    const move = (e) => applySidebarWidth(aside, startWidth + (e.clientX - startX));
    const stop = () => {
      document.body.classList.remove("resizing-sidebar");
      window.removeEventListener("pointermove", move);
      window.removeEventListener("pointerup", stop);
    };
    window.addEventListener("pointermove", move);
    window.addEventListener("pointerup", stop);
  };
  handle.addEventListener("pointerdown", startDrag);

  handle.addEventListener("keydown", (event) => {
    const step = event.shiftKey ? 40 : 12;
    const current = aside.getBoundingClientRect().width;
    if (event.key === "ArrowLeft") {
      event.preventDefault();
      applySidebarWidth(aside, current - step);
    } else if (event.key === "ArrowRight") {
      event.preventDefault();
      applySidebarWidth(aside, current + step);
    } else if (event.key === "Home") {
      event.preventDefault();
      applySidebarWidth(aside, sidebarDefault(aside.id)); // back to the default
    }
  });
  // Double-click the handle to reset, the convention everywhere else.
  handle.addEventListener("dblclick", () =>
    applySidebarWidth(aside, sidebarDefault(aside.id))
  );
}

function initResizableSidebars() {
  for (const id of ["sidebar", "chat-sidebar", "doc-sidebar"]) {
    const aside = document.getElementById(id);
    if (aside) makeSidebarResizable(aside);
  }
  makeWebPanelResizable(document.getElementById("web-panel"));
  applySidebarSheetMode(layoutIsStacked());
  initSidebarSheetDismissal();
}

// The Notes sidebar used to mirror `main`'s height into its own `min-height`
// via a ResizeObserver watching `main`. That's exactly backwards for a grid
// row with `align-items: stretch`: setting the sidebar's height taller grows
// the shared row, which stretches `main` to fill it, which re-fires the
// observer with a bigger `main.offsetHeight`, an unbounded feedback loop
// (reported as the sidebar "continuously expanding"). The chat sidebar never
// needed this: it just sets `height: 100%` and lets the grid resolve it (see
// `#chat-sidebar` in style.css). Removed here too: `.layout`'s own
// `align-items: stretch` plus the `min-height: var(--page-sticky-h)` floor in
// style.css already produces the right height with no JS and nothing to loop.

// The web panel (§36G) isn't a grid column like the three sidebars above, it
// is a flex sibling of #chat-main inside <main>, sized by `flex-basis:
// clamp(19rem, 30%, 26rem)` (see style.css). That clamp is a considered
// default, not a placeholder, it keeps the column readable without a drag , 
// so unlike the sidebars, this only overrides it once the user actually asks
// to, and "reset" removes the inline style entirely rather than reapplying a
// remembered default. Below WEB_PANEL_NARROW the panel takes the whole of
// <main> (see the media query in style.css); an inline flex-basis would beat
// that stylesheet rule regardless of the media query; so it stays suppressed
// there and comes back once the window is wide enough again.
const WEB_PANEL_MIN = 280;
const WEB_PANEL_MAX = 900;
const WEB_PANEL_NARROW = "(max-width: 1100px)";

function webPanelIsNarrow() {
  return window.matchMedia(WEB_PANEL_NARROW).matches;
}

// function applyWebPanelWidth(panel, width) {
//   const clamped = Math.min(Math.max(Math.round(width), WEB_PANEL_MIN), WEB_PANEL_MAX);
//   localStorage.setItem("webPanelWidth", String(clamped));
//   panel.style.flexBasis = webPanelIsNarrow() ? "" : `${clamped}px`;
//   // panel.style.flex = webPanelIsNarrow() ? "" : `0 1 ${clamped}px`;
//   return clamped;
// }

function applyWebPanelWidth(panel, width) {
  // Constrain max width to 900px OR 60% of the window width, whichever is smaller.
  const dynamicMax = Math.min(WEB_PANEL_MAX, window.innerWidth * 0.6);
  const clamped = Math.min(Math.max(Math.round(width), WEB_PANEL_MIN), dynamicMax);
  localStorage.setItem("webPanelWidth", String(clamped));
  
  if (webPanelIsNarrow()) {
    panel.style.removeProperty("flex");
    panel.style.removeProperty("width");
  } else {
    // 0 0 prevents flex shrinkage so the drag math stays pixel-perfect
    panel.style.flex = `0 0 ${clamped}px`;
    panel.style.width = `${clamped}px`;
  }
  return clamped;
}

// function resetWebPanelWidth(panel) {
//   localStorage.removeItem("webPanelWidth");
//   panel.style.removeProperty("flex-basis");
// }

function resetWebPanelWidth(panel) {
  localStorage.removeItem("webPanelWidth");
  panel.style.removeProperty("flex");
  panel.style.removeProperty("width");
}

// window.matchMedia(WEB_PANEL_NARROW).addEventListener("change", () => {
//   const panel = document.getElementById("web-panel");
//   if (!panel?.dataset.resizable) return;
//   const saved = Number(localStorage.getItem("webPanelWidth"));
//   panel.style.flexBasis =
//     Number.isFinite(saved) && saved >= WEB_PANEL_MIN && !webPanelIsNarrow()
//       ? `${saved}px`
//       : "";
// });

window.matchMedia(WEB_PANEL_NARROW).addEventListener("change", () => {
  const panel = document.getElementById("web-panel");
  if (!panel?.dataset.resizable) return;
  
  const saved = Number(localStorage.getItem("webPanelWidth"));
  if (Number.isFinite(saved) && saved >= WEB_PANEL_MIN && !webPanelIsNarrow()) {
    panel.style.flex = `0 0 ${saved}px`;
    panel.style.width = `${saved}px`;
  } else {
    panel.style.removeProperty("flex");
    panel.style.removeProperty("width");
  }
});

function makeWebPanelResizable(panel) {
  if (!panel || panel.dataset.resizable) return;
  panel.dataset.resizable = "1";

  const saved = Number(localStorage.getItem("webPanelWidth"));
  if (Number.isFinite(saved) && saved >= WEB_PANEL_MIN) applyWebPanelWidth(panel, saved);

  const handle = document.createElement("div");
  handle.className = "sidebar-resize web-panel-resize";
  handle.setAttribute("role", "separator");
  handle.setAttribute("aria-orientation", "vertical");
  handle.setAttribute("tabindex", "0");
  handle.setAttribute("aria-label", "Resize the web panel, arrow keys, or drag");
  panel.appendChild(handle);

  const startDrag = (event) => {
    event.preventDefault();
    const startX = event.clientX;
    const startWidth = panel.getBoundingClientRect().width;
    document.body.classList.add("resizing-sidebar");

    // The panel sits to the *right* of the conversation, so dragging the
    // handle left (a negative clientX delta) is what widens it, the mirror
    // image of the sidebars, whose handle is on their trailing (right) edge.
    const move = (e) => applyWebPanelWidth(panel, startWidth - (e.clientX - startX));
    const stop = () => {
      document.body.classList.remove("resizing-sidebar");
      window.removeEventListener("pointermove", move);
      window.removeEventListener("pointerup", stop);
    };
    window.addEventListener("pointermove", move);
    window.addEventListener("pointerup", stop);
  };
  handle.addEventListener("pointerdown", startDrag);

  handle.addEventListener("keydown", (event) => {
    const step = event.shiftKey ? 40 : 12;
    const current = panel.getBoundingClientRect().width;
    // Same mirrored direction as the drag: ArrowLeft widens, ArrowRight narrows.
    if (event.key === "ArrowLeft") {
      event.preventDefault();
      applyWebPanelWidth(panel, current + step);
    } else if (event.key === "ArrowRight") {
      event.preventDefault();
      applyWebPanelWidth(panel, current - step);
    } else if (event.key === "Home") {
      event.preventDefault();
      resetWebPanelWidth(panel);
    }
  });
  handle.addEventListener("dblclick", () => resetWebPanelWidth(panel));
}

// A ⋯ button that opens a small menu. Built from the same pieces as the note
// overflow menu so the two behave identically, one open at a time, click away
// or Escape to close, arrow keys to move.
function makeMenuItem(label, title, run) {
  return { label, title, run };
}

// The same menu as `kebabMenu`, with a worded opener instead of a "⋯".
//
// Reported: "a lot of the dropdown menus aren't the same ui style??", and
// they were not, because some of them were not this component at all. A
// native `<select>` used as an action list is drawn by the operating system:
// it cannot take the app's padding, radius, hover or icons, which is exactly
// the "tight and right up against the edge of the text" the report describes.
// A `<select>` is the right control for *choosing a value in a form*; an
// action that happens the moment you pick it is a menu, and now uses the
// app's own one.
//
// `openerClass` because the opener has to belong to the row it stands in: on
// a `.small` toolbar it is a `.small` button, and on the capture panel's
// 40px attach row it is a plain `.ghost` one beside "Attach" and "From
// library". Defaulted to what every existing caller already got, so adding
// the parameter changed nothing that was already on screen.
function labelledMenu(label, items, ariaLabel, openerClass = "ghost small") {
  const wrap = document.createElement("span");
  wrap.className = "menu-wrap";

  const menu = document.createElement("div");
  menu.className = "action-menu hidden";
  menu.setAttribute("role", "menu");

  const opener = document.createElement("button");
  opener.type = "button";
  opener.className = openerClass;
  setLabel(opener, label);
  opener.title = ariaLabel;
  opener.setAttribute("aria-label", ariaLabel);
  opener.setAttribute("aria-haspopup", "menu");
  opener.setAttribute("aria-expanded", "false");
  opener.addEventListener("click", (event) => {
    event.stopPropagation();
    const willOpen = menu.classList.contains("hidden");
    if (willOpen) openActionMenu(menu, opener);
    else closeActionMenus();
  });

  for (const item of items) {
    const button = document.createElement("button");
    button.className = "menu-item";
    button.setAttribute("role", "menuitem");
    setLabel(button, item.label);
    button.title = item.title;
    button.addEventListener("click", async (event) => {
      event.stopPropagation();
      closeActionMenus();
      await item.run();
    });
    menu.appendChild(button);
  }
  wireMenuKeyboard(menu, opener);
  wrap.append(opener, menu);
  return wrap;
}

// --- every <select> in the app wears the app's own menu ---------------------
//
// **The last surface the stylesheet could not reach.** Reported repeatedly,
// and finally with a screenshot of the model picker: a native `<select>`
// popup is drawn by the operating system, not the page. It ignores the
// app's palette, radius, padding, hover and icons entirely, which is why
// dropdowns looked like a different program, why their text sat "right up
// against the edge", and why no amount of CSS on `select` ever fixed it.
// `select` itself is styled (the closed control matches); only the *popup*
// was out of reach, and there is no CSS that reaches it.
//
// So the popup is replaced rather than restyled. The real `<select>` stays
// in the DOM and stays the source of truth: every `.value` read, `.options`
// write and `change` listener in the rest of the app keeps working
// untouched, which is what makes this safe to apply everywhere at once
// instead of rewriting dozens of call sites. The visible control is a
// button plus a `role="listbox"`, using the same `openActionMenu` /
// `closeActionMenus` plumbing as every other menu here, so it inherits
// their positioning, flip-when-clipped and click-away behaviour for free.
//
// Selects are repopulated all over this app (models, categories, personas),
// often long after first render, so a MutationObserver re-reads the options
// rather than trusting a one-time build.
const SELECT_ENHANCED = "data-enhanced-select";

function enhanceSelect(select) {
  if (!select || select.hasAttribute(SELECT_ENHANCED)) return;
  // A multi-select is a different control with different semantics, and
  // nothing in this app uses one; leave it to the browser rather than
  // guessing at a listbox that supports multiple selection.
  if (select.multiple || select.size > 1) return;
  if (select.closest("[data-no-select-enhance]")) return;
  select.setAttribute(SELECT_ENHANCED, "1");

  const shell = document.createElement("span");
  shell.className = "select-shell";

  const opener = document.createElement("button");
  opener.type = "button";
  opener.className = "select-opener";
  opener.setAttribute("aria-haspopup", "listbox");
  opener.setAttribute("aria-expanded", "false");

  const valueText = document.createElement("span");
  valueText.className = "select-value";
  const caret = document.createElement("i");
  caret.className = "ph ph-caret-down select-caret";
  caret.setAttribute("aria-hidden", "true");
  opener.append(valueText, caret);

  const menu = document.createElement("div");
  menu.className = "action-menu select-menu hidden";
  menu.setAttribute("role", "listbox");

  select.parentNode.insertBefore(shell, select);
  shell.append(select, opener, menu);
  // Reported repeatedly, on different selects, as the same shape: the
  // model picker (Settings) and the note editor's category picker both
  // spilled off the edge of whatever scrolling/backdrop-filter ancestor
  // they opened inside: ".modal-content" for the first, the note card's
  // own stacking context for the second. `wireEscapedActionMenu` (this
  // file, above) already exists for exactly this, it was built for the
  // Library's Documents kebab and reparents an open menu to <body>,
  // positioning it from the opener's own rect so no ancestor's overflow or
  // stacking context can clip it, but it was only ever wired to that one
  // menu. Every one of this app's 51+ selects shares the same
  // `.select-menu`/`openActionMenu` shape, so wiring it here once covers
  // all of them instead of chasing each report to a different select.
  wireEscapedActionMenu(shell);

  // The native control keeps doing its job (form value, validation, the
  // label association) but stops being what you see or tab to, the opener
  // carries the keyboard now.
  select.classList.add("select-native-hidden");
  select.tabIndex = -1;
  select.setAttribute("aria-hidden", "true");

  const label =
    select.getAttribute("aria-label") ||
    select.title ||
    "Choose an option";
  opener.setAttribute("aria-label", label);
  opener.title = select.title || label;

  const syncValue = () => {
    const chosen = select.options[select.selectedIndex];
    valueText.textContent = chosen ? chosen.textContent.trim() : "";
    opener.disabled = select.disabled;
    for (const row of menu.querySelectorAll("[role='option']")) {
      const on = row.dataset.value === select.value;
      row.setAttribute("aria-selected", String(on));
      row.classList.toggle("is-chosen", on);
    }
  };

  const rebuild = () => {
    menu.replaceChildren();
    for (const option of select.options) {
      //: **An option the app has hidden is not offered here either.** Measured
      //: on the OCR workspace's reader picker: `#ocr-reader` carries
      //: `<option value="ocr" hidden>AI vision model</option>`, which
      //: `ocrLoadReaders` unhides only on a machine that really has two
      //: different readers, and this stand-in listed all three regardless, so
      //: the control offered a reader that does not exist here. The native
      //: `<select>` has honoured `hidden` on an option for years; the shell in
      //: front of it had never been told to. `syncHidden` below covers the same
      //: mistake one level up, for a select that is hidden as a whole.
      //:
      //: No observer needed for it: `rebuild()` runs on every open, so a
      //: picker that gains a reader while the app is running shows it the next
      //: time it is opened.
      if (option.hidden) continue;
      const row = document.createElement("button");
      row.type = "button";
      row.className = "menu-item select-option";
      row.setAttribute("role", "option");
      row.dataset.value = option.value;
      row.textContent = option.textContent.trim();
      if (option.disabled) row.setAttribute("aria-disabled", "true");
      row.addEventListener("click", (event) => {
        event.stopPropagation();
        closeActionMenus();
        if (option.disabled || select.value === option.value) return;
        select.value = option.value;
        syncValue();
        // The app listens on the real control, so the real control is what
        // announces the change.
        select.dispatchEvent(new Event("change", { bubbles: true }));
      });
      menu.appendChild(row);
    }
    syncValue();
  };

  opener.addEventListener("click", (event) => {
    event.stopPropagation();
    if (select.disabled) return;
    if (menu.classList.contains("hidden")) {
      rebuild();
      openActionMenu(menu, opener);
      focusMenuItem(menu.querySelector(".is-chosen"), menu);
    } else {
      closeActionMenus();
    }
  });

  select.addEventListener("change", syncValue);
  new MutationObserver(rebuild).observe(select, { childList: true, subtree: true });

  // **A `<select>` that has been hidden must take its stand-in with it.**
  // Measured, not reasoned: on Library → Images the native
  // `#library-media-read` was 0x0 (`setLibraryMediaKind` adds `hidden`, since a
  // read filter is a Files idea) while the shell this function wraps it in
  // still rendered a 124x36 dropdown reading "Read or not", on a tab where
  // "read" means nothing. `#update-version-select` in Settings → About is
  // toggled the same way and had the same hole.
  //
  // This is the shape CLAUDE.md names: the value was set correctly on the
  // native control and did its damage on a *different element*, so the code
  // that hides it reads as right at every line. The fix belongs here rather
  // than at either call site, because every one of the app's 50-odd selects
  // inherits the same stand-in and any of them could be hidden tomorrow.
  // `hidden` is watched alongside the class for the same reason the
  // stylesheet protects both: this app hides things with either.
  const syncHidden = () => {
    shell.classList.toggle("hidden", select.classList.contains("hidden") || select.hidden);
  };
  syncHidden();
  new MutationObserver(syncHidden).observe(select, {
    attributes: true,
    attributeFilter: ["class", "hidden"],
  });

  // **Programmatic `select.value = …` fires no event at all**, and this app
  // sets one directly in dozens of places, every "load the saved settings
  // into the form" path does. A `change` listener alone therefore leaves the
  // opener showing whatever was selected when the page was built.
  //
  // Measured, not reasoned: the Timeline's own View control read "Grid" while
  // the timeline underneath it was rendering the *line* view, because the tab
  // assigned the saved value to that select directly, after this control had
  // been enhanced. (Both views and the select are gone now, the Timeline is one
  // feed: the hole this fixes was in every one of the app's 51 selects.)
  //
  // The fix is to make assignment observable: shadow `value`, `selectedIndex`
  // and `disabled` on this instance with accessors that call through to the
  // prototype's real ones and then re-sync the label. `Reflect.get/set` with
  // the element as receiver is what keeps the native accessor working on the
  // right object: reading the descriptor and calling `.get.call(select)`
  // directly would be the same thing written less safely.
  const proto = Object.getPrototypeOf(select);
  for (const prop of ["value", "selectedIndex", "disabled"]) {
    const native = Object.getOwnPropertyDescriptor(proto, prop);
    if (!native || !native.set) continue;
    Object.defineProperty(select, prop, {
      configurable: true,
      enumerable: false,
      get() {
        return native.get.call(this);
      },
      set(next) {
        native.set.call(this, next);
        syncValue();
      },
    });
  }

  wireMenuKeyboard(menu, opener);
  rebuild();
}

// **Double-click any slider to put it back to its default.** Asked for
// directly: "allow the user to double click any slider to reset it to
// default."
//
// One delegated listener rather than fourteen handlers, and no table of
// default values anywhere: every `<input type="range">` in this app already
// carries its default in its `value` attribute, and `defaultValue` reflects
// exactly that attribute rather than whatever the control currently shows.
// So the default is read from the same place the markup states it, and a
// slider added later is covered the moment it exists.
//
// Both events are dispatched, and both are needed: this app has live
// handlers on `input` (the graph's gravity/spread redraw as you drag) and
// commit handlers on `change` (the appearance settings persist there).
// Firing only one would either leave the screen stale or leave the setting
// unsaved.
document.addEventListener("dblclick", (event) => {
  const slider = event.target;
  if (!(slider instanceof HTMLInputElement) || slider.type !== "range") return;
  if (slider.disabled || slider.value === slider.defaultValue) return;
  slider.value = slider.defaultValue;
  slider.dispatchEvent(new Event("input", { bubbles: true }));
  slider.dispatchEvent(new Event("change", { bubbles: true }));
  toast("Reset to default");
});

// A control that does something on double-click has to say so somewhere, and
// the tooltip is where this app already explains its controls. Appended to
// whatever the slider's own title says rather than replacing it, so the
// existing explanations survive.
function annotateSliders(root) {
  for (const slider of (root || document).querySelectorAll("input[type='range']")) {
    if (slider.dataset.dblHinted) continue;
    slider.dataset.dblHinted = "1";
    const existing = (slider.title || "").trim();
    slider.title = existing
      ? `${existing}: double-click to reset`
      : "Double-click to reset to default";
  }
}

function enhanceAllSelects(root) {
  for (const select of (root || document).querySelectorAll("select")) {
    enhanceSelect(select);
  }
}

// **Focus a `<select>`. Never call `.focus()` on one directly.**
//
// `enhanceSelect` above takes the native control out of the tab order
// (`select-native-hidden`, `tabIndex = -1`, `aria-hidden`) and puts a
// `<button class="select-opener">` in front of it. So `select.focus()` on any
// enhanced select focuses *nothing*: the keystrokes that follow go to
// `document.body`, and a `keydown` bound to the select never fires at all
// because the select never has the focus. Nothing throws and nothing logs;
// the call reads as correct at every line involved.
//
// Found the hard way. Two listeners in the documents editor's "attach a link"
// picker were written this way and only a Playwright sweep caught them: the
// sweep pressed Escape, the picker stayed open, and the row's children read
// back as SPAN and BUTTON rather than SELECT and BUTTON. Three more call
// sites elsewhere in this file were doing the same thing silently
// (the note's own bookmark picker, the chat skills panel, the note-to-document
// picker), which is why this is a helper rather than three edits.
//
// **Why there is no lint for it.** `tests/test_frontend_handlers.py` and its
// siblings read the source as text, and the thing that decides here is what a
// variable *holds* at runtime: `picker.focus()` is dead when `picker` is a
// select and correct when it is an input, and nothing in the text says which.
// A name-based rule (`/select|picker/`) would both miss `box.focus()` on a
// select and fail `picker.focus()` on a text input, and CLAUDE.md's rule is
// that a lint which fires on the wrong thing gets widened until it means
// nothing. So the guard is this function plus this comment, and the check is
// the sweep: `scratchpad/ui-sweeps/selectfocus.js` walks every enhanced select
// in the page and asserts that focusing it through here lands on something
// focusable.
//
// The frame matters: `enhanceSelect` runs from a MutationObserver, so a select
// created and focused in the same turn has no shell yet. One retry on the next
// frame covers that without a timeout anyone has to tune.
//
// **`closest(".select-shell")`, not `parentElement`,** and that is a measured
// correction rather than defensive coding. `enhanceSelect` does
// `shell.append(select, opener, menu)`, so the shell *is* the parent at the
// moment it runs, and the first version of this helper read the opener off
// `select.parentElement`. `scratchpad/ui-sweeps/selectfocus.js` then found
// three selects where that returns null (`notes-page-size`,
// `library-page-size`, `reminders-page-size`): something in their markup sits
// between them and the shell, so `parentElement` is not it, and the fallback
// quietly focused the native control instead, which is `tabindex="-1"` and
// `aria-hidden="true"`. `closest` finds the shell for every enhanced select in
// the app, on every tab, measured.
//
// **When nothing takes the focus, nothing takes it.** Six of the app's selects
// live inside a closed `<details>` menu (the timeline's options, the graph's,
// the page-size pickers), where no descendant is focusable at all. This ends
// up calling `opener.focus()` on a button that cannot have it, and the focus
// stays where it was. That is the honest outcome for "the control you asked
// for is inside a menu that is shut", and it is why the sweep skips those
// rather than demanding a landing.
function focusSelect(select) {
  if (!select) return;
  const land = () => {
    const opener = select.closest(".select-shell")?.querySelector(".select-opener");
    (opener || select).focus();
  };
  if (select.hasAttribute(SELECT_ENHANCED)) land();
  else requestAnimationFrame(land);
}

// New selects appear whenever a panel renders, so watch for them rather
// than asking every render path to remember to call this.
function watchForSelects() {
  enhanceAllSelects(document);
  annotateSliders(document);
  new MutationObserver((records) => {
    for (const record of records) {
      for (const node of record.addedNodes) {
        if (node.nodeType !== 1) continue;
        if (node.tagName === "SELECT") enhanceSelect(node);
        else enhanceAllSelects(node);
        if (node.tagName === "INPUT") annotateSliders(node.parentNode || document);
        else annotateSliders(node);
      }
    }
  }).observe(document.body, { childList: true, subtree: true });
}

function kebabMenu(items, ariaLabel) {
  const wrap = document.createElement("span");
  wrap.className = "menu-wrap";

  const menu = document.createElement("div");
  menu.className = "action-menu hidden";
  menu.setAttribute("role", "menu");

  const opener = smallButton("ph:dots-three", ariaLabel, () => {
    const willOpen = menu.classList.contains("hidden");
    if (willOpen) openActionMenu(menu, opener);
    else closeActionMenus();
  });
  //: **A kebab is one glyph, so it is square.** Reported: "all the chat header
  //: buttons [should] be square, there should be no rectangle single icon
  //: buttons as that is not consistent with the rest of the application."
  //: Measured in that header: Fork and Compress 28×28, this opener 43×28, it
  //: took `.small`'s text padding because the class that squares an icon
  //: button has to be remembered per button (see the rule's own comment in
  //: 00-tokens-shell.css) and nobody remembered it here. Set at the source, so
  //: every ⋯ in the app is square rather than one more thing to remember.
  opener.classList.add("icon-only");
  opener.setAttribute("aria-haspopup", "menu");
  opener.setAttribute("aria-expanded", "false");

  for (const item of items) {
    const button = document.createElement("button");
    button.className = item.disabled ? "menu-item menu-item-unavailable" : "menu-item";
    //: A destructive row says so in the app's own danger colour. Added when
    //: the Images gallery's bespoke menu was folded into this one, it had a
    //: red Delete and this did not, and losing that on the way in would have
    //: made the shared control worse than the one it replaced.
    //: `menu-danger`, the class this menu's own stylesheet already defines, 
    //: not the generic `danger`, which is written for buttons with a ground.
    if (item.danger) button.classList.add("menu-danger");
    button.setAttribute("role", "menuitem");
    setLabel(button, item.label);
    button.title = item.title;
    // Muted, not `disabled`, a native disabled button also blocks its own
    // title tooltip on some platforms, which is the one piece of information
    // this state actually needs to deliver (why the button can't do its
    // normal job). `run` still fires; a disabled item's `run` says why.
    if (item.disabled) button.setAttribute("aria-disabled", "true");
    button.addEventListener("click", async (event) => {
      event.stopPropagation();
      closeActionMenus();
      await item.run();
    });
    menu.appendChild(button);
  }
  wireMenuKeyboard(menu, opener);
  wrap.append(opener, menu);
  //: **Every ⋯ menu escapes its container, not just the ones somebody
  //: remembered.** Reported three times across three surfaces, the documents
  //: list, the gallery, and then the lightbox, always the same shape: the
  //: menu is `position: absolute` inside an ancestor that scrolls or paints a
  //: `backdrop-filter`, and either clips it.
  //:
  //: `wireEscapedActionMenu` was written to be opted into "for any menu known
  //: to live inside a scrolling ancestor", and that is the part that keeps
  //: failing: which ancestors scroll is not knowable from where the menu is
  //: built, and a caller added next year will not know either. Opting in
  //: *here* covers every `kebabMenu` at once, which is every ⋯ in the app.
  //:
  //: It is still not folded into `openActionMenu`, deliberately: the chat
  //: dock's popovers, the selection popup and the whiteboard's context menu
  //: build `.action-menu` by other routes, none of them are clipped, and
  //: rewriting what they all share to fix this class is the bigger change
  //: that function's own comment argues against.
  wireEscapedActionMenu(wrap);
  return wrap;
}

//: **A formatting-toolbar menu has to stay inside its panel**, and until this
//: ran it did not.
//:
//: Reported twice: *"formatting can go off the edge of the pannel in the
//: capture tab and im assuming the documents tab as well"* and *"dropdown
//: menus from the formatting bar get cut off and dont stay in the panel"*.
//: Measured in the capture composer at 1440px: the **Insert** menu spanned
//: x=164–356 against a panel starting at x=287, **123px of it outside the
//: panel's left edge**. The three menus at the right end of the same strip
//: were all comfortably inside, which is why this reads as intermittent.
//:
//: The cause is one line of CSS doing the right thing in the wrong place.
//: `.doc-dock-menu-list` is `position: absolute; right: 0`, anchored to its
//: opener's *right* edge, growing leftwards. That is correct for the menu it
//: was written for (the document ⋯, which sits at the right end of the header
//: row) and wrong for an opener near the left of a toolbar, where a 192px
//: menu is pushed straight out of the panel.
//:
//: Not fixable in CSS: which edge to anchor to depends on where the opener
//: happens to sit relative to a panel whose width changes with the window,
//: the sidebar and the chat dock. So it is measured on open, the same way
//: `wireEscapedActionMenu` handles the clipping case it owns.
//:
//: `toggle` does not bubble, so this listens in the capture phase, one
//: delegated listener covers the note composer's strip and the document
//: editor's, including any `<details>` menu added to either later.
function clampToolbarMenu(details, { retry = true } = {}) {
  const list = details.querySelector(".doc-dock-menu-list");
  if (!list) return;
  const opener = details.querySelector("summary") || details;
  // **Cleared, not zeroed: and this distinction is the whole bug below.**
  //
  // The inline values have to go before measuring, or the menu's own size is
  // measured from wherever the previous open left it. This used to clear them
  // by writing `left: 0; top: 0`, and then the guard two lines down could
  // `return`, leaving those zeros in place. A `position: fixed` element at
  // 0,0 sits in the top-left corner of whatever its containing block is,
  // which for these menus is the surrounding `.card`: reported as "the
  // toolbar dropdowns are now appearing in the top left corner of the panel",
  // with a screenshot of the Block menu pinned to the corner of the capture
  // card while its button sat 1,600px away.
  //
  // Writing "" removes the declaration instead, so a failed measurement falls
  // back to the stylesheet, which now says `top: auto; left: auto`, i.e. the
  // static position, i.e. roughly under the button. A wrong-but-near answer
  // beats a corner every time.
  list.style.left = "";
  list.style.top = "";
  list.style.right = "";
  const anchor = opener.getBoundingClientRect();
  const box = list.getBoundingClientRect();
  if (!box.width || !anchor.width) {
    // Nothing to measure *yet* is a real state: a `<details>` panel is not
    // laid out until the open takes effect, and this runs from the `toggle`
    // event. One retry on the next frame, once, a loop here would spin
    // forever on a menu that is genuinely empty.
    if (retry) requestAnimationFrame(() => clampToolbarMenu(details, { retry: false }));
    // Out of retries: show it where the stylesheet put it rather than never.
    // `.doc-dock-menu-list` is invisible until this class arrives.
    else list.classList.add("is-placed");
    return;
  }
  const margin = 8;
  // **Left-aligned to the opener, growing rightwards.**
  //
  // This was `anchor.right - box.width`, right-aligned, transcribed from the
  // stylesheet's `right: 0`, which is correct for `#doc-dock-menu` (a kebab at
  // the far right of the panel, where a menu growing rightwards would leave
  // the screen) and wrong for every menu in a toolbar. Measured: a 192px menu
  // right-aligned to a 41px icon button lands **151px to the left of the
  // button that opened it**, over the sidebar, on the capture toolbar, at
  // every viewport. Reported as "dropdowns are completely broken and dont show
  // in the capture notes and documents toolbars", which is what a menu that
  // opens nowhere near its control looks like from the outside.
  //
  // `clampToolbarMenu` only ever runs for `.doc-toolbar-menu` (see the toggle
  // listener below), so the kebab keeps the stylesheet's right-alignment and
  // this is a toolbar-only rule.
  let left = anchor.left;
  if (left + box.width > window.innerWidth - margin) {
    // No room to the right: right-align to the opener, which is the shape that
    // keeps a menu attached to its button near the end of a row.
    left = Math.min(anchor.right - box.width, window.innerWidth - margin - box.width);
  }
  // `margin` wins a tie deliberately: a viewport narrower than the menu cannot
  // satisfy both edges, and losing the *start* of the list is worse than
  // losing its end.
  if (left < margin) left = margin;
  let top = anchor.bottom + 4;
  if (top + box.height > window.innerHeight - margin) {
    // Flip above the opener, and only fall back to "pinned to the bottom" when
    // there is no room either way, a menu that covers its own button is still
    // better than one whose last item is unreachable.
    const above = anchor.top - 4 - box.height;
    top = above >= margin ? above : Math.max(margin, window.innerHeight - margin - box.height);
  }
  list.style.left = `${Math.round(left)}px`;
  list.style.top = `${Math.round(top)}px`;

  // **A second pass, because `position: fixed` is not always fixed to the
  // viewport.** Any ancestor with `transform`, `filter`, `backdrop-filter`,
  // `perspective`, `contain` or `will-change` becomes the containing block for
  // its fixed descendants, and `left`/`top` are then measured from *that* box,
  // not from the screen. Every one of these menus lives inside a `.card`, and
  // `.card` carries `backdrop-filter: blur(var(--glass-blur))` whenever the
  // Appearance → Glass setting is on, which is the default.
  //
  // So the numbers computed above, which are viewport coordinates taken from
  // `getBoundingClientRect` and clamped against `window.innerWidth/Height`,
  // land the panel offset by the card's own position: up and to the left of
  // where it belongs, and clipped by the card on top of that. Reported as
  // "these toolbar dropdowns flicker somewhere random on the screen and dont
  // show", and the flicker is this function re-running on every scroll and
  // re-placing it wrongly each time.
  //
  // Rather than enumerate the properties that create a containing block, a
  // list CSS keeps adding to, and one that would have to be checked up the
  // whole ancestor chain on every open, measure where the panel actually
  // landed and correct by the difference. Self-correcting, cause-agnostic, and
  // one extra layout read.
  //
  // Proven, not reasoned: this sandbox's headless Chromium reports
  // `backdrop-filter: none` on every `.card`, so the user's exact trigger does
  // not fire here: but `filter` creates the same containing block and *is*
  // supported, so forcing `.card.doc-main { filter: saturate(1) }` reproduces
  // it exactly. Measured with that in place: the panel's `style.left` reads
  // 595px while it renders at x=886, the correction having subtracted the
  // card's own 291px offset. Without the second pass the same menu would have
  // been given left=886 and rendered at 1177, 291px to the right of the
  // button that opened it, which is the reported "somewhere random". After
  // the correction, dx is 0 (±1 rounding) on all six and every one is
  // hit-testable. With no containing block the correction is zero, so this
  // costs one layout read and changes nothing.
  const landed = list.getBoundingClientRect();
  const driftX = left - landed.x;
  const driftY = top - landed.y;
  if (Math.abs(driftX) > 0.5 || Math.abs(driftY) > 0.5) {
    list.style.left = `${Math.round(left + driftX)}px`;
    list.style.top = `${Math.round(top + driftY)}px`;
  }
  // Only now is it allowed to paint -- see `.doc-dock-menu-list` in
  // 04-chat-dock-appearance.css for the flicker this prevents.
  list.classList.add("is-placed");
}

//: A fixed-position menu does not travel with the strip it belongs to, so any
//: scroll or resize while it is open would leave it stranded beside a button
//: that has moved. Re-placing on both is cheaper than the alternative (an
//: anchor-positioning polyfill) and covers the two ways it can happen: the
//: page scrolls under a sticky toolbar, or the toolbar itself is scrolled
//: sideways in row mode.
function replaceOpenToolbarMenus() {
  for (const details of document.querySelectorAll(".doc-toolbar-menu[open]")) {
    clampToolbarMenu(details);
  }
}
window.addEventListener("resize", replaceOpenToolbarMenus);
window.addEventListener("scroll", replaceOpenToolbarMenus, true);

document.addEventListener(
  "toggle",
  (event) => {
    const details = event.target;
    if (!(details instanceof HTMLElement) || details.tagName !== "DETAILS") return;
    if (!details.classList.contains("doc-toolbar-menu")) return;
    if (!details.open) {
      // Back to invisible for the next open, so it never paints unplaced.
      details.querySelector(".doc-dock-menu-list")?.classList.remove("is-placed");
      return;
    }
    clampToolbarMenu(details);
  },
  true
);

// "12.4k" beats "12417" when the number is a rough sense of scale, which is
// all a token count ever is.
//: **A model's name as a badge should say, at a glance, which model.**
//: Reported: "can you truncate hugging face model names in visual badges
//: except for in the model settings page to remove the hf.co/ part??"
//:
//: A HuggingFace id arrives as `hf.co/LiquidAI/LFM2.5-VL-1.6B` (Ollama's own
//: form): three segments of which only the last identifies the model, and
//: the first two eat the width a badge has. The org is kept off too: two
//: models from the same org differ in their last segment, never their first.
//: Settings → Models is deliberately *not* a caller: choosing a model to pull
//: needs the id you would actually type.
//:
//: Only prefixes that are registry addresses are stripped. `llama3.2:3b` and
//: `gemma3:latest` are already short and are returned untouched, tag and all.
function shortModelName(name) {
  const raw = String(name || "").trim();
  if (!raw) return "";
  const withoutHost = raw.replace(/^(https?:\/\/)?(hf\.co|huggingface\.co)\//i, "");
  //: Only when a registry host was actually stripped is the remaining
  //: `org/model` split safe: a bare `library/llama3` from a private registry
  //: keeps its shape, because there the org may be the only thing telling two
  //: models apart.
  if (withoutHost === raw) return raw;
  const parts = withoutHost.split("/").filter(Boolean);
  return parts.at(-1) || withoutHost;
}
window.shortModelName = shortModelName;

function formatTokens(n) {
  const count = Number(n) || 0;
  if (count < 1000) return String(count);
  return `${(count / 1000).toFixed(count < 10000 ? 1 : 0)}k`;
}

// Server timestamps are UTC. Most now carry an explicit offset or Z; older
// stored values may carry neither, and a naive string is parsed as LOCAL by
// JavaScript. One parser, so the assumption lives in exactly one place.
function parseServerTime(iso) {
  if (!iso) return null;
  const text = String(iso);
  const hasZone = /[Zz]$|[+-]\d{2}:?\d{2}$/.test(text);
  const date = new Date(hasZone ? text : `${text}Z`);
  return Number.isNaN(date.getTime()) ? null : date;
}

// How long ago, in words. A wall of identical timestamps tells you nothing;
// "yesterday" and "3 weeks ago" are what you actually navigate by.
function relativeTime(iso) {
  // Timestamps now come back explicitly UTC ("...+00:00"), so the old
  // unconditional `iso + "Z"` produced "…+00:00Z", an unparseable string that
  // rendered literally as "Invalid Date" in the documents sidebar. Only assume
  // UTC when the value doesn't already say what it is.
  const then = parseServerTime(iso);
  if (!then) return "";
  const seconds = Math.max(0, (Date.now() - then.getTime()) / 1000);
  if (seconds < 90) return "just now";
  const minutes = seconds / 60;
  if (minutes < 60) return `${Math.round(minutes)} min ago`;
  const hours = minutes / 60;
  if (hours < 24) return `${Math.round(hours)}h ago`;
  const days = Math.round(hours / 24);
  if (days === 1) return "yesterday";
  if (days < 7) return `${days} days ago`;
  // Screenshotted as "1 weeks ago". Rounding 8 days gives 1, and the plural
  // was hard-coded: the only branch here that forgot to agree with its own
  // number.
  const weeks = Math.round(days / 7);
  if (days < 30) return `${weeks} week${weeks === 1 ? "" : "s"} ago`;
  return then.toLocaleDateString(undefined, { day: "numeric", month: "short" });
}

//: How many chats the switcher shows. Searching and sorting all of them is
//: the Library's job now (§36F); this list exists so the chat you were in ten
//: minutes ago is one click away without leaving the tab you are typing in,
//: and eight is comfortably more than "the one before this one" while still
//: fitting beside a conversation.
const RECENT_CHATS_SHOWN = 8;

const CHAT_SIDEBAR_SORT_KEY = "chatSidebarSort";

// Pinned notes stay first regardless of sort, that promise (a divider marks
// the boundary, just below) predates this control and a sort choice
// shouldn't silently break it. Only the order *within* each of the two
// groups changes.
function sortConversations(conversations, mode) {
  const pinned = conversations.filter((c) => c.pinned);
  const rest = conversations.filter((c) => !c.pinned);
  const byMode = {
    recent: (a, b) => new Date(b.updated_at) - new Date(a.updated_at),
    turns: (a, b) => (b.turns || 0) - (a.turns || 0),
    tokens: (a, b) => (b.tokens || 0) - (a.tokens || 0),
    alpha: (a, b) => a.title.localeCompare(b.title),
  }[mode] || null;
  if (!byMode) return conversations; // "recent" is already the server's own order
  return [...pinned.sort(byMode), ...rest.sort(byMode)];
}

async function loadConversationList() {
  const conversations = sortConversations(
    await apiJson("/conversations").catch(() => []),
    $("chat-sidebar-sort")?.value || "recent"
  ).slice(0, RECENT_CHATS_SHOWN);
  const list = $("conversation-list");
  list.replaceChildren();
  const empty = $("conv-empty");
  empty.classList.toggle("hidden", conversations.length > 0);
  empty.textContent = "No saved chats yet. Ask something to start one.";

  let sawUnpinned = false;
  for (const conversation of conversations) {
    // One divider between the pinned block and the rest, so "pinned" reads as
    // a section rather than as an unexplained reordering.
    if (!conversation.pinned && !sawUnpinned && list.children.length) {
      const rule = document.createElement("li");
      rule.className = "conv-divider";
      rule.setAttribute("aria-hidden", "true");
      list.appendChild(rule);
    }
    if (!conversation.pinned) sawUnpinned = true;

    const li = document.createElement("li");
    if (conversation.id === chatConv.id) li.classList.add("active-conv");
    if (conversation.pinned) li.classList.add("pinned-conv");

    //: **The whole row opens the chat, not just the words in it.** Reported:
    //: "I clicked on other chat conversations in the chat sidebar but the
    //: conversations didnt visibly select in the sidebar." Measured: the
    //: `<li>` is 268x48 and `.conv-title`, which carried the only click
    //: handler: is 211x35. The 6.4px/9.6px padding ring and the gutter kept
    //: clear for the ⋯ are dead: `elementFromPoint` returns the `<li>` at the
    //: row's top edge, bottom edge, left edge and right-hand side alike. So
    //: roughly a third of every row did nothing when clicked, which reads
    //: exactly like a selection that failed rather than a click that missed.
    //:
    //: On the `<li>`, with the actions cluster excluded: a click on the ⋯ (or
    //: on anything inside the menu it opens) is not a request to switch
    //: conversations. `aria-current` says which row is the open one to a
    //: screen reader, which the accent fill says to everyone else.
    li.addEventListener("click", (event) => {
      if (event.target instanceof Element && event.target.closest(".entry-actions")) return;
      openConversation(conversation.id);
    });
    li.setAttribute("aria-current", conversation.id === chatConv.id ? "true" : "false");

    const title = document.createElement("span");
    title.className = "conv-title";
    title.title = "Open this chat";

    const name = document.createElement("span");
    name.className = "conv-name";
    setLabel(name, `${conversation.pinned ? "ph:push-pin " : ""}${conversation.title}`);
    const meta = document.createElement("span");
    meta.className = "conv-meta muted";
    const bits = [relativeTime(conversation.updated_at)];
    if (conversation.turns) {
      bits.push(`${conversation.turns} ${conversation.turns === 1 ? "turn" : "turns"}`);
    }
    // "tok" rather than "tokens": the row is one line by design, and the
    // number is the useful part, spelling out the unit is what pushed it
    // into an ellipsis at the default sidebar width.
    if (conversation.tokens) bits.push(`${formatTokens(conversation.tokens)} tok`);
    meta.textContent = bits.join(" · ");
    meta.title = bits.join(" · "); // in full, if the row still has to clip
    title.append(name, meta);
    // The title often isn't the subject: show what was actually asked.
    if (conversation.preview && conversation.preview !== conversation.title) {
      title.title = conversation.preview;
    }
    // One ⋯ instead of three buttons. In a sidebar this narrow they were
    // taking most of the row, leaving a few characters of the chat's name.
    const actions = document.createElement("span");
    actions.className = "entry-actions";
    const items = [];
    items.push(
      makeMenuItem(
        conversation.pinned ? "ph:push-pin-slash Unpin" : "ph:push-pin Pin",
        conversation.pinned ? "Let this chat sort by date again" : "Keep this chat at the top",
        async () => {
          await apiJson(`/conversations/${conversation.id}/pin`, {
            method: "PUT",
            body: JSON.stringify({ pinned: !conversation.pinned }),
          });
          loadConversationList();
        }
      )
    );
    items.push(
      makeMenuItem("ph:pencil-simple Rename", "Rename this chat", async () => {
        const next = await promptDialog("Rename this chat:", conversation.title);
        if (!next || !next.trim()) return;
        await apiJson(`/conversations/${conversation.id}`, {
          method: "PUT",
          body: JSON.stringify({ title: next.trim() }),
        });
        loadConversationList();
      })
    );
    items.push(
      makeMenuItem("ph:magic-wand Name with AI", "Let the AI name this chat", async () => {
        const named = await apiJson(`/conversations/${conversation.id}/retitle`, {
          method: "POST",
        }).catch((e) => {
          toast(e.message, true);
          return null;
        });
        if (!named) return;
        if (chatConv.id === conversation.id) $("chat-title").textContent = named.title;
        //: The AI naming a conversation is activity, not something the user
        //: did: so it obeys the same "pop up, or only in the centre" choice
        //: as every other thing the AI does on its own.
        agentActivityNotice(
          named.ai_named ? `Renamed to “${named.title}”.` : "Used the first question as the title.",
          { kind: "run" }
        );
        loadConversationList();
      })
    );
    items.push(
      // Not destructive, so not grouped with Delete below, same "keep it,
      // but out of the way" action Notes already has for entries (BACKLOG
      // §30b's named remaining scope: chats and documents). Reachable
      // again from the Library's Shelved filter.
      makeMenuItem("ph:archive Archive", "Keep it, but out of the way, not deleted", async () => {
        await apiJson(`/conversations/${conversation.id}/archive`, { method: "PUT" });
        if (chatConv.id === conversation.id) newChatConversation();
        toast("Archived.");
        loadConversationList();
      })
    );
    items.push(
      makeMenuItem("ph:trash Delete", "Delete this chat", async () => {
        if (!(await confirmDialog("Delete this saved chat?"))) return;
        await apiJson(`/conversations/${conversation.id}`, { method: "DELETE" });
        if (chatConv.id === conversation.id) newChatConversation();
        loadConversationList();
      })
    );
    actions.appendChild(kebabMenu(items, `Actions for ${conversation.title}`));
    li.append(title, actions);
    list.appendChild(li);
  }
}

// An edited answer is labelled, always. A transcript that silently presents
// your words as the model's is worse than no transcript.
function editedMarker() {
  const tag = document.createElement("span");
  tag.className = "edited-marker muted";
  tag.textContent = "edited by you";
  tag.title = "You changed this answer after the model wrote it";
  return tag;
}

// Editing questions has worked for a while; answers were fixed forever, so a
// model that got one detail wrong left you regenerating the whole thing and
// hoping. Editing in place keeps the rest of the thread intact.
function editChatAnswer(handles, turnIndex, current) {
  if (handles.bubble.querySelector(".answer-editor")) return; // already open
  const editor = document.createElement("div");
  editor.className = "answer-editor";
  const box = document.createElement("textarea");
  box.value = current;
  box.rows = Math.min(20, Math.max(4, current.split("\n").length + 1));
  box.setAttribute("aria-label", "Edit this answer");

  const target = handles.timeline.answerElement();
  const finish = (markdown) => {
    editor.remove();
    target.classList.remove("hidden");
    if (markdown !== null) handles.timeline.replaceAnswer(markdown);
  };

  const save = document.createElement("button");
  save.className = "small";
  save.type = "button";
  save.textContent = "Save";
  save.addEventListener("click", async () => {
    const next = box.value.trim();
    if (!next) {
      toast("An empty answer isn't a correction: delete the message instead.", true);
      return;
    }
    if (chatConv.id) {
      try {
        await apiJson(`/conversations/${chatConv.id}/turns/${turnIndex}/answer`, {
          method: "PUT",
          body: JSON.stringify({ content: next }),
        });
      } catch (error) {
        toast(error.message, true);
        return; // leave the editor open rather than losing the edit
      }
    }
    if (chatConv.turns[turnIndex]) chatConv.turns[turnIndex].answer = next;
    finish(next);
    if (!handles.bubble.querySelector(".edited-marker")) {
      handles.bubble.insertBefore(
        editedMarker(),
        handles.bubble.querySelector(".msg-actions")
      );
    }
    toast("Answer updated.");
  });

  const cancel = document.createElement("button");
  cancel.className = "ghost small";
  cancel.type = "button";
  cancel.textContent = "Cancel";
  cancel.addEventListener("click", () => finish(null));

  const row = document.createElement("div");
  row.className = "row";
  row.append(save, cancel);
  editor.append(box, row);
  target.classList.add("hidden");
  target.after(editor);
  box.focus();
}

async function openConversation(id) {
  const full = await apiJson(`/conversations/${id}`).catch(() => null);
  if (!full) return;
  // Before the pane is rebuilt, not after: this reads the composer state that
  // belongs to the conversation being left.
  releaseChatComposer();
  // ROADMAP.md item 13: switching between saved chats was invisible to
  // back/forward. Recorded here rather than at each of this function's
  // call sites (the sidebar, the Library) so neither has to remember to.
  recordTabVisit("chat", `conv:${full.id}`);
  chatConv = { id: full.id, turns: [] };
  chatAwaitingAgentAnswer = false; // a saved thread's own pending ask, if any, isn't answerable live
  // Not carried across conversations, and not persisted: re-deriving it is one
  // click, and a summary restored against the wrong thread would be worse than
  // no summary at all.
  chatSummary = null;
  renderCompressionState();
  $("chat-title").textContent = full.title;
  renderChatUsage(full.tokens);
  //: **Give the starter chips back before clearing the pane, not after.**
  //:
  //: Reported with a screenshot: *"I cant view older chat sessions, the
  //: panel/page just appears blank."* The title, model and token count in the
  //: header were all correct, only the transcript was empty, which is what
  //: made it look like a rendering problem with the messages rather than a
  //: crash.
  //:
  //: `#chat-suggest` is **on loan**. `chatEmptyState` *moves* that element out
  //: of the dock and into `.chat-empty` inside `#chat-messages` (see its own
  //: comment on why the starters belong with the welcome). So on any chat that
  //: was showing the empty state, every fresh load of the tab, the element
  //: is a child of the very thing being wiped here: `replaceChildren()`
  //: destroyed it, and the next line dereferenced `null` and threw.
  //:
  //: The throw landed exactly between "clear the transcript" and "render the
  //: messages", so the pane was emptied and then nothing was drawn. Every
  //: saved conversation opened blank, and the console error was the only
  //: sign.
  //:
  //: `clearChatEmptyState` already knows how to return the chips to the dock, 
  //: it exists for this, so the fix is to let it run first rather than to
  //: null-guard the symptom.
  clearChatEmptyState();
  $("chat-messages").replaceChildren();
  //: Optional-chained regardless: this element is moved between two parents at
  //: runtime, and a second caller that clears the pane should degrade to a
  //: stale chip strip rather than to a blank conversation.
  $("chat-suggest")?.classList.add("hidden");
  let lastQuestionText = null;
  for (const message of full.messages) {
    if (message.role === "user") {
      lastQuestionText = message.content;
      addBubble("user", message.content, message.attachments);
    } else {
      const handles = addAssistantBubble();
      // Replay the run in the order it happened when the turn recorded one.
      // Older turns (saved before steps existed) only have the flattened
      // thinking/tools/answer, so they're rebuilt in that fixed order, 
      // everything is still shown, just without the interleaving.
      if (message.steps && message.steps.length) {
        handles.timeline.replay(message.steps);
      } else {
        if (message.thinking) {
          handles.timeline.thinking(message.thinking);
        }
        // Re-draw the tool-activity chips (Wave G) so they don't vanish on
        // reload the way they used to (user-reported).
        for (const t of message.tools || []) {
          handles.timeline.tool(toolChip(t.label, t.ok !== false, t));
        }
        if (message.content) {
          handles.timeline.answer(message.content);
        }
      }
      handles.timeline.finalise();
      //: …and the step group, so a replayed turn does not reopen with
      //: "Working: 3 steps" over a conversation that finished yesterday.
      handles.timeline.finish?.();
      // Rebuild the metadata line. Reported in IDEAS.md as "chat message
      // metadata disappears on reload": it was only ever built from the live
      // stream, so reopening a chat showed answers with nothing to say which
      // model wrote them or what they cost. Turns saved before this stored no
      // stats and correctly get no line, rather than a row of "?"s.
      if (message.stats) {
        //: A reopened conversation gets its meter back from the last turn that
        //: recorded one: without this the header says nothing about a thread
        //: that is already 80% through its window, which is precisely the
        //: thread you want warned about.
        renderChatContextMeter(message.stats);
        handles.bubble.appendChild(
          messageMetaLine({
            model: message.stats.model,
            elapsedMs: message.elapsed_ms,
            stats: message.stats,
            toolCount: (message.tools || []).length,
            rounds: message.stats.round || 0,
            usedTools: message.used_tools ?? null,
          })
        );
      }
      //: **The Sources panel is rebuilt, not the thing it replaced.**
      //:
      //: Reported: *"a lot of the steps and agent process disappears when I
      //: leave the chat session and come back to it."* A live turn ends with
      //: the Sources panel: notes, files and web pages, with previews and
      //: links: and this path rebuilt the old "N matching notes" disclosure
      //: instead, which knows nothing about files or the web. So reopening a
      //: conversation genuinely lost most of what the turn had consulted, and
      //: what survived was drawn as a different control.
      //:
      //: `touched` comes back off the saved tool events, which have carried it
      //: since the live action line was built, the same rows, from the same
      //: place, so a reopened panel is the panel and not an approximation.
      const savedSources = chatSourcesPanel({
        meta: {
          raw_results: message.raw_results || [],
          search_mode: message.search_mode,
        },
        toolEvents: message.tools || [],
        touched: (message.tools || []).flatMap((t) => t.touched || []),
      });
      if (savedSources) {
        handles.recordsHolder.appendChild(savedSources);
      } else if (message.raw_results) {
        renderRecordsDetails(handles.recordsHolder, {
          raw_results: message.raw_results,
          search_mode: message.search_mode,
          match_info: message.match_info || {},
          connected_ids: message.connected_ids || [],
        });
      }
      // Same reload-reconstruction fix as raw_results just above, for the
      // "Grounded in" chips: reported directly as disappearing once the chat
      // tab was left or the session ended, since nothing rebuilt this on
      // reopen either.
      if (message.sentence_grounding) {
        renderAnswerGrounding(
          handles.groundingHolder,
          message.sentence_grounding,
          message.raw_results || [],
          handles.bubble?.querySelectorAll(".bubble-answer") || null
        );
      }
      // And the same shape again for the "what to ask next" chips, reported
      // separately: "suggested repsponse continuation prompts in chat doesnt
      // persist and disappears once I switch chat sessions or quit the app".
      // Rendered through the same function the live path uses, so a restored
      // chip is not a slightly different chip.
      if (message.followups) {
        renderFollowups(handles.bubble, message.followups);
      }
      const turnIndex = chatConv.turns.length; // index this pair will occupy
      if (message.edited) handles.bubble.appendChild(editedMarker());
      //: The same list the live stream builds, see `assistantMessageActions`.
      //: These two paths had already drifted (this one had Edit and no fork or
      //: rewrite; the live one the reverse), which is how a fix lands on half
      //: the app's messages.
      handles.bubble.appendChild(
        assistantMessageActions({
          bubble: handles.bubble,
          text: message.content,
          question: lastQuestionText,
          onEdit: () => editChatAnswer(handles, turnIndex, message.content),
        })
      );
      if (lastQuestionText !== null) {
        chatConv.turns.push({ question: lastQuestionText, answer: message.content });
      }
    }
  }
  // A conversation that is still being answered has not saved that turn yet, 
  // the save happens when the stream ends, so what came back from the server
  // above is the thread *without* the message in flight. Left alone, coming
  // back to it shows either an empty pane or a thread missing its newest
  // question: exactly the "my message disappeared" this whole change is about.
  // Saying so is the honest render, and the note is replaced by the real turn
  // the moment the stream finishes and the list refreshes.
  if (isStreamingConversation(full.id)) {
    // Coming back to the thread that is still being answered. The saved
    // messages above are the thread *without* this turn, it has not been
    // written yet, or exists only as a half-finished checkpoint row, which is
    // the reported "empty message bubble". Drop that partial and put the live
    // nodes back instead.
    const bubbles = $("chat-messages").querySelectorAll(".msg");
    const lastAssistant = [...bubbles].reverse().find((b) => b.classList.contains("assistant"));
    if (lastAssistant && !lastAssistant.textContent.trim()) {
      lastAssistant.previousElementSibling?.classList.contains("msg")
        && lastAssistant.previousElementSibling.remove();
      lastAssistant.remove();
    }
    reattachStreamingTurn();
  } else if (!full.messages.length) {
    renderChatEmptyState();
  }
  if (lastQuestionText) lastChatQuestion = lastQuestionText;
  loadConversationList();
  chatScrollToEnd();
}

async function loadChatSuggestions() {
  // Only the welcome placeholder may be present, real messages hide the chips.
  if ($("chat-messages").querySelector(".msg")) return;
  const picks = await apiJson("/chat/suggestions").catch(() => []);

  // Re-check after the await in case a message was sent while we waited
  if ($("chat-messages").querySelector(".msg")) return;

  // batch-a.md's "left open" item: `#chat-suggest` is on loan to `.chat-empty`
  // (see the long comment on `openConversation` below) and `newChatConversation`
  // used to wipe `#chat-messages` with a bare `replaceChildren()` without
  // sending it home first, so a "+ New" click while this call was still
  // awaiting the network took the element it was about to write to with it.
  // `newChatConversation` returns it home first now (below), so this should
  // not fire in practice any more; kept as the same defensive `?.`
  // `openConversation` already uses at its own call site, since a null box
  // here would otherwise throw past the point where anything could tell.
  const box = $("chat-suggest");
  if (!box) return;
  box.replaceChildren();
  box.classList.toggle("hidden", picks.length === 0);
  if (!picks.length) return;
  const label = document.createElement("span");
  label.className = "muted";
  label.textContent = "Try asking:";
  box.appendChild(label);
  for (const question of picks) {
    const chipEl = chip(question, "", () => sendChatMessage(question));
    box.appendChild(chipEl);
  }
  //: They arrive after the welcome was drawn, so the welcome takes them now.
  const empty = $("chat-messages").querySelector(".chat-empty");
  if (empty && !empty.contains(box)) empty.appendChild(box);
  // These chips arrive after the tab is drawn and are a row or two of height
  // the composer's fit was measured without.
  refitComposer();
}

// Personas section in Settings (Wave C, editing + reset in Wave D).
// Mirrors the backend's built-ins: editing one saves an override with the
// same name (the saved list wins), and Reset deletes the override.
const BUILTIN_PERSONAS = {
  Librarian: "You are the librarian of the user's personal notebook.",
  Coach:
    "You are an encouraging personal coach reviewing the user's notes. " +
    "Spot patterns, celebrate progress, and suggest one concrete next step.",
  Analyst:
    "You are a precise analyst. Extract the facts, numbers, and patterns " +
    "from the notes and organise your answer clearly.",
};

let personaEditing = null; // name currently in inline-edit mode

async function savePersonaList(personas) {
  await apiJson("/preferences", {
    method: "PUT",
    body: JSON.stringify({ personas }),
  });
  await renderPersonas();
  personaOptions();
}

async function renderPersonas() {
  prefsCache = await apiJson("/preferences").catch(() => prefsCache);
  const custom = (prefsCache && prefsCache.personas) || [];
  const overrides = new Map(custom.map((p) => [p.name, p]));
  const list = $("persona-list");
  list.replaceChildren();

  const rows = [
    ...Object.keys(BUILTIN_PERSONAS).map((name) => ({
      name,
      builtin: true,
      overridden: overrides.has(name),
      prompt: overrides.has(name) ? overrides.get(name).prompt : BUILTIN_PERSONAS[name],
    })),
    ...custom
      .filter((p) => !(p.name in BUILTIN_PERSONAS))
      .map((p) => ({ ...p, builtin: false, overridden: false })),
  ];

  for (const persona of rows) {
    const li = document.createElement("li");

    if (personaEditing === persona.name) {
      // Inline editor: textarea + save/cancel.
      const textarea = document.createElement("textarea");
      textarea.rows = 3;
      textarea.value = persona.prompt;
      const row = document.createElement("div");
      row.className = "row";
      row.appendChild(
        smallButton(
          "Save",
          "",
          async () => {
            const prompt = textarea.value.trim();
            if (!prompt) return;
            const updated = custom.filter((p) => p.name !== persona.name);
            updated.push({ name: persona.name, prompt });
            personaEditing = null;
            await savePersonaList(updated);
          },
          false
        )
      );
      row.appendChild(
        smallButton("Cancel", "", () => {
          personaEditing = null;
          renderPersonas();
        })
      );
      li.append(chip(persona.name), textarea, row);
      list.appendChild(li);
      setTimeout(() => textarea.focus(), 0);
      continue;
    }

    const row = document.createElement("div");
    row.className = "entry-meta";
    row.appendChild(chip(persona.name));
    if (persona.builtin) {
      row.appendChild(chip(persona.overridden ? "edited" : "built-in", "tag"));
    }
    const note = document.createElement("span");
    note.className = "muted persona-preview";
    note.textContent = persona.prompt.slice(0, 70);
    row.appendChild(note);

    const actions = document.createElement("span");
    actions.className = "entry-actions";
    actions.appendChild(
      smallButton("Edit", "Edit this persona's prompt", () => {
        personaEditing = persona.name;
        renderPersonas();
      })
    );
    if (persona.builtin && persona.overridden) {
      actions.appendChild(
        smallButton("Reset", "Restore the default prompt", async () => {
          await savePersonaList(custom.filter((p) => p.name !== persona.name));
        })
      );
    }
    if (!persona.builtin) {
      actions.appendChild(
        smallButton("Delete", "Remove this persona", async () => {
          if (!(await confirmDialog(`Delete the “${persona.name}” persona?`))) return;
          await savePersonaList(custom.filter((p) => p.name !== persona.name));
        })
      );
    }
    row.appendChild(actions);
    li.appendChild(row);
    list.appendChild(li);
  }
  renderDashboardPersonaSelect(rows.map((p) => p.name));
}

// A second, independent picker (asked for directly): the dashboard greeting
// otherwise always spoke in whichever persona Chat had active, with no way
// to give the notebook's own front page a different voice. "" means "no
// override" and falls back to active_persona server-side, same clear-with-
// empty-string convention display_name/dashboard_persona already share.
function renderDashboardPersonaSelect(names) {
  const select = $("dashboard-persona-select");
  const current = (prefsCache && prefsCache.dashboard_persona) || "";
  select.replaceChildren();
  const sameAsChat = document.createElement("option");
  sameAsChat.value = "";
  sameAsChat.textContent = "Same as Chat";
  select.appendChild(sameAsChat);
  for (const name of names) {
    const option = document.createElement("option");
    option.value = name;
    option.textContent = name;
    select.appendChild(option);
  }
  select.value = current;
}

async function addPersona() {
  const name = $("persona-name").value.trim();
  const promptText = $("persona-prompt").value.trim();
  const status = $("persona-status");
  if (!name || !promptText) {
    status.textContent = "Both a name and a prompt are needed.";
    return;
  }
  const custom = ((prefsCache && prefsCache.personas) || []).filter(
    (p) => p.name !== name
  );
  custom.push({ name, prompt: promptText });
  await apiJson("/preferences", {
    method: "PUT",
    body: JSON.stringify({ personas: custom }),
  });
  $("persona-name").value = "";
  $("persona-prompt").value = "";
  status.textContent = `Added “${name}”.`;
  await renderPersonas();
  personaOptions();
}

// --- skills (§21): named, repeatable jobs over the notebook ----------------------

// A skill used to be {name, prompt} and clicking one dropped its prompt into
// the chat box. It is now a job: what to do, the steps to do it in, the tools
// it may use, and the values it asks for first. The built-in ones used to be
// a list right here, which meant the server could not resolve a skill the
// user clicked; they are served from GET /skills now, alongside the user's own.
let skillsCache = [];
let skillLimits = { steps: 10, tools: 12, inputs: 5 };

async function loadSkills() {
  const body = await apiJson("/skills").catch(() => null);
  if (!body) return skillsCache;
  skillsCache = body.skills || [];
  if (body.limits) skillLimits = body.limits;
  return skillsCache;
}

function allSkills() {
  return skillsCache;
}

function customSkills() {
  return skillsCache.filter((skill) => !skill.builtin);
}

// Which custom skill (by name) the editor is currently editing, if any.
// Tracking it lets Edit rename a skill instead of leaving a duplicate.
let editingSkillName = null;

// Steps and inputs are edited as one-per-line text, which is the shape people
// already write a list in. An input is "name" or "name: the question to ask".
function stepsToText(steps) {
  return (steps || []).join("\n");
}

function textToSteps(text) {
  return text
    .split("\n")
    .map((line) => line.trim())
    .filter(Boolean);
}

function inputsToText(inputs) {
  return (inputs || [])
    .map((item) => (item.label && item.label !== `${item.name}?` ? `${item.name}: ${item.label}` : item.name))
    .join("\n");
}

function textToInputs(text) {
  return textToSteps(text).map((line) => {
    const [name, ...rest] = line.split(":");
    return { name: name.trim(), label: rest.join(":").trim(), required: true };
  });
}

function startEditingSkill(skill) {
  editingSkillName = skill.name;
  $("skill-name").value = skill.name;
  $("skill-prompt").value = skill.prompt;
  $("skill-description").value = skill.description || "";
  $("skill-steps").value = stepsToText(skill.steps);
  $("skill-inputs").value = inputsToText(skill.inputs);
  renderSkillToolPicker(skill.tools || []);
  $("skill-add").textContent = "Save changes";
  $("skill-cancel").classList.remove("hidden");
  $("skill-status").textContent = `Editing “${skill.name}”…`;
  $("skill-prompt").focus();
}

function stopEditingSkill() {
  editingSkillName = null;
  for (const id of ["skill-name", "skill-prompt", "skill-description", "skill-steps", "skill-inputs"]) {
    $(id).value = "";
  }
  renderSkillToolPicker([]);
  $("skill-add").textContent = "Add skill";
  $("skill-cancel").classList.add("hidden");
  $("skill-status").textContent = "";
}

// The tools a skill may use, as checkboxes over the real registry, so a
// skill cannot name a tool that doesn't exist, and picking them is a matter
// of reading rather than remembering.
async function renderSkillToolPicker(selected = []) {
  const box = $("skill-tool-list");
  if (!box) return;
  const chosen = new Set(selected);
  const catalog = await apiJson("/chat/tools").catch(() => []);
  box.replaceChildren();
  for (const tool of catalog) {
    const label = document.createElement("label");
    label.className = "check-row";
    const input = document.createElement("input");
    input.type = "checkbox";
    input.value = tool.name;
    input.checked = chosen.has(tool.name);
    const text = document.createElement("span");
    text.textContent = tool.name;
    text.title = tool.description;
    label.append(input, text);
    box.appendChild(label);
  }
}

function chosenSkillTools() {
  const box = $("skill-tool-list");
  if (!box) return [];
  return [...box.querySelectorAll("input:checked")].map((input) => input.value);
}

// Run a skill. The server owns what a skill is, so this sends its name and
// the values it asked for, not a prompt assembled here. The mode a skill runs
// in is settled in `startSkill`, which both entry points go through.
function runSkill(skill) {
  if ((skill.inputs || []).length) {
    askSkillInputs(skill, (values) => startSkill(skill, values));
    return;
  }
  startSkill(skill, {});
}

// A plan the model drew for the last request, run the way a skill is run
// (§35K). The steps are sent back rather than parked on the server, for the
// same reason `ask_user`'s answer is: nothing to expire, nothing lost on a
// reload, and the run is a message in the conversation like any other.
function startPlannedRun(goal, steps) {
  switchTab("chat"); // same reason as startSkill: the run happens in the chat
  sendChatMessage(goal, { plan: { goal, steps }, skipPlanMode: true });
}

async function startSkill(skill, values) {
  // Both entry points land here, the Skill dropdown and a run the agent started
  // itself (§33): so the dashboard's recent-skill buttons cover both.
  noteSkillRun(skill.name);
  // **And so does the dashboard's Skill chip, which is why this is here.**
  // Reported: *"when I click on the suggested skills in the dashboard, it runs
  // the skill but doesn't navigate me to it."* Exactly right: the run started,
  // the answer streamed into a tab nobody was looking at, and the dashboard sat
  // there as though the button had done nothing. A skill *is* a message in the
  // conversation, so starting one has to take you to the conversation. From
  // the Skill dropdown, where you are already here, this is a no-op.
  switchTab("chat");
  //: **A skill runs in Agent mode, and says so** (INBOX 39, the owner's
  //: decision).
  //:
  //: The rule until now was the opposite: an *action* skill carried its own
  //: permission, so the backend turned tools on for that one call
  //: (`skill["acts"]` in routes_chat.py) and the toggle was deliberately left
  //: alone. As a contract that is tidy; read as a person it is not. The
  //: segment said "Ask" while the run was creating and tagging notes, a
  //: non-acting skill quietly got a different toolbox depending on a control
  //: nobody had touched, and the mode a run actually used was invisible until
  //: the meta line under the answer.
  //:
  //: So the mode moves, once, before the run starts, and stays moved: a
  //: setting that flips back on its own is a worse surprise than one that
  //: does not. Announced in a line, the way Plan mode already announces the
  //: same switch, because a mode that changed under you and said so beats
  //: "why can it suddenly do that?".
  //:
  //: Awaited, not fired off: `sendChatMessage` reads `#tools-toggle` to decide
  //: what this turn sends and what the saved turn records, so the checkbox has
  //: to be true before the message leaves.
  if (!$("tools-toggle").checked) {
    await setChatMode("agent");
    toast("Switched to Agent for this skill.");
  }
  const given = Object.values(values).filter(Boolean).join(", ");
  sendChatMessage(`${skill.name}${given ? `, ${given}` : ""}`, {
    skill: skill.name,
    skillInputs: values,
    // A skill is its own instruction. Wrapping it in "plan this first" would
    // plan a thing that already has steps.
    skipPlanMode: true,
  });
}

// One dialog for everything a skill asks for. Two window.prompt boxes in a
// row is how this started, and the second one gave no clue which skill it
// belonged to or what the first answer had been.
function askSkillInputs(skill, done) {
  const overlay = $("skill-run-overlay");
  const fields = $("skill-run-fields");
  $("skill-run-title").textContent = skill.name;
  $("skill-run-description").textContent = skill.description || skill.prompt;
  fields.replaceChildren();
  const inputs = [];
  for (const item of skill.inputs || []) {
    const label = document.createElement("label");
    label.className = "field";
    const text = document.createElement("span");
    text.textContent = item.label || item.name;
    const box = document.createElement("input");
    box.type = "text";
    box.value = item.default || "";
    box.maxLength = 200;
    box.placeholder = item.required ? "" : "optional";
    label.append(text, box);
    fields.appendChild(label);
    inputs.push({ item, box });
  }

  const close = () => {
    overlay.classList.add("hidden");
    document.removeEventListener("keydown", onKey);
  };
  const submit = () => {
    const values = {};
    for (const { item, box } of inputs) {
      const value = box.value.trim();
      if (!value && item.required && !item.default) {
        box.focus();
        // Nothing is sent half-filled: a skill run with a blank {{topic}}
        // searches the whole notebook for nothing and reads as being ignored.
        toast(`“${skill.name}” needs ${item.label || item.name}.`, true);
        return;
      }
      values[item.name] = value;
    }
    close();
    done(values);
  };
  const onKey = (event) => {
    if (event.key === "Escape") close();
    else if (event.key === "Enter" && event.target.tagName === "INPUT") submit();
  };

  $("skill-run-go").onclick = submit;
  $("skill-run-cancel").onclick = close;
  document.addEventListener("keydown", onKey);
  overlay.classList.remove("hidden");
  inputs[0]?.box.focus();
}

// Skills as a dropdown rather than a row of chips. Ten built-ins plus up to
// thirty of your own is a wrapping wall of buttons that pushes the message box
// off the screen, and every one of them is a click you can make by accident
// while reaching for the text area. A select is one line, groups "yours" apart
// from the built-ins, and, the part that matters, leaves room to say what a
// skill DOES next to its name instead of hiding it in a hover.
// The skills group in the chat dock: everything about running a saved job,
// in one place.
//
// It was a lightning mark, a select, a Run button and a bare "＋" that opened
// Settings: with the "run skills step-by-step" preference stranded three
// controls away inside the gear popup, where nobody found it. Asked for
// directly: fold the "+" into the combobox as an option, put the step-by-step
// choice next to the skill it applies to as a two-option pill, and keep Run.
//
// The pill and the hidden checkbox is the same pattern the Ask/Agent pair
// already uses in this strip: the checkbox stays as the thing the rest of the
// app reads and stores (`sendChatMessage` reads `#skill-manual-toggle`), and
// the pill is what a person operates. Two named options rather than a tickbox,
// because a tickbox states one mode and leaves the other implied, "not
// step-by-step" had no name and no description.
const SKILL_MANAGE_VALUE = "__manage__";

async function loadChatSkills() {
  await loadSkills();
  const box = $("chat-skills");
  box.replaceChildren();

  const label = document.createElement("span");
  label.className = "muted chat-skill-mark";
  setLabel(label, "ph:lightning");
  label.title = "Skills: saved jobs you can run over your notes";

  const select = document.createElement("select");
  select.className = "small-select chat-skill-select";
  select.id = "chat-skill-select";
  select.setAttribute("aria-label", "Activate a skill");
  const placeholder = document.createElement("option");
  placeholder.value = "";
  placeholder.textContent = "Activate a skill…";
  select.appendChild(placeholder);

  const groups = { builtin: [], mine: [] };
  for (const skill of allSkills()) {
    groups[skill.builtin ? "builtin" : "mine"].push(skill);
  }
  for (const [key, title] of [["mine", "Yours"], ["builtin", "Built-in"]]) {
    if (!groups[key].length) continue;
    const group = document.createElement("optgroup");
    group.label = title;
    for (const skill of groups[key]) {
      const option = document.createElement("option");
      option.value = skill.name;
      // An <option> cannot contain an element, so the "this one changes your
      // notebook" marker has to be a word. It was an emoji, and then briefly a
      // `ph:` marker: which would have rendered as the literal text
      // "ph:gear" in the list, since setLabel has no element to build into.
      option.textContent = skill.name + (skill.changes ? "  (edits notes)" : "");
      option.title = skillSummary(skill);
      group.appendChild(option);
    }
    select.appendChild(group);
  }

  // Managing skills is one of the things you come to this control to do, so it
  // is in the list rather than beside it as an unlabelled "＋". Its own group,
  // at the bottom, so it never sits among the runnable options.
  const manageGroup = document.createElement("optgroup");
  manageGroup.label = "Manage";
  const manage = document.createElement("option");
  manage.value = SKILL_MANAGE_VALUE;
  manage.textContent = "Add or edit skills…";
  manageGroup.appendChild(manage);
  select.appendChild(manageGroup);

  // Chosen, then run: rather than running on change. A dropdown that fires an
  // action the instant it changes cannot be browsed, and these actions edit
  // the notebook. "Add or edit skills…" is the exception: it opens a settings
  // pane, which is safe and is the whole reason to pick it.
  const run = smallButton("ph:play Run", "Run the selected skill", () => {
    const chosen = allSkills().find((s) => s.name === select.value);
    if (chosen) runSkill(chosen);
  });
  run.disabled = true;
  select.addEventListener("change", () => {
    if (select.value === SKILL_MANAGE_VALUE) {
      select.value = "";
      run.disabled = true;
      openSettingsModal("skills");
      return;
    }
    run.disabled = !select.value;
    // What the skill does lives in the select's own tooltip rather than a line
    // of prose beside it, it was the widest thing in the dock and clipped at
    // 120 characters anyway.
    const chosen = allSkills().find((s) => s.name === select.value);
    select.title = chosen ? skillSummary(chosen) : "Run one of your saved skills";
  });

  // **One "Skills" dropdown, not four controls loose in the strip.** Asked for
  // directly, twice: the selector, the Auto|Manual pill and Run belong inside
  // a Skills menu, not spread across the dock competing with Ask/Agent/Web/
  // Plan for width. Running a skill is one job; it should occupy one control
  // until you are actually doing it.
  //
  // Built on the same trigger-plus-panel shape as the gear popup two groups
  // along (.chat-dock-more), because a second popup pattern in one strip is
  // how a toolbar starts looking assembled rather than designed.
  const trigger = document.createElement("button");
  trigger.type = "button";
  trigger.id = "chat-skills-btn";
  trigger.className = "ghost small";
  trigger.setAttribute("aria-haspopup", "dialog");
  trigger.setAttribute("aria-expanded", "false");
  trigger.setAttribute("aria-controls", "chat-skills-panel");
  trigger.title = "Skills: saved jobs you can run over your notes";
  setLabel(trigger, "ph:lightning Skills");

  const panel = document.createElement("div");
  panel.id = "chat-skills-panel";
  panel.className = "chat-skills-panel hidden";
  panel.setAttribute("role", "dialog");
  panel.setAttribute("aria-label", "Run a skill");

  const pickRow = document.createElement("label");
  pickRow.className = "chat-skills-row";
  const pickLabel = document.createElement("span");
  pickLabel.className = "muted";
  pickLabel.textContent = "Skill";
  pickRow.append(pickLabel, select);

  const paceRow = document.createElement("div");
  paceRow.className = "chat-skills-row";
  const paceLabel = document.createElement("span");
  paceLabel.className = "muted";
  paceLabel.textContent = "Pace";
  paceRow.append(paceLabel, skillPacePill());

  const runRow = document.createElement("div");
  runRow.className = "chat-skills-run";
  runRow.appendChild(run);

  panel.append(pickRow, paceRow, runRow);

  const close = () => {
    panel.classList.add("hidden");
    trigger.setAttribute("aria-expanded", "false");
  };
  trigger.addEventListener("click", (event) => {
    event.stopPropagation();
    const open = trigger.getAttribute("aria-expanded") === "true";
    trigger.setAttribute("aria-expanded", String(!open));
    panel.classList.toggle("hidden", open);
    //: See `focusSelect`: a bare `select.focus()` here left the skills panel
    //: open with nothing focused, so the first Tab went to the top of the page.
    if (!open) focusSelect(select);
  });
  document.addEventListener("click", (event) => {
    if (!box.contains(event.target)) close();
  });
  document.addEventListener("keydown", (event) => {
    if (event.key === "Escape") close();
  });
  // Running one is the end of the interaction, so the menu gets out of the way.
  run.addEventListener("click", close);

  // The trigger says which skill is armed, so the dock still answers "what is
  // this about to do?" without being opened.
  select.addEventListener("change", () => {
    setLabel(
      trigger,
      select.value && select.value !== SKILL_MANAGE_VALUE
        ? `ph:lightning ${select.selectedOptions[0].textContent}`
        : "ph:lightning Skills"
    );
  });

  box.append(trigger, panel);
  box.classList.remove("hidden");
  void label; // the group's mark is the trigger's own icon now
}

// Auto | Manual, over the hidden #skill-manual-toggle checkbox that the rest of
// the app reads. Kept in sync both ways: Settings can still flip the checkbox,
// and the pill follows.
function skillPacePill() {
  const seg = document.createElement("div");
  seg.className = "seg seg-compact chat-skill-pace";
  seg.setAttribute("role", "group");
  seg.setAttribute("aria-label", "How a skill runs");

  const toggle = $("skill-manual-toggle");
  const options = [
    ["auto", "Auto", "Run every step straight through without stopping."],
    ["manual", "Manual", "Pause after each step so you can add something before it continues."],
  ];
  const buttons = [];
  for (const [value, text, title] of options) {
    const button = document.createElement("button");
    button.type = "button";
    button.dataset.pace = value;
    button.textContent = text;
    button.title = title;
    button.addEventListener("click", () => {
      if (toggle) {
        toggle.checked = value === "manual";
        // `change`, so anything else listening to the stored preference, the
        // Settings row, a future autosave, hears it. Setting .checked in JS
        // does not fire one on its own, which is the classic way a pill and
        // the thing it controls drift apart.
        toggle.dispatchEvent(new Event("change", { bubbles: true }));
      }
      paint();
    });
    buttons.push(button);
    seg.appendChild(button);
  }

  function paint() {
    const manual = Boolean(toggle?.checked);
    for (const button of buttons) {
      const on = (button.dataset.pace === "manual") === manual;
      button.classList.toggle("active", on);
      button.setAttribute("aria-pressed", String(on));
    }
  }
  toggle?.addEventListener("change", paint);
  paint();
  return seg;
}

// --- the composer's two nudges (BACKLOG: agent-mode + skill auto-detect) -----
//
// Both capabilities were reachable only by people who already knew where the
// controls were. Typing "delete the notes I tagged scratch" in Ask mode gets a
// careful description of how one might do that, because Ask genuinely cannot
// act; and a skill someone wrote last month for exactly that job sits behind a
// dropdown behind a popup. Neither is a bug, they are both "a capability with
// no control is a capability most people never meet", the same observation
// that put the Plan button in the dock.
//
// The rules this follows, because a nudge that gets any of them wrong is worse
// than no nudge at all:
//
// - **It never acts.** It offers a button. Switching modes and running a skill
//   are both things that change what happens to your notes.
// - **Dismiss means dismissed.** Per draft, per kind, clearing the box or
//   sending resets it, so it does not become a thing you dismiss every time.
// - **It stays quiet when it has nothing to add**: already in Agent mode, or
//   the text is too short to be a request at all.
//
// Matching is a heuristic here rather than a model call for the same reason
// ai/intent.py's is: it runs on every keystroke (debounced), so it has to be
// instant, and a local model call per keystroke is neither.

// Verbs that only mean something if the assistant can act. Deliberately
// narrow: "write" and "find" are absent because "write me a poem" and "find
// out what X means" are ordinary Ask questions, and a nudge that fires on
// those is noise on most messages.
const AGENT_INTENT_RE = new RegExp(
  "\\b(?:" +
    "delete|remove|archive|rename|merge|de-?duplicate|dedupe|" +
    "tag|untag|re-?tag|link|unlink|organi[sz]e|tidy|clean ?up|sort|categori[sz]e|" +
    "create|make|add|save|append|update|edit|change|move|" +
    "schedule|remind me|set a reminder|" +
    "summari[sz]e (?:my|all|the|every)|go through (?:my|all|the)" +
    ")\\b",
  "i"
);

// A second, independent trigger: things that need the web tool specifically.
const AGENT_WEB_RE = /\b(?:search the web|look (?:this |it )?up online|google|browse to|open (?:this |the )?(?:page|link|url)|https?:\/\/)/i;

// A draft is "a request" only if it also names something in the notebook, or
// is plainly imperative. Without this, "I should probably tag things better"
//, a musing, not an instruction, fires the nudge.
const AGENT_OBJECT_RE = /\b(?:not(?:e|es)|entr(?:y|ies)|tag(?:s|ged)?|document|documents|space|spaces|reminder|reminders|task|tasks|link(?:s|ed)?|my notebook|everything)\b/i;

// Which nudges this draft has been told to stop offering. Reset when the box
// empties or a message is sent, see the input handler at the bottom of this
// file.
const chatNudgeDismissed = new Set();

function looksLikeAnAgentRequest(text) {
  if (text.trim().length < 8) return false;
  if (AGENT_WEB_RE.test(text)) return true;
  return AGENT_INTENT_RE.test(text) && AGENT_OBJECT_RE.test(text);
}

// The skill whose name (or description) the draft is most plainly asking for,
// or null. Scored rather than first-match: with a dozen skills installed, the
// one that shares three words with what you typed is a better guess than
// whichever happens to sort first.
function skillMatchingDraft(text) {
  const haystack = text.toLowerCase();
  if (haystack.trim().length < 8) return null;
  let best = null;
  let bestScore = 0;
  for (const skill of allSkills()) {
    const name = String(skill.name || "");
    if (!name) continue;
    // A name typed out in full is as explicit as it gets, nothing scored
    // word-by-word should be able to beat it.
    let score = haystack.includes(name.toLowerCase()) ? 10 : 0;
    // Words short enough to be incidental ("a", "the", "my", "and") match
    // everything and would make every skill look relevant.
    const words = `${name} ${skill.description || ""}`
      .toLowerCase()
      .split(/[^a-z0-9]+/)
      .filter((w) => w.length > 4);
    const seen = new Set();
    for (const word of words) {
      if (seen.has(word)) continue;
      seen.add(word);
      if (haystack.includes(word)) score += 1;
    }
    if (score > bestScore) {
      bestScore = score;
      best = skill;
    }
  }
  // Two independent words, or the name in full. One shared word is a
  // coincidence on any notebook with more than a few skills.
  return bestScore >= 2 ? best : null;
}

function renderChatNudge() {
  const box = $("chat-nudge");
  if (!box) return;
  const text = $("chat-input")?.value || "";
  box.replaceChildren();

  const offers = [];
  // Mode first: it changes what the message can do at all, so it outranks
  // "there is a saved job for this".
  if (
    !chatNudgeDismissed.has("agent") &&
    !$("tools-toggle")?.checked &&
    looksLikeAnAgentRequest(text)
  ) {
    offers.push({
      kind: "agent",
      icon: "ph:robot",
      text: "That reads like something to do, not something to answer. Ask mode can't touch your notes.",
      action: "Switch to Agent",
      run: () => setChatMode("agent"),
    });
  }
  if (!chatNudgeDismissed.has("skill")) {
    const skill = skillMatchingDraft(text);
    if (skill) {
      offers.push({
        kind: "skill",
        icon: "ph:lightning",
        text: `You have a skill for this: “${skill.name}”.`,
        action: "Run it",
        title: skillSummary(skill),
        run: () => runSkill(skill),
      });
    }
  }

  // One at a time. Two stacked nudges above a one-line composer is the dock
  // arguing with you rather than helping.
  const offer = offers[0];
  box.classList.toggle("hidden", !offer);
  if (!offer) return;

  const mark = document.createElement("span");
  mark.className = "chat-nudge-mark";
  setLabel(mark, offer.icon);
  const line = document.createElement("span");
  line.className = "chat-nudge-text";
  line.textContent = offer.text;
  const act = smallButton(offer.action, offer.title || offer.action, () => {
    // Whatever the offer was, taking it ends it, re-offering the switch you
    // just made would be the dock talking to itself.
    chatNudgeDismissed.add(offer.kind);
    renderChatNudge();
    offer.run();
  }, false);
  const dismiss = smallButton("ph:x", "Dismiss this suggestion", () => {
    chatNudgeDismissed.add(offer.kind);
    renderChatNudge();
  });
  dismiss.classList.add("chat-nudge-dismiss");
  box.append(mark, line, act, dismiss);
}

// Cleared when the draft is, a new message is a new question, and the
// suggestion you turned down for the last one should not follow it.
function resetChatNudge() {
  chatNudgeDismissed.clear();
  renderChatNudge();
}

function skillSummary(skill) {
  const lines = [skill.description || skill.prompt];
  if (skill.changes) lines.push("(This one changes your notes, deletes still ask first.)");
  if ((skill.steps || []).length) {
    lines.push("", ...skill.steps.map((step, i) => `${i + 1}. ${step}`));
  }
  if ((skill.tools || []).length) lines.push("", `Tools: ${skill.tools.join(", ")}`);
  if ((skill.inputs || []).length) {
    lines.push("", `Asks you for: ${skill.inputs.map((i) => i.name).join(", ")}`);
  }
  return lines.join("\n");
}

async function saveSkillList(skills) {
  prefsCache = await apiJson("/preferences", {
    method: "PUT",
    body: JSON.stringify({ skills }),
  });
  await loadSkills();
  renderSkillSettings();
  loadChatSkills();
}

function skillRow(skill) {
  const li = document.createElement("li");
  const row = document.createElement("div");
  row.className = "entry-meta skill-row";
  row.appendChild(chip(skill.name));
  if (skill.builtin) row.appendChild(chip("built-in", "tag"));
  if (skill.changes) row.appendChild(chip("changes notes", "tag"));
  if ((skill.steps || []).length) {
    row.appendChild(chip(`${skill.steps.length} steps`, "tag"));
  }
  if ((skill.tools || []).length) {
    row.appendChild(chip(`${skill.tools.length} tools`, "tag"));
  }
  for (const item of skill.inputs || []) row.appendChild(chip(`asks: ${item.name}`, "tag"));
  // Its own class, not `persona-preview`. That one is `white-space: nowrap`
  // with an ellipsis, which is right for a persona (one line of voice) and
  // wrong here: a skill's description is the only thing that says what it
  // *does*, and clipping it to the width left over after five chips showed
  // three words. Reported twice. It wraps onto its own line now.
  const note = document.createElement("span");
  note.className = "muted skill-blurb";
  note.textContent = skill.description || skill.prompt;
  row.appendChild(note);
  if (!skill.builtin) {
    const actions = document.createElement("span");
    actions.className = "entry-actions";
    actions.appendChild(
      smallButton("Edit", "Edit this skill", () => startEditingSkill(skill))
    );
    actions.appendChild(
      smallButton("Delete", "Remove this skill", async () => {
        if (!(await confirmDialog(`Delete the “${skill.name}” skill?`))) return;
        await saveSkillList(customSkills().filter((s) => s.name !== skill.name));
      })
    );
    row.appendChild(actions);
  }
  li.appendChild(row);
  return li;
}

async function renderSkillSettings() {
  await loadSkills();
  const list = $("skill-list");
  list.replaceChildren();
  for (const skill of allSkills()) list.appendChild(skillRow(skill));
  if (!$("skill-tool-list").children.length) renderSkillToolPicker([]);
}

async function addSkill() {
  const name = $("skill-name").value.trim();
  const promptText = $("skill-prompt").value.trim();
  const status = $("skill-status");
  status.classList.remove("error");
  if (!name || !promptText) {
    status.textContent = "Both a name and a request are needed.";
    return;
  }
  // Drop any skill with the new name AND (when editing) the one being edited,
  // so saving updates in place and even a rename doesn't leave a duplicate.
  const custom = customSkills().filter(
    (s) => s.name !== name && s.name !== editingSkillName
  );
  custom.push({
    name,
    prompt: promptText,
    description: $("skill-description").value.trim(),
    steps: textToSteps($("skill-steps").value),
    tools: chosenSkillTools(),
    inputs: textToInputs($("skill-inputs").value),
  });
  const wasEditing = editingSkillName;
  try {
    await saveSkillList(custom);
  } catch (error) {
    // The server validates both ways in, so this is the same message the AI
    // would get for the same mistake, an undeclared {{placeholder}}, say.
    status.classList.add("error");
    status.textContent = error.message;
    return;
  }
  stopEditingSkill();
  status.textContent = wasEditing ? `Updated “${name}”.` : `Saved “${name}”.`;
}

// --- Wave O: agent-tools toggles ----------------------------------------------------

// How many tool descriptions each message carries (§11a). Saved on change
// rather than behind an Apply button, the search-engine picker taught us
// that a control which saves nothing until later reads as broken, because
// the next status poll paints the old value back over it.
function renderToolFocus(current) {
  for (const radio of document.querySelectorAll('input[name="tool-focus"]')) {
    radio.checked = radio.value === current;
    radio.onchange = async () => {
      if (!radio.checked) return;
      const status = $("tool-focus-status");
      status.textContent = "Saving…";
      prefsCache = await apiJson("/preferences", {
        method: "PUT",
        body: JSON.stringify({ tool_focus: radio.value }),
      });
      status.textContent =
        radio.value === "auto"
          ? "Each message is offered the tools it needs."
          : "Every message is offered every tool.";
    };
  }
}

//: **The Phase B setting, given the control it never had.** `small_model_mode`
//: has been on GET/PUT /preferences since the skills reform's backend half,
//: read by the chat route on every run, with nothing anywhere in the app that
//: could change it, so every notebook ran on `auto` whatever its owner wanted.
//: Saved on change for the same reason the tool-focus radios above are: a
//: control that waits for an Apply button reads as broken here, because the
//: next preferences render paints the old value back over it.
function renderSmallModelMode(current) {
  const select = $("small-model-mode");
  if (!select) return;
  select.value = current || "auto";
}

$("small-model-mode")?.addEventListener("change", async () => {
  const select = $("small-model-mode");
  const status = $("small-model-mode-status");
  if (status) status.textContent = "Saving…";
  try {
    prefsCache = await apiJson("/preferences", {
      method: "PUT",
      body: JSON.stringify({ small_model_mode: select.value }),
    });
  } catch (error) {
    if (status) {
      status.classList.add("error");
      status.textContent = error.message;
    }
    return;
  }
  if (!status) return;
  status.classList.remove("error");
  status.textContent =
    select.value === "on"
      ? "Every skill step is offered only the tool it names."
      : select.value === "off"
        ? "Every step is offered the skill's whole toolbox."
        : "Decided per run from the chat model's name.";
});

//: **The run budget** (Brief 13), the same shape as the two controls above:
//: saved on change, because a control that waits for an Apply button reads as
//: broken here, the next preferences render paints the old value back over it.
//: Both fields together in one request, so a person who edits one and then the
//: other does not race two writes of the same preferences file.
function renderRunBudget(prefs) {
  const tokens = $("run-budget-tokens");
  const seconds = $("run-budget-seconds");
  if (tokens) tokens.value = String(prefs.run_budget_tokens ?? 20000);
  if (seconds) seconds.value = String(prefs.run_budget_seconds ?? 90);
}

async function saveRunBudget() {
  const tokens = $("run-budget-tokens");
  const seconds = $("run-budget-seconds");
  const status = $("run-budget-status");
  if (!tokens || !seconds) return;
  //: Clamped here as well as by the server: a negative number in a number
  //: input is one keystroke away, and the failure it causes (a budget that is
  //: exceeded before the first round) would look like the feature being
  //: broken rather than like a typo.
  const body = {
    run_budget_tokens: Math.max(0, Math.round(Number(tokens.value) || 0)),
    run_budget_seconds: Math.max(0, Math.round(Number(seconds.value) || 0)),
  };
  if (status) status.textContent = "Saving…";
  try {
    prefsCache = await apiJson("/preferences", {
      method: "PUT",
      body: JSON.stringify(body),
    });
  } catch (error) {
    if (status) {
      status.classList.add("error");
      status.textContent = error.message;
    }
    return;
  }
  if (!status) return;
  status.classList.remove("error");
  const parts = [];
  parts.push(body.run_budget_tokens ? `${body.run_budget_tokens} tokens` : "no token limit");
  parts.push(body.run_budget_seconds ? `${body.run_budget_seconds}s` : "no time limit");
  status.textContent = `A run may spend ${parts.join(" and ")}.`;
}

$("run-budget-tokens")?.addEventListener("change", saveRunBudget);
$("run-budget-seconds")?.addEventListener("change", saveRunBudget);

async function renderToolSettings() {
  const list = $("tool-list");
  const [catalog, prefs] = await Promise.all([
    apiJson("/chat/tools").catch(() => []),
    apiJson("/preferences").catch(() => ({ disabled_tools: [] })),
  ]);
  prefsCache = prefs;
  renderToolFocus(prefs.tool_focus || "auto");
  renderSmallModelMode(prefs.small_model_mode || "auto");
  renderRunBudget(prefs);
  const disabled = new Set(prefs.disabled_tools || []);
  list.replaceChildren();
  for (const tool of catalog) {
    const li = document.createElement("li");
    const label = document.createElement("label");
    label.className = "tool-row setting-check";
    const check = document.createElement("input");
    check.type = "checkbox";
    check.checked = !disabled.has(tool.name);
    // web_search is gated by the separate online opt-in, show why it's off.
    if (tool.online && !tool.enabled && !disabled.has(tool.name)) {
      check.checked = false;
      check.disabled = true;
      check.title = "Enable web search in Preferences first";
    }
    check.addEventListener("change", async () => {
      const next = new Set(prefsCache.disabled_tools || []);
      if (check.checked) next.delete(tool.name);
      else next.add(tool.name);
      prefsCache = await apiJson("/preferences", {
        method: "PUT",
        body: JSON.stringify({ disabled_tools: [...next] }),
      });
      // The "N of 51 on" count is only true until someone flips one.
      applyToolFilter();
    });
    const text = document.createElement("span");
    const name = document.createElement("strong");
    name.textContent = tool.name.replace(/_/g, " ");
    text.append(name);
    if (tool.destructive) text.append(" ", chip("confirms first", "review"));
    if (tool.online) text.append(" ", chip("online", "tag"));
    const desc = document.createElement("span");
    desc.className = "muted tool-desc";
    desc.textContent = tool.description;
    // The description goes *inside* the label's text column, not beside the
    // label in the <li>. That is what lets this row be `.setting-check`'s
    // grid, name and description stacked in column one, switch hard right , 
    // instead of a flex row whose switch tracked the length of each name.
    // It also makes the description part of the control's own hit area, the
    // way the hint under every other setting already is.
    text.append(desc);
    label.append(check, text);
    li.append(label);
    // Matched against by the filter below. Stored on the row rather than
    // re-read from the DOM on every keystroke, and lower-cased once here
    // instead of once per row per keystroke.
    li.dataset.search = `${tool.name} ${tool.description || ""}`.toLowerCase().replace(/_/g, " ");
    list.appendChild(li);
  }
  applyToolFilter();
}

//: Narrow a fifty-one item list, and say how many are on.
//:
//: The first audit of Settings measured this section at **5,708px**, by some
//: way the longest scroll in the app, with every tool a name plus a
//: paragraph of description. Finding one meant scrolling past fifty others,
//: and nothing anywhere answered the question the list actually raises: how
//: many of these are switched on?
//:
//: Filtering hides rows rather than re-rendering them, so a checkbox keeps
//: its state and its listener while you type. Re-rendering would also lose
//: focus from the filter field on every keystroke.
function applyToolFilter() {
  const list = $("tool-list");
  const box = $("tool-filter");
  const count = $("tool-count");
  const empty = $("tool-filter-empty");
  if (!list) return;
  const needle = (box?.value || "").trim().toLowerCase();
  const rows = [...list.children];
  let shown = 0;
  for (const row of rows) {
    const hit = !needle || (row.dataset.search || "").includes(needle);
    row.classList.toggle("hidden", !hit);
    if (hit) shown++;
  }
  empty?.classList.toggle("hidden", shown > 0 || !rows.length);
  if (count) {
    // Two different questions, so two different answers: with no filter the
    // useful number is how many are enabled; while filtering it is how many
    // the search actually found.
    const on = rows.filter((r) => r.querySelector("input[type=checkbox]")?.checked).length;
    count.textContent = needle
      ? `${shown} of ${rows.length}`
      : `${on} of ${rows.length} on`;
  }
}

$("tool-filter")?.addEventListener("input", applyToolFilter);

// --- Wave M: share skills/personas as JSON ------------------------------------------

function downloadJson(filename, payload) {
  return saveFile(
    filename,
    new Blob([JSON.stringify(payload, null, 2)], { type: "application/json" })
  );
}

// --- saving a generated file (§35E) ----------------------------------------------
//
// Every export here used to build a Blob and click a hidden `<a download>`.
// That works in a browser tab and does nothing whatsoever in the desktop
// window: pywebview has no download handler, so the click is swallowed and
// the user gets no file and no error. Reported as "I don't think any of the
// file save features in the whole application work on the python desktop app",
// which was exactly right and true of all of them at once.
//
// So there are two paths, chosen by asking the server which shell it is
// serving rather than by sniffing the user agent, pywebview's user agent is
// not reliably distinguishable, and a wrong guess here is a silent failure in
// the direction we are trying to fix.
let isDesktopShell = null; // null = not yet asked

async function desktopShell() {
  if (isDesktopShell === null) {
    const health = await apiJson("/health", { silent: true }).catch(() => null);
    isDesktopShell = !!(health && health.desktop);
  }
  return isDesktopShell;
}

function blobToBase64(blob) {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    // readAsDataURL gives "data:<type>;base64,<payload>", take the payload.
    reader.onload = () => resolve(String(reader.result).split(",", 2)[1] || "");
    reader.onerror = () => reject(reader.error);
    reader.readAsDataURL(blob);
  });
}

// Save a Blob under `filename`. Resolves once the file is somewhere the user
// can find it, and says where when that isn't the browser's own downloads.
async function saveFile(filename, blob) {
  if (await desktopShell()) {
    try {
      const saved = await apiJson("/files/save", {
        method: "POST",
        body: JSON.stringify({
          filename,
          content_base64: await blobToBase64(blob),
        }),
      });
      // Where it went matters more here than in a browser: there is no
      // downloads shelf to look at, so an unannounced file is a lost one.
      // An action button on the toast itself, not just a path in the text,
      // is what makes that true rather than aspirational, asked for
      // directly after "I have to dig in the app data files to find them".
      toastAction(`Saved to ${saved.path}`, "Open folder", () => {
        apiJson("/files/open-exports-folder", { method: "POST" }).catch((error) => {
          toast(error.message || "Couldn't open the exports folder.", true);
        });
      });
      return saved;
    } catch (error) {
      toast(`Couldn't save ${filename}: ${error.message}`, true);
      return null;
    }
  }
  const url = URL.createObjectURL(blob);
  const a = document.createElement("a");
  a.href = url;
  a.download = filename;
  // In the document, not detached: some engines ignore a click on an anchor
  // that was never in the DOM.
  a.style.display = "none";
  document.body.appendChild(a);
  a.click();
  a.remove();
  URL.revokeObjectURL(url);
  return { filename };
}

// Open a picker, parse the chosen file, hand the object to `apply`.
function pickJsonFile(inputId, apply) {
  const input = $(inputId);
  input.onchange = async () => {
    const file = input.files[0];
    input.value = "";
    if (!file) return;
    try {
      apply(JSON.parse(await file.text()));
    } catch {
      toast("That file isn't valid JSON.", true);
    }
  };
  input.click();
}

// Merge imported {name, prompt} items over existing ones (imports win
// on a name clash), used by both skills and personas.
function mergeNamedPrompts(existing, imported) {
  const cleaned = (imported || []).filter(
    (item) => item && typeof item.name === "string" && typeof item.prompt === "string"
  );
  if (!cleaned.length) return null;
  const names = new Set(cleaned.map((item) => item.name));
  return [...existing.filter((item) => !names.has(item.name)), ...cleaned];
}

// --- Wave M: batch operations on notes ----------------------------------------------

let selectMode = false;
const selectedIds = new Set();

function updateBatchCount() {
  const n = selectedIds.size;
  $("batch-count").textContent = `${n} selected`;
  // The Timeline's table selects into the same set through the same actions
  // (TIMELINE_PLAN decision 6), so there are two bars showing one count.
  $("timeline-batch-count").textContent = `${n} selected`;
}

// **One step, not three.** This used to be a `<select>` of categories beside
// a separate "Move" button: you picked a category, which did nothing, then
// pressed Move: and pressing Move without having picked produced an error
// toast ("Pick a category to move them to"). A menu whose items *are* the
// categories removes the second control and the failure state with it:
// choosing a category is the move. It also puts the list in the app's own
// menu styling instead of the operating system's select popup.
function fillBatchCategories(hostId = "batch-category-host") {
  const host = $(hostId);
  if (!host) return;
  const names = [...new Set(allEntries.map((e) => e.category))].filter(Boolean).sort();
  const items = names.map((name) =>
    makeMenuItem(`ph:folder ${name}`, `Move the selected notes to ${name}`, () =>
      batchMove(name)
    )
  );
  items.push(
    makeMenuItem("ph:plus New category…", "Move them to a category you name now", async () => {
      const category = await promptDialog("New category name:", "", { confirmLabel: "Move" });
      if (category) await batchMove(category);
    })
  );
  host.replaceChildren(labelledMenu("ph:folder-open Move to", items, "Move selected notes to a category"));
}

//: **One selection, two surfaces.** The Timeline's table ticks rows into this
//: same `selectedIds` set and runs the same `batchMove`/`batchTag`/
//: `batchDelete` (TIMELINE_PLAN decision 6: "the Notes selection bar drives
//: bulk actions"), so a note moved from the table takes exactly the path a
//: note moved from the Notes list takes, including the undo. Each surface has
//: its own bar because each lives in its own tab; both read one count and one
//: set, which is what stops the two from disagreeing.
function enterSelectMode() {
  selectMode = true;
  selectedIds.clear();
  fillBatchCategories();
  fillBatchCategories("timeline-batch-category-host");
  updateBatchCount();
  show("batch-bar");
  $("select-btn").classList.add("active");
  syncTimelineSelectUi();
  // The table's tick column only exists while the mode is on, so entering or
  // leaving the mode is a repaint of it. Measured the other way: after a bulk
  // action the table kept a column of boxes for a mode that had ended.
  paintTimeline();
  renderEntries();
}

function exitSelectMode() {
  selectMode = false;
  selectedIds.clear();
  hide("batch-bar");
  $("select-btn").classList.remove("active");
  syncTimelineSelectUi();
  paintTimeline();
  renderEntries();
}

function batchSelection() {
  const ids = [...selectedIds];
  if (!ids.length) toast("Tick some notes first.", true);
  return ids;
}

async function batchMove(category) {
  const ids = batchSelection();
  if (!ids.length) return;
  if (!category) return;
  for (const id of ids) {
    await apiJson(`/entries/${id}`, {
      method: "PUT",
      body: JSON.stringify({ category }),
    });
  }
  toast(`Moved ${ids.length} note${ids.length === 1 ? "" : "s"} to ${category}.`);
  exitSelectMode();
  await loadEntries();
}

async function batchTag() {
  const ids = batchSelection();
  if (!ids.length) return;
  const tag = await promptDialog("Tag to add to the selected notes:", "", { confirmLabel: "Add tag" });
  if (!tag) return;
  for (const id of ids) {
    const entry = allEntries.find((e) => e.id === id);
    if (!entry) continue;
    await apiJson(`/entries/${id}`, {
      method: "PUT",
      body: JSON.stringify({ tags: [...new Set([...entry.tags, tag])] }),
    });
  }
  toast(`Tagged ${ids.length} note${ids.length === 1 ? "" : "s"} with “${tag}”.`);
  exitSelectMode();
  await loadEntries();
}

async function batchDelete() {
  const ids = batchSelection();
  if (!ids.length) return;
  // No confirm dialog: this is a soft delete (DELETE /entries/{id} moves a
  // note to the bin, not gone) and the toastAction below already offers a
  // one-click Undo: the single-note "Move to bin" action right above this
  // function established the same pattern (Wave J). Gating an already-
  // reversible action behind an interrupting confirm *and* an undo toast is
  // redundant friction, not extra safety (Tier 3 §30e).
  for (const id of ids) await api(`/entries/${id}`, { method: "DELETE" });
  exitSelectMode();
  await loadEntries();
  const restoreAll = async () => {
    for (const id of ids) await api(`/entries/${id}/restore`, { method: "POST" });
    await loadEntries();
  };
  const binAll = async () => {
    for (const id of ids) await api(`/entries/${id}`, { method: "DELETE" });
    await loadEntries();
  };
  const action = pushUndo(`Moved ${ids.length} note${ids.length === 1 ? "" : "s"} to the bin`, restoreAll, binAll);
  toastAction(`Moved ${ids.length} to the recycle bin.`, "Undo", async () => {
    settleUndoFromToast(action);
    await restoreAll();
    toast("Notes restored.");
  });
}

// --- live clock + dashboard welcome ------------------------------------------------
// One ticker updates every visible .live-clock (reminders tab + dashboard),
// so the current time is always on screen, the reminders tab used to give
// no sense of "now" at all (user-reported).
function tickClocks() {
  const now = new Date();
  const time = now.toLocaleTimeString([], { hour: "numeric", minute: "2-digit" });
  const date = now.toLocaleDateString([], {
    weekday: "long",
    month: "long",
    day: "numeric",
  });
  for (const el of document.querySelectorAll(".live-clock")) {
    const t = el.querySelector(".clock-time");
    const d = el.querySelector(".clock-date");
    if (t) t.textContent = time;
    if (d) d.textContent = date;
  }
}
// **Stopped while the tab is hidden, restarted when it comes back.**
// This paints HH:MM, so 59 of every 60 runs wrote the string that was already
// there, and it ran for as long as the app was open whether or not anyone
// could see it: a background tab kept a one-second timer and a
// `querySelectorAll` alive for hours (WORLD_CLASS_PLAN section 10, F6, whose
// gate is "0 timers while hidden").
//
// Cleared rather than made to return early, because a timer that wakes the
// process a thousand times an hour to decide it has nothing to do is the
// thing being paid for. The repaint on return is what keeps it honest: a
// clock that resumed on the next tick would show the time it stopped at for
// up to a second, and "up to a second" on a clock is exactly what a person
// notices.
let clockTimer = null;

function startClockTicker() {
  if (clockTimer === null) clockTimer = setInterval(tickClocks, 1000);
}

function stopClockTicker() {
  if (clockTimer !== null) {
    clearInterval(clockTimer);
    clockTimer = null;
  }
}

document.addEventListener("visibilitychange", () => {
  if (document.hidden) {
    stopClockTicker();
  } else {
    tickClocks();
    startClockTicker();
  }
});

startClockTicker();
tickClocks();

window.addEventListener("resize", () => {
  if ($("dash-grid")) sizeDashWidgets();
  // A dragged composer height is only valid for the window it was dragged in.
  refitComposer();
});

// Fade a tab-strip edge only while there is something hidden beyond it.
//
// This was a media query, which is the wrong test: whether the tabs overflow
// depends on how long the AI status pill's text currently is and whether the
// wordmark is showing, not only on the window width. So a fixed breakpoint
// faded a tab bar that fitted perfectly, and left a scrolling one at other
// widths looking as though "Reminders" had been clipped: which is exactly
// the complaint the fade exists to prevent. Measuring is both simpler and
// correct at every width.
//
// Measuring *overflow* was still not enough, and it was reported: "the
// reminders tab in the top bar is partially faded out on the right." A bar
// scrolled to its end has nothing further right, but the old single class
// kept fading anyway: so the last tab was permanently dimmed, which reads as
// a disabled control. The question each edge answers is "is there more THIS
// way", so each edge gets its own class and the answer is recomputed on
// scroll as well as on resize.
// How much room the tab strip has if it stays on the header's own row.
//
// Measured from the header's other children rather than guessed from a
// breakpoint, for the same reason the fade is: whether the tabs fit depends on
// the wordmark, the status pill's current text and which header buttons are
// showing, none of which a width range knows about.
function tabRowSpace() {
  const header = document.getElementById("top-bar");
  const bar = $("tab-bar");
  if (!header || !bar) return 0;
  const style = getComputedStyle(header);
  const gap = parseFloat(style.columnGap || style.gap) || 0;
  const padding =
    (parseFloat(style.paddingLeft) || 0) + (parseFloat(style.paddingRight) || 0);
  let others = 0;
  let siblings = 0;
  for (const child of header.children) {
    if (child === bar || child.classList.contains("hidden")) continue;
    others += child.getBoundingClientRect().width;
    siblings += 1;
  }
  return header.clientWidth - padding - others - gap * siblings;
}

// What the tab strip actually needs, summed from the buttons rather than read
// off the strip's own box.
//
// **This is the fix for a reported bug, and the distinction is the whole
// bug.** The wrap test used `bar.scrollWidth`, which is `max(content,
// clientWidth)`, and the wrapped rule gives the strip `flex-basis: 100%`. So
// the moment it wrapped, its scrollWidth became the *width of the header*,
// which is by definition larger than the room beside the header's other
// children, and the test that decided wrapping was measuring its own output.
// It could not oscillate, as the old comment said. It latched, which is worse:
// one transient narrow moment, a drag of the window edge, a font arriving
// late: and the header stayed two rows tall for the rest of the session.
// Measured: at 900px it wraps and scrollWidth reads 868; widened to 2000px it
// reads 1952 and stays wrapped at 102px tall, where a fresh load at the same
// width renders one row at 60px. That is "the top bar keeps switching and
// permanently changing layout", exactly.
//
// The buttons are `flex: 0 0 auto`, so their widths are the same whichever row
// the strip is on. That is what makes this measurement independent of the
// state it is being used to decide.
function tabContentWidth() {
  const bar = $("tab-bar");
  if (!bar) return 0;
  const style = getComputedStyle(bar);
  const gap = parseFloat(style.columnGap || style.gap) || 0;
  const padding =
    (parseFloat(style.paddingLeft) || 0) + (parseFloat(style.paddingRight) || 0);
  let total = 0;
  let count = 0;
  for (const child of bar.children) {
    if (child.classList.contains("hidden")) continue;
    total += child.getBoundingClientRect().width;
    count += 1;
  }
  return total + padding + gap * Math.max(0, count - 1);
}

function syncTabOverflowFade() {
  const bar = $("tab-bar");
  if (!bar) return;
  // A tab you have to scroll to is a tab you will not find. When the strip
  // cannot fit beside the wordmark and the header buttons, it takes a row of
  // its own: where all seven fit with room to spare at any width the app is
  // usable at. Photographed on a 7-tab window: "Dashboard" clipped to "oard"
  // at the left edge, which no amount of edge-fading makes readable.
  const header = document.getElementById("top-bar");
  // Below 600 the strip is not in the header at all: `dockTabBar` moves it
  // onto the body so `position: fixed` can reach the viewport past the
  // header's backdrop filter. The wrap question is then meaningless, and
  // leaving it to be asked kept `.tabs-wrapped` on a header that had nothing
  // to wrap: measured at 390 the top bar stood at 110px against 58px at 599
  // with identical contents.
  if (header && bar.parentElement !== header) {
    header.classList.remove("tabs-wrapped");
    bar.classList.remove("fade-start", "fade-end");
    return;
  }
  if (header) {
    const needed = tabContentWidth();
    const space = tabRowSpace();
    // Asymmetric thresholds, and only for jitter: both measurements are now
    // independent of which row the strip is on, so there is no feedback to
    // oscillate. What remains is sub-pixel rounding at the exact width where
    // the two are equal, and a header that flickers between one and two rows
    // while you drag the window edge is its own kind of broken. 8px is under
    // half a character and well over the rounding.
    const wrapped = header.classList.contains("tabs-wrapped");
    header.classList.toggle(
      "tabs-wrapped",
      wrapped ? needed > space - 8 : needed > space + 1
    );
  }
  // 1px of slack at each end: sub-pixel layout makes scrollWidth exceed
  // clientWidth by a fraction on plenty of widths where nothing is cut off,
  // and a scroll offset lands on .5 of a pixel as often as not.
  const hidden = bar.scrollWidth - bar.clientWidth;
  bar.classList.toggle("fade-start", hidden > 1 && bar.scrollLeft > 1);
  bar.classList.toggle("fade-end", hidden - bar.scrollLeft > 1);
}

// A tab you cannot fully see is a tab you cannot fully read. Selecting one
// brings it into view, so the fade is only ever over a tab you are not using.
function revealActiveTab() {
  const active = document.querySelector("#tab-bar button.active");
  if (active && active.scrollIntoView) {
    active.scrollIntoView({ block: "nearest", inline: "nearest" });
  }
  syncTabOverflowFade();
}

window.addEventListener("resize", syncTabOverflowFade, { passive: true });
$("tab-bar")?.addEventListener("scroll", syncTabOverflowFade, { passive: true });

// Same edge-fade, generalised for every other `.edge-fade` strip (Notes
// sub-tabs, Library sub-tabs, the document sidebar's tabs): none of them
// wrap to their own row the way #tab-bar does, so this is just the fade
// half of syncTabOverflowFade, reused rather than duplicated.
function syncEdgeFade(bar) {
  if (!bar) return;
  const hidden = bar.scrollWidth - bar.clientWidth;
  bar.classList.toggle("fade-start", hidden > 1 && bar.scrollLeft > 1);
  bar.classList.toggle("fade-end", hidden - bar.scrollLeft > 1);
}

for (const bar of document.querySelectorAll(".edge-fade")) {
  syncEdgeFade(bar);
  bar.addEventListener("scroll", () => syncEdgeFade(bar), { passive: true });
  if (typeof ResizeObserver !== "undefined") {
    // Fires when a hidden (0-width) strip becomes visible on tab switch,
    // same as content changing width, no extra wiring needed per tab.
    new ResizeObserver(() => syncEdgeFade(bar)).observe(bar);
  }
}
window.addEventListener("resize", () => {
  document.querySelectorAll(".edge-fade").forEach(syncEdgeFade);
}, { passive: true });

// --- the scroll edge effect (UI_MODERNISATION_PLAN Phase 10, INBOX 100) -----
//
// "Optimize for legibility when content scrolls beneath controls": the bar
// over a scrolling region fades a soft edge under itself while there is
// content passing behind it, and paints nothing at rest. DESIGN.md, "Taken
// from Liquid Glass and the HIG", rule 2.
//
// **One listener, and the bar is chosen by measurement rather than by name.**
// The obvious implementation is a rule per surface, and it is wrong on the
// first surface you try it on: Notes has three candidate bars stacked above
// its list (the top bar, the sub-tab strip, the dock) and only the *last* of
// them has scrolling content under it. A gradient under the other two lands
// on another bar, where it reads as a smudge rather than as depth. So this
// takes the region that actually scrolled, and marks the one bar whose bottom
// edge is sitting against that region's top.
//
// Nothing here knows which tab it is on, which is the point: a new surface
// with a dock over a scroller gets the effect with no new code, and a surface
// that puts its dock somewhere else gets nothing rather than getting it in
// the wrong place.
const SCROLL_EDGE_BARS = "header#top-bar, .dock, .notes-subtabs, .library-subtabs";

// How close a bar's bottom edge has to be to the top of the scrolling region
// to count as "the bar over it". A few pixels of margin between the two is
// normal (`.dock` carries `margin-bottom: var(--space-4)`); half a control
// height is not, and means the bar belongs to something else.
const SCROLL_EDGE_GAP = 24;

// Regions that have actually scrolled at least once. Switching tabs has to
// restore the effect on a page that was left mid-scroll, and re-scanning
// every element of a page for scrollability on each tab change is a lot of
// getComputedStyle for a cosmetic gradient. A scroll event is the cheapest
// possible way to learn which elements are worth asking about.
const scrollEdgeRegions = new Set();

function markScrollEdge(region) {
  if (!region || typeof region.getBoundingClientRect !== "function") return;
  // A menu, a dialog or a popover scrolls over the page, not under a bar.
  if (
    region.closest &&
    region.closest(".action-menu, .help-popover, .modal-overlay, #settings-modal, [role='menu']")
  ) {
    return;
  }
  scrollEdgeRegions.add(region);
  const scrolled = region.scrollTop > 1;
  const top = region.getBoundingClientRect().top;
  let best = null;
  let gap = Infinity;
  for (const bar of document.querySelectorAll(SCROLL_EDGE_BARS)) {
    // A bar inside the region scrolls with the content; a bar wrapping it is
    // its container, not a lid over it.
    if (region.contains(bar) || bar.contains(region)) continue;
    const box = bar.getBoundingClientRect();
    if (!box.height) continue;
    const distance = top - box.bottom;
    if (distance < -1 || distance > SCROLL_EDGE_GAP) continue;
    if (distance < gap) {
      gap = distance;
      best = bar;
    }
  }
  for (const bar of document.querySelectorAll("[data-scrolled]")) {
    if (bar !== best) bar.removeAttribute("data-scrolled");
  }
  if (best && scrolled) best.setAttribute("data-scrolled", "1");
  else if (best) best.removeAttribute("data-scrolled");
}

let scrollEdgeFrame = 0;
function onScrollEdge(event) {
  const region = event.target === document ? document.scrollingElement : event.target;
  if (!region || region.nodeType !== 1) return;
  if (scrollEdgeFrame) return;
  // Coalesced to one measurement per frame: a scroll event fires far more
  // often than the screen repaints, and this one reads layout.
  scrollEdgeFrame = requestAnimationFrame(() => {
    scrollEdgeFrame = 0;
    markScrollEdge(region);
  });
}

// Capture, because scroll does not bubble: without it this would only ever
// hear about the document's own scrolling, which is the one thing this app
// does not do (the page is its own scroll container, see §36A).
document.addEventListener("scroll", onScrollEdge, { capture: true, passive: true });

function syncScrollEdges() {
  const page = document.querySelector(".tab-page:not(.hidden)");
  let handled = false;
  for (const region of scrollEdgeRegions) {
    if (!region.isConnected) {
      scrollEdgeRegions.delete(region);
      continue;
    }
    if (page && page.contains(region) && region.scrollTop > 1) {
      markScrollEdge(region);
      handled = true;
    }
  }
  if (handled) return;
  for (const bar of document.querySelectorAll("[data-scrolled]")) {
    bar.removeAttribute("data-scrolled");
  }
}

window.addEventListener("resize", syncScrollEdges, { passive: true });

// A tab switch is a class change on the pages, not an event this file
// publishes, and observing it here keeps the whole effect in one block
// instead of adding a line to the tab machinery for a gradient.
if (typeof MutationObserver !== "undefined") {
  const scrollEdgeObserver = new MutationObserver(() => syncScrollEdges());
  for (const page of document.querySelectorAll(".tab-page")) {
    scrollEdgeObserver.observe(page, { attributes: true, attributeFilter: ["class"] });
  }
}
// The pill's text arrives with the status polls, long after first paint, and
// changes width when it does, so remeasure whenever the header changes size
// rather than only on window resize.
if (typeof ResizeObserver !== "undefined") {
  // Measured on the next frame rather than inside the callback.
  //
  // Reported from the desktop shell's console: "ResizeObserver loop completed
  // with undelivered notifications." That warning is the browser saying an
  // observer callback changed the layout of something it observes, and this
  // one does exactly that, deciding `.tabs-wrapped` changes the header's
  // height and the strip's width, which is what it is watching. The loop
  // terminates (both measurements are independent of the class now, so the
  // second pass agrees with the first), but it costs a wasted layout every
  // resize and prints an error that looks like a fault.
  //
  // Deferring breaks the cycle: the write lands after the observation phase,
  // and the `queued` flag collapses a burst of resize notifications into one
  // measurement instead of one per element per frame.
  let queued = false;
  const headerObserver = new ResizeObserver(() => {
    if (queued) return;
    queued = true;
    requestAnimationFrame(() => {
      queued = false;
      syncTabOverflowFade();
    });
  });
  const bar = $("tab-bar");
  if (bar) {
    headerObserver.observe(bar);
    if (bar.parentElement) headerObserver.observe(bar.parentElement);
  }
}
syncTabOverflowFade();

// safeMdSlice/notePreviewText stay here rather than moving to dashboard.js
// with the widgets that use them (roadmap §88.3): notePreviewText is also
// called from note-card previews, the writing room and whiteboard.js's node
// labels, and safeMdSlice from the Library's own truncation: genuinely
// shared, not dashboard-only, despite having sat in the same comment block.
//
// A note's text as it should read in a preview: the [[link]] syntax is
// scaffolding, not content, so previews show the words without the brackets.
// Full note bodies get real clickable chips instead (renderNoteText).
//: A raw-character slice that won't leave a markdown marker dangling at the
//: cut: reported directly (Notes-tab "Most used" list): a clip landing
//: mid-`` `code` `` left a bare `` ` `` sitting in the rendered text, since
//: `INLINE_MD` only matches a marker pair that's fully present and an
//: unmatched one falls through as a literal character. Checked longest
//: marker first (`**`/`~~` before `*`) so a bold pair isn't mistaken for two
//: stray italics. Not a full CommonMark-safe truncator, good enough for a
//: short label, which is the only place this is used.
// A preview slice that never cuts through markdown syntax, and, since it is
// the only thing standing between a note and a widget row, never returns
// nothing.
//
// **It returned the empty string for a whole class of note.** Balancing an
// unpaired marker was done with `cut.slice(0, cut.lastIndexOf(marker))`, and
// when the marker was the FIRST character that index is 0, so the slice was
// empty and the row rendered as a bare "…" with no text at all. One stray `*`
// in the first hundred characters was enough, reported on the Most-used
// widget, where long notes showed as nothing but an ellipsis.
//
// Two changes:
//   - the balanced cut is only accepted if something survives it, and the
//     fallback is a plain-text slice with the markers stripped, because a
//     preview with visible asterisks still beats an empty row;
//   - the cut prefers a sentence end inside the budget. Asked for: show the
//     first sentence like the rest of the list does. A preview that stops on a
//     full stop reads as a summary; one that stops mid-word reads as damage.
function safeMdSlice(text, maxChars) {
  if (text.length <= maxChars) return { text, truncated: false };

  // Look for a sentence end in the back half of the budget, so a very long
  // first sentence still gets cut at the budget rather than swallowing it.
  const window = text.slice(0, maxChars);
  const sentence = window.search(/[.!?…](?=\s|$)(?![^\s]*[.!?])/);
  let cut =
    sentence >= Math.floor(maxChars * 0.4) ? window.slice(0, sentence + 1) : window;

  for (const marker of ["**", "~~", "`", "*"]) {
    if ((cut.split(marker).length - 1) % 2 !== 1) continue;
    const balanced = cut.slice(0, cut.lastIndexOf(marker));
    // Only if it leaves something to show. Otherwise drop the markers and
    // keep the words.
    if (balanced.trim()) cut = balanced;
    else cut = cut.replace(/[*~`]/g, "");
    break;
  }
  if (!cut.trim()) cut = window.replace(/[*~`]/g, "");
  return { text: cut, truncated: cut.length < text.length };
}

// One line of a note, as plain text, used wherever a preview genuinely
// can't be rendered markup (a `title` tooltip, an SVG export label, a
// whiteboard card's own text). The dashboard's label-sized widget lists
// (dashboard.js) render real markdown instead, via `safeMdSlice` +
// `renderInlineMarkdown`'s `compact` mode, the same as every other
// label-sized surface in this app.
//: **The first image a note actually shows**, for surfaces that want to put a
//: face on a row rather than a filename. Reported against the Contents tab,
//: which rendered every note as `noteLabel` text: so a note that *is* a photo
//: appeared as "20251018_OHR.SilburyHill….jpg", or as the bare word "image"
//: when the alt text was empty.
//:
//: Reads the markdown rather than any stored field, because that is where a
//: note's images live: pasted, dropped and AI-attached pictures all end up as
//: `![alt](/media/…)` in the body, and there is no column that mirrors them.
//:
//: Only this app's own stored files. An external `https://` image in a note is
//: skipped on purpose: the CSP blocks it (`img-src 'self' data: blob:`), so a
//: thumbnail built from one would be a guaranteed broken frame, which is worse
//: than no thumbnail at all.
//: A note's picture, wherever it lives, the markdown, or the attachments
//: table. See `noteRowImage` in dashboard.js for the report behind this: an
//: *attached* image appears nowhere in the note's text, so every surface that
//: looked for `![](…)` alone showed nothing for a note whose only picture was
//: attached rather than pasted.
function noteAnyImage(entry) {
  const embedded = noteFirstImage(entry?.content);
  if (embedded) return embedded;
  const attached = (entry?.attachments || []).find((file) => file.is_image);
  return attached ? { alt: attached.filename || "", url: `/files/${attached.id}` } : null;
}

function noteFirstImage(content) {
  const match = /!\[([^\]\n]{0,200})\]\((\/(?:media|files)\/[^)\n]{1,500})\)/.exec(content || "");
  if (!match) return null;
  return { alt: match[1] || "", url: match[2] };
}

//: **A `[[link]]`'s visible words, without the syntax its target happens to
//: start with.** Reported: *"note links have inline md not rendered or
//: suppressed, when an ai mentions a note that starts with a note that has a
//: '# text' hashtag md heading, it will write the hashtag"*, with a screenshot
//: of `[[# Girl with bell]]` rendering as "# Girl with bell" in both the
//: editor and the preview.
//:
//: The `[[` picker inserts the target note's first line verbatim, `# ` and
//: all, and `resolveWikiTarget` deliberately keeps matching that form, because
//: every link already written in every existing note is in it. So the raw text
//: has to stay in the document and only the *label* is cleaned, which is what
//: this is: the same treatment `noteLabel` already gives a chat badge, for the
//: same reason (INBOX 35 and 40, "a badge is not a source view"), applied to
//: the other place a note's opening words are shown as a control.
//:
//: Falls back to the raw name rather than to an empty string: a link whose
//: text is nothing but markers is still a link somebody typed, and a button
//: with no words in it cannot be clicked on purpose.
function wikiLinkLabel(name) {
  const clean = notePreviewText(name).replace(/\s+/g, " ").trim();
  return clean || name;
}

function notePreviewText(content) {
  return (content || "")
    .replace(/^#{1,6}\s+/gm, "")
    .replace(/\[\[([^[\]]{1,120})\]\]/g, "$1")
    .replace(
      new RegExp(INLINE_MD.source, "g"),
      // m[10]/m[12] are the image/link *URLs*, only checked for "which branch
      // matched", never shown; a preview shows the image's alt text (or a
      // placeholder, since alt is often empty) and a link's own text, not a
      // raw path nobody asked to read.
      //
      // **These indices were off by two and the previous comment named the
      // wrong groups.** Reported with a screenshot of the Contents page:
      // "Girl with bell undefined", "Leafeon Pokemon image test undefined", 
      // notes whose body ends in an image. The `++colour|text++` highlight
      // alternative was added to INLINE_MD after this replacer was written,
      // and it introduced two capture groups in the middle of the pattern, so
      // every index past it shifted by two. Nothing failed loudly: `??` walked
      // off the end of the branches it knew, the last one returned
      // `undefined`, and `String.replace` stringified that into the preview.
      //
      // It was wrong in three ways at once, and only one of them was visible:
      // an image previewed as "undefined", a link previewed as "undefined",
      // and `==red|highlighted==` previewed as "red", the colour name, because
      // m[4] is the optional colour group and was being read as the text.
      // Verified against the live pattern: g1 code, g2 bold, g3 strike,
      // g4 highlight colour, g5 highlight text, g6 ++colour, g7 ++text,
      // g8 italic, g9/g10 image alt+url, g11/g12 link text+url.
      (...m) =>
        m[1] ?? m[2] ?? m[3] ?? m[5] ?? m[7] ?? m[8] ??
        (m[10] !== undefined ? m[9] || "image" : m[11])
    );
}

// --- reminders tab (Wave D) --------------------------------------------------------

// (The session-scoped `notifiedReminderIds` set went with the dead poller
// above. §36C keeps announced ids in localStorage instead, so a reload does
// not re-announce everything already overdue, which a Set could not survive.)

let reminderFilter = "open"; // open | all | done

// BACKLOG §77's pattern, extended to Reminders (§89 item 1): deliberately
// narrower than Notes' own version. Applies only to the Done group; see the
// note on #reminders-page-size in index.html for why Overdue/Today/Upcoming
// are never paginated in any filter.
let remindersPageSize = localStorage.getItem("reminders-page-size") || "all";
let remindersDonePage = 1;

// list | calendar. Persisted the same way timeline's own view toggle is
// (a bare localStorage key), a display mode, not data, so it doesn't need
// the weight of a real preference round-tripped through the backend.
let reminderView = localStorage.getItem("reminderView") === "calendar" ? "calendar" : "list";
// The month the calendar is showing, always pinned to day 1 so "next month"
// arithmetic can't land on the 31st of a shorter month.
let reminderCalMonth = (() => {
  const d = new Date();
  d.setDate(1);
  d.setHours(0, 0, 0, 0);
  return d;
})();

async function loadReminders() {
  //: Every reminder, not the first page. `/reminders` is ordered `due_at`
  //: ascending, so the first page is the *oldest* rows with the ticked-off
  //: ones among them: a notebook whose oldest two hundred are all done would
  //: push everything upcoming off the list, which is exactly the silent loss
  //: paging was added to prevent. Reading to the end keeps the grouping below
  //: unchanged and loses nothing; a real pager is the better answer at
  //: thousands and is written up in `agent-remaining/list-paging.md`.
  const all = await apiPagedList("/reminders", 200).catch(() => []);
  const groupsBox = $("reminder-groups");
  groupsBox.replaceChildren();

  const reminders = all.filter((r) =>
    reminderFilter === "all" ? true : reminderFilter === "done" ? r.done : !r.done
  );
  const isList = reminderView === "list";
  $("reminder-groups").classList.toggle("hidden", !isList);
  $("reminders-empty").classList.toggle("hidden", !isList || all.length > 0);
  $("reminder-calendar").classList.toggle("hidden", isList);
  if (!isList) renderReminderCalendar(all);
  $("reminder-clear-done").classList.toggle("hidden", !all.some((r) => r.done));
  // Surface anything due on the tab itself, from wherever you are.
  updateReminderBadge(all);

  const now = new Date();
  const endOfToday = new Date(now);
  endOfToday.setHours(23, 59, 59, 999);
  const groups = { Overdue: [], Today: [], Upcoming: [], Done: [] };
  for (const reminder of reminders) {
    const due = new Date(reminder.due_at);
    if (reminder.done) groups.Done.push(reminder);
    else if (due < now) groups.Overdue.push(reminder);
    else if (due <= endOfToday) groups.Today.push(reminder);
    else groups.Upcoming.push(reminder);
  }

  // Nothing in this filter, but reminders do exist elsewhere.
  if (all.length && !reminders.length) {
    const none = document.createElement("p");
    none.className = "muted";
    none.textContent =
      reminderFilter === "done"
        ? "Nothing completed yet."
        : "All clear: nothing open.";
    groupsBox.appendChild(none);
  }

  const donePagination = $("reminders-done-pagination");
  for (const label of ["Overdue", "Today", "Upcoming", "Done"]) {
    const items = groups[label];
    if (!items.length) continue;
    const heading = document.createElement("h3");
    heading.className = `reminder-group-head group-${label.toLowerCase()}`;
    const text = document.createElement("span");
    text.textContent = label;
    const count = document.createElement("span");
    count.className = "group-count";
    count.textContent = items.length;
    heading.append(text, count);
    groupsBox.appendChild(heading);
    const ul = document.createElement("ul");
    ul.className = "entry-list";
    // Done is the one group this app ever slices, see remindersPageSize's
    // own comment. Every other group renders in full, always, regardless of
    // this control's value.
    const shown =
      label === "Done" ? paginateDoneReminders(items) : items;
    for (const reminder of shown) ul.appendChild(reminderItem(reminder, label));
    groupsBox.appendChild(ul);
  }
  // The bar only means something under a Done group that actually rendered
  // one: paginateDoneReminders already hid/showed it for that case, but a
  // filter with no Done items at all (Open) has to hide it too, since the
  // loop above never reaches the branch that would.
  if (!groups.Done.length) donePagination.classList.add("hidden");
}

function paginateDoneReminders(items) {
  const bar = $("reminders-done-pagination");
  if (remindersPageSize === "all") {
    bar.classList.add("hidden");
    return items;
  }
  const pageSize = Number(remindersPageSize);
  const totalPages = Math.max(1, Math.ceil(items.length / pageSize));
  remindersDonePage = Math.min(Math.max(1, remindersDonePage), totalPages);
  const start = (remindersDonePage - 1) * pageSize;
  bar.classList.remove("hidden");
  $("reminders-done-page-status").textContent = `Page ${remindersDonePage} of ${totalPages}`;
  $("reminders-done-page-prev").disabled = remindersDonePage <= 1;
  $("reminders-done-page-next").disabled = remindersDonePage >= totalPages;
  return items.slice(start, start + pageSize);
}

// Month-grid view of due dates (ROADMAP.md gap 4: the flat list has no way
// to see "what's due this week" laid out as a calendar). `all` is every
// reminder regardless of reminderFilter, a month view answers "what's on
// this day," which isn't the same question the Open/All/Done filter above it
// answers, so it deliberately ignores that filter rather than surprising
// someone who switches view mid-browse and sees fewer days than expected.
function renderReminderCalendar(all) {
  const box = $("reminder-calendar");
  box.replaceChildren();

  const byDay = new Map(); // "YYYY-MM-DD" -> reminders due that local day
  for (const reminder of all) {
    const due = new Date(reminder.due_at);
    const key = `${due.getFullYear()}-${String(due.getMonth() + 1).padStart(2, "0")}-${String(due.getDate()).padStart(2, "0")}`;
    if (!byDay.has(key)) byDay.set(key, []);
    byDay.get(key).push(reminder);
  }

  const head = document.createElement("div");
  head.className = "reminder-cal-head";
  const prev = smallButton("‹", "Previous month", () => {
    reminderCalMonth.setMonth(reminderCalMonth.getMonth() - 1);
    renderReminderCalendar(all);
  });
  const today = smallButton("Today", "Jump to this month", () => {
    const d = new Date();
    d.setDate(1);
    d.setHours(0, 0, 0, 0);
    reminderCalMonth = d;
    renderReminderCalendar(all);
  });
  const next = smallButton("›", "Next month", () => {
    reminderCalMonth.setMonth(reminderCalMonth.getMonth() + 1);
    renderReminderCalendar(all);
  });
  const title = document.createElement("h3");
  title.className = "reminder-cal-title";
  title.textContent = reminderCalMonth.toLocaleDateString(undefined, { month: "long", year: "numeric" });
  head.append(prev, title, today, next);
  box.appendChild(head);

  const grid = document.createElement("div");
  grid.className = "reminder-cal-grid";
  for (const label of ["Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat"]) {
    const dow = document.createElement("span");
    dow.className = "reminder-cal-dow muted";
    dow.textContent = label;
    grid.appendChild(dow);
  }

  const monthStart = new Date(reminderCalMonth);
  const lead = monthStart.getDay(); // blank cells so day 1 lands in its real weekday column
  const daysInMonth = new Date(monthStart.getFullYear(), monthStart.getMonth() + 1, 0).getDate();
  const todayKey = (() => {
    const d = new Date();
    return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, "0")}-${String(d.getDate()).padStart(2, "0")}`;
  })();

  for (let i = 0; i < lead; i++) {
    const blank = document.createElement("span");
    blank.className = "reminder-cal-cell reminder-cal-blank";
    grid.appendChild(blank);
  }

  for (let day = 1; day <= daysInMonth; day++) {
    const key = `${monthStart.getFullYear()}-${String(monthStart.getMonth() + 1).padStart(2, "0")}-${String(day).padStart(2, "0")}`;
    const dayReminders = byDay.get(key) || [];
    const cell = document.createElement("button");
    cell.type = "button";
    cell.className = "reminder-cal-cell";
    if (key === todayKey) cell.classList.add("reminder-cal-today");
    if (dayReminders.length) cell.classList.add("reminder-cal-has-items");

    const num = document.createElement("span");
    num.className = "reminder-cal-daynum";
    num.textContent = day;
    cell.appendChild(num);

    if (dayReminders.length) {
      const dots = document.createElement("span");
      dots.className = "reminder-cal-dots";
      for (const reminder of dayReminders.slice(0, 4)) {
        const dot = document.createElement("span");
        dot.className = `reminder-cal-dot priority-${reminder.priority || "normal"}${reminder.done ? " done" : ""}`;
        dots.appendChild(dot);
      }
      cell.appendChild(dots);
      cell.title = dayReminders.map((r) => r.text).join("\n");
      cell.setAttribute("aria-label", `${day}: ${dayReminders.length} reminder${dayReminders.length === 1 ? "" : "s"}`);
      cell.addEventListener("click", () => {
        // Jump into the list at the first one, reuses flashReminder's own
        // switch-to-list/scroll/flash rather than inventing a day-filtered
        // list view just for this.
        reminderView = "list";
        localStorage.setItem("reminderView", "list");
        for (const b of document.querySelectorAll("#reminder-view-toggle button")) {
          b.classList.toggle("active", b.dataset.view === "list");
        }
        flashReminder(dayReminders[0].id);
      });
    } else {
      cell.setAttribute("aria-label", `${day}, no reminders`);
      cell.title = "Add a reminder on this day";
      cell.addEventListener("click", () => {
        const iso = `${monthStart.getFullYear()}-${String(monthStart.getMonth() + 1).padStart(2, "0")}-${String(day).padStart(2, "0")}`;
        $("reminder-date").value = iso;
        $("reminder-text").focus();
      });
    }
    grid.appendChild(cell);
  }
  box.appendChild(grid);
}

// A count of due-or-overdue reminders on the Reminders tab button, so you
// notice them from any tab.
function updateReminderBadge(reminders) {
  const button = $("tab-btn-reminders");
  if (!button) return;
  const now = new Date();
  const due = (reminders || []).filter(
    (r) => !r.done && new Date(r.due_at) <= now
  ).length;
  // The status bar's reminder slot is fed from here rather than from its own
  // fetch: this function is the one place both callers of /reminders land, so
  // the bar and the tab badge cannot disagree and no second timer exists to
  // drift from the first.
  reminderCounts = {
    open: (reminders || []).filter((r) => !r.done).length,
    due,
  };
  renderStatusBar();

  let badge = button.querySelector(".tab-badge");
  if (!due) {
    badge?.remove();
    return;
  }
  if (!badge) {
    badge = document.createElement("span");
    badge.className = "tab-badge";
    button.appendChild(badge);
  }
  badge.textContent = due;
  badge.title = `${due} reminder${due === 1 ? "" : "s"} due`;
}

async function clearDoneReminders() {
  //: To the end, or this clears the first page's done rows and reports that
  //: count as if it were all of them.
  const all = await apiPagedList("/reminders", 200).catch(() => []);
  const done = all.filter((r) => r.done);
  if (!done.length) return;
  if (!(await confirmDialog(`Delete ${done.length} completed reminder${done.length === 1 ? "" : "s"}?`))) {
    return;
  }
  await Promise.all(
    done.map((r) => api(`/reminders/${r.id}`, { method: "DELETE" }).catch(() => {}))
  );
  toast(`Cleared ${done.length} completed reminder${done.length === 1 ? "" : "s"}.`);
  loadReminders();
}

let editingReminderId = null;

function reminderItem(reminder, label) {
  const li = document.createElement("li");
  li.dataset.id = reminder.id; // flashReminder's own hook, same shape as #entry-list's data-id
  if (label === "Overdue") li.classList.add("overdue");
  // Colour-code by priority (styled in CSS: a coloured left border).
  if (reminder.priority && reminder.priority !== "normal") {
    li.classList.add(`priority-${reminder.priority}`);
  }

  if (editingReminderId === reminder.id) {
    li.appendChild(reminderEditForm(reminder));
    return li;
  }

  const row = document.createElement("div");
  row.className = "entry-meta";

  const checkbox = document.createElement("input");
  checkbox.type = "checkbox";
  checkbox.checked = reminder.done;
  checkbox.title = reminder.done ? "Reopen" : "Mark done";
  checkbox.style.width = "auto";
  checkbox.addEventListener("change", async () => {
    // Completing a recurring reminder rolls it forward to the next interval
    // instead of closing it permanently.
    if (checkbox.checked && reminder.recurring && reminder.recurring !== "none") {
      const next = nextRecurringDate(reminder.due_at, reminder.recurring);
      await apiJson(`/reminders/${reminder.id}`, {
        method: "PUT",
        body: JSON.stringify({ due_at: next.toISOString(), done: false }),
      });
      toast(`Rescheduled to ${next.toLocaleString()}.`);
      loadReminders();
      return;
    }
    await apiJson(`/reminders/${reminder.id}`, {
      method: "PUT",
      body: JSON.stringify({ done: checkbox.checked }),
    });
    loadReminders();
  });
  row.appendChild(checkbox);

  const text = document.createElement("span");
  text.className = "reminder-text";
  text.textContent = reminder.text;
  if (reminder.done) text.style.textDecoration = "line-through";
  row.appendChild(text);

  if (reminder.recurring && reminder.recurring !== "none") {
    const repeat = chip(`ph:repeat ${reminder.recurring}`, "tag");
    repeat.title = `Repeats ${reminder.recurring}`;
    row.appendChild(repeat);
  }

  const due = document.createElement("span");
  due.className = "entry-date";
  due.textContent = relativeWhen(reminder.due_at); // "in 2 hours" / "3 days ago"
  due.title = new Date(reminder.due_at).toLocaleString(); // exact on hover
  row.appendChild(due);

  const actions = document.createElement("span");
  actions.className = "entry-actions";
  if (!reminder.done) {
    actions.appendChild(
      smallButton("+1h", "Snooze one hour", () =>
        snoozeReminderTo(reminder, new Date(Date.now() + 60 * 60 * 1000))
      )
    );
    actions.appendChild(
      smallButton("→ tmrw", "Snooze to tomorrow 9am", () =>
        snoozeReminderTo(reminder, presetDate("tomorrow"))
      )
    );
  }
  actions.appendChild(
    smallButton("ph:pencil-simple", "Edit this reminder", () => {
      editingReminderId = reminder.id;
      loadReminders();
    })
  );
  actions.appendChild(
    smallButton("×", "Delete this reminder", async () => {
      await apiJson(`/reminders/${reminder.id}`, { method: "DELETE" });
      loadReminders();
      // Deleting a reminder is as undo-able as binning a note. There's no
      // restore endpoint here (unlike entries): undo recreates it, which
      // means a redo's own delete target has to track the *new* id, not the
      // one this closure started with.
      let liveId = reminder.id;
      const recreate = async () => {
        const created = await apiJson("/reminders", {
          method: "POST",
          body: JSON.stringify({
            text: reminder.text,
            due_at: reminder.due_at,
            entry_id: reminder.entry_id,
            priority: reminder.priority || "normal",
            recurring: reminder.recurring || "none",
          }),
        });
        liveId = created.id;
        loadReminders();
      };
      const redelete = async () => {
        await apiJson(`/reminders/${liveId}`, { method: "DELETE" });
        loadReminders();
      };
      const action = pushUndo("Deleted a reminder", recreate, redelete);
      toastAction("Reminder deleted.", "Undo", async () => {
        settleUndoFromToast(action);
        await recreate().catch((e) => toast(e.message, true));
        toast("Reminder restored.");
      });
    })
  );
  row.appendChild(actions);
  li.appendChild(row);

  if (reminder.entry_preview) {
    const linkRow = document.createElement("div");
    linkRow.className = "entry-links";
    const noteChip = chip(`ph:note-pencil ${reminder.entry_preview}`, "link", () =>
      flashEntry(reminder.entry_id)
    );
    linkRow.appendChild(noteChip);
    li.appendChild(linkRow);
  }
  return li;
}

// Relative time that works both ways: "in 2 hours" (future) and "3 days ago"
// (past). relativeTime() only handles the past, which is wrong for reminders.
function relativeWhen(iso) {
  const diff = new Date(iso).getTime() - Date.now();
  const future = diff >= 0;
  const mins = Math.abs(diff) / 60000;
  if (mins < 0.75) return future ? "now" : "just now";
  let value;
  let unit;
  if (mins < 60) {
    value = Math.round(mins);
    unit = "minute";
  } else if (mins / 60 < 24) {
    value = Math.round(mins / 60);
    unit = "hour";
  } else if (mins / 60 / 24 < 7) {
    value = Math.round(mins / 60 / 24);
    unit = "day";
  } else {
    return new Date(iso).toLocaleDateString();
  }
  const label = `${value} ${unit}${value === 1 ? "" : "s"}`;
  return future ? `in ${label}` : `${label} ago`;
}

// Convert an ISO timestamp to the value a <input type=datetime-local> wants.
function toLocalInputValue(iso) {
  const d = new Date(iso);
  const pad = (n) => String(n).padStart(2, "0");
  return `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}T${pad(d.getHours())}:${pad(d.getMinutes())}`;
}

// The next occurrence of a recurring reminder. Steps forward from the due
// time until it lands in the future, so completing a long-overdue daily
// reminder doesn't just move it one day into the past.
function nextRecurringDate(fromIso, recurring) {
  const next = new Date(fromIso);
  const step = () => {
    if (recurring === "daily") next.setDate(next.getDate() + 1);
    else if (recurring === "weekly") next.setDate(next.getDate() + 7);
    else if (recurring === "monthly") next.setMonth(next.getMonth() + 1);
    else next.setDate(next.getDate() + 1); // safety fallback
  };
  step();
  const now = Date.now();
  let guard = 0;
  while (next.getTime() <= now && guard < 600) {
    step();
    guard += 1;
  }
  return next;
}

// A named quick-due preset -> a concrete Date.
function presetDate(preset) {
  const d = new Date();
  d.setSeconds(0, 0);
  switch (preset) {
    case "30m":
      d.setMinutes(d.getMinutes() + 30);
      break;
    case "1h":
      d.setHours(d.getHours() + 1);
      break;
    case "3h":
      d.setHours(d.getHours() + 3);
      break;
    case "tonight":
      // If it's already past 7pm, "tonight" can only mean tomorrow evening.
      if (d.getHours() >= 19) d.setDate(d.getDate() + 1);
      d.setHours(19, 0, 0, 0);
      break;
    case "tomorrow":
      d.setDate(d.getDate() + 1);
      d.setHours(9, 0, 0, 0);
      break;
    case "tomorrowpm":
      d.setDate(d.getDate() + 1);
      d.setHours(14, 0, 0, 0);
      break;
    case "weekend": {
      // The coming Saturday morning; on a Saturday or Sunday, the next one.
      const daysToSaturday = (6 - d.getDay() + 7) % 7 || 7;
      d.setDate(d.getDate() + daysToSaturday);
      d.setHours(10, 0, 0, 0);
      break;
    }
    case "nextweek":
      d.setDate(d.getDate() + 7);
      d.setHours(9, 0, 0, 0);
      break;
    default:
      break;
  }
  return d;
}

// --- the due time, split across two fields ------------------------------------
// #reminder-due stays the single source of truth (every caller already writes
// it), and these two keep the visible date/time inputs in step with it. Going
// through one setter is what stops the hidden value and the fields drifting
// apart, which would show one time and save another.

function setDue(localValue) {
  $("reminder-due").value = localValue || "";
  syncPartsFromDue();
  updateDueReadout();
}

function syncPartsFromDue() {
  const raw = $("reminder-due").value;
  const [date, time] = raw.split("T");
  $("reminder-date").value = date || "";
  // datetime-local may carry seconds; the time field wants HH:MM.
  $("reminder-time").value = (time || "").slice(0, 5);
}

function syncDueFromParts() {
  const date = $("reminder-date").value;
  const time = $("reminder-time").value || "09:00";
  // A date with no time is still a usable intention; a time with no date
  // isn't, so that combination is left alone until a date is picked.
  $("reminder-due").value = date ? `${date}T${time}` : "";
  updateDueReadout();
}

// A plain-English echo of whatever is in the datetime field. The raw
// "27/07/2026 11:20 AM" is hard to sanity-check at a glance; "in about 3
// hours: Monday 27 July, 11:20" is not (user-reported).
function updateDueReadout() {
  const readout = $("reminder-due-readout");
  if (!readout) return;
  const raw = $("reminder-due").value;
  if (!raw) {
    readout.textContent = "No time set";
    readout.classList.add("muted");
    return;
  }
  const when = new Date(raw);
  if (Number.isNaN(when.getTime())) {
    readout.textContent = "That date doesn't look right";
    return;
  }
  const minutes = Math.round((when.getTime() - Date.now()) / 60000);
  const pretty = when.toLocaleString([], {
    weekday: "short",
    day: "numeric",
    month: "short",
    hour: "numeric",
    minute: "2-digit",
  });
  let relative;
  if (minutes < 0) relative = "in the past";
  else if (minutes < 1) relative = "in under a minute";
  else if (minutes < 60) relative = `in ${minutes} min`;
  else if (minutes < 60 * 24) relative = `in about ${Math.round(minutes / 60)} h`;
  else {
    const days = Math.round(minutes / (60 * 24));
    relative = `in ${days} day${days === 1 ? "" : "s"}`;
  }
  setLabel(readout, `ph:alarm ${relative}: ${pretty}`);
  readout.classList.toggle("error", minutes < 0);
}

// Shift the due time by a number of minutes, from whatever is there now.
function nudgeDue(minutes) {
  const raw = $("reminder-due").value;
  const base = raw && !Number.isNaN(new Date(raw).getTime()) ? new Date(raw) : new Date();
  base.setMinutes(base.getMinutes() + minutes);
  setDue(toLocalInputValue(base.toISOString()));
}

// True when the compose form is untouched, nothing typed anywhere. Only then
// is it safe to move the due time out from under the user.
function reminderComposeIsPristine() {
  return (
    !$("reminder-text").value.trim() &&
    !$("reminder-magic").value.trim() &&
    $("reminder-priority").value === "normal" &&
    $("reminder-recurring").value === "none"
  );
}

// Re-seed the due time whenever the tab is opened on an untouched form, so it
// is always relative to now rather than to whenever the app happened to start
// (user request). A half-written reminder is never disturbed.
function refreshReminderDefaults() {
  if (!$("reminder-due").value || reminderComposeIsPristine()) {
    setDue(defaultDueValue());
  } else {
    syncPartsFromDue();
    updateDueReadout();
  }
}

async function snoozeReminderTo(reminder, when) {
  await apiJson(`/reminders/${reminder.id}`, {
    method: "PUT",
    body: JSON.stringify({ due_at: when.toISOString(), done: false }),
  });
  toast(`Snoozed to ${when.toLocaleString()}.`);
  loadReminders();
}

function reminderEditForm(reminder) {
  const wrap = document.createElement("div");
  wrap.className = "inline-action";
  const textInput = document.createElement("input");
  textInput.type = "text";
  textInput.maxLength = 500;
  textInput.value = reminder.text;
  const dueInput = document.createElement("input");
  dueInput.type = "datetime-local";
  dueInput.value = toLocalInputValue(reminder.due_at);
  const prioritySelect = buildSelect(
    [
      ["normal", "Normal"],
      ["low", "Low priority"],
      ["high", "High priority"],
    ],
    reminder.priority || "normal"
  );
  prioritySelect.title = "Priority";
  const recurringSelect = buildSelect(
    [
      ["none", "Once"],
      ["daily", "Daily"],
      ["weekly", "Weekly"],
      ["monthly", "Monthly"],
    ],
    reminder.recurring || "none"
  );
  recurringSelect.title = "Repeat";
  const row = document.createElement("div");
  row.className = "row";
  row.appendChild(
    smallButton("Save", "", async () => {
      const text = textInput.value.trim();
      if (!text || !dueInput.value) {
        toast("A reminder needs text and a time.", true);
        return;
      }
      await apiJson(`/reminders/${reminder.id}`, {
        method: "PUT",
        body: JSON.stringify({
          text,
          due_at: new Date(dueInput.value).toISOString(),
          priority: prioritySelect.value,
          recurring: recurringSelect.value,
        }),
      });
      editingReminderId = null;
      loadReminders();
    }, false)
  );
  row.appendChild(
    smallButton("Cancel", "", () => {
      editingReminderId = null;
      loadReminders();
    })
  );
  wrap.append(textInput, dueInput, prioritySelect, recurringSelect, row);
  setTimeout(() => textInput.focus(), 0);
  return wrap;
}

async function addReminder(text, dueValue, entryId = null, opts = {}) {
  if (!text || !dueValue) {
    toast("A reminder needs text and a due time.", true);
    return false;
  }
  await apiJson("/reminders", {
    method: "POST",
    body: JSON.stringify({
      text,
      due_at: new Date(dueValue).toISOString(),
      entry_id: entryId,
      priority: opts.priority || "normal",
      recurring: opts.recurring || "none",
    }),
  });
  // Asked here, when a reminder actually lands, and not on first load, a
  // permission prompt with no context is refused by default, and a refusal is
  // close to permanent (§36C).
  askNotificationPermission();
  toast("Reminder set.");
  loadReminders();
  return true;
}

// Magic Add: send natural language to the AI, which parses it into a reminder.
async function magicAddReminder() {
  const input = $("reminder-magic");
  const status = $("reminder-magic-status");
  const text = input.value.trim();
  if (!text) return;
  status.classList.remove("error");
  setLabel(status, "ph:magic-wand Parsing…");
  try {
    const reminder = await apiJson("/reminders/parse", {
      method: "POST",
      // Send our clock, so "tomorrow evening" is resolved against the time
      // the user can see rather than the server's UTC.
      body: JSON.stringify({ text, tz_offset_minutes: -new Date().getTimezoneOffset() }),
    });
    input.value = "";
    status.textContent = `Added “${reminder.text}”: ${relativeWhen(reminder.due_at)}. Edit it below if needed.`;
    askNotificationPermission();
    loadReminders();
  } catch (error) {
    status.classList.add("error");
    status.textContent = error.message;
  }
}

// The Wave O reminder poller used to live here. **It was dead code with a
// live timer**, and that combination is worse than either half.
//
// §36C rewrote `checkDueReminders` further down this file, badge, title
// count, one-notification-per-reminder, announced ids in localStorage, and a
// second `async function checkDueReminders` at the same scope simply replaces
// the first. What did not get deleted was the `setInterval(...)` that sat
// beside the old one, and since the name resolves to the surviving
// definition, that stray timer was running the *new* poller on a second
// 30-second interval. Two effects, both real:
//
// - twice the requests, for nothing;
// - and a race on the announcement: both polls read `announcedReminders()`
//   before either calls `rememberAnnounced`, so a reminder coming due could
//   be announced twice: which is precisely the "notifications are noisy"
//   shape of report this rewrite existed to fix.
//
// Found by opening the app in a real browser and reading the network log,
// which also showed the other half: the surviving poller runs before the
// unlock and 401s once per load. Its predecessor guarded on `authToken()`;
// that guard moved with the deletion (see `checkDueReminders` below).

// Default due time for new reminders: tomorrow morning, 9am.
// The field starts at today's date and the current time, so the common case
// is a small nudge rather than re-typing the whole thing. It used to jump to
// 9am tomorrow, which was wrong far more often than it was right. Rounded up
// to the next five minutes so the default isn't already in the past by the
// time you press Add.
function defaultDueValue() {
  const due = new Date();
  due.setSeconds(0, 0);
  due.setMinutes(Math.ceil((due.getMinutes() + 1) / 5) * 5);
  return toLocalInputValue(due.toISOString());
}

// --- tiny markdown renderer (Round 1) -------------------------------------------
// Safe by construction: builds DOM with createElement/textContent, never
// innerHTML, so note/answer text can never inject markup. Supports the
// subset small local models actually emit: headings, bullet/numbered
// lists, fenced code, and inline **bold**/*italic*/`code`/[links].

// True when `line` looks like a GFM table separator row, e.g.
// "| --- | :---: |", the row that turns the line above it into a header.
function isTableSeparator(line) {
  const trimmed = line.trim();
  if (!trimmed.includes("-") || !/\|/.test(trimmed)) return false;
  const cells = splitTableRow(trimmed);
  return cells.length > 0 && cells.every((c) => /^:?-{1,}:?$/.test(c.trim()));
}

// Split one "| a | b |" row into its cell strings, tolerating (and
// stripping) the optional leading/trailing pipes. Escaped \| stays literal.
function splitTableRow(line) {
  const cells = [];
  let current = "";
  for (let k = 0; k < line.length; k++) {
    const ch = line[k];
    if (ch === "\\" && line[k + 1] === "|") {
      current += "|";
      k++;
    } else if (ch === "|") {
      cells.push(current);
      current = "";
    } else {
      current += ch;
    }
  }
  cells.push(current);
  // Drop the empty cells created by leading/trailing pipes.
  if (cells.length && cells[0].trim() === "") cells.shift();
  if (cells.length && cells[cells.length - 1].trim() === "") cells.pop();
  return cells;
}

// Column alignment from the separator row: ":--" left, "--:" right,
// ":-:" centre, else none.
function columnAlign(spec) {
  const s = spec.trim();
  const left = s.startsWith(":");
  const right = s.endsWith(":");
  if (left && right) return "center";
  if (right) return "right";
  if (left) return "left";
  return "";
}

// A heading's anchor id: lowercase, spaces to dashes, punctuation dropped.
//
// The document outline could already jump to a heading, but it did it by
// moving the caret in the textarea (jumpToDocLine): which works only inside
// the editor, and not at all for a link written into the text. Real ids mean a
// heading is addressable the way every other markdown tool assumes.
function mdHeadingId(text, taken) {
  const base =
    String(text)
      .toLowerCase()
      .replace(/[`*_~\[\]()]/g, "")
      .replace(/[^a-z0-9]+/g, "-")
      .replace(/^-+|-+$/g, "")
      .slice(0, 60) || "section";
  // Two headings can share a name ("Notes" under three chapters), and a
  // duplicate id makes every link to it resolve to the first one.
  if (!taken) return base;
  let id = base;
  let n = 2;
  while (taken.has(id)) id = `${base}-${n++}`;
  taken.add(id);
  return id;
}

// The two block-level constructs the "/" menu inserts, built once and shared.
//
// They live outside renderMarkdown because **notes do not go through
// renderMarkdown at all**: a note card is rendered by renderNoteText, which
// is an inline pass (wiki links + emphasis + search-term highlighting). That
// asymmetry is easy to miss and was: the first live check of this feature
// found callouts and embeds rendering perfectly in a document and not at all
// in a note, which is half the feature missing in the surface people use most.

// A `.callout` element for a run of blockquote lines, or null when the quote
// is an ordinary one (no `[!kind]` marker) or nesting is already too deep.
function mdCalloutElement(quoted, depth) {
  // **The `-`/`+` after the marker is the fold flag**, REDESIGN.md §R7.3
  // item 3, Kortex's "typed collapsible blocks", asked for again directly:
  // "I want the structured note features and elements from kortex with the
  // slash commands to be rendered and easier for the user to use."
  //
  // It is deliberately Obsidian's own spelling rather than a new one: people
  // who want this feature have almost certainly met it there, and it is a
  // *marker*, so §R7.3's constraint holds exactly, storage and export do not
  // change, and a plain `> [!note]` in a note written last year still renders
  // as the same open box it always did.
  //
  //     > [!note]-  collapsed, click to open
  //     > [!note]+  a real fold, but open to begin with
  //     > [!note]   not foldable at all, unchanged
  const callout = quoted.length && quoted[0].match(/^\s*\[!(\w+)\]([-+])?\s*(.*)$/);
  if (!callout || depth >= MD_MAX_DEPTH) return null;

  const kind = callout[1].toLowerCase();
  const fold = callout[2] || "";
  const meta = (typeof CALLOUT_KINDS !== "undefined" && CALLOUT_KINDS[kind]) || null;
  // `<details>`/`<summary>` rather than a div and a click handler: the
  // browser gives the open/close, the keyboard operation and the ARIA for
  // free, which is the same reason every other disclosure in this app is one.
  const box = document.createElement(fold ? "details" : "div");
  if (fold === "+") box.open = true;
  // An unrecognised kind still renders as a box rather than as literal
  // "[!whatever]" text: a typo should look slightly wrong, not broken.
  box.className = `callout callout-${meta ? kind : "note"}${fold ? " callout-foldable" : ""}`;

  const head = document.createElement(fold ? "summary" : "p");
  head.className = "callout-head";
  const icon = document.createElement("span");
  icon.setAttribute("aria-hidden", "true");
  icon.textContent = meta ? meta.icon : "\u{1F4DD}";
  head.appendChild(icon);
  const title = document.createElement("span");
  // The title after the marker wins; failing that, the kind's own name.
  title.textContent = callout[3].trim() || (meta ? meta.label : kind);
  head.appendChild(title);
  box.appendChild(head);

  const body = document.createElement("div");
  body.className = "callout-body";
  // Rendered rather than inlined, so a callout can hold a list, a code block
  // or a link: which is most of why it beats a bold paragraph.
  renderMarkdown(body, quoted.slice(1).join("\n"), depth + 1);
  box.appendChild(body);
  return box;
}

// A `.note-embed` element for `![[name]]`.
function mdEmbedElement(name, depth) {
  const box = document.createElement("div");
  box.className = "note-embed";

  const head = document.createElement("p");
  head.className = "note-embed-head";
  const marker = document.createElement("span");
  marker.setAttribute("aria-hidden", "true");
  marker.textContent = "\u{1F4CE}";
  head.append(marker, document.createTextNode(` Embedded: ${name}`));
  box.appendChild(head);

  const body = document.createElement("div");
  body.className = "note-embed-body";
  const target = resolveWikiTarget(name);
  if (depth >= MD_MAX_DEPTH) {
    // A embeds B embeds A. The cap is what stops that hanging the tab, and
    // saying so beats rendering nothing and looking like a bug.
    body.textContent = "…(embedded too deep to show)";
  } else if (target && target.kind === "note") {
    renderMarkdown(body, target.entry.content || "", depth + 1);
  } else if (target && target.kind === "document") {
    // Documents have no content in the list payload (routes_documents._summary),
    // so this is a way in rather than an inline copy. See renderMarkdown's own
    // note on why a fetch does not belong in this path.
    const open = document.createElement("button");
    open.type = "button";
    open.className = "wiki-link";
    open.textContent = target.doc.title || wikiLinkLabel(name);
    open.title = "Open this document";
    open.addEventListener("click", (event) => {
      event.stopPropagation();
      openDocument(target.doc.id);
    });
    body.appendChild(open);
  } else {
    body.textContent = `Nothing called \u{201C}${name}\u{201D} yet.`;
  }
  box.appendChild(body);
  return box;
}

//: How deep a callout or an embed may nest before rendering stops.
//
// Both recurse into renderMarkdown, so both can loop: a callout containing a
// callout is legitimate and useful, but note A embedding note B embedding note
// A is an infinite regress that would hang the tab. The cap is generous enough
// that no honest document reaches it and low enough that a cycle costs
// nothing.
const MD_MAX_DEPTH = 4;

function renderMarkdown(container, text, depth = 0) {
  container.replaceChildren();
  const lines = unlatex(text).replace(/\r\n/g, "\n").split("\n");
  let i = 0;
  let list = null; // the <ul>/<ol> currently being filled, or null
  const headingIds = new Set(); // so two "Notes" headings get distinct anchors

  const closeList = () => {
    if (list) container.appendChild(list);
    list = null;
  };

  while (i < lines.length) {
    const line = lines[i];

    // Fenced code block. Gets a header strip with the language (when the
    // fence names one) and a copy button: selecting a code block by hand is
    // the one thing every other chat interface saves you from, and getting
    // it slightly wrong, a stray line, a missing last character, is the
    // kind of mistake you only notice after pasting it somewhere.
    if (line.trim().startsWith("```")) {
      closeList();
      const language = line.trim().slice(3).trim().split(/\s+/)[0] || "";
      const code = [];
      i++;
      while (i < lines.length && !lines[i].trim().startsWith("```")) {
        code.push(lines[i]);
        i++;
      }
      i++; // skip the closing fence
      const text = code.join("\n");

      const block = document.createElement("div");
      block.className = "code-block";
      const bar = document.createElement("div");
      bar.className = "code-bar";
      const label = document.createElement("span");
      label.className = "code-lang";
      label.textContent = language || "code";
      const copy = document.createElement("button");
      copy.type = "button";
      copy.className = "ghost small code-copy";
      copy.textContent = "⧉ Copy";
      copy.title = "Copy this code block";
      copy.addEventListener("click", (event) =>
        copyToClipboard(text, event.currentTarget)
      );
      bar.append(label, copy);

      const pre = document.createElement("pre");
      const codeEl = document.createElement("code");
      if (language) codeEl.dataset.lang = language;
      codeEl.textContent = text;
      pre.appendChild(codeEl);
      block.append(bar, pre);
      container.appendChild(block);
      continue;
    }

    // GFM pipe table: a row of "| … |" immediately followed by a
    // "| --- | --- |" separator turns into a real <table>.
    if (
      line.includes("|") &&
      i + 1 < lines.length &&
      isTableSeparator(lines[i + 1])
    ) {
      closeList();
      const headers = splitTableRow(line);
      const aligns = splitTableRow(lines[i + 1]).map(columnAlign);
      i += 2; // consume header + separator
      const bodyRows = [];
      while (i < lines.length && lines[i].includes("|") && lines[i].trim() !== "") {
        bodyRows.push(splitTableRow(lines[i]));
        i++;
      }
      const table = document.createElement("table");
      table.className = "md-table";
      const thead = document.createElement("thead");
      const headTr = document.createElement("tr");
      headers.forEach((cell, c) => {
        const th = document.createElement("th");
        if (aligns[c]) th.style.textAlign = aligns[c];
        appendInline(th, cell.trim());
        headTr.appendChild(th);
      });
      thead.appendChild(headTr);
      table.appendChild(thead);
      const tbody = document.createElement("tbody");
      for (const row of bodyRows) {
        const tr = document.createElement("tr");
        for (let c = 0; c < headers.length; c++) {
          const td = document.createElement("td");
          if (aligns[c]) td.style.textAlign = aligns[c];
          appendInline(td, (row[c] || "").trim());
          tr.appendChild(td);
        }
        tbody.appendChild(tr);
      }
      table.appendChild(tbody);
      // Let wide tables scroll sideways instead of breaking the layout.
      const scroller = document.createElement("div");
      scroller.className = "md-table-wrap";
      scroller.appendChild(table);
      container.appendChild(scroller);
      continue;
    }

    // Horizontal rule: ---, ***, or ___ on their own line.
    if (/^\s*([-*_])(\s*\1){2,}\s*$/.test(line)) {
      closeList();
      container.appendChild(document.createElement("hr"));
      i++;
      continue;
    }

    const heading = line.match(/^(#{1,6})\s+(.*)$/);
    if (heading) {
      closeList();
      // Map #→h3 … ######→h6 (the app reserves h1/h2 for its own chrome).
      const level = Math.min(6, heading[1].length + 2);
      const el = document.createElement(`h${level}`);
      // An id makes the heading a real jump target, for the outline and for
      // any [](#anchor) link written into the text.
      el.id = mdHeadingId(heading[2], headingIds);
      appendInline(el, heading[2]);
      container.appendChild(el);
      i++;
      continue;
    }

    // Transclusion: a line that is nothing but ![[name]] inlines that note's
    // text here, rather than linking to it. This is what makes a document
    // genuinely *composed of* notes instead of merely pointing at them.
    //
    // **Notes only, deliberately.** GET /documents returns id/title/words and
    // no content (routes_documents._summary), so embedding a document would
    // need a fetch: and renderMarkdown runs on every streamed chat chunk, so
    // a fetch in this path is a request storm waiting to happen. A document
    // target therefore renders as a labelled link, and the inline version
    // waits for a content-bearing endpoint rather than being bolted on here.
    const embedded = line.match(/^\s*!\[\[([^[\]]{1,120})\]\]\s*$/);
    if (embedded) {
      closeList();
      const name = embedded[1].trim();
      container.appendChild(mdEmbedElement(name, depth));
      i++;
      continue;
    }

    // Blockquote, and its dressed-up form the callout.
    //
    // `> [!warning] Watch out` on the first quoted line turns the whole quote
    // into a titled box. The syntax is GitHub/Obsidian's, chosen because it
    // degrades to an ordinary blockquote everywhere else, a note that leaves
    // this app stays readable, which a custom fence would not.
    if (/^\s*>\s?/.test(line)) {
      closeList();
      const quoted = [];
      while (i < lines.length && /^\s*>\s?/.test(lines[i])) {
        quoted.push(lines[i].replace(/^\s*>\s?/, ""));
        i++;
      }

      const box = mdCalloutElement(quoted, depth);
      if (box) {
        container.appendChild(box);
        continue;
      }

      const bq = document.createElement("blockquote");
      appendInline(bq, quoted.join(" "));
      container.appendChild(bq);
      continue;
    }

    const bullet = line.match(/^\s*[-*+]\s+(.*)$/);
    const numbered = line.match(/^\s*\d+\.\s+(.*)$/);
    if (bullet || numbered) {
      const wantOrdered = Boolean(numbered);
      if (!list || (list.tagName === "OL") !== wantOrdered) {
        closeList();
        list = document.createElement(wantOrdered ? "ol" : "ul");
        // Start where the author started. Without this a list written as
        // "3. 4. 5." renders as 1, 2, 3, and, more importantly, a list that
        // resumes after a paragraph restarts from 1.
        if (wantOrdered) {
          const first = Number.parseInt(line.trim(), 10);
          if (Number.isFinite(first) && first !== 1) list.start = first;
        }
      }
      const li = document.createElement("li");
      let itemText = (bullet || numbered)[1];
      // GFM task list: "- [ ] todo" / "- [x] done" → a real checkbox.
      const task = itemText.match(/^\[([ xX])\]\s+(.*)$/);
      if (task) {
        li.className = "md-task";
        const box = document.createElement("input");
        box.type = "checkbox";
        box.disabled = true;
        box.checked = task[1].toLowerCase() === "x";
        li.appendChild(box);
        itemText = task[2];
      }
      appendInline(li, itemText);
      list.appendChild(li);
      i++;
      continue;
    }

    if (line.trim() === "") {
      // A blank line only ends a list if what follows isn't another item of
      // the same kind. Models write "1.\n\n2.\n\n3." far more often than
      // they write it tightly, and closing the <ol> on each gap restarted the
      // numbering at 1 every single time (user-reported).
      let next = i + 1;
      while (next < lines.length && lines[next].trim() === "") next++;
      const continues =
        list &&
        next < lines.length &&
        (list.tagName === "OL"
          ? /^\s*\d+\.\s+/.test(lines[next])
          : /^\s*[-*+]\s+/.test(lines[next]));
      if (!continues) closeList();
      i++;
      continue;
    }

    // Plain paragraph: gather consecutive non-blank, non-special lines.
    closeList();
    const para = [line];
    i++;
    while (
      i < lines.length &&
      lines[i].trim() !== "" &&
      !lines[i].trim().startsWith("```") &&
      !lines[i].match(/^(#{1,6})\s+/) &&
      !lines[i].match(/^\s*>\s?/) &&
      !/^\s*([-*_])(\s*\1){2,}\s*$/.test(lines[i]) &&
      !lines[i].match(/^\s*[-*+]\s+/) &&
      !lines[i].match(/^\s*\d+\.\s+/) &&
      !(lines[i].includes("|") && i + 1 < lines.length && isTableSeparator(lines[i + 1]))
    ) {
      para.push(lines[i]);
      i++;
    }
    const p = document.createElement("p");
    appendInline(p, para.join(" "));
    container.appendChild(p);
  }
  closeList();
}

// --- tabs (Wave A) ----------------------------------------------------------------

// TABS drives which pages hide; the arrow-key order comes from the bar's own
// buttons, so this list's order is not load-bearing. "documents" sits last
// because it has no button of its own, it is reached from the Library.
const TABS = ["dashboard", "notes", "chat", "graph", "library", "timeline", "reminders", "documents"];

// The DOM-only half of switchTab: which panel is visible, which tab button
// is active. No network calls here, so this is safe to run before a token
// exists: see revealTab("dashboard")'s module-level call below, and why
// it's this instead of a full switchTab().
function revealTab(name) {
  for (const tab of TABS) {
    $(`tab-${tab}`).classList.toggle("hidden", tab !== name);
  }
  // `documents` is a sub-view of Library, there is no `data-tab="documents"`
  // button in the tab bar, so the name that determines which button is active
  // must be "library" whenever we are showing the documents pane. Without
  // this, switchTab("documents") leaves every tab button deactivated, making
  // it look as though nothing is selected while the Documents page is visible.
  //
  // This was briefly removed when Documents was promoted to a top-level tab,
  // and restored when that was reversed, the real fix for "documents feel
  // inaccessible" was giving them their own section in the Library instead of
  // leaving them inside a catch-all view called "Documents" that showed
  // everything. Worth the note so the next session does not re-derive it.
  const activeTabName = name === "documents" ? "library" : name;
  for (const button of document.querySelectorAll("#tab-bar button")) {
    const active = button.dataset.tab === activeTabName;
    button.classList.toggle("active", active);
    // Real tab semantics (Wave L): one tab stop for the whole list
    // (roving tabindex), arrow keys move between tabs.
    button.setAttribute("aria-selected", String(active));
    button.tabIndex = active ? 0 : -1;
  }
  // When the strip is narrow enough to scroll, the tab you just chose is the
  // one that must be legible, see revealActiveTab.
  revealActiveTab?.();
  localStorage.setItem("activeTab", name); // reopen where you left off
  // A new tab starts at its own top, and the back-to-top button re-evaluates
  // (it stays off the graph). Each page keeps its own scroll position now, so
  // this is a deliberate reset rather than a side effect of one shared one.
  scrollingPage()?.scrollTo({ top: 0, behavior: "auto" });
  scrollTopUpdate?.();
  // Any autogrow box that was measured while hidden gets its real height now
  // that its page is on screen. See autoGrow() for why a hidden measurement is
  // refused rather than applied.
  for (const box of document.querySelectorAll("textarea.autogrow")) {
    if (box.offsetParent !== null) autoGrow(box);
  }
}

// --- back / forward through the pages you have visited ----------------------
//
// Asked for directly. Deliberately *not* the browser's own history: this app
// is a single page with no routing, so pushState would put entries in the
// browser's stack that its Back button would then walk out of the app
// entirely on the first press past the start. This is a small stack of its
// own, capped, and behaving the way the browser's does: visiting a page
// while somewhere in the middle of the stack discards what was ahead.
const TAB_HISTORY_CAP = 50;
const tabHistory = { stack: [], index: -1, navigating: false };

// **The navigation-history popup**: asked for directly: "if they are right
// clicked, a little popup shows above with the navigation history to fast
// track back to a place (or maybe it can be a little button next to it??)".
// Built as both: a dedicated button beside Back/Forward, and right-click on
// either of them, opening the same list. Most-recent-first (a browser's own
// history dropdown reads the same way), with the current entry marked
// rather than clickable: jumping to where you already are is not a step.
function closeNavHistoryMenu() {
  const menu = $("status-nav-history-menu");
  if (!menu || menu.classList.contains("hidden")) return;
  menu.classList.add("hidden");
  $("status-nav-history")?.setAttribute("aria-expanded", "false");
}

function renderNavHistoryMenu() {
  const menu = $("status-nav-history-menu");
  if (!menu) return;
  menu.replaceChildren();
  if (!tabHistory.stack.length) {
    const empty = document.createElement("div");
    empty.className = "muted";
    empty.style.padding = "0.4rem 0.6rem";
    empty.textContent = "Nowhere visited yet this session.";
    menu.appendChild(empty);
    return;
  }
  // Asked for directly: "instead of squishing it, just make it scrollable
  // and/or cap the history stored". Both, and this is the cap half. The
  // stack itself stays at TAB_HISTORY_CAP so Back/Forward can still walk a
  // long way; what gets capped is how much of it this menu draws, because a
  // jump list is for the handful of places you were just at - past a dozen
  // rows you are reading a log, not picking a destination. The `.hidden`
  // path below and `max-height`/`overflow-y: auto` in
  // 02-chat-graph.css keep the rest scrollable rather than clipped.
  const NAV_HISTORY_SHOWN = 12;
  const oldest = Math.max(0, tabHistory.stack.length - NAV_HISTORY_SHOWN);
  for (let i = tabHistory.stack.length - 1; i >= oldest; i--) {
    const entry = tabHistory.stack[i];
    const current = i === tabHistory.index;
    const item = document.createElement(current ? "div" : "button");
    if (!current) item.type = "button";
    item.className = current ? "nav-history-item nav-history-current" : "nav-history-item";
    item.setAttribute("role", "menuitem");
    setLabel(item, `${current ? "ph:map-pin " : ""}${entryLabel(entry)}`);
    if (current) {
      item.title = "You're here";
    } else {
      item.addEventListener("click", () => {
        closeNavHistoryMenu();
        goToTabHistory(i);
      });
    }
    menu.appendChild(item);
  }
  // Say so rather than silently truncating: a jump list that quietly forgets
  // where you were is worse than one that admits its own limit.
  if (oldest > 0) {
    const more = document.createElement("div");
    more.className = "muted text-xs nav-history-more";
    more.textContent = `${oldest} older ${oldest === 1 ? "step" : "steps"} not shown`;
    menu.appendChild(more);
  }
}

// Opens upward, anchored to whichever of the three triggers was used, the
// status bar sits at the very bottom of the screen, so there is no "below"
// to open into. `position: fixed` (nav-history-menu's own CSS) plus an
// inline top/left computed here is the same escape-a-container shape
// `wireEscapedActionMenu` already uses for the Documents kebab, just
// triggered manually instead of by a class toggle.
function openNavHistoryMenu(anchorEl) {
  const menu = $("status-nav-history-menu");
  if (!menu) return;
  renderNavHistoryMenu();
  menu.classList.remove("hidden");
  $("status-nav-history")?.setAttribute("aria-expanded", "true");
  // `bottom` is fixed in CSS (nav-history-menu's own rule, anchored off the
  // status bar): only `left` needs computing, and only after the menu is
  // visible and populated, so its real width is known.
  const margin = 8;
  const anchor = anchorEl.getBoundingClientRect();
  menu.style.left = "0px";
  const box = menu.getBoundingClientRect();
  let left = anchor.left;
  if (left + box.width > window.innerWidth - margin) {
    left = Math.max(margin, window.innerWidth - margin - box.width);
  }
  menu.style.left = `${Math.round(left)}px`;
}

function paintTabHistory() {
  const back = $("status-back");
  const forward = $("status-forward");
  if (!back || !forward) return;
  back.disabled = tabHistory.index <= 0;
  forward.disabled = tabHistory.index >= tabHistory.stack.length - 1;
  // Named pages in the tooltip, not a bare "Back": knowing where it goes is
  // the difference between using it and guessing. paintStatusItem mirrors
  // title into aria-label centrally, so the disabled state is honest to a
  // screen reader too rather than still promising a previous page.
  const prev = tabHistory.stack[tabHistory.index - 1];
  const next = tabHistory.stack[tabHistory.index + 1];
  paintStatusItem("status-back", {
    icon: "ph:caret-left",
    title: prev ? `Back to ${entryLabel(prev)}` : "Nothing to go back to",
  });
  paintStatusItem("status-forward", {
    icon: "ph:caret-right",
    title: next ? `Forward to ${entryLabel(next)}` : "Nothing to go forward to",
  });
  // The settings modal's own copy of these two buttons, see their markup
  // comment for why a second copy exists instead of just raising the status
  // bar's z-index above every modal in the app.
  const modalBack = $("settings-nav-back");
  const modalForward = $("settings-nav-forward");
  if (modalBack && modalForward) {
    modalBack.disabled = back.disabled;
    modalForward.disabled = forward.disabled;
    modalBack.title = prev ? `Back to ${entryLabel(prev)}` : "Nothing to go back to";
    modalForward.title = next ? `Forward to ${entryLabel(next)}` : "Nothing to go forward to";
    modalBack.setAttribute("aria-label", modalBack.title);
    modalForward.setAttribute("aria-label", modalForward.title);
  }
}

// The tab's own visible name, so a tooltip says "Back to Documents" rather
// than "Back to documents" or, worse, an internal id.
function tabLabel(name) {
  // Not a real tab-page, see stepTabHistory's own "settings" branch, so
  // there is no `#tab-bar` button to read a label from.
  if (name === "settings") return "Settings";
  const button = document.querySelector(`#tab-bar button[data-tab="${name}"]`);
  return button?.textContent?.trim() || name;
}

// "Notes → Capture" rather than just "Notes", so Back names the step it
// actually takes when the move was between sub-tabs of one tab.
function entryLabel(entry) {
  const tab = tabLabel(entry.tab);
  if (!entry.section) return tab;
  // Chat's section is a conversation id ("conv:42") or "new", neither is a
  // button with real text the way Notes'/Library's sub-tabs are, so there is
  // no good short label to build; naming the tab is honest instead of
  // printing the raw id.
  if (entry.tab === "chat") return tab;
  const button = document.querySelector(`[data-section="${entry.section}"]`);
  const section = button?.textContent?.trim() || entry.section;
  return `${tab} → ${section}`;
}

// One history entry. `section` is the sub-tab within a tab, when that tab has
// them: asked for directly: "have the back and forward navigation also handle
// navigation between sub tabs as well." Notes has four (browse / capture /
// writing-room / ask) and moving between them is as much a navigation as
// moving between tabs, so Back should undo it.
function recordTabVisit(name, section = null) {
  // A back/forward press is a move *through* history, not a new entry.
  if (tabHistory.navigating) return;
  const current = tabHistory.stack[tabHistory.index];
  // Re-selecting exactly where you already are is not a step.
  if (current && current.tab === name && current.section === section) return;
  // One entry per visit. A Notes arrival is recorded twice, as {notes,
  // "browse"} by showNotesSection and as {notes, null} by switchTab (in
  // either order), so Back from the next tab landed on the duplicate first
  // and looked like it did nothing (reported: "I need to click back or
  // forwards twice"). When the tab on top is this tab and one of the two
  // sections is null, the entry is refined in place rather than pushed.
  if (current && current.tab === name && (current.section == null || section == null)) {
    if (section != null) current.section = section;
    paintTabHistory();
    return;
  }
  tabHistory.stack = tabHistory.stack.slice(0, tabHistory.index + 1);
  tabHistory.stack.push({ tab: name, section });
  if (tabHistory.stack.length > TAB_HISTORY_CAP) tabHistory.stack.shift();
  tabHistory.index = tabHistory.stack.length - 1;
  paintTabHistory();
}

function stepTabHistory(delta) {
  return goToTabHistory(tabHistory.index + delta);
}

// The shared jump used by both Back/Forward (one step) and the history
// popup below (any step at once), asked for directly: "a little popup
// shows above with the navigation history to fast track back to a place".
// stepTabHistory used to inline this with a fixed +1/-1, which had no way
// to land on an arbitrary earlier or later entry.
async function goToTabHistory(next) {
  if (next < 0 || next >= tabHistory.stack.length) return;
  const entry = tabHistory.stack[next];
  tabHistory.index = next;
  tabHistory.navigating = true;
  try {
    // Settings is a modal overlay, not one of the tab-pages switchTab knows
    // about: asked for directly: "the back and forward buttons should cover
    // going in and out of settings too", which they didn't, because nothing
    // ever called recordTabVisit for it. Restoring a settings entry opens the
    // modal (or moves it to a different section) instead of going through
    // switchTab at all; restoring anything else closes it first if it was
    // left open, the same way clicking Close would.
    if (entry.tab === "settings") {
      await openSettingsModal(entry.section || "models");
      paintTabHistory();
      return;
    }
    if (settingsModalOpen()) closeSettingsModal();
    switchTab(entry.tab);
    // The sub-tab is restored after the tab, because both restore paths below
    // act on elements the tab switch has just revealed.
    if (entry.tab === "notes" && entry.section) {
      showNotesSection(entry.section);
    } else if (entry.tab === "library") {
      // Reuses the real click handler (whiteboard.js) rather than
      // duplicating its section-show/whiteboard-landing/gallery-render
      // logic here: a second copy is exactly the shape this codebase keeps
      // getting bitten by. `tabHistory.navigating` (set above) makes the
      // handler's own `recordTabVisit` call a no-op, the same guard
      // `showNotesSection`'s call already relies on above. A bare `{tab:
      // "library"}` entry (recorded the moment the tab itself was opened,
      // before any sub-tab click) has no `section`, falls back to "All"
      // (`library-view-documents`, the sub-tab that kept its old id) rather
      // than leaving whatever sub-view happened to be on screen already.
      //: **A board is a place, and `board:{id}` is not a sub-tab id.**
      //: `openWhiteboardBoard` records one now (see whiteboard.js), so this
      //: has to know how to go back to one, without this branch the selector
      //: below would look for `button[data-target="board:12"]`, match nothing,
      //: and Back would silently do nothing at all. Recording a place you
      //: cannot return to is worse than not recording it: the entry appears in
      //: the history popup and then refuses to work.
      if (entry.section?.startsWith("board:")) {
        //: Awaited for the same reason chat's `conv:` and documents' `doc:`
        //: branches are: it fetches before it finishes, and returning early
        //: would clear `tabHistory.navigating` in the `finally` below: turning
        //: every back/forward through a board into a fresh history entry
        //: instead of a no-op.
        await openWhiteboardBoard(Number(entry.section.slice("board:".length)));
      } else {
        document
          .querySelector(
            `#library-subtabs button[data-target="${entry.section || "library-view-documents"}"]`
          )
          ?.click();
      }
    } else if (entry.tab === "chat" && entry.section) {
      if (entry.section.startsWith("conv:")) {
        // Awaited deliberately: openConversation does its own network fetch
        // before calling recordTabVisit, so returning early here would clear
        // tabHistory.navigating (in the finally below) before that call runs
        //, turning every back/forward through a saved chat into a fresh,
        // spurious history entry instead of a no-op.
        await openConversation(Number(entry.section.slice("conv:".length)));
      } else if (entry.section === "new") {
        newChatConversation();
      }
    } else if (entry.tab === "documents" && entry.section?.startsWith("doc:")) {
      // Same awaited-before-finally shape as chat's conv: branch above, for
      // the same reason: openDocument does its own network fetch before
      // calling recordTabVisit, so an un-awaited call here would clear
      // tabHistory.navigating too early and turn this into a fresh entry.
      await openDocument(Number(entry.section.slice("doc:".length)));
    } else if (entry.tab === "graph") {
      // switchTab's own "graph" branch above already rendered once with
      // whatever graphFocusModeId happened to hold; set it to match this
      // history entry and render again so Focus Mode itself is part of what
      // back/forward restores, not just the tab underneath it.
      graphFocusModeId = entry.section?.startsWith("focus:")
        ? Number(entry.section.slice("focus:".length))
        : null;
      $("graph-focus-clear")?.classList.toggle("hidden", !graphFocusModeId);
      await renderGraph();
    }
  } finally {
    // Cleared in a finally so a throw inside a tab's own setup cannot strand
    // the flag on and silently stop recording every later visit.
    tabHistory.navigating = false;
  }
  paintTabHistory();
}

// Empty states carry one action (DESIGN.md → Voice): "Capture a note" from
// the Timeline and Graph empties, "Add a reminder" from the Reminders one.
// One delegated listener rather than one per button, so a fourth empty
// state adds a `data-empty-action` and nothing else (and
// test_frontend_handlers.py has one listener to count, not four).
//: Every dock menu (UI_MODERNISATION_PLAN.md Phase 8) is a `<details>`: the
//: browser gives open-on-click, Enter/Space, Escape and the ARIA. What it does
//: not give is closing when you pick an item or click away, and both are what
//: make a menu feel like a menu rather than a panel you have to shut. One
//: delegated pair for every `.dock-menu` on every tab: the same shape the
//: documents kebab wires for itself in documents.js, so a dock added later
//: gets the behaviour without anyone remembering to add it. A segmented
//: control inside a menu (Layout, Colour) keeps the menu open: picking a
//: layout and then a colour is one visit, not two.
document.addEventListener("click", (event) => {
  // `.action-menu-escaped` covers a list `escapeMenuIfClipped` has reparented
  // to <body> (see the toggle listener below): it is then a sibling of its
  // `details.dock-menu`, not a descendant, so `menu.contains(event.target)`
  // below would read every click inside the still-open list as an outside
  // click and shut it on the first interaction. Same widening
  // `.action-menu-escaped` already gets in the pointerdown-close listener
  // for `.action-menu` (search this file for that class).
  const item = event.target.closest(".dock-menu .doc-dock-menu-item, .action-menu-escaped .doc-dock-menu-item");
  if (item) {
    const menu = item.closest("details.dock-menu") || item.closest(".doc-dock-menu-list")?._escapedHome?.parent;
    // After the item's own handler has run: closing first would move focus
    // and, for a toggle, leave its aria-expanded one step behind.
    if (menu) setTimeout(() => { menu.open = false; }, 0);
  }
  for (const menu of document.querySelectorAll("details.dock-menu[open]")) {
    if (menu.contains(event.target)) continue;
    if (event.target.closest(".action-menu-escaped")) continue;
    menu.open = false;
  }
});
//: A dock menu opens under its own button, which is right for a button on
//: the left of the row and wrong for one near the right edge: measured, the
//: Timeline's Options list ran 41px past the viewport. On open, the list is
//: measured once and flipped to right-align when it would overflow, a class,
//: not a computed left, so the stylesheet still owns the geometry.
//:
//: **Vertical clipping was the same shape and had no fix at all.** Reported
//: (INBOX 31, whiteboard's View menu screenshot): "dropdown menus clip off
//: the bottom of the panel and do not scroll, app-wide." The stylesheet caps
//: `.doc-dock-menu-list` at a flat `calc(100vh - space-9*2)`, which is blind
//: to *where* the menu opened: a button in the lower half of a short window
//: opens a list well under that flat cap and still lands with its own
//: bottom edge past the viewport, nothing to scroll because nothing
//: overflowed the box the stylesheet gave it. Measured before this fix,
//: Reminders' Quick set menu at 1024x560: rect.bottom 732 against a 560px
//: viewport, 172px unreachable, no internal scrollbar
//: (`scrollHeight === clientHeight`). After: the cap is recomputed from the
//: list's own top on every open, so it can never claim more room than is
//: actually left below it.
//:
//: `escapeAndCapMenu` (above) is both halves of that: it escapes a clipping
//: ancestor first, because a dock menu whose panel sits inside a scrolling
//: one (`overflow` anything but `visible`) is still cut by that ancestor
//: however correctly its own height is capped, and only reparenting to <body>
//: gets it out. The escape is a no-op whenever there is no such ancestor,
//: which is most of these menus, so nothing changes for a dock menu that
//: already had room. The whiteboard's top-bar menus call the same function;
//: this handler used to hold its own copy of it.
document.addEventListener(
  "toggle",
  (event) => {
    const menu = event.target;
    if (!(menu instanceof HTMLElement) || !menu.matches("details.dock-menu")) return;
    // Once escaped, the list is a child of <body>, not of `menu`: cache the
    // reference the first time so a later close/reopen can still find it.
    const list = menu._dockMenuList || menu.querySelector(".dock-menu-list");
    if (!list) return;
    menu._dockMenuList = list;
    if (!menu.open) {
      // Closed: put an escaped list back where it lives in the DOM (a no-op
      // if it was never escaped) and drop this open's inline cap, so the
      // next open starts from the stylesheet's own numbers, not a stale one.
      restoreEscapedMenu(list);
      list.style.maxHeight = "";
      return;
    }
    menu.classList.remove("dock-menu-flip");
    if (list.getBoundingClientRect().right > window.innerWidth - 8) menu.classList.add("dock-menu-flip");
    escapeAndCapMenu(list, menu.querySelector("summary") || menu);
  },
  true
);
//: Escape closes an open dock menu and puts focus back on its button, 
//: `<details>` does not do this on its own, whatever a comment elsewhere in
//: this codebase once claimed; measured with a keyboard-only probe. Capture
//: phase, so the graph's own Escape (leave trace mode) and the lock screen's
//: never see a key that was meant for the menu.
document.addEventListener(
  "keydown",
  (event) => {
    if (event.key !== "Escape") return;
    const open = document.querySelector("details.dock-menu[open]");
    if (!open) return;
    event.preventDefault();
    event.stopPropagation();
    open.open = false;
    open.querySelector("summary")?.focus();
  },
  true
);

document.addEventListener("click", (event) => {
  const button = event.target.closest("[data-empty-action]");
  if (!button) return;
  const action = button.dataset.emptyAction;
  if (action === "capture") {
    switchTab("notes");
    showNotesSection("capture", { focus: true });
    // The section reveal is a class toggle in the same task; focus a frame
    // later so the box is visible when the caret lands in it.
    requestAnimationFrame(() => $("entry-content")?.focus());
  } else if (action === "reminder") {
    const field = $("reminder-text") || $("reminder-magic");
    if (field) field.focus();
  } else if (action === "clear-filter") {
    // The same path as typing into the box and deleting it: the handler on
    // #note-search owns `noteSearch`, the Save-filter button and the render.
    const search = $("note-search");
    if (search) {
      search.value = "";
      search.dispatchEvent(new Event("input", { bubbles: true }));
      search.focus();
    }
  } else if (action === "new-document") {
    $("library-docs-new")?.click();
  } else if (action === "new-board") {
    $("wb-boards-new")?.click();
  } else if (action === "add-link") {
    $("bookmark-url-input")?.focus();
  }
});

function switchTab(name) {
  // Profiled directly: leaving the Graph tab left `graphSimulation` running
  //, it is only ever `.stop()`-ed "before every rebuild" (graph.js), never
  // on navigating away: so its tick handler kept costing real main-thread
  // time on every *other* tab until its own alpha naturally decayed. Under
  // 6x CPU throttling on a 120-note graph: busy time on the Dashboard tab
  // measured 21% before ever opening Graph, 58% immediately after leaving
  // it, decaying back to ~20% only after roughly 12 more seconds, a
  // background cost with no relation to whatever tab the person actually
  // switched to, and easily misread as "the app feels slow" generally
  // rather than traced back to the Graph tab. `graphSimulation?.stop()` is
  // safe to call unconditionally on leaving: `renderGraph()` already
  // creates a fresh simulation on the next visit regardless of whether the
  // old one was still running or already stopped.
  const leavingGraph = localStorage.getItem("activeTab") === "graph" && name !== "graph";
  recordTabVisit(name);
  revealTab(name);
  if (leavingGraph) {
    graphSimulation?.stop();
    // The canvas renderer's simulation is in a Worker, so there is no
    // `graphSimulation` to stop: the same "a cooling layout must not go on
    // running in a tab nobody is looking at" rule needs its own message.
    if (typeof gcStop === "function") gcStop();
    // Full screen is a state of the map, not of the app, and it now hides the
    // top bar and the status bar with it. Leaving the tab while it is on (the
    // command palette and the keyboard shortcuts still work with the chrome
    // hidden) would otherwise land somebody on another tab with no tab bar to
    // get back with.
    if ($("graph-card")?.classList.contains("graph-fullscreen")) toggleGraphFullscreen();
  }
  // The generative-art animation only needs to run while it's on screen.
  if (name !== "dashboard") stopArt();
  if (name === "chat") {
    renderChatEmptyState(); // welcome placeholder when the thread is empty
    loadChatSuggestions();
    //: **The composer takes the caret, but not the focus ring, on arrival.**
    //: Reported as "chat panel shadow". Measured on a freshly loaded Chat tab
    //: (`scratchpad/ui-sweeps/chatshadow.js`): `.chat-dock` computed
    //: `box-shadow: rgba(79,109,245,0.14) 0 0 0 3px` with an accent-mixed
    //: border, and `dockFocusWithin: true` with `#chat-input` as the active
    //: element, all before anyone had touched anything. It is not a shadow,
    //: it is `.chat-dock:focus-within`'s accent ring, and the focus that
    //: lights it is the line below, not the reader's. So every visit to Chat
    //: opened with a permanent blue halo round the composer, the loudest
    //: thing on the screen and the only element in the app that rings itself
    //: on load.
    //:
    //: The focus stays (arriving able to type is the point of it); the ring
    //: waits until the focus is the reader's own. `chatDockArmRing` below
    //: takes the marker back off at the first key, the first press inside the
    //: dock, or the moment focus leaves it, so a deliberate click into the
    //: composer rings exactly as it did.
    chatDockSuppressRing();
    $("chat-input").focus();
    // Nothing in a hidden tab can be measured, so the composer's fit is done
    // here rather than at startup, the window may well have changed size
    // since the last time this tab was visible.
    refitComposer();
  }
  if (name === "dashboard") renderDashboard();
  if (name === "graph") {
    // A fresh visit to the tab frames the whole map; the filter/slider
    // changes that call renderGraph() again while already on this tab
    // leave whatever the user last panned or zoomed to alone (graph.js).
    graphAutoFitDone = false;
    const layout = graphLayout();
    const layoutInput = document.querySelector(`input[name="graph-layout"][value="${layout}"]`);
    if (layoutInput) layoutInput.checked = true;
    
    // Same for what the colours mean: a saved setting the control does not
    // show is a control that lies about the map beside it.
    const savedColour = localStorage.getItem("graph-colour");
    const colourSelect = document.getElementById("graph-colour");
    if (savedColour && colourSelect && [...colourSelect.options].some((o) => o.value === savedColour)) {
      colourSelect.value = savedColour;
    }
    // Match the saved layout on arrival, not only on change, otherwise a
    // notebook left on Tree comes back with two live-looking dead sliders.
    setGraphPhysicsEnabled(graphLayout());
    setGraphOptionsOpen(localStorage.getItem("graph-options-open") === "1");
    setTracePanelOpen(localStorage.getItem("graph-trace-open") === "1");
    renderGraph();
  }
  if (name === "timeline") {
    // Match the saved bucket choice on arrival, not only on change: a notebook
    // left on Month that comes back on Auto is a control that lies about the
    // feed beside it, which is the same bug the graph's layout picker had.
    $("timeline-scale").value = timelineScaleChoice();
    // Same for which view: a saved choice the segment does not show is a
    // control that lies about the thing under it.
    syncTimelineViewSeg();
    renderTimeline();
  }
  if (name === "documents") {
    loadDocuments();
    renderDocStorage();
  }
  if (name === "library") loadLibrary();
  if (name === "reminders") {
    refreshReminderDefaults();
    loadReminders();
  }
}

// --- Timeline (§10B, TIMELINE_PLAN.md Phase 1) -------------------------------
//
// Asked for repeatedly, and with more shape each time: "I want a note timeline
// where I can see notes visually by what time they were made. Maybe I can even
// group them by events or related places etc."
//
// What this replaced, and why, because the shape that went is the shape the
// next session would otherwise reach for again (TIMELINE_PLAN.md §2, measured
// over 48 notes and six months): a **grid** of one column per bucket and one
// card per note, 8,800px wide against a 1,358px viewport with 79% of its cells
// empty, and a **line** view drawn in SVG, 14 text nodes for 48 notes, no
// titles, no keyboard stops, a hover popup as the only way to read anything.
// Both answered a question ("when were notes written") that a notebook's owner
// does not have. The question they do have is the one a journal answers: what
// was I doing then, and what came before and after it.
//
// So the timeline is a feed now: newest first, a `<section>` per bucket with a
// sticky header, a row per entry, the spine and the headers in CSS. Rows are
// real elements, which is what buys the titles, the tab stops, the text
// selection, the ellipsis and the app's own chip recipe without building any
// of them (TIMELINE_PLAN decision 3). The table view is the same rows in a
// `<table>` (Phase 2); both read from `timelineRow()` and from nothing else,
// so the two can never disagree about what a search matched.

//: **One row model** (TIMELINE_PLAN decision 2). Everything the feed, the
//: table, search, the filter and the count need, derived once per entry, with
//: the endpoint's wire names translated here and nowhere else.
//:
//: `space`, `words` and `links` are in the shape because the table's columns
//: are (decision 6) and `/timeline` does not send them yet: they read as
//: absent rather than as zero, so a column can say "not known" instead of
//: claiming a note has no links. The endpoint grows them with the table.
function timelineRow(entry) {
  // A board *is* an `Entry` (MINDMAP_PLAN.md §2) and `/timeline` has always
  // returned one, so without this a mind map reads as a note titled
  // "# My map". `loadMapBoardIndex()` is awaited before any row is built.
  const board = mapBoardById(entry.id);
  const flat = stripMarkdownPreview(entry.preview || "").trim();
  const cut = flat.indexOf("\n");
  const head = (cut === -1 ? flat : flat.slice(0, cut)).trim();
  const rest = cut === -1 ? "" : flat.slice(cut + 1).replace(/\s+/g, " ").trim();
  return {
    id: entry.id,
    kind: board ? "board" : "note",
    board,
    // The first line of a note is what a person calls it, heading or not.
    title: (board ? board.title : head) || "Untitled note",
    snippet: rest,
    when: parseServerTime(entry.at) || new Date(entry.at),
    whenIso: entry.at,
    writtenAt: entry.written_at,
    //: Said out loud, because the alternative is a timeline that looks like it
    //: has quietly moved someone's notes: "mentioned" means the row sits on a
    //: date the note *talks about*, and `phrase` is the words that did it.
    placedBy: entry.placed_by,
    phrase: entry.phrase || "",
    tags: Array.isArray(entry.tags) ? entry.tags : [],
    category: entry.category || "",
    space: entry.space ?? null,
    words: entry.words ?? null,
    links: entry.links ?? null,
    pinned: Boolean(entry.pinned),
    parentId: entry.parent_id ?? null,
  };
}

//: **The buckets are computed here, not fetched.** `/timeline` labels every
//: entry with a bucket for the `scale` it was asked for, which made a change
//: of scale a round trip, and made "auto" impossible: the rule for auto is a
//: count of what is in range, which is only known once the range has arrived.
//: Bucketing from the row's own moment instead makes Day/Week/Month/Year a
//: repaint (measured at 0 requests), and keeps one definition of "which week
//: is this" rather than one here and one in Python.
//:
//: Monday starts the week, matching `routes_timeline.py`'s `weekday()`, so the
//: two agree for as long as the endpoint's own labels are still read by
//: anything.
function timelineBucketKey(when, scale) {
  const day = new Date(when.getTime());
  day.setHours(0, 0, 0, 0);
  if (scale === "week") day.setDate(day.getDate() - ((day.getDay() + 6) % 7));
  if (scale === "month") day.setDate(1);
  if (scale === "year") {
    day.setMonth(0);
    day.setDate(1);
  }
  return `${day.getFullYear()}-${String(day.getMonth() + 1).padStart(2, "0")}-${String(
    day.getDate()
  ).padStart(2, "0")}`;
}

// The header a bucket wears. A day gets the words people use for it, which is
// what makes the feed read as a journal rather than as a list of dates; a
// month or a year is already unambiguous and gets its name.
function timelineBucketLabel(key, scale) {
  const day = new Date(`${key}T00:00:00`);
  if (Number.isNaN(day.getTime())) return key;
  const thisYear = day.getFullYear() === new Date().getFullYear();
  if (scale === "year") return String(day.getFullYear());
  if (scale === "month") {
    return day.toLocaleDateString(undefined, { month: "long", year: "numeric" });
  }
  if (scale === "week") {
    return `Week of ${day.toLocaleDateString(undefined, {
      day: "numeric",
      month: "short",
      ...(thisYear ? {} : { year: "numeric" }),
    })}`;
  }
  const today = timelineBucketKey(new Date(), "day");
  const yesterday = new Date();
  yesterday.setDate(yesterday.getDate() - 1);
  if (key === today) return "Today";
  if (key === timelineBucketKey(yesterday, "day")) return "Yesterday";
  return day.toLocaleDateString(undefined, {
    weekday: "short",
    day: "numeric",
    month: "short",
    ...(thisYear ? {} : { year: "numeric" }),
  });
}

//: **Auto is the default scale** (TIMELINE_PLAN decision 4). Day buckets over
//: a year of writing are a header every second row; month buckets over a week
//: are one header and no structure at all. The thresholds (day under 60 notes
//: in range, week under 400, else month) are the plan's first guess and are
//: written down there as something to tune against a real notebook, not as a
//: measurement.
//:
//: It counts what the *range* holds rather than what the search left, so
//: typing in the search box never re-cuts the headers under the reader.
const TIMELINE_SCALES = ["day", "week", "month", "year"];
// Density follows the bucket, and nothing else decides it: a day's rows carry
// the snippet, a week's drop it, a month's and a year's are a title and a date
// in two columns. The names are the `data-density` values the CSS reads.
const TIMELINE_DENSITY = { day: "full", week: "compact", month: "dense", year: "dense" };

function timelineScaleChoice() {
  const saved = localStorage.getItem("timeline-scale");
  return saved === "auto" || TIMELINE_SCALES.includes(saved) ? saved : "auto";
}

function timelineResolvedScale(countInRange) {
  const chosen = $("timeline-scale").value || timelineScaleChoice();
  if (TIMELINE_SCALES.includes(chosen)) return chosen;
  if (countInRange < 60) return "day";
  if (countInRange < 400) return "week";
  return "month";
}

//: The loaded range, as rows, plus the one row opened in place and the one
//: group filter that is on. Search, filter and sort all run over this array
//: (decision 2), so the feed and the table cannot disagree, and a keystroke
//: costs a repaint rather than a request.
let timelineRows = [];
// By id, so a row that continues another can name it without a scan per row:
// `find` per row is the shape that turns 1,500 rows into a million comparisons
// to draw one screen.
let timelineById = new Map();
let timelineGroupNames = [];
let timelineFilter = null;
let timelineOpenId = null;

async function renderTimeline() {
  let url = `/timeline?scale=${$("timeline-scale").value === "auto" ? "day" : $("timeline-scale").value}`
    + `&group=${$("timeline-group").value}`;
  const daysVal = $("timeline-days").value;
  if (daysVal === "custom") {
    const start = $("timeline-start-date").value;
    const end = $("timeline-end-date").value;
    if (start && end) {
      url += `&start=${start}T00:00:00Z&end=${end}T23:59:59Z`;
    } else {
      url += `&days=365`; // Fallback if they haven't picked both dates yet
    }
  } else {
    url += `&days=${daysVal}`;
  }
  //: Which of these entries are maps, awaited alongside the timeline rather
  //: than before it, because neither needs the other's answer.
  const [body] = await Promise.all([apiJson(url).catch(() => null), loadMapBoardIndex()]);
  timelineRows = body ? body.notes.map(timelineRow) : [];
  // Newest first by the moment the row *sits* on, not by when it was typed.
  // Those differ for every note placed by what it mentions, and the old grid
  // ordered by one and bucketed by the other, so a note about next Friday
  // arrived in Friday's column behind notes written after it.
  timelineRows.sort((a, b) => b.when - a.when);
  timelineById = new Map(timelineRows.map((row) => [row.id, row]));
  timelineOpenId = null;
  if (timelineFilter && !timelineRows.some((row) => timelineRowGroups(row).includes(timelineFilter))) {
    // A filter naming a category that is not in the new range would hide
    // everything with no way to tell why.
    timelineFilter = null;
  }
  fillTimelineBandOptions();
  paintTimeline();
}

// What a row belongs to under the current grouping: the value the band filter
// matches against. Threads are named by the note they continue, which is the
// only name a thread has.
function timelineRowGroups(row) {
  const group = $("timeline-group").value;
  if (group === "tag") return row.tags.length ? row.tags : ["untagged"];
  if (group === "thread") return [row.parentId ? `note-${row.parentId}` : `note-${row.id}`];
  if (group === "none") return [];
  // "Uncategorised" is where notes land when a category goes away, and is the
  // name the rest of the app uses for it.
  return [row.category || "Uncategorised"];
}

// The band filter's options come from what is loaded, because a filter offering
// a category the range does not contain is a dead end. Built after every fetch
// and after a change of grouping; the current value survives if it is still
// there.
function fillTimelineBandOptions() {
  const select = $("timeline-band");
  const group = $("timeline-group").value;
  const section = $("timeline-band-section");
  section.classList.toggle("hidden", group === "none" || group === "thread");
  const counts = new Map();
  for (const row of timelineRows) {
    for (const name of timelineRowGroups(row)) counts.set(name, (counts.get(name) || 0) + 1);
  }
  const names = [...counts.entries()].sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0]));
  timelineGroupNames = names.map(([name]) => name);
  select.replaceChildren();
  const all = document.createElement("option");
  all.value = "";
  all.textContent = "Everything";
  select.appendChild(all);
  for (const [name, count] of names) {
    const option = document.createElement("option");
    option.value = name;
    option.textContent = `${name} (${count})`;
    select.appendChild(option);
  }
  if (timelineFilter && !counts.has(timelineFilter)) timelineFilter = null;
  select.value = timelineFilter || "";
  syncTimelineFilterChip();
}

// The filter, said out loud in the dock's find zone rather than only inside a
// menu nobody has open: the same shape Graph uses for "a state is on and here
// is the way out of it" (`#graph-highlight-clear`).
function syncTimelineFilterChip() {
  const clear = $("timeline-filter-clear");
  clear.classList.toggle("hidden", !timelineFilter);
  if (timelineFilter) {
    setLabel(clear, `ph:x Show: ${timelineFilter}`);
    clear.title = `Stop showing only ${timelineFilter}`;
  }
}

// Search and the band filter, applied to the array (decision 2). They filter
// rather than dim: a dimmed row still takes its space, still answers Ctrl+F
// and still has to be read past, which is why the old view's search was
// reported as doing nothing useful.
function timelineVisibleRows() {
  const query = ($("timeline-search").value || "").trim().toLowerCase();
  let rows = timelineRows;
  if (timelineFilter) {
    rows = rows.filter((row) => timelineRowGroups(row).includes(timelineFilter));
  }
  if (query) {
    rows = rows.filter((row) =>
      `${row.title} ${row.snippet} ${row.category} ${row.tags.join(" ")}`
        .toLowerCase()
        .includes(query)
    );
  }
  return rows;
}

//: Everything that is true of both views, in one place: which of them is
//: showing, the two empty states, and the rows they share. A view change, a
//: sort, a search keystroke, a filter and a change of bucket all land here, and
//: none of them fetches anything (TIMELINE_PLAN decision 2).
function paintTimeline() {
  const rows = timelineVisibleRows();
  const table = timelineViewMode() === "table";
  const nothingLoaded = timelineRows.length === 0;
  $("timeline-empty").classList.toggle("hidden", !nothingLoaded);
  $("timeline-no-match").classList.toggle("hidden", nothingLoaded || rows.length > 0);
  $("timeline-scroll").classList.toggle("hidden", rows.length === 0);
  $("timeline-feed").classList.toggle("hidden", table);
  $("timeline-table").classList.toggle("hidden", !table);
  // Selecting rows is the table's affordance: the feed has no tick boxes, and
  // offering the mode where it cannot be used is a control that does nothing.
  $("timeline-select-btn").classList.toggle("hidden", !table);
  syncTimelineSelectUi();
  if (table) paintTimelineTable(rows);
  else paintTimelineFeed(rows);
}

function paintTimelineFeed(rows) {
  const feed = $("timeline-feed");
  const scale = timelineResolvedScale(timelineRows.length);
  const density = TIMELINE_DENSITY[scale];
  feed.dataset.scale = scale;
  feed.dataset.density = density;
  feed.replaceChildren();

  // Buckets in the order the rows are in, so the grouping is one pass and the
  // feed's order is the array's order: the two cannot drift.
  const buckets = [];
  let current = null;
  for (const row of rows) {
    const key = timelineBucketKey(row.when, scale);
    if (!current || current.key !== key) {
      current = { key, rows: [] };
      buckets.push(current);
    }
    current.rows.push(row);
  }

  const unit = { day: "day", week: "week", month: "month", year: "year" }[scale];
  const filtered = rows.length !== timelineRows.length;
  $("timeline-count").textContent = rows.length
    ? `${filtered ? `${rows.length} of ${timelineRows.length}` : rows.length} note${
        rows.length === 1 ? "" : "s"
      } · ${buckets.length} ${unit}${buckets.length === 1 ? "" : "s"}`
    : "";

  const fragment = document.createDocumentFragment();
  for (const bucket of buckets) {
    const section = document.createElement("section");
    section.className = "timeline-bucket";
    section.dataset.bucket = bucket.key;
    const head = document.createElement("h3");
    head.className = "timeline-bucket-head";
    const label = document.createElement("span");
    label.className = "timeline-bucket-label";
    label.textContent = timelineBucketLabel(bucket.key, scale);
    const count = document.createElement("span");
    count.className = "muted timeline-bucket-count";
    count.textContent = `${bucket.rows.length}`;
    head.append(label, count);
    const list = document.createElement("ul");
    list.className = "timeline-rows";
    for (const row of bucket.rows) list.appendChild(timelineRowElement(row, density));
    section.append(head, list);
    fragment.appendChild(section);
  }
  feed.appendChild(fragment);
  applyTimelineRowTabOrder();
}

// One Tab stop for the feed, kept on the row the reader was on. A repaint
// happens on every keystroke in the search box, and resetting the stop to the
// top of the feed each time takes the focus away mid-typing: the same reason
// `applyEntryListTabOrder` keeps the Notes list's stop where it was.
function applyTimelineRowTabOrder() {
  // Whichever view is showing: `.timeline-row` is the class both a feed row
  // and a table row wear, so the keyboard behaves the same in both.
  const rows = [...$("timeline-scroll").querySelectorAll(".timeline-row")];
  const current = document.activeElement;
  const keepId = rows.some((row) => row === current) ? current.dataset.id : null;
  for (const row of rows) {
    row.tabIndex = keepId ? (row.dataset.id === keepId ? 0 : -1) : -1;
  }
  if (!keepId && rows.length) rows[0].tabIndex = 0;
}

// A row. The order you read it in: what kind of thing this is and whether it
// is sitting on a date it only talks about, then what it is called, then the
// line under it, then the facts (category, tags) and the time.
function timelineRowElement(row, density) {
  const li = document.createElement("li");
  li.className = "timeline-row";
  li.dataset.id = row.id;
  li.dataset.kind = row.kind;
  if (row.placedBy === "mentioned") li.dataset.placed = "mentioned";
  if (row.pinned) li.dataset.pinned = "1";
  //: **Reachable by keyboard, on the app's own recipe for a list.** The SVG
  //: view had 0 focusable notes; the Notes list has a *roving* tab stop
  //: (`applyEntryListTabOrder`): one row in the page's Tab order, arrows to
  //: move between rows. Forty-eight Tab stops in one feed would be the other
  //: failure, and it is not what the rest of the app does. `aria-expanded`
  //: says what Enter will do here.
  li.tabIndex = -1;
  li.setAttribute("aria-expanded", "false");

  const mark = document.createElement("span");
  mark.className = "timeline-row-mark";
  mark.setAttribute("aria-hidden", "true");
  const glyph = document.createElement("i");
  //: The kind is carried by the glyph, and the *placement* by the clock: a
  //: note plotted on a Friday it mentions is a different fact from one
  //: plotted on the day it was typed, and the old view said so only in a
  //: tooltip. Colour is deliberately not the signal here (decision 10 asks
  //: for category tokens, and this app has none: the Library's chips are
  //: accent-and-surface, not one hue per category), so the marker takes its
  //: colour from `--accent` or `--ink-soft` and the icon does the work.
  glyph.className =
    row.kind === "board"
      ? "ph ph-tree-structure"
      : row.placedBy === "mentioned"
        ? "ph ph-clock-countdown"
        : "ph ph-note";
  mark.appendChild(glyph);

  const main = document.createElement("span");
  main.className = "timeline-row-main";
  const title = document.createElement("span");
  title.className = "timeline-row-title";
  title.textContent = row.title;
  // One native tooltip for the full title, because the ellipsis is the only
  // other escape hatch and the text is already plain.
  title.title = row.title;
  main.appendChild(title);
  if (density === "full" && row.snippet) {
    const snippet = document.createElement("span");
    snippet.className = "timeline-row-snippet";
    snippet.textContent = row.snippet;
    main.appendChild(snippet);
  }

  const meta = document.createElement("span");
  meta.className = "timeline-row-meta";
  if (density !== "dense") {
    // The note row's own chips (`chip()`), not a second chip recipe for the
    // same facts: a tag should look the same here as in the Notes list.
    if (row.category) meta.appendChild(chip(row.category));
    for (const tag of row.tags.slice(0, density === "full" ? 3 : 2)) {
      meta.appendChild(chip(tag, "tag"));
    }
  }
  const when = document.createElement("time");
  when.className = "timeline-row-when";
  when.dateTime = row.whenIso;
  // A day's rows all share their date with the header above them, so the row
  // shows the time; any longer bucket shows the date, which is the thing the
  // header no longer says.
  when.textContent =
    density === "full"
      ? row.when.toLocaleTimeString(undefined, { hour: "numeric", minute: "2-digit" })
      : row.when.toLocaleDateString(undefined, { day: "numeric", month: "short" });
  when.title =
    row.placedBy === "mentioned"
      ? `“${row.phrase}” in this note meant ${shortDate(row.whenIso)}. Written ${shortDate(row.writtenAt)}.`
      : `Written ${new Date(row.writtenAt).toLocaleString()}`;
  meta.appendChild(when);

  li.append(mark, main, meta);

  // A row that continues another says so and goes there (decision 5's one
  // surviving thread affordance). Only where there is room to say it.
  if (density === "full" && row.parentId) {
    const parent = timelineById.get(row.parentId);
    if (parent) {
      const link = document.createElement("button");
      link.type = "button";
      link.className = "ghost small timeline-row-thread";
      setLabel(link, `ph:arrow-bend-up-left ${parent.title}`);
      link.title = `Continues “${parent.title}”`;
      link.addEventListener("click", (event) => {
        event.stopPropagation();
        focusTimelineRow(parent.id);
      });
      main.appendChild(link);
    }
  }

  li.addEventListener("click", (event) => {
    // The same "don't swallow a click meant for something else" guard the
    // Notes list's own row handler uses.
    if (event.target.closest("a, button, input, textarea, .chip, img")) return;
    if (window.getSelection()?.toString()) return; // a text selection, not a click
    toggleTimelineRow(li, row);
  });
  return li;
}

// Focus, and scroll into view without walking every scrolling ancestor:
// `scrollIntoView` takes the page with it (DESIGN.md's rule for a list that
// says where you are), and the feed is a box inside a card.
function focusTimelineRow(id) {
  const row = $("timeline-scroll").querySelector(`.timeline-row[data-id="${id}"]`);
  if (!row) return;
  const box = $("timeline-scroll");
  const offset = row.getBoundingClientRect().top - box.getBoundingClientRect().top;
  box.scrollTop += offset - box.clientHeight / 3;
  for (const other of $("timeline-scroll").querySelectorAll(".timeline-row")) other.tabIndex = -1;
  row.tabIndex = 0;
  row.focus();
}

//: **Open in place**, which is what replaced the popup (decision 8). The popup
//: was positioned by hand against two different offset parents, clamped
//: itself, re-placed itself on every image that loaded, and could only ever
//: show one note: the row opens underneath itself instead, stays where the
//: reader's eye already is, and keeps its place in the keyboard order.
//:
//: One at a time, the same rule the app's popovers follow, so the feed never
//: becomes a wall of open notes.
//:
//: TIMELINE_PLAN decision 8 names "the app's split panel (the same one Notes
//: uses)". There is no such panel: Notes opens a note by expanding the row it
//: is already in (`expandedRows`, `entryItem`). This is that affordance, built
//: on the same idea, and the plan's wording is the thing that is out of date.
function toggleTimelineRow(el, row) {
  if (el.getAttribute("aria-expanded") === "true") {
    closeTimelineRow(el);
    return;
  }
  if (timelineOpenId !== null) {
    const open = $("timeline-scroll").querySelector(
      `.timeline-row[data-id="${timelineOpenId}"][aria-expanded="true"]`
    );
    if (open) closeTimelineRow(open);
  }
  timelineOpenId = row.id;
  el.setAttribute("aria-expanded", "true");
  // A table row cannot hold a block: its detail is a row of its own with one
  // cell across every column (`openTimelineTableDetail`). Everything inside
  // that cell is what the feed builds, from the same function.
  if (el.tagName === "TR") {
    openTimelineTableDetail(el, row);
    return;
  }
  const detail = document.createElement("div");
  detail.className = "timeline-row-detail";
  el.appendChild(detail);
  openTimelineRowDetail(detail, row);
}

function closeTimelineRow(el) {
  el.setAttribute("aria-expanded", "false");
  if (el.tagName === "TR") {
    const next = el.nextElementSibling;
    if (next && next.classList.contains("timeline-detail-row")) next.remove();
  } else {
    el.querySelector(".timeline-row-detail")?.remove();
  }
  if (String(timelineOpenId) === el.dataset.id) timelineOpenId = null;
}

async function openTimelineRowDetail(detail, row) {
  const actions = document.createElement("div");
  actions.className = "row timeline-row-actions";

  if (row.kind === "board") {
    // A map has no prose to render. Its own chip says what it is and how big
    // it is, which is what the Library and the dashboard show for one too.
    detail.append(mapChip(row.board, { interactive: false }));
    actions.appendChild(
      smallButton("ph:tree-structure Open this map", "Open this map on the whiteboard", () =>
        openWhiteboardBoard(row.board.id)
      )
    );
    detail.appendChild(actions);
    return;
  }

  const body = document.createElement("div");
  body.className = "timeline-row-body";
  body.textContent = "Loading…";
  const media = document.createElement("div");
  media.className = "timeline-row-media hidden";
  detail.append(body, media, actions);

  actions.appendChild(
    smallButton("ph:pencil-simple Open in editor", "Open this note in the Notes tab", () => {
      switchTab("notes");
      showNotesSection("browse");
      flashEntry(row.id);
    })
  );

  const entry = await apiJson(`/entries/${row.id}`).catch(() => null);
  // The row may have been closed, or the feed repainted, while this was in
  // flight; writing into a detached node would be invisible and confusing.
  if (!detail.isConnected) return;
  if (!entry) {
    body.textContent = "Couldn't load this note.";
    return;
  }
  body.replaceChildren();
  renderMarkdown(body, entry.content || "");
  renderTimelineRowMedia(entry, media);
}

//: **Everything attached, not only the pictures.** Reported twice against the
//: popup this moved out of: "a photo i attached to a note ... doesn't render"
//: and "files and attachments dont render in the timeline and popups". The
//: non-image half is `fileCard`, the same control the note cards, the chat
//: transcript and the widgets use, so a file looks the same wherever the app
//: shows it. Kept through the redesign on purpose: the popup went, the two
//: fixes it carried did not.
function renderTimelineRowMedia(entry, box) {
  box.replaceChildren();
  const all = entry.attachments || [];
  box.classList.toggle("hidden", all.length === 0);
  if (!all.length) return;
  const images = all.filter((a) => a.is_image);
  for (const attachment of all.filter((a) => !a.is_image)) {
    //: `url` is what every other file surface is given; attachments carry
    //: theirs as `/files/{id}` when the row does not spell one out.
    box.appendChild(
      fileCard(attachment.filename || attachment.name || "", attachment.url || `/files/${attachment.id}`)
    );
  }
  for (const attachment of images) {
    const img = document.createElement("img");
    img.className = "timeline-row-thumb";
    img.alt = attachment.filename;
    img.title = `${attachment.filename}: click to view full size`;
    attachmentObjectUrl(attachment)
      .then((url) => {
        img.src = url;
      })
      .catch(() => img.remove());
    img.addEventListener("click", () => {
      openLightbox(
        images.map((a) => ({ filename: a.filename, getUrl: () => attachmentObjectUrl(a) })),
        images.indexOf(attachment)
      );
    });
    box.appendChild(img);
  }
}

//: The keys are the app's (TIMELINE_PLAN §6): arrows walk the rows in document
//: order, Enter and Space open one in place, Escape closes it. Delegated to the
//: feed rather than bound per row, because a repaint builds every row again and
//: a listener per row is a listener per row per repaint.
//:
//: Guarded on the row itself being the target: a chip inside a row is its own
//: `role="button"` with its own Enter, and an arrow pressed inside one should
//: not steal the key from it.
$("timeline-scroll").addEventListener("keydown", (event) => {
  const row = event.target.closest?.(".timeline-row");
  if (!row || event.target !== row) return;
  const rows = [...$("timeline-scroll").querySelectorAll(".timeline-row")];
  const at = rows.indexOf(row);
  const go = (index) => {
    const next = rows[Math.max(0, Math.min(rows.length - 1, index))];
    if (next) {
      event.preventDefault();
      focusTimelineRow(next.dataset.id);
    }
  };
  if (event.key === "ArrowDown") return go(at + 1);
  if (event.key === "ArrowUp") return go(at - 1);
  if (event.key === "Home") return go(0);
  if (event.key === "End") return go(rows.length - 1);
  if (event.key === " " && selectMode && row.tagName === "TR") {
    event.preventDefault();
    const model = timelineById.get(Number(row.dataset.id));
    if (model) setTimelineRowSelected(row, model, !selectedIds.has(model.id));
    return;
  }
  if (event.key === "Enter" || event.key === " ") {
    event.preventDefault();
    const model = timelineById.get(Number(row.dataset.id));
    if (model) toggleTimelineRow(row, model);
    return;
  }
  if (event.key === "Escape" && row.getAttribute("aria-expanded") === "true") {
    event.preventDefault();
    closeTimelineRow(row);
  }
});
// The preview is the raw note text sliced to 120 chars server-side (§37J): 
// `**bold**` and `# a heading` showed their literal punctuation in the one
// place they're smallest and most cramped to read. Full `renderMarkdown`
// builds block-level DOM (headings, code blocks with a copy button) that
// doesn't make sense clamped to two lines inside a button, so this strips the
// syntax to plain words instead. The slice can land mid-token, `**bold te`
// with no closing `**`, so every rule here deletes delimiter characters
// outright rather than matching opening/closing pairs, which handles a
// truncated run the same way as a complete one.
function stripMarkdownPreview(text) {
  return text
    .replace(/^#{1,6}\s+/gm, "")
    .replace(/^>\s?/gm, "")
    .replace(/^[-*+]\s+/gm, "")
    .replace(/^\d+\.\s+/gm, "")
    .replace(/`{1,3}/g, "")
    .replace(/\*\*/g, "")
    .replace(/__/g, "")
    .replace(/~~/g, "")
    .replace(/[*_](?=\S)|(?<=\S)[*_]/g, "")
    .replace(/!?\[([^\]]*)\]\([^)]*\)?/g, "$1");
}

// A date with no time, in the reader's locale. Used where a full timestamp is
// noise: a card header, a tooltip's second line.
function shortDate(iso) {
  const date = parseServerTime(iso) || new Date(iso);
  return Number.isNaN(date.getTime())
    ? ""
    : date.toLocaleDateString(undefined, { day: "numeric", month: "short", year: "numeric" });
}

//: **The table** (TIMELINE_PLAN Phase 2, decision 6). The same rows the feed
//: draws, in the shape you want when the question is "which of these" rather
//: than "what happened then": every column at once, sortable, and several rows
//: at a time. It is a real `<table>`, so the columns are a header row a screen
//: reader announces, the sort lives on the header cells where a person looks
//: for it, and `aria-sort` says which way round it is.
//:
//: Switching views is a repaint of the array, never a fetch: the two views
//: cannot disagree about what a search matched, because they read the same
//: `timelineVisibleRows()`.
function timelineViewMode() {
  return localStorage.getItem("timeline-view") === "table" ? "table" : "feed";
}

// The columns, in the order decision 6 sets them out, with how each one sorts.
// `kind` and the counts are the reason this is a table at all: they are facts
// about a note that a feed row has no room for.
const TIMELINE_COLUMNS = [
  { key: "when", label: "Date", type: "time" },
  { key: "title", label: "Title", type: "text" },
  { key: "kind", label: "Kind", type: "text" },
  { key: "category", label: "Category", type: "text" },
  { key: "space", label: "Space", type: "text" },
  { key: "tags", label: "Tags", type: "text" },
  { key: "words", label: "Words", type: "number" },
  { key: "links", label: "Links", type: "number" },
];

// Newest first is the timeline's own order, so it is the table's default too.
let timelineSort = { key: "when", dir: "desc" };

function timelineSortValue(row, key) {
  if (key === "when") return row.when.getTime();
  if (key === "tags") return row.tags.join(", ");
  if (key === "kind") return row.kind === "board" ? "Map" : "Note";
  if (key === "words" || key === "links") return row[key];
  return row[key] || "";
}

function timelineSortedRows(rows) {
  const { key, dir } = timelineSort;
  const column = TIMELINE_COLUMNS.find((c) => c.key === key) || TIMELINE_COLUMNS[0];
  const sign = dir === "asc" ? 1 : -1;
  return [...rows].sort((a, b) => {
    const left = timelineSortValue(a, key);
    const right = timelineSortValue(b, key);
    // A column the endpoint has not filled in yet (`words` and `links` are
    // null on an old payload) sorts last in both directions rather than
    // pretending to be zero, which would put every unknown note at one end and
    // read as a fact.
    if (left === null || left === undefined) return 1;
    if (right === null || right === undefined) return -1;
    if (column.type === "text") return sign * String(left).localeCompare(String(right));
    return sign * (left - right);
  });
}

function paintTimelineTable(rows) {
  const body = $("timeline-table-body");
  body.replaceChildren();
  const filtered = rows.length !== timelineRows.length;
  const column = TIMELINE_COLUMNS.find((c) => c.key === timelineSort.key);
  $("timeline-count").textContent = rows.length
    ? `${filtered ? `${rows.length} of ${timelineRows.length}` : rows.length} note${
        rows.length === 1 ? "" : "s"
      } · by ${(column ? column.label : "date").toLowerCase()}`
    : "";
  const sorted = timelineSortedRows(rows);
  const fragment = document.createDocumentFragment();
  for (const row of sorted) fragment.appendChild(timelineTableRow(row));
  body.appendChild(fragment);

  // The head says what it is sorted by, to the eye and to a screen reader.
  for (const button of $("timeline-table-head").querySelectorAll(".timeline-sort")) {
    const on = button.dataset.sort === timelineSort.key;
    button.classList.toggle("is-on", on);
    button.closest("th").setAttribute(
      "aria-sort",
      on ? (timelineSort.dir === "asc" ? "ascending" : "descending") : "none"
    );
  }
  for (const cell of document.querySelectorAll(".timeline-col-select")) {
    cell.classList.toggle("hidden", !selectMode);
  }
  applyTimelineRowTabOrder();
}

function timelineTableRow(row) {
  const tr = document.createElement("tr");
  tr.className = "timeline-row timeline-trow";
  tr.dataset.id = row.id;
  tr.dataset.kind = row.kind;
  if (row.placedBy === "mentioned") tr.dataset.placed = "mentioned";
  tr.tabIndex = -1;
  tr.setAttribute("aria-expanded", "false");

  // The tick box only exists while the mode is on, the way the Notes list's
  // does: a column of empty boxes down a table nobody is selecting in is a
  // column of noise.
  const select = document.createElement("td");
  select.className = `timeline-col-select${selectMode ? "" : " hidden"}`;
  if (selectMode) {
    const check = document.createElement("input");
    check.type = "checkbox";
    check.className = "select-check";
    check.checked = selectedIds.has(row.id);
    check.setAttribute("aria-label", `Select ${row.title}`);
    check.addEventListener("change", () => {
      setTimelineRowSelected(tr, row, check.checked);
    });
    select.appendChild(check);
  }
  tr.appendChild(select);

  const when = document.createElement("td");
  const time = document.createElement("time");
  time.dateTime = row.whenIso;
  time.textContent = shortDate(row.whenIso);
  time.title =
    row.placedBy === "mentioned"
      ? `“${row.phrase}” in this note meant ${shortDate(row.whenIso)}. Written ${shortDate(row.writtenAt)}.`
      : `Written ${new Date(row.writtenAt).toLocaleString()}`;
  when.appendChild(time);
  tr.appendChild(when);

  const title = document.createElement("td");
  title.className = "timeline-col-title";
  title.textContent = row.title;
  title.title = row.title;
  tr.appendChild(title);

  const kind = document.createElement("td");
  kind.className = "timeline-col-wide";
  kind.textContent = row.kind === "board" ? "Map" : "Note";
  tr.appendChild(kind);

  const category = document.createElement("td");
  category.className = "timeline-col-wide";
  category.textContent = row.category || "";
  tr.appendChild(category);

  const space = document.createElement("td");
  space.className = "timeline-col-wide";
  space.textContent = row.space || "";
  tr.appendChild(space);

  const tags = document.createElement("td");
  tags.className = "timeline-col-wide timeline-col-tags";
  tags.textContent = row.tags.join(", ");
  tags.title = row.tags.join(", ");
  tr.appendChild(tags);

  for (const key of ["words", "links"]) {
    const cell = document.createElement("td");
    cell.className = "timeline-col-wide timeline-col-number";
    // An em dash is not allowed and a 0 would be a claim: a blank cell with a
    // title is what "the endpoint did not say" looks like.
    cell.textContent = row[key] === null || row[key] === undefined ? "" : String(row[key]);
    if (row[key] === null || row[key] === undefined) cell.title = "Not known for this note";
    tr.appendChild(cell);
  }

  tr.addEventListener("click", (event) => {
    if (event.target.closest("a, button, input, textarea, .chip, img")) return;
    if (window.getSelection()?.toString()) return;
    if (selectMode) {
      setTimelineRowSelected(tr, row, !selectedIds.has(row.id));
      return;
    }
    toggleTimelineRow(tr, row);
  });
  if (selectedIds.has(row.id)) tr.setAttribute("aria-selected", "true");
  return tr;
}

function setTimelineRowSelected(tr, row, on) {
  if (on) selectedIds.add(row.id);
  else selectedIds.delete(row.id);
  tr.setAttribute("aria-selected", on ? "true" : "false");
  const check = tr.querySelector(".select-check");
  if (check) check.checked = on;
  updateBatchCount();
}

// Opening a row in a table is a row of its own: a `<td>` spanning every
// column, under the row it belongs to, which is the table's version of the
// feed's detail box and uses the same builder.
function openTimelineTableDetail(tr, row) {
  const holder = document.createElement("tr");
  holder.className = "timeline-detail-row";
  const cell = document.createElement("td");
  cell.colSpan = TIMELINE_COLUMNS.length + 1;
  const detail = document.createElement("div");
  detail.className = "timeline-row-detail";
  cell.appendChild(detail);
  holder.appendChild(cell);
  tr.after(holder);
  openTimelineRowDetail(detail, row);
}

//: The Select mode, in the Options menu because the row is at its
//: seven-control ceiling. It is the app's one selection mode, not a second
//: one: `enterSelectMode` clears the set, fills both bars and repaints both
//: surfaces.
function syncTimelineSelectUi() {
  const table = timelineViewMode() === "table";
  $("timeline-batch-bar").classList.toggle("hidden", !(selectMode && table));
  $("timeline-select-btn").classList.toggle("is-on", selectMode);
  $("timeline-select-btn").setAttribute("aria-pressed", String(selectMode));
}

$("timeline-select-btn").addEventListener("click", () => {
  if (selectMode) exitSelectMode();
  else enterSelectMode();
});

$("timeline-batch-tag").addEventListener("click", batchTag);
$("timeline-batch-delete").addEventListener("click", batchDelete);
$("timeline-batch-done").addEventListener("click", exitSelectMode);

//: Sorting is a click on the column head, and clicking the column you are
//: already sorted by turns it around. Time starts newest first and text starts
//: A to Z, because those are the two orders a person means by "sort by this".
$("timeline-table-head").addEventListener("click", (event) => {
  const button = event.target.closest(".timeline-sort");
  if (!button) return;
  const key = button.dataset.sort;
  const column = TIMELINE_COLUMNS.find((c) => c.key === key);
  if (!column) return;
  timelineSort =
    timelineSort.key === key
      ? { key, dir: timelineSort.dir === "asc" ? "desc" : "asc" }
      : { key, dir: column.type === "text" ? "asc" : "desc" };
  paintTimeline();
});

$("timeline-view-seg").addEventListener("click", (event) => {
  const button = event.target.closest("[data-timeline-view]");
  if (!button) return;
  const mode = button.dataset.timelineView;
  if (mode === timelineViewMode()) return;
  localStorage.setItem("timeline-view", mode);
  syncTimelineViewSeg();
  // A repaint, not a reload: `timelineRows` is already in memory and both
  // views render from it.
  paintTimeline();
});

function syncTimelineViewSeg() {
  const mode = timelineViewMode();
  for (const button of $("timeline-view-seg").querySelectorAll("[data-timeline-view]")) {
    const on = button.dataset.timelineView === mode;
    button.classList.toggle("active", on);
    button.setAttribute("aria-pressed", String(on));
  }
}

//: Scale is a repaint, not a request (see `timelineBucketKey`), and it is
//: remembered the way the graph's layout is: which bucket suits a notebook is
//: a property of the notebook rather than of one visit. "Auto" is stored like
//: any other choice, so a notebook that grows past the day threshold re-cuts
//: its own headers without anyone touching the control.
$("timeline-scale").addEventListener("change", (event) => {
  localStorage.setItem("timeline-scale", event.target.value);
  paintTimeline();
});

//: Grouping decides what the band filter offers, so it rebuilds the options
//: and repaints. It does not refetch either: every row already carries its
//: category, its tags and the note it continues.
$("timeline-group").addEventListener("change", () => {
  timelineFilter = null;
  fillTimelineBandOptions();
  paintTimeline();
});

//: **The bands are a filter now, not lanes** (TIMELINE_PLAN decision 5). As
//: lanes they were mostly empty: eight rows of whitespace with a handful of
//: dots in each. The same choice is worth more as "show me only this", which
//: is what the rest of the app does with a category.
$("timeline-band").addEventListener("change", (event) => {
  timelineFilter = event.target.value || null;
  syncTimelineFilterChip();
  paintTimeline();
});

$("timeline-filter-clear").addEventListener("click", () => {
  timelineFilter = null;
  $("timeline-band").value = "";
  syncTimelineFilterChip();
  paintTimeline();
});

const timelineDays = $("timeline-days");
if (timelineDays) {
  timelineDays.addEventListener("change", () => {
    const isCustom = timelineDays.value === "custom";
    const customRangeEl = $("timeline-custom-range");
    if (customRangeEl) {
      customRangeEl.classList.toggle("hidden", !isCustom);
    }
    // A range is the one control that has to go back to the server.
    if (!isCustom || ($("timeline-start-date").value && $("timeline-end-date").value)) {
      renderTimeline();
    }
  });
}

$("timeline-start-date")?.addEventListener("change", () => {
  if ($("timeline-end-date").value) renderTimeline();
});
$("timeline-end-date")?.addEventListener("change", () => {
  if ($("timeline-start-date").value) renderTimeline();
});

//: Today is at the top of a newest-first feed, so this is a scroll rather than
//: a search. It still looks the bucket up by key rather than assuming the
//: first section is today's: a notebook with nothing written today should land
//: on the newest day it has, not claim that day is today.
$("timeline-jump-today")?.addEventListener("click", () => {
  const feed = $("timeline-feed");
  const today = timelineBucketKey(new Date(), feed.dataset.scale || "day");
  const section =
    feed.querySelector(`.timeline-bucket[data-bucket="${today}"]`) || feed.firstElementChild;
  if (!section) return;
  const box = $("timeline-scroll");
  box.scrollTop += section.getBoundingClientRect().top - box.getBoundingClientRect().top;
  section.querySelector(".timeline-row")?.focus();
});

//: **Search filters, it does not dim** (decision 2). Dimming left every row in
//: place: the same scroll distance, the same Ctrl+F hits, 48 rows to read past
//: to find the two that matched. 150ms is the debounce the Notes, Library and
//: Graph boxes use, and a repaint costs no request.
let timelineSearchDebounceTimeout;
$("timeline-search").addEventListener("input", () => {
  clearTimeout(timelineSearchDebounceTimeout);
  timelineSearchDebounceTimeout = setTimeout(paintTimeline, 150);
});

$("timeline-clear-search")?.addEventListener("click", () => {
  $("timeline-search").value = "";
  paintTimeline();
  $("timeline-search").focus();
});

// Layout picker (§9). Stored, because which shape suits a notebook is a
// property of the notebook rather than of one visit.
$("graph-layout").addEventListener("change", (event) => {
  localStorage.setItem("graph-layout", event.target.value);
  setGraphPhysicsEnabled(event.target.value);
  // A different layout is a different shape (a radial ring is nothing like
  // a force-directed cloud): re-frame for it, unlike the filter/slider
  // changes that intentionally leave the camera alone.
  graphAutoFitDone = false;
  renderGraph();
});

// --- Notes sub-tabs ---------------------------------------------------------------
// Four full-height cards stacked on one page meant scrolling past three forms
// you weren't using to reach your notes (roadmap §10). Folding each card
// helped, but it was mitigation: you still had four things to manage.
//
// The per-card collapse chevrons are retired here rather than kept alongside.
// Two mechanisms for hiding the same card is exactly the trap that had the
// Notes sections not collapsing at all a few sessions ago, one implementation
// quietly undoing the other.

const NOTES_SECTIONS = ["browse", "capture", "writing-room", "ask"];
const NOTES_SECTION_STORE = "notesSection";

// --- a new session starts at the front of every tab ----------------------------
//
// Reported directly: "Ive had times where I log into the app, click on the
// notes tab, and the tab is selected on 'Write with AI' instead of 'Your
// Notes' because that must have been what I was on last."
//
// **Which sub-tab you are on is not a preference; it is where you happen to
// be standing.** Reopening on the last *tab* is useful, you were working on
// something. Reopening three levels in, on a sub-tab you visited once a week
// ago, is not: it reads as the app being in a state you did not put it in,
// and the deeper the restore the more true that is. So a new session lands on
// each tab's front page.
//
// `sessionStorage`, not a timestamp or a login hook, and the distinction it
// draws is exactly the right one: it survives a reload (F5, or the desktop
// window reloading itself after an update) and is cleared when the tab or the
// app window closes. So "I refreshed" keeps your place and "I started the app
// again" does not.
//
// Only navigation is reset. `library-view`'s grid/list, the timeline's own
// bucket size, reminders' list/calendar and the document editor's Live/Source
// choice are display preferences someone deliberately set, and clearing those
// would be a different, and unwanted, change.
const SESSION_STARTED_KEY = "mm-session-started";
const NAVIGATION_KEYS = [NOTES_SECTION_STORE];

function resetNavigationForNewSession() {
  try {
    if (sessionStorage.getItem(SESSION_STARTED_KEY)) return false;
    sessionStorage.setItem(SESSION_STARTED_KEY, "1");
  } catch {
    // Storage can throw outright (a private window, a shell with site data
    // blocked). Not resetting is the safe answer, it leaves the previous
    // behaviour rather than resetting on every single navigation.
    return false;
  }
  for (const key of NAVIGATION_KEYS) localStorage.removeItem(key);
  return true;
}

// Run at load, before anything can have navigated. One-shot per session: a
// reload inside the same session finds the marker and leaves your place
// alone, which is the distinction sessionStorage draws for free.
resetNavigationForNewSession();

function resetNavigationToDefaults() {
  for (const key of NAVIGATION_KEYS) localStorage.removeItem(key);
  // The Library's switcher keeps its state in the DOM (which button carries
  // `.active`), not in storage, so clearing a key cannot reach it. Clicking
  // its default button reuses the real handler, which also shows the right
  // section, stops the gallery poll and lands the whiteboard view correctly.
  // A second copy of that logic here is exactly the shape this codebase keeps
  // getting bitten by.
  const allTab = document.querySelector(
    '#library-subtabs button[data-target="library-view-documents"]'
  );
  if (allTab && !allTab.classList.contains("active")) allTab.click();
  // If the Notes strip is already built, put it back on its front page now;
  // on a cold load it has not been built yet and will read the cleared key.
  if (typeof showNotesSection === "function" && document.getElementById("notes-subtabs")?.dataset.ready) {
    showNotesSection("browse");
  }
}

function activeNotesSection() {
  const saved = localStorage.getItem(NOTES_SECTION_STORE);
  return NOTES_SECTIONS.includes(saved) ? saved : "browse";
}

function showNotesSection(name, { focus = false } = {}) {
  // Measurements only mean anything once the section is on screen.
  if (name === "browse") setTimeout(settleNoteClamps, 0);
  // The picker lists documents that may have been created since this page
  // loaded: a stale list is how "add to document" ends up offering nothing.
  if (name === "capture") loadCaptureDocuments();
  const wanted = NOTES_SECTIONS.includes(name) ? name : "browse";
  // A sub-tab move is a navigation, so it becomes a history step too. Recorded
  // against the Notes tab specifically because that is the tab these sections
  // belong to: switchTab records its own entry when the *tab* changes, and
  // recordTabVisit ignores a repeat of where you already are, so arriving at
  // Notes and then landing on a section does not produce two entries.
  recordTabVisit("notes", wanted);
  for (const id of NOTES_SECTIONS) {
    const card = document.getElementById(id);
    if (card) card.classList.toggle("hidden", id !== wanted);
  }
  for (const button of document.querySelectorAll("#notes-subtabs button")) {
    const active = button.dataset.section === wanted;
    button.classList.toggle("active", active);
    button.setAttribute("aria-selected", String(active));
    // Roving tabindex: the strip is one tab stop, arrows move within it.
    button.tabIndex = active ? 0 : -1;
    if (active && focus) button.focus();
  }
  localStorage.setItem(NOTES_SECTION_STORE, wanted);
  // A textarea measured while its section is display:none reports
  // scrollHeight 0, so autoGrow collapsed the capture box to its minimum and
  // it only sprang open once clicked (user-reported). Re-measure now that the
  // section is actually visible.
  for (const box of document.querySelectorAll("textarea.autogrow")) {
    if (box.offsetParent !== null) autoGrow(box);
  }
}

function initNotesSubtabs() {
  const strip = document.getElementById("notes-subtabs");
  if (!strip || strip.dataset.ready) return;
  strip.dataset.ready = "1";
  strip.addEventListener("click", (event) => {
    const button = event.target.closest("button[data-section]");
    if (button) showNotesSection(button.dataset.section);
  });
  strip.addEventListener("keydown", (event) => {
    const step = { ArrowRight: 1, ArrowLeft: -1 }[event.key];
    if (!step) return;
    event.preventDefault();
    const order = [...strip.querySelectorAll("button[data-section]")].map(
      (b) => b.dataset.section
    );
    const index = order.indexOf(activeNotesSection());
    showNotesSection(order[(index + step + order.length) % order.length], {
      focus: true,
    });
  });
  showNotesSection(activeNotesSection());
}

// The Notes tab's bin, activity and tag panels are gone (§36G).
//
// Each of them had a second implementation in the Library, the same list,
// the same controls: and the bin's two could disagree about what was in it,
// because each fetched its own. Three surfaces, three render functions, three
// blocks of markup and a `showPanel` that hid whichever two you were not
// looking at, all replaced by a filter chip on a screen built for exactly
// this. The last thing the panel could do that the Library could not was show
// a binned note in full; `openBinnedNote` above is that, and it is the reason
// this could finally go.
//
// This is the first surface this project has *removed* rather than added.

// The element that actually scrolls (§36A). The window no longer does, the
// visible .tab-page is its own scroll container, so the scrollbar starts below
// the top bar instead of running behind it.
function scrollingPage() {
  return document.querySelector(".tab-page:not(.hidden)");
}

// Honour "prefers reduced motion", a long smooth scroll is exactly the kind
// of movement that setting exists to stop.
function scrollPageToTop() {
  const smooth = !window.matchMedia("(prefers-reduced-motion: reduce)").matches;
  scrollingPage()?.scrollTo({ top: 0, behavior: smooth ? "smooth" : "auto" });
}

// --- back-to-top button -----------------------------------------------------------
// Shown on every tab except the graph, where the page itself doesn't scroll
// and the button would just sit on top of the map.
//
// Chat, Notes and Library are special cases, not exclusions: `.tab-page`
// itself never scrolls on any of the three, each uses a flex column with a
// nested real scroll container instead (`#tab-chat`/`#tab-notes
// > .layout > main`, see 04-chat-dock-appearance.css; `#tab-library`'s
// active `.library-view-section`, see 07-whiteboard-misc.css), so a button
// watching `.tab-page.scrollTop` would see 0 forever and never show, and
// clicking it would scroll an element that never moves. Reported as "the
// back-to-top button doesn't appear in all places it should (like the
// Library)" twice: Notes was fixed first, but the *actual* top-level
// Library tab (Documents/AI Skills/Whiteboards/Image Gallery) turned out to
// have the identical shape and was still missing it. One lookup table, one
// target per tab, rather than a growing pile of hardcoded special cases.
//
// **Chat is excluded too, but for the opposite reason (INBOX 34).** This
// button used to flip into a "jump to the newest message" arrow there,
// reading the same distance-from-bottom `#chat-jump-latest` (the pill
// above the composer) already does. Reported and reproduced: both showed
// at once on a brand-new chat with nothing to scroll, because starting one
// clears `#chat-messages` without firing the scroll/resize event this
// button's own `update()` waits for, leaving whichever state the *previous*
// conversation left it in. Decision: one control in chat, the pill (it is
// already wired to `syncChatJumpLatest`, called right after that clear);
// this button simply never shows there any more rather than needing to be
// kept in sync with a second copy of the same "scrolled away" logic.
const NO_SCROLL_TOP_TABS = new Set(["graph", "chat"]);
const NESTED_SCROLL_TABS = {
  chat: () => chatMessagesEl(),
  notes: () => document.querySelector("#tab-notes .layout > main"),
  // The Whiteboards sub-view pans rather than scrolls (like Graph), so it
  // deliberately returns nothing here, scrollTopTargetEl() then falls
  // back to scrollingPage(), whose scrollTop is always 0 on this tab,
  // which is exactly what keeps the button correctly hidden there.
  library: () => {
    const visible = document.querySelector("#tab-library .library-view-section:not(.hidden)");
    return visible && visible.id !== "library-view-whiteboard" ? visible : null;
  },
};
let scrollTopUpdate = null;

function chatMessagesEl() {
  return document.getElementById("chat-messages");
}

function scrollTopTargetEl() {
  const tab = localStorage.getItem("activeTab") || "dashboard";
  return NESTED_SCROLL_TABS[tab]?.() || scrollingPage();
}

// A content panel can be narrower than the viewport and sit behind its own
// real scrollbar, which a fixed CSS `right` offset doesn't know to clear, 
// and the panel's own box can run taller than the viewport, which a fixed
// CSS `bottom` offset doesn't know to stay above. Reported, more than once
// and on more than one tab (first Library, then screenshotted on Notes'
// "Your notes" and "Ask" sub-tabs): the button overlapping the scrollbar and
// the content beside it, or sitting below the visible fold. Computed here
// instead of in CSS, from the *actual scroll target*'s live
// `getBoundingClientRect()`, the same one `scrollTopTargetEl()` already
// resolves per tab: for every tab but Chat (reparented into `.chat-dock`
// and positioned by its own CSS instead), clamped so the button can never
// end up outside the visible viewport no matter how tall the panel's box
// actually is.
function positionScrollTopForNested(button, tab) {
  if (tab === "chat") {
    // Reparented into .chat-dock by the MutationObserver below and
    // positioned by that container's own CSS instead, inline right/bottom
    // here would fight it rather than help it.
    button.style.right = "";
    button.style.bottom = "";
    return;
  }
  // Anchoring to the actual scrolling content panel, not the viewport,
  // for every tab: not just Library and Notes. A flat `right`/`bottom`
  // offset from the *window* edge is correct only when the panel happens to
  // reach that edge; the moment a real (non-overlay) scrollbar reserves
  // layout width the panel's own `getBoundingClientRect()` doesn't subtract
  // for, that flat offset lands the button sitting on top of the scrollbar
  // and the content beside it (reported, screenshotted: an up-arrow button
  // overlapping the scrollbar's own down-arrow and a line of note text on
  // Notes' "Your notes" and "Ask" sub-tabs): and every tab shares the same
  // scroll container shape (`scrollTopTargetEl()`), so the fix has to be
  // general rather than three more special cases in `NESTED_SCROLL_TABS`.
  const panel = scrollTopTargetEl();
  const rect = panel?.getBoundingClientRect();
  if (!panel || !rect) {
    button.style.right = "";
    button.style.bottom = "";
    return;
  }
  const margin = 24; // 1.5rem, matching every other tab's own offset

  // Real (non-overlay) scrollbars reserve layout width that
  // getBoundingClientRect() doesn't subtract for; measuring it live
  // (0 on this project's own sandbox and macOS, 15-17px on most
  // Windows/Linux setups) replaces what used to be a flat guessed
  // constant, wrong in both directions depending on platform.
  const scrollbarClearance = panel.offsetWidth - panel.clientWidth;

  // A right-side element the panel's own edge doesn't already account for, 
  // today only the AI Skills sidebar, sitting *inside* Library's own panel
  // rather than beside it. Notes' sidebar is on the *left*, so it never
  // needs this branch; most panels don't have one at all.
  const rightPanel = document.querySelector("#library-view-skills:not(.hidden) #skills-sidebar");
  if (rightPanel) {
    const rightPanelRect = rightPanel.getBoundingClientRect();
    button.style.right = `${Math.max(margin, window.innerWidth - rightPanelRect.left + margin + scrollbarClearance)}px`;
  } else {
    button.style.right = `${Math.max(margin, window.innerWidth - rect.right + margin + scrollbarClearance)}px`;
  }

  // **Bottom**: a panel shorter than the viewport must not leave the button
  // floating below its own content.
  button.style.bottom = `${Math.max(margin, window.innerHeight - Math.min(rect.bottom, window.innerHeight) + margin)}px`;
}

//: **The back-to-top button must never sit on top of a Save button.**
//: Reported with a screenshot of the capture form: the floating button
//: landed over the one irreversible action on the screen, so the control you
//: reached for was not the one you got.
//:
//: This is a geometric test rather than a bigger `bottom` offset, and that is
//: deliberate. The button is `position: fixed` at the bottom-right of the
//: viewport while a form's footer can be at any scroll position and any
//: width, so "raise it by 3rem" is a value that happens to work at the width
//: it was measured at and silently stops working at the next one. Asking, on
//: every scroll and resize, whether the two boxes actually intersect is the
//: only version of this that is a guarantee.
//:
//: Touching counts as covering: the clearance below is the same step the rest
//: of the app puts between two adjacent controls, because the point is that
//: the floating button and the form's Save must never read as one cluster.
//:
//: Only *primary* buttons count. A form footer also holds ghost buttons
//: (Discard, Undo, Extract notes), and hiding the back-to-top control every
//: time one of those drifted underneath would make it flicker in and out on
//: pages that have no problem at all.
const FORM_PRIMARY_SELECTOR = [
  "#capture",
  "#writing-room",
  "#ask",
  ".doc-ai-card",
  ".extract-card",
  ".modal-card",
]
  .map((scope) => `${scope} button:not(.ghost):not(.icon-only):not(.linklike)`)
  .join(", ");

//: `--space-3` is declared in rem and wrapped in the density multiplier, so
//: it cannot be read as a pixel count directly. Resolving it through a real
//: element is what makes the clearance track the density setting instead of
//: freezing at one multiplier's value.
function spacingPx(name, fallback) {
  const probe = document.createElement("div");
  probe.style.cssText = `position:absolute;visibility:hidden;width:var(${name})`;
  document.body.appendChild(probe);
  const px = probe.getBoundingClientRect().width;
  probe.remove();
  return px > 0 ? px : fallback;
}

function coversAFormPrimary(button) {
  const f = button.getBoundingClientRect();
  if (!f.width || !f.height) return false;
  const pad = spacingPx("--space-3", 8);
  for (const el of document.querySelectorAll(FORM_PRIMARY_SELECTOR)) {
    const s = el.getBoundingClientRect();
    if (!s.width || !s.height) continue;
    //: Off-screen footers cannot be covered, and skipping them keeps this to
    //: a handful of rect reads per scroll event.
    if (s.bottom < 0 || s.top > window.innerHeight) continue;
    const clear =
      f.right < s.left - pad ||
      f.left > s.right + pad ||
      f.bottom < s.top - pad ||
      f.top > s.bottom + pad;
    if (!clear) return true;
  }
  return false;
}

function initScrollTopButton() {
  const button = document.createElement("button");
  button.id = "scroll-top";
  button.className = "scroll-top";
  button.type = "button";
  button.textContent = "↑";
  button.title = "Back to top";
  button.setAttribute("aria-label", "Back to top");
  button.addEventListener("click", () => {
    const smooth = !window.matchMedia("(prefers-reduced-motion: reduce)").matches;
    const target = scrollTopTargetEl();
    //: **In a chat, the thing you have scrolled away from is the bottom.**
    //: Reported: *"the back to top button in the chat should be a back to
    //: bottom instead."* A transcript is written downwards and the newest
    //: message, the one being streamed, is the last one; sending a reader
    //: to the top sends them to the oldest question in the thread, which is
    //: the one place nobody scrolled up to look for.
    const toBottom = button.dataset.mode === "bottom";
    target?.scrollTo({
      top: toBottom ? target.scrollHeight : 0,
      behavior: smooth ? "smooth" : "auto",
    });
    // Send focus somewhere sensible rather than leaving it on a button that
    // is about to hide itself.
    if (toBottom) $("chat-input")?.focus();
    else document.querySelector(".tab-page:not(.hidden)")?.focus();
  });
  document.body.appendChild(button);

  const update = () => {
    const tab = localStorage.getItem("activeTab") || "dashboard";
    const target = scrollTopTargetEl();
    const scrollTop = target?.scrollTop || 0;
    //: Chat flips the button over: it appears when you have scrolled *up*
    //: away from the newest message, and it takes you back down. 200px rather
    //: than 400 because a chat pane is shorter than a page and one message
    //: scrolled past is already enough to lose the live one.
    const chat = tab === "chat";
    const fromBottom = target ? target.scrollHeight - target.clientHeight - scrollTop : 0;
    //: **The dashboard shows it sooner, and that is the report.** The owner:
    //: "also no back to top button appears on the dashboard??" Measured on a
    //: seeded profile at 1440x900 it does appear, but only past 400px, and
    //: the dashboard is the one page in the app whose *first* content sits at
    //: y=613: the hero, the start band and the stats strip are 600px of
    //: preamble before a single widget. So 400px of scrolling is barely one
    //: screen in, on the longest scan-page the app has, and the button that
    //: gets you back is still absent. 200px is chat's figure, for the same
    //: reason chat uses it: this pane is scrolled in short movements and one
    //: screen away is already lost.
    const show = chat
      ? fromBottom > 200
      : scrollTop > (tab === "dashboard" ? 200 : 400) && !NO_SCROLL_TOP_TABS.has(tab);
    button.dataset.mode = chat ? "bottom" : "top";
    button.textContent = chat ? "↓" : "↑";
    const label = chat ? "Jump to the newest message" : "Back to top";
    button.title = label;
    button.setAttribute("aria-label", label);
    const visible = show && !NO_SCROLL_TOP_TABS.has(tab) && !coversAFormPrimary(button);
    button.classList.toggle("visible", visible);
    //: INBOX 33: `--scroll-top-clearance` used to be unconditional
    //: `padding-bottom` on every scrolling list, so a short page (an empty
    //: Ask sub-tab, three notes on a fresh space) scrolled a hundred-odd
    //: pixels of nothing at its own bottom even though this button was
    //: nowhere near visible to need clearing. Read by 04-chat-dock-
    //: appearance.css and 07-whiteboard-misc.css, which now apply the
    //: clearance only while this class says the button is actually there
    //: to clear.
    document.body.classList.toggle("scroll-top-visible", visible);
    positionScrollTopForNested(button, tab);
  };
  // Capture, because scroll events do not bubble: the listener has to see them
  // on whichever .tab-page is currently the scroll container, and that changes
  // every time the user switches tab.
  document.addEventListener("scroll", update, { passive: true, capture: true });
  window.addEventListener("resize", update, { passive: true });
  update();
  return update;
}

const chatTabNode = document.getElementById("tab-chat");
if (chatTabNode) {
  new MutationObserver(() => {
    const btn = document.querySelector(".scroll-top");
    const dock = document.querySelector(".chat-dock");
    if (!btn || !dock) return;

    if (!chatTabNode.classList.contains("hidden")) {
      dock.appendChild(btn);
    } else {
      document.body.appendChild(btn);
    }
  }).observe(chatTabNode, { attributes: true, attributeFilter: ["class"] });
}

// Library used to relocate the button into #tab-library's own DOM subtree
// the same way Chat does, relying on CSS `position: absolute` there. Moved
// to a JS-computed `position: fixed` offset instead (positionScrollTopForNested,
// called from initScrollTopButton's own `update()`), reparenting the button
// is no longer needed, and not reparenting it also sidesteps a real CSS trap:
// if any ancestor between it and <body> ever gains a `transform`/`filter`/
// `backdrop-filter` (Library's glass-tier cards are exactly the kind of
// element that might), that ancestor silently becomes the containing block
// for `position: fixed` too, and the button would jump to being positioned
// relative to *that* instead of the viewport again.

// --- what the AI remembers (ROADMAP §39B) ------------------------------------------
//
// The list `save_user_preference` writes into, and the only place the user can
// see it. Worth the screen: this tool's output becomes part of the model's own
// system prompt on every later turn, so without this the assistant's behaviour
// could change permanently for a reason nobody could look up, edit or undo.
//
// The budget line is not decoration. Only active preferences reach the model,
// newest first, and only until the character budget runs out, so a long list
// quietly stops including its oldest entries. Saying so beats letting someone
// wonder why the rule they saved first is being ignored.
async function renderMemorySettings() {
  const list = $("memory-list");
  const empty = $("memory-empty");
  const budget = $("memory-budget");
  if (!list) return;

  const data = await apiJson("/memory").catch(() => null);
  if (!data) {
    list.replaceChildren();
    budget.textContent = "Couldn't load what the AI has remembered.";
    return;
  }

  const active = data.preferences.filter((p) => p.active).length;
  budget.textContent = active
    ? `${active} in use, about ${data.in_prompt} of ${data.budget_chars} characters. ` +
      "The newest are kept when this runs out."
    : "";
  empty.classList.toggle("hidden", data.preferences.length > 0);

  // Pending suggestions first. They are the only rows that need an answer,
  // and a proposal buried below thirty settled ones is a proposal nobody
  // sees: which was the whole complaint about the silent version of this
  // feature. Order is otherwise unchanged (newest first, from the API).
  const ordered = [
    ...data.preferences.filter((p) => p.proposed),
    ...data.preferences.filter((p) => !p.proposed),
  ];

  list.replaceChildren(
    ...ordered.map((pref) => {
      const row = document.createElement("div");
      row.className =
        "memory-row" + (pref.proposed ? " is-proposed" : pref.active ? "" : " is-off");

      const text = document.createElement("span");
      text.className = "memory-text";
      text.textContent = pref.content;
      text.title = pref.created_at
        ? `Saved ${new Date(pref.created_at).toLocaleString()}`
        : "";

      // A suggestion is a question, not a switch someone flipped: it gets
      // yes/no rather than on/off, and it is not in the prompt either way
      // until it is answered.
      if (pref.proposed) {
        const tag = document.createElement("span");
        tag.className = "memory-proposed-tag";
        setLabel(tag, "ph:brain Suggested by the AI");

        const answer = async (accept) => {
          await apiJson(`/memory/${pref.id}/answer`, {
            method: "POST",
            body: JSON.stringify({ accept }),
          }).catch(() => {});
          renderMemorySettings();
        };
        const yes = document.createElement("button");
        yes.type = "button";
        yes.className = "small";
        yes.textContent = "Remember it";
        yes.addEventListener("click", () => answer(true));

        const no = document.createElement("button");
        no.type = "button";
        no.className = "ghost small";
        no.textContent = "No thanks";
        no.addEventListener("click", () => answer(false));

        row.append(text, tag, yes, no);
        return row;
      }

      const toggle = document.createElement("button");
      toggle.type = "button";
      toggle.className = "ghost small";
      toggle.textContent = pref.active ? "Turn off" : "Turn on";
      toggle.addEventListener("click", async () => {
        toggle.disabled = true;
        await apiJson(`/memory/${pref.id}`, {
          method: "PATCH",
          body: JSON.stringify({ active: !pref.active }),
        }).catch(() => {});
        renderMemorySettings();
      });

      const remove = document.createElement("button");
      remove.type = "button";
      remove.className = "ghost small danger";
      remove.textContent = "Forget";
      remove.addEventListener("click", async () => {
        const ok = await confirmDialog(
          `Forget this?\n\n“${pref.content}”\n\nThe AI will stop applying it.`,
          { confirmLabel: "Forget it" }
        );
        if (!ok) return;
        await apiJson(`/memory/${pref.id}`, { method: "DELETE" }).catch(() => {});
        renderMemorySettings();
      });

      row.append(text, toggle, remove);
      return row;
    })
  );
}

// --- overlay focus-return, scroll lock, autogrow textareas -----------------
// SETTINGS_SECTIONS and the settings-modal shell itself moved to
// settings.js (§88.3 item 4). `overlayReturnFocus` stays: it is shared by
// every dialog in the app (the sketch pad, meeting recorder, improve-writing
// panel, onboarding, the command palette and more, grepped every call site
// before deciding, the same check the other three splits in this series
// describe doing), not owned by Settings, and it has to be defined here
// regardless since dashboard.js already reads and writes it as one of the
// app.js globals its own split's header names.

// Where to send focus back when a dialog closes (Wave L).
let overlayReturnFocus = null;

// --- page scroll lock while any overlay is open ---------------------------------
// Every dialog in the app is a `.modal-overlay` toggled by the `hidden` class,
// and the page behind kept scrolling under them, you'd reach for the settings
// scrollbar and move the notebook instead (user-reported). Rather than pairing
// a lock/unlock onto each of the seven open/close sites (and every one added
// later), one observer watches the overlays and derives the lock from whatever
// is actually visible. Overlays created on the fly, the image lightbox, are
// picked up by the same observer watching <body> for added nodes.
// `.lightbox` is the same idea under a different class (it's built at runtime
// rather than living in index.html), so it locks the page too.
const OVERLAY_SELECTOR = ".modal-overlay, .lightbox";

function syncScrollLock() {
  const anyOpen = [...document.querySelectorAll(OVERLAY_SELECTOR)].some(
    (el) => !el.classList.contains("hidden") && el.isConnected
  );
  document.documentElement.classList.toggle("modal-open", anyOpen);
}

// --- textareas that grow with what you type -----------------------------------
// A fixed-height box for "capture a thought" or "magic add" hides everything
// but the last couple of lines the moment a note runs long, which is exactly
// when you most want to see it (user request). Height follows content, up to a
// cap so the page never gets pushed around; past that it scrolls.
// 480, not 340: "about a third of the screen" (asked for) is the 0.35 cap
// below on any window under ~1370px tall; 340 undercut it on a 1080p display.
const AUTOGROW_MAX_PX = 480;

// How much of the window a growing box may take before it scrolls instead.
//
// A flat 340px is most of a laptop window's chat area and nearly all of a
// phone's: the box kept growing and the conversation it was about disappeared
// above it. The cap is the *smaller* of the two, so a tall screen keeps the
// familiar 340 and a short one keeps its conversation.
const AUTOGROW_MAX_VIEWPORT = 0.35;

//: Where a hand-dragged composer height is remembered. A preference about how
//: you write, so it outlives the session that set it.
const COMPOSER_HEIGHT_KEY = "chat-composer-height";

function autoGrowLimit(el) {
  // A height the user dragged to wins over both defaults, they have said, in
  // the most direct way an interface allows, how tall they want this box.
  const chosen = Number(el.dataset.maxPx || 0);
  if (chosen > 0) return chosen;
  return Math.min(AUTOGROW_MAX_PX, Math.round(window.innerHeight * AUTOGROW_MAX_VIEWPORT));
}

function autoGrow(el) {
  if (!el) return;
  // **A hidden textarea reports scrollHeight 0, and sizing to that collapses
  // it.** This is the reported "the capture box is short at the bottom and
  // only opens up when I click in it": the box was measured while its section
  // was display:none, sized to nothing, and the first `focus` re-ran this with
  // the box finally on screen, which looked like clicking made it grow.
  //
  // One caller already re-measured after a sub-tab switch, which fixed that
  // one route in. It did not fix arriving from another TAB with Capture
  // already the remembered section, and it never could, the bug is that a
  // measurement taken while invisible is meaningless, and the right place to
  // say so is here, once, rather than at every call site that might run early.
  //
  // `offsetParent` is null for a display:none element and for any element
  // inside one, which is exactly the condition. (It is also null for
  // position:fixed elements: none of the app's autogrow boxes are fixed, and
  // the cost of being wrong would be one un-resized box, not a collapsed one.)
  if (el.offsetParent === null) {
    // Marked so the box gets its size the moment it becomes visible, instead
    // of waiting for a focus that may never come.
    el.dataset.autogrowPending = "1";
    return;
  }
  delete el.dataset.autogrowPending;
  if (el.dataset.resizing) return; // a grabber drag is in progress; it wins
  // Reset first: without it the height only ever ratchets upwards, because
  // scrollHeight is measured against the height already set.
  el.style.height = "auto";
  const limit = autoGrowLimit(el);
  // **A height somebody dragged to is a floor, not just a ceiling.** Driven in
  // a browser: dragging the composer taller stored the new height and then
  // snapped the box straight back to one line, because this took
  // `min(scrollHeight, limit)` and an empty box has a scrollHeight of one row.
  // The setting was saved and instantly undone, which is worse than not
  // offering the drag at all.
  //
  // So a hand-set height is the height. It is what "manually adjustable"
  // means: the box stays where it was put, and only scrolls once the text
  // outgrows it.
  //: **Revised, by direct instruction**: "should auto expand to about a
  //: third of the screen if large amounts of text are in it but should be
  //: able to be lowered in height manually and should go back to normal
  //: when empty or the text reduces." A fixed hand-set height (the previous
  //: rule) is exactly what stopped the box expanding. Now a drag *below*
  //: the automatic height is a cap, a drag *above* it is a floor, and an
  //: empty box forgets the drag altogether.
  //: One-shot, read and cleared here rather than inside the branch below:
  //: when the drag happens on a box that *has* text the branch never runs,
  //: so a flag cleared only there would still be set the next time the box
  //: was emptied and would suppress the forget it exists to allow once.
  const keptDrag = Boolean(el.dataset.keepDrag);
  delete el.dataset.keepDrag;
  if (!el.value.trim() && el.dataset.maxPx) {
    //: **Except on the release of the drag that just set it.** Reported:
    //: "when I try to manually change the height of the chat bar, it snaps
    //: back to what it was with or without text in it." Reproduced: with
    //: text the drag holds at 240px, on an empty box it snapped straight
    //: back to 44 and the height was never kept. `record()` sets `maxPx`
    //: on pointerup and then asks for this function on the next frame, so
    //: this branch was undoing the drag as part of performing it, and an
    //: empty composer could not be resized at all. "Go back to normal when
    //: empty" is about a box you *clear* after dragging it, not about
    //: refusing the drag itself, so that one call is exempt.
    if (!keptDrag) {
      delete el.dataset.maxPx;
      try { localStorage.removeItem(COMPOSER_HEIGHT_KEY); } catch { /* storage may be unavailable */ }
    }
  }
  const chosen = Number(el.dataset.maxPx || 0);
  const viewportLimit = Math.min(AUTOGROW_MAX_PX, Math.round(window.innerHeight * AUTOGROW_MAX_VIEWPORT));
  const auto = Math.min(el.scrollHeight, viewportLimit);
  //: **INBOX 37: an empty box is pinned to its CSS floor, not measured.**
  //: Reported with a screenshot: Reminders' Magic add field taller than its
  //: own Add button on the owner's desktop shell; measured 44/44 (equal) in
  //: this sandbox's headless Chromium, on the bundled system font, in light
  //: mode. `el.scrollHeight` on an *empty* box is still a function of the
  //: rendered line box, which is a function of the actual font in use, and
  //: that is exactly what differs: a fallback font before a webfont has
  //: finished loading, a heavier weight dark mode's own stylesheet may pick,
  //: a different system font entirely on another OS. Every one of those can
  //: round `scrollHeight` a pixel or two past the button's fixed height,
  //: which is why this was invisible here and not there. `min-height` in
  //: rem is none of that, it is a fixed length the browser converts from the
  //: root font size alone, so reading it back is the one measurement that
  //: cannot drift with the textarea's own font. Only while there is nothing
  //: to measure: the moment real content wraps past this floor, `scrollHeight`
  //: takes back over below, which is the box actually growing to fit typed
  //: text rather than a static height with nothing behind it.
  const next = chosen > 0
    ? (chosen < auto ? chosen : Math.max(auto, Math.min(chosen, viewportLimit)))
    : !el.value.trim()
      //: An empty box is its own natural height (`rows` and the placeholder,
      //: measured at height:auto above), floored at min-height, never *just*
      //: min-height. Reported with a screenshot: the capture box at 44px
      //: under a two-line placeholder, the second line clipped, a scrollbar
      //: on an empty textarea. "A cleared box must not keep the height of
      //: what was in it" still holds: scrollHeight at height:auto is the
      //: empty box's own size, not the old text's.
      ? Math.max(parseFloat(getComputedStyle(el).minHeight) || 0, auto)
      : Math.min(el.scrollHeight, limit);
  el.style.height = `${next}px`;
  el.style.overflowY = el.scrollHeight > next ? "auto" : "hidden";
  // What this function chose, so a later resize can be told apart from a drag
  // by the user: the two are indistinguishable to a ResizeObserver otherwise.
  el.dataset.autoHeight = String(next);
  fitComposerToDock(el);
}

//: A composer smaller than this is not a composer. The floor exists so a very
//: short window trims the box rather than erasing it, at that point the
//: conversation scrolls and the user can drag the window instead.
const MIN_COMPOSER_PX = 44;

// A hand-dragged composer height, trimmed to the room the chat card has.
//
// The drag is a preference and it is kept as one: `dataset.maxPx` and
// localStorage are **not** touched here. Only the applied height is trimmed,
// so a box dragged to 380px on a large monitor comes back to 380px the moment
// there is room for it again. Writing the trimmed value back would be the app
// quietly forgetting a setting because the window was small once.
//
// The measurement is the card's own overflow rather than any sum of the
// furniture above it. Every number this file has ever guessed at, a viewport
// fraction, a rem cap, the dock's height: has been wrong within two sessions,
// because the dock gains controls and the tab strip wraps. `scrollHeight -
// clientHeight` is the browser answering "by how much does this not fit",
// which needs no maintenance and is exact.
// It iterates because one subtraction does not converge. The conversation
// above the dock is `flex: 1 1 auto` with a floor, so some of the height the
// composer gives back is immediately taken by the message list growing into
// it: measured: a 56px trim cleared only 24px of a 88px overflow. Each pass
// is exact about what it can see, and three of them have been enough at every
// size driven so far; the cap is there so a layout that somehow oscillates
// costs four reflows rather than the frame.
const COMPOSER_FIT_PASSES = 4;

function fitComposerToDock(box) {
  if (!box || box.id !== "chat-input") return;
  const card = document.getElementById("chat-main");
  // Nothing to measure while the tab is hidden; switchTab re-runs this.
  if (!card || !card.getClientRects().length) return;
  for (let pass = 0; pass < COMPOSER_FIT_PASSES; pass += 1) {
    const overflow = Math.round(card.scrollHeight - card.clientHeight);
    if (overflow <= 0) return;
    const now = Math.round(box.getBoundingClientRect().height);
    const next = Math.max(MIN_COMPOSER_PX, now - overflow);
    if (next >= now) return; // already as small as it is allowed to be
    // Set before the style write: the ResizeObserver below reads this to
    // decide whether a height change was a drag, and a trim must never be
    // recorded as one: that is how a preference gets eaten.
    box.dataset.autoHeight = String(next);
    box.style.height = `${next}px`;
    box.style.overflowY = box.scrollHeight > next ? "auto" : "hidden";
  }
}

// The trim depends on the window, so it has to be redone when the window
// changes. Re-running `autoGrow` rather than `fitComposerToDock` alone is what
// lets the box grow *back* towards the dragged height when the window gets
// bigger: autoGrow re-applies the preference, and the fit trims it again only
// if it still does not fit.
function refitComposer() {
  const box = document.getElementById("chat-input");
  if (box) autoGrow(box);
}

//: `ring-held` holds `.chat-dock:focus-within`'s accent ring off while the
//: focus in the composer is the app's doing rather than the reader's. See the
//: call in `switchTab` for the measurement that produced it, and
//: `.chat-dock.ring-held` in 04-chat-dock-appearance.css for what it turns off.
//:
//: A class rather than a `blur()` because the caret has to stay where it is:
//: the whole point of focusing the composer on arrival is that you can type
//: straight away, and taking the focus back to fix the ring would undo that.
//:
//: **Everything here is a hoisted `function` and the class name is a literal.**
//: `switchTab` can run before this line does (the app restores the last tab at
//: startup), so a `const` holding the name would be in its temporal dead zone
//: at the one moment that matters, and a module-level IIFE binding the
//: listeners would run before `.chat-dock` is necessarily in the document. The
//: listeners are therefore bound on the first suppression instead, which is
//: also the first moment the dock is certain to exist.
function chatDockSuppressRing() {
  const dock = document.querySelector(".chat-dock");
  if (!dock) return;
  //: Three ways the focus becomes the reader's: they type, they press
  //: something in the dock, or they leave and come back. `focusout` covers
  //: the last on its own, since the ring is only ever drawn while something
  //: in here has focus, so releasing the hold as focus leaves means the next
  //: focus, however it arrives, rings normally. Bound once (the dock element
  //: itself remembers), on the dock rather than per control: all three
  //: bubble.
  if (!dock.dataset.ringWired) {
    dock.dataset.ringWired = "1";
    for (const type of ["keydown", "pointerdown", "focusout"]) {
      dock.addEventListener(type, chatDockReleaseRing);
    }
  }
  dock.classList.add("ring-held");
}

function chatDockReleaseRing() {
  const dock = document.querySelector(".chat-dock");
  if (dock) dock.classList.remove("ring-held");
}

// The chat composer can be dragged taller, and remembers it.
//
// Asked for directly: *"there should be a max height that the chat text bar
// can grow to before it gets a scrollbar. the height should also be manually
// adjustable."* Both halves: the cap above, and this.
//
// The native resize grabber does the dragging; all this has to do is notice
// the result and stop `autoGrow` from immediately undoing it on the next
// keystroke. A drag is told from a grow by comparing against the height
// autoGrow last set: anything else was a hand on the corner.
function initComposerResize() {
  const box = $("chat-input");
  if (!box || box.dataset.resizeReady) return;
  box.dataset.resizeReady = "1";

  //: A saved drag is no longer applied on load: the box starts at its
  //: automatic size and a drag is remembered only until the box is emptied
  //: (see autoGrow). The key is still cleared here for profiles that have
  //: one from before.
  try { localStorage.removeItem(COMPOSER_HEIGHT_KEY); } catch { /* storage may be unavailable */ }

  //: **Double-tap the grabber to put it back.** Asked for directly: "allow
  //: double tapping the bottom expansion corner of the chat text box to reset
  //: it to the regular height." A dragged height is sticky by design (it
  //: survives reloads, see above), so without this the only way back to the
  //: automatic height was to drag it to *exactly* the right size by hand, 
  //: which is not a thing anyone can do.
  //:
  //: Scoped to the corner rather than the whole box: a double-click in the
  //: text is how you select a word, and stealing that would trade one small
  //: annoyance for a much larger one. The grabber is ~16px square at the
  //: bottom-right, and a little slack around it costs nothing because the
  //: only thing in that corner *is* the grabber.
  const GRABBER = 22;
  box.addEventListener("dblclick", (event) => {
    const rect = box.getBoundingClientRect();
    const inCorner =
      event.clientX >= rect.right - GRABBER && event.clientY >= rect.bottom - GRABBER;
    if (!inCorner) return;
    event.preventDefault();
    delete box.dataset.maxPx;
    try {
      localStorage.removeItem(COMPOSER_HEIGHT_KEY);
    } catch {
      /* private mode: there was nothing stored to remove */
    }
    // The inline height a drag left behind has to go too, or `autoGrow`'s own
    // reset measures against it and the box never shrinks back.
    box.style.height = "auto";
    autoGrow(box);
    toast("Composer height reset.");
  });

  if (typeof ResizeObserver !== "function") return;
  // The observer used to re-run autoGrow on every size change, including
  // the ones the grabber drag itself was making: autoGrow reset the height,
  // the drag set it again, the observer fired again (reported: "it just
  // spasms and fails"). While the pointer is down on the grabber nothing
  // fights the drag; the final height is recorded once on release. The
  // deferred frame stays: a synchronous autoGrow inside the callback is
  // the "ResizeObserver loop" console error.
  let dragging = false;
  const record = () => {
    const height = Math.round(box.getBoundingClientRect().height);
    const automatic = Number(box.dataset.autoHeight || 0);
    if (!height || Math.abs(height - automatic) <= 2) return;
    box.dataset.maxPx = String(height);
    try { localStorage.setItem(COMPOSER_HEIGHT_KEY, String(height)); } catch { /* private mode */ }
    //: Read and cleared by `autoGrow`'s "an empty box forgets the drag"
    //: branch, so the height this just recorded survives the very call
    //: that applies it. See that branch for the report.
    box.dataset.keepDrag = "1";
    requestAnimationFrame(() => autoGrow(box));
  };
  box.addEventListener("pointerdown", (event) => {
    const rect = box.getBoundingClientRect();
    dragging = event.clientX >= rect.right - GRABBER && event.clientY >= rect.bottom - GRABBER;
    if (dragging) box.dataset.resizing = "1";
  });
  window.addEventListener("pointerup", () => {
    if (!dragging) return;
    dragging = false;
    delete box.dataset.resizing;
    record();
  });
  const observer = new ResizeObserver(() => {
    if (dragging) return;
    record();
  });
  observer.observe(box);
}

function initAutoGrow() {
  for (const el of document.querySelectorAll("textarea.autogrow")) {
    if (el.dataset.autogrowReady) continue;
    el.dataset.autogrowReady = "1";
    el.addEventListener("input", () => autoGrow(el));
    // Also on programmatic changes, templates, the Remind button, a cleared form.
    el.addEventListener("focus", () => autoGrow(el));
    autoGrow(el);
  }
  initComposerResize();
}

function watchOverlays() {
  let queued = false;
  // The app toggles classes constantly while streaming a chat answer, so this
  // observer sees a lot of traffic it doesn't care about. Ignore anything that
  // isn't an overlay, then coalesce the rest into one check per frame, the
  // lock must never become a cost on the hot path.
  const touchesOverlay = (record) => {
    const target = record.target;
    if (target instanceof Element && target.matches(OVERLAY_SELECTOR)) return true;
    // An added/removed node may BE an overlay (the lightbox) or contain one.
    const isOverlay = (node) =>
      node instanceof Element &&
      (node.matches(OVERLAY_SELECTOR) || node.querySelector(OVERLAY_SELECTOR) !== null);
    return [...record.addedNodes, ...record.removedNodes].some(isOverlay);
  };

  const observer = new MutationObserver((records) => {
    if (queued || !records.some(touchesOverlay)) return;
    queued = true;
    requestAnimationFrame(() => {
      queued = false;
      syncScrollLock();
    });
  });
  observer.observe(document.body, {
    subtree: true,
    childList: true, // lightbox-style overlays appended at runtime
    attributes: true,
    attributeFilter: ["class"], // the `hidden` toggle on existing dialogs
  });
  syncScrollLock();
}

// --- account & security ------------------------------------------------------------

async function renderAccount() {
  const facts = $("account-facts");
  facts.replaceChildren();
  const info = await apiJson("/auth/account").catch(() => null);
  if (!info) {
    const li = document.createElement("li");
    li.className = "muted";
    li.textContent = "Couldn't read the account state.";
    facts.appendChild(li);
    return;
  }
  const rows = [
    ["Password", info.configured ? "Set" : "Not set yet"],
    [
      "Created",
      info.created_at ? new Date(info.created_at).toLocaleDateString() : ", ",
    ],
    [
      "Private notes",
      info.vault_exists
        ? info.vault_open
          ? "Encryption key loaded: private notes are readable"
          : "Locked: unlock to read private notes"
        : "No encrypted notes yet",
    ],
    ["Open sessions", String(info.active_sessions)],
  ];
  for (const [label, value] of rows) {
    const li = document.createElement("li");
    const name = document.createElement("strong");
    name.textContent = `${label}: `;
    li.append(name, document.createTextNode(value));
    facts.appendChild(li);
  }
}

async function changePassword() {
  const status = $("account-status");
  const current = $("account-current").value;
  const next = $("account-new").value;
  const confirmed = $("account-confirm").value;
  status.classList.remove("error");

  // Checked here as well as on the server, so a typo costs a moment rather
  // than a password you didn't mean to set.
  if (!current || !next) {
    status.classList.add("error");
    status.textContent = "Fill in your current and new password.";
    return;
  }
  if (next !== confirmed) {
    status.classList.add("error");
    status.textContent = "The two new passwords don't match.";
    return;
  }
  if (next.length < 4) {
    status.classList.add("error");
    status.textContent = "A password needs at least 4 characters.";
    return;
  }

  status.textContent = "Changing…";
  try {
    const result = await apiJson("/auth/change-password", {
      method: "POST",
      body: JSON.stringify({ current_password: current, new_password: next }),
      // A 401 here means "wrong current password", not "your session died".
      ownsAuthErrors: true,
    });
    // Changing the password invalidates every token, including this tab's.
    // The server hands back a fresh one so the change doesn't log you out of
    // the screen you just used to make it. Key must match authToken().
    localStorage.setItem("token", result.token);
    $("account-current").value = "";
    $("account-new").value = "";
    $("account-confirm").value = "";
    status.textContent = "Password changed.";
    toast(
      result.other_sessions_ended
        ? `Password changed. ${result.other_sessions_ended} other session(s) were signed out.`
        : "Password changed."
    );
    renderAccount().catch(() => {});
  } catch (error) {
    status.classList.add("error");
    status.textContent = error.message;
  }
}

let prefsCache = null;
// Set by savePrefs() to the PUT's own promise while it is in flight, and
// awaited here first (INBOX 73, see savePrefs' own comment): without this,
// re-showing the Preferences section (closing and reopening Settings does,
// via showSettingsSection) fires this function's fresh GET concurrently
// with an unfinished save, and whichever one the server answers first wins
// -- reproduced with the GET winning, which replaced prefsCache wholesale
// with the pre-save value and left the checkbox showing it permanently,
// not just for the moment the save was in flight.
let prefsSaveInFlight = null;

async function renderPrefs() {
  if (prefsSaveInFlight) await prefsSaveInFlight.catch(() => {});
  prefsCache = await apiJson("/preferences");
  $("pref-display-name").value = prefsCache.display_name || "";
  $("pref-bin-days").value = prefsCache.recycle_bin_days;
  $("pref-chat-retention").value = prefsCache.conversation_retention_days ?? 0;
  $("pref-search-min-sim").value = prefsCache.search_min_similarity;
  $("pref-search-z-margin").value = prefsCache.search_relative_z_margin;
  $("pref-style").value = prefsCache.communication_style;
  $("pref-profile").value = prefsCache.user_profile;
  $("pref-profile-enabled").checked = prefsCache.profile_enabled;
  if (prefsCache.session_idle_ttl_minutes) {
    $("account-idle-ttl").value = prefsCache.session_idle_ttl_minutes;
  }
  $("pref-notif-mute-except-reminders").checked = Boolean(
    prefsCache.notifications_muted_except_reminders
  );
  $("prefs-status").textContent = "";
}

// --- Settings → Web search ------------------------------------------------------
//
// Its own screen, and its own save. Web search used to be four controls inside
// Preferences, which is why every error message that said "Settings → Web
// search" pointed at a screen that did not exist.
//
// The engine list comes from the server rather than being written out here:
// the frontend and `websearch.PROVIDERS` would otherwise drift, and the first
// symptom would be a radio button the API rejects.
// The Background tasks section's own controls (`#pref-autonomous-tasks` and
// everything under it): pulled out so `showSettingsSection` can populate
// them the moment *that* section opens, not only as a side effect of opening
// Web search. They used to be filled in exclusively by `renderWebSearch`
// despite living in `#settings-tasks`, a different section entirely, open
// Settings → Background tasks directly in a fresh session (never having
// visited Web search) and every checkbox here read its raw HTML default
// (unchecked) instead of what was actually saved. Toggling one of them then
// called `savePrefs()`, which rebuilds the *entire* preferences object from
// the DOM: sending those defaults back to the server and silently
// overwriting the real values. This is "my preferences settings keep
// getting deleted": not one bad field, but a whole section's worth of
// settings reset the moment anything on it was touched without the
// Web-search tab having been opened first in the same session.
function renderAutonomousSettings() {
  $("pref-autonomous-tasks").checked = Boolean(prefsCache.autonomous_tasks_enabled);
  $("pref-ai-first-filing").checked = prefsCache.ai_first_filing ?? true;
  $("pref-background-filing").checked = prefsCache.background_filing ?? true;
  $("pref-auto-caption-images").checked = prefsCache.auto_caption_images ?? true;
  $("pref-auto-read-image-text").checked = prefsCache.auto_read_image_text ?? true;
  $("pref-auto-tag").checked = prefsCache.auto_tag_enabled ?? true;
  $("pref-auto-link").checked = prefsCache.auto_link_enabled ?? true;
  $("pref-auto-dedupe").checked = prefsCache.auto_dedupe_enabled ?? true;
  $("pref-auto-stale-review").checked = Boolean(prefsCache.auto_stale_review_enabled);
  $("pref-auto-capture").checked = Boolean(prefsCache.auto_capture_enabled);
  $("pref-autonomous-interval").value = prefsCache.autonomous_tasks_interval_hours || 6;
  $("pref-autonomous-model").value = prefsCache.autonomous_tasks_model || "";
  $("pref-battery-mode").checked = Boolean(prefsCache.battery_efficient_mode);
  $("pref-smart-model-routing").checked = prefsCache.smart_model_routing_enabled ?? true;
  toggleAutonomousPanel();
}

async function renderWebSearch() {
  prefsCache = await apiJson("/preferences");
  $("pref-web-search").checked = Boolean(prefsCache.web_search_enabled);
  $("pref-searxng").value = prefsCache.searxng_url || "";
  renderAutonomousSettings();
  $("searxng-autostart").checked = Boolean(prefsCache.searxng_autostart);
  $("search-provider-status").textContent = "";

  const picker = $("search-provider-picker");
  picker.replaceChildren();
  const info = await apiJson("/websearch/providers").catch(() => null);
  if (!info) {
    picker.textContent = "Couldn't load the engine list.";
    return;
  }
  for (const provider of info.providers) {
    const row = document.createElement("label");
    row.className = "provider-option";
    const radio = document.createElement("input");
    radio.type = "radio";
    radio.name = "search-provider";
    radio.value = provider.id;
    radio.checked = provider.id === info.selected;
    radio.addEventListener("change", () => saveSearchProvider(provider.id));
    const text = document.createElement("span");
    const title = document.createElement("strong");
    title.textContent = provider.label;
    const detail = document.createElement("span");
    detail.className = "muted";
    detail.textContent = provider.detail;
    text.append(title, document.createElement("br"), detail);
    row.append(radio, text);
    picker.appendChild(row);
  }
  refreshSearxngHost().catch(() => {});
}

async function saveSearchProvider(provider) {
  const status = $("search-provider-status");
  try {
    prefsCache = await apiJson("/preferences", {
      method: "PUT",
      body: JSON.stringify({ search_provider: provider }),
    });
    status.classList.remove("error");
    status.textContent = "Saved.";
  } catch (error) {
    status.classList.add("error");
    status.textContent = error.message;
  }
}

async function saveWebSearchSettings() {
  const status = $("search-provider-status");
  try {
    prefsCache = await apiJson("/preferences", {
      method: "PUT",
      body: JSON.stringify({
        web_search_enabled: $("pref-web-search").checked,
        searxng_url: $("pref-searxng").value.trim(),
      }),
    });
    // Reported: "the web search button is visibly disabled in the chat
    // dock instead of inactive when I have web search enabled in the
    // settings", the chat dock's own click handler keeps this Settings
    // checkbox in sync going the other way, but this save handler never
    // synced the chat dock button back, so it stayed on whatever look it
    // had at page load until clicked directly or the page reloaded.
    renderWebSearchToggle();
    status.classList.remove("error");
    status.textContent = "Saved.";
  } catch (error) {
    status.classList.add("error");
    status.textContent = error.message;
  }
}

// Shared by the "Check now" button and the silent startup check. `silent`
// suppresses the status-line text and the toast for the common "you're on
// the latest version" outcome: the startup check should only ever speak up
// when there's actually something to say.
async function checkForUpdate(silent = false) {
  const status = $("update-check-status");
  const applyBtn = $("update-apply-now");
  if (!silent && status) status.textContent = "Checking…";
  let result;
  try {
    result = await apiJson("/update/check", { silent: true });
  } catch (error) {
    if (!silent && status) status.textContent = "Couldn't check for updates.";
    return;
  }
  if (!result || !result.checked) {
    if (!silent && status) {
      status.textContent =
        result && result.reason === "disabled"
          ? "Enable the checkbox above, then try again."
          : "Couldn't reach GitHub to check for updates.";
    }
    applyBtn?.classList.add("hidden");
    return;
  }
  // Settings -> About's own fallback for "or they can manually do it in the
  // settings", same button, same apiJson('/update/apply') call the
  // post-login dialog's "Update automatically" makes.
  applyBtn?.classList.toggle("hidden", !(result.update_available && result.can_auto_apply));
  if (result.update_available) {
    const msg = `Version ${result.latest} is available (you have ${result.current}).`;
    if (status) status.textContent = msg;
    // The silent startup check is the one that runs on every login, asked
    // for directly: a popup after login, but "only if... not every time
    // they login". A toast alone auto-dismisses in 5.5s and is easy to miss
    // entirely if it fires mid-startup while other things are still
    // loading, so a newly-detected version also gets a real dialog, but
    // only once per version, via the same localStorage-latch pattern the
    // rest of this app uses for "seen it" state (e.g. the graph layout/
    // colour prefs above). Re-showing it every login for a version the
    // user has already dismissed would be the exact nagging this was
    // asked to avoid.
    if (silent && localStorage.getItem(UPDATE_SEEN_KEY) !== result.latest) {
      showUpdateAvailableDialog(result);
    } else {
      toast(msg);
    }
  } else if (!silent && status) {
    status.textContent = `You're on the latest version (${result.current}).`;
  }
}

//: The last version this profile was already told about, so the post-login
//: dialog fires once per newly-available release rather than every login
//: for as long as the user hasn't updated.
const UPDATE_SEEN_KEY = "update-seen-version";

// Shared by the dialog's "Update automatically" button and Settings ->
// About's manual one: asked for directly: "either by the message popping
// up the next time they load up the app and are connected to the internet,
// and/or they can manually do it in the settings." `onProgress(state)` is
// called on every poll (`{step, done_bytes, total_bytes}` from
// GET /update/apply/status) so each caller can render it its own way; the
// promise resolves `true` on outcome "launched" and `false` on "failed", 
// never rejects, since a failed apply is exactly the case both callers have
// to handle gracefully (offline, GitHub unreachable, no asset), not an
// exception to propagate.
async function applyUpdateNow(onProgress, tag = null) {
  const url = tag ? `/update/apply?tag=${encodeURIComponent(tag)}` : "/update/apply";
  const start = await apiJson(url, { method: "POST" }).catch((error) => {
    onProgress?.({ step: error.message, failed: true });
    return null;
  });
  if (!start) return false;
  for (;;) {
    await new Promise((resolve) => setTimeout(resolve, 700));
    const state = await apiJson("/update/apply/status", { silent: true }).catch(() => null);
    if (!state) continue; // a transient miss mid-poll isn't a failure
    onProgress?.(state);
    if (state.outcome === "launched") return true;
    if (state.outcome === "failed") return false;
    if (!state.running) return false; // shouldn't happen, but never loop forever
  }
}

function showUpdateAvailableDialog(result) {
  const overlay = document.createElement("div");
  overlay.className = "modal-overlay confirm-overlay";
  overlay.setAttribute("role", "dialog");
  overlay.setAttribute("aria-modal", "true");
  overlay.setAttribute("aria-label", "A new version is available");

  const card = document.createElement("div");
  card.className = "card modal-card confirm-card";
  const heading = document.createElement("h3");
  heading.textContent = "A new version is available";
  const text = document.createElement("p");
  text.className = "confirm-text";
  text.textContent = result.can_auto_apply
    ? `MemoryMap AI ${result.latest} is out: you're on ${result.current}. ` +
      "Update automatically (downloads and installs it, then closes MemoryMap " +
      "AI: reopen it in a minute or two to start using the new version), or " +
      "download it yourself from the release page."
    : `MemoryMap AI ${result.latest} is out: you're on ${result.current}. ` +
      "This app never updates itself without asking: download the new " +
      "version yourself whenever you're ready.";
  const progress = document.createElement("p");
  progress.className = "muted";
  const row = document.createElement("div");
  row.className = "row confirm-actions";

  let dismissed = false;
  const dismiss = () => {
    if (dismissed) return;
    dismissed = true;
    document.removeEventListener("keydown", onKey, true);
    overlay.remove();
    localStorage.setItem(UPDATE_SEEN_KEY, result.latest);
  };
  const onKey = (event) => {
    if (event.key === "Escape") {
      event.stopPropagation();
      dismiss();
    }
  };

  const later = smallButton("Remind me next time", "Remind me next time", dismiss);
  const view = document.createElement("a");
  view.href = result.url;
  view.target = "_blank";
  view.rel = "noopener";
  // A real <a>, not a button with a click handler that navigates, right-
  // click "open in new tab", middle-click, and Ctrl-click all need to keep
  // working the way they do on every other external link in this app. The
  // `.small`/`.ghost` button rules are scoped to `button.small` and don't
  // reach an anchor at all, hence the dedicated class below rather than
  // relying on those.
  view.className = "small update-dialog-link";
  view.textContent = "View release";
  view.addEventListener("click", dismiss);
  row.append(later, view);

  if (result.can_auto_apply) {
    const auto = smallButton("Update automatically", "Update automatically", async () => {
      auto.disabled = true;
      later.disabled = true;
      const ok = await applyUpdateNow((state) => {
        progress.textContent = state.total_bytes
          ? `${state.step} (${Math.round((state.done_bytes / state.total_bytes) * 100)}%)`
          : state.step;
      });
      if (!ok) {
        // A failed apply must not mark this version "seen", asked for
        // directly: it has to come back next login while still offline (or
        // whatever the real cause was), not go quiet. Re-enabling the
        // buttons also lets them retry immediately without waiting for
        // that next login at all.
        auto.disabled = false;
        later.disabled = false;
        toast(progress.textContent || "Couldn't apply the update.", true);
      }
      // On success the app exits itself shortly after (routes_update.py): 
      // nothing left to do here; the dialog just stays up, showing the
      // last progress line, until the process closes.
    }, false);
    row.appendChild(auto);
  }

  card.append(heading, text, progress, row);
  overlay.appendChild(card);
  wireBackdropClose(overlay, () => dismiss());
  document.addEventListener("keydown", onKey, true);
  document.body.appendChild(overlay);
  later.focus();
}

// A source checkout (start.sh/start.bat) auto-updates via `git pull` before
// the server even starts, asked for directly, the same "popup after
// login, only if the app auto updates" the packaged-Windows dialog above
// gives, for the other install type that also auto-updates but had no way
// to say so. GET /update/source-status is a plain env-var read with no
// network call and self-clears after one read, so this never fires twice
// for the same real update and never blocks on being offline.
async function checkForSourceUpdateNotice() {
  const result = await apiJson("/update/source-status", { silent: true }).catch(() => null);
  if (!result || !result.just_updated) return;
  showSourceUpdatedDialog(result);
}

function showSourceUpdatedDialog(result) {
  const overlay = document.createElement("div");
  overlay.className = "modal-overlay confirm-overlay";
  overlay.setAttribute("role", "dialog");
  overlay.setAttribute("aria-modal", "true");
  overlay.setAttribute("aria-label", "MemoryMap AI was updated");

  const card = document.createElement("div");
  card.className = "card modal-card confirm-card";
  const heading = document.createElement("h3");
  heading.textContent = "MemoryMap AI was updated";
  const text = document.createElement("p");
  text.className = "confirm-text";
  text.textContent = result.from
    ? `Your checkout auto-updated from ${result.from} to ${result.to} when you started it just now.`
    : `Your checkout auto-updated to ${result.to} when you started it just now.`;
  const row = document.createElement("div");
  row.className = "row confirm-actions";

  let dismissed = false;
  const dismiss = () => {
    if (dismissed) return;
    dismissed = true;
    document.removeEventListener("keydown", onKey, true);
    overlay.remove();
  };
  const onKey = (event) => {
    if (event.key === "Escape") {
      event.stopPropagation();
      dismiss();
    }
  };
  const ok = smallButton("Got it", "Got it", dismiss, false);
  row.appendChild(ok);

  card.append(heading, text, row);
  overlay.appendChild(card);
  wireBackdropClose(overlay, () => dismiss());
  document.addEventListener("keydown", onKey, true);
  document.body.appendChild(overlay);
  ok.focus();
}

//: Which checkbox in Settings mirrors which one elsewhere in the app. Two
//: controls for one preference is a reasonable convenience and a reliable way
//: to get them out of step; this is the list that keeps them honest.
const MIRRORED_PREFS = {
  autonomous_tasks_enabled: ["pref-autonomous-tasks", "skills-auto-toggle"],
  auto_tag_enabled: ["pref-auto-tag", "skills-auto-tag"],
  auto_link_enabled: ["pref-auto-link", "skills-auto-link"],
};

// Save one preference without rebuilding the whole object from the DOM.
//
// `savePrefs` reads every control on the Preferences screen and PUTs the lot,
// which is fine when that screen is what you are looking at and wrong when it
// is not: a control on another panel that saved directly left `prefsCache`
// stale, and the next `savePrefs` overwrote it from a checkbox nobody had
// touched. Anything outside the Preferences form should come through here.
async function setPreference(key, value) {
  try {
    prefsCache = await apiJson("/preferences", {
      method: "PUT",
      body: JSON.stringify({ [key]: value }),
    });
    for (const id of MIRRORED_PREFS[key] || []) {
      const box = $(id);
      if (box && box.checked !== value) box.checked = value;
    }
    if (key === "autonomous_tasks_enabled") {
      $("autonomous-settings-panel")?.classList.toggle("hidden", !value);
    }
  } catch (error) {
    toast(error.message || "Couldn't save that setting.", true);
  }
}

async function savePrefs() {
  try {
    const binDaysRaw = Number($("pref-bin-days").value);
    const recycleBinDays = Number.isFinite(binDaysRaw) && binDaysRaw >= 1
      ? Math.min(365, Math.round(binDaysRaw))
      : 30;
    $("pref-bin-days").value = recycleBinDays;
    const minSimRaw = Number($("pref-search-min-sim").value);
    const searchMinSim = Number.isFinite(minSimRaw) ? Math.min(1, Math.max(0, minSimRaw)) : 0.25;
    const zMarginRaw = Number($("pref-search-z-margin").value);
    const searchZMargin = Number.isFinite(zMarginRaw) ? Math.min(3, Math.max(0, zMarginRaw)) : 0.5;
    $("pref-search-min-sim").value = searchMinSim;
    $("pref-search-z-margin").value = searchZMargin;
    // Only this section's own fields. Background tasks' checkboxes
    // (autonomous_tasks_enabled and everything under it) save independently
    // via `setPreference` now: see the comment on `renderAutonomousSettings`
    // for why folding them in here was the actual cause of "preferences keep
    // getting deleted": this form's DOM may never have been rendered this
    // session, and sending its stale defaults back overwrote real values.
    const payload = {
      display_name: $("pref-display-name").value.trim(),
      recycle_bin_days: recycleBinDays,
      conversation_retention_days: Number($("pref-chat-retention").value) || 0,
      search_min_similarity: searchMinSim,
      search_relative_z_margin: searchZMargin,
      communication_style: $("pref-style").value,
      user_profile: $("pref-profile").value,
      profile_enabled: $("pref-profile-enabled").checked,
      notifications_muted_except_reminders:
        $("pref-notif-mute-except-reminders").checked,
    };
    // INBOX 73: "'Mute notifications except reminders' toggle disables
    // itself when the settings close." Reproduced two ways with Playwright
    // route interception: (1) check the box, Save, close and reopen
    // Settings before the PUT resolves -- renderPrefs' own fresh GET can
    // win the race and replace prefsCache wholesale with the pre-save
    // value; (2) delay the PUT leaving the browser at all (a slow
    // connection) so a concurrent GET genuinely reaches the server first
    // -- the checkbox then stayed wrong even after the PUT went on to
    // succeed, since nothing re-read it afterwards. Two matched fixes:
    // write the change into prefsCache immediately, before the await, so
    // any render mid-flight already sees it (renderPrefs still overwrites
    // this with the server's answer once its own GET lands, this is only
    // for the window before that); and hold the PUT's promise in
    // `prefsSaveInFlight` so renderPrefs (above) waits for it first
    // instead of racing it, which is what closes case 2.
    if (prefsCache) Object.assign(prefsCache, payload);
    prefsSaveInFlight = apiJson("/preferences", {
      method: "PUT",
      body: JSON.stringify(payload),
    });
    try {
      prefsCache = await prefsSaveInFlight;
    } finally {
      prefsSaveInFlight = null;
    }
    $("prefs-status").textContent = "Saved.";

    // Reflect a name change immediately if the dashboard is showing.
    if (typeof renderDashboardGreeting === "function") renderDashboardGreeting();
  } catch (error) {
    $("prefs-status").textContent = error.message;
  }
}

async function deleteProfile() {
  if (!(await confirmDialog("Delete your profile text? The AI will stop personalising answers."))) return;
  prefsCache = await apiJson("/preferences", {
    method: "PUT",
    body: JSON.stringify({ user_profile: "", profile_enabled: false }),
  });
  await renderPrefs();
  toast("Profile data deleted.");
}

// Downloads need the auth header, so plain <a href> won't do: fetch the
// bytes and hand the browser a blob instead.
async function downloadExport(kind) {
  const response = await api(`/export/${kind}`);
  // Markdown and the full backup arrive as zips; the rest are single files.
  const name =
    kind === "markdown" ? "memorymap-markdown.zip" :
    kind === "backup" ? "memorymap-backup.zip" :
    `memorymap-export.${kind}`;
  await saveFile(name, await response.blob());
}

// --- Wave F: backups UI -------------------------------------------------------------

async function renderBackups() {
  const list = $("backup-list");
  const backups = await apiJson("/backups").catch(() => []);
  list.replaceChildren();
  for (const item of backups) {
    const li = document.createElement("li");
    const row = document.createElement("div");
    row.className = "entry-meta";
    const name = document.createElement("span");
    setLabel(name, item.name);
    const size = document.createElement("span");
    size.className = "muted";
    size.textContent = `${(item.size / 1024).toFixed(0)} KB`;
    const actions = document.createElement("span");
    actions.className = "entry-actions";
    actions.appendChild(
      smallButton("Restore", "Roll the notebook back to this backup", async () => {
        if (
          !(await confirmDialog(
            "Restore this backup? Your current notebook is snapshotted first, " +
              "then replaced by the backup."
          ))
        )
          return;
        try {
          await apiJson("/backups/restore", {
            method: "POST",
            body: JSON.stringify({ name: item.name }),
          });
          toast("Backup restored.");
          loadEntries().catch(() => {});
          renderBackups();
        } catch (error) {
          toast(error.message, true);
        }
      })
    );
    actions.appendChild(
      smallButton("×", "Delete this backup", async () => {
        if (!(await confirmDialog("Delete this backup file?"))) return;
        await apiJson(`/backups/${item.name}`, { method: "DELETE" }).catch(() => {});
        renderBackups();
      })
    );
    row.append(name, size, actions);
    li.appendChild(row);
    list.appendChild(li);
  }
}

// The retention setting itself, separate fetch from renderBackups() (which
// only ever hits GET /backups) because the count/bounds live on GET
// /storage, so this app's own tests that treat GET /backups as a plain list
// of backups don't have to change shape for a control that isn't about any
// one backup.
async function renderBackupRetention() {
  const input = $("backup-retention");
  if (!input) return;
  const storage = await apiJson("/storage", { silent: true }).catch(() => null);
  if (!storage) return;
  input.min = storage.backup_retention_min;
  input.max = storage.backup_retention_max;
  input.value = storage.backup_retention_count;
  input.title = `Between ${storage.backup_retention_min} and ${storage.backup_retention_max}`;
}

$("backup-retention")?.addEventListener("change", async (e) => {
  const status = $("backup-retention-status");
  const keep = Number(e.target.value);
  try {
    const result = await apiJson("/backups/retention", {
      method: "PUT",
      body: JSON.stringify({ keep }),
    });
    status.textContent = result.removed
      ? `Saved: removed ${result.removed} old backup${result.removed === 1 ? "" : "s"}.`
      : "Saved.";
    renderBackups();
  } catch (error) {
    status.textContent = error.message;
    renderBackupRetention(); // put the field back to what's actually saved
  }
});

async function backupNow() {
  const status = $("backup-status");
  try {
    const made = await apiJson("/backups", { method: "POST" });
    status.textContent = `Saved ${made.name}.`;
    renderBackups();
  } catch (error) {
    status.textContent = error.message;
  }
}

async function importDirectory() {
  const pathInput = $("import-dir-path").value.trim();
  const status = $("import-dir-status");
  if (!pathInput) {
    status.textContent = "Please enter a directory path.";
    return;
  }
  status.textContent = "Starting import...";
  try {
    const response = await apiJson("/import/directory", {
      method: "POST",
      body: { path: pathInput },
    });
    status.textContent = "Import started in the background. Check your library soon.";
    $("import-dir-path").value = "";
  } catch (error) {
    status.textContent = error.message;
  }
}

async function importMarkdown(inputId = "import-md-files") {
  const input = $(inputId);
  const status = $("import-md-status");
  if (!input.files.length) {
    status.textContent =
      inputId === "import-md-folder"
        ? "Choose a folder first."
        : "Choose one or more .md files first.";
    return;
  }
  const form = new FormData();
  //: The third argument is the filename the server sees, and `webkitRelativePath`
  //: is the only place a folder picker puts the path, `file.name` is the bare
  //: name even when the file came from three folders down. Sending the path is
  //: what lets an imported vault keep its tree (`Entry.source_path`) and its
  //: `[[wiki links]]`, which name the file rather than its opening words.
  //: A vault folder holds far more than markdown (`.obsidian/`, images,
  //: PDFs), and the picker hands over every one of them, filtering here
  //: keeps the request from being mostly files the endpoint would reject one
  //: at a time and report as "skipped".
  const chosen = [...input.files].filter((file) =>
    /\.(md|markdown|txt)$/i.test(file.webkitRelativePath || file.name),
  );
  if (!chosen.length) {
    status.textContent = "No markdown files in that folder.";
    return;
  }
  for (const file of chosen) {
    form.append("files", file, file.webkitRelativePath || file.name);
  }
  try {
    const response = await fetch("/import/markdown", {
      method: "POST",
      // The multipart type still comes from the browser; X-Workspace-ID does
      // not, and without it an import while a non-default space is active
      // would silently land the new notes in the default space instead.
      headers: { "X-Auth-Token": authToken(), "X-Workspace-ID": activeSpaceId() },
      body: form,
    });
    if (!response.ok) throw new Error(`Import failed (${response.status})`);
    const result = await response.json();
    status.textContent =
      `Imported ${result.imported} note${result.imported === 1 ? "" : "s"}.` +
      (result.skipped.length ? ` Skipped: ${result.skipped.join("; ")}` : "");
    input.value = "";
    loadEntries().catch(() => {});
  } catch (error) {
    status.textContent = error.message;
  }
}

// §37G: a document (PDF/Word/slide deck) becomes one or more notes, via the
// markitdown extra: the same "Import" pattern as importMarkdown above, one
// file at a time rather than several, since a document commonly becomes
// several notes on its own (one per chapter or slide).
async function importDocument() {
  const input = $("import-document-file");
  const status = $("import-document-status");
  const file = input.files[0];
  if (!file) {
    status.textContent = "Choose a file first.";
    return;
  }
  const form = new FormData();
  form.append("file", file);
  try {
    const response = await fetch("/import/document", {
      method: "POST",
      // Same gap as /import/markdown above: without this, the imported
      // document lands in the default space regardless of which is active.
      headers: { "X-Auth-Token": authToken(), "X-Workspace-ID": activeSpaceId() },
      body: form,
    });
    if (!response.ok) {
      const detail = await response.json().catch(() => ({}));
      throw new Error(detail.detail || `Import failed (${response.status})`);
    }
    const result = await response.json();
    status.textContent =
      `Imported ${result.imported} note${result.imported === 1 ? "" : "s"}` +
      ` from ${result.filename}.` +
      (result.truncated ? " (Stopped at the note limit, the rest wasn't imported.)" : "");
    input.value = "";
    loadEntries().catch(() => {});
  } catch (error) {
    status.textContent = error.message;
  }
}

// --- Wave F: command palette (Ctrl/Cmd-K) -------------------------------------------

let paletteIndex = 0;

// Static commands; note search results are appended live as you type.
//: Interface zoom, in one place so the slider, the +/- buttons, the keyboard
//: shortcut and the command palette cannot drift apart. Asked for directly:
//: "a nicer way to adjust zoom… + and - buttons next to the slider, hotkeys
//: like ctrl + +/-, and in the commands list".
//:
//: Same range and step as the slider in Settings -> Appearance, and it writes
//: the same key, so all four routes are literally the same control.
const ZOOM_MIN = 70;
const ZOOM_MAX = 130;
const ZOOM_STEP = 5;

function currentZoom() {
  const stored = Number(localStorage.getItem("zoom"));
  return Number.isFinite(stored) && stored ? stored : 100;
}

function setZoom(percent) {
  const next = Math.max(ZOOM_MIN, Math.min(ZOOM_MAX, Math.round(percent / ZOOM_STEP) * ZOOM_STEP));
  localStorage.setItem("zoom", String(next));
  const slider = $("zoom-slider");
  if (slider) slider.value = next;
  const readout = $("zoom-value");
  if (readout) readout.textContent = `${next}%`;
  applyAppearance();
  return next;
}

//: **Feedback for a control you just used, which muting must not swallow.**
//: Reported: "the mute notifications button mutes things like if I hot key
//: zooming in and out, I cant see what zoom level Im at if the notifications
//: dont appear, maybe they can appear some other way visually??"
//:
//: The answer is that this was never a notification. A notification tells you
//: about something that happened elsewhere -- a background pass, a reminder --
//: and muting it is a real preference. Confirming a key you are holding down
//: is a *readout*: it belongs on screen for a moment, centred, with no history
//: and no dismiss button, and it has nothing to do with whether the app is
//: allowed to interrupt you. Every editor with a zoom shortcut does this.
//:
//: Deliberately not recorded in the notifications centre either: "Zoom 110%"
//: is not something anyone wants to scroll back through tomorrow.
let hudTimer = null;

//: Where the HUD has to live to be seen. INBOX 86: "zoom popup does not show
//: while a dialog (Settings) is open." Two different reasons, and only one of
//: them is a z-index.
//:
//: Settings is a `.modal-overlay` div at `z-index: 1010` against the HUD's
//: 90, so it simply painted over it: that is fixed in the stylesheet. A
//: native `<dialog>` opened with `showModal()` is a harder case, because it
//: renders in the browser's top layer, which sits above *every* z-index in
//: the document, so no number would ever win. The only way in is to be inside
//: that dialog, so while one is open the HUD is moved into it and put back
//: afterwards. `hudHome` remembers where it belongs rather than assuming
//: `<body>`, the same shape `wireEscapedActionMenu` uses for menus.
let hudHome = null;

function hud(text) {
  const box = $("hud");
  if (!box) return;
  const dialog = document.querySelector("dialog[open]");
  const wanted = dialog || hudHome || document.body;
  if (box.parentElement !== wanted) {
    if (!hudHome) hudHome = box.parentElement;
    wanted.appendChild(box);
  }
  box.textContent = text;
  box.classList.remove("hidden");
  clearTimeout(hudTimer);
  hudTimer = setTimeout(() => {
    box.classList.add("hidden");
    //: Home again once it is hidden, so a dialog that closes does not take
    //: the app's only HUD element out of the document with it.
    if (hudHome && box.parentElement !== hudHome) hudHome.appendChild(box);
  }, 1100);
}
window.hud = hud;

function nudgeZoom(direction) {
  const next = setZoom(currentZoom() + direction * ZOOM_STEP);
  hud(`Zoom ${next}%`);
}

// Ctrl/Cmd with + or - . On `capture` so a focused textarea cannot swallow it,
// and `preventDefault` so the browser's own zoom does not fire as well, 
// otherwise the two stack and one press moves both.
//
// `event.key` for "-" and "=" rather than a keyCode: "+" needs Shift on most
// layouts, so the unshifted "=" is what people actually press, and both are
// accepted for the same reason every other app accepts both.
document.addEventListener(
  "keydown",
  (event) => {
    if (!(event.ctrlKey || event.metaKey) || event.altKey) return;
    if (event.key === "+" || event.key === "=") {
      event.preventDefault();
      nudgeZoom(1);
    } else if (event.key === "-" || event.key === "_") {
      event.preventDefault();
      nudgeZoom(-1);
    } else if (event.key === "0") {
      event.preventDefault();
      setZoom(100);
      hud("Zoom 100%");
    }
  },
  true
);

