let paletteReminders = [];
let paletteConversations = [];
//: Files and boards, so the palette resolves every kind of thing this app
//: holds rather than four of six. REDESIGN.md R7.3 asks for exactly this, 
//: "one universal picker... resolving notes, documents, files and maps
//: alike", and it is the difference between a jump-to-note box and the way
//: you actually move around the app.
let paletteMedia = [];
let paletteBoards = [];

async function openPalette() {
  overlayReturnFocus = document.activeElement;
  $("palette-overlay").classList.remove("hidden");
  $("palette-input").value = "";
  paletteIndex = 0;
  renderPalette("");
  $("palette-input").focus();
  
  // Background fetch of Reminders and Conversations for the palette to search.
  //: To the end: the palette searches these by text, so a reminder past the
  //: first page would simply not be findable from the palette.
  apiPagedList("/reminders", 200, { silent: true }).then(res => { paletteReminders = res || []; }).catch(() => { paletteReminders = []; });
  //: Both to the end, for the same reason as the reminders above: each is
  //: paged server-side, and the palette searches them by text, so anything
  //: past the first page was simply not findable from the palette. The chat
  //: list joined them when its own flat cap became a page (INBOX 117's
  //: finding, one list later).
  apiPagedList("/conversations", 200, { silent: true }).then(res => { paletteConversations = res || []; }).catch(() => { paletteConversations = []; });
  apiPagedList("/media", 200, { silent: true }).then(res => { paletteMedia = res || []; }).catch(() => { paletteMedia = []; });
  //: Boards joined them when `GET /whiteboard/boards` became a page of its
  //: own: the palette searches boards by title, so a board past the first
  //: page would not be findable from here.
  apiPagedList("/whiteboard/boards", 200, { silent: true }).then(res => { paletteBoards = res || []; }).catch(() => { paletteBoards = []; });
}

function closePalette() {
  $("palette-overlay").classList.add("hidden");
  overlayReturnFocus?.focus?.();
  overlayReturnFocus = null;
}

//: Read a field that is *supposed* to be a string, without letting one bad
//: record take the whole palette down with it.
//:
//: Not defensive padding: the fix for a real outage. The reminders filter
//: below read `r.content`, and a reminder has no `content`: its field is
//: `text`. So `undefined.toLowerCase()` threw, and because the throw happened
//: partway through `paletteMatches`, **every** group was lost with it, notes,
//: documents, reminders and conversations alike. The palette silently degraded
//: to its static command list for anyone with so much as one reminder saved,
//: and the only trace was an exception in a console nobody has open.
//:
//: The field name is fixed below. This helper exists so the *class* of failure
//: cannot come back: a payload that changes shape again costs one missing
//: group, not all of them.
function paletteText(value) {
  return typeof value === "string" ? value.toLowerCase() : "";
}

function paletteMatches(query) {
  const lowered = query.trim().toLowerCase();
  const commands = paletteCommands().filter((c) =>
    paletteText(c.label).includes(lowered)
  );
  if (!lowered) return commands;

  // Notes: match body or title.
  const notes = allEntries
    .filter((e) =>
      paletteText(e.content).includes(lowered) ||
      paletteText(e.title).includes(lowered)
    )
    .slice(0, 5)
    .map((e) => ({
      group: "Notes",
      label: `ph:file-text ${e.title || e.content.slice(0, 55)}${!e.title && e.content.length > 55 ? "…" : ""}`,
      run: () => flashEntry(e.id),
    }));

  // Documents: title search against the in-memory docs list.
  const docMatches = docs
    .filter((d) => paletteText(d.title).includes(lowered))
    .slice(0, 3)
    .map((d) => ({
      group: "Documents",
      label: `ph:article ${d.title}`,
      run: () => openDocumentFromNote(d.id),
    }));

  // Reminders: search content.
  // `r.text`, not `r.content`, see `paletteText` above for what the wrong
  // field name actually cost.
  const reminderMatches = paletteReminders
    .filter((r) => paletteText(r.text).includes(lowered))
    .slice(0, 3)
    .map((r) => ({
      group: "Reminders",
      label: `ph:alarm ${r.text.length > 55 ? r.text.slice(0, 55) + "…" : r.text}`,
      run: () => flashReminder(r.id),
    }));

  // Conversations: search title.
  const conversationMatches = paletteConversations
    .filter((c) => paletteText(c.title).includes(lowered))
    .slice(0, 3)
    .map((c) => ({
      group: "Conversations",
      label: `ph:chat-circle ${c.title}`,
      run: () => loadChatHistory(c.id),
    }));

  // Files: matched on the name you gave the file and on its caption, because
  // "the screenshot of the timetable" is how people remember an image, not
  // `a3f9c2.png`. Opens the Library's Files tab, which is where the file's own
  // metadata and its usage links live.
  const mediaMatches = paletteMedia
    .filter(
      (m) =>
        paletteText(m.original_name).includes(lowered) ||
        paletteText(m.caption).includes(lowered)
    )
    .slice(0, 3)
    .map((m) => ({
      group: "Files",
      label: `ph:image ${m.original_name || "Untitled file"}`,
      // `focusLibraryFile` picks Images or Files from the url, the media
      // view is two sub-tabs now, and a `[data-target="library-view-media"]`
      // query matches both.
      run: () => focusLibraryFile(m.original_name || "", m.url || ""),
    }));

  // Boards and maps. `id` is null for the default board, passed through as
  // null rather than skipped, because the default board is the one most
  // people actually draw on.
  const boardMatches = paletteBoards
    .filter((b) => paletteText(b.title).includes(lowered))
    .slice(0, 3)
    .map((b) => ({
      group: "Boards & maps",
      label: `ph:squares-four ${b.title || "Untitled board"}`,
      run: () => openWhiteboardBoard(b.id ?? null),
    }));

  return [
    ...commands,
    ...notes,
    ...docMatches,
    ...mediaMatches,
    ...boardMatches,
    ...reminderMatches,
    ...conversationMatches,
  ];
}

function renderPalette(query) {
  const list = $("palette-list");
  const matches = paletteMatches(query);
  paletteIndex = Math.min(paletteIndex, Math.max(0, matches.length - 1));
  list.replaceChildren();
  let lastGroup = null;
  matches.forEach((match, index) => {
    // Insert a non-interactive group header when the group changes.
    if (match.group && match.group !== lastGroup) {
      const header = document.createElement("li");
      header.className = "palette-group-header";
      header.textContent = match.group;
      header.setAttribute("aria-hidden", "true");
      list.appendChild(header);
      lastGroup = match.group;
    }
    const li = document.createElement("li");
    setLabel(li, match.label);
    if (index === paletteIndex) li.classList.add("active");
    li.addEventListener("click", () => {
      closePalette();
      match.run();
    });
    list.appendChild(li);
  });
  if (!matches.length) {
    const li = document.createElement("li");
    li.className = "muted";
    li.textContent = "No matching command, note or document.";
    list.appendChild(li);
  }
}

function paletteKeydown(event) {
  const matches = paletteMatches($("palette-input").value);
  if (event.key === "Escape") closePalette();
  else if (event.key === "ArrowDown") {
    event.preventDefault();
    paletteIndex = Math.min(paletteIndex + 1, matches.length - 1);
    renderPalette($("palette-input").value);
    scrollPaletteToActive();
  } else if (event.key === "ArrowUp") {
    event.preventDefault();
    paletteIndex = Math.max(paletteIndex - 1, 0);
    renderPalette($("palette-input").value);
    scrollPaletteToActive();
  } else if (event.key === "Enter" && matches[paletteIndex]) {
    closePalette();
    matches[paletteIndex].run();
  }
}

// Reported live: arrowing past the visible rows left the selection off
// screen: nothing followed it. `renderPalette` rebuilds the list from
// scratch on every keypress (replaceChildren), so there is no focused or
// otherwise browser-tracked element for the browser's own native
// scroll-on-focus to follow; `.active` is a plain CSS class on an
// unfocused `<li>`, invisible to that mechanism entirely.
function scrollPaletteToActive() {
  $("palette-list").querySelector(".active")?.scrollIntoView({ block: "nearest" });
}

// --- Wave F: whiteboard-lite --------------------------------------------------------

// Reported directly as "completely wrong": at 0.05 the highlighter needed
// roughly twenty overlapping passes before a stroke showed at all, visually
// indistinguishable from the tool doing nothing. 0.35 reads as an actual
// highlighter (translucent, tints rather than covers) in one pass.
const SKETCH_HIGHLIGHTER_ALPHA = 0.35;

// **The remaining two differences from the whiteboard's highlighter, now
// gone.** Reported: "fix the highlighter in the quick sketch feature to be
// the same as the whiteboard". The alpha and the width multiplier already
// matched (see both constants); what did not was how the stroke was painted.
//
// · `globalCompositeOperation: "multiply"` was the substantive one. Multiply
//   darkens toward black against whatever is behind it, so the same yellow
//   that tints a white page turns to mud on a dark one, and this app has a
//   dark theme. The whiteboard draws an SVG path with plain `stroke-opacity`
//   and no blend mode at all, which behaves the same on any background.
// · `lineJoin: "bevel"` against the whiteboard's `round`, which is what made
//   a scribbled corner look chipped here and smooth there.
//
// `lineCap: "square"` stays: the whiteboard sets exactly that, and a flat
// end is what a marker leaves.
const SKETCH_HIGHLIGHTER_LINE_JOIN = "round";
const SKETCH_HIGHLIGHTER_COMPOSITE = "source-over";
// Was 6x: the whiteboard's own highlighter (WB_STROKE_WIDTH * 4 in
// whiteboard.js) is the reference the two are meant to match, and reported
// directly as needing to. Both start from a different base width (sketchPen
// default 4px vs. the whiteboard's 3px), so matching the multiplier rather
// than the pixel result is what keeps them proportionally alike as either
// slider moves.
const SKETCH_HIGHLIGHTER_WIDTH_MULTIPLIER = 4;

let sketchPen = { color: "#3b82f6", size: 4, eraser: false };
let sketchDrawing = false;
let sketchDirty = false;
let sketchTool = "pen"; // "pen", "rect", "circ", "arrow", "text"
let sketchHistory = [];
let sketchRedoStack = [];
let sketchStartX = 0;
let sketchStartY = 0;

function sketchSaveSnapshot() {
  const canvas = $("sketch-canvas");
  const ctx = canvas.getContext("2d");
  sketchHistory.push(ctx.getImageData(0, 0, canvas.width, canvas.height));
  if (sketchHistory.length > 30) sketchHistory.shift();
  sketchRedoStack = [];
}

// §37G: an image the user brought in to annotate over, an `ImageBitmap`, or
// null for a blank page. Lives on its own layer (`#sketch-bg-canvas`) below
// the pen strokes (`#sketch-canvas`), so Clear and the eraser can affect the
// strokes without touching it.
let sketchBackgroundImage = null;

function sketchContext() {
  return $("sketch-canvas").getContext("2d");
}

// Redraws the background layer from scratch: white, then the uploaded image
// (if any) scaled to fit inside the canvas without cropping or stretching.
// Called after every change to `sketchBackgroundImage`, rather than patched
// in place, because "fit inside and centre" isn't otherwise idempotent.
// A reachable background colour, asked for directly, the canvas painted a
// hardcoded white fill with nothing that could change it, and a CSS
// background on the canvas *element* would have done nothing either: this
// fill is opaque pixels drawn into the canvas's own bitmap, which sits in
// front of (and fully hides) whatever the element's CSS background is.
// Persisted the same way the whiteboard's own board colour is (a
// `localStorage` key, not a preference, a look, not notebook data).
const SKETCH_BG_KEY = "sketch-bg-color";
let sketchBgColor = localStorage.getItem(SKETCH_BG_KEY) || "#ffffff";

function sketchDrawBackground() {
  const canvas = $("sketch-bg-canvas");
  const context = canvas.getContext("2d");
  context.fillStyle = sketchBgColor;
  context.fillRect(0, 0, canvas.width, canvas.height);
  const img = sketchBackgroundImage;
  if (!img) return;
  const scale = Math.min(canvas.width / img.width, canvas.height / img.height);
  const w = img.width * scale;
  const h = img.height * scale;
  context.drawImage(img, (canvas.width - w) / 2, (canvas.height - h) / 2, w, h);
}

function openSketch() {
  overlayReturnFocus = document.activeElement;
  $("sketch-overlay").classList.remove("hidden");
  $("sketch-close").focus();
  sketchBackgroundImage = null;
  $("sketch-bg-color-picker").value = sketchBgColor;
  sketchDrawBackground();
  const canvas = $("sketch-canvas");
  canvas.getContext("2d").clearRect(0, 0, canvas.width, canvas.height);
  sketchDirty = false;
  sketchHistory = [];
  sketchRedoStack = [];
  sketchTool = "pen";
  // The tool state and the buttons that show it were reset separately, which
  // is to say the buttons were not reset at all: closing the pad with the
  // eraser held left `sketchPen.eraser` true and the eraser lit, and the next
  // open declared `sketchTool = "pen"` above while the eraser button kept its
  // `.active` ring and the eraser kept erasing. Both halves move together.
  sketchPen.eraser = false;
  for (const button of document.querySelectorAll("#sketch-toolbar .ghost.icon-button")) {
    button.classList.toggle("active", button.id === "sketch-tool-pen");
  }
  syncSketchSizeReadout();
  $("sketch-status").textContent = "";
}

// The number beside the width slider. It is written from the input's own value
// rather than from `sketchPen.size` so that it cannot drift from what the
// slider is showing, which is the one thing it exists to report.
function syncSketchSizeReadout() {
  const slider = $("sketch-size");
  $("sketch-size-value").textContent = slider.value;
}

async function sketchUploadImage(file) {
  if (!file) return;
  const status = $("sketch-status");
  try {
    sketchBackgroundImage = await createImageBitmap(file);
    sketchDrawBackground();
    sketchDirty = true; // an image is as much a change as a pen stroke
    status.textContent = "";
  } catch {
    status.textContent = "Couldn't load that image.";
  }
}

async function closeSketch() {
  if (sketchDirty && !(await confirmDialog("Close without saving your sketch?"))) return;
  $("sketch-overlay").classList.add("hidden");
  overlayReturnFocus?.focus?.();
  overlayReturnFocus = null;
}

function sketchPointer(event) {
  const canvas = $("sketch-canvas");
  const rect = canvas.getBoundingClientRect();
  return {
    x: ((event.clientX - rect.left) / rect.width) * canvas.width,
    y: ((event.clientY - rect.top) / rect.height) * canvas.height,
  };
}

let sketchMoved = false;

function sketchStart(event) {
  sketchDrawing = true;
  sketchDirty = true;
  sketchMoved = false;
  const { x, y } = sketchPointer(event);
  sketchStartX = x;
  sketchStartY = y;
  
  if (sketchTool === "text") {
    const text = prompt("Enter text:");
    if (text) {
      sketchSaveSnapshot();
      const context = sketchContext();
      context.font = `${sketchPen.size * 6}px sans-serif`;
      context.fillStyle = sketchPen.color;
      context.fillText(text, x, y);
    }
    sketchDrawing = false;
    return;
  }

  sketchSaveSnapshot();
  const context = sketchContext();
  if (sketchTool === "pen" || sketchTool === "highlighter") {
    context.beginPath();
    context.moveTo(x, y);
  }
  event.target.setPointerCapture(event.pointerId);
}

function sketchMove(event) {
  if (!sketchDrawing) return;
  const { x, y } = sketchPointer(event);
  const context = sketchContext();
  if (x === sketchStartX && y === sketchStartY) return;
  sketchMoved = true;
  
  if (sketchTool !== "pen" && sketchTool !== "highlighter") {
    const last = sketchHistory[sketchHistory.length - 1];
    if (last) context.putImageData(last, 0, 0);
    else context.clearRect(0, 0, context.canvas.width, context.canvas.height);
  }

  context.lineCap = sketchTool === "highlighter" ? "square" : "round";
  context.lineJoin = sketchTool === "highlighter" ? SKETCH_HIGHLIGHTER_LINE_JOIN : "round";
  context.globalCompositeOperation =
    sketchPen.eraser && sketchTool === "pen"
      ? "destination-out"
      : sketchTool === "highlighter"
        ? SKETCH_HIGHLIGHTER_COMPOSITE
        : "source-over";
  context.globalAlpha = sketchTool === "highlighter" ? SKETCH_HIGHLIGHTER_ALPHA : 1.0;
  context.strokeStyle = sketchPen.color;
  context.lineWidth = sketchTool === "highlighter" ? sketchPen.size * SKETCH_HIGHLIGHTER_WIDTH_MULTIPLIER : (sketchPen.eraser && sketchTool === "pen" ? sketchPen.size * 4 : sketchPen.size);

  if (sketchTool === "pen" || sketchTool === "highlighter") {
    context.lineTo(x, y);
    context.stroke();
    // Reported: "the highlighter has no opacity to it, it's basically a
    // thick pen." The path opened in sketchStart keeps every point ever
    // added via lineTo: stroke() re-draws the *whole accumulated path*
    // each time, not just the newest segment, so a stroke a hundred points
    // long gets its first segment re-composited a hundred times over. At
    // full opacity (the plain pen) that's invisible: opaque drawn twice is
    // still opaque: but at the highlighter's 0.35 alpha, ~10 overlapping
    // passes already reads as ~99% opaque (1-(1-0.35)^10), which is exactly
    // "no opacity to it". Starting a fresh single-segment path from the
    // current point makes every stroke() call draw that one segment
    // exactly once, at exactly the alpha asked for.
    context.beginPath();
    context.moveTo(x, y);
  } else if (sketchTool === "line") {
    context.beginPath();
    context.moveTo(sketchStartX, sketchStartY);
    context.lineTo(x, y);
    context.stroke();
  } else if (sketchTool === "rect") {
    // Shift locks proportions: a square instead of whatever rectangle the
    // pointer happens to trace, the same convention every other drawing
    // tool uses, asked for directly. `circ` needs no equivalent: it has
    // always drawn from a single radius (`context.arc`), never width/height
    // independently, so it was already a perfect circle with no ellipse
    // mode to lock out of.
    let w = x - sketchStartX;
    let h = y - sketchStartY;
    if (event.shiftKey) {
      const side = Math.max(Math.abs(w), Math.abs(h));
      w = Math.sign(w || 1) * side;
      h = Math.sign(h || 1) * side;
    }
    context.beginPath();
    context.rect(sketchStartX, sketchStartY, w, h);
    context.stroke();
  } else if (sketchTool === "circ") {
    context.beginPath();
    const r = Math.sqrt(Math.pow(x - sketchStartX, 2) + Math.pow(y - sketchStartY, 2));
    context.arc(sketchStartX, sketchStartY, r, 0, 2 * Math.PI);
    context.stroke();
  } else if (sketchTool === "arrow") {
    context.beginPath();
    context.moveTo(sketchStartX, sketchStartY);
    context.lineTo(x, y);
    context.stroke();
    const angle = Math.atan2(y - sketchStartY, x - sketchStartX);
    const headLen = sketchPen.size * 3 + 5;
    context.beginPath();
    context.moveTo(x, y);
    context.lineTo(x - headLen * Math.cos(angle - Math.PI / 6), y - headLen * Math.sin(angle - Math.PI / 6));
    context.moveTo(x, y);
    context.lineTo(x - headLen * Math.cos(angle + Math.PI / 6), y - headLen * Math.sin(angle + Math.PI / 6));
    context.stroke();
  }
}

function sketchEnd(event) {
  if (sketchDrawing && !sketchMoved && event && (event.type === "pointerup" || event.type === "click")) {
    const context = sketchContext();
    context.lineCap = sketchTool === "highlighter" ? "square" : "round";
    context.lineJoin = sketchTool === "highlighter" ? SKETCH_HIGHLIGHTER_LINE_JOIN : "round";
    context.globalCompositeOperation =
      sketchPen.eraser && sketchTool === "pen"
        ? "destination-out"
        : sketchTool === "highlighter"
          ? SKETCH_HIGHLIGHTER_COMPOSITE
          : "source-over";
    context.globalAlpha = sketchTool === "highlighter" ? SKETCH_HIGHLIGHTER_ALPHA : 1.0;
    context.strokeStyle = sketchPen.color;
    
    if (sketchTool === "pen" || sketchTool === "highlighter") {
      context.lineWidth = sketchTool === "highlighter" ? sketchPen.size * SKETCH_HIGHLIGHTER_WIDTH_MULTIPLIER : (sketchPen.eraser && sketchTool === "pen" ? sketchPen.size * 4 : sketchPen.size);
      context.beginPath();
      context.moveTo(sketchStartX, sketchStartY);
      context.lineTo(sketchStartX, sketchStartY + 0.1);
      context.stroke();
    } else if (sketchTool === "rect") {
      context.lineWidth = sketchPen.size;
      context.beginPath();
      const s = sketchPen.size * 10 + 20;
      context.rect(sketchStartX - s/2, sketchStartY - s/2, s, s);
      context.stroke();
    } else if (sketchTool === "circ") {
      context.lineWidth = sketchPen.size;
      context.beginPath();
      const r = sketchPen.size * 5 + 10;
      context.arc(sketchStartX, sketchStartY, r, 0, 2 * Math.PI);
      context.stroke();
    } else if (sketchTool === "arrow") {
      context.lineWidth = sketchPen.size;
      const len = sketchPen.size * 10 + 20;
      context.beginPath();
      context.moveTo(sketchStartX - len/2, sketchStartY);
      context.lineTo(sketchStartX + len/2, sketchStartY);
      context.stroke();
      const headLen = sketchPen.size * 3 + 5;
      context.beginPath();
      context.moveTo(sketchStartX + len/2, sketchStartY);
      context.lineTo(sketchStartX + len/2 - headLen * Math.cos(Math.PI / 6), sketchStartY - headLen * Math.sin(Math.PI / 6));
      context.moveTo(sketchStartX + len/2, sketchStartY);
      context.lineTo(sketchStartX + len/2 - headLen * Math.cos(-Math.PI / 6), sketchStartY - headLen * Math.sin(-Math.PI / 6));
      context.stroke();
    }
  }
  sketchDrawing = false;
}

async function saveSketch() {
  const status = $("sketch-status");
  status.textContent = "Saving…";
  const caption =
    $("sketch-caption").value.trim() ||
    `Sketch: ${new Date().toLocaleDateString()}`;
  try {
    // Strokes and any uploaded image live on separate canvases (§37G); the
    // saved PNG has to be both together, composited onto a throwaway canvas
    // rather than either layer alone.
    const composite = document.createElement("canvas");
    composite.width = $("sketch-canvas").width;
    composite.height = $("sketch-canvas").height;
    const compositeContext = composite.getContext("2d");
    compositeContext.drawImage($("sketch-bg-canvas"), 0, 0);
    compositeContext.drawImage($("sketch-canvas"), 0, 0);
    const blob = await new Promise((resolve) => composite.toBlob(resolve, "image/png"));

    // **Through `/media/upload`, not `/entries/{id}/files`.** A sketch used
    // to be saved as an *attachment*, which is a different table and a
    // different pipeline: attachments are files hanging off a note, and only
    // `MediaUpload` rows are captioned, OCR'd, read by a vision model, or
    // listed in the Library's gallery. So a drawing was the one image in this
    // app that none of that ever touched, reported directly: "add captioning
    // and vision and ocr for sketches the user draws and saves as well".
    //
    // Uploading first and referencing the result in the note's markdown is
    // exactly what dropping an image into the note editor already does, so
    // this is now the same path rather than a second one: the picture appears
    // inline in the note, in the gallery, and in `media_process`'s queue.
    const stamp = new Date().toISOString().slice(0, 19).replace(/[:T]/g, "-");
    const form = new FormData();
    form.append("file", blob, `sketch-${stamp}.png`);
    const uploaded = await apiJson("/media/upload", {
      method: "POST",
      headers: { "X-Auth-Token": authToken() },
      body: form,
    });
    // The caption stays the note's own first line, it is what the person
    // typed and what the note is called. The image follows it.
    const entry = await apiJson("/entries", {
      method: "POST",
      body: JSON.stringify({
        content: `${caption}\n\n![${caption}](${uploaded.url})`,
        category: "Sketches",
      }),
    });
    if (!entry?.id) throw new Error("Couldn't save the sketch note.");
    sketchDirty = false;
    $("sketch-overlay").classList.add("hidden");
    $("sketch-caption").value = "";
    toast("Sketch saved to your notebook.");
    loadEntries().catch(() => {});
  } catch (error) {
    status.textContent = error.message;
  }
}

// --- Wave H: voice capture (local Whisper) ------------------------------------------

let voiceStatus = null; // cached /voice/status
let recorder = null; // the active MediaRecorder, if any
let recorderTarget = null; // which input gets the transcript

// Live mic-level ring on a recording button, driven off the same MediaStream
// the recorder already opened, no extra permission, no extra stream.
// Returns a stop() that tears down the AudioContext; callers must invoke it
// before the stream's tracks are stopped.
// A small scrolling bar meter, Voice-Memos-style: five bars, oldest sample on
// the left, newest on the right, each redrawn from the analyser at ~15fps, 
// full 60fps would reshuffle the bars faster than a glance can read as a
// wave. The plain ring this replaced was a single number's worth of signal
// and, worse, was drawn in --warn-soft: a token pre-mixed pale enough that on
// a near-white modal card it was measured, by screenshot, as functionally
// invisible: that's what "no animation" on the meeting recorder turned out
// to be. --recording-ring (a solid --warn mixed at capture time, defined
// alongside button.recording below) replaced it there and is reused here.
const MIC_BAR_COUNT = 5;
const MIC_BAR_SAMPLE_EVERY = 4; // frames between bar updates, ~15fps at 60fps rAF
// getByteFrequencyData's 128 bins (at fftSize=256) span the full 0-22kHz
// range, but speech energy sits almost entirely under ~5.5kHz. Averaging
// every bin, the previous behaviour, mixed a real voice signal with ~100
// near-silent high-frequency bins and diluted it to a fraction of what a
// human ear perceives as "there's sound". Restricting the average to the
// low bins reflects what's actually in a voice.
const MIC_BAR_SPEECH_BIN_FRACTION = 0.25;
// Reported live as "the bars don't show even at minimum sound pick-up":
// at a 0.12 floor, a 14px bar renders under 2px tall, not subtle, just
// below what's visible. 0.12 was chosen to read as "listening, not
// frozen" (see below) but never accounted for how few pixels that scale
// actually leaves. Raised so the resting state itself is visible.
const MIC_BAR_MIN_SCALE = 0.3;

function startMicLevelMeter(stream, button) {
  let ctx;
  try {
    ctx = new (window.AudioContext || window.webkitAudioContext)();
  } catch {
    return () => {}; // no Web Audio support, recording still works, just no meter
  }
  const source = ctx.createMediaStreamSource(stream);
  const analyser = ctx.createAnalyser();
  analyser.fftSize = 256;
  source.connect(analyser);
  const data = new Uint8Array(analyser.frequencyBinCount);
  const speechBinCount = Math.round(data.length * MIC_BAR_SPEECH_BIN_FRACTION);
  button.classList.add("live-level");

  const bars = document.createElement("span");
  bars.className = "mic-bars";
  bars.setAttribute("aria-hidden", "true");
  const barEls = Array.from({ length: MIC_BAR_COUNT }, () => {
    const bar = document.createElement("span");
    bar.className = "mic-bar";
    bars.appendChild(bar);
    return bar;
  });
  button.appendChild(bars);
  const history = new Array(MIC_BAR_COUNT).fill(0);

  let tickCount = 0;
  let frame = null;
  let stopped = false;

  function startLoop() {
    if (stopped) return;
    frame = requestAnimationFrame(function tick() {
      if (stopped) return;
      analyser.getByteFrequencyData(data);
      let sum = 0;
      for (let i = 0; i < speechBinCount; i++) sum += data[i];
      const avg = sum / speechBinCount;
      if (tickCount % MIC_BAR_SAMPLE_EVERY === 0) {
        // sqrt, not linear: ordinary speaking volume sits low in the raw
        // 0-255 range, and a linear map leaves it barely above the resting
        // floor. The square root curve lifts quiet-to-moderate signal
        // (where a voice actually lives) without letting loud input clip.
        history.push(Math.sqrt(avg / 255));
        history.shift();
        history.forEach((level, i) => {
          // A silent bar never fully flattens, Voice Memos' own resting bars
          // read as "listening", a flat line reads as "frozen".
          barEls[i].style.setProperty("--bar-scale", Math.max(level, MIC_BAR_MIN_SCALE).toFixed(3));
        });
      }
      tickCount++;
      frame = requestAnimationFrame(tick);
    });
  }

  // Some browsers (including Chrome on Windows) create AudioContext suspended
  // even inside a click handler. The analyser returns all-zero until the
  // context is actually running. Wait for resume() to resolve rather than
  // firing the loop immediately and reading silence on the first N frames.
  // A small additional delay lets the OS audio stack fully open the device.
  ctx.resume().then(() => {
    setTimeout(startLoop, 150);
  }).catch(() => {
    // resume() failed: start anyway; if it's really suspended the bars just
    // stay at their floor scale, which is still visible and shows the button
    // is in recording state.
    setTimeout(startLoop, 150);
  });

  return () => {
    stopped = true;
    if (frame !== null) cancelAnimationFrame(frame);
    button.classList.remove("live-level");
    bars.remove();
    source.disconnect();
    ctx.close().catch(() => {});
  };
}

async function toggleDictation(button, targetInput) {
  if (recorder) {
    recorder.stop(); // second press = stop → transcribe
    return;
  }
  if (voiceStatus === null) {
    voiceStatus = await apiJson("/voice/status").catch(() => ({ available: false }));
  }
  if (!voiceStatus.available) {
    toast(voiceStatus.hint || "Voice capture isn't available.", true);
    return;
  }
  let stream;
  try {
    stream = await navigator.mediaDevices.getUserMedia({ audio: true });
  } catch {
    toast("Microphone access was blocked, allow it in your browser.", true);
    return;
  }
  //: **The button's resting label, read once and kept.** Reported: the word
  //: "Dictate" disappears the first time you record and never comes back.
  //: `setLabel` replaces every child of the button, so the two calls below
  //: were swapping the glyph and dropping the word with it; the stop handler
  //: then restored a bare microphone, which is the state the report describes.
  //:
  //: Read here rather than inside the stop handler because by then the only
  //: label on the button is "Stop", and kept on the element rather than in a
  //: closure because a second recording starts a new one. The chat mic
  //: (`#mic-chat`) is `icon-only` and has no `.ph-text` at all: it reads as an
  //: empty string and must stay that way, or it gains a word and stops being
  //: square.
  if (button.dataset.restLabel === undefined) {
    button.dataset.restLabel = button.querySelector(".ph-text")?.textContent?.trim() || "";
  }
  const resting = button.dataset.restLabel;
  const chunks = [];
  recorder = new MediaRecorder(stream);
  recorderTarget = targetInput;
  let stopLevelMeter = () => {};
  recorder.addEventListener("dataavailable", (e) => chunks.push(e.data));
  recorder.addEventListener("stop", async () => {
    stream.getTracks().forEach((t) => t.stop());
    stopLevelMeter();
    button.classList.remove("recording");
    setLabel(button, resting ? `ph:microphone ${resting}` : "ph:microphone");
    recorder = null;
    const blob = new Blob(chunks, { type: chunks[0]?.type || "audio/webm" });
    const form = new FormData();
    form.append("file", blob, "clip.webm");
    toast("Transcribing…");
    try {
      const response = await fetch("/voice/transcribe", {
        method: "POST",
        headers: { "X-Auth-Token": authToken() },
        body: form,
      });
      const body = await response.json();
      if (!response.ok) throw new Error(body.detail || "Transcription failed");
      const box = recorderTarget;
      box.value = box.value ? `${box.value.trimEnd()} ${body.text}` : body.text;
      box.focus();
    } catch (error) {
      toast(error.message, true);
    }
  });
  recorder.start();
  button.classList.add("recording");
  setLabel(button, resting ? "ph:stop Stop" : "ph:stop");
  // Appended after setLabel, not before: setLabel's replaceChildren() wipes
  // every child on the button, and the bar meter startMicLevelMeter() builds
  // is one: appending it earlier just got it discarded a line later.
  stopLevelMeter = startMicLevelMeter(stream, button);
}

// --- meeting notes (§17) -------------------------------------------------------------
//
// The backlog's own "highest-value single addition still unbuilt": the quick
// microphone button above is sized for a spoken note (server caps it at 25MB,
// `routes_voice.py`'s own comment says "a spoken note, not a podcast"), a
// meeting or a lecture needs a separate flow with its own recording cap, a
// visible elapsed timer so a long recording doesn't feel stalled, and a
// review step before the transcript becomes a note, the same "you're in
// control before it's saved" shape the persona-peek and compression-summary
// features already use elsewhere.
//
// Action-item extraction (the other half of §17's ask, "extract action items
// into reminders") is deliberately not built here. It needs a real model
// call this sandbox cannot exercise, faster-whisper itself is not installed
// here either, so even the transcription step is untested past its request
// shape: and guessing at that prompt's behaviour without a way to check it
// is exactly what CLAUDE.md's standing caveat warns against. Recording it as
// open rather than quietly shipping an unverified guess.

let meetingRecorder = null;
let meetingStream = null;
let meetingChunks = [];
let meetingTimerHandle = null;
let meetingStartedAt = 0;

function meetingElapsedText() {
  const seconds = Math.max(0, Math.round((Date.now() - meetingStartedAt) / 1000));
  const m = Math.floor(seconds / 60);
  const s = seconds % 60;
  return `${m}:${String(s).padStart(2, "0")}`;
}

//: How many amplitude samples the waveform holds. About four seconds at the
//: sample rate below, which is enough to see the shape of a sentence without
//: the line becoming a texture.
const MEETING_WAVE_POINTS = 140;
//: Frames between samples. Every frame would fill the window in two seconds
//: and spend a redraw on a difference nobody can see.
const MEETING_WAVE_EVERY = 3;

//: Kept at module level so `closeMeetingRecorder` can stop a draw loop that
//: `toggleMeetingRecording` started: the two are different user actions and
//: neither can reach the other's locals.
let stopMeetingWave = () => {};

// The line that moves while you talk. See the note in index.html for why the
// six-bar meter on the Record button was not enough: a recording with no
// visible response to your voice is indistinguishable from a broken
// microphone, and that is what was actually being reported.
function startMeetingWave(stream) {
  const canvas = document.getElementById("meeting-wave");
  if (!canvas) return () => {};
  let ctx;
  try {
    ctx = new (window.AudioContext || window.webkitAudioContext)();
  } catch {
    return () => {}; // no Web Audio: the recording itself is unaffected
  }
  const analyser = ctx.createAnalyser();
  // 2048 in the *time* domain: this draws a level line, and a bigger window
  // gives a steadier RMS than the 256-bin frequency analyser the button meter
  // uses. Both can run at once, they are separate nodes on the same stream.
  analyser.fftSize = 2048;
  ctx.createMediaStreamSource(stream).connect(analyser);
  const samples = new Uint8Array(analyser.fftSize);
  const levels = new Array(MEETING_WAVE_POINTS).fill(0);

  const paint = canvas.getContext("2d");
  canvas.classList.remove("hidden");
  // Size the backing store to the box it is actually drawn in, at the
  // device's own pixel density. The markup's 960×120 is a fallback for the
  // frame before layout; leaving it there stretches the line horizontally and
  // makes it soft on any HiDPI screen. Measured after `remove("hidden")`, 
  // a hidden element has no width to read.
  const box = canvas.getBoundingClientRect();
  const ratio = Math.min(window.devicePixelRatio || 1, 2);
  if (box.width) {
    canvas.width = Math.round(box.width * ratio);
    canvas.height = Math.round(box.height * ratio);
  }
  let frame = null;
  let ticks = 0;
  let stopped = false;

  function draw() {
    const { width, height } = canvas;
    const middle = height / 2;
    paint.clearRect(0, 0, width, height);
    // The accent, read from the live stylesheet rather than hard-coded, so
    // the line follows whatever theme is set, including a custom one.
    const accent =
      getComputedStyle(document.documentElement).getPropertyValue("--accent").trim() ||
      "#4664f0";
    paint.strokeStyle = accent;
    paint.lineWidth = 2;
    paint.lineJoin = "round";
    paint.lineCap = "round";
    const step = width / (levels.length - 1);
    // Two mirrored strokes rather than one: a level line drawn only upward
    // reads as a graph, and the symmetrical pair reads as sound.
    for (const direction of [-1, 1]) {
      paint.beginPath();
      levels.forEach((level, i) => {
        const y = middle + direction * level * (middle - 4);
        if (i === 0) paint.moveTo(0, y);
        else paint.lineTo(i * step, y);
      });
      paint.stroke();
    }
  }

  function tick() {
    if (stopped) return;
    if (ticks % MEETING_WAVE_EVERY === 0) {
      analyser.getByteTimeDomainData(samples);
      // RMS around the 128 midpoint, the honest measure of loudness, and
      // steadier than a peak, which flickers on consonants.
      let sum = 0;
      for (let i = 0; i < samples.length; i++) {
        const value = (samples[i] - 128) / 128;
        sum += value * value;
      }
      const rms = Math.sqrt(sum / samples.length);
      // sqrt again for the same reason the bar meter gives: ordinary speech
      // sits low in the range and a linear map leaves it near the floor.
      levels.push(Math.min(1, Math.sqrt(rms) * 1.6));
      levels.shift();
      draw();
    }
    ticks++;
    frame = requestAnimationFrame(tick);
  }

  // Chrome creates an AudioContext suspended even inside a click handler, and
  // the analyser reads all-zero until it is running, the same trap the bar
  // meter documents. Start the loop after resume resolves.
  ctx.resume().then(tick, tick);

  return () => {
    stopped = true;
    if (frame) cancelAnimationFrame(frame);
    ctx.close().catch(() => {});
    canvas.classList.add("hidden");
    paint.clearRect(0, 0, canvas.width, canvas.height);
  };
}

function stopMeetingTimer() {
  if (meetingTimerHandle) clearInterval(meetingTimerHandle);
  meetingTimerHandle = null;
}

// Resets the overlay to "ready to record", whether it's opening fresh or
// coming back after a discard, the same state either way.
function resetMeetingUI() {
  $("meeting-timer").textContent = "0:00";
  $("meeting-status").textContent = "";
  $("meeting-status").classList.remove("error");
  $("meeting-transcript").value = "";
  $("meeting-transcript").classList.add("hidden");
  $("meeting-save-row").classList.add("hidden");
  $("meeting-record").disabled = false;
  $("meeting-record").classList.remove("recording");
  setLabel($("meeting-record"), "ph:record Record");
  $("meeting-pause")?.classList.add("hidden");
  setLabel($("meeting-pause"), "ph:pause Pause");
  $("meeting-wave")?.classList.add("hidden");
}

async function openMeetingRecorder() {
  overlayReturnFocus = document.activeElement;
  resetMeetingUI();
  $("meeting-overlay").classList.remove("hidden");
  $("meeting-record").focus();
}

// Recording is stopped (discarded, not transcribed) rather than left running
// in the background: a MediaRecorder with no owner is a live microphone
// nobody is looking at.
function closeMeetingRecorder() {
  if (meetingRecorder && meetingRecorder.state !== "inactive") {
    meetingRecorder.onstop = null; // don't also try to transcribe a discard
    meetingRecorder.stop();
  }
  meetingStream?.getTracks().forEach((t) => t.stop());
  stopMeetingWave();
  stopMeetingWave = () => {};
  meetingRecorder = null;
  meetingStream = null;
  stopMeetingTimer();
  $("meeting-overlay").classList.add("hidden");
  overlayReturnFocus?.focus?.();
  overlayReturnFocus = null;
}

async function toggleMeetingRecording() {
  const button = $("meeting-record");
  if (meetingRecorder) {
    button.disabled = true; // one press, not a double-fire while it stops
    meetingRecorder.stop();
    return;
  }
  if (voiceStatus === null) {
    voiceStatus = await apiJson("/voice/status").catch(() => ({ available: false }));
  }
  if (!voiceStatus.available) {
    $("meeting-status").textContent = voiceStatus.hint || "Voice capture isn't available.";
    $("meeting-status").classList.add("error");
    return;
  }
  try {
    meetingStream = await navigator.mediaDevices.getUserMedia({ audio: true });
  } catch {
    $("meeting-status").textContent = "Microphone access was blocked, allow it in your browser.";
    $("meeting-status").classList.add("error");
    return;
  }
  meetingChunks = [];
  meetingRecorder = new MediaRecorder(meetingStream);
  let stopMeetingLevelMeter = () => {};
  meetingRecorder.addEventListener("dataavailable", (e) => meetingChunks.push(e.data));
  meetingRecorder.addEventListener("stop", async () => {
    meetingStream?.getTracks().forEach((t) => t.stop());
    stopMeetingLevelMeter();
    stopMeetingWave();
    stopMeetingWave = () => {};
    $("meeting-pause").classList.add("hidden");
    meetingStream = null;
    meetingRecorder = null;
    stopMeetingTimer();
    button.classList.remove("recording");
    setLabel(button, "ph:record Record");
    button.disabled = false;
    const blob = new Blob(meetingChunks, { type: meetingChunks[0]?.type || "audio/webm" });
    const form = new FormData();
    form.append("file", blob, "meeting.webm");
    $("meeting-status").classList.remove("error");
    $("meeting-status").textContent =
      "Transcribing… a long recording can take a while on CPU.";
    try {
      const response = await fetch("/voice/transcribe-meeting", {
        method: "POST",
        headers: { "X-Auth-Token": authToken() },
        body: form,
      });
      const body = await response.json();
      if (!response.ok) throw new Error(body.detail || "Transcription failed");
      $("meeting-status").textContent = "Transcribed: review it below before saving.";
      $("meeting-transcript").value = body.text;
      $("meeting-transcript").classList.remove("hidden");
      $("meeting-save-row").classList.remove("hidden");
      $("meeting-transcript").focus();
    } catch (error) {
      $("meeting-status").textContent = error.message;
      $("meeting-status").classList.add("error");
    }
  });
  meetingRecorder.start();
  meetingStartedAt = Date.now();
  $("meeting-timer").textContent = meetingElapsedText();
  meetingTimerHandle = setInterval(() => {
    $("meeting-timer").textContent = meetingElapsedText();
  }, 1000);
  button.classList.add("recording");
  setLabel(button, "ph:stop Stop");
  // Appended after setLabel, not before: setLabel's replaceChildren() wipes
  // every child on the button, and the bar meter startMicLevelMeter() builds
  // is one: appending it earlier just got it discarded a line later.
  stopMeetingLevelMeter = startMicLevelMeter(meetingStream, button);
  stopMeetingWave = startMeetingWave(meetingStream);
  $("meeting-pause").classList.remove("hidden");
  $("meeting-status").textContent = "";
  $("meeting-status").classList.remove("error");
}

// Pause and resume, which a MediaRecorder supports directly, the chunks
// simply stop arriving and the recording continues where it left off. Asked
// for as part of "expanded as a proper feature with more capabilities", and
// it is the one a real meeting needs: someone leaves the room, a side
// conversation starts, and the alternative today is stopping and starting a
// second recording that transcribes as a separate transcript.
//
// The elapsed timer is corrected on resume rather than left running: it is
// showing how long the *recording* is, and a paused stretch is not in it.
let meetingPausedAt = 0;

function toggleMeetingPause() {
  if (!meetingRecorder) return;
  const button = $("meeting-pause");
  if (meetingRecorder.state === "recording") {
    meetingRecorder.pause();
    meetingPausedAt = Date.now();
    stopMeetingTimer();
    setLabel(button, "ph:play Resume");
    $("meeting-status").textContent = "Paused.";
  } else if (meetingRecorder.state === "paused") {
    meetingRecorder.resume();
    // Push the start forward by however long the pause lasted, so the timer
    // keeps reading as the length of the audio rather than of the sitting.
    meetingStartedAt += Date.now() - meetingPausedAt;
    meetingTimerHandle = setInterval(() => {
      $("meeting-timer").textContent = meetingElapsedText();
    }, 1000);
    setLabel(button, "ph:pause Pause");
    $("meeting-status").textContent = "";
  }
}

// An hour of transcript is not a note. In the Notes list it is one enormous
// card nobody can scroll past; as a document it is something you can open,
// edit, extract notes from and export, which is what the rest of this app
// already does well with long text.
async function saveMeetingDocument() {
  const content = $("meeting-transcript").value.trim();
  if (!content) return;
  const status = $("meeting-status");
  const button = $("meeting-save-doc");
  button.disabled = true;
  status.classList.remove("error");
  status.textContent = "Saving…";
  try {
    const title =
      ($("meeting-title")?.value || "").trim() ||
      `Recording: ${new Date().toLocaleString()}`;
    const document_ = await apiJson("/documents", {
      method: "POST",
      body: JSON.stringify({ title, content }),
    });
    closeMeetingRecorder();
    switchTab("documents");
    openDocument(document_.id);
    toast(`Saved “${title}” to your documents.`);
  } catch (error) {
    status.textContent = error.message || "Couldn't save that.";
    status.classList.add("error");
  } finally {
    button.disabled = false;
  }
}

async function saveMeetingNote() {
  const content = $("meeting-transcript").value.trim();
  if (!content) return;
  const status = $("meeting-status");
  const button = $("meeting-save");
  button.disabled = true;
  status.classList.remove("error");
  status.textContent = "Summarizing…";
  try {
    // Best-effort, same contract as suggest-tags: a model that's offline or
    // errors must never block filing the note, so any failure here just
    // means no summary block gets prepended, not a stalled save.
    let summary = "";
    try {
      const result = await apiJson("/voice/summarize", {
        method: "POST",
        body: JSON.stringify({ text: content }),
      });
      summary = (result?.summary || "").trim();
    } catch {
      summary = "";
    }

    status.textContent = "Filing…";
    // Tagged, not force-categorised: filing still goes through the same
    // AI-or-keyword pipeline as any other capture (routes_entries.py), so a
    // meeting about a specific project lands there rather than in a generic
    // "Meetings" bucket regardless of what it was actually about. The tag is
    // what makes every meeting findable as a class either way.
    // The title, when one was typed, becomes the note's first line: which is
    // what every list in this app shows as its name. Without it a saved
    // recording is titled by whatever word the transcript happens to open on.
    const title = ($("meeting-title")?.value || "").trim();
    const body = summary ? `${summary}\n\n---\n\n${content}` : content;
    const saved = await apiJson("/entries", {
      method: "POST",
      body: JSON.stringify({
        content: title ? `${title}\n\n${body}` : body,
        tags: ["meeting"],
      }),
    });
    toast(filedByText(saved));
    await loadEntries();
    // The overlay is about to close, so this jumps straight to the note
    // rather than leaving an "offer" button behind in a dialog nobody is
    // looking at anymore (`offerJumpToNewNote`'s pattern, used from the
    // Capture tab you're still sitting on), `flashEntry` handles its own
    // navigation to Notes → Browse.
    closeMeetingRecorder();
    flashEntry(saved.id);
  } catch (error) {
    status.textContent = error.message;
    status.classList.add("error");
  } finally {
    button.disabled = false;
  }
}

// --- Wave H: read-aloud (the browser's local voices) --------------------------------

function speakText(text) {
  if (!("speechSynthesis" in window)) {
    toast("This browser has no text-to-speech voices.", true);
    return;
  }
  if (speechSynthesis.speaking) {
    speechSynthesis.cancel(); // acting as a stop button
    return;
  }
  if (text.trim()) speechSynthesis.speak(new SpeechSynthesisUtterance(text));
}

// --- toasts (Phase 5) ---------------------------------------------------------------

// --- reminders you actually notice (§36C) ------------------------------------------
//
// Reported: "reminders when they go off aren't really noticeable and need to be
// more evident, maybe through a browser or system/app notification?"
//
// The reason they were unnoticeable is simpler than it sounds: **nothing
// checked.** A reminder's only surface was a small badge on the Reminders tab
// button, painted by `updateReminderBadge`, which only ran when something
// happened to call `loadReminders()`. So unless you reloaded, or visited that
// tab, a reminder came due and the interface said nothing at all, forever.
//
// Three surfaces now, in increasing order of how much they interrupt:
//   · the tab badge, as before;
//   · a count in the document title, which is visible from another tab or a
//     taskbar without the app being focused;
//   · a system notification and a toast, once per reminder.
//
// The honest limit, stated because the alternative is implying otherwise:
// none of this fires while the app is closed. A local-first app with no
// background service cannot wake itself up, and pretending it can would be
// worse than the gap.

//: 60s, was 30. A reminder is due to the minute, so once a minute is the
//: granularity the data has; the second poll a minute bought nothing and was
//: two of the fourteen idle requests PLAN.md P1 counts against.
const REMINDER_POLL_MS = 60_000;
//: Which reminders have already been announced, so a once-a-minute poll does not
//: re-fire the same notification twice a minute. Kept in localStorage rather
//: than memory: a reload would otherwise re-announce everything overdue, which
//: is the most annoying possible version of this feature.
const ANNOUNCED_KEY = "announcedReminders";

function announcedReminders() {
  try {
    return new Set(JSON.parse(localStorage.getItem(ANNOUNCED_KEY) || "[]"));
  } catch {
    return new Set();
  }
}

function rememberAnnounced(ids) {
  // Bounded, and trimmed from the front: without a cap this grows forever in a
  // notebook that has been used for years.
  const kept = [...announcedReminders(), ...ids].slice(-200);
  localStorage.setItem(ANNOUNCED_KEY, JSON.stringify(kept));
}

// --- the notifications centre (§36E) ----------------------------------------
//
// MemoryMap already *produces* all of these events, a reminder comes due, a
// background task finishes, a skill run stalls, and shows each of them in its
// own way: a system notification, a toast, a status pill, a step timeline.
// Every one of those is a moment. Miss the moment and the event is gone.
//
// This is the place they persist after their moment has passed, which is the
// whole of what §36E asks for. Three things it is deliberately *not*:
//
// - **Not a second source of truth.** A fired reminder is still a row in the
//   reminders table; this records that it was announced, and the panel folds
//   in whatever is *currently* overdue from the server when it opens. So a
//   reminder that came due while the app was closed is not lost, even though
//   nothing was running to record it, which is the one case a purely
//   event-driven log cannot cover.
// - **Not persisted to the server.** These are ephemeral by nature and there
//   can be many of them; the notebook's preferences file is not a log.
// - **Not a promise that anything fires while the app is shut.** A local-first
//   app with no background service cannot do that, and §36C says so plainly
//   rather than implying otherwise.

const NOTIFICATIONS_KEY = "notifications";
const NOTIFICATIONS_READ_KEY = "notificationsReadAt";
//: Enough to answer "what did I miss?" and not enough to become a log file.
const MAX_NOTIFICATIONS = 50;

function storedNotifications() {
  try {
    const raw = JSON.parse(localStorage.getItem(NOTIFICATIONS_KEY) || "[]");
    return Array.isArray(raw) ? raw : [];
  } catch {
    return []; // hand-edited or truncated storage costs the history, not the app
  }
}

// Record something worth remembering. `key` de-duplicates: the reminder poll
// runs every thirty seconds and must not add the same fired reminder twice.
function recordNotification({ kind, title, detail = "", key = "", action = null }) {
  if (kind !== "reminder" && notificationsMuted()) return;
  const items = storedNotifications();
  const id = key || `${kind}:${title}:${Date.now()}`;
  if (key && items.some((n) => n.id === id)) return;
  items.push({ id, kind, title, detail, at: Date.now(), action });
  localStorage.setItem(
    NOTIFICATIONS_KEY,
    JSON.stringify(items.slice(-MAX_NOTIFICATIONS))
  );
  renderNotificationBadge();
}

function notificationsReadAt() {
  return Number(localStorage.getItem(NOTIFICATIONS_READ_KEY) || 0);
}

//: **Read state is a watermark, and "mark this one unread" is not.**
//:
//: Asked for directly: "also allow marking notifications as unread as well."
//: Opening the panel stamps `notificationsReadAt` with the current time, and
//: everything older than the stamp is read, which is the right model for
//: "I've seen the list" and cannot express "…except that one, I want to come
//: back to it." Rewinding the watermark to just before that item would mark
//: everything after it unread too.
//:
//: So a small set of ids sits alongside the watermark and overrides it. It
//: holds only the exceptions, which is a handful at most, and "mark all read"
//: empties it: that action means the same thing either way.
const NOTIFICATIONS_UNREAD_KEY = "notificationsForcedUnread";

function forcedUnreadIds() {
  try {
    const raw = JSON.parse(localStorage.getItem(NOTIFICATIONS_UNREAD_KEY) || "[]");
    return new Set(Array.isArray(raw) ? raw : []);
  } catch {
    return new Set(); // a corrupt override list costs the flags, not the panel
  }
}

function setForcedUnreadIds(ids) {
  try {
    //: Pruned to what is still in the history: `MAX_NOTIFICATIONS` drops old
    //: rows, and an override for a row nobody can see any more would sit in
    //: storage forever keeping the badge count wrong.
    const live = new Set(storedNotifications().map((item) => item.id));
    const kept = [...ids].filter((id) => live.has(id));
    localStorage.setItem(NOTIFICATIONS_UNREAD_KEY, JSON.stringify(kept));
  } catch {
    /* private mode: the flag just will not be remembered */
  }
}

//: **Marking one row read must not mark the rest read.** Reported: "when I
//: tick mark as complete on a single notification it does that for all of
//: them." The old code moved the *watermark* up to that row's timestamp,
//: and the watermark is "everything older than this is read", so ticking
//: the newest row silently read every row beneath it. A second override set,
//: the mirror of `forcedUnreadIds`, holds rows read *ahead* of the watermark;
//: the watermark itself only ever moves on "mark all" / opening the panel.
const NOTIFICATIONS_READ_IDS_KEY = "notificationsForcedRead";

function forcedReadIds() {
  try {
    const raw = JSON.parse(localStorage.getItem(NOTIFICATIONS_READ_IDS_KEY) || "[]");
    return new Set(Array.isArray(raw) ? raw : []);
  } catch {
    return new Set();
  }
}

function setForcedReadIds(ids) {
  try {
    const known = new Set(storedNotifications().map((n) => n.id));
    localStorage.setItem(NOTIFICATIONS_READ_IDS_KEY, JSON.stringify([...ids].filter((id) => known.has(id))));
  } catch {
    // Storage refused: the flag is lost, the panel is not.
  }
}

function isNotificationUnread(item, readAt = notificationsReadAt(), forced = forcedUnreadIds(), read = forcedReadIds()) {
  if (forced.has(item.id)) return true;
  if (read.has(item.id)) return false;
  return item.at > readAt;
}

function setNotificationUnread(id, unread) {
  const unreadIds = forcedUnreadIds();
  const readIds = forcedReadIds();
  if (unread) { unreadIds.add(id); readIds.delete(id); }
  else { unreadIds.delete(id); readIds.add(id); }
  setForcedUnreadIds(unreadIds);
  setForcedReadIds(readIds);
  renderNotificationBadge();
}

function unreadNotifications() {
  const since = notificationsReadAt();
  const forced = forcedUnreadIds();
  return storedNotifications().filter((n) => isNotificationUnread(n, since, forced));
}

function renderNotificationBadge() {
  const button = $("notif-btn");
  if (!button) return;
  const count = unreadNotifications().length;
  button.dataset.count = count > 9 ? "9+" : String(count || "");
  button.classList.toggle("has-unread", count > 0);
  const muted = notificationsMuted();
  // The bell itself says whether anything but a reminder will actually get
  // through: asked for directly, so muting isn't a setting you have to
  // remember you turned on three screens away.
  setLabel(button, muted ? "ph:bell-slash" : "ph:bell");
  button.setAttribute(
    "aria-label",
    (count ? `Notifications: ${count} unread` : "Notifications") +
      (muted ? " (muted except reminders)" : "")
  );
}

// The mute toggle's own state, kept in sync wherever it's shown: the bell
// icon above, and this button inside the panel it opens.
function renderNotifMuteToggle() {
  const button = $("notif-mute-toggle");
  if (!button) return;
  const muted = notificationsMuted();
  setLabel(button, muted ? "ph:bell-slash" : "ph:bell");
  // button.textContent = muted ? "Bell Unmute" : "bell slash Mute";
  button.title = muted
    ? "Stop muting: everything will notify again"
    : "Mute notifications except reminders";
  button.setAttribute("aria-pressed", String(muted));
  //: Icon-only since the head lost its second row, so the tooltip is no
  //: longer backed by a visible word, the accessible name has to carry it.
  button.setAttribute("aria-label", button.title);
  button.classList.toggle("active", muted);
}

async function toggleNotificationMute() {
  const next = !notificationsMuted();
  prefsCache = await apiJson("/preferences", {
    method: "PUT",
    body: JSON.stringify({ notifications_muted_except_reminders: next }),
  });
  renderNotifMuteToggle();
  renderNotificationBadge();
}

$("notif-activity-mode")?.addEventListener("change", async (event) => {
  const value = event.currentTarget.value === "centre" ? "centre" : "toasts";
  try {
    prefsCache = await apiJson("/preferences", {
      method: "PUT",
      body: JSON.stringify({ agent_activity_notices: value }),
    });
  } catch (error) {
    toast(error.message || "Couldn't save that.", true);
  }
  renderAgentActivityMode();
});

//: Which icon a kind gets. Colour alone is never the signal (DESIGN.md), and
//: these read as a list of *kinds* rather than a list of times.
const NOTIFICATION_ICONS = {
  reminder: "ph:alarm",
  task: "ph:gear",
  run: "ph:lightning",
  error: "ph:warning",
  info: "•",
};

//: `keepWatermark`: a re-render from a row's own read/unread toggle must
//: not also stamp the "seen everything" watermark: that is what made one
//: tick mark every unread row as read (reported twice).
async function openNotifications({ keepWatermark = false } = {}) {
  const panel = $("notif-panel");
  const list = $("notif-list");
  panel.classList.remove("hidden");
  renderNotifMuteToggle();
  renderAgentActivityMode();

  // Fold in anything currently overdue on the server. This is what makes the
  // centre honest about time it was not running for: the event log can only
  // know what happened while a tab was open, and the reminders table knows
  // what is due regardless.
  const all = await apiJson("/reminders", { silent: true }).catch(() => null);
  for (const reminder of all || []) {
    if (reminder.done) continue;
    if (new Date(reminder.due_at).getTime() > Date.now()) continue;
    recordNotification({
      kind: "reminder",
      title: reminder.text,
      detail: `Due ${relativeTime(reminder.due_at)}`,
      key: `reminder:${reminder.id}`,
      action: { tab: "reminders" },
    });
  }

  const items = storedNotifications().slice().reverse();
  const readAt = notificationsReadAt();
  //: The count, beside the word it qualifies. The bell in the header already
  //: carries it, but the bell is what you clicked to get here, inside the
  //: panel the number has to say how many of the rows below are new.
  const forced = forcedUnreadIds();
  const chip = $("notif-unread");
  if (chip) {
    const unread = items.filter((item) => isNotificationUnread(item, readAt, forced)).length;
    chip.textContent = unread > 99 ? "99+" : String(unread);
    chip.classList.toggle("hidden", unread === 0);
    chip.title = `${unread} unread`;
  }
  list.replaceChildren();
  //: **An empty state, not a paragraph.** Reported with a screenshot: three
  //: lines of muted prose filled the panel where nothing had happened, which
  //: reads as an error message rather than as calm. The shape every other
  //: empty surface in this app uses, a glyph, a short line, and the
  //: explanation underneath in small text, says the same thing in a glance.
  if (!items.length) {
    const empty = document.createElement("li");
    empty.className = "notif-empty";
    const glyph = document.createElement("span");
    glyph.className = "notif-empty-icon";
    setLabel(glyph, "ph:bell-simple");
    glyph.setAttribute("aria-hidden", "true");
    const headline = document.createElement("p");
    headline.className = "notif-empty-title";
    headline.textContent = "You're all caught up";
    const sub = document.createElement("p");
    sub.className = "muted text-sm notif-empty-sub";
    sub.textContent =
      "Reminders that come due, finished background jobs and runs that " +
      "stopped early collect here.";
    empty.append(glyph, headline, sub);
    list.appendChild(empty);
  }
  for (const item of items) {
    const row = document.createElement("li");
    row.className = "notif-row";
    const unread = isNotificationUnread(item, readAt, forced);
    if (unread) row.classList.add("notif-unread");

    const icon = document.createElement("span");
    icon.className = "notif-icon";
    setLabel(icon, NOTIFICATION_ICONS[item.kind] || NOTIFICATION_ICONS.info);
    icon.setAttribute("aria-hidden", "true");

    const body = document.createElement("div");
    body.className = "notif-body";
    //: Title and time on one line, detail underneath. Reported with a
    //: screenshot: the time was glued to the end of a three-line detail
    //: and the title wrapped under a 2.25rem "mark read" button: the row
    //: read as a paragraph with a random button, not as a notification.
    const head = document.createElement("div");
    head.className = "notif-row-head";
    const title = document.createElement("span");
    title.className = "notif-title";
    setLabel(title, item.title);
    const time = document.createElement("time");
    time.className = "notif-time muted";
    time.dateTime = new Date(item.at).toISOString();
    time.textContent = relativeTime(time.dateTime);
    time.title = new Date(item.at).toLocaleString();
    head.append(title, time);
    body.append(head);
    if (item.detail) {
      const meta = document.createElement("div");
      meta.className = "notif-meta muted";
      meta.textContent = item.detail;
      body.append(meta);
    }
    row.append(icon, body);

    //: The dot is the control. A row is either new or it is not, so this is a
    //: two-state toggle rather than a menu, and it sits where the "new"
    //: marker already is, so pressing the thing that says "unread" is what
    //: changes whether it is unread. `stopPropagation` because the row itself
    //: may navigate somewhere, and "keep this for later" is the opposite of
    //: "take me there now".
    const readToggle = document.createElement("button");
    readToggle.type = "button";
    readToggle.className = "ghost small icon-only notif-read-toggle";
    readToggle.setAttribute("aria-pressed", String(unread));
    readToggle.title = unread ? "Mark as read" : "Mark as unread";
    readToggle.setAttribute("aria-label", readToggle.title);
    setLabel(readToggle, unread ? "ph:circle" : "ph:check-circle");
    readToggle.addEventListener("click", (event) => {
      event.stopPropagation();
      // Reported: "the individual mark as complete buttons don't work". A
      // row from before ids were stamped has no `item.id`, so the override
      // set had nothing to add and the click changed nothing visible. Stamp
      // one from its timestamp, stable across renders, unique enough.
      if (item.id == null) {
        item.id = `n-${item.at}`;
        const all = storedNotifications();
        const same = all.find((entry) => entry.at === item.at && entry.id == null);
        if (same) { same.id = item.id; localStorage.setItem(NOTIFICATIONS_KEY, JSON.stringify(all)); }
      }
      setNotificationUnread(item.id, !unread);
      openNotifications({ keepWatermark: true });
    });
    row.append(readToggle);

    // A notification you cannot act on is a notification you learn to ignore.
    if (item.action && item.action.tab) {
      row.classList.add("notif-actionable");
      row.tabIndex = 0;
      row.title = "Open";
      const go = () => {
        closeNotifications();
        switchTab(item.action.tab);
      };
      row.addEventListener("click", go);
      row.addEventListener("keydown", (event) => {
        if (event.key === "Enter" || event.key === " ") {
          event.preventDefault();
          go();
        }
      });
    }
    list.appendChild(row);
  }

  // Opening the panel *is* reading them. Marked after rendering, so the
  // unread ones are still highlighted in the list you are looking at.
  //
  // The overrides survive it: a row deliberately kept unread must not be
  // cleared by looking at the panel, or "mark as unread" would last exactly
  // until the next time the bell is opened, which is no time at all.
  // The watermark moves on *close*, not on open (see closeNotifications):
  // while the panel is up, an unread row stays unread, so ticking one row
  // changes one row. Opening used to stamp it, and the next re-render, 
  // the one a tick causes, then showed every row as read (reported twice
  // as "mark one, all get marked").
  renderNotificationBadge();
}

function closeNotifications() {
  const panel = $("notif-panel");
  if (panel.classList.contains("hidden")) return;
  panel.classList.add("hidden");
  // Closing the panel is reading it: everything shown is now old news,
  // except rows deliberately kept unread (the override set survives).
  localStorage.setItem(NOTIFICATIONS_READ_KEY, String(Date.now()));
  renderNotificationBadge();
}

// Asked when a reminder is SET, not on first load. A permission prompt with no
// context is refused by default, and a refusal is close to permanent, the
// browser will not ask again, and most people never find the site settings.
function askNotificationPermission() {
  if ("Notification" in window && Notification.permission === "default") {
    Notification.requestPermission().catch(() => {});
  }
}

// A reminder firing had only a toast (5.5s, gone if you looked away) and an
// OS notification that never arrives without permission having been granted
// earlier. Reported directly: "half the time when reminders go off I don't
// actually notice". A short chime is a third, independent channel, audible
// with the tab backgrounded, and unlike the OS notification needs no
// permission at all.
//
// Created lazily on the first real user gesture rather than eagerly on load:
// browsers refuse to start an AudioContext with sound before one, and
// `checkDueReminders` runs off a timer with no gesture of its own. The
// context, once unlocked this way, keeps working for timer-driven calls for
// the rest of the session, the unlock is per-context, not per-call.
let reminderAudioCtx = null;
function primeReminderAudio() {
  if (reminderAudioCtx) return;
  try {
    reminderAudioCtx = new (window.AudioContext || window.webkitAudioContext)();
  } catch {
    // No Web Audio support, reminders still show as a toast/notification.
  }
}
document.addEventListener("pointerdown", primeReminderAudio, { once: true });
document.addEventListener("keydown", primeReminderAudio, { once: true });

function playReminderChime() {
  if (!reminderAudioCtx) return;
  reminderAudioCtx.resume().catch(() => {});
  const now = reminderAudioCtx.currentTime;
  // Two short notes, rising, reads as "an alert" rather than a UI click,
  // without being long or harsh enough to be reached for on a repeat.
  for (const [i, freq] of [523.25, 659.25].entries()) {
    const osc = reminderAudioCtx.createOscillator();
    const gain = reminderAudioCtx.createGain();
    osc.type = "sine";
    osc.frequency.value = freq;
    const start = now + i * 0.14;
    gain.gain.setValueAtTime(0, start);
    gain.gain.linearRampToValueAtTime(0.18, start + 0.02);
    gain.gain.exponentialRampToValueAtTime(0.001, start + 0.32);
    osc.connect(gain).connect(reminderAudioCtx.destination);
    osc.start(start);
    osc.stop(start + 0.34);
  }
}

//: How long a system notification stays up before this app closes it itself.
//: Reported as notifications that "never auto close and stay open until the
//: user closes them", which is exactly what a `Notification` does when
//: nobody calls `close()` on it: the banner's own fade is the *shell's*
//: behaviour, and the notification object outlives it, sitting in the OS
//: notification centre (and, in the desktop WebView, sometimes on screen)
//: until dismissed by hand. The web platform has no `timeout` option, so the
//: only way to auto-close one is to close it.
//:
//: Longer than a toast's 5.5s because a system notification is for the case
//: where the app is not the window you are looking at.
const NOTIFICATION_AUTOCLOSE_MS = 12000;

function notify(title, body) {
  if ("Notification" in window && Notification.permission === "granted") {
    try {
      const shown = new Notification(title, {
        body,
        icon: "/favicon.svg",
        tag: "memorymap",
      });
      setTimeout(() => {
        try {
          shown.close();
        } catch {
          // A notification the OS already disposed of. Closing twice is not
          // an error worth a line in the console.
        }
      }, NOTIFICATION_AUTOCLOSE_MS);
      return true;
    } catch {
      // Some embedded shells expose the constructor and then throw. Falling
      // through to the toast is the point of returning a boolean.
    }
  }
  return false;
}

// The count in the title bar, the one surface that works while the app is in
// a background tab, which is where it usually is when a reminder comes due.
const BASE_TITLE = "MemoryMap AI";
function setTitleCount(count) {
  document.title = count > 0 ? `(${count}) ${BASE_TITLE}` : BASE_TITLE;
}

async function checkDueReminders() {
  // Before the unlock there is no token, and asking anyway is a guaranteed 401
  // on every load: visible in the browser's network log, and in the server's
  // own log, where it looks like an auth failure worth investigating.
  if (!authToken()) return;
  const all = await apiJson("/reminders", { silent: true }).catch(() => null);
  if (!all) return; // server asleep or locked, say nothing rather than guess
  const now = Date.now();
  const due = all.filter((r) => !r.done && new Date(r.due_at).getTime() <= now);
  updateReminderBadge(all);
  setTitleCount(due.length);

  const already = announcedReminders();
  const fresh = due.filter((r) => !already.has(r.id));
  if (!fresh.length) return;
  rememberAnnounced(fresh.map((r) => r.id));
  playReminderChime();

  // Into the centre as well as onto the screen (§36E). A toast and a system
  // notification are both moments; this is the record that outlives them, and
  // it is the difference between "I think something was due" and knowing what.
  for (const reminder of fresh) {
    recordNotification({
      kind: "reminder",
      title: reminder.text,
      detail: "Came due",
      key: `reminder:${reminder.id}`,
      action: { tab: "reminders" },
    });
  }

  // One notification for one reminder; a summary for several, because three
  // separate system notifications for three reminders is worse than one.
  if (fresh.length === 1) {
    const text = fresh[0].text;
    if (!notify("Reminder", text)) toast(text, false, { exempt: true });
  } else {
    const summary = `${fresh.length} reminders are due`;
    if (!notify("MemoryMap", summary)) toast(summary, false, { exempt: true });
  }
  // Always in-app as well as out: a system notification can be suppressed by
  // Do Not Disturb without the app ever knowing.
  if ("Notification" in window && Notification.permission === "granted") {
    toast(
      fresh.length === 1 ? fresh[0].text : `${fresh.length} reminders are due`,
      false,
      { exempt: true }
    );
  }
  loadReminders().catch(() => {});
}

function startReminderWatch() {
  checkDueReminders();
  setInterval(checkDueReminders, REMINDER_POLL_MS);
  // A machine that was asleep wakes up with reminders long past due, and the
  // interval will not have run. Checking on focus catches that immediately
  // rather than up to a minute later.
  window.addEventListener("focus", () => checkDueReminders());
  document.addEventListener("visibilitychange", () => {
    if (!document.hidden) checkDueReminders();
  });
}

// Asked directly: "an option to mute notifications except for reminders".
// A reminder toast passes `exempt: true` so it still gets through; an error
// always does too: silencing a real failure would hide the thing muting is
// least meant to hide. Everything else (background jobs, agent runs, general
// activity) is what the toggle actually quiets.
function notificationsMuted() {
  return Boolean(prefsCache && prefsCache.notifications_muted_except_reminders);
}

//: **Where the AI's own activity is announced.**
//:
//: Asked for directly: *"make an option for agent activity notifications to be
//: hidden and not show up as toast notifications but somewhere else."* The
//: somewhere else already existed, the notifications centre records every one
//: of these: so this is only about whether a toast also flies past the corner
//: of the screen while you are reading something.
//:
//: Deliberately not the existing mute: that one suppresses the *record* as
//: well, so a muted app forgets what it did. This keeps the history and drops
//: the interruption, which is what was actually asked for.
function agentActivityQuiet() {
  return (prefsCache && prefsCache.agent_activity_notices) === "centre";
}

//: One call for "the AI did something worth mentioning". Always recorded,
//: shown as a toast only when the reader wants them. Every background-job and
//: run notice goes through this rather than `toast` directly: a rule that
//: only some of them followed would be a setting that half works.
function agentActivityNotice(message, { isError = false, kind = "task", detail = "", action = null } = {}) {
  recordNotification({ kind: isError ? "error" : kind, title: message, detail, action });
  //: **Both switches bind here, errors included.** Reported twice: "the agent
  //: activity straight up ignores muted notifications even when on panel only"
  //: and "notifications for the background agent appeared when I had them
  //: muted??".
  //:
  //: `toast()` lets an error through whatever the mute says, and that is right
  //: for a *failure the user caused and is waiting on*, a save that did not
  //: save. It is wrong here: a background pass failing to tag a note is
  //: precisely the unattended chatter these two settings exist to quiet, and
  //: the notifications centre above has already recorded it, so nothing is
  //: lost by not flying it past the corner of the screen.
  if (agentActivityQuiet() || notificationsMuted()) return;
  toast(message, isError);
}

function renderAgentActivityMode() {
  const select = $("notif-activity-mode");
  if (!select) return;
  select.value = agentActivityQuiet() ? "centre" : "toasts";
}

// Asked for directly: "allow popup notifications to be manually closable
// with an x button if the user wants them gone faster". A toast that has
// already been read is just something left to wait out otherwise, the
// timer clears when this fires, so a stray late setTimeout can't reach for
// a note the click already removed.
function toastCloseButton(note, timer) {
  const button = document.createElement("button");
  button.type = "button";
  button.className = "toast-close";
  setLabel(button, "ph:x");
  button.title = "Dismiss";
  button.setAttribute("aria-label", "Dismiss this notification");
  button.addEventListener("click", () => {
    clearTimeout(timer);
    note.remove();
  });
  return button;
}

//: The last toast's text and when it landed, so a click that somehow fires
//: two handlers for one gesture (CM6's own event dispatch does not always
//: agree with a plain DOM `stopPropagation` about which handler runs) shows
//: one notice, not two stacked identical ones. Reported on a wiki-link
//: click: `[[Act I, Scene I]]` toasted the same "not found" message twice.
//: A real repeat within the window is rare enough (nobody clicks a broken
//: link twice inside 400ms on purpose) that this costs nothing anyone would
//: notice, and it is the whole message plus severity that must match, not
//: just the timing, so two different toasts arriving close together both
//: still show.
let lastToastKey = "";
let lastToastAt = 0;
function toast(message, isError = false, { exempt = false } = {}) {
  if (!exempt && !isError && notificationsMuted()) return;
  const key = `${isError ? "1" : "0"}:${message}`;
  const now = Date.now();
  if (key === lastToastKey && now - lastToastAt < 400) return;
  lastToastKey = key;
  lastToastAt = now;
  const box = $("toast-box");
  const note = document.createElement("div");
  note.className = isError ? "toast error" : "toast";
  const text = document.createElement("span");
  text.textContent = message;
  note.appendChild(text);
  const timer = setTimeout(() => note.remove(), 5500);
  note.appendChild(toastCloseButton(note, timer));
  box.appendChild(note);
}

// A toast with one action button, used for Undo (Wave J). The button
// stays until clicked or the toast times out (a bit longer than usual,
// since the user has to react to it).
//: **A toast that stays until the work it is announcing finishes.**
//:
//: Reported of OCR: *"if i close the lightbox as I am generating ocr, then it
//: stops and I have to restart it again. also ocr generation is slow and i
//: dont even know if it is working."* The second half is this function's job.
//: Every other toast in the app is a 5.5-second notice about something that
//: already happened; a job that takes thirty seconds needs the opposite, a
//: notice that persists *while* it happens and then reports what it found.
//:
//: Returns a handle rather than a node: the caller finishes the job, and
//: finishing it is one call rather than a DOM edit at each of its exits.
function toastProgress(message) {
  const box = $("toast-box");
  const note = document.createElement("div");
  note.className = "toast";
  const spinner = typingDots(message);
  const text = document.createElement("span");
  text.textContent = message;
  note.append(spinner, text);
  box.appendChild(note);
  return {
    say(next) {
      text.textContent = next;
      spinner.setStatus?.(next);
    },
    //: `done` swaps the spinner for the outcome and starts the ordinary
    //: 5.5-second life every other toast has, so a finished job does not
    //: leave a permanent line on screen.
    done(finalMessage, { isError = false, actionLabel = null, onAction = null } = {}) {
      spinner.remove();
      text.textContent = finalMessage;
      note.classList.toggle("error", Boolean(isError));
      if (actionLabel && onAction) {
        const button = document.createElement("button");
        button.className = "link-button";
        button.type = "button";
        button.textContent = actionLabel;
        button.addEventListener("click", () => {
          onAction();
          note.remove();
        });
        note.appendChild(button);
      }
      const timer = setTimeout(() => note.remove(), 5500);
      note.appendChild(toastCloseButton(note, timer));
    },
  };
}

function toastAction(message, actionLabel, onAction) {
  const box = $("toast-box");
  const note = document.createElement("div");
  note.className = "toast";
  const text = document.createElement("span");
  text.textContent = message;
  const button = document.createElement("button");
  button.className = "small toast-action";
  button.textContent = actionLabel;
  button.addEventListener("click", async () => {
    clearTimeout(timer);
    note.remove();
    await onAction();
  });
  const timer = setTimeout(() => note.remove(), 8000);
  note.append(text, button, toastCloseButton(note, timer));
  box.appendChild(note);
}

// --- global undo/redo (status bar) ------------------------------------------------
//
// The app already had per-action undo scattered across it, a toast's Undo
// button on note/reminder delete, the whiteboard's own local history, a
// per-tool-call "put this back" in the agent panel. None of those help once
// the toast has timed out, or for the actions that never got one (linking
// two notes, editing a note's body, attaching an image). This is the one
// mechanism that catches all of it: any mutation that can name its own
// inverse calls `pushUndo(label, undo, redo)`, and the status bar's Undo/Redo
// buttons (plus Ctrl+Z/Ctrl+Shift+Z) work the two stacks below. Session-only
// by design: like the rest of this app's undo, it does not survive a reload,
// which is the same lifetime a browser's own Ctrl+Z already has.
const undoStack = [];
const redoStack = [];
const UNDO_STACK_LIMIT = 50;

function pushUndo(label, undo, redo) {
  const action = { label, undo, redo };
  undoStack.push(action);
  if (undoStack.length > UNDO_STACK_LIMIT) undoStack.shift();
  // A fresh action invalidates whatever was available to redo, the same
  // rule every text editor's undo stack already follows.
  redoStack.length = 0;
  renderUndoBar();
  return action;
}

// A few call sites also offer an immediate toast "Undo" button alongside the
// global stack (Wave J's pattern, from before this stack existed). If that
// button is used, the action has to come off the undo stack, otherwise a
// later Ctrl+Z would redo the exact same restore, since the closure runs
// fine either way and nothing stops it firing twice.
function settleUndoFromToast(action) {
  const idx = undoStack.indexOf(action);
  if (idx !== -1) undoStack.splice(idx, 1);
  redoStack.push(action);
  renderUndoBar();
}

// A `PUT /entries/{id}` before/after snapshot: the shared inverse for every
// kind of note-content edit (a manual text correction, an image attached or
// removed from the body, a tag/category change from the edit form), since
// all of them are just this one request with a different body.
function pushEntryPutUndo(entryId, label, beforeBody, afterBody) {
  pushUndo(
    label,
    async () => {
      await api(`/entries/${entryId}`, { method: "PUT", body: JSON.stringify(beforeBody) });
      await loadEntries();
    },
    async () => {
      await api(`/entries/${entryId}`, { method: "PUT", body: JSON.stringify(afterBody) });
      await loadEntries();
    }
  );
}

async function performUndo() {
  const action = undoStack.pop();
  if (!action) return;
  try {
    await action.undo();
    redoStack.push(action);
    toast(`Undone: ${action.label}`);
  } catch (error) {
    // Nothing changed: put it back rather than silently dropping it off
    // the stack, so a transient network error doesn't cost the undo itself.
    undoStack.push(action);
    toast(error.message || "Couldn't undo that.", true);
  }
  renderUndoBar();
}

async function performRedo() {
  const action = redoStack.pop();
  if (!action) return;
  try {
    await action.redo();
    undoStack.push(action);
    toast(`Redone: ${action.label}`);
  } catch (error) {
    redoStack.push(action);
    toast(error.message || "Couldn't redo that.", true);
  }
  renderUndoBar();
}

function renderUndoBar() {
  const undoBtn = $("status-undo");
  const redoBtn = $("status-redo");
  if (!undoBtn || !redoBtn) return;
  const last = undoStack[undoStack.length - 1];
  const next = redoStack[redoStack.length - 1];
  undoBtn.disabled = !last;
  redoBtn.disabled = !next;
  paintStatusItem("status-undo", {
    icon: "ph:arrow-u-up-left",
    //: The right-click gesture is named here because a hidden gesture is not a
    //: feature: the same reason the nav pair's tooltips name theirs.
    title: last
      ? `Undo: ${last.label} (${shortcuts.undo.keys}): right-click for the last ${undoStack.length}`
      : "Nothing to undo",
  });
  paintStatusItem("status-redo", {
    icon: "ph:arrow-u-up-right",
    title: next ? `Redo: ${next.label} (${shortcuts.redo.keys})` : "Nothing to redo",
  });
}

$("status-undo").addEventListener("click", performUndo);
$("status-redo").addEventListener("click", performRedo);

//: **The stack you can see.** Reported: the global undo is "significantly
//: outdated and dont register a lot of actions", and the second half of that
//: is that there was no way to *look*. A single button that says "Undo: moved
//: a note to the bin" tells you the last thing and nothing about the four
//: before it, so undoing three steps is three presses into the dark.
//:
//: Right-click, the same gesture the back/forward pair already uses for their
//: own history, and named in the tooltip so it is discoverable rather than
//: folklore. Picking a row undoes everything down to and including it, which
//: is what a history list means everywhere else.
function openUndoHistoryMenu(anchorEl) {
  const menu = $("undo-history-menu");
  if (!menu) return;
  menu.replaceChildren();
  if (!undoStack.length) return;
  const list = document.createElement("ul");
  list.className = "action-menu-list";
  //: Newest first, because the newest is the one you are almost always
  //: reaching for and a list you have to read upwards is a list you misread.
  [...undoStack].reverse().forEach((action, offset) => {
    const li = document.createElement("li");
    const button = document.createElement("button");
    button.type = "button";
    button.className = "action-menu-item";
    setLabel(button, `ph:arrow-u-up-left ${action.label}`);
    button.title = offset === 0 ? "Undo this" : `Undo this and the ${offset} after it`;
    button.addEventListener("click", async () => {
      menu.classList.add("hidden");
      //: One at a time through `performUndo`, so a step that fails stops the
      //: run with the stack intact rather than leaving the notebook half
      //: rolled back: the same contract a single press already has.
      for (let step = 0; step <= offset; step += 1) {
        const before = undoStack.length;
        await performUndo();
        if (undoStack.length === before) break;
      }
    });
    li.appendChild(button);
    list.appendChild(li);
  });
  menu.appendChild(list);
  menu.classList.remove("hidden");
  const margin = 8;
  const anchor = anchorEl.getBoundingClientRect();
  menu.style.left = "0px";
  const box = menu.getBoundingClientRect();
  const left = Math.min(anchor.left, window.innerWidth - margin - box.width);
  menu.style.left = `${Math.round(Math.max(margin, left))}px`;
}

$("status-undo").addEventListener("contextmenu", (event) => {
  if (!undoStack.length) return;
  event.preventDefault();
  openUndoHistoryMenu($("status-undo"));
});

document.addEventListener("mousedown", (event) => {
  const menu = $("undo-history-menu");
  if (!menu || menu.classList.contains("hidden")) return;
  if (!menu.contains(event.target) && event.target !== $("status-undo")) {
    menu.classList.add("hidden");
  }
});

// --- quick access: recent questions + most-used entries (Phase 5) -------------------

async function loadRecentQuestions() {
  const box = $("recent-questions");
  const questions = await apiJson("/chat/recent").catch(() => []);
  box.replaceChildren();
  box.classList.toggle("hidden", questions.length === 0);
  if (questions.length === 0) return;
  const label = document.createElement("span");
  label.className = "muted";
  label.textContent = "Ask again:";
  box.appendChild(label);
  for (const question of questions) {
    const again = chip(question.length > 48 ? question.slice(0, 47) + "…" : question, "", () => {
      $("question").value = question;
      askQuestion();
    });
    again.title = question;
    box.appendChild(again);
  }
}

async function loadMostUsed() {
  const box = $("most-used-box");
  const list = $("most-used");
  const entries = await apiJson("/entries/most-accessed").catch(() => []);
  list.replaceChildren();
  box.classList.toggle("hidden", entries.length === 0);
  for (const entry of entries) {
    const li = document.createElement("li");
    li.title = entry.content;
    const text = document.createElement("span");
    // Reported directly: a clip landing mid-token (`` `code` `` cut before
    // its closing backtick) left a stray `` ` `` sitting in the rendered
    // text: `safeMdSlice` drops the dangling marker instead of the plain
    // `slice(0, 25)` this used to do.
    //
    // Block syntax stripped first. renderInlineMarkdown is inline-only, so a
    // note beginning "# Groceries" rendered the literal "# Groceries", the
    // same gap the dashboard's mini-lists had, here too since this list uses
    // the same two-function combination.
    const flat = entry.content.replace(/^\s*(?:#{1,6}\s+|>\s?|[-*+]\s+|\d+\.\s+)/gm, "");
    const { text: sliced, truncated } = safeMdSlice(flat, 25);
    renderInlineMarkdown(text, sliced, [], true);
    if (truncated) text.appendChild(document.createTextNode("…"));
    const count = document.createElement("span");
    count.className = "count";
    count.textContent = `×${entry.access_count}`;
    li.append(text, count);
    li.addEventListener("click", () => flashEntry(entry.id));
    list.appendChild(li);
  }
}

// --- model manager (Phase 3.5) ---------------------------------------------------

let modelStatus = null; // latest /models/status payload
// Has the status endpoint ever answered? "We haven't asked yet" and "we asked
// and got nothing" are both `modelStatus === null`, but they mean opposite
// things to the user: the first is normal for the first second of every
// startup, the second is a fault. Without this the indicator flashed red on
// every single page load before settling.
let statusEverAnswered = false;
let suggestedCatalog = null; // loaded once, it never changes
let statusTimer = null;

// The Ollama embedding model offered as a one-click fallback when the
// built-in (sentence-transformers) engine can't load: asked for directly,
// after a real support-bundle report: the built-in engine needs
// sentence-transformers, which isn't bundled (see CLAUDE.md/requirements.txt
//, installing it has broken past sessions, and a packaged Windows build
// excludes torch on purpose), so a fresh install with no working Python on
// PATH for Settings -> Packages to fall back to has no way to make the
// built-in engine work at all. nomic-embed-text: small, well-known, and
// exactly what Settings -> Models' own "quick fix" sentence already named
// before this button existed.
const EMBEDDING_FALLBACK_MODEL = "nomic-embed-text";
let embeddingFallbackRunning = false;

function settingsOpen() {
  // The Models section lives inside the settings modal now (Wave A).
  return settingsModalOpen();
}

function jobsRunning() {
  // Anything in `GET /tasks` counts, not just the two jobs `/models/status`
  // happens to carry. This used to read re-index and pulls only, so while a
  // caption, an image OCR or an autonomous pass was running the loop stayed
  // on its 10-second idle cadence, the status bar's job slot lagged by up
  // to ten seconds behind work that often does not last that long, and the
  // finish was noticed just as late. The two below are kept as their own
  // check rather than folded in: they come from a different payload, and a
  // `/tasks` call that fails leaves `backgroundTasks` empty while a pull is
  // demonstrably still running.
  if (backgroundTasks.length) return true;
  if (!modelStatus) return false;
  const reindexing = modelStatus.reindex && modelStatus.reindex.status === "running";
  const pulling = Object.values(modelStatus.pulls || {}).some(
    (job) => job.status === "running"
  );
  return reindexing || pulling;
}

// One polling loop for everything: slow when idle, fast while a
// download/re-index is running or the settings panel is open.
//: When `/tasks` was last asked, so the idle cadence below can ask it half as
//: often as `/models/status` (PLAN.md P1; MODERNISATION_AUDIT.md F2 measured
//: 14 requests in an idle minute on the Dashboard, status ×6, tasks ×6,
//: reminders ×2: against P1's gate of ≤ 4).
let backgroundTasksAskedAt = 0;
const TASKS_IDLE_MS = 60_000;

async function refreshModelStatus() {
  // Locked: no token, so every request is a guaranteed 401, noise in both
  // logs and a wake-up of the Python process for nothing. Re-arm cheaply and
  // let the unlock path call this itself (it does, after login).
  if (!authToken()) {
    clearTimeout(statusTimer);
    statusTimer = setTimeout(refreshModelStatus, 10000);
    return;
  }
  try {
    // silent: a poll must never trigger the lock screen (Wave O fix).
    // Fast-fail timeout: if the LLM hangs, the UI reflects offline in 8s.
    // Backend's own worst case is ~5s (one list_models() call, its own
    // 5s timeout) since /models/status stopped double-probing Ollama, 
    // this leaves real headroom instead of racing that budget at the wire.
    modelStatus = await apiJson("/models/status", {
      silent: true,
      signal: AbortSignal.timeout(8000)
    });
    statusEverAnswered = true;
  } catch {
    modelStatus = null; // locked or unreachable: pill shows the worst case
  }
  renderAiPill();
  syncAiOnlyControls();
  // The status bar's job slot rides this loop rather than starting one of its
  // own, so it inherits the whole cadence: one second while something is
  // running, thirty when idle, two minutes behind a hidden tab. Idle, `/tasks`
  // is asked every other tick: a job that starts from this page kicks the poll
  // itself (`kickBackgroundTaskPoll`), so an idle minute only has to notice a
  // job started somewhere else, and once a minute is soon enough for that.
  const idle = !jobsRunning() && !settingsOpen();
  if (!idle || Date.now() - backgroundTasksAskedAt >= TASKS_IDLE_MS) {
    backgroundTasksAskedAt = Date.now();
    await refreshBackgroundTasks();
  }
  if (settingsOpen()) renderSettings();

  clearTimeout(statusTimer);
  // Back right off when the tab is hidden, no point polling a page nobody's
  // looking at (visibilitychange below refreshes the moment it's shown again).
  // Idle is 30s, not 10: the status this reports (is the model runner up,
  // which model) changes on the order of minutes, and every tick wakes the
  // process that is also running the model. Measured before: 14 requests in
  // an idle minute; the gate is 4 (status ×2, tasks ×1, reminders ×1).
  const delay = jobsRunning()
    ? 1000
    : document.hidden
      ? 120000
      : settingsOpen()
        ? 3000
        : 30000;
  statusTimer = setTimeout(refreshModelStatus, delay);
}

// Refresh immediately when the user returns to the tab, so a status that went
// stale while hidden snaps up to date instead of waiting out the long delay.
document.addEventListener("visibilitychange", () => {
  if (!document.hidden) refreshModelStatus();
});

// Controls that can only do their job with a chat model running. Left
// enabled, they look available and only fail once you've committed to them, 
// you type a note, press AI Improve, wait, and get an apology. Disabling them
// with a reason attached says the same thing before you spend the effort.
//
// Deliberately NOT in here: Save, Ask, search, tags, categories, the graph,
// reminders, documents. Those work fully without any AI and must never look
// diminished by its absence, the notebook is the point, the AI is a helper.
const AI_ONLY_CONTROLS = [
  ["improve-btn", "Proofreading needs the local AI"],
  ["reminder-magic-add", "Reading a reminder from a sentence needs the local AI"],
  ["draft-compose", "Drafting needs the local AI"],
  ["doc-ai", "AI editing needs the local AI"],
  // Extract notes (BACKLOG.md §62): without the AI it can only hand back
  // the selection as one plain, unlinked note, a materially weaker result
  // than what the button promises, so it's disabled here rather than left
  // to explain that after the fact, same as Draft and AI edit above.
  ["draft-extract", "Extracting notes needs the local AI"],
  ["doc-extract", "Extracting notes needs the local AI"],
  ["wb-extract-notes", "Extracting notes needs the local AI"],
];

function syncAiOnlyControls() {
  // Unknown status (locked, still loading) is treated as available: better to
  // let a click fail than to grey out a working button on a slow start.
  const off = modelStatus ? modelStatus.ollama_running === false : false;
  for (const [id, reason] of AI_ONLY_CONTROLS) {
    const button = $(id);
    if (!button) continue;
    button.disabled = off;
    button.classList.toggle("ai-unavailable", off);
    if (off) {
      if (!button.dataset.enabledTitle) button.dataset.enabledTitle = button.title || "";
      button.title = `${reason}: start Ollama to use this.`;
    } else if (button.dataset.enabledTitle !== undefined) {
      button.title = button.dataset.enabledTitle;
    }
  }
}

// What the AI is doing, as one decision.
//
// Three levels, and the boundary between them is deliberate. This app is built
// to degrade gracefully, so "no AI at all" is a supported way to run it, not a
// fault: it is amber, not red. Red is reserved for something that is actually
// broken: a model that failed to load, or a server we can't reach. Colouring a
// normal offline setup red would train the user to ignore the indicator.
//
//   idle  … grey    haven't heard back yet, says nothing either way
//   ok    ✓ green   everything the AI can do is available
//   warn  ! amber   loading, switched off, or partly available, app works
//   error ✕ red     something is broken and won't fix itself
function aiStatusState() {
  if (!modelStatus) {
    // The first poll of every page load lands here for a moment. Reporting
    // that as a fault would flash red on every startup and teach the user
    // that red means nothing, so an unanswered *first* request is its own
    // quiet state, and only a request that has failed after we have already
    // had an answer counts as the server going away.
    if (!statusEverAnswered) {
      return {
        level: "idle",
        title: "Checking…",
        detail: "Asking the app what the AI is doing. This takes a moment.",
      };
    }
    return {
      level: "error",
      title: "Can't reach MemoryMap",
      detail:
        "The app can't read its own status, which usually means the server " +
        "stopped. Your notes are safe on disk.",
    };
  }
  const chatReady = modelStatus.ollama_running;
  const searchReady = modelStatus.embedding_ready;

  if (modelStatus.reindex && modelStatus.reindex.status === "running") {
    return {
      level: "warn",
      title: "Rebuilding the search index",
      detail:
        "Searching by word works while this runs. Searching by meaning comes " +
        "back when it finishes.",
    };
  }
  if (!searchReady && modelStatus.embedding_warming) {
    return {
      level: "warn",
      title: "Search AI is warming up",
      detail:
        "Searching by word works now. Searching by meaning becomes available " +
        "once the model has loaded.",
    };
  }
  if (!searchReady && modelStatus.embedding_error) {
    // "Broken" and "still loading" looked identical before: the old pill said
    // "warming up…" forever when the model had actually failed.
    return {
      level: "error",
      title: "Search AI didn't load",
      detail:
        `${modelStatus.embedding_error}\n\nSearching by word still works, and ` +
        "notes, tags, reminders and the graph are unaffected. Settings → Logs " +
        "has the details.",
    };
  }
  if (chatReady && searchReady) {
    return {
      level: "ok",
      title: "AI ready",
      detail: "Chat, auto-filing and search by meaning are all available.",
    };
  }
  // Everything below leads with what still WORKS. Announcing a fault and
  // pointing at a log reads as "the app is broken" when in fact only the
  // optional half is missing.
  if (!chatReady && searchReady) {
    return {
      level: "warn",
      title: "Everything works · chat AI off",
      detail:
        "Notes, search, tags, reminders and the graph all work. Start Ollama " +
        "to add chat and auto-filing.",
    };
  }
  if (chatReady && !searchReady) {
    return {
      level: "warn",
      title: "Word search on · AI search warming",
      detail:
        "Searching by word works now; searching by meaning becomes available " +
        "once the embedding model has loaded.",
    };
  }
  return {
    level: "warn",
    title: "Everything works · AI off",
    detail:
      "Writing, searching, tagging, reminders, documents and the graph all " +
      "work without any AI. Start Ollama to add chat, auto-filing and search " +
      "by meaning.",
  };
}

// The glyph is not decoration. Colour alone fails for the ~8% of men with a
// colour vision deficiency, and fails everyone in high-contrast mode, so the
// shape carries the same meaning the colour does.
// "…" for connecting rather than a spinner: a spinner has to be animated to
// read as one, and under prefers-reduced-motion a frozen spinner looks like a
// rendering fault. The ellipsis says "waiting" while perfectly still.
const AI_STATUS_GLYPH = { idle: "…", ok: "✓", warn: "!", error: "✕" };

function renderAiPill() {
  const button = $("ai-status");
  if (!button) return;
  const state = aiStatusState();
  button.dataset.level = state.level;
  button.querySelector(".ai-status-dot").textContent = AI_STATUS_GLYPH[state.level];
  // The button's own name for screen readers and for the native tooltip, so
  // the information is reachable without opening anything.
  const summary = `AI status: ${state.title}`;
  $("ai-status-label").textContent = summary;
  // button.title = `${state.title}\n\n${state.detail}`;
  $("ai-status-title").textContent = state.title;
  $("ai-status-detail").textContent = state.detail;
  renderChatActiveModelBadge();
}

// --- the status bar (§36D) ---------------------------------------------------
//
// Five items, and the roadmap's own test for what may be here: each one is
// either a state worth knowing at a glance or a command you use constantly.
// Anything else is a permanent strip of decoration, so anything added later
// should have to displace one of these rather than sit beside them.
//
// **Nothing here polls.** Every value arrives on a loop that already existed:
// the AI state and the background job on `refreshModelStatus`, the reminder
// counts wherever the tab badge is painted, the notebook size when the notes
// are loaded. That is deliberate and it is not a micro-optimisation, a
// reminder poll running on two timers is a bug this project has already had
// and had to find in a browser, and a bar with five values is five chances to
// repeat it.

//: What the reminder poll last saw. Two numbers rather than a list: the bar
//: needs counts, and holding the reminders themselves here would be a second
//: copy of state the Reminders tab already owns.
let reminderCounts = { open: 0, due: 0 };

//: The running background jobs, straight from GET /tasks. Not reassembled from
//: `modelStatus`, routes_tasks.py exists precisely because the frontend used
//: to build this list out of the two jobs that happened to be in the status
//: payload, and everything else (the embedding warm-up, the SearXNG install)
//: was invisible.
let backgroundTasks = [];

//: ⌘ on a Mac, Ctrl everywhere else. `userAgentData` where it exists because
//: `navigator.platform` is deprecated and lies inside some embedded shells;
//: the fallback is what the desktop window still answers.
const STATUS_META_KEY = /Mac|iPhone|iPad/.test(
  (navigator.userAgentData && navigator.userAgentData.platform) ||
    navigator.platform ||
    ""
)
  ? "⌘K"
  : "Ctrl K";

// One item: an icon, a number, and a word. The number is bold and tabular so
// the row does not twitch sideways as counts change, a status bar that moves
// while you are reading it is the thing the header was rebuilt to stop doing.
function paintStatusItem(id, { icon, value, label, title, tone = "" }) {
  const button = $(id);
  if (!button) return;
  button.replaceChildren();
  if (icon) {
    const glyph = document.createElement("span");
    setLabel(glyph, icon);
    glyph.setAttribute("aria-hidden", "true");
    button.appendChild(glyph);
  }
  if (value !== undefined && value !== null) {
    const strong = document.createElement("b");
    strong.textContent = String(value);
    button.appendChild(strong);
  }
  if (label) {
    const text = document.createElement("span");
    text.textContent = label;
    button.appendChild(text);
  }
  button.title = title || "";
  // The title doubles as the accessible name, exactly as `smallButton` already
  // does: without this the three icon-only status buttons (Undo, Redo,
  // Commands) announce as a bare "button" to a screen reader. The ones that
  // also paint a `value`/`label` have real text and do not need it, but
  // setting it uniformly keeps the two from drifting apart.
  if (title) button.setAttribute("aria-label", title);
  else button.removeAttribute("aria-label");
  button.classList.toggle("status-due", tone === "due");
}

function renderStatusBar() {
  if (!$("status-bar")) return;

  // The notebook's size, from the list the app has already loaded rather
  // than from /insights/stats: costs nothing, and is exact once loadEntries
  // finishes. GET /entries pages for a large notebook now (ENTRIES_PAGE_SIZE
  // above), so for the first moment after unlocking a several-thousand-note
  // notebook this can undercount while later pages are still landing in the
  // background: self-corrects within a render or two, and is still a more
  // honest number than showing nothing while it catches up. Before the first
  // load it says nothing rather than "0 notes", which would be a lie for the
  // second it is up.
  paintStatusItem("status-notes", {
    icon: "ph:note-pencil",
    value: entriesEverLoaded ? allEntries.length : "–",
    label: allEntries.length === 1 && entriesEverLoaded ? "note" : "notes",
    title: "Your notebook: click to browse it",
  });

  // Due, or open. The same choice the dashboard's tile makes, and it has to
  // stay the same choice: two counters visible at once that count differently
  // is worse than either alone.
  const { open, due } = reminderCounts;
  paintStatusItem("status-reminders", {
    icon: due ? "ph:alarm" : "ph:check-circle",
    value: due || open,
    label: due ? "due" : "open",
    title: due
      ? `${due} reminder${due === 1 ? "" : "s"} due now`
      : `${open} open reminder${open === 1 ? "" : "s"}`,
    tone: due ? "due" : "",
  });

  // The job slot appears only while there is one. Where several run at once it
  // shows the first, /tasks orders them newest-concern-first, and says how
  // many are behind it, because a bar is one line and a queue is not.
  const task = backgroundTasks[0];
  const slot = $("status-task");
  slot.classList.toggle("hidden", !task);
  if (task) {
    const others = backgroundTasks.length - 1;
    paintStatusItem("status-task", {
      icon: "ph:gear",
      label: others > 0 ? `${task.label} (+${others})` : task.label,
      title:
        `${task.label}${task.detail ? `, ${task.detail}` : ""}` +
        "\n\nClick to open Background tasks.",
    });
  }

  // The palette already exists and is already on Ctrl/⌘-K; what it did not
  // have was anywhere on screen saying so. A shortcut nobody can see is a
  // shortcut only the person who wrote it uses.
  const command = $("status-command");
  command.replaceChildren();
  const key = document.createElement("span");
  key.className = "status-key";
  key.textContent = STATUS_META_KEY;
  const word = document.createElement("span");
  word.textContent = "Commands";
  command.append(key, word);
  command.title = `Search everything and jump anywhere (${STATUS_META_KEY})`;

  // Same reasoning one control along: the popup agent works from every tab
  // and had nothing on screen saying it exists. Reported as exactly that, 
  // it needed to be reachable from the tools popup, the palette, Settings
  // "and maybe even the bottom status bar".
  const agent = $("status-agent");
  if (agent) {
    agent.replaceChildren();
    const glyph = document.createElement("i");
    glyph.className = "ph ph-magic-wand";
    glyph.setAttribute("aria-hidden", "true");
    const word = document.createElement("span");
    word.textContent = "Ask";
    agent.append(glyph, word);
    //: `STATUS_META_KEY` is the whole "Ctrl K"/"⌘K" hint, not a bare
    //: modifier: appending "+Shift+A" to it produced "Ctrl K+Shift+A", which
    //: names no shortcut at all. Caught by reading the rendered title
    //: attribute rather than the source.
    const meta = STATUS_META_KEY.startsWith("⌘") ? "⌘" : "Ctrl";
    agent.title = `Ask the agent anything, from any tab (${meta}+Shift+A)`;
  }
}

// Hover is handled in CSS. This is the click half, needed for touch, where
// there is no hover, and for keyboards, where there is no pointer.
function toggleAiStatusPopup(force) {
  const button = $("ai-status");
  const popup = $("ai-status-popup");
  if (!button || !popup) return;
  const open = force !== undefined ? force : !button.classList.contains("pinned");
  button.classList.toggle("pinned", open);
  button.setAttribute("aria-expanded", String(open));
  // Visibility, not the `hidden` attribute: `hidden` is display:none, which
  // the CSS hover rule would then have to fight. The stylesheet owns whether
  // the popup is shown; this only records that it has been pinned open.
  popup.classList.toggle("pinned", open);
}

// One plain-English line: which search engine is active and whether it works.
// The built-in engine runs without Ollama, so this shows in every state.
function renderSearchEngineHealth(status) {
  const el = $("search-engine-health");
  // The name comes from the server, never from a string in here: this line
  // said "Built-in (all-MiniLM)" for two model changes after the built-in
  // model stopped being all-MiniLM, and the only way to find out what was
  // really running was to watch it download in the log.
  const engine =
    status.embedding_backend === "ollama"
      ? `Ollama · ${status.embedding_model}`
      : `Built-in · ${status.active_embedding_model || "…"}`;
  let state = "not ready";
  let cls = "busy";
  if (status.embedding_ready) {
    state = "✓ ready";
    cls = "ok";
  } else if (status.embedding_warming) {
    state = "… warming up";
  } else if (status.embedding_error) {
    state = "Unavailable: using keyword search (details below)";
    cls = "error";
  }
  el.textContent = `Search engine: ${engine}: ${state}`;
  el.className = `status ${cls}`;
}

// What to call the backend on screen. The whole UI was written when there was
// only Ollama, and the word is in a dozen strings; this is the one place that
// decides, so the rest read from it (§6).
// The Chat / Agent pair. The hidden checkbox stays the single source of truth
//, every other reader in the app already consults it, and a second store for
// the same fact is how two of them end up disagreeing. These buttons just show
// it and set it.
function renderChatModeSeg() {
  const agent = $("tools-toggle").checked;
  // Two `addEventListener` calls for Quit and Clear-history used to sit here,
  // spliced into the middle of this function by an editing accident. It parsed,
  // so nothing complained: but this function runs on every chat-mode change,
  // so each call bound *another* listener to both buttons. Clicking Quit after
  // switching modes a few times opened that many confirm dialogs and fired
  // that many shutdown requests. The correctly-placed copies of both are
  // registered once, at the bottom of this file, where every other handler is.
  for (const button of document.querySelectorAll("#chat-mode-seg button")) {
    const active = button.dataset.chatMode === (agent ? "agent" : "chat");
    button.classList.toggle("active", active);
    button.setAttribute("aria-pressed", active ? "true" : "false");
  }
}

async function setChatMode(mode) {
  const agent = mode === "agent";
  $("tools-toggle").checked = agent;
  renderChatModeSeg();
  // Remembered, because it is a way of working rather than a per-message
  // choice: the same preference the checkbox always wrote.
  await apiJson("/preferences", {
    method: "PUT",
    body: JSON.stringify({ tools_enabled: agent }),
  }).catch(() => {});
}

function backendLabel(status) {
  return (status && status.provider) === "openai" ? "The model server" : "Ollama";
}

// True while the user is mid-edit, so a status poll doesn't overwrite the
// address they are halfway through typing. The polling that keeps this screen
// live is the reason: without it, a five-second refresh eats every third
// keystroke.
let backendFieldsDirty = false;

function renderBackendPicker(status) {
  const select = $("llm-provider-select");
  const url = $("llm-base-url");
  if (!select || !url) return;
  if (backendFieldsDirty || document.activeElement === url) return;
  select.value = status.provider || "ollama";
  // Show the address actually in use, but as a placeholder when it is just the
  // default: so the field stays empty and "blank means the usual one" keeps
  // being true after a round trip.
  const defaults = status.provider_default_base_urls || {};
  const fallback = defaults[select.value] || "";
  if (status.base_url && status.base_url !== fallback) {
    url.value = status.base_url;
  } else {
    url.value = "";
  }
  url.placeholder = fallback || "Default address";

  // Drawn from the status poll, not only from the Connect response. A warning
  // that shows once and disappears on the next reload is a warning about a
  // condition that has not gone away, and this one says the notes are leaving
  // the machine, which is the promise the whole app is built on.
  const privacy = $("llm-privacy-warning");
  if (privacy) {
    privacy.textContent = status.privacy_note || "";
    privacy.classList.toggle("hidden", !status.privacy_note);
  }
  const lock = $("local-only-ai");
  if (lock && document.activeElement !== lock) {
    lock.checked = status.local_only_ai !== false;
  }
}

async function applyBackendChoice() {
  const provider = $("llm-provider-select").value;
  const baseUrl = $("llm-base-url").value.trim();
  const note = $("llm-provider-status");
  note.textContent = "Connecting…";
  try {
    const body = await apiJson("/models/provider", {
      method: "POST",
      body: JSON.stringify({ provider, base_url: baseUrl }),
    });
    backendFieldsDirty = false;
    // The setting is saved either way, you set the address, then you start
    // the server: so this reports what was found rather than treating an
    // unreachable server as a rejected setting.
    note.textContent = body.reachable
      ? `● Connected to ${body.base_url}: ${body.installed_models.length} model(s) available.`
      : `○ Saved, but nothing is answering at ${body.base_url} yet. Start the server and this will light up.`;
    // This app's headline promise is that notes stay on the machine. A backend
    // somewhere else is allowed, someone may want it, but never quietly, so
    // the warning is loud and stays until the address changes.
    const privacy = $("llm-privacy-warning");
    privacy.textContent = body.privacy_note || "";
    privacy.classList.toggle("hidden", !body.privacy_note);
    await refreshModelStatus();
  } catch (err) {
    note.textContent = err.message;
  }
}

function renderSettings() {
  const status = modelStatus;
  const ollamaLine = $("ollama-status");

  if (!status) {
    ollamaLine.textContent = "Can't reach the MemoryMap server.";
    return;
  }

  // Name the backend that actually answered. Saying "Ollama not detected"
  // when the app was pointed at LM Studio sends people to install the wrong
  // thing (§6).
  const backend = backendLabel(status);
  ollamaLine.textContent = status.ollama_running
    ? `● ${backend} is running`
    : `○ ${backend} not detected`;
  renderBackendPicker(status);
  const embeddingError = $("embedding-error");
  embeddingError.classList.toggle("hidden", !status.embedding_error);
  if (status.embedding_error) {
    embeddingError.textContent =
      `Search engine problem: ${status.embedding_error}: semantic search is ` +
      "falling back to keywords. Quick fix: switch the search engine below to " +
      "an Ollama embedding model (download nomic-embed-text from the list), " +
      "it runs fully offline. Full details in Settings → Logs.";
  }
  // The one-click version of the "quick fix" sentence above: only offered
  // when it can actually be carried out (Ollama has to be running to either
  // pull or use an Ollama embedding model), and not while the fix is
  // already running or already switched over.
  const fixRow = $("embedding-error-fix-row");
  const alreadyOnOllama = status.embedding_backend === "ollama"
    && status.embedding_model === EMBEDDING_FALLBACK_MODEL;
  fixRow.classList.toggle(
    "hidden",
    !status.embedding_error
      || !status.ollama_running
      || !status.supports_pull
      || embeddingFallbackRunning
      || alreadyOnOllama
  );
  renderSearchEngineHealth(status);
  // The "install Ollama" advice only helps someone who chose Ollama.
  $("ollama-help").classList.toggle(
    "hidden",
    status.ollama_running || status.provider !== "ollama"
  );
  $("models-config").classList.toggle("hidden", !status.ollama_running);
  // Downloads are an Ollama capability. Every other backend is handed a model
  // that is already on disk, so the panel hides rather than offering a button
  // that cannot work.
  $("suggested-box").classList.toggle(
    "hidden",
    !status.ollama_running || status.supports_pull === false
  );

  // The search engine is always adjustable: its recommended option is the
  // built-in one, which needs no Ollama. Only the Ollama half of it depends
  // on Ollama being up.
  renderEmbeddingPicker(status);
  if (status.ollama_running) {
    renderChatModelPicker(status);
    renderUtilityModelPicker(status);
    renderVisionModelPicker(status);
  renderOcrModelPicker(status);
    renderAutonomousModelPicker(status);
    renderInstalledModels(status);
    renderSuggested(status);
    renderModelSpec(status.chat_model);
  } else {
    $("installed-box").classList.add("hidden");
    $("model-spec").classList.add("hidden");
    $("model-spec-health").classList.add("hidden");
  }
  renderReindex(status);
}

// GET /tasks, once per status poll, feeding everything that wants to know what
// is running: the status bar's job slot, the Background tasks panel when it is
// open, and the notifications centre.
//
// That last one was a real gap rather than a tidy-up. `renderTaskHistory`
// records a finished job into the centre "whether or not this screen is open, 
// which is the point of the centre", but the only thing that called it was
// `renderTasks`, and the only thing that called *that* was the panel being on
// screen. So a re-index that finished while you were anywhere else, which is
// most of them, since these jobs run for minutes, was recorded nowhere. It is
// polled from here now, so the record does not depend on being watched.
async function refreshBackgroundTasks() {
  // Before the unlock there is no token and this is a guaranteed 401 on every
  // poll: noise in the browser's network log and in the server's, where it
  // reads as an auth failure worth investigating.
  if (!authToken()) {
    backgroundTasks = [];
    return;
  }
  const body = await apiJson("/tasks", { silent: true }).catch(() => null);
  backgroundTasks = (body && body.tasks) || [];
  noticeTaskTransitions(backgroundTasks, (body && body.history) || []);
  renderStatusBar();
  // One fetch, not two: the panel renders from this payload rather than asking
  // again a few milliseconds later.
  if (settingsModalOpen() && currentSettingsSection === "tasks") renderTasks(body);
  else renderTaskHistory((body && body.history) || []);
}

// --- a background job starting and finishing, said out loud --------------------
//
// Half of this existed and half did not, which is why it read as broken rather
// than as missing: `renderTaskHistory` records every *finish* into the
// notifications centre, but a **start** was recorded nowhere, and neither end
// was ever said out loud. So kicking off a re-index or an extras install and
// then going back to writing gave you no sign anything was happening and no
// sign when it stopped, the only trace was a screen inside Settings and a
// centre you had to open.
//
// What this adds is the transitions: a job appearing in `GET /tasks` and a job
// disappearing from it.
//
// The rule that keeps it from becoming noise: **a toast only for a job whose
// start this session actually saw.** These jobs run for minutes and the app
// may well have been opened halfway through one; announcing the end of
// something you were never told had begun is a notification about nothing.
// The centre still records both ends either way, because that is a record
// rather than an interruption.

//: The jobs seen running on the previous poll, keyed the way `taskKey` keys
//: them. A Map rather than a Set so a finish can name the job that ended
//: without needing the poll it vanished from to still carry it.
const seenRunningTasks = new Map();

//: The activity panel's row for each of those jobs, keyed the same way. Kept
//: beside `seenRunningTasks` rather than inside it because the two answer
//: different questions: that map is "did this session see it start", which is
//: what decides whether its end is announced, and this one is "which row on
//: screen is it".
const backgroundRunRows = new Map();

function taskKey(task) {
  // `name` distinguishes two downloads running at once; `kind` alone would
  // merge them into one job that appears to start twice and finish once.
  return `${task.kind || "job"}:${task.name || ""}`;
}

function noticeTaskTransitions(running, history) {
  const now = new Map(running.map((task) => [taskKey(task), task]));

  //: A running job's row keeps its fraction and its own status line up to
  //: date. It is the same run list the chat's skill runs land in, an
  //: autonomous pass rewriting tags in the background is exactly the "agent
  //: model activity" the report was about, and reading it off `/tasks` is how
  //: it gets a progress bar the chat runs cannot have.
  for (const [key, task] of now) {
    const run = backgroundRunRows.get(key);
    if (!run) continue;
    run.progress = typeof task.progress === "number" ? task.progress : null;
    run.detail = task.detail || "";
    renderAgentRunSummary(run);
  }

  for (const [key, task] of now) {
    if (seenRunningTasks.has(key)) continue;
    seenRunningTasks.set(key, task);
    const run = addAgentRun({
      kind: "job",
      name: task.label,
      icon: "ph:gear",
      detail: task.detail || "",
    });
    run.progress = typeof task.progress === "number" ? task.progress : null;
    renderAgentRunSummary(run);
    backgroundRunRows.set(key, run);
    openPanelForRun(run);
    recordNotification({
      kind: "task",
      title: `Started: ${task.label}`,
      detail: task.detail || "",
      // Keyed per *start*, not per job. It used to be `task-start:${key}`,
      // which deduped against localStorage, so the second time the
      // autonomous pass (or any recurring job) ran, its start recorded
      // nothing at all, forever, because an entry with that exact id was
      // already stored from the first run days earlier. The poll-repeat this
      // was defending against is already handled by `seenRunningTasks` two
      // lines up, which `continue`s before reaching here.
      key: `task-start:${key}:${Date.now()}`,
    });
  }

  for (const [key, task] of [...seenRunningTasks]) {
    if (now.has(key)) continue;
    seenRunningTasks.delete(key);
    const row = backgroundRunRows.get(key);
    backgroundRunRows.delete(key);
    // The outcome comes from the server's own history, on this same payload, 
    // "it stopped appearing in the running list" is true of a job that died as
    // much as one that succeeded, and a cheerful toast over a failure is how
    // people learn to ignore toasts. Newest first, so `find` takes the ending
    // that just happened rather than a previous run of the same job.
    const ended = history.find((item) => (item.kind || "job") === (task.kind || "job"));
    if (ended && ended.outcome === "failed") {
      endAgentRun(row, { state: "failed" });
      agentActivityNotice(`Failed: ${ended.label || task.label}`, { isError: true });
    } else if (ended && ended.outcome === "cancelled") {
      endAgentRun(row, { state: "stalled", detail: "cancelled" });
      // Not an error and not an achievement, the user stopped it and already
      // knows. Recorded in the centre by renderTaskHistory; no toast.
      continue;
    } else {
      endAgentRun(row, { state: "done" });
      agentActivityNotice(`Finished: ${(ended && ended.label) || task.label}`);
    }
  }
}

// --- optional extras (Settings → Optional extras) -----------------------------
//
// Each of these is a feature the app already offers and cannot run: the microphone
// buttons need faster-whisper, the desktop window needs pywebview, search by
// meaning needs sentence-transformers. The only way to switch one on was a
// terminal and a README.
//
// The catalogue is the **server's**, and the install is chosen by id from an
// allowlist there: the client never sends a package name. See
// `core/extras.py` for why that is the whole security property.
let extrasPollTimer = null;

async function renderExtras() {
  const list = $("extras-list");
  if (!list) return;
  const body = await apiJson("/extras", { silent: true }).catch(() => null);
  if (!body) return;

  list.replaceChildren();
  for (const extra of body.extras) {
    const li = document.createElement("li");
    li.className = "extras-row";

    const head = document.createElement("div");
    head.className = "entry-meta";
    // The name and its state chip are one flex item now, not two. Reported:
    // "there are also still wrapping issues in the packages tab with the
    // buttons, titles, and badges" -- the Tesseract row's title, its
    // "Installed" chip and its Reinstall/Remove buttons are three
    // independent flex children of one wrapping row, same shape as the
    // chat answer header's own wrap bug (see .answer-title). A long label
    // like "Search inside images (Tesseract OCR)" plus a chip plus two
    // buttons does not fit one line in the settings modal, and letting the
    // three fragment independently is what put them on three unrelated
    // lines instead of two related ones (title+chip, then actions).
    const title = document.createElement("span");
    title.className = "entry-title";
    const name = document.createElement("strong");
    name.textContent = extra.label;
    title.appendChild(name);
    head.appendChild(title);

    const actions = document.createElement("span");
    actions.className = "entry-actions";
    if (extra.installed) {
      // A tick, not a disabled button. "Installed" is the answer to the only
      // question this row asks, and a greyed-out Install invites a click that
      // will do nothing.
      // A chip, beside the name, not a coloured word wedged between the title
      // and the first button. Reported: "the installed and not ready yet
      // badges are poorly spaced and aligned and need affordance" -- as bare
      // text it had no box of its own, so it inherited the row's 0.4rem gap on
      // both sides and read as part of whichever neighbour you looked at
      // first. A chip says "state", a button says "press me", and this is a
      // state.
      const done = chip("ph:check-circle Installed", "extras-installed");
      title.appendChild(done);
      // And a way back out of the state detection cannot see. `find_spec`
      // answers "is it there", not "is it sound", a half-finished download or
      // a wheel built for the wrong platform imports and does not work, and
      // this is the button for that. Quiet, because it is the rarer need.
      // …except when nothing calls the package. Reinstalling a library the app
      // never imports cannot fix anything, because there is nothing to fix.
      if (!extra.unavailable) actions.appendChild(
        smallButton("ph:arrow-clockwise Reinstall", `Reinstall ${extra.label}`, async () => {
          const ok = await confirmDialog(
            `Reinstall ${extra.label}?\n\nUse this if the feature is switched ` +
              "on but not working, it downloads the package again from " +
              "scratch rather than trusting what is already there."
          );
          if (!ok) return;
          const result = await apiJson(`/extras/${extra.id}/install?reinstall=true`, {
            method: "POST",
          }).catch((e) => ({ started: false, message: e.message }));
          toast(result.message, !result.started);
          renderExtras();
        })
      );
      actions.appendChild(
        smallButton("ph:trash Remove", `Uninstall ${extra.label}`, async () => {
          const ok = await confirmDialog(
            `Remove ${extra.label}?\n\nThe feature it turns on stops working. ` +
              "Only the package itself is removed, anything it pulled in is " +
              "left alone, since something else may be using it."
          );
          if (!ok) return;
          const result = await apiJson(`/extras/${extra.id}/uninstall`, {
            method: "POST",
          }).catch((e) => ({ started: false, message: e.message }));
          toast(result.message, !result.started);
          renderExtras();
        })
      );
    } else if (extra.installing) {
      const busy = document.createElement("div");
      busy.className = "muted extras-install-progress";

      const text = document.createElement("span");
      text.className = "extras-install-progress-text";
      text.textContent = extra.step || "Installing…";

      const bar = document.createElement("progress");
      bar.className = "task-progress extras-install-progress-bar";

      busy.append(text, bar);
      actions.appendChild(busy);
    } else if (extra.unavailable) {
      // Greyed out rather than hidden. The row still earns its place, it says
      // what the app *will* be able to do, and hiding the two unfinished
      // extras would be tidier and less honest. The reason travels with the
      // button as its tooltip and is spelled out in full underneath, because a
      // disabled control whose reason is not visible is just a broken one.
      const blocked = smallButton("⬇ Install", extra.unavailable, () => {});
      blocked.disabled = true;
      actions.appendChild(blocked);
      // Same treatment as Installed, and for the same reason: it is the row's
      // state, so it sits with the name rather than in the action column.
      title.appendChild(chip("ph:hourglass Not ready yet", "extras-soon"));
    } else {
      actions.appendChild(
        smallButton("⬇ Install", `Install ${extra.label}`, async () => {
          const ok = await confirmDialog(
            `Install ${extra.label}?\n\n${extra.size}. It is downloaded from ` +
              "PyPI to this machine, and MemoryMap needs a restart afterwards " +
              "before the feature works."
          );
          if (!ok) return;
          const result = await apiJson(`/extras/${extra.id}/install`, {
            method: "POST",
          }).catch((e) => ({ started: false, message: e.message }));
          toast(result.message, !result.started);
          renderExtras();
        })
      );
    }
    head.appendChild(actions);
    li.appendChild(head);

    const enables = document.createElement("p");
    enables.className = "muted extras-enables";
    enables.textContent = extra.enables;
    li.appendChild(enables);

    const meta = document.createElement("p");
    meta.className = "muted extras-meta";
    meta.textContent = `${extra.packages.join(", ")} · ${extra.size}`;
    li.appendChild(meta);

    // Said before the button is pressed, not after: "this installs the library
    // but nothing uses it yet" is exactly the sort of thing that turns into a
    // bug report if it is discovered afterwards.
    if (extra.caveat) {
      const caveat = document.createElement("p");
      caveat.className = "muted extras-caveat";
      setLabel(caveat, `ph:warning ${extra.caveat}`);
      li.appendChild(caveat);
    }
    // The reason the button is grey, in full. Same shape as the caveat because
    // it is the same kind of sentence, the difference is that this one is
    // also enforced by `core/extras.py`, so it is a fact about the app rather
    // than advice about a choice.
    if (extra.unavailable) {
      const why = document.createElement("p");
      why.className = "muted extras-caveat";
      setLabel(why, `ph:traffic-cone ${extra.unavailable}`);
      li.appendChild(why);
    }
    list.appendChild(li);
  }

  $("extras-status").textContent = body.running
    ? body.step
    : body.outcome === "completed"
      ? `${body.step}`
      : body.outcome === "failed"
        ? `Install failed. ${body.step}`
        : "";
  const logWrap = $("extras-log-wrap");
  logWrap.classList.toggle("hidden", !body.log.length);
  $("extras-log").textContent = body.log.join("\n");

  // Poll only while something is running, and only while the panel is open.
  clearTimeout(extrasPollTimer);
  if (body.running && settingsModalOpen() && currentSettingsSection === "extras") {
    extrasPollTimer = setTimeout(renderExtras, 1500);
  }
  renderEmbedModels();

  // The model-size choice only means anything once faster-whisper is
  // actually there to load one.
  const voiceExtra = body.extras.find((e) => e.id === "voice");
  const wrap = $("voice-model-wrap");
  if (wrap) {
    wrap.classList.toggle("hidden", !voiceExtra?.installed);
    if (voiceExtra?.installed) {
      if (!prefsCache) prefsCache = await apiJson("/preferences").catch(() => null);
      $("voice-model-select").value = prefsCache?.voice_model || "base";
    }
  }
}

// --- embedding models, on the same screen as the packages ------------------------
//
// Reuses `.extras-row` deliberately. These are two lists of "things downloaded
// to this machine, with a way to undo it", and giving the second one its own
// row style would make them look like different kinds of thing when the whole
// argument for putting them together is that they are not.
let embedPollTimer = null;

async function renderEmbedModels() {
  const list = $("embed-models-list");
  if (!list) return;
  const body = await apiJson("/embedding-models", { silent: true }).catch(() => null);
  if (!body) return;

  list.replaceChildren();
  for (const model of body.models) {
    const li = document.createElement("li");
    li.className = "extras-row";

    const head = document.createElement("div");
    head.className = "entry-meta";
    const name = document.createElement("strong");
    name.textContent = model.label + (model.default ? " · default" : "");
    head.appendChild(name);

    const actions = document.createElement("span");
    actions.className = "entry-actions";
    if (model.downloading) {
      const busy = document.createElement("span");
      busy.className = "muted";
      busy.textContent = "Downloading…";
      actions.appendChild(busy);
    } else if (model.installed) {
      const done = document.createElement("span");
      done.className = "extras-installed";
      done.textContent = `✓ ${model.on_disk} on disk`;
      actions.appendChild(done);
      // The same argument the packages' Reinstall makes: "the directory is
      // there" is not "the model is sound". A download interrupted halfway
      // leaves a snapshot that loads and produces nonsense, and fetching over
      // the top of it resumes the same broken files, so this removes first.
      if (body.can_download) {
        actions.appendChild(
          smallButton("ph:arrow-clockwise Re-download", `Fetch ${model.label} again from scratch`, async () => {
            if (!(await confirmDialog(
              `Download ${model.label} again?\n\nThe copy on this machine is ` +
                "deleted first, so this is the fix for one that arrived broken."
            ))) return;
            const result = await apiJson(
              `/embedding-models/${model.id}/download?reinstall=true`,
              { method: "POST" }
            ).catch((e) => ({ started: false, message: e.message }));
            toast(result.message, !result.started);
            renderEmbedModels();
          })
        );
      }
      actions.appendChild(
        smallButton("ph:trash Remove", `Delete ${model.label} from this machine`, async () => {
          if (!(await confirmDialog(
            `Remove ${model.label}?\n\nIt frees ${model.on_disk}. Nothing is ` +
              "lost that a download cannot bring back, but if this is the " +
              "model in use, searching falls back to keywords until it returns."
          ))) return;
          const result = await apiJson(`/embedding-models/${model.id}`, {
            method: "DELETE",
          }).catch((e) => ({ removed: false, message: e.message }));
          toast(result.message, !result.removed);
          renderEmbedModels();
        })
      );
    } else {
      const get = smallButton("⬇ Download", `Fetch ${model.label}`, async () => {
        if (!(await confirmDialog(
          `Download ${model.label}?\n\n${model.size}, fetched from HuggingFace ` +
            "to this machine. It is the one thing on this screen that needs " +
            "the internet."
        ))) return;
        const result = await apiJson(`/embedding-models/${model.id}/download`, {
          method: "POST",
        }).catch((e) => ({ started: false, message: e.message }));
        toast(result.message, !result.started);
        renderEmbedModels();
      });
      // Without huggingface_hub there is nothing to download *with*, so the
      // button says so rather than failing on an ImportError nobody can read.
      if (!body.can_download) {
        get.disabled = true;
        get.title =
          "Needs the huggingface_hub library, it arrives with “Search by " +
          "meaning” in the list above.";
      }
      actions.appendChild(get);
    }
    head.appendChild(actions);
    li.appendChild(head);

    const about = document.createElement("p");
    about.className = "muted extras-enables";
    about.textContent = model.about;
    li.appendChild(about);

    const meta = document.createElement("p");
    meta.className = "muted extras-meta";
    meta.textContent = `${model.repo} · ${model.size}`;
    li.appendChild(meta);
    list.appendChild(li);
  }

  // Where they are, in as many words. "Somewhere in your home directory" is
  // the answer people are given everywhere else and it is the reason this
  // screen had to exist.
  $("embed-models-cache").textContent = `Kept in ${body.cache}`;
  $("embed-models-status").textContent = body.running
    ? body.step
    : body.outcome
      ? body.step
      : "";

  clearTimeout(embedPollTimer);
  if (body.running && settingsModalOpen() && currentSettingsSection === "extras") {
    embedPollTimer = setTimeout(renderEmbedModels, 1500);
  }
}

// --- Wave N: tasks manager (see and quit background jobs) ---------------------------

// The list is built by the server (GET /tasks), not assembled here from
// whatever happened to be in the model status. It used to know about exactly
// two jobs, a re-index and a model download, so the embedding model loading
// at startup and the SearXNG install, which is minutes long, ran with nothing
// on this screen to say so. Rendering whatever the server sends means the
// next background job appears here without touching this file.
// `payload` is the /tasks body when the caller has already fetched it, the
// status poll has, once, for the bar. Opening the panel passes nothing and
// fetches, so the list is filled the moment you get there rather than at the
// next tick.
async function renderTasks(payload) {
  const list = $("task-list");
  const body = payload || (await apiJson("/tasks", { silent: true }).catch(() => null));
  const jobs = (body && body.tasks) || [];
  list.replaceChildren();
  $("tasks-empty").classList.toggle("hidden", jobs.length > 0);
  for (const job of jobs) {
    const li = document.createElement("li");
    // The heading row is the job and its Quit button; everything else stacks
    // underneath at full width. The bar used to sit inline after the label,
    // where it ran off the right edge of the card on a long job name.
    const row = document.createElement("div");
    row.className = "entry-meta";
    const name = document.createElement("strong");
    name.textContent = job.label;
    row.appendChild(name);

    if (job.cancellable) {
      const actions = document.createElement("span");
      actions.className = "entry-actions";
      actions.appendChild(
        smallButton("Quit", "Stop this job", async () => {
          // `/tasks/cancel`, not `/models/jobs/cancel`: the old endpoint knew
          // about a re-index and a model pull and nothing else, so this
          // button only ever appeared on two of the eight kinds this panel
          // lists. The server now answers for all of them and says what it
          // actually did: a pip install is terminated, an autonomous pass
          // stops at its next safe point and stays off for a while, an
          // embedding download stops after the file it is on. Reporting the
          // server's own sentence rather than a fixed "asked it to stop"
          // is the difference between the three.
          try {
            const result = await apiJson("/tasks/cancel", {
              method: "POST",
              body: JSON.stringify({ kind: job.kind, name: job.name || "" }),
            });
            toast(result.detail || (result.stopped ? "Stopping." : "It had already finished."));
          } catch (e) {
            toast(e.message, true);
          }
          renderTasks();
          refreshModelStatus();
        })
      );
      row.appendChild(actions);
    }
    li.appendChild(row);

    if (job.detail) {
      const detail = document.createElement("p");
      detail.className = "muted task-detail";
      detail.textContent = job.detail;
      li.appendChild(detail);
    }

    // A bar only where there is a real fraction to show. A progress bar that
    // guesses is worse than one that admits it can't say: and under reduced
    // motion an indeterminate animation freezes and reads as a fault.
    if (typeof job.progress === "number") {
      const bar = document.createElement("progress");
      bar.max = 1;
      bar.value = job.progress;
      bar.className = "task-progress";
      li.appendChild(bar);
    }

    // What the job itself is printing. A bar answers "is it working?" only
    // while it moves, and pip can sit on one number for minutes, the output
    // is the thing that keeps changing, so it is the real answer to "has it
    // frozen?". Open by default while a job is running; there is nothing to
    // be spared from here.
    if ((job.log || []).length) {
      const fold = document.createElement("details");
      fold.className = "task-log";
      fold.open = taskLogsOpen.has(job.kind);
      fold.addEventListener("toggle", () => {
        if (fold.open) taskLogsOpen.add(job.kind);
        else taskLogsOpen.delete(job.kind);
      });
      const summary = document.createElement("summary");
      summary.textContent = `What it's doing (${job.log.length} lines)`;
      const pre = document.createElement("pre");
      pre.className = "task-log-lines";
      pre.textContent = job.log.join("\n");
      fold.append(summary, pre);
      li.appendChild(fold);

      // Listen for scroll events to track if the user has scrolled up from the bottom
      pre.addEventListener("scroll", () => {
        const isAtBottom = Math.abs(pre.scrollHeight - pre.scrollTop - pre.clientHeight) < 5;
        taskLogScrollStates.set(job.kind, isAtBottom);
      });

      // Follow the tail, the way a terminal does, unless the user scrolled up
      if (fold.open && taskLogScrollStates.get(job.kind) !== false) {
        // Use a slight timeout to ensure rendering is complete before scrolling
        requestAnimationFrame(() => {
          pre.scrollTop = pre.scrollHeight;
        });
      }
    }
    list.appendChild(li);
  }
  renderTaskHistory((body && body.history) || []);
}

// What has stopped, newest first. Separate from the running list on purpose:
// mixing them means a finished job and a running one look alike at a glance,
// and the question this screen answers most often is "is it still going?".
const TASK_OUTCOMES = {
  completed: { icon: "ph:check-circle", className: "" },
  failed: { icon: "ph:warning", className: "task-failed" },
  // Not an error. Reporting a user's own decision in red is how people learn
  // to ignore red.
  cancelled: { icon: "ph:x", className: "muted" },
};

function renderTaskHistory(history) {
  const box = $("task-history-box");
  const list = $("task-history");
  // A finished background job goes into the notifications centre whether or
  // not this screen is open, which is the point of the centre (§36E). These
  // jobs are long: an install or a re-index finishes minutes after you stopped
  // watching it, and until now the only record was a screen inside Settings
  // that you had to know to open. Recorded first, so it happens even when the
  // Tasks panel is not on screen and the two elements below are missing.
  for (const item of history) {
    recordNotification({
      kind: item.outcome === "failed" ? "error" : "task",
      title: item.label,
      detail: item.detail || "",
      // Keyed on the job and when it stopped, so the three-second re-render
      // does not add the same finished job over and over.
      key: `task:${item.kind || item.label}:${item.at}`,
    });
  }
  if (!box || !list) return;
  box.classList.toggle("hidden", history.length === 0);
  list.replaceChildren();
  for (const item of history) {
    const style = TASK_OUTCOMES[item.outcome] || TASK_OUTCOMES.completed;
    const li = document.createElement("li");
    if (style.className) li.className = style.className;

    const row = document.createElement("div");
    row.className = "entry-meta";
    const name = document.createElement("strong");
    setLabel(name, `${style.icon} ${item.label}`);
    const when = document.createElement("span");
    when.className = "muted";
    // Which model actually did the work (captioning, OCR, the weekly
    // digest): recorded by the backend all along (`taskhistory.record`'s
    // `name` param) but never shown here, so "which model answered this"
    // was answerable only by opening the log console. Asked about
    // directly (BACKLOG.md §95 item A.3).
    when.textContent = item.name
      ? `${relativeTime(item.at)} · ${item.name}`
      : relativeTime(item.at);
    row.append(name, when);
    li.appendChild(row);

    // The reason, which is the whole point for a failure, until now it
    // existed only in the log console, a screen you have to know to open.
    if (item.detail) {
      const detail = document.createElement("p");
      detail.className = "muted task-detail";
      setLabel(detail, item.detail);
      li.appendChild(detail);
    }
    list.appendChild(li);
  }
}

// Which task logs the user has opened, kept across the 3-second re-render so
// a fold doesn't slam shut under them.
const taskLogsOpen = new Set(["searxng"]);
const taskLogScrollStates = new Map();

// Model pickers (rewritten, Wave O). The old version let the status poll
// (every ~3s while Settings is open) reset the dropdown to the SAVED
// model, so a selection would "switch back after a few seconds".
//
// New rule, dead simple: the option list is (re)built ONLY when the SET
// of installed model names actually changes (order-independent: Ollama
// doesn't return a stable order). The selected value is set once, when
// the list is first built; after that a poll never touches `.value`, so
// your choice stays put until you Apply (which re-syncs to the new saved
// value). No timing-sensitive "userChosen" flag to get wrong.
function _namesSignature(names) {
  return [...names].sort().join("|");
}

function fillModelSelect(select, names, extraFirst, savedValue) {
  const wanted = extraFirst ? [extraFirst.value, ...names] : names;
  const signature = _namesSignature(wanted);
  if (select.dataset.sig === signature) return; // same options → leave it alone
  select.dataset.sig = signature;
  const previous = select.value; // preserve a live selection across a rebuild
  select.replaceChildren();
  if (extraFirst) {
    const option = document.createElement("option");
    option.value = extraFirst.value;
    option.textContent = extraFirst.label;
    select.appendChild(option);
  }
  for (const name of names) {
    const option = document.createElement("option");
    option.value = name;
    option.textContent = name;
    select.appendChild(option);
  }
  // Prefer the value already showing; else the saved preference.
  const values = [...select.options].map((o) => o.value);
  const match =
    (previous && values.includes(previous) && previous) ||
    values.find((v) => v === savedValue) ||
    values.find((v) => v.split(":")[0] === savedValue);
  if (match !== undefined) select.value = match;
}

function renderChatModelPicker(status) {
  const names = status.installed_models.map((m) => m.name);
  fillModelSelect($("chat-model-select"), names, null, status.chat_model);
  $("chat-model-note").textContent =
    status.chat_model_installed === false
      ? `Active model “${status.chat_model}” is not installed any more, pick another or download it below.`
      : `Active: ${status.chat_model}`;
}

// Nielsen #6, recognition over recall: which model answers was previously
// knowable only by opening Settings → Models, and only then if the backend
// is Ollama (the picker above is gated on ollama_running). status.chat_model
// itself isn't backend-specific, so this reads it straight off the poll
// loop instead of piggybacking on that gated render.
function renderChatActiveModelBadge() {
  const badge = $("chat-active-model");
  if (!badge) return;
  const name = modelStatus && modelStatus.chat_model;
  badge.hidden = !name;
  //: The short form in the badge, the full id in the tooltip below, the
  //: badge is 22ch wide and a HuggingFace id is routinely longer than that.
  badge.textContent = shortModelName(name);
  // The badge itself ellipsis-truncates a long id (a full HuggingFace path
  // easily runs past the header), the full name is still one hover away.
  badge.title = name
    ? `The model currently answering in this chat: ${name}: click for what it is and what it can do`
    : "";
}

//: **What this model actually is.** Asked for: "in chat I want more details in
//: features, including model attributes, token expense distribution, more
//: features."
//:
//: `GET /models/spec` has existed since §11, size, quantisation, family, the
//: declared window against the one the app will really run it at, and the
//: tri-state capability flags: and **nothing in the frontend had ever called
//: it.** A whole endpoint that never ran once, which is this repo's second
//: recurring failure shape. It answers the first question anyone has when a
//: model behaves oddly ("can this one even use tools?") and the answer was
//: only discoverable by trying it and reading the failure.
//:
//: Pressing the badge opens this rather than jumping straight to Settings: the
//: panel is what you wanted nine times in ten, and "change it" is a button
//: inside it for the tenth.
//: Places the panel under the badge, in viewport coordinates. It is
//: `position: fixed` (see the stylesheet's own note on why `absolute` put it
//: off the bottom of the screen), so nothing positions it but this.
function placeChatModelPanel() {
  const panel = $("chat-model-panel");
  const badge = $("chat-active-model");
  if (!panel || !badge || panel.classList.contains("hidden")) return;
  const margin = 8;
  panel.style.left = "0px";
  panel.style.top = "0px";
  const anchor = badge.getBoundingClientRect();
  const box = panel.getBoundingClientRect();
  let left = anchor.left;
  if (left + box.width > window.innerWidth - margin) {
    left = window.innerWidth - margin - box.width;
  }
  if (left < margin) left = margin;
  let top = anchor.bottom + margin;
  if (top + box.height > window.innerHeight - margin) {
    // Above the badge when there is no room below it, and pinned inside the
    // window when there is room neither way, never off the edge, which is
    // the whole bug this is here to end.
    const above = anchor.top - margin - box.height;
    top = above >= margin ? above : Math.max(margin, window.innerHeight - margin - box.height);
  }
  panel.style.left = `${Math.round(left)}px`;
  panel.style.top = `${Math.round(top)}px`;
}

//: The panel fills in asynchronously (`GET /models/spec`), and it grows when
//: it does: so it is placed again once the content lands, and on any resize
//: or scroll that moves the badge out from under it.
window.addEventListener("resize", placeChatModelPanel);
window.addEventListener("scroll", placeChatModelPanel, true);

async function openChatModelPanel() {
  const name = modelStatus && modelStatus.chat_model;
  const panel = $("chat-model-panel");
  if (!panel || !name) return;
  panel.replaceChildren();
  const head = document.createElement("div");
  head.className = "row space-between chat-model-panel-head";
  const title = document.createElement("strong");
  title.textContent = name;
  title.className = "chat-model-panel-name";
  head.appendChild(title);
  const close = smallButton("ph:x", "Close", () => panel.classList.add("hidden"));
  close.classList.add("icon-only");
  head.appendChild(close);
  panel.appendChild(head);

  const list = document.createElement("dl");
  list.className = "chat-model-facts";
  const loading = document.createElement("p");
  loading.className = "muted";
  loading.textContent = "Reading the model's own specification…";
  panel.append(list, loading);
  panel.classList.remove("hidden");
  placeChatModelPanel();

  const spec = await apiJson(`/models/spec?name=${encodeURIComponent(name)}`).catch(() => null);
  //: The panel was measured empty a moment ago; it is a different height now.
  placeChatModelPanel();
  loading.remove();
  if (!spec) {
    const failed = document.createElement("p");
    failed.className = "muted";
    //: Named as a *backend* silence rather than a model fault: the usual cause
    //: is that Ollama is not running, and "unknown" with no reason sends
    //: people looking at the wrong thing.
    failed.textContent =
      "The backend didn't answer. This needs the model runner to be up, everything else in this panel comes from it.";
    panel.appendChild(failed);
    return;
  }
  const fact = (label, value, why) => {
    if (value === null || value === undefined || value === "") return;
    const dt = document.createElement("dt");
    dt.textContent = label;
    const dd = document.createElement("dd");
    dd.textContent = String(value);
    if (why) dd.title = why;
    list.append(dt, dd);
  };
  fact("Family", spec.family, "The architecture this model is built on");
  fact("Size", spec.parameters, "How many parameters it has");
  fact("Quantisation", spec.quantisation, "How much its weights were compressed to fit in memory");
  if (spec.context_length) {
    fact(
      "Declared window",
      `${compactTokens(spec.context_length)} tokens`,
      "What the model says it can hold"
    );
  }
  if (spec.usable_context) {
    fact(
      "Used here",
      `${compactTokens(spec.usable_context)} tokens`,
      "What this app actually runs it at, often lower on purpose, to leave room for the key/value cache"
    );
  }
  //: Tri-state, and rendered as three states. `null` means this backend does
  //: not say, and drawing that as "No" would be a confident lie about a model
  //: that works fine: the endpoint's own docstring makes the same point.
  const flag = (value) => (value === null || value === undefined ? "Not reported" : value ? "Yes" : "No");
  fact("Can call tools", flag(spec.supports_tools), "Whether agent mode can work with this model");
  fact("Can show its reasoning", flag(spec.supports_thinking));
  fact("Can see images", flag(spec.supports_vision), "Whether it can read a picture or a scanned page");

  const change = smallButton("ph:gear Change the model", "Open Settings → Models", () => {
    panel.classList.add("hidden");
    openSettingsModal("models", "chat-model-select");
  });
  panel.appendChild(change);
}

$("chat-active-model")?.addEventListener("click", () => {
  const panel = $("chat-model-panel");
  if (panel && !panel.classList.contains("hidden")) {
    panel.classList.add("hidden");
    return;
  }
  openChatModelPanel();
});

function renderUtilityModelPicker(status) {
  const names = status.installed_models.map((m) => m.name);
  fillModelSelect(
    $("utility-model-select"),
    names,
    { value: "", label: "Same as chat model" },
    status.utility_model || ""
  );
}

function renderVisionModelPicker(status) {
  const names = status.installed_models.map((m) => m.name);
  fillModelSelect(
    $("vision-model-select"),
    names,
    // The one model preference in this app that does NOT default to "same
    // as chat model" (model_manager.py's vision_model() explains why: a
    // chat model silently can't see images more often than it can).
    { value: "", label: "Auto-detect" },
    status.vision_model || ""
  );
  // Auto-detect is a choice with no fixed answer, say what it resolved to
  // right now, the same reason chat-model-note exists, rather than leaving
  // "Auto-detect" to mean nothing concrete in the UI.
  const note = $("vision-model-note");
  if (status.vision_model) {
    note.textContent = `Active: ${status.vision_model}`;
  } else if (status.vision_model_resolved) {
    note.textContent = `Auto-detect: currently: ${status.vision_model_resolved}`;
  } else {
    note.textContent =
      "Auto-detect: no installed model reports it can see images yet.";
  }
}

// Separate from the vision picker above because the jobs are separate, see
// ModelManager.ocr_model. "Automatic" here means something more specific than
// the vision picker's "Auto-detect": it prefers an installed document reader
// over a general vision model, because both report the same `vision`
// capability and only one of them is built to transcribe a page.
function renderOcrModelPicker(status) {
  const names = status.installed_models.map((m) => m.name);
  fillModelSelect(
    $("ocr-model-select"),
    names,
    { value: "", label: "Automatic" },
    status.ocr_model || ""
  );
  const note = $("ocr-model-note");
  if (status.ocr_model) {
    note.textContent = `Active: ${status.ocr_model}`;
  } else if (status.ocr_model_resolved) {
    note.textContent = `Automatic: currently: ${status.ocr_model_resolved}`;
  } else {
    note.textContent =
      "Automatic: nothing installed can read text off a page yet.";
  }
}

function renderAutonomousModelPicker(status) {
  const names = status.installed_models.map((m) => m.name);
  fillModelSelect(
    $("pref-autonomous-model"),
    names,
    { value: "", label: "Same as utility model" },
    (window.prefsCache && window.prefsCache.autonomous_tasks_model) || ""
  );
}

function renderEmbeddingPicker(status) {
  // Name the built-in model rather than describing it. "Works out of the box,
  // no download" was wrong on both counts: it fetches ~130 MB from Hugging
  // Face the first time, which is a long quiet wait to have described as
  // needing nothing.
  $("builtin-model-name").textContent = status.active_embedding_model
    ? `${status.active_embedding_model}, downloaded once on first use`
    : "downloaded once on first use";
  // The backend radios only reflect the saved value while the user has no
  // pending choice of their own.
  //
  // A focus check alone was not enough, and it is why switching search
  // engines was reported as impossible. Picking a radio does not save
  // anything, "Apply & re-index" does, so between the click and the apply
  // there is a pending choice the server doesn't know about yet. The moment
  // focus moved (clicking Apply, or just tabbing away) the status poll ran,
  // found `touching` false, and reset the radio to the *saved* backend. The
  // selection visibly snapped back, so the setting looked stuck.
  //
  // Same `userChosen` latch the model selects already use, cleared once the
  // choice is actually applied.
  const group = document.querySelectorAll('input[name="emb-backend"]');
  const touching =
    document.activeElement?.name === "emb-backend" ||
    [...group].some((radio) => radio.dataset.userChosen === "1");
  if (!touching) {
    for (const radio of document.querySelectorAll('input[name="emb-backend"]')) {
      radio.checked = radio.value === status.embedding_backend;
    }
  }
  const names = (status.installed_models || []).map((m) => m.name);
  fillModelSelect(
    $("embedding-model-select"),
    names,
    null,
    status.embedding_model
  );
  // With Ollama down there are no embedding models to pick from, so that half
  // of the choice is disabled and says why, rather than the whole section
  // disappearing, which is what used to happen.
  const offline = !status.ollama_running;
  $("embedding-model-select").disabled = offline;
  $("embedding-apply").disabled = offline;
  document.querySelector('input[name="emb-backend"][value="ollama"]').disabled = offline;
  $("embedding-ollama-note").classList.toggle("hidden", offline);
  $("embedding-offline-note").classList.toggle("hidden", !offline);
}

// The button lives in index.html (see `#reindex-box`) rather than being built
// here: `test_frontend_ids.py` refuses an id this file looks up that the
// markup never declares, and it is right to, a control that exists only in
// JS is one nobody can find by reading the page.
function wireReindexButton() {
  const button = $("reindex-start");
  if (!button || button.dataset.wired === "1") return;
  button.dataset.wired = "1";
  setLabel(button, "ph:arrows-clockwise Rebuild search index");
  button.addEventListener("click", async () => {
    button.disabled = true;
    try {
      await apiJson("/models/reindex", { method: "POST" });
      toast("Rebuilding the search index…");
      refreshModelStatus?.();
    } catch (error) {
      // A 409 is not a failure to report as one: it means the thing the user
      // asked for is already happening.
      toast(error.message, !/already running/i.test(error.message || ""));
    } finally {
      button.disabled = false;
    }
  });
}

function renderReindex(status) {
  const box = $("reindex-box");
  const job = status.reindex;
  const running = job && job.status === "running";
  wireReindexButton();
  // The box is no longer only a progress readout, so it stays visible, the
  // heading and the progress bar are what come and go with the job.
  box.classList.remove("hidden");
  const heading = box.querySelector("h3");
  if (heading) heading.textContent = running ? "Re-indexing your notes…" : "Search index";
  $("reindex-progress").classList.toggle("hidden", !running);
  $("reindex-label").classList.toggle("hidden", !running);
  $("reindex-start").classList.toggle("hidden", running);
  if (running) {
    $("reindex-progress").value = job.done;
    $("reindex-progress").max = Math.max(job.total, 1);
    $("reindex-label").textContent = `${job.done} of ${job.total} notes re-indexed`;
  }
  //: **Say when it is actually worth doing.** Asked for: "suggest rebuilding
  //: the search index upon large changes". The backend counts notes that
  //: arrived or vanished in bulk (`mark_index_stale`); this is the only place
  //: that counter is ever shown, and it says nothing at all until the count
  //: crosses the threshold the same module sets, a permanent nudge is
  //: furniture, and a nudge after every third note is noise.
  const stale = Number(status.index_stale_notes || 0);
  const threshold = Number(status.index_stale_suggest_at || 20);
  const staleLine = $("reindex-stale");
  if (staleLine) {
    const worth = !running && stale >= threshold;
    staleLine.classList.toggle("hidden", !worth);
    if (worth) {
      staleLine.textContent =
        `${stale} notes have been added or removed in bulk since the last rebuild, ` +
        "semantic search may be missing them.";
    }
  }
}

function renderInstalledModels(status) {
  const box = $("installed-box");
  const list = $("installed-list");
  const models = status.installed_models || [];
  box.classList.toggle("hidden", models.length === 0);
  list.replaceChildren();

  // Models the app is actively pointing at can't be removed (would break it).
  const inUse = new Set([status.chat_model]);
  if (status.utility_model) inUse.add(status.utility_model);
  if (status.vision_model) inUse.add(status.vision_model);
  //: The OCR reader is a fourth assignable role and was missing from this set,
  //: so a model set as the OCR model showed a Remove button instead of "in
  //: use", reported directly. Both the chosen name and what it actually
  //: resolves to: the setting may be blank ("use the vision model") or name a
  //: model by a tag Ollama reports differently.
  if (status.ocr_model) inUse.add(status.ocr_model);
  if (status.ocr_model_resolved) inUse.add(status.ocr_model_resolved);
  if (status.vision_model_resolved) inUse.add(status.vision_model_resolved);
  if (status.embedding_backend === "ollama") inUse.add(status.embedding_model);
  const usedBases = new Set([...inUse].map((n) => (n || "").split(":")[0]));

  for (const model of models) {
    const li = document.createElement("li");
    const name = document.createElement("span");
    name.className = "model-name";
    name.textContent = model.name;
    const info = document.createElement("span");
    info.className = "model-info";
    info.textContent = model.size ? `${(model.size / 1e9).toFixed(1)} GB` : "";
    li.append(name, info);

    const used = inUse.has(model.name) || usedBases.has(model.name.split(":")[0]);
    if (used) {
      li.appendChild(chip("in use", "tag"));
    } else {
      li.appendChild(
        smallButton("Remove", `Uninstall ${model.name}`, async (event) => {
          if (
            !(await confirmDialog(
              `Remove “${model.name}” from Ollama? This frees its disk space, ` +
                "you can re-download it any time."
            ))
          )
            return;
          event.target.disabled = true;
          try {
            await api("/models/delete", {
              method: "POST",
              body: JSON.stringify({ name: model.name }),
            });
            toast(`Removed ${model.name}.`);
            refreshModelStatus();
          } catch (error) {
            toast(error.message, true);
            event.target.disabled = false;
          }
        })
      );
    }
    list.appendChild(li);
  }
}

//: Human-readable section headings for SUGGESTED_MODELS' own dict keys
//: (model_manager.py): asked for directly: the list read as one long,
//: undifferentiated column with the type buried inside each row's own
//: "kind · size · purpose" text, so nothing set "the small, fast ones"
//: apart from "the one that reads images" at a glance. Order matches the
//: backend dict's own insertion order (Object.entries preserves it),
//: which is already curated small-to-large within each group, grouping
//: here doesn't re-sort that, only labels the breaks between groups.
const SUGGESTED_KIND_LABELS = {
  text: "Text",
  moe: "Mixture-of-experts (MoE): big download, small working set",
  embedding: "Embeddings: for semantic search",
  vision: "Vision: can see images",
};

function renderSuggested(status) {
  const list = $("suggested-list");
  if (!suggestedCatalog) return;
  list.replaceChildren();
  const installedNames = new Set(
    status.installed_models.flatMap((m) => [m.name, m.name.split(":")[0]])
  );

  for (const [kind, models] of Object.entries(suggestedCatalog)) {
    if (!models.length) continue;
    const heading = document.createElement("li");
    heading.className = "suggested-group-label";
    heading.textContent = SUGGESTED_KIND_LABELS[kind] || kind;
    list.appendChild(heading);
    for (const model of models) {
      const li = document.createElement("li");
      const name = document.createElement("span");
      name.className = "model-name";
      name.textContent = model.name;
      const info = document.createElement("span");
      info.className = "model-info";
      // "~2.0 GB" for a figure we shipped and cannot check, the exact size for
      // one the backend has actually measured (§35J). The tilde is the whole
      // signal: this number is the one someone checks their free disk against
      // before committing to a multi-gigabyte download, so presenting a stale
      // guess as fact is the part that was wrong, not the guess itself.
      const approximate = model.size_source !== "measured";
      const size = approximate ? `~${String(model.size).replace(/^~/, "")}` : model.size;
      // No longer repeats `kind` here: the group heading above says it once
      // for the whole section instead of on every single row under it.
      info.textContent = `${size} · ${model.purpose}`;
      info.title = approximate
        ? "Approximate download size: the exact figure shows once it's installed."
        : "Measured on your machine.";
      li.append(name, info);

      const pull = (status.pulls || {})[model.name];
      if (installedNames.has(model.name)) {
        li.appendChild(chip("installed ✓", "confidence"));
      } else if (pull && pull.status === "running") {
        const progress = document.createElement("progress");
        progress.max = Math.max(pull.total, 1);
        progress.value = pull.done;
        progress.style.width = "120px";
        li.appendChild(progress);
      } else {
        if (pull && pull.status === "error") {
          li.appendChild(chip("failed: retry?", "review"));
        }
        li.appendChild(
          smallButton(
            "Download",
            `Download ${model.name} with Ollama`,
            async (event) => {
              event.target.disabled = true;
              try {
                await api("/models/pull", {
                  method: "POST",
                  body: JSON.stringify({ name: model.name }),
                });
                refreshModelStatus();
              } catch (error) {
                toast(error.message, true);
                event.target.disabled = false;
              }
            },
            false
          )
        );
      }
      list.appendChild(li);
    }
  }
}

// One click for the sentence #embedding-error already prints: download
// nomic-embed-text (skipped if it's already installed), then switch the
// search engine to it and re-index. Self-contained polling rather than
// riding the shared `modelStatus` refresh loop: that loop backs off to a
// slow cadence when nothing else is running, which would make a fresh
// download look stalled for up to 20s at a time; this polls every second
// for exactly as long as this one operation is in flight.
async function runEmbeddingFallback() {
  if (embeddingFallbackRunning) return;
  embeddingFallbackRunning = true;
  const button = $("embedding-error-fix");
  const status = $("embedding-error-fix-status");
  button.disabled = true;
  const setStatus = (text) => {
    status.textContent = text;
  };
  try {
    const already = (modelStatus?.installed_models || []).some(
      (m) => m.name === EMBEDDING_FALLBACK_MODEL || m.name.split(":")[0] === EMBEDDING_FALLBACK_MODEL
    );
    if (!already) {
      setStatus(`Downloading ${EMBEDDING_FALLBACK_MODEL}…`);
      try {
        await api("/models/pull", {
          method: "POST",
          body: JSON.stringify({ name: EMBEDDING_FALLBACK_MODEL }),
        });
      } catch (error) {
        // 409 "Already downloading" means someone else (or a previous
        // click) already started this exact pull, fall through to the
        // same wait loop rather than treating it as a failure.
        if (!/already downloading/i.test(error.message || "")) throw error;
      }
      // Poll until the pull leaves "running", succeeded (it drops out of
      // `pulls` once installed) or failed (status "error").
      for (;;) {
        await new Promise((resolve) => setTimeout(resolve, 1000));
        const poll = await apiJson("/models/status", { silent: true }).catch(() => null);
        if (!poll) continue; // a transient miss mid-download isn't a failure
        const pull = (poll.pulls || {})[EMBEDDING_FALLBACK_MODEL];
        if (pull && pull.status === "error") {
          throw new Error(pull.error || `Couldn't download ${EMBEDDING_FALLBACK_MODEL}.`);
        }
        const nowInstalled = (poll.installed_models || []).some(
          (m) => m.name === EMBEDDING_FALLBACK_MODEL || m.name.split(":")[0] === EMBEDDING_FALLBACK_MODEL
        );
        if (nowInstalled || !pull) break;
        setStatus(
          pull.total
            ? `Downloading ${EMBEDDING_FALLBACK_MODEL}… ${Math.round((pull.done / pull.total) * 100)}%`
            : `Downloading ${EMBEDDING_FALLBACK_MODEL}…`
        );
      }
    }
    setStatus("Switching search engine and re-indexing…");
    await api("/models/embedding-backend", {
      method: "POST",
      body: JSON.stringify({ backend: "ollama", model: EMBEDDING_FALLBACK_MODEL }),
    });
    toast(`Switched to ${EMBEDDING_FALLBACK_MODEL}: re-indexing your notes now.`);
    setStatus("");
  } catch (error) {
    toast(error.message || `Couldn't switch to ${EMBEDDING_FALLBACK_MODEL}.`, true);
    setStatus("");
  } finally {
    embeddingFallbackRunning = false;
    button.disabled = false;
    refreshModelStatus();
  }
}
$("embedding-error-fix").addEventListener("click", runEmbeddingFallback);

