// --- Wave N: AI improve-writing (before/after, user approves) -----------------------

let improveMode = "proofread";
let improveTarget = null; // the textarea to write the accepted result into
let improveCustomInstruction = "";

function openImprove(targetTextarea) {
  const text = targetTextarea.value.trim();
  if (!text) {
    toast("Write something first, then improve it.", true);
    return;
  }
  improveTarget = targetTextarea;
  improveMode = "proofread";
  improveCustomInstruction = "";
  $("improve-custom-input").value = "";
  $("improve-custom-row").classList.add("hidden");
  for (const b of document.querySelectorAll(".improve-mode"))
    b.classList.toggle("active", b.dataset.mode === "proofread");
  $("improve-original").textContent = text;
  overlayReturnFocus = document.activeElement;
  $("improve-overlay").classList.remove("hidden");
  $("improve-close").focus();
  runImprove();
}

function closeImprove() {
  $("improve-overlay").classList.add("hidden");
  overlayReturnFocus?.focus?.();
  overlayReturnFocus = null;
}

async function runImprove() {
  const status = $("improve-status");
  const result = $("improve-result");
  if (improveMode === "custom" && !improveCustomInstruction.trim()) {
    // Nothing to send yet, the box just opened on "Custom" and the person
    // hasn't typed anything. Prompting here instead of calling the API with
    // an empty instruction (which the backend would reject anyway) so the
    // very first thing that happens after picking Custom isn't an error.
    status.textContent = "Say what you want changed, then press Go.";
    status.classList.remove("error");
    result.textContent = "";
    $("improve-apply").disabled = true;
    return;
  }
  result.textContent = "";
  status.textContent = "The AI is editing…";
  status.classList.remove("error");
  $("improve-apply").disabled = true;
  try {
    const body = await apiJson("/entries/improve", {
      method: "POST",
      body: JSON.stringify({
        text: $("improve-original").textContent,
        mode: improveMode,
        custom_instruction: improveMode === "custom" ? improveCustomInstruction.trim() : undefined,
      }),
    });
    result.textContent = body.improved;
    status.textContent = "";
    $("improve-apply").disabled = false;
  } catch (error) {
    status.textContent = error.message;
    status.classList.add("error");
  }
}

function applyImprove() {
  if (improveTarget) {
    improveTarget.value = $("improve-result").textContent;
    improveTarget.dispatchEvent(new Event("input")); // refresh char count
  }
  closeImprove();
  toast("Applied the AI's suggestion.");
}

// --- Tensions: where the notebook disagrees with itself ---------------------
//
// Sibling of the auto-linker below, and deliberately next to it: both propose
// a connection and neither writes one without a click. The difference is what
// they can see. Similarity, every kind this app has, embeddings included , 
// answers "are these about the same thing", and two notes that flatly
// contradict each other are, to a vector, maximally similar. Only a model
// reading both can tell agreement from disagreement.
//
// `core/database.py`'s LINK_TYPES comment called `contradicts` "the one worth
// having built this for" and nothing ever produced one; `ai/tensions.py` is
// the half that does, and this is the review.

function tensionsDialog() {
  return document.getElementById("tensions-dialog");
}

function openTensions() {
  const dialog = tensionsDialog();
  if (!dialog) return;
  if (!dialog.open) dialog.showModal();
  // Deliberately does *not* auto-run. A pass reads pairs of notes with the
  // local model, free, but not instant, so starting one is a decision the
  // person makes, not something that happens because a dialog opened.
  const results = document.getElementById("tensions-results");
  if (results && !results.childElementCount) setTensionsStatus("");
}

function setTensionsStatus(text, busy = false) {
  const el = document.getElementById("tensions-status");
  if (!el) return;
  el.textContent = text;
  // `aria-live="polite"` is on the element itself, so a screen reader gets
  // the progress line without the focus being moved off the button that
  // started it.
  el.classList.toggle("is-busy", busy);
}

const TENSION_STATUS_TEXT = {
  no_model: "No local model is running, so nothing can read your notes. Start Ollama and try again.",
  no_embeddings:
    "Semantic search is off, so there is no shortlist of notes to compare. Turn it on in Settings → Models.",
  too_few_notes: "Not enough notes yet, there is nothing to compare.",
  no_candidates:
    "No pairs were close enough in subject to be worth reading. Contradictions only show up between notes about the same thing.",
  none_found: "Nothing contradicted itself. Your notebook is consistent, as far as this pass could tell.",
};

async function runTensionReview() {
  const button = document.getElementById("tensions-run");
  const results = document.getElementById("tensions-results");
  if (!results) return;
  if (button) button.disabled = true;
  results.replaceChildren();
  setTensionsStatus("Reading your notes… this runs on your machine and can take a minute.", true);

  const body = await apiJson("/entries/tensions", { silent: true }).catch(() => null);
  if (button) button.disabled = false;

  if (!body) {
    setTensionsStatus("The review could not run. Nothing was changed.");
    return;
  }
  const found = body.tensions || [];
  if (!found.length) {
    setTensionsStatus(TENSION_STATUS_TEXT[body.status] || "Nothing found.");
    return;
  }
  const checked = body.pairs_checked || 0;
  setTensionsStatus(
    `${found.length} to look at, from ${checked} pair${checked === 1 ? "" : "s"} read.`,
  );
  for (const tension of found) results.appendChild(tensionCard(tension));
}

/** One proposed disagreement, with both notes and the two decisions. */
function tensionCard(tension) {
  const card = document.createElement("div");
  card.className = "card tension-card";
  // A group with its own label, so a screen reader moving by landmark hears
  // what this block is about before its buttons.
  card.setAttribute("role", "group");
  card.setAttribute("aria-label", `Possible contradiction: ${tension.explanation}`);

  const why = document.createElement("p");
  why.className = "tension-why";
  why.textContent = tension.explanation;
  card.appendChild(why);

  const gap = document.createElement("p");
  gap.className = "muted tension-gap";
  // The gap is the finding as much as the text is, "you thought this, then
  // months later you thought that" is the story, and a bare pair of notes
  // does not tell it.
  gap.textContent = tension.gap_days
    ? `${tensionGapText(tension.gap_days)} apart`
    : "Written around the same time";
  card.appendChild(gap);

  const pair = document.createElement("div");
  pair.className = "tension-pair";
  pair.appendChild(tensionSide("Earlier", tension.earlier_at, tension.earlier_excerpt, tension.earlier_id));
  pair.appendChild(tensionSide("Later", tension.later_at, tension.later_excerpt, tension.later_id));
  card.appendChild(pair);

  const actions = document.createElement("div");
  actions.className = "row tension-actions";
  const accept = document.createElement("button");
  accept.type = "button";
  accept.className = "accent small";
  accept.textContent = "Yes: link these as contradicting";
  accept.addEventListener("click", async () => {
    await apiJson("/entries/tensions/accept", {
      method: "POST",
      body: JSON.stringify({ earlier_id: tension.earlier_id, later_id: tension.later_id }),
    }).catch(() => null);
    tensionResolve(card, "Linked as contradicting.");
  });
  const dismiss = document.createElement("button");
  dismiss.type = "button";
  dismiss.className = "ghost small";
  dismiss.textContent = "Not a contradiction";
  dismiss.addEventListener("click", async () => {
    await apiJson("/entries/tensions/dismiss", {
      method: "POST",
      body: JSON.stringify({ earlier_id: tension.earlier_id, later_id: tension.later_id }),
    }).catch(() => null);
    tensionResolve(card, "Dismissed: this pair won't come back.");
  });
  actions.append(accept, dismiss);
  card.appendChild(actions);
  return card;
}

/** Replace a card's controls with what happened, in place. */
function tensionResolve(card, message) {
  card.classList.add("is-resolved");
  const actions = card.querySelector(".tension-actions");
  if (!actions) return;
  const done = document.createElement("p");
  done.className = "muted tension-done";
  // `role="status"` so the outcome is announced: the button that was just
  // pressed is gone, and without this a screen-reader user gets silence.
  done.setAttribute("role", "status");
  done.textContent = message;
  actions.replaceWith(done);
}

function tensionGapText(days) {
  if (days < 31) return `${days} day${days === 1 ? "" : "s"}`;
  const months = Math.round(days / 30);
  if (months < 18) return `${months} month${months === 1 ? "" : "s"}`;
  const years = (days / 365).toFixed(1).replace(/\.0$/, "");
  return `${years} year${years === "1" ? "" : "s"}`;
}

function tensionSide(label, when, excerpt, entryId) {
  const side = document.createElement("div");
  side.className = "tension-side";
  const head = document.createElement("p");
  head.className = "tension-side-head";
  const tag = document.createElement("strong");
  tag.textContent = label;
  head.appendChild(tag);
  if (when) {
    const date = document.createElement("span");
    date.className = "muted tension-date";
    date.textContent = when;
    head.appendChild(date);
  }
  side.appendChild(head);
  const text = document.createElement("p");
  text.className = "tension-excerpt";
  text.textContent = excerpt || "(empty note)";
  side.appendChild(text);
  const open = document.createElement("button");
  open.type = "button";
  open.className = "ghost small";
  open.textContent = "Open this note";
  open.addEventListener("click", () => {
    tensionsDialog()?.close();
    flashEntry(entryId);
  });
  side.appendChild(open);
  return side;
}

// --- Wave N: AI link suggestions (auto-linker, approve each) -------------------------

async function loadLinkSuggestions() {
  const box = $("link-suggestions");
  box.classList.remove("hidden");
  box.textContent = "Looking for notes worth connecting…";
  const suggestions = await apiJson("/entries/link-suggestions").catch(() => []);
  box.replaceChildren();
  if (!suggestions.length) {
    box.textContent =
      "No new links to suggest, either everything related is already linked, or semantic search is off.";
    return;
  }
  // Was a bare space-between over three children, which put the backfill
  // button in the MIDDLE of the row between the sentence and the close
  // button: reported as "weirdly spaced". A heading and its actions is two
  // groups, not three peers: the sentence takes the slack, the buttons sit
  // together on the right.
  const heading = document.createElement("div");
  heading.className = "row link-suggest-head";

  const headingText = document.createElement("span");
  headingText.className = "muted link-suggest-title";
  headingText.textContent = "Notes that look related, link the ones you agree with:";

  const actions = document.createElement("div");
  actions.className = "row link-suggest-actions";

  // Asked directly: "none of my notes have a linked reason yet, is there an
  // easy way to give them all a reason?"
  //
  // It ran only the embedding pass, which can compare two vectors and has no
  // WORDS for what it found, so every reason it wrote was the literal string
  // "similar in meaning", the button looked like it worked and produced
  // reasons that said nothing. The endpoint runs the model over those
  // afterwards now, and this reports both numbers so it is obvious which
  // half did the work.
  //
  // **Not the same list as the rows below.** This explains links that
  // already exist elsewhere in the notebook; the rows here are proposed
  // links that don't exist yet. Reported as "doesn't work right" because
  // sitting directly above a list of unlinked suggestions, with nothing
  // distinguishing it, reads as if it should fill in *their* reason boxes, 
  // it can't, since a reason for a link that isn't made yet is exactly the
  // per-row box already offers (typed by hand, or left for the Link button's
  // own deduction). Labelled for what it actually touches instead.
  const backfill = smallButton(
    "ph:lightbulb Explain your existing links",
    "For links you've already made elsewhere: work out why each one exists, first from how alike the notes are, then by asking the AI to name the actual connection. Doesn't touch the suggestions below, which aren't links yet.",
    async () => {
      backfill.disabled = true;
      setLabel(backfill, "ph:lightbulb Working…");
      const result = await apiJson("/entries/links/backfill-reasons", {
        method: "POST",
        body: JSON.stringify({ ai: true }),
      }).catch((e) => {
        toast(e.message, true);
        return null;
      });
      backfill.disabled = false;
      setLabel(backfill, "ph:lightbulb Explain your existing links");
      if (!result) return;
      const parts = [];
      if (result.updated) parts.push(`marked ${result.updated}`);
      if (result.rewritten) parts.push(`wrote a real reason for ${result.rewritten}`);
      if (parts.length) {
        toast(`Links: ${parts.join(", ")}.`);
        loadLinkSuggestions();
      } else if (result.ai_unavailable) {
        toast("Marked what I could, the AI isn't running, so none could be put into words yet.", true);
      } else if (result.checked) {
        toast("Nothing left to explain, every link already has a reason.");
      } else {
        toast("Every link already has a reason.");
      }
    }
  );

  // Asked for directly, after the backfill button above was reported as
  // "doesn't fill in the empty Why boxes", correctly, because it never
  // could (it only ever touches links that already exist, see its own
  // comment). This is the actual thing that was missing: an AI guess for
  // *these* rows' own reason boxes, written in as a real value (not just a
  // placeholder) so it's visible, editable, and used as-is by Link if left
  // alone. `rowReasons` is populated by the suggestion loop below; the
  // click handler only runs once the user clicks, by which point it's full.
  const rowReasons = [];
  const suggestReasons = smallButton(
    "ph:sparkle Suggest reasons",
    "Ask the AI to guess why each note pair below might be connected, and fill in any empty Why box with its answer, still yours to edit or clear before linking.",
    async () => {
      const targets = rowReasons.filter((r) => !r.input.value.trim());
      if (!targets.length) {
        toast("Every visible suggestion already has a reason.");
        return;
      }
      suggestReasons.disabled = true;
      setLabel(suggestReasons, "ph:sparkle Working…");
      const result = await apiJson("/entries/link-suggestions/reasons", {
        method: "POST",
        body: JSON.stringify({
          pairs: targets.map((r) => ({ source_id: r.s.source_id, target_id: r.s.target_id })),
        }),
      }).catch((e) => {
        toast(e.message, true);
        return null;
      });
      suggestReasons.disabled = false;
      setLabel(suggestReasons, "ph:sparkle Suggest reasons");
      if (!result) return;
      const byPair = new Map(
        result.reasons.map((r) => [`${r.source_id}:${r.target_id}`, r.reason])
      );
      let filled = 0;
      for (const r of targets) {
        const reason = byPair.get(`${r.s.source_id}:${r.s.target_id}`);
        if (reason) {
          r.input.value = reason;
          filled++;
        }
      }
      if (filled) {
        toast(`Filled in ${filled} reason${filled === 1 ? "" : "s"}.`);
      } else if (result.ai_unavailable) {
        toast("The AI isn't running, so no reasons could be guessed.", true);
      } else {
        toast("Couldn't guess a reason for any of these.");
      }
    }
  );

  const closeAll = smallButton("ph:x", "Close suggestions", () => {
    box.classList.add("hidden");
    box.replaceChildren();
  });

  actions.append(backfill, suggestReasons, closeAll);

  // **Reasons arrive on their own now.** Asked for directly: "whenever a
  // link is suggested, the ai should suggest a reason that the user can
  // edit." The button above stays, it is how you retry after the model was
  // down, or refill a box you cleared, but a suggestion that needs a click
  // before it can say *why* is a suggestion most people will never see the
  // reason for.
  //
  // Fired after render rather than inside the endpoint: `/link-suggestions`
  // is a GET that already does one embedding scan, and putting a dozen
  // model round-trips behind it would turn opening this panel from instant
  // into a stall. This way the rows appear immediately with the deduced
  // text, and the AI's wording replaces it as each answer lands. Failure is
  // silent by design: the deduced reason is already showing as the box's
  // placeholder, and `create_link` deduces the same text server-side if the
  // box is left empty, so a failed guess costs nothing and there is nothing
  // to warn about.
  requestAnimationFrame(() => {
    // Only the top few automatically. Each pair is a model round-trip and
    // they run sequentially server-side, so filling all twelve unasked is a
    // long request on a slow local model for rows most people never scroll
    // to. The suggestions arrive best-first, so these are the ones worth
    // spending on; "Suggest reasons" still fills the rest on demand.
    const AUTO_REASON_LIMIT = 6;
    const pending = rowReasons
      .filter((r) => !r.input.dataset.userEdited)
      .slice(0, AUTO_REASON_LIMIT);
    if (!pending.length) return;
    apiJson("/entries/link-suggestions/reasons", {
      method: "POST",
      silent: true,
      body: JSON.stringify({
        pairs: pending.map((r) => ({ source_id: r.s.source_id, target_id: r.s.target_id })),
      }),
    })
      .then((result) => {
        const byPair = new Map(
          result.reasons.map((r) => [`${r.source_id}:${r.target_id}`, r.reason])
        );
        for (const r of pending) {
          // Never overwrite something typed while the request was in flight.
          if (r.input.dataset.userEdited) continue;
          const reason = byPair.get(`${r.s.source_id}:${r.s.target_id}`);
          if (reason) r.input.value = reason;
        }
      })
      .catch(() => {});
  });
  heading.append(headingText, actions);
  box.appendChild(heading);

  // Only this list scrolls when it's long: the heading above stays put.
  const rowsWrap = document.createElement("div");
  rowsWrap.className = "link-suggest-rows";
  box.appendChild(rowsWrap);

  for (const s of suggestions) {
    const row = document.createElement("div");
    row.className = "link-suggestion";
    const text = document.createElement("span");
    text.className = "link-suggestion-text";
    //: **The note's name, not its markdown.** Reported on 2026-09-09: this
    //: panel is "poorly designed and not consistent with the rest of the app
    //: ui style", with a screenshot whose rows read `"# Leafeon Pokemon image
    //: test ![WallpaperEngineOverride_ran..." ↔ "Some ideas for features I
    //: had: ![image.png](/media/8f5884..."`. That is not a styling problem:
    //: the server sends a raw slice of the note's content and this list
    //: printed it verbatim, so headings, image syntax and media paths landed
    //: in a sentence a person is meant to read. `notePreviewText` is what
    //: every other surface in this app already uses for exactly this, and it
    //: was the one caller that never did.
    const name = (raw) => {
      const clean = notePreviewText(raw || "").replace(/\s+/g, " ").trim();
      return clean.length > 70 ? `${clean.slice(0, 69)}…` : clean || "Untitled note";
    };
    const pair = `${name(s.source_preview)} ↔ ${name(s.target_preview)}`;
    text.append(document.createTextNode(pair));
    //: Truncating to one readable line means the whole of each name has to be
    //: reachable, and hover is what the rest of the app uses.
    text.title = `${notePreviewText(s.source_preview || "")}\n↔\n${notePreviewText(s.target_preview || "")}`;

    // **A reason you can type before you link.** Every suggestion offered
    // "similar in meaning" and there was no way to say anything else without
    // linking first, finding the link, and editing it, reported as the
    // suggestions refusing to offer reasons. Left blank, the server deduces
    // one exactly as before, so the fast path is unchanged.
    const reason = document.createElement("input");
    reason.type = "text";
    reason.className = "link-suggestion-reason";
    reason.maxLength = 80;
    reason.placeholder = s.reason && s.reason !== "similar in meaning"
      ? s.reason
      : "Why? (optional: the AI will work it out)";
    reason.setAttribute("aria-label", "Reason for this link");
    // Marks the box as the user's the moment they touch it, so the
    // auto-fill above can never overwrite what someone is typing.
    reason.addEventListener("input", () => {
      reason.dataset.userEdited = "1";
    });
    rowReasons.push({ s, input: reason });

    const score = chip(`${Math.round(s.similarity * 100)}%`, "confidence");
    const link = smallButton("ph:link Link", "Connect these two notes", async () => {
      const given = reason.value.trim();
      await apiJson(`/entries/${s.source_id}/links`, {
        method: "POST",
        // Only sent when the user typed one. Left out, the server runs the
        // same deduction it always did and returns a real confidence score,
        // rather than a hand-built duplicate of it.
        body: JSON.stringify(given ? { target_id: s.target_id, reason: given } : { target_id: s.target_id }),
      }).catch((e) => toast(e.message, true));
      row.remove();
      toast(given ? "Linked, with your reason." : "Linked.");
      loadEntries().catch(() => {});
      if (!box.querySelector(".link-suggestion")) {
        box.classList.add("hidden");
      }
    });
    // Enter in the reason box links, which is what you have just described.
    reason.addEventListener("keydown", (event) => {
      if (event.key === "Enter") {
        event.preventDefault();
        link.click();
      }
    });
    //: **A dismissal the notebook keeps.** This used to remove the row and
    //: nothing else, so the same pair was offered again on the next render,
    //: the next reload, and for ever: "a suggestion that comes back after
    //: being dismissed is the single most annoying thing a suggester can do",
    //: as `routes_entries.link_suggestions` puts it in the comment above the
    //: filter that was already waiting for this. The server has honoured
    //: `dismiss_link` corrections since Brief 23; the browser never sent one,
    //: which made the whole loop inert from the only end that can start it.
    //:
    //: The row goes whether or not the write lands: a dismissal that appears
    //: to do nothing because the notebook was busy is worse than one that is
    //: not remembered, and the pair comes back on the next render anyway if
    //: it was not.
    const dismiss = smallButton("ph:x", "Dismiss this suggestion", () => {
      row.remove();
      if (!box.querySelector(".link-suggestion")) {
        box.classList.add("hidden");
      }
      apiJson("/learned/corrections", {
        method: "POST",
        silent: true,
        body: JSON.stringify({
          kind: "dismiss_link",
          subject: { a: s.source_id, b: s.target_id },
        }),
      }).catch(() => {});
    });
    row.append(text, reason, score, link, dismiss);
    rowsWrap.appendChild(row);
  }
}

// Heuristic: does this Ollama model look like it can produce embeddings?
// Chat/generation models can't, Ollama answers /api/embed with 501, and
// picking one by mistake is the #1 way people break the search engine.
function looksLikeEmbeddingModel(name) {
  return /embed|minilm|bge|gte|e5|arctic/i.test(name || "");
}

async function applyEmbeddingBackend() {
  const backend = document.querySelector('input[name="emb-backend"]:checked')?.value;
  const model = $("embedding-model-select").value || null;
  if (!backend) return;
  // Guard the #1 misconfiguration: a chat model chosen as the search engine.
  if (backend === "ollama") {
    if (!model) {
      toast("Pick an embedding model first, e.g. nomic-embed-text.", true);
      return;
    }
    if (!looksLikeEmbeddingModel(model)) {
      const proceed = (await confirmDialog(
        `"${model}" doesn't look like an embedding model. Chat models can't create ` +
          "embeddings, so semantic search will fail (Ollama returns 501). Download and " +
          "pick a dedicated embedding model like nomic-embed-text instead.\n\nApply anyway?"
      ));
      if (!proceed) return;
    }
  }
  const ok = (await confirmDialog(
    `Switching the search engine re-indexes all ${allEntries.length} of your ` +
      "notes so search keeps making sense. Notes and keyword search stay " +
      "available while it runs. Continue?"
  ));
  if (!ok) {
    // Backing out puts the saved backend back on screen, rather than leaving
    // a radio selected for a switch that never happened.
    clearEmbeddingBackendLatch();
    refreshModelStatus();
    return;
  }
  try {
    await api("/models/embedding-backend", {
      method: "POST",
      body: JSON.stringify({ backend, model: backend === "ollama" ? model : null }),
    });
    clearEmbeddingBackendLatch(); // applied: polling may reflect it again
    refreshModelStatus();
  } catch (error) {
    toast(error.message, true);
  }
}

// Let the status poll own the radios again. Called once a choice is applied,
// and when the user backs out of applying it, otherwise a cancelled switch
// would leave the radio showing a backend that was never saved, which is the
// same lie in the opposite direction.
function clearEmbeddingBackendLatch() {
  delete $("embedding-model-select").dataset.userChosen;
  for (const radio of document.querySelectorAll('input[name="emb-backend"]')) {
    delete radio.dataset.userChosen;
  }
}

// --- keeping the look across restarts (§35E) --------------------------------
//
// Reported as two bugs: *"the theme resets to default on every start"* and
// *"onboarding shows every time"*. They are one bug. Both were stored in
// `localStorage` and nowhere else, and the desktop shell does not reliably
// persist it: pywebview is a different browser with its own profile, and if
// that profile is not stable across launches then everything kept there is
// something the app forgets. Two symptoms, one storage, exactly as §35E
// predicted.
//
// The fix is a mirror, not a move. localStorage stays the thing every
// `appearancePref` read goes through: it is synchronous, it works with the
// server unreachable, and moving the reads would mean rewriting the whole
// appearance system to be async. The server keeps a copy, seeded back into
// localStorage on load when the local one is empty, so a shell that loses it
// gets it back, and a browser that keeps it never notices.

//: The keys worth surviving a restart. Explicit rather than "everything in
//: localStorage": this is written to the notebook's own preferences file, and
//: scroll positions and one-visit UI state have no business in there.
// The appearance half is `LOOK_KEYS`, the same list a saved custom theme
// snapshots: rather than a second hand-written copy of it. The first draft
// *was* a hand-written copy, and it guessed two key names wrong ("bgart",
// "bgart-motion" for what are really `bgArt`, `bg-style`, `bg-motion` and
// `bg-intensity`), so the background art would have been the one setting that
// still did not survive a restart. Deriving it cannot be wrong.
// Everything not covered by the look: the tour flag, and the few view
// settings that are properties of how you use the app rather than of one
// visit.
const MIRRORED_UI_EXTRAS = [
  "themePreset",
  "motion",
  "custom-css",
  "onboardingDone",
  "activeTab",
  "graph-layout",
  "graph-colour",
  "graph-options-open",
  "graph-trace-open",
  "chat-composer-height",
  "wb-bg-color",
  "wb-panel-pos-board",
  "wb-panel-pos-library",
  "wb-panel-pos-tools",
  "wb-panel-pos-zoom",
];

// A function rather than a `const` array, because `LOOK_KEYS` is declared
// several hundred lines below this one and a top-level spread of it would be
// read before its initialiser had run, a temporal-dead-zone error at load,
// which in a file with no bundler means a blank app.
function mirroredUiKeys() {
  return [...LOOK_KEYS, ...MIRRORED_UI_EXTRAS];
}

let uiStateSaveTimer = null;

// Write the mirrored keys to the server, coalesced. Debounced because the
// appearance panel fires a change per slider tick, and a preferences write per
// tick would be a write per pixel of a corner-radius drag.
function saveUiState() {
  clearTimeout(uiStateSaveTimer);
  uiStateSaveTimer = setTimeout(() => {
    // Not before the unlock. The tab restore writes `activeTab` at module
    // level, which schedules a save that would land while the lock screen is
    // still up: a guaranteed 401 on every cold load, visible in the browser's
    // network log and in the server's, where it reads as an auth failure worth
    // investigating. §35E-bis found exactly this in the reminder poll; the
    // guard is the same one, for the same reason.
    if (!authToken()) return;
    const state = {};
    for (const key of mirroredUiKeys()) {
      const value = localStorage.getItem(key);
      if (value != null) state[key] = String(value).slice(0, 400);
    }
    // Silent and best-effort. This is a backup of something that already
    // worked locally; a toast about it would be noise about a copy.
    apiJson("/preferences", {
      method: "PUT",
      body: JSON.stringify({ ui_state: state }),
      silent: true,
    }).catch(() => {});
  }, 800);
}

// Mirror every write to a watched key, from one place.
//
// There are twenty-odd sites that write these, a theme toggle, eight
// appearance controls, the graph's pickers, onboarding. Adding a `saveUiState()`
// call to each would work today and rot the moment somebody adds the
// twenty-third and forgets: the setting would keep working in a browser and
// quietly stop surviving a desktop restart, which is a bug nobody would
// connect to the commit that caused it.
//
// So the *store* is watched instead of its callers. Adding a key to
// MIRRORED_UI_KEYS is then the whole of making a new setting persistent, which
// is the property worth having. Only the listed keys trigger a save; every
// other `localStorage` write in the app is untouched and unwatched.
function watchMirroredUiKeys() {
  const mirrored = new Set(mirroredUiKeys());
  const store = window.localStorage;
  const setItem = store.setItem.bind(store);
  const removeItem = store.removeItem.bind(store);
  // Own properties shadowing Storage.prototype, the storage itself is
  // untouched, so anything else reading it (including these two) is unaffected.
  store.setItem = (key, value) => {
    setItem(key, value);
    if (mirrored.has(String(key))) saveUiState();
  };
  store.removeItem = (key) => {
    removeItem(key);
    // A removal is a change too: clearing an explicit theme to fall back to
    // the system one has to survive a restart just as setting one does.
    if (mirrored.has(String(key))) saveUiState();
  };
}

// Seed localStorage from the server's copy, for keys the browser has lost.
// Called once, before the look is applied, so the app paints in the remembered
// theme rather than flashing the default and correcting itself.
//
// **Local wins.** If a key exists in both, the local one is newer by
// definition, it is what the person set in this browser, and overwriting it
// with a copy saved from another window would make two open windows fight.
function seedUiStateFromServer(state) {
  if (!state || typeof state !== "object") return false;
  let restored = 0;
  for (const key of mirroredUiKeys()) {
    if (localStorage.getItem(key) == null && state[key] != null) {
      localStorage.setItem(key, String(state[key]));
      restored += 1;
    }
  }
  return restored > 0;
}

// Which manual overrides are currently sitting on top of the theme. Shown in
// the UI so "why isn't the theme's colour showing?" has a visible answer.
const OVERRIDABLE_KEYS = [
  "theme", "palette", "accent", "accent-custom", "page-bg", "font", "fontsize",
  "density", "radius", "glass", "glass-blur", "glass-opacity", "glass-sheen",
  "glass-sheen-strength", "bg-style", "bg-motion", "bg-intensity", "zoom",
];

// LOOK_KEYS stays here, not in settings.js with the rest of "your own saved
// themes" (§88.3 item 4): mirroredUiKeys() above spreads it into its own
// list from a bare top-level call in this file's own wiring
// (`watchMirroredUiKeys();`), which runs before settings.js has loaded, so
// it has to already exist here. OVERRIDABLE_KEYS above is kept for the same
// reason (LOOK_KEYS is built from it). settings.js's saveCurrentLook() and
// friends read both across the file boundary, which is safe: they only ever
// run from a user's own click, long after every script has loaded.
const LOOK_KEYS = [...OVERRIDABLE_KEYS, "bgArt"];

function applyPalette(id, remember = true) {
  const root = document.documentElement;
  // "default" means "no palette overrides", leave the attribute off rather
  // than shipping a block that restates the base :root values.
  if (id && id !== "default") root.dataset.palette = id;
  else delete root.dataset.palette;
  if (remember) localStorage.setItem("palette", id || "default");
  // The generative background paints from the accent, so it has to be rebuilt, 
  // and so does the dashboard constellation, for the same reason.
  if (bgArtOn()) startBgArt();
  // Guarded since the dashboard.js split (roadmap §88.3 item 3): originally
  // because applyPalette() was reachable from a bare top-level call in THIS
  // file's own wiring (`applyAppearance()` -> `applyPalette()`, painting the
  // saved appearance before first render) while dashboard.js, which owns
  // `refreshArtForTheme`, hadn't loaded yet. An unguarded call threw
  // `ReferenceError: refreshArtForTheme is not defined` from inside that
  // exact chain and aborted the rest of app.js's synchronous top-level code
  // (same shape as the `initDocSidebarTabs()` hazard documents.js's split
  // found). The settings.js split (item 4) moved that bare call itself, 
  // `applyAppearance()` now runs from settings.js's own tail, after
  // dashboard.js has already loaded, so this guard now always passes at
  // that call site too. Left in place rather than removed: applyPalette()
  // stays a plain global function, callable from anywhere, and nothing
  // guarantees a *future* caller runs this late, the guard is what makes
  // that safe by construction instead of by "nothing calls it early right
  // now." Still a genuine no-op either way at today's one early call site:
  // the dashboard's art widget hasn't mounted a canvas yet at startup
  // (`artHolder` is still null), so `refreshArtForTheme()` returns
  // immediately regardless of whether the guard lets it run. Every other
  // call site (the theme toggle, the accent/theme pickers, the OS
  // dark-mode listener) fires only from user interaction, well after every
  // script has loaded.
  if (typeof refreshArtForTheme === "function") refreshArtForTheme();
}

// --- Wave O: the p5 brand emblem (unique each load, reused app-wide) ----------

// A tiny generative emblem next to the title: a ring of linked nodes (the
// MemoryMap motif), coloured in the accent, seeded randomly each visit so
// it's one-of-a-kind, with a slow rotation.
// One identity per visit: every emblem in the app draws from the same seed, so
// the logo in the top bar, on the lock screen and in the empty states is
// recognisably the *same* mark rather than five unrelated doodles.
const emblemSeed = Math.floor(Math.random() * 1e6);
const emblemInstances = new Map(); // element -> p5 instance
const emblemObservers = new Map(); // element -> IntersectionObserver

//: **A mark nobody can see does not need to be drawn.** Six emblems are built
//: at boot (`EMBLEM_SLOTS`) and five of them live inside a panel that is
//: `display: none` almost all the time: the lock screen, the onboarding card,
//: the chat and graph empty states, the About dialog. Each one is a p5
//: instance with its own 24fps draw loop, and p5 keeps that loop running
//: whether or not its canvas has a box: measured on an idle whiteboard, six
//: canvases alive, one visible, and 5.0 `requestAnimationFrame` requests per
//: displayed frame.
//:
//: This is the same shape as the hidden tab that kept two clocks ticking, and
//: it is *not* a retreat from "whenever the generated p5.js node graph logo
//: shows, make sure it is never static and always rotating": the loop is
//: stopped only while the mark is not shown, and started again the moment it
//: is. An `IntersectionObserver` is the right instrument because a
//: `display: none` element never intersects anything, so "is this on screen"
//: needs no polling and no per-panel wiring.
//:
//: Not a claim about the whiteboard's drag lag. That report is still
//: unattributed (`agent-remaining/mindmap.md`); this is work the app was
//: doing for nothing, found while profiling it.
function watchEmblemVisibility(holder, instance) {
  if (typeof IntersectionObserver === "undefined") return;
  emblemObservers.get(holder)?.disconnect();
  const observer = new IntersectionObserver((entries) => {
    for (const entry of entries) {
      if (entry.isIntersecting) instance.loop();
      else instance.noLoop();
    }
  });
  observer.observe(holder);
  emblemObservers.set(holder, observer);
}

// The shared emblem sketch: a small ring of linked nodes, the MemoryMap motif
//, in the current accent. Animated only where it's worth the frames.
function renderEmblem(holder, size = 34, { animate = false } = {}) {
  if (typeof p5 === "undefined" || !holder) return;
  const existing = emblemInstances.get(holder);
  if (existing) {
    existing.remove();
    emblemInstances.delete(holder);
    // The observer holds the instance it was told to pause, so it has to go
    // with it: left behind, it would call `loop()` on a removed sketch the
    // next time its holder came into view.
    emblemObservers.get(holder)?.disconnect();
    emblemObservers.delete(holder);
  }
  const accentHex =
    localStorage.getItem("accent-custom") ||
    (ACCENTS.find((a) => a.name === activeAccent()) || ACCENTS[0]).swatch;
  // The emblem spins unless the user has explicitly asked for a still UI in
  // Settings → Appearance. We deliberately don't freeze it on the OS-level
  // prefers-reduced-motion hint alone: this mark has always turned, the app
  // ships its own motion switch, and that switch is the one to obey.
  const still = appearancePref("motion") === "reduced";

  const sketch = (p) => {
    let nodes = [];
    let baseHue = 230;
    p.setup = () => {
      p.createCanvas(size, size);
      p.colorMode(p.HSL, 360, 100, 100, 1);
      p.randomSeed(emblemSeed);
      baseHue = p.hue(p.color(accentHex));
      const count = 4 + Math.floor(p.random(3)); // 4-6 nodes
      nodes = Array.from({ length: count }, (_, i) => ({
        angle: (i / count) * p.TWO_PI + p.random(-0.3, 0.3),
        hue: (baseHue + p.random(-40, 40) + 360) % 360,
      }));
      if (animate && !still) p.frameRate(24);
      else {
        p.draw();
        p.noLoop(); // a single crisp frame where motion adds nothing
      }
    };
    p.draw = () => {
      p.clear();
      p.translate(size / 2, size / 2);
      if (animate && !still) p.rotate(p.frameCount * 0.006);
      const r = size * 0.32;
      const dot = Math.max(4, size * 0.18);
      p.stroke(baseHue, 60, 60, 0.6);
      p.strokeWeight(Math.max(1, size / 34));
      for (let i = 0; i < nodes.length; i++) {
        for (let j = i + 1; j < nodes.length; j++) {
          p.line(
            Math.cos(nodes[i].angle) * r,
            Math.sin(nodes[i].angle) * r,
            Math.cos(nodes[j].angle) * r,
            Math.sin(nodes[j].angle) * r
          );
        }
      }
      p.noStroke();
      for (const n of nodes) {
        p.fill(n.hue, 75, 60, 1);
        p.circle(Math.cos(n.angle) * r, Math.sin(n.angle) * r, dot);
      }
      p.fill(baseHue, 70, 62, 1);
      p.circle(0, 0, dot * 0.85); // a bright hub
    };
  };
  const instance = new p5(sketch, holder);
  emblemInstances.set(holder, instance);
  // Only the animated ones: the still ones called `noLoop()` in their own
  // setup and have no loop to pause.
  if (animate && !still) watchEmblemVisibility(holder, instance);
}

// Every emblem currently on the page, keyed by element id and size.
// Every slot animates: direct instruction, after the onboarding and About
// emblems were caught sitting still: "whenever the generated p5.js node
// graph logo shows, make sure it is never static and always rotating."
// `renderEmblem` already respects Settings → Appearance's motion switch
// (and only that switch, not the OS-level prefers-reduced-motion hint, 
// see its own comment), so `animate: true` here doesn't reintroduce motion
// for anyone who asked this app to hold still; it only removes the extra,
// per-slot "hold this one still anyway" that had nothing to do with that
// preference.
const EMBLEM_SLOTS = [
  // Not the top bar any more: that is the favicon now, so the app's icon in
  // the tab strip and the mark above it are the same thing. The generated
  // emblem is the dashboard's hero, and a small animated marker on the tabs
  // where the AI is doing something, asked for as "kinda like an ai symbol".
  ["ai-mark", 24, true],
  ["lock-emblem", 76, true],
  ["onboarding-emblem", 64, true],
  ["chat-empty-emblem", 52, true],
  ["graph-empty-emblem", 52, true],
  ["about-emblem", 44, true],
];

function renderBrandLogo() {
  for (const [id, size, animate] of EMBLEM_SLOTS) {
    const holder = document.getElementById(id);
    if (holder) renderEmblem(holder, size, { animate });
  }
}

// --- wiring --------------------------------------------------------------------

$("account-change").addEventListener("click", changePassword);
$("account-idle-ttl").addEventListener("change", (e) => {
  setPreference("session_idle_ttl_minutes", Number(e.target.value));
});
$("account-lock-all").addEventListener("click", async () => {
  if (!(await confirmDialog("End every session, including this one? You'll need your password to get back in."))) return;
  await apiJson("/auth/lock-all", { method: "POST" }).catch(() => {});
  localStorage.removeItem("token");
  location.reload();
});
// Enter anywhere in the change-password form submits it.
for (const id of ["account-current", "account-new", "account-confirm"]) {
  $(id).addEventListener("keydown", (e) => {
    if (e.key === "Enter") changePassword();
  });
}

// --- the notifications centre's controls (§36E) -----------------------------
$("notif-btn").addEventListener("click", () => {
  const open = $("notif-panel").classList.contains("hidden");
  $("notif-btn").setAttribute("aria-expanded", String(open));
  if (open) openNotifications();
  else closeNotifications();
});
$("notif-close").addEventListener("click", () => {
  closeNotifications();
  $("notif-btn").setAttribute("aria-expanded", "false");
});
$("notif-clear").addEventListener("click", () => {
  localStorage.removeItem(NOTIFICATIONS_KEY);
  localStorage.setItem(NOTIFICATIONS_READ_KEY, String(Date.now()));
  openNotifications(); // redraw in place: the panel stays open, now empty
});
// Asked for directly: the mute toggle reachable from the panel it affects,
// not only three screens away in Settings, and the bell itself says
// whether it's on, so muting isn't a setting you have to remember you set.
$("notif-mute-toggle").addEventListener("click", () => {
  toggleNotificationMute().catch((e) => toast(e.message, true));
});
// Click-away and Escape, the same two gestures every other popup here honours.
document.addEventListener("click", (event) => {
  const panel = $("notif-panel");
  if (panel.classList.contains("hidden")) return;
  //: **A menu this panel owns counts as inside it.** INBOX 70: "the 'AI
  //: activity' combobox doesn't open, and the feature doesn't work". It
  //: opened: `enhanceSelect` replaces the `<select>` with an
  //: `.action-menu.select-menu`, which is reparented to `<body>` while open,
  //: so a click on one of its options is not a descendant of `.notif-wrap`,
  //: this guard read it as a click away, and the panel closed under the menu
  //: before the option's own handler could run. The choice never landed, and
  //: the control read as dead.
  //:
  //: `.action-menu` rather than `.select-menu` alone: every escaped menu in
  //: this app carries it, so a panel that grows a second kind of menu later
  //: does not have to rediscover this.
  if (event.target.closest(".notif-wrap, .action-menu")) return;
  closeNotifications();
  $("notif-btn").setAttribute("aria-expanded", "false");
});
renderNotificationBadge();

// Watch the settings worth surviving a restart *before* anything can write
// one (§35E). Installed here rather than inside startApp because the tab
// restore below writes `activeTab`, and a write that happens before the watch
// is a write the server never hears about.
watchMirroredUiKeys();

// applyAppearance()/startBgArt() moved to settings.js's own tail (§88.3 item
// 4): both are defined there now, and calling them from a bare line here, 
// before settings.js has loaded, threw ReferenceError. See settings.js's
// own file header for the full hazard and why running them slightly later
// (after every split file has loaded, still well before first paint) changes
// nothing visible. watchMirroredUiKeys() above still runs from here.

// Tabs (Wave A): switch pages, restore the last one used.
for (const button of document.querySelectorAll("#tab-bar button")) {
  button.addEventListener("click", () => switchTab(button.dataset.tab));
}
// Arrow keys walk the tablist; Home/End jump to the ends (Wave L).
//
// Read from the bar itself rather than from TABS. Since the Library absorbed
// the Documents tab (§36F) the two lists are no longer the same: `documents`
// is still a page you can switch to, it is the editor the Library opens, but
// it has no button, so walking TABS would land on a tab that does not exist
// and `.focus()` on the null it returned would throw on an arrow key.
$("tab-bar").addEventListener("keydown", (e) => {
  const keys = { ArrowRight: 1, ArrowLeft: -1, Home: 0, End: 0 };
  // Alt+arrow is the app-wide Back/Forward shortcut. Without this check,
  // a bare arrow here always won, a tab button is exactly where focus
  // sits right after clicking a tab, so this ARIA-tablist roving-focus
  // handler (an ancestor of the focused button, so it sees the keydown
  // before the document-level shortcut listener does) hijacked Alt+Left/
  // Right into "move to the adjacent tab button" every time, with its own
  // preventDefault() leaving nothing clean for the real shortcut to act
  // on. Bare Left/Right/Home/End still cycle tabs exactly as before.
  if (!(e.key in keys) || e.altKey) return;
  e.preventDefault();
  const buttons = [...document.querySelectorAll("#tab-bar button")];
  if (!buttons.length) return;
  const names = buttons.map((b) => b.dataset.tab);
  const index = Math.max(0, names.indexOf(localStorage.getItem("activeTab") || "notes"));
  let next;
  if (e.key === "Home") next = 0;
  else if (e.key === "End") next = names.length - 1;
  else next = (index + keys[e.key] + names.length) % names.length;
  switchTab(names[next]);
  buttons[next].focus();
});
// Every other tablist gets the same keys. Reported directly: "I cant
// navigate things like subtabs with arrow keys." Only the top bar and the
// Notes strip had roving focus; the Library strip, the document sidebar
// tabs, the note picker's sources and every strip added since were mouse
// only, which is exactly the kind of small thing that makes an app feel
// unfinished. One document-level handler covers all of them and any strip
// added later, so long as it is marked role="tablist" with role="tab"
// children. Strips with their own handler call preventDefault first and are
// left alone; a click() on the target tab reuses each strip's own click
// wiring rather than duplicating its section logic here.
document.addEventListener("keydown", (e) => {
  if (e.defaultPrevented || e.altKey || e.ctrlKey || e.metaKey) return;
  const keys = { ArrowRight: 1, ArrowLeft: -1, Home: 0, End: 0 };
  if (!(e.key in keys)) return;
  const tab = e.target.closest?.('[role="tab"]');
  const list = tab?.closest('[role="tablist"]');
  if (!tab || !list || list.id === "tab-bar") return;
  const tabs = [...list.querySelectorAll('[role="tab"]')].filter(
    (t) => !t.disabled && !t.hidden && t.offsetParent !== null
  );
  if (tabs.length < 2) return;
  e.preventDefault();
  const index = tabs.indexOf(tab);
  let next;
  if (e.key === "Home") next = 0;
  else if (e.key === "End") next = tabs.length - 1;
  else next = (index + keys[e.key] + tabs.length) % tabs.length;
  const target = tabs[next];
  target.click();
  target.focus();
});
// Skip link (Wave L): jump keyboard focus straight into the open panel.
$("skip-link").addEventListener("click", (e) => {
  e.preventDefault();
  $(`tab-${localStorage.getItem("activeTab") || "notes"}`).focus();
});
initNotesSubtabs();
initSelectionPopup();
initEntryListKeyboardNav();
scrollTopUpdate = initScrollTopButton();
// Reminder watching moved into startApp() (below `_active_tokens` note in
// api()'s own comment): this used to run unconditionally here, before
// initAuth() has resolved whether a token even exists. A cold load: 
// lock screen up, nothing unlocked yet, fired /reminders anyway, one 401
// with an empty X-Auth-Token header, joining the exact same pile as the
// dashboard's below. See revealTab("dashboard")'s comment for the full
// picture; both were part of one bug.
initResizableSidebars();

// --- the top bar's real height, as a token ------------------------------------
// UI_MODERNISATION_PLAN.md Phase 9.
//
// `--header-h` is a constant in the stylesheet: `calc(3.7rem + 1px)`, with a
// second value of 7.5rem below the phone breakpoint. Two things read it, and
// both were wrong at ordinary widths. `--page-viewport` is how tall a sticky
// sidebar may be, and the sheet added in band 3 is positioned from the top of
// the header downward.
//
// The bar's height is not a constant. `syncTabOverflowFade` gives the tab
// strip a row of its own (`.tabs-wrapped`) whenever the seven tabs cannot fit
// beside the wordmark and the buttons, which depends on the space switcher's
// current text as much as on the window. Measured at 768: the token said
// 60.2px and the bar was 120px, so the sidebar sheet started 60px too high
// and ran under the header, and every sticky sidebar in the app was told it
// had 60px more room than it has.
//
// A ResizeObserver writes the measured height back into the same token, so
// everything that already reads it gets the truth with no new property to
// learn. Through the CSSOM rather than a style attribute, which this app's
// own CSP refuses. No feedback loop: the bar's height comes from its content,
// and nothing in it is sized from this token.
function initHeaderHeightToken() {
  const bar = document.getElementById("top-bar");
  if (!bar || typeof ResizeObserver === "undefined") return;
  const write = () => {
    const h = Math.round(bar.getBoundingClientRect().height);
    // Zero while the bar is display:none (the lock screen) would collapse
    // every sticky sidebar to the full window height and hand the sheet a
    // top of 0. Leave the stylesheet's value standing until there is a real
    // one to replace it with.
    if (h > 0) document.documentElement.style.setProperty("--header-h", `${h}px`);
  };
  new ResizeObserver(write).observe(bar);
  write();
}

initHeaderHeightToken();

// --- the tab bar docks to the bottom on a phone -------------------------------
// UI_MODERNISATION_PLAN.md Phase 9, band 4.
//
// The stylesheet does the whole of the bottom bar's appearance. This function
// exists for one reason, and it is a reason that cost a measurement to find:
// **`position: fixed` does not reach the viewport from inside the header.**
// `header#top-bar` carries `backdrop-filter`, and a filtered element becomes
// the containing block for every fixed descendant, so the bar pinned itself
// to the bottom of the *header* instead. Measured at 390: `position: fixed`,
// `bottom: 0` applied, and the bar sitting at y=51 on an 844px screen.
//
// So the node moves. Out of the header and onto the body while the phone band
// holds, and back into the header on the way out, in its original place. The
// same element throughout, so every listener, the roving tabindex and the ids
// survive; this is the move `foldDockArrange` makes for the same reason.
//
// `.tabs-wrapped` comes off with it. `syncTabOverflowFade` gives the strip a
// row of its own inside the header when the seven tabs will not fit beside
// the wordmark, and with the strip no longer in the header that class was
// still on, holding the top bar at two rows: 110px at 390 against 58px at
// 599, for a header with identical contents.
const PHONE_TABS = "(max-width: 599.98px)";

function dockTabBar(toBottom) {
  const bar = document.getElementById("tab-bar");
  const header = document.getElementById("top-bar");
  if (!bar || !header) return;
  if (toBottom) {
    if (bar.parentElement === document.body) return;
    // Where to put it back. The header's children are fixed markup, so the
    // next sibling is a stable anchor.
    bar.dataset.homeNext = bar.nextElementSibling?.className || "";
    header.classList.remove("tabs-wrapped");
    document.body.appendChild(bar);
  } else {
    if (bar.parentElement === header) return;
    const anchor = bar.dataset.homeNext
      ? header.querySelector(`:scope > .${CSS.escape(bar.dataset.homeNext.split(" ")[0])}`)
      : null;
    if (anchor) header.insertBefore(bar, anchor);
    else header.appendChild(bar);
    delete bar.dataset.homeNext;
  }
  // The fade is about a strip that scrolls inside the header; recompute it
  // for wherever the strip now lives.
  if (typeof syncTabOverflowFade === "function") syncTabOverflowFade();
}

function initBottomTabBar() {
  const query = window.matchMedia(PHONE_TABS);
  dockTabBar(query.matches);
  query.addEventListener("change", (event) => dockTabBar(event.matches));
}

initBottomTabBar();

// --- how much of the window the on-screen keyboard is covering ----------------
// UI_MODERNISATION_PLAN.md Phase 9, band 4.
//
// The two strips you type at, the chat composer and the documents formatting
// bar, sit at the bottom of their card. On a phone the on-screen keyboard
// comes up over the bottom of the window and takes both with it, so the
// buttons that act on what you are typing are under the keys you are typing
// with.
//
// `window.innerHeight` does not change when a keyboard opens; the *visual*
// viewport does. The difference between the two is the covered strip, and
// writing it into `--keyboard-inset` lets the stylesheet handle the rest:
// both docks already add the token to their bottom padding (07-whiteboard-
// misc.css), so nothing here needs to know which elements exist.
//
// Through the CSSOM, because this app's own CSP refuses a style attribute,
// and rounded because a fractional value here becomes a fractional padding
// on every keystroke of a resize.
//
// **Not verifiable in this sandbox.** Chromium headless has no on-screen
// keyboard, so what is tested here is that the property is written, that it
// is 0 with no keyboard, and that the two docks read it. The behaviour with
// a real keyboard on a real phone is reasoned, not observed.
function initKeyboardInset() {
  const viewport = window.visualViewport;
  if (!viewport) return;
  const write = () => {
    const covered = window.innerHeight - viewport.height - viewport.offsetTop;
    // Clamped at zero: `offsetTop` is negative while a page is rubber-banding
    // on iOS, which would otherwise write a negative padding.
    document.documentElement.style.setProperty(
      "--keyboard-inset",
      `${Math.max(0, Math.round(covered))}px`
    );
  };
  viewport.addEventListener("resize", write);
  viewport.addEventListener("scroll", write);
  write();
}

initKeyboardInset();

// --- the settings section jump list -------------------------------------------
// UI_MODERNISATION_PLAN.md Phase 9, band 4.
//
// **This one already existed, and that was not the same as it being good
// enough.** Below 640 the Settings dialog already collapses to a single
// column with the seventeen sections laid out as a strip that scrolls
// sideways, and the comment on that rule explains why a vertical list was
// worse: stacked, the nav's natural height is about 700px and the content
// pane was left twenty pixels tall.
//
// The strip fixed that and left its own problem, which is only visible if you
// measure it: at 390 the strip needs **2337px of scroll inside 308px**. Seven
// and a half screen widths of chips, with the group headings hidden because
// they do not work horizontally, to reach "About". Every section is reachable
// and none of them is findable.
//
// A native `<select>` with an `<optgroup>` per heading is the whole answer on
// a phone: it opens the platform's own picker, shows all seventeen at once
// under the three headings the desktop nav uses, is keyboard and screen
// reader accessible for free, and adds no custom popup to a dialog that is
// already a popup. It is built from the nav rather than declared beside it,
// so a section added to the markup appears here with nothing to remember.
function buildSettingsJumpList() {
  const nav = document.getElementById("settings-nav");
  if (!nav || document.getElementById("settings-jump")) return;

  const select = document.createElement("select");
  select.id = "settings-jump";
  select.className = "settings-jump";
  select.setAttribute("aria-label", "Jump to a settings section");
  // A native select, not the enhanced stand-in. The stand-in mirrors a
  // select that CSS hides above 640px, so it drew a "Models" combobox on a
  // desktop Settings page and, opened, covered the pane (reported with a
  // screenshot: "the settings page went blank"). On a phone the native
  // picker is the better control anyway. Same opt-out #timeline-view uses.
  select.setAttribute("data-no-select-enhance", "");

  for (const group of nav.querySelectorAll(":scope > div[role='group']")) {
    const heading = document.getElementById(group.getAttribute("aria-labelledby"));
    const optgroup = document.createElement("optgroup");
    optgroup.label = heading ? heading.textContent.trim() : "Sections";
    for (const button of group.querySelectorAll("button[data-section]")) {
      const option = document.createElement("option");
      option.value = button.dataset.section;
      option.textContent = button.textContent.trim();
      if (button.classList.contains("active")) option.selected = true;
      optgroup.appendChild(option);
    }
    if (optgroup.children.length) select.appendChild(optgroup);
  }
  if (!select.children.length) return;

  // The select drives the real buttons rather than duplicating what they do.
  // Every handler, every side effect and the section history stay in one
  // place, and a hidden button still answers `.click()`.
  select.addEventListener("change", () => {
    nav.querySelector(`button[data-section="${CSS.escape(select.value)}"]`)?.click();
  });

  // And follows them: the section can also change from a search result, from
  // a deep link, or from the dialog's own back and forward pair.
  new MutationObserver(() => {
    const active = nav.querySelector("button[data-section].active");
    if (active && select.value !== active.dataset.section) {
      select.value = active.dataset.section;
    }
  }).observe(nav, { subtree: true, attributes: true, attributeFilter: ["class"] });

  // After the search field, which stays: searching the sections' contents and
  // jumping to one by name are different questions (the search field's own
  // comment makes that case).
  const search = document.getElementById("settings-search");
  const count = document.getElementById("settings-search-count");
  (count || search || nav.firstElementChild)?.after(select);
}

buildSettingsJumpList();

// --- the floating primary action ----------------------------------------------
// UI_MODERNISATION_PLAN.md Phase 9, band 4.
//
// Three docks have a single filled action and the phone band floats it
// bottom-right, in the thumb's arc above the tab bar. The stylesheet does the
// whole appearance; this exists for the same reason `dockTabBar` does, and it
// was found the same way.
//
// **`position: fixed` does not reach the viewport from inside a card.** Every
// `.card` in this app carries `backdrop-filter` (that is what makes it glass),
// and a filtered element is the containing block for its fixed descendants. So
// the button pinned itself to the bottom right of the *card* it lives in,
// which on Library is the card holding the dock, at the top of the page.
// `touch.js` caught it as two controls that cannot be tapped: `#library-refresh`
// and the dock's overflow menu, both covered by "New document" sitting on top
// of them at y=201.
//
// The button moves to its own `.tab-page`, which has no filter and is a direct
// child of the body, so `fixed` means the window again. That element is also
// the one that gets hidden when its tab is not showing, which is what keeps a
// floating action from appearing over a tab it has nothing to do with; parking
// it on the body would have needed a second mechanism to answer that.
const PHONE_FAB = "(max-width: 599.98px)";
const FAB_IDS = ["graph-add-node", "library-new-doc", "timeline-jump-today"];

function floatPrimaryActions(floating) {
  for (const id of FAB_IDS) {
    const button = document.getElementById(id);
    if (!button) continue;
    const page = button.closest(".tab-page");
    if (!page) continue;
    if (floating) {
      if (button.parentElement === page) continue;
      // A marker in its place, so it goes back where it was rather than at
      // the end of whatever zone it belonged to.
      const slot = document.createElement("span");
      slot.className = "dock-fab-slot";
      slot.dataset.fabFor = id;
      slot.hidden = true;
      button.replaceWith(slot);
      button.classList.add("dock-fab");
      page.appendChild(button);
    } else {
      if (button.parentElement !== page) continue;
      const slot = page.querySelector(`.dock-fab-slot[data-fab-for="${CSS.escape(id)}"]`);
      button.classList.remove("dock-fab");
      if (slot) slot.replaceWith(button);
    }
  }
}

function initPrimaryFab() {
  const query = window.matchMedia(PHONE_FAB);
  floatPrimaryActions(query.matches);
  query.addEventListener("change", (event) => floatPrimaryActions(event.matches));
}

initPrimaryFab();

// --- the dock's arrange zone folds into its own overflow menu ------------------
// UI_MODERNISATION_PLAN.md Phase 9, bands 2 and 3.
//
// Measured with `scratchpad/ui-sweeps/` at four widths, before this existed:
// the Notes and Graph docks are 36px at 1440 and **80px at 1024 and 820** and
// 172px at 390. They wrap. That is the whole of the owner's complaint about
// this app having no responsive design: nothing was designed for a tablet,
// the row simply ran out of width and folded onto a second and a fourth line
// until the chrome ate the page.
//
// The grammar Phase 8 settled already says what to drop first. Identity,
// search and the one primary action are what a narrow surface must keep;
// order and view are settings you change occasionally, and the dock already
// owns a place for a control used occasionally, its `...` menu. So below
// 1100 the `.dock-arrange` zone moves into that menu, and above 1100 it moves
// back out.
//
// **Moved, not cloned, and never hidden.** Two rules this phase is explicitly
// held to, and both have bitten this codebase before. Cloning a control
// leaves two elements with the same id and one of them wired to nothing
// (`initNotesFiltersSheet` carries the same note). And `display: none` on a
// sort select is a control that no longer exists on a tablet, which is not a
// responsive design, it is a smaller app. Moving the same nodes keeps every
// listener, every id and every enhanced `<select>` shell intact, and the
// controls stay one tap away behind a button that is always in the row.
const DOCK_FOLD_BELOW = "(max-width: 1099.98px)";

// Where the zone came back to. A comment node would be tidier, but a marker
// element can be found again after any re-render of the dock around it.
function dockArrangeSlot(dock) {
  let slot = dock.querySelector(":scope > .dock-arrange-slot");
  if (!slot) {
    slot = document.createElement("span");
    slot.className = "dock-arrange-slot";
    slot.hidden = true;
  }
  return slot;
}

// The zone label, created once per menu and removed when the zone leaves.
function dockArrangeLabel(menu) {
  let label = menu.querySelector(":scope > .dock-arrange-label");
  if (!label) {
    label = document.createElement("span");
    label.className = "muted dock-menu-label dock-arrange-label";
    label.textContent = "Sort and view";
    menu.prepend(label);
  }
  return label;
}

// The whole `.dock-arrange` element, in and out of a menu that sits outside it.
function foldZoneIntoMenu(dock, menu, fold) {
  const inRow = dock.querySelector(":scope > .dock-arrange");
  const inMenu = menu.querySelector(":scope > .dock-arrange");
  if (fold && inRow) {
    inRow.replaceWith(dockArrangeSlot(dock));
    inRow.classList.add("dock-arrange-folded");
    dockArrangeLabel(menu).after(inRow);
  } else if (!fold && inMenu) {
    inMenu.classList.remove("dock-arrange-folded");
    const slot = dock.querySelector(":scope > .dock-arrange-slot");
    if (slot) slot.replaceWith(inMenu);
    else dock.querySelector(":scope > .dock-find")?.after(inMenu);
    menu.querySelector(":scope > .dock-arrange-label")?.remove();
  }
}

// The arrange zone's other children, in and out of a menu that is one of them.
// `data-folded-from` records where each came back to, because unlike the zone
// above these are several elements and they must return in order.
function foldSiblingsIntoMenu(dock, menu, fold) {
  const zone = dock.querySelector(":scope > .dock-arrange");
  if (!zone) return;
  const holder = menu.closest(".dock-menu");
  if (fold) {
    const moving = [...zone.children].filter(
      (child) => child !== holder && !child.classList.contains("dock-native-hidden")
    );
    if (!moving.length) return;
    const label = dockArrangeLabel(menu);
    let after = label;
    for (const child of moving) {
      child.dataset.foldedFrom = dock.dataset.dockName;
      child.classList.add("dock-folded-control");
      after.after(child);
      after = child;
    }
  } else {
    const returning = [...menu.querySelectorAll(":scope > [data-folded-from]")];
    for (const child of returning) {
      delete child.dataset.foldedFrom;
      child.classList.remove("dock-folded-control");
      zone.prepend(child);
    }
    if (returning.length) menu.querySelector(":scope > .dock-arrange-label")?.remove();
  }
}

function foldDockArrange(fold) {
  for (const dock of document.querySelectorAll(".dock[data-dock-name]")) {
    const menu = dock.querySelector(":scope > .dock-actions > .dock-more > .dock-menu-list");
    if (menu) {
      foldZoneIntoMenu(dock, menu, fold);
      continue;
    }
    // A dock whose only overflow menu lives *inside* the arrange zone cannot
    // fold the zone into it, because the zone contains the destination. The
    // Timeline is the one: Phase 8 gave it an `Options` menu in the arrange
    // group and no `...` in the actions group. Folding its siblings into that
    // menu is the same move by the same rule, and it leaves the row at
    // identity + Options + Today + help.
    const inner = dock.querySelector(":scope > .dock-arrange .dock-menu > .dock-menu-list");
    if (inner) foldSiblingsIntoMenu(dock, inner, fold);
  }
}

function initDockFolding() {
  const query = window.matchMedia(DOCK_FOLD_BELOW);
  foldDockArrange(query.matches);
  // A window dragged across the boundary, or a tablet rotated, re-decides.
  query.addEventListener("change", (event) => foldDockArrange(event.matches));
}

initDockFolding();
watchOverlays(); // page behind a dialog must not scroll
initAutoGrow(); // capture + magic-add boxes follow their content
// Used to reopen on whichever tab was last active, with only the very
// first-ever visit defaulting to Dashboard. Changed on direct request: every
// load should open on Dashboard, not just the first one, closing the app on
// Chat and coming back to Chat wasn't "picking up where you left off" in the
// way that was wanted. `activeTab` is still tracked (`switchTab` still
// writes it) for the things that read the *current* tab during a session, 
// the scroll-to-top button, keyboard tab-cycling, just not to decide where
// a fresh load starts.
//
// revealTab, not switchTab: this runs before initAuth() has asked the server
// whether a token is even needed yet, so switchTab("dashboard")'s dashboard
// branch: renderDashboard(), which fetches stats/greeting/heatmap/tag-cloud/
// on-this-day/entries/chat/recent/most-accessed: used to fire here every
// cold load, token or not. With one already unlocked (stale-but-present, or
// simply not yet re-checked this tab) that's one harmless early 401 caught by
// api()'s isLockout path; with none at all, the common case, lock screen
// still up: it was ~20 requests a load, every one with an empty
// X-Auth-Token header, logged as browser console errors and, for the
// non-silent calls among them, into Settings → Logs. None of it painted
// anything (the lock overlay covers the tab), and startApp() already reloads
// the real data once a session exists (`entriesReady.then(refreshActiveTab)`
// above): so the early fetch was pure waste, not a second source of truth.
// The visual reveal still has to happen now, unconditionally: the tab-pages
// default to `hidden` in the markup, and the lock overlay is the only thing
// standing between a bare `hidden` class and a blank white app once it's
// dismissed.
revealTab("dashboard");

