// PWA: the shell caches itself so the app opens instantly (Wave F).
// When a new service worker takes over (after an update), reload once so
// the page never runs new HTML against stale cached CSS/JS (Wave O fix).
if ("serviceWorker" in navigator) {
  // Only reload when an EXISTING worker is replaced (a real update): not
  // on the first install, whose clients.claim() also fires controllerchange
  // and would reload the page mid-setup (Wave O fix).
  const hadController = Boolean(navigator.serviceWorker.controller);
  navigator.serviceWorker.register("/sw.js").catch(() => {});
  let swReloaded = false;
  navigator.serviceWorker.addEventListener("controllerchange", () => {
    if (!hadController || swReloaded) return;
    swReloaded = true;
    location.reload();
  });
}

// The generative brand emblem's initial draw (Wave O) moved to settings.js's
// own tail (§88.3 item 4): renderBrandLogo() itself stays here (used far
// outside Settings), but the accent/appearance state it reads through
// renderEmblem() moved, so calling it from this bare line, before
// settings.js has loaded: threw ReferenceError. See settings.js's header.

initAuth();

// Whiteboard subsystem moved to frontend/whiteboard.js (loaded via a
// second <script> tag in index.html, after this file). Everything that
// used to live here, board/card CRUD, sketch drawing, mind-mapping,
// export, move/resize: is defined there now, in the same shared global
// scope, so nothing here needs to change to keep calling it.

// ======================= FLOATING FORMAT MENU =======================

// --- Global Drag and Drop & Paste Image Upload for Textareas ---
document.addEventListener("dragover", (e) => {
  if (e.target.tagName && e.target.tagName.toLowerCase() === 'textarea') {
    e.preventDefault();
    e.target.classList.add("drag-over");
  }
});

document.addEventListener("dragleave", (e) => {
  if (e.target.tagName && e.target.tagName.toLowerCase() === 'textarea') {
    e.preventDefault();
    e.target.classList.remove("drag-over");
  }
});

// ROADMAP.md §89 item 5, fixed: this pair matches ANY `<textarea>` by tag
// name alone, which `#chat-input` is too: so a dropped/pasted image there
// used to route through `handleFileUpload` (written for the Notes/Document
// composer: inserts `![Uploading…]()` markdown placeholders into the
// textarea's own text) instead of the chat composer's real image-staging
// system, `attachImageFiles()`/`renderImageAttachments()`, the same one
// the composer's "+" button already uses, with its own attachment cards and
// its own toast-on-failure error handling. The symptom matched exactly:
// literal markdown-image syntax landing in the message box, and no
// attachment card, because nothing was ever staged through that system.
// `#chat-input` is excluded here and given its own branch instead of a
// second global listener, so there is exactly one place either kind of
// composer's drop/paste behaviour is decided.
function _isChatComposer(target) {
  return target && target.id === "chat-input";
}

document.addEventListener("drop", async (e) => {
  if (!e.target.tagName || e.target.tagName.toLowerCase() !== 'textarea') return;
  e.preventDefault();
  e.target.classList.remove("drag-over");

  if (_isChatComposer(e.target)) {
    const files = Array.from(e.dataTransfer.files);
    const images = files.filter((f) => f.type.startsWith("image/"));
    if (images.length) await attachImageFiles(images);
    if (images.length < files.length) {
      toast("Only images can be attached to a chat message right now.", true);
    }
    return;
  }

  const files = Array.from(e.dataTransfer.files).filter(f => f.type.startsWith("image/") || f.type.startsWith("application/") || f.type.startsWith("text/") || f.type.startsWith("video/") || f.type.startsWith("audio/"));
  if (!files.length) return;

  await handleFileUpload(e.target, files);
});

document.addEventListener("paste", async (e) => {
  if (!e.target.tagName || e.target.tagName.toLowerCase() !== 'textarea') return;
  const items = (e.clipboardData || e.originalEvent.clipboardData).items;
  const files = [];
  for (const item of items) {
    if (item.kind === 'file') {
      files.push(item.getAsFile());
    }
  }
  if (!files.length) return;
  // Don't prevent default entirely unless we have files, otherwise normal paste breaks
  e.preventDefault();

  if (_isChatComposer(e.target)) {
    const images = files.filter((f) => f.type.startsWith("image/"));
    if (images.length) await attachImageFiles(images);
    if (images.length < files.length) {
      toast("Only images can be attached to a chat message right now.", true);
    }
    return;
  }

  await handleFileUpload(e.target, files);
});

//: Files waiting to become attachments on a note that does not exist yet.
//:
//: **Why staging rather than uploading immediately.** `/media/upload`, the
//: only endpoint the composer could reach, accepts nine image types and
//: `.pdf`, and that allowlist is not paranoia to widen: `/media/{name}`
//: serves inline from the app's own origin, so an `.html` or `.svg` landing
//: there is stored XSS, and the AI can write to that folder too. So a
//: `.docx`, a `.txt` or a code file dropped into the composer got a 415 and
//: a red toast, while **the same file attached fine to an already-saved
//: note** through `POST /entries/{id}/files`, whose allowlist covers about
//: sixty types precisely because attachments are served as downloads.
//:
//: The difference was never the file. It was that the composer has no note
//: id yet. So the file waits here until Save produces one, and then takes
//: the attachment path it should have taken all along, which also gets it
//: a real row, a card with a delete button, and a place in the Library.
//:
//: Images are deliberately *not* staged: an image in the middle of a
//: paragraph is content, and it needs to be inline markdown at the point in
//: the text where it was dropped, not an attachment at the bottom.

//: **Images wait for the note too now.**
//:
//: The composer used to `POST /media/upload` the moment a picture was dropped
//: or pasted, and the comment above explained why that was different from the
//: files beside it: an image is *content*, it has to land as inline markdown
//: at the point in the text where it was dropped. That is still true, and it
//: was never a reason for the file to survive a note nobody saved. Every
//: abandoned draft with a pasted screenshot left a row in the Library and a
//: file on disk, which is exactly the leak asked about: "files should only be
//: staged and not permanently saved while uploaded to a note that hasnt been
//: saved yet".
//:
//: So the markdown goes in immediately, pointing at a `staged:<key>` url the
//: renderer resolves to the local Blob, and Save swaps every one of those for
//: the real `/media/...` url the upload returns. The bytes never leave the
//: browser until there is a note to attach them to.
//: Swap every `staged:<key>` for the url its upload produced. A pure string
//: function on purpose: it is the step that decides what gets *saved*, so it
//: is the step worth being able to test on its own.
function rewriteStagedUrls(content, urlByKey) {
  let out = content;
  for (const [key, url] of Object.entries(urlByKey)) {
    out = out.split(stagedImageUrl(key)).join(url);
  }
  return out;
}

//: Upload everything staged in the composer and return `{key: url}`. Throws
//: on the first failure, which is deliberate: Save must not write a note
//: whose picture is a dead `staged:` url, and it must not silently drop the
//: picture either: the same rule `commitStagedImages` follows for chat.
async function commitCaptureImages() {
  const urlByKey = {};
  for (const image of captureStagedImages) {
    const form = new FormData();
    form.append("file", image.file);
    const uploaded = await apiJson("/media/upload", {
      method: "POST",
      headers: { "X-Auth-Token": authToken() },
      body: form,
    });
    urlByKey[image.key] = uploaded.url;
  }
  return urlByKey;
}

function clearStagedImages() {
  for (const image of captureStagedImages) {
    //: An object URL is a document-lifetime reference to the bytes; dropping
    //: the array alone leaks them for as long as the tab is open.
    if (image.objectUrl) URL.revokeObjectURL(image.objectUrl);
  }
  captureStagedImages = [];
}

async function uploadStagedFiles(entryId) {
  if (!captureStagedFiles.length) return;
  const staged = captureStagedFiles;
  captureStagedFiles = [];
  renderCaptureFiles();
  let failures = 0;
  for (const file of staged) {
    const form = new FormData();
    form.append("file", file);
    // Raw fetch: multipart must NOT get the JSON content-type header.
    const response = await fetch(`/entries/${entryId}/files`, {
      method: "POST",
      // Same gap as the composer's own version of this call, above.
      headers: { "X-Auth-Token": authToken(), "X-Workspace-ID": activeSpaceId() },
      body: form,
    });
    if (!response.ok) {
      failures++;
      const detail = await response.json().catch(() => ({}));
      toast(detail.detail || `${file.name}: couldn't attach (${response.status})`, true);
    }
  }
  // Only mentioned when it worked; a failure already said so, per file, and
  // "attached 2 files" under two error toasts would be the app arguing with
  // itself.
  if (failures < staged.length) await loadEntries();
}

async function handleFileUpload(textarea, files) {
  // The capture composer is the one place that can stage: it is the only
  // textarea whose content becomes a note with an id a moment later. A
  // document's own editor writes into a document, which has no attachment
  // table, so it keeps the inline-markdown path for everything.
  const canStage = textarea.id === "entry-content";
  const images = canStage ? files.filter((f) => f.type.startsWith("image/")) : files;
  const others = canStage ? files.filter((f) => !f.type.startsWith("image/")) : [];
  if (others.length) {
    captureStagedFiles.push(...others);
    renderCaptureFiles();
    toast(
      others.length === 1
        ? `“${others[0].name}” will be attached when you save.`
        : `${others.length} files will be attached when you save.`
    );
  }
  if (!images.length) return;
  files = images;

  const cursorPosition = textarea.selectionStart;
  const selectionEnd = textarea.selectionEnd;
  const originalText = textarea.value;

  //: **The composer stages instead of uploading**, see `captureStagedImages`.
  //: Everywhere else (the document editor) still uploads inline, because a
  //: document has an id from the moment it exists and nothing to wait for.
  //:
  //: Written before the "Uploading…" placeholder below rather than after it:
  //: assigning `textarea.value` moves the selection, so a branch that ran
  //: afterwards and re-sliced against `selectionEnd` would cut the note in a
  //: different place than it meant to.
  if (canStage) {
    let inserted = "";
    for (const file of files) {
      const key = `img-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
      captureStagedImages.push({
        key,
        file,
        objectUrl: URL.createObjectURL(file),
        name: file.name,
      });
      inserted += `![${file.name}](${stagedImageUrl(key)})\n`;
    }
    textarea.value =
      originalText.slice(0, cursorPosition) + inserted + originalText.slice(selectionEnd);
    textarea.dispatchEvent(new Event("input", { bubbles: true }));
    const at = cursorPosition + inserted.length;
    textarea.setSelectionRange(at, at);
    toast(
      files.length === 1
        ? `“${files[0].name}” will be saved with the note.`
        : `${files.length} images will be saved with the note.`,
    );
    return;
  }

  let textToInsert = "";
  for (const file of files) {
    textToInsert += `![Uploading ${file.name}…]()\n`;
  }
  textarea.value = originalText.substring(0, cursorPosition) + textToInsert + originalText.substring(selectionEnd);
  textarea.dispatchEvent(new Event('input', { bubbles: true }));

  for (const file of files) {
    const formData = new FormData();
    formData.append("file", file);
    try {
      const res = await apiJson("/media/upload", {
        method: "POST",
        headers: { "X-Auth-Token": authToken() },
        body: formData
      });
      // Image syntax (`![]()`) unconditionally became an <img> at render
      // time (renderInlineMarkdown): a non-image upload (PDF, docx, audio)
      // failed to decode as an image and the img.onerror handler then
      // reported it as "filename deleted", which is actively wrong: the
      // file uploaded fine and is sitting at res.url. Link syntax for
      // anything that isn't actually an image.
      const fileMarkdown = file.type.startsWith("image/")
        ? `![${res.filename}](${res.url})\n`
        : `[${res.filename}](${res.url})\n`;
      textarea.value = textarea.value.replace(`![Uploading ${file.name}…]()\n`, fileMarkdown);
      textarea.dispatchEvent(new Event('input', { bubbles: true }));
    } catch (err) {
      // Reported directly (§89 item 2): an upload failure rendered as if it
      // were the AI's own message: literal error text left sitting in the
      // note/document content, indistinguishable from something the user
      // actually typed. A toast is a notification; content is what gets
      // saved. Removing the placeholder outright (not replacing it with
      // more text) leaves the composer exactly as if the file were never
      // dropped/pasted, which is the honest description of what happened.
      console.error("Upload failed", err);
      textarea.value = textarea.value.replace(`![Uploading ${file.name}…]()\n`, "");
      textarea.dispatchEvent(new Event('input', { bubbles: true }));
      toast(err.message || `Couldn't upload "${file.name}".`, true);
    }
  }
}

// ROADMAP.md Tier 2 §16c: paste and drag-drop already reached Capture (the
// global textarea handler above matches any `<textarea>`, and `#entry-content`
// is one): checked live before building, and both already worked. The one
// genuinely missing path was a file-picker button; the only "attach" control
// near Capture was for linking existing *notes* to a chat message, not
// uploading a new file. Reuses the same `handleFileUpload` the paste/drop
// paths already use, so all three input paths insert identically.
if ($("entry-attach-file")) {
  $("entry-attach-file").addEventListener("click", () => {
    $("entry-attach-file-input").click();
  });
  $("entry-attach-file-input").addEventListener("change", async (e) => {
    const files = Array.from(e.target.files);
    if (files.length) await handleFileUpload($("entry-content"), files);
    e.target.value = ""; // so picking the same file twice still fires "change"
  });
}

if ($("entry-attach-existing")) {
  $("entry-attach-existing").addEventListener("click", async () => {
    const upload = await pickMediaDialog();
    if (!upload) return;
    // Same inline-markdown insertion shape handleFileUpload's own success
    // path uses, minus the upload, this is already sitting on disk.
    const textarea = $("entry-content");
    const cursorPosition = textarea.selectionStart;
    const original = textarea.value;
    const markdown = `![${upload.original_name}](${upload.url})\n`;
    textarea.value =
      original.substring(0, cursorPosition) + markdown + original.substring(textarea.selectionEnd);
    textarea.dispatchEvent(new Event("input", { bubbles: true }));
  });
}

// --- what shows in the status bar --------------------------------------------
//
// Asked for: "allow more stuff to be added and removed to the bottom status
// bar?? maybe??" The bar is a permanent strip across the bottom of every
// screen, so what belongs on it is taste rather than correctness.
//
// **Stored as what is hidden, not what is shown**, and that choice is the
// whole of the forward-compatibility story: a slot added in a later version
// appears by default for everyone, instead of being invisible to every user
// who ever opened this screen and saved a list that could not have named it.
//
// Only the slots that are *always* there are listed. The offline badge, the
// power-saver badge and the running-job slot appear when there is something
// to say and hide themselves again, and hiding a warning you asked for is a
// different kind of setting from tidying a permanent one away.
const STATUS_SLOTS = [
  { key: "ai", label: "AI status", hint: "The dot and emblem saying what the local model is doing" },
  { key: "notes", label: "Note count", hint: "How many notes you have, as a link to them" },
  { key: "reminders", label: "Reminders", hint: "Open and due reminders" },
  { key: "nav", label: "Back and forward", hint: "Move between the pages you have visited" },
  { key: "undo", label: "Undo and redo", hint: "The same undo the rest of the app uses" },
  { key: "command", label: "Command palette hint", hint: "The Ctrl-K reminder" },
  {
    key: "agent",
    label: "Ask the agent",
    hint: "Open the agent over whatever you are doing, from any tab",
  },
];

function hiddenStatusSlots() {
  // `prefsCache`, not `window.prefsCache`. It is declared with `let` at the
  // top level of a classic script, which puts it in the *global lexical*
  // scope, shared with every other script here, so a bare reference works , 
  // and explicitly NOT on `window`. Two existing call sites in this file get
  // that wrong and silently read `undefined` forever; this one measured as a
  // toggle that ticked and did nothing.
  const stored = typeof prefsCache === "object" && prefsCache ? prefsCache.status_bar_hidden : null;
  return new Set(Array.isArray(stored) ? stored : []);
}

function applyStatusBarSlots() {
  const hidden = hiddenStatusSlots();
  for (const element of document.querySelectorAll("[data-status-slot]")) {
    // `.hidden` rather than a style: everything else in this app that shows
    // and hides uses the class, and one of these slots (`status-task`) is
    // already driven by it from another code path.
    element.classList.toggle("status-slot-off", hidden.has(element.dataset.statusSlot));
  }
}

function renderStatusBarSettings() {
  const box = $("status-bar-items");
  if (!box) return;
  const hidden = hiddenStatusSlots();
  // The clock's own row lives inside this same container now (index.html): 
  // moved there so it wraps as one more compact chip alongside STATUS_SLOTS'
  // instead of stretching full-width as a lone sibling after the flex box.
  // `replaceChildren()` below is only ever meant to clear the *generated*
  // rows this loop is about to rebuild; without pulling the static clock
  // label out first, it would delete that markup along with them on every
  // call and silently orphan `#status-bar-clock-toggle` for the rest of
  // this function.
  const clockLabel = document.getElementById("status-bar-clock-toggle")?.closest("label");
  box.replaceChildren();
  for (const slot of STATUS_SLOTS) {
    const label = document.createElement("label");
    label.className = "checkbox-label status-bar-item";
    label.title = slot.hint;
    const box_ = document.createElement("input");
    box_.type = "checkbox";
    box_.checked = !hidden.has(slot.key);
    box_.addEventListener("change", () => {
      const next = hiddenStatusSlots();
      if (box_.checked) next.delete(slot.key);
      else next.add(slot.key);
      const list = [...next];
      if (prefsCache) prefsCache.status_bar_hidden = list;
      applyStatusBarSlots();
      setPreference("status_bar_hidden", list);
    });
    const text = document.createElement("span");
    text.textContent = slot.label;
    label.append(box_, text);
    box.appendChild(label);
  }
  // Put the clock's row back: see the comment above `clockLabel`'s
  // declaration. Appended last, so it reads as the odd one out it actually
  // is (off by default) without visually separating from its siblings.
  if (clockLabel) box.appendChild(clockLabel);
  // The clock's own opt-in toggle, not one of STATUS_SLOTS above (it is
  // off by default, so it is rendered and wired separately rather than
  // joining a loop that assumes every entry starts visible).
  const clockToggle = $("status-bar-clock-toggle");
  if (clockToggle) {
    clockToggle.checked = Boolean(prefsCache?.status_bar_clock);
    clockToggle.onchange = () => {
      if (prefsCache) prefsCache.status_bar_clock = clockToggle.checked;
      applyStatusClock();
      setPreference("status_bar_clock", clockToggle.checked);
    };
  }
}

let statusClockTimer = null;

// HH:MM, no seconds: a status-bar clock is glanced at, not watched, so a
// 30s repaint interval keeps it current without the per-second DOM writes
// the Dashboard's own bigger clock (paintDashClock) uses.
function paintStatusClock() {
  const el = $("status-clock");
  if (!el) return;
  el.textContent = new Date().toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" });
}

// Reads prefsCache.status_bar_clock rather than taking an argument, the same
// convention applyStatusBarSlots() and applyAppearance() already use: one
// source of truth, called again after every write.
function applyStatusClock() {
  const el = $("status-clock");
  if (!el) return;
  const on = Boolean(prefsCache?.status_bar_clock);
  el.classList.toggle("hidden", !on);
  if (statusClockTimer) {
    clearInterval(statusClockTimer);
    statusClockTimer = null;
  }
  if (on) {
    paintStatusClock();
    statusClockTimer = setInterval(paintStatusClock, 30000);
  } else {
    closeStatusClockDetail();
  }
}

// **The detail popover.** Asked for directly: seconds, the date and the
// timezone, on click or hover, none of which belong in the bar's own
// HH:MM (the comment on paintStatusClock explains why: glanced at, not
// watched, so a 30s repaint is deliberate there). This is the opposite
// case, open only while someone is actually looking at it, so it gets
// its own 1s ticker, started on open and stopped on close rather than
// running unconditionally in the background the way the bar's clock does.
let statusClockDetailTimer = null;
let statusClockDetailPinned = false;

function paintStatusClockDetail() {
  const now = new Date();
  const dateEl = $("status-clock-detail-date");
  const timeEl = $("status-clock-detail-time");
  const zoneEl = $("status-clock-detail-zone");
  if (!dateEl || !timeEl || !zoneEl) return;
  dateEl.textContent = now.toLocaleDateString([], {
    weekday: "long",
    year: "numeric",
    month: "long",
    day: "numeric",
  });
  timeEl.textContent = now.toLocaleTimeString([], {
    hour: "2-digit",
    minute: "2-digit",
    second: "2-digit",
  });
  // Both the IANA name (what a person recognises, "Europe/London") and
  // the numeric offset (what actually explains a gap between two
  // people's clocks): a name alone doesn't say which side of UTC you're
  // on, and an offset alone doesn't say which timezone that even is.
  const zone = Intl.DateTimeFormat().resolvedOptions().timeZone;
  const offsetMatch = /GMT([+-]\d+(?::\d+)?)/.exec(
    now.toLocaleTimeString([], { timeZoneName: "shortOffset" })
  );
  zoneEl.textContent = offsetMatch ? `${zone} (UTC${offsetMatch[1]})` : zone;
}

function openStatusClockDetail(pin) {
  const panel = $("status-clock-detail");
  const btn = $("status-clock");
  if (!panel || !btn || !prefsCache?.status_bar_clock) return;
  if (pin) statusClockDetailPinned = true;
  panel.classList.remove("hidden");
  btn.setAttribute("aria-expanded", "true");
  paintStatusClockDetail();
  if (!statusClockDetailTimer) {
    statusClockDetailTimer = setInterval(paintStatusClockDetail, 1000);
  }
  // Positioned from the button's own rect, not a static CSS offset: the
  // clock's horizontal position among the bar's other optional slots
  // (STATUS_SLOTS) isn't fixed, so a hardcoded `right:` would drift out
  // from under the button the moment a neighbouring slot is toggled off.
  // Opens *upward*: the status bar is the bottom of the screen, so
  // "below the button" is off-window.
  const margin = 8;
  const anchor = btn.getBoundingClientRect();
  panel.style.left = "0px";
  const box = panel.getBoundingClientRect();
  let left = anchor.left;
  if (left + box.width > window.innerWidth - margin) {
    left = Math.max(margin, window.innerWidth - margin - box.width);
  }
  panel.style.left = `${Math.round(left)}px`;
  panel.style.bottom = `${Math.round(window.innerHeight - anchor.top + margin)}px`;
}

function closeStatusClockDetail(force) {
  // Hover-out shouldn't close a click-pinned popover, only Escape,
  // outside click, or the clock itself being turned off should.
  if (statusClockDetailPinned && !force) return;
  statusClockDetailPinned = false;
  $("status-clock-detail")?.classList.add("hidden");
  $("status-clock")?.setAttribute("aria-expanded", "false");
  if (statusClockDetailTimer) {
    clearInterval(statusClockDetailTimer);
    statusClockDetailTimer = null;
  }
}

(() => {
  const btn = $("status-clock");
  if (!btn) return;
  btn.addEventListener("mouseenter", () => openStatusClockDetail(false));
  btn.addEventListener("mouseleave", () => closeStatusClockDetail(false));
  btn.addEventListener("focus", () => openStatusClockDetail(false));
  btn.addEventListener("blur", () => closeStatusClockDetail(false));
  btn.addEventListener("click", () => {
    if (statusClockDetailPinned) closeStatusClockDetail(true);
    else openStatusClockDetail(true);
  });
})();
document.addEventListener("click", (e) => {
  if (
    statusClockDetailPinned &&
    !e.target.closest("#status-clock, #status-clock-detail")
  ) {
    closeStatusClockDetail(true);
  }
});
document.addEventListener("keydown", (e) => {
  if (e.key === "Escape" && statusClockDetailPinned) closeStatusClockDetail(true);
});

// --- Agent Activity: a list of runs, not a log -------------------------------
//
// Reported, verbatim: *"make a better way to view and access agent model
// activity and logs that appear in the agent activity toast panels then how
// they appear now, they just spawn in and its a bunch of text dump in your
// face and just gets annoying. it should still be accessible though."*
//
// What it was: a live tail of every log record from `memorymap.*`, opened by
// the arrival of a line. One agent turn writes its context budget, its prompt
// composition and its tool budget, three paragraphs of arithmetic, so the
// panel's whole content was machinery nobody asked to read, and it opened
// itself to show it.
//
// What it is (AGENT_SKILLS_REFORM.md, Phase C): **one row per run**, collapsed.
// Opening a row shows its steps; opening a step shows the tool calls it made
// and what they returned. Three levels, each collapsed until asked for, and
// deliberately the *same* `<details>` shape and CSS the chat transcript uses
// for Thinking (`agent-step step-thinking`) and for a skill's plan
// (`agent-step step-plan`), so this is that component in another place rather
// than a fourth thing to maintain.
//
// The log is not gone and is not summarised: it is behind "Show log", with the
// same lines it always had. That is the "it should still be accessible though"
// half, and it is why `appendAgentLog` below is unchanged apart from no longer
// forcing the panel open.
const agentMonitor = $("agent-monitor");
const agentMonitorLogs = $("agent-monitor-logs");
const agentMonitorRuns = $("agent-monitor-runs");
const agentMonitorEmpty = $("agent-monitor-empty");
const agentMonitorLogToggle = $("agent-monitor-log-toggle");
const agentMonitorClose = $("agent-monitor-close");
const agentMonitorClear = $("agent-monitor-clear");

//: Runs kept in the panel for this session, oldest first. Twelve because the
//: panel is 350px wide and a row is one line collapsed: past that it is a list
//: to scroll rather than a thing to glance at, and the audit log
//: (Library → AI Skills) is the real history.
const AGENT_RUN_LIMIT = 12;
const agentRuns = [];
let agentRunSeq = 0;

//: Whether the reader opened the panel themselves. A manual open must not be
//: taken away by the idle timer twelve seconds later, that timer exists for
//: a panel that opened *itself*.
let agentMonitorPinned = false;

//: **One wording for a step's state, used in both places it is shown.** The
//: chat's plan card and this panel are two renderings of the same run, and
//: two different sentences for `retrying` would read as two different things
//: happening. Phase A's runner emits `attempt`/`of`/`reason` with the event;
//: this is where they become words.
function stepStateWords(state, event = {}) {
  const reason = event.reason ? `, ${event.reason}` : "";
  if (state === "retrying") {
    const attempt = event.attempt || 1;
    const of = event.of || attempt;
    return `retrying, attempt ${attempt} of ${of}${reason}`;
  }
  //: A step the run *rewrote* after it failed (PLAN.md §4 A2: 
  //: `skill_runner.MAX_REPLANS`). Worded as recovery rather than as an error,
  //: because that is what it is: the step is about to be tried again with a
  //: smaller instruction, and the line under it is the new one.
  if (state === "replanned") {
    const attempt = event.attempt || 1;
    const of = event.of || attempt;
    return `re-planned, attempt ${attempt} of ${of}${reason}`;
  }
  //: **Paging** (CHAT_PLAN decision 10). A step that must see every note
  //: calls its read once per page, and without this the reader watches one
  //: step sit on "running" through four tool calls with no sign that it is
  //: getting anywhere. The count of notes read is the progress, so it is the
  //: half that gets said.
  if (state === "paging") {
    const page = event.page || 1;
    const of = event.of || page;
    const seen = event.seen ? `, ${event.seen} read` : "";
    return `reading page ${page} of at most ${of}${seen}`;
  }
  if (state === "running") return "running";
  if (state === "done") return "done";
  if (state === "earlier") return "done in the run this resumed";
  if (state === "failed") return `failed${reason}`;
  if (state === "stalled") return `stalled${reason}`;
  return `${state}${reason}`;
}

//: The icon and word for a whole run, in the same "ph:icon Text" shape every
//: other label in this app uses (`setLabel` resolves it).
function runStateLabel(state) {
  if (state === "running") return "ph:circle-notch Running";
  if (state === "done") return "ph:check-circle Done";
  if (state === "failed") return "ph:x-circle Failed";
  if (state === "stalled") return "ph:pause-circle Stalled";
  if (state === "paused") return "ph:pause-circle Waiting for you";
  return state;
}

function renderAgentRunSummary(run) {
  if (!run) return;
  setLabel(run.nameEl, run.icon ? `${run.icon} ${run.name}` : run.name);
  // "Step 2 of 5" only when the run declared steps. A background job knows how
  // far along it is as a fraction and not as a step number; an agent turn with
  // no plan has no steps at all, and inventing one for either would be the
  // progress bar that guesses.
  const done = run.steps.filter((step) => step.state === "done" || step.state === "earlier").length;
  if (run.stepCount) {
    const at = Math.min(run.stepCount, (run.currentIndex ?? done) + 1);
    run.metaEl.textContent =
      run.state === "running" ? `Step ${at} of ${run.stepCount}` : `${done} of ${run.stepCount} steps`;
  } else {
    run.metaEl.textContent = run.detail || "";
  }
  //: **A counter is a label on the bar beside it; a detail is a sentence.**
  //: Both go in the same slot, and the slot is allowed to wrap because of the
  //: sentence: so "Step 2 of 3" broke across two lines next to the bar, which
  //: is how a 60px row became 78 and three runs came to need a scroller in a
  //: panel that could hold them. The class says which of the two this is, and
  //: the stylesheet stops the counter wrapping without touching the sentence.
  run.metaEl.classList.toggle("agent-run-count", Boolean(run.stepCount));
  setLabel(run.stateEl, runStateLabel(run.state));
  run.stateEl.className = `agent-run-state plan-step-${run.state}`;
  // A fraction, or nothing at all, the same rule the Tasks panel follows for
  // exactly the same reason (`renderTasks`): a bar that guesses is worse than
  // one that admits it cannot say.
  const fraction =
    typeof run.progress === "number"
      ? run.progress
      : run.stepCount
        ? done / run.stepCount
        : null;
  run.bar.classList.toggle("hidden", fraction === null);
  if (fraction !== null) run.bar.value = Math.max(0, Math.min(1, fraction));
  // An agent turn has neither a step count nor a fraction, and an empty second
  // line under its name is a gap that looks like something failed to load.
  run.progressWrap.classList.toggle("hidden", fraction === null && !run.metaEl.textContent);
  run.el.classList.toggle("is-running", run.state === "running");
}

//: What to call a run that has no name of its own. An agent turn is titled by
//: the question that started it, trimmed to something that fits one line of a
//: 350px panel: the alternative is a row called "Agent turn" fourteen times.
function agentRunTitle(question) {
  const text = String(question || "").replace(/\s+/g, " ").trim();
  if (!text) return "Agent turn";
  return text.length > 48 ? `${text.slice(0, 47)}…` : text;
}

//: A run row. Built once and updated in place, re-rendering the list on every
//: event would slam shut any `<details>` the reader had just opened, which is
//: the one thing this panel exists to let them do.
function addAgentRun({ kind, name, icon = "", steps = [], detail = "" }) {
  //: A desktop shell running a cached `index.html` against a fresh `app.js`
  //: is a thing that has actually happened here (CLAUDE.md, the static-cache
  //: header bug), and the failure mode must be "no run list", not a TypeError
  //: that takes the chat turn down with it.
  if (!agentMonitorRuns) return null;
  const run = {
    id: `run-${++agentRunSeq}`,
    kind,
    name: name || "Run",
    icon,
    detail,
    state: "running",
    steps: [],
    stepCount: steps.length,
    currentIndex: null,
    progress: null,
  };

  const el = document.createElement("details");
  // The chat's own plan card, reused wholesale: same fold, same marker, same
  // type scale.
  el.className = "agent-step step-plan agent-run-row";
  const summary = document.createElement("summary");
  summary.className = "agent-run-summary";
  run.nameEl = document.createElement("span");
  run.nameEl.className = "agent-run-name";
  run.metaEl = document.createElement("span");
  run.metaEl.className = "agent-run-meta";
  run.stateEl = document.createElement("span");
  run.stateEl.className = "agent-run-state";
  run.bar = document.createElement("progress");
  run.bar.className = "task-progress";
  run.bar.max = 1;
  run.bar.value = 0;
  //: **The bar goes inside the `<summary>`, and it has to.** A row is
  //: collapsed by default, that is the whole point of the rebuild, so
  //: anything in the `<details>` body is invisible exactly when the run is
  //: worth watching. `<progress>` and `<span>` are phrasing content, which is
  //: what a `<summary>` may contain.
  //:
  //: The second line is a wrapper rather than two more items in the summary's
  //: own flex row: measured on the 350px panel, "Step 1 of 3" and "Running"
  //: beside the name left it 125px, a run called "Summarise my week" showed
  //: as "Summarise …". The step count belongs with the bar it describes, and
  //: moving it there gives the name back most of the row.
  run.progressWrap = document.createElement("span");
  run.progressWrap.className = "agent-run-progress";
  run.progressWrap.append(run.metaEl, run.bar);
  summary.append(run.nameEl, run.stateEl, run.progressWrap);
  run.body = document.createElement("div");
  run.body.className = "agent-run-body";
  el.append(summary, run.body);
  run.el = el;
  //: **A run with no steps must not offer a fold.** Reported twice (INBOX 69,
  //: "a 'Starting SearXNG' row with a caret that does nothing"; and again on
  //: 2026-09-09 against "Loading the embedding model"). Both are background
  //: jobs, which is exactly the case that declares no steps: the `<details>`
  //: still drew the marker and still toggled, onto an empty body. The step
  //: rows have had this rule since Phase C (`:not(.has-tools)`), the run row
  //: never got it. `has-steps` is set by `agentRunAddStep`; the guard below
  //: is the half the CSS cannot do, since a hidden marker is still a summary
  //: and a click on it still toggles.
  summary.addEventListener("click", (event) => {
    if (!el.classList.contains("has-steps")) event.preventDefault();
  });

  for (const [index, text] of steps.entries()) agentRunAddStep(run, index, text);

  agentMonitorRuns.appendChild(el);
  agentRuns.push(run);
  // Oldest first out, and never one that is still going: a run scrolled off
  // the list while it was running is a run whose end is never shown.
  while (agentRuns.length > AGENT_RUN_LIMIT) {
    const oldest = agentRuns.findIndex((item) => item.state !== "running");
    if (oldest === -1) break;
    agentRuns.splice(oldest, 1)[0].el.remove();
  }
  renderAgentRunSummary(run);
  renderActivityStatusItem();
  agentMonitorEmpty?.classList.add("hidden");
  //: The list is chronological and it scrolls, so without this a run that
  //: starts while eight are already listed is appended out of sight, the
  //: same tail-following the log it replaced has always done.
  agentMonitorRuns.scrollTop = agentMonitorRuns.scrollHeight;
  return run;
}

function agentRunAddStep(run, index, text) {
  const step = { index, state: "pending", text, toolCount: 0 };
  const el = document.createElement("details");
  // The Thinking disclosure, reused: quieter than the run row above it, folds
  // the same way, and the marker is drawn inside the summary rather than in
  // the rail's gutter (see its rule in 02-chat-graph.css).
  el.className = "agent-step step-thinking agent-run-step";
  const summary = document.createElement("summary");
  summary.className = "plan-step";
  step.summary = summary;
  step.tools = document.createElement("div");
  step.tools.className = "agent-run-tools";
  el.append(summary, step.tools);
  step.el = el;
  run.body.appendChild(el);
  run.el.classList.add("has-steps");
  run.steps.push(step);
  agentRunPaintStep(run, step);
  return step;
}

function agentRunPaintStep(run, step, event = {}) {
  const words = step.state === "pending" ? "not started yet" : stepStateWords(step.state, event);
  const number = `${step.index + 1}. `;
  step.summary.textContent = `${number}${step.text}: ${words}`;
  step.summary.className = `plan-step plan-step-${step.state}`;
  step.summary.dataset.state = step.state;
}

//: **What the app checked after the run, in the app's own words.** A skill
//: may declare a `verify` block (a tool call plus a predicate); the runner
//: runs it against the notebook once the last step is done and the answer
//: lands here. Worded as a fact with the number in it, never as a badge on
//: its own: "verified" with nothing behind it is the same reassurance the
//: green tick on an unfinished step used to give.
function verificationRow(check) {
  const row = document.createElement("div");
  row.className = `skill-verify skill-verify-${check.ok ? "ok" : "not-ok"}`;
  row.textContent = check.ok ? `Verified: ${check.reason}` : `Not verified: ${check.reason}`;
  return row;
}

//: One step event from the runner. `retrying` is Phase A's own state and is
//: the reason this panel had to change: a step that is being re-prompted looks
//: exactly like one that is running unless it says so.
function agentRunStep(run, event) {
  if (!run) return;
  let step = run.steps[event.index];
  if (!step) step = agentRunAddStep(run, event.index, event.text || `Step ${event.index + 1}`);
  if (event.text) step.text = event.text;
  step.state = event.state;
  agentRunPaintStep(run, step, event);
  run.currentIndex = event.index;
  //: `replanned` is included because the step is about to be run again at the
  //: same index: the calls it makes next belong under it, not under whatever
  //: step happened to be current before it.
  if (
    event.state === "running" ||
    event.state === "retrying" ||
    event.state === "replanned" ||
    //: `paging` is the step still working: the next page's tool call belongs
    //: under it, and leaving it out would file the rest of a paged read under
    //: whatever step was current before this one.
    event.state === "paging"
  ) {
    run.currentStep = step;
  }
  //: A step that stopped the run opens itself. Everything else stays folded, 
  //: which is the point of the panel, but a failure nobody can see without a
  //: click is a failure reported as silence.
  if (event.state === "failed" || event.state === "stalled") step.el.open = true;
  renderAgentRunSummary(run);
}

//: A tool call, filed under the step that made it. A run with no steps (a
//: plain agent turn) keeps its calls at the top level: inventing a "step 1 of
//: 1" for it would be a level that says nothing.
function agentRunTool(run, node) {
  if (!run || !node) return;
  const holder = run.currentStep ? run.currentStep.tools : run.body;
  holder.appendChild(node);
  if (run.currentStep) {
    run.currentStep.toolCount += 1;
    run.currentStep.el.classList.add("has-tools");
  }
  renderAgentRunSummary(run);
}

function endAgentRun(run, { state = "done", detail = "" } = {}) {
  if (!run || run.state !== "running") return;
  run.state = state;
  if (detail) run.detail = detail;
  run.currentStep = null;
  // Anything still marked running when the run ended did not finish. Saying so
  // is the difference between a record and a wish.
  for (const step of run.steps) {
    if (step.state !== "running" && step.state !== "retrying" && step.state !== "paging") continue;
    step.state = state === "done" ? "done" : state;
    agentRunPaintStep(run, step);
  }
  renderAgentRunSummary(run);
  renderActivityStatusItem();
  //: **The only toast a chat run raises, and only when nobody could have seen
  //: it end.** Phase C's rule is start / finished / failed and nothing else;
  //: the *start* of a run the reader is not watching is already announced by
  //: this panel opening itself, so the end is the half with nothing saying it.
  //: A run that ended in the transcript the reader is looking at needs no
  //: notice at all: the transcript is the notice.
  //:
  //: Through `agentActivityNotice`, never `toast`, so the mute and "Panel
  //: only" switches keep working: it records into the notifications centre
  //: either way and only flies a toast past the corner of the screen when the
  //: reader has asked for those. Background jobs are not included, they have
  //: announced their own ends since before this panel existed
  //: (`noticeTaskTransitions`), and doing it here as well would say it twice.
  if (run.kind !== "job" && agentRunWantsPanel(run)) {
    const failed = state === "failed" || state === "stalled";
    agentActivityNotice(failed ? `Stopped: ${run.name}` : `Finished: ${run.name}`, {
      isError: state === "failed",
      detail: failed ? "Open Agent Activity to see which step stopped it." : "",
    });
  }
}

//: Whether a starting run should also *open* the panel.
//:
//: The old rule was "any log line opens it", which is the reported complaint.
//: The new one: a run the reader is already watching does not need a panel
//: over the top of it, a skill run in the Chat tab is drawn step by step in
//: the transcript: but a background pass, or a run left behind on another
//: tab, has nowhere else to show itself.
function agentRunWantsPanel(run) {
  if (run.kind === "job") return true;
  //: The tab the app is actually showing, read the way every other caller
  //: reads it: `switchTab` writes it, and there is no in-memory copy to go
  //: stale against a reload.
  return (localStorage.getItem("activeTab") || "") !== "chat";
}

function openPanelForRun(run) {
  if (!run || !agentRunWantsPanel(run)) return;
  if (!agentMonitor.classList.contains("hidden")) return;
  if (Date.now() - agentMonitorDismissedAt < AGENT_MONITOR_REOPEN_AFTER_MS) return;
  setAgentMonitorVisible(true);
  nudgeAgentMonitorIdle();
}

//: The way back in. See index.html for why it exists: log lines no longer open
//: this panel, so without a control naming it, a finished run would be
//: unreachable the moment the panel timed out.
function renderActivityStatusItem() {
  const button = $("status-activity");
  if (!button) return;
  button.classList.toggle("hidden", agentRuns.length === 0);
  if (!agentRuns.length) return;
  const running = agentRuns.filter((run) => run.state === "running").length;
  paintStatusItem("status-activity", {
    icon: "ph:robot",
    value: running || agentRuns.length,
    label: running ? "running" : agentRuns.length === 1 ? "run" : "runs",
    title: "Agent activity: every run this session, and the log.\n\nClick to show or hide the panel.",
  });
}

function setAgentMonitorLogVisible(show) {
  if (!agentMonitorLogToggle || !agentMonitorRuns) return;
  agentMonitorLogs.classList.toggle("hidden", !show);
  agentMonitorRuns.classList.toggle("hidden", show);
  agentMonitorEmpty?.classList.toggle("hidden", show || agentRuns.length > 0);
  agentMonitorLogToggle.textContent = show ? "Show runs" : "Show log";
  agentMonitorLogToggle.setAttribute("aria-expanded", String(show));
}

if (agentMonitorLogToggle) {
  agentMonitorLogToggle.addEventListener("click", () => {
    setAgentMonitorLogVisible(agentMonitorLogs.classList.contains("hidden"));
  });
}

$("status-activity")?.addEventListener("click", () => {
  const showing = !agentMonitor.classList.contains("hidden");
  agentMonitorPinned = !showing;
  setAgentMonitorVisible(!showing);
  // Opened by hand, so the dismissal window that keeps a run from reopening it
  // is spent: otherwise pressing this within 90s of an X does nothing.
  if (!showing) agentMonitorDismissedAt = 0;
});

// The monitor is `position: fixed` in the bottom-right corner, which is also
// where the whiteboard keeps its zoom controls, so while it was open those
// controls were behind it and simply could not be clicked. A floating panel
// that covers a fixed control is a broken control, so the app is told when the
// monitor is showing and the whiteboard lifts its panel clear.
function setAgentMonitorVisible(visible) {
  agentMonitor.classList.toggle("hidden", !visible);
  document.body.classList.toggle("has-agent-monitor", visible);
  if (!visible) clearTimeout(agentMonitorIdleTimer);
}

//: How long after the last line the monitor puts itself away. Reported
//: directly: "autonomous background task notifications never auto close and
//: stay open until the user closes them", and they did not, because nothing
//: here ever called `setAgentMonitorVisible(false)` except the X button. A
//: background pass would open this panel over the corner of the app and leave
//: it there for the rest of the session.
//:
//: Twelve seconds is picked against what the panel is *for*: it is a live
//: tail, so it is interesting while lines are arriving and is a leftover the
//: moment they stop. Every new line restarts the clock, so a pass that runs
//: for four minutes keeps it open for four minutes.
const AGENT_MONITOR_IDLE_MS = 12000;

//: Long enough that a *new* pass reopens the panel, short enough that a
//: dismissal during one pass is not overridden two seconds later by the next
//: line of the same pass. Closing it used to mean nothing at all: the very
//: next log line re-opened it, so the X button read as broken.
const AGENT_MONITOR_REOPEN_AFTER_MS = 90000;

let agentMonitorIdleTimer = null;
let agentMonitorDismissedAt = 0;

function nudgeAgentMonitorIdle() {
  clearTimeout(agentMonitorIdleTimer);
  //: **A panel somebody opened on purpose is never taken away.** The timer
  //: below exists for a panel that opened *itself*; applying it to a manual
  //: open would close the run list twelve seconds into reading it.
  if (agentMonitorPinned) return;
  agentMonitorIdleTimer = setTimeout(() => {
    // Never yank it away from under a pointer or a keyboard focus: someone
    // reading a line or reaching for the X is the one case where the panel
    // is doing its job.
    if (agentMonitor.matches(":hover") || agentMonitor.contains(document.activeElement)) {
      nudgeAgentMonitorIdle();
      return;
    }
    //: Nor while something is still going: a run row that is still ticking is
    //: the live thing this panel is for, and it used to be a log line every
    //: few seconds that kept the panel awake. There are no log lines keeping
    //: it awake any more, so the run itself has to.
    if (agentRuns.some((run) => run.state === "running")) {
      nudgeAgentMonitorIdle();
      return;
    }
    setAgentMonitorVisible(false);
  }, AGENT_MONITOR_IDLE_MS);
}

//: **Clear**, reported on 2026-09-09: "the agent activity logs cant be
//: cleared". The panel is a session tail with a fifty-line cap and an
//: eight-row run cap, so it never emptied on its own except by ageing out,
//: and a reader who has read it had no way to say so. Both halves go, since
//: the button is in the header above both and clearing one while the other
//: kept its backlog would be the sort of half-action that reads as broken.
//: A run still going is kept: it is the live thing the panel is for, and
//: removing its row would strand its end with nothing to draw it on.
if (agentMonitorClear) {
  agentMonitorClear.addEventListener("click", () => {
    const kept = [];
    for (const run of agentRuns) {
      if (run.state === "running") kept.push(run);
      else run.el.remove();
    }
    agentRuns.length = 0;
    agentRuns.push(...kept);
    agentMonitorLogs.textContent = "";
    agentMonitorEmpty?.classList.toggle(
      "hidden",
      agentRuns.length > 0 || !agentMonitorLogs.classList.contains("hidden"),
    );
    renderActivityStatusItem();
  });
}

if (agentMonitorClose) {
  agentMonitorClose.addEventListener("click", () => {
    agentMonitorDismissedAt = Date.now();
    agentMonitorPinned = false;
    setAgentMonitorVisible(false);
  });
}

function appendAgentLog(record) {
  // **Agent lines only.** This used to read `if (!isAgent && record.level !==
  // "ERROR") return;`, which let *every* ERROR in the app through whatever
  // logger produced it: so a failed embedding backend, a bad request, a
  // stray traceback all popped open a panel labelled "Agent Activity" and
  // left it there. Errors already have somewhere to go (a toast, and
  // Settings → Logs); this panel is a tail of one specific thing.
  const logger = record.logger || "";
  const isAgent =
    logger.startsWith("memorymap.ai") ||
    logger.includes("autonomous") ||
    logger.includes("agent");
  if (!isAgent) return;

  //: **A log line no longer opens this panel** (Phase C). It is the whole of
  //: the reported complaint: one agent turn writes its context budget, its
  //: prompt composition and its tool budget, and each of those three
  //: paragraphs was enough to throw the panel over whatever you were reading.
  //: The lines are still collected, identically, and still capped at fifty , 
  //: and Show log is one click. What opens the panel now is a *run* starting
  //: (`openPanelForRun`), which is a thing that happened rather than a
  //: sentence that was written about it.
  const div = document.createElement("div");
  div.className = "monitor-log-item " + record.level.toLowerCase();
  div.textContent = record.message;

  agentMonitorLogs.appendChild(div);

  if (agentMonitorLogs.children.length > 50) {
    agentMonitorLogs.removeChild(agentMonitorLogs.firstChild);
  }

  agentMonitorLogs.scrollTop = agentMonitorLogs.scrollHeight;
  //: Only while the log is the view being read, otherwise a burst of lines
  //: from a background pass would keep a panel awake that is showing a list
  //: nothing is changing in.
  if (!agentMonitorLogs.classList.contains("hidden")) nudgeAgentMonitorIdle();
}

let agentLogStreamStarted = false;
async function streamAgentLogs() {
  if (agentLogStreamStarted) return;
  agentLogStreamStarted = true;
  let cursor = 0;
  while (true) {
    try {
      const response = await fetch(`/logs/stream?after=${cursor}`, {
        headers: { "X-Auth-Token": authToken() }
      });
      if (response.status === 401) {
         await new Promise(r => setTimeout(r, 5000));
         continue;
      }
      if (!response.ok) throw new Error("stream failed");
      
      const reader = response.body.getReader();
      const decoder = new TextDecoder();
      let buffer = "";
      
      while (true) {
        const { value, done } = await reader.read();
        if (done) break;
        buffer += decoder.decode(value, { stream: true });
        const lines = buffer.split("\n");
        buffer = lines.pop(); // keep last incomplete line
        
        for (const line of lines) {
          if (!line.trim()) continue;
          const msg = JSON.parse(line);
          if (msg.cursor) cursor = msg.cursor;
          
          if (msg.type === "open") {
            cursor = msg.latest || cursor;
          } else if (msg.type === "record") {
            appendAgentLog(msg.record);
          }
        }
      }
    } catch (e) {
      await new Promise(r => setTimeout(r, 5000));
    }
  }
}

// Hook it into startApp
const originalStartAppAgentHook = window.startApp;
window.startApp = async function() {
  if (originalStartAppAgentHook) {
    await originalStartAppAgentHook.apply(this, arguments);
  }
  streamAgentLogs();
  //: After the app has painted, so the strips that are built at run time
  //: (the Library sub-tabs, the editor toolbars) are in the DOM to be wired.
  //: Idempotent per element (`data-wheel-x`), so calling it again is free.
  wireHorizontalWheelScrolling();
}

// --- Global Command Palette (Ctrl+K) ---
const cmdPaletteOverlay = $("command-palette-overlay");
const cmdPaletteInput = $("command-palette-input");
const cmdPaletteResults = $("command-palette-results");

// Opened and closed by `runShortcut("askAgent")`, see DEFAULT_SHORTCUTS.
// This deliberately has no `document.addEventListener` chord of its own:
// binding one here is what let this overlay collide with the navigation
// palette on Ctrl+K, and then with the sketch pad on Ctrl+Shift+K, twice
// without anything noticing.
function toggleAgentPalette() {
  if (cmdPaletteOverlay.classList.contains("hidden")) {
    cmdPaletteOverlay.classList.remove("hidden");
    cmdPaletteInput.focus();
  } else {
    cmdPaletteOverlay.classList.add("hidden");
  }
}

document.addEventListener("keydown", (e) => {
  if (e.key === "Escape" && !cmdPaletteOverlay.classList.contains("hidden")) {
    cmdPaletteOverlay.classList.add("hidden");
  }
});

cmdPaletteOverlay.addEventListener("click", (e) => {
  if (e.target === cmdPaletteOverlay) {
    cmdPaletteOverlay.classList.add("hidden");
  }
});

// The head's Close. Escape and a click on the backdrop both already closed this
// surface and neither is visible, which is the half of "redesigned with the
// consistent modern look" that is not paint: every other dialog in the app
// offers a control you can see and this one asked you to know a key.
$("command-palette-close").addEventListener("click", () => toggleAgentPalette());

//: **The agent bar keeps a conversation, and says so.** Reported: "the popup
//: agent needs more features, capability, and learnability, there's no way to
//: clear the chat and start over, idk what it can do, and even if it works".
//: Every one of those was true of the same handler:
//:
//: - It sent `history: []` on every turn, so a follow-up ("now file that as a
//:   note") could not refer to the answer above it. It was a series of
//:   unrelated one-shot questions in a window that looked like a chat.
//: - There was no way to clear it, so the only reset was reloading the app.
//: - Its whole affordance was "Press Enter to send", which says nothing about
//:   what it can be asked to *do*.
//: - Every failure came out as "Error communicating with agent.", the one
//:   message that guarantees "idk if it even works", and it threw away
//:   `err.message`, which is exactly where `describe_http_error`'s diagnosis
//:   of a failing model arrives.
const cmdPaletteTurns = [];
let cmdPaletteRun = null;

function cmdPaletteReset() {
  cmdPaletteTurns.length = 0;
  cmdPaletteResults.replaceChildren();
  $("command-palette-intro")?.classList.remove("hidden");
  $("command-palette-status").textContent = "";
}

function cmdPaletteBusy(busy) {
  cmdPaletteInput.disabled = busy;
  $("command-palette-stop")?.classList.toggle("hidden", !busy);
  $("command-palette-clear")?.classList.toggle("hidden", busy);
  $("command-palette-status").textContent = busy ? "Working…" : "";
  if (!busy) cmdPaletteInput.focus();
}

//: **The palette says what it did, the way the Chat tab does.** Reported:
//: "the popup agent is still missing many things like the semantic search,
//: token count, thinking boxes, metadata, persona used, model used... the
//: popup agent should be an application wide utility tool."
//:
//: Every one of those already arrives on the stream, `onMeta` carries the
//: search mode and what answered, `onStats` the model and the token counts,
//: `onThinking` the reasoning: and the palette wired all three to `() => {}`.
//: So this is not new machinery; it is the same events the Chat tab reads,
//: rendered in the one surface that was throwing them away.
//:
//: A quiet footer rather than the Chat tab's full panel, on purpose: the
//: palette is a 600px overlay you open on top of whatever you were doing, and
//: reproducing a side panel in it would make the answer harder to read, not
//: better evidenced. Each fact is a chip, so the row wraps and stays one line
//: tall when there is little to say.
function cmdPaletteMetaRow({ meta, stats, persona }) {
  const facts = [];
  if (meta?.search_mode && meta.search_mode !== "none") {
    facts.push([
      "ph:magnifying-glass",
      SEARCH_MODE_LABELS[meta.search_mode] || meta.search_mode,
      "How your notes were searched for this answer",
    ]);
  }
  const model = stats?.model || meta?.answered_by;
  if (model) facts.push(["ph:cpu", model, "The model that answered"]);
  if (persona) facts.push(["ph:user-circle", persona, "The persona that answered"]);
  const tokens = (stats?.prompt_tokens || 0) + (stats?.output_tokens || 0);
  if (tokens) {
    //: `usage_source` is the difference between a measured count and a guess,
    //: and reporting a guess as a measurement is the dishonest way round, 
    //: the same reason the Chat tab's own accumulator propagates it.
    const estimated = stats.usage_source === "estimated";
    facts.push([
      "ph:coins",
      `${formatTokens(tokens)} tokens${estimated ? " (est.)" : ""}`,
      estimated
        ? "Estimated: this model did not report its own usage"
        : "Counted by the model",
    ]);
  }
  if (stats?.round > 1) {
    facts.push(["ph:arrows-clockwise", `${stats.round} rounds`, "Tool rounds this turn took"]);
  }
  if (!facts.length) return null;
  const row = document.createElement("div");
  row.className = "row cmd-palette-meta";
  for (const [icon, text, title] of facts) {
    const item = document.createElement("span");
    item.className = "chip tag cmd-palette-fact";
    setLabel(item, `${icon} ${text}`);
    item.title = title;
    row.appendChild(item);
  }
  return row;
}

//: The model's reasoning, closed. It is long, it is not the answer, and the
//: palette is the smallest surface in the app, but hiding it entirely is what
//: made this window feel like it was doing something it would not explain.
function cmdPaletteThinkingBox(text) {
  const box = document.createElement("details");
  box.className = "tool-chip cmd-palette-thinking";
  const summary = document.createElement("summary");
  setLabel(summary, "ph:brain Thinking");
  box.appendChild(summary);
  const body = document.createElement("div");
  body.className = "tool-chip-body";
  const pre = document.createElement("pre");
  pre.className = "tool-chip-result";
  pre.textContent = text;
  body.appendChild(pre);
  box.appendChild(body);
  return box;
}

//: **What the agent found has to be reachable, not recited.** Reported with a
//: screenshot of the palette answering "You can find your notes about gaming
//: in notes id 3, 43 and 49": *"i have no clue what the notes numbers are,
//: there are no links to notes, no way to actually find and navigate to the
//: things it found, there is no semantic search results that appear."*
//:
//: Every word of that was a fair reading of what the code did. `onMeta`, the
//: event carrying `raw_results`, the notes retrieval actually surfaced, was
//: wired to `() => {}` here, so the one surface that knew which notes the turn
//: had found threw them away and left the model to describe them in prose. A
//: row id is the app's internal handle; printing it at a person is the same
//: mistake as the audit log's raw `entity_type`, and worse, because there is
//: nothing they can do with it.
//:
//: Two halves, and both are needed. The row below the answer is the *result
//: set*: it exists even when the model's prose forgets to mention a note, and
//: it is the semantic search result the report says is missing. The linkifier
//: is for the prose itself: a model that says "note id 43" is naming something
//: real, so that phrase becomes the button that opens it rather than a number
//: to go hunting for.
const CMD_NOTE_REF = /\bnotes?\s*(?:id|#)?\s*(\d{1,7})\b/gi;

//: Opening a note means leaving the palette, it is an overlay over the app it
//: is about to navigate. Closing it first is what makes "find it" and "go to
//: it" one gesture instead of a jump that happens behind a panel.
function cmdPaletteGoToNote(id) {
  cmdPaletteOverlay.classList.add("hidden");
  flashEntry(id);
}

//: The same gesture for a document. Notes and documents share an id space
//: only by accident, id 12 is a different object in each table, so this
//: cannot be folded into the note case: sending a document id through
//: `flashEntry` opens an unrelated note, silently.
function cmdPaletteGoToDocument(id) {
  cmdPaletteOverlay.classList.add("hidden");
  openDocumentFromNote(id);
}

//: What the *tools* opened, as opposed to what retrieval found. The report
//: this answers: "no way to actually find and navigate to the things it
//: found". Retrieval's row (`cmdPaletteResultRow`) only ever covers notes the
//: semantic search returned; a turn that read a document, edited a note or
//: followed a link touched things that row never mentions. The backend already
//: names them per tool call (`_touched_items`), so the palette accumulates
//: them across the turn and shows them under one heading.
function cmdPaletteTouchedRow(items) {
  if (!items.length) return null;
  //: Same grid as the retrieved-notes block above, these two lists sat under
  //: one another in different shapes and different chip sizes, which is what
  //: made the pair read as clutter rather than as provenance.
  return cmdSourceList(
    items.length === 1 ? "Opened 1 item" : `Opened ${items.length} items`,
    items,
    (item) => {
      const spec = TOUCHED_KINDS[item.kind] || TOUCHED_KINDS.note;
      const chip = document.createElement("button");
      chip.type = "button";
      chip.className = "cmd-source-row";
      //: INBOX 35, batch B's own next step: `item.label` is a raw title/
      //: preview from the backend (a document's own title, a note's opening
      //: words). Reported with a screenshot: a document titled `# CAB432`
      //: and a note opening `**Ice Breakers:**` printed their own markdown
      //: markers here. `setNoteLabel` is the one place that both strips a
      //: label short enough to cut safely and renders one long enough to
      //: show in full, rather than a plain-text stripper that always
      //: flattens -- the same badge recipe the grounding/touched chips
      //: elsewhere in chat already use.
      setNoteLabel(chip, spec.icon, item.label || `#${item.id}`, 44);
      chip.title = spec.title;
      chip.addEventListener("click", () =>
        item.kind === "document" ? cmdPaletteGoToDocument(item.id) : cmdPaletteGoToNote(item.id),
      );
      return chip;
    }
  );
}

//: **A list of what was used, not a drift of pills.**
//:
//: Reported with a screenshot of "Found in 10 notes" and "Opened 6 items":
//: *"refine the ui display of these in the popup agent."* They were inline
//: chips of whatever width their text happened to be, wrapping into a ragged
//: block: three on one line, two on the next, each truncated at a different
//: point, and the second list's chips a different size from the first's
//: because their labels were longer. Nothing lines up, so nothing scans.
//:
//: A fixed grid fixes both halves at once: every row is the same width, so the
//: eye reads down a column instead of hunting, and the truncation lands in one
//: place. Past `CMD_SOURCE_PREVIEW` the rest fold behind one "show all", 
//: eleven rows of provenance under a two-line answer is the panel reporting on
//: itself rather than answering.
const CMD_SOURCE_PREVIEW = 6;

function cmdSourceList(labelText, items, render) {
  const block = document.createElement("div");
  block.className = "cmd-source-block";
  const head = document.createElement("p");
  head.className = "muted cmd-source-head";
  head.textContent = labelText;
  block.appendChild(head);
  const grid = document.createElement("div");
  grid.className = "cmd-source-grid";
  items.slice(0, CMD_SOURCE_PREVIEW).forEach((item) => grid.appendChild(render(item)));
  block.appendChild(grid);
  const rest = items.slice(CMD_SOURCE_PREVIEW);
  if (rest.length) {
    const more = document.createElement("button");
    more.type = "button";
    more.className = "link-button cmd-source-more";
    more.textContent = `Show ${rest.length} more`;
    more.addEventListener("click", () => {
      rest.forEach((item) => grid.appendChild(render(item)));
      more.remove();
    });
    block.appendChild(more);
  }
  return block;
}

//: The notes this turn actually retrieved, as things you can open.
function cmdPaletteResultRow(results) {
  return cmdSourceList(
    results.length === 1 ? "Found in 1 note" : `Found in ${results.length} notes`,
    results,
    (entry) => {
      const chip = document.createElement("button");
      chip.type = "button";
      chip.className = "cmd-source-row";
      //: `ph:note`, not `ph:file-text`, that glyph means *document* in the
      //: touched row below, and the same picture standing for two different
      //: objects in one panel is exactly the inconsistency this app is being
      //: pulled out of. `setNoteLabel`, not `noteLabel` plus `setLabel`: the
      //: latter pair always flattens (INBOX 35's original fix), the former
      //: renders the note's own Markdown when the label is short enough to
      //: show in full (chat-b.md's own next step).
      setNoteLabel(chip, "ph:note", entry.content || "", 44);
      chip.title = `Open this note${entry.category ? ` (${entry.category})` : ""}`;
      chip.addEventListener("click", () => cmdPaletteGoToNote(entry.id));
      return chip;
    }
  );
}

//: One reference, as a control. Extracted because a list of ids builds several
//: of these and they must be identical, a note you can open should not look
//: like two different things in the same sentence.
//: **The link says which note it opens, and that is a correctness feature
//: rather than a nicety.** Reported: "the bubble tea note it mentioned was
//: my bubble tea mind map, but the link it gave and grounded was my
//: shakespeare note". The id in a link comes from the model's own prose
//: (`CMD_NOTE_REF` matches the "68" in "note #68"), and a model that writes
//: the wrong id produces a link that goes somewhere the answer never meant.
//: Nothing here can tell a right id from a wrong one: only the person
//: reading the sentence knows which note they were promised.
//:
//: So the tooltip carries the note's own opening words, labelled the same
//: way the source chips below the answer are labelled and from the same
//: retrieved entry. When the model gets it right the tooltip agrees with
//: the sentence; when it gets it wrong the disagreement is visible before
//: the click rather than after it. `entry` is optional because a caller
//: without one is still better off with a working link than none.
//: **The link says which note it opens, in the sentence, before it is
//: clicked** (INBOX 112).
//:
//: Reported with two screenshots: an answer that read "You only have one note
//: (note #68) in your notebook, and its content is simply '# bubble tea'",
//: with both chips labelled "bubble tea", and clicking "note #68" opened a
//: Shakespeare sonnet parody. Traced: the destination is not wrong.
//: `flashEntry` selects `li[data-id="${id}"]`, so the button opens exactly the
//: id the text names, and the run-of-ids walk below only ever links an id this
//: turn actually retrieved. What went wrong is upstream of the app: the model
//: wrote an id that belonged to a different note than the one its own sentence
//: was describing, and the app then dressed that number up as a citation, which
//: is what made a model's mistake read as the app sending you somewhere at
//: random.
//:
//: A tooltip was the first answer and it is not enough: you have to hover a
//: thing you have no reason to distrust. So the note's own opening words go
//: *in* the link, beside the model's own wording, which is left exactly as it
//: was written. When the model is right the link reads "note #68 · bubble tea"
//: and confirms itself; when it is wrong it reads "note #68 · Act I, Scene I"
//: and the mismatch is visible in the sentence without clicking anything. The
//: app cannot make a small local model cite correctly, and it can stop
//: repeating the claim as though it had checked it.
//: The first line of a note, as a name. Empty when there is nothing to show,
//: so the caller can leave the reference bare rather than print "(empty
//: note)" in the middle of a sentence.
function cmdNoteName(entry) {
  const first = String(entry?.content || "")
    .split("\n")
    .map((line) => line.trim())
    .find((line) => line.length > 0);
  if (!first) return "";
  const clean = (typeof notePreviewText === "function" ? notePreviewText(first) : first)
    .replace(/\s+/g, " ")
    .trim();
  if (!clean) return "";
  return clean.length > 24 ? `${clean.slice(0, 23).trimEnd()}\u2026` : clean;
}

function cmdNoteLink(text, id, entry = null) {
  const link = document.createElement("button");
  link.type = "button";
  link.className = "cmd-note-link";
  const said = document.createElement("span");
  said.textContent = text;
  link.appendChild(said);
  //: **The note's first line, not `noteLabel`'s preview of the whole note.**
  //: `noteLabel` runs the entire content through the markdown stripper and
  //: collapses it to one line, which is right for a card ("Act I, Scene I A
  //: sonnet parody") and wrong here: this is a name inside a sentence, and
  //: what a reader recognises a note by is its heading. 24 characters, not
  //: `noteLabel`'s 40, for the same reason: three linked ids in one list at 40
  //: each is a paragraph of titles in the middle of an answer.
  const preview = cmdNoteName(entry);
  if (preview) {
    const name = document.createElement("span");
    name.className = "cmd-note-link-name";
    name.textContent = preview;
    link.appendChild(name);
  }
  link.title = preview ? `Open note ${id}: "${preview}"` : `Open note ${id}`;
  link.addEventListener("click", () => cmdPaletteGoToNote(id));
  return link;
}

//: Turns "note id 43" in the rendered answer into a button that opens note 43.
//:
//: Walks text nodes and splits them, the same shape `addInlineCitations` uses
//: for the Ask box's citation markers: and for the same reason: the answer is
//: already safe DOM built by `renderMarkdown`, and going back to a string to
//: regex over it would be re-introducing the innerHTML this function's own
//: neighbourhood was fixed to stop using. Only ids the turn actually retrieved
//: are linked, so a model inventing "note id 900" leaves plain text behind
//: rather than a button that goes nowhere.
function cmdPaletteLinkNotes(root, results) {
  //: A map rather than a set: every link now carries the note's own opening
  //: words in its tooltip (see `cmdNoteLink`), so the entry has to travel
  //: with the id rather than just the fact that the id was retrieved.
  const known = new Map((results || []).map((entry) => [entry.id, entry]));
  if (!known.size) return;
  const queue = [root];
  while (queue.length) {
    const node = queue.shift();
    if (node.nodeType === Node.ELEMENT_NODE) {
      if (node.classList?.contains("cmd-note-link")) continue;
      queue.unshift(...node.childNodes);
      continue;
    }
    if (node.nodeType !== Node.TEXT_NODE) continue;
    CMD_NOTE_REF.lastIndex = 0;
    const match = CMD_NOTE_REF.exec(node.textContent);
    if (!match) continue;
    const id = Number(match[1]);
    if (!known.has(id)) continue;
    const tail = node.splitText(match.index);
    const rest = tail.splitText(match[0].length);
    tail.replaceWith(cmdNoteLink(match[0], id, known.get(id)));
    //: **The rest of the list, which is where the report actually lands.** A
    //: model writes "notes id 3, 43 and 49", one phrase naming the id, then
    //: bare numbers. Linking only the head leaves two of the three notes as
    //: unreachable digits, which is the complaint verbatim. So after a match,
    //: keep eating `, 43` / ` and 49` for as long as the next number is one
    //: this turn actually retrieved. An unknown id ends the run rather than
    //: being skipped over: past it the numbers are no longer reliably part of
    //: this list, and guessing is how "$150 to $68" in the very next sentence
    //: of that screenshot would have become two note links.
    let cursor = rest;
    for (;;) {
      const more = /^(\s*(?:,|and|,\s*and)\s*)(\d{1,7})\b/i.exec(cursor.textContent);
      if (!more) break;
      const nextId = Number(more[2]);
      if (!known.has(nextId)) break;
      const numStart = cursor.splitText(more[1].length);
      const after = numStart.splitText(more[2].length);
      numStart.replaceWith(cmdNoteLink(more[2], nextId, known.get(nextId)));
      cursor = after;
    }
    //: `cursor` carries everything after the run, including any further
    //: mentions in the same sentence, re-queueing it is what stops the first
    //: reference in a paragraph being the only one that becomes a link.
    queue.unshift(cursor);
  }
}

async function cmdPaletteAsk(text) {
  $("command-palette-intro")?.classList.add("hidden");

  const userMsg = document.createElement("div");
  userMsg.className = "msg user";
  userMsg.textContent = text;
  //: **The same three actions the Chat tab's own bubbles carry.** Reported:
  //: *"I cant copy edit or resend any messages in the popup agent. it still
  //: lacks a lot of features."* The palette had none of them, a question you
  //: mistyped could only be retyped from memory, and an answer could only be
  //: selected by hand.
  //:
  //: `chatMessageActions` is the Chat tab's own row, reused rather than
  //: rebuilt: the palette is supposed to be the same assistant in a smaller
  //: window, and two different action rows for one idea is how they drift.
  //: Edit puts the text back in the box rather than opening an editor, 
  //: there is one input here and it is right below, so the shortest path to
  //: "ask that again, differently" is to hand it back.
  userMsg.appendChild(
    chatMessageActions([
      { label: "ph:copy", title: "Copy", onClick: (e) => copyToClipboard(text, e.currentTarget) },
      {
        label: "ph:pencil-simple",
        title: "Edit and ask again",
        onClick: () => {
          cmdPaletteInput.value = text;
          cmdPaletteInput.focus();
          cmdPaletteInput.setSelectionRange(text.length, text.length);
          autoGrow(cmdPaletteInput);
        },
      },
      {
        label: "ph:arrow-clockwise",
        title: "Ask this again",
        onClick: () => cmdPaletteAsk(text),
      },
    ])
  );
  cmdPaletteResults.appendChild(userMsg);

  const agentMsg = document.createElement("div");
  //: `.is-generating` is the app's one "this is working" signal
  //: (01-forms-settings.css). It goes on the bubble that is filling, not on a
  //: spinner parked elsewhere, so what pulses is the thing being waited for.
  agentMsg.className = "msg assistant is-generating";
  agentMsg.appendChild(typingDots());
  cmdPaletteResults.appendChild(agentMsg);
  //: The answer's own row, added now and reading `answerRaw` at click time: 
  //: the text does not exist yet, and binding a copy of an empty string is
  //: how "Copy" ends up copying nothing on a fast answer.
  agentMsg.appendChild(
    chatMessageActions([
      {
        label: "ph:copy",
        title: "Copy this answer",
        onClick: (e) => copyToClipboard(answerRaw, e.currentTarget),
      },
      {
        label: "ph:arrow-clockwise",
        title: "Ask again for a different answer",
        onClick: () => cmdPaletteAsk(text),
      },
    ])
  );
  cmdPaletteResults.scrollTop = cmdPaletteResults.scrollHeight;

  // Was hand-rolled against `/chat` (the non-streaming endpoint, a single
  // JSON object) as though it were the NDJSON `/chat/stream` shape: so
  // `msg.type` was never "content" and this never actually rendered an
  // answer at all (a "feature that never ran once", CLAUDE.md's own
  // category for this). It also built the answer with
  // `innerHTML = answerText.replace(...)` and no escaping: a real,
  // reachable XSS the moment the parsing bug above was fixed, since a
  // model can echo a note's own text back verbatim. Fixed by reusing this
  // file's one real streaming client (`streamChat`) and its one safe
  // renderer (`renderMarkdown`, DOM nodes only, never innerHTML) instead
  // of a second, parallel, broken implementation of both.
  let answerRaw = "";
  let answered = false;
  let found = [];
  //: Keyed on kind *and* id, because a note 3 and a document 3 are two
  //: different things and both may be touched in one turn.
  const touched = new Map();
  let meta = null;
  let stats = null;
  let thinkingRaw = "";
  cmdPaletteRun = new AbortController();
  cmdPaletteBusy(true);
  try {
    await streamChat({
      question: text,
      // The same window the Ask box uses, and for the same reason: enough
      // for a follow-up to mean something, short enough that a small local
      // model is not re-reading a transcript every turn.
      history: cmdPaletteTurns.slice(-MAX_CLIENT_HISTORY),
      useTools: true, // the palette is meant to act on the notebook, like Chat
      signal: cmdPaletteRun.signal,
      //: `raw_results` is the notes retrieval surfaced for this turn. It used
      //: to be discarded here, which is why the palette could only describe
      //: what it found and never show it.
      onMeta: (event) => {
        meta = event;
        found = event?.raw_results || [];
      },
      //: Accumulated, not rendered per delta: the box is closed, so there is
      //: nothing on screen to keep up to date, and re-rendering a <pre> on
      //: every token would be work nobody can see.
      onThinking: (delta) => {
        thinkingRaw += delta;
      },
      //: An agent turn reports once per round. Same accumulation the Chat tab
      //: does: output tokens add up, the prompt is the largest one sent, and
      //: one estimated round makes the whole figure an estimate.
      onStats: (event) => {
        if (!stats) {
          stats = { ...event };
          return;
        }
        stats.model = event.model || stats.model;
        stats.prompt_tokens = Math.max(stats.prompt_tokens || 0, event.prompt_tokens || 0);
        stats.output_tokens = (stats.output_tokens || 0) + (event.output_tokens || 0);
        stats.round = Math.max(stats.round || 0, event.round || 0);
        if (event.usage_source === "estimated") stats.usage_source = "estimated";
      },
      onTool: (event) => {
        // Something visible while a tool runs, so a long silence reads as
        // work rather than as nothing happening.
        //: `setLabel`, not `textContent`. A tool event's label carries this
        //: app's icon token, `ph:books Listed notes (…)`, and `setLabel` is
        //: the one function that turns that into the glyph. Writing it as text
        //: printed the token itself: reported with a screenshot reading
        //: "Running ph:books Listed notes ([\"Thoughts & Ideas\"])…". The label
        //: has to be composed before the icon is resolved, since the token is
        //: only recognised at the start of the string.
        setLabel(
          $("command-palette-status"),
          event?.label ? `${event.label} …` : "Working…",
        );
        for (const item of event?.touched || []) {
          touched.set(`${item.kind}:${item.id}`, item);
        }
        //: **The rest of the app has to hear about it too.**
        //:
        //: Reported: *"the popup agent made a note, but there was no way to
        //: go to it, it didn't appear in the notes tab and only appeared in
        //: the library."* Both halves are this one line. The Chat tab has
        //: called `loadEntries()` on a change event since it was built; the
        //: palette never did, so `allEntries`, which the Notes tab renders
        //: from, and which the palette's own chips resolve titles against, 
        //: still held the notebook as it was before the agent wrote to it.
        //: The Library looked correct only because it re-fetches when opened.
        //:
        //: Not awaited: this runs mid-stream and the answer must keep
        //: arriving while the list refreshes behind it.
        if ((event?.changes || []).length) loadEntries();
      },
      onAnswer: (delta) => {
        answered = true;
        answerRaw += delta;
        renderMarkdown(agentMsg, answerRaw);
        cmdPaletteResults.scrollTop = cmdPaletteResults.scrollHeight;
      },
    });
    if (!answered) agentMsg.textContent = "(no answer)";
    else {
      //: Linked once, at the end, rather than on every delta: mid-stream the
      //: text can be "note id 4" on its way to "note id 43", and a link built
      //: from that half-arrived number would point at the wrong note.
      //: Retrieval's notes *and* the notes tools opened: an `edit_note` turn
      //: retrieves nothing, so "note id 43" in its answer had no link at all.
      cmdPaletteLinkNotes(agentMsg, [
        ...found,
        ...[...touched.values()].filter((item) => item.kind === "note"),
      ]);
      cmdPaletteTurns.push({ question: text, answer: answerRaw });
    }
    //: Below the answer, and always when there were results, the model's
    //: prose is free to summarise or to leave a note out, but what retrieval
    //: found should not depend on whether it got a mention.
    if (found.length) cmdPaletteResults.appendChild(cmdPaletteResultRow(found));
    //: Under retrieval's row, not instead of it: "what I searched" and "what I
    //: opened" are different claims, and a turn can have one without the other.
    const touchedRow = cmdPaletteTouchedRow([...touched.values()]);
    if (touchedRow) cmdPaletteResults.appendChild(touchedRow);
    //: Reasoning above the evidence, evidence above the accounting, the same
    //: order the Chat tab reads in, so moving between the two surfaces does
    //: not mean learning a second layout.
    if (thinkingRaw.trim()) {
      agentMsg.prepend(cmdPaletteThinkingBox(thinkingRaw.trim()));
    }
    const metaRow = cmdPaletteMetaRow({
      meta,
      stats,
      persona: (prefsCache && prefsCache.active_persona) || null,
    });
    if (metaRow) cmdPaletteResults.appendChild(metaRow);
    cmdPaletteResults.scrollTop = cmdPaletteResults.scrollHeight;
  } catch (err) {
    if (err?.name === "AbortError") {
      agentMsg.textContent = answerRaw || "(stopped)";
    } else {
      // The message, not a euphemism for it. A failing model's real reason
      // arrives here (see `describe_http_error` in ai/ollama_client.py) and
      // "Error communicating with agent." threw all of it away.
      agentMsg.textContent = err?.message || "The agent could not be reached.";
      agentMsg.classList.add("error");
    }
  } finally {
    agentMsg.classList.remove("is-generating");
    cmdPaletteRun = null;
    cmdPaletteBusy(false);
  }
}

// The palette's input is a `<textarea>` (see index.html for why), so it has
// to be told to behave like a command bar rather than a text box: Enter
// sends, Shift+Enter, and any of the IME/composition states below, insert a
// newline. `isComposing` matters for anyone typing Japanese, Chinese or Korean:
// Enter commits the candidate word there, and sending on it would fire the
// agent at half a sentence every time.
function cmdPaletteGrow() {
  // Reset first: without it the box only ever ratchets taller, because
  // scrollHeight can never come back below a height already set on it.
  cmdPaletteInput.style.height = "auto";
  const max = 9 * 16; // ~9rem, then it scrolls, the palette is not an editor
  cmdPaletteInput.style.height = `${Math.min(cmdPaletteInput.scrollHeight, max)}px`;
}

cmdPaletteInput.addEventListener("input", cmdPaletteGrow);

cmdPaletteInput.addEventListener("keydown", (e) => {
  if (e.key !== "Enter" || e.shiftKey || e.isComposing || e.keyCode === 229) return;
  e.preventDefault(); // or the newline lands in the box we are about to clear
  if (!cmdPaletteInput.value.trim()) return;
  const text = cmdPaletteInput.value.trim();
  cmdPaletteInput.value = "";
  cmdPaletteGrow();
  cmdPaletteAsk(text);
});

$("command-palette-clear")?.addEventListener("click", cmdPaletteReset);
$("command-palette-stop")?.addEventListener("click", () => cmdPaletteRun?.abort());
$("command-palette-intro")?.addEventListener("click", (e) => {
  const example = e.target.closest("[data-example]");
  if (!example) return;
  cmdPaletteInput.value = example.dataset.example;
  cmdPaletteGrow();
  cmdPaletteInput.focus();
  // A complete question runs; a stem ("Make a note: ") is left for the user
  // to finish, with the caret already after it.
  if (example.dataset.example.trim().endsWith("?")) {
    const text = cmdPaletteInput.value.trim();
    cmdPaletteInput.value = "";
    cmdPaletteAsk(text);
  }
});

// --- spaces ------------------------------------------------------------------
//
// A space partitions notes, categories, links and documents. It is soft
// separation, not separate databases: every row carries a `workspace_id` and
// the server adds a loader criterion for the one named in `X-Workspace-ID`.
// That header is added in `api()` above, which is the only reason switching
// spaces changes what you see rather than just the label in the header.
//
// The id is kept in localStorage rather than on the server on purpose: which
// space you were last in is a property of this window, not of the notebook,
// and syncing it would mean two open windows fighting over one value.
//
// `SPACE_ALL` itself is declared up near `api()`, not here: see the comment
// there for why.

// The icons a space may be given. A closed set, because the value is
// interpolated into a class name, an arbitrary string there is CSS class
// injection, and it is also how you end up with a space whose icon is a
// typo that renders as an empty box.
const SPACE_ICONS = [
  "ph-folder", "ph-briefcase", "ph-house", "ph-user", "ph-kanban",
  "ph-code", "ph-flask", "ph-heart", "ph-book-open", "ph-graduation-cap",
  "ph-game-controller", "ph-terminal-window", "ph-camera", "ph-music-notes",
  "ph-airplane", "ph-shopping-cart", "ph-tree", "ph-lightbulb",
];

let spacesCache = [];

function activeSpaceId() {
  return localStorage.getItem("spaceId") || SPACE_ALL;
}

function setActiveSpace(id) {
  localStorage.setItem("spaceId", id);
  // A full reload rather than a re-fetch of everything on the page. Every list,
  // count, graph and sidebar in the app is scoped by the header, so a partial
  // refresh would leave whichever one we forgot showing the old space, and a
  // space that is half-switched is worse than one that took a second.
  window.location.reload();
}

function spaceIconPicker(container, hiddenInput) {
  container.replaceChildren();
  for (const name of SPACE_ICONS) {
    const button = document.createElement("button");
    button.type = "button";
    button.setAttribute("role", "radio");
    button.setAttribute("aria-checked", String(hiddenInput.value === name));
    button.setAttribute("aria-label", name.replace("ph-", "").replace(/-/g, " "));
    const icon = document.createElement("i");
    icon.className = `ph ${name}`;
    icon.setAttribute("aria-hidden", "true");
    button.appendChild(icon);
    button.addEventListener("click", () => {
      hiddenInput.value = name;
      for (const sibling of container.children) {
        sibling.setAttribute("aria-checked", String(sibling === button));
      }
    });
    container.appendChild(button);
  }
}

function spaceMenuOption({ id, name, icon, deletable, hiddenFromAll }) {
  const option = document.createElement("button");
  option.type = "button";
  option.className = "space-option";
  option.setAttribute("role", "option");
  option.dataset.spaceId = id;
  option.setAttribute("aria-selected", String(id === activeSpaceId()));
  // .space-option-name ellipsises with no other escape hatch for a long
  // board name.
  option.title = name;

  const glyph = document.createElement("i");
  glyph.className = `ph ${icon}`;
  glyph.setAttribute("aria-hidden", "true");

  const label = document.createElement("span");
  label.className = "space-option-name";
  label.textContent = name;

  option.append(glyph, label);
  option.addEventListener("click", () => setActiveSpace(id));

  if (deletable) {
    const actions = document.createElement("span");
    actions.className = "space-option-actions";

    // Nested <button> is invalid HTML, so these are spans with a button role.
    // The click handlers stop propagation: without it, "rename" would also
    // trip the row's own switch-to-this-space handler and reload the page out
    // from under the dialog that was about to open.
    for (const [glyphName, title, run] of [
      // Keep this space out of "All spaces", or put it back. Asked for
      // directly: "how do I hide a specific space's notes and
      // images/documents etc, all the content from the 'all spaces' space if
      // I wish??" It lives on the space's own row because that is where a
      // person is when they think it, not buried in Settings, which is the
      // other place it could have gone and a worse one.
      //
      // The glyph carries the state (an open eye means visible, a struck-out
      // one means hidden), and the title says what pressing it will do,
      // which is the pair every other toggle in this app uses.
      [
        hiddenFromAll ? "ph-eye-slash" : "ph-eye",
        hiddenFromAll
          ? "Hidden from All spaces, show it there again"
          : "Hide this space's contents from All spaces",
        () => toggleSpaceHidden(id, !hiddenFromAll),
      ],
      ["ph-pencil-simple", "Rename this space", () => openSpaceEdit(id, name, icon)],
      ["ph-trash", "Delete this space", () => openSpaceDelete(id)],
    ]) {
      const action = document.createElement("span");
      action.className = "ghost small";
      action.setAttribute("role", "button");
      action.tabIndex = 0;
      action.title = title;
      action.setAttribute("aria-label", title);
      const actionIcon = document.createElement("i");
      actionIcon.className = `ph ${glyphName}`;
      actionIcon.setAttribute("aria-hidden", "true");
      action.appendChild(actionIcon);
      const fire = (event) => {
        event.stopPropagation();
        event.preventDefault();
        closeSpaceMenu();
        run();
      };
      action.addEventListener("click", fire);
      action.addEventListener("keydown", (event) => {
        if (event.key === "Enter" || event.key === " ") fire(event);
      });
      actions.appendChild(action);
    }
    option.appendChild(actions);
  }
  return option;
}

// Flip a space in or out of the everything-view. A view filter, not a
// privacy boundary: the space stays completely usable when selected.
async function toggleSpaceHidden(id, hidden) {
  try {
    await apiJson(`/spaces/${id}`, {
      method: "PUT",
      body: JSON.stringify({ hidden_from_all: hidden }),
    });
    await loadSpaces();
    renderSpaceMenu();
    toast(
      hidden
        ? "Hidden from All spaces. It still opens normally when you pick it."
        : "Showing in All spaces again."
    );
    // The everything-view's contents just changed under whatever is on
    // screen, so it has to be re-read rather than left stale.
    if (activeSpaceId() === SPACE_ALL) await loadEntries();
  } catch (error) {
    toast(error.message || "Couldn't change that space.", true);
  }
}

function renderSpaceMenu() {
  const menu = $("space-menu");
  if (!menu) return;
  menu.replaceChildren();

  menu.appendChild(spaceMenuOption({
    id: SPACE_ALL,
    name: "All spaces",
    icon: "ph-circles-four",
    deletable: false,
  }));
  for (const space of spacesCache) {
    menu.appendChild(spaceMenuOption({
      id: space.id,
      name: space.name,
      icon: space.icon,
      // "default" is where a deleted space's notes go, so it cannot itself be
      // deleted: the server refuses it too, but offering a button that always
      // errors is not a UI.
      hiddenFromAll: Boolean(space.hidden_from_all),
      deletable: space.id !== "default",
    }));
  }

  const divider = document.createElement("div");
  divider.className = "space-menu-divider";
  menu.appendChild(divider);

  const create = document.createElement("button");
  create.type = "button";
  create.className = "space-option";
  create.id = "space-create-open";
  const plus = document.createElement("i");
  plus.className = "ph ph-plus";
  plus.setAttribute("aria-hidden", "true");
  const createLabel = document.createElement("span");
  createLabel.className = "space-option-name";
  createLabel.textContent = "New space…";
  create.append(plus, createLabel);
  create.addEventListener("click", () => {
    closeSpaceMenu();
    openSpaceCreate();
  });
  menu.appendChild(create);

  // The button's own label follows whatever is selected.
  const current = spacesCache.find((space) => space.id === activeSpaceId());
  const nameEl = $("space-current-name");
  const iconEl = $("space-current-icon");
  if (nameEl) {
    nameEl.textContent = current ? current.name : "All spaces";
    nameEl.title = current ? current.name : "All spaces";
  }
  if (iconEl) iconEl.className = `ph ${current ? current.icon : "ph-circles-four"}`;
}

function closeSpaceMenu() {
  $("space-menu")?.classList.add("hidden");
  $("space-switcher-btn")?.setAttribute("aria-expanded", "false");
}

function openSpaceCreate() {
  $("space-create-name").value = "";
  $("space-create-icon").value = "ph-folder";
  $("space-create-error").textContent = "";
  spaceIconPicker($("space-create-icon-picker"), $("space-create-icon"));
  $("space-create-dialog").showModal();
  $("space-create-name").focus();
}

function openSpaceEdit(id, name, icon) {
  $("space-edit-id").value = id;
  $("space-edit-name").value = name;
  $("space-edit-icon").value = icon;
  $("space-edit-error").textContent = "";
  spaceIconPicker($("space-edit-icon-picker"), $("space-edit-icon"));
  $("space-edit-dialog").showModal();
  $("space-edit-name").focus();
}

function openSpaceDelete(id) {
  $("space-delete-id").value = id;
  $("space-delete-error").textContent = "";
  $("space-delete-dialog").showModal();
}

async function loadSpaces() {
  if (!$("space-switcher-btn")) return;
  const wasEmpty = !spacesCache.length;
  try {
    spacesCache = await apiJson("/spaces", { silent: true });
  } catch {
    // A notebook that has never had a space made still has to work. Failing to
    // list them leaves the switcher on "All spaces", which is exactly right.
    spacesCache = [];
  }
  renderSpaceMenu();
  updateCaptureSpaceLabel();
  //: The other half of the guard on the note card's space chip: the list is
  //: drawn before this request comes back, and every card that drew while the
  //: cache was empty is now missing the chip it should carry. Re-rendered only
  //: when there is something on screen to re-render and the cache actually has
  //: something in it, so this costs a fresh notebook nothing and cannot loop
  //: (nothing in `renderEntries` calls back into here).
  if (wasEmpty && spacesCache.length && $("entry-list")?.children.length) renderEntries();
}

//: INBOX 1a/38: says which space the capture form actually files into,
//: because the answer is not always the one picked at the top. Selecting
//: "All spaces" turns off the workspace filter for *reading*, but a new
//: note still has to land somewhere concrete, and `database.py`'s own
//: insert hook only stamps a workspace when one is actually selected: with
//: "all" sent, a fresh row keeps its column default, "default" (Default
//: Space). Read that off the same rule rather than re-deciding it here, so
//: this label and the server's own behaviour cannot drift apart.
function updateCaptureSpaceLabel() {
  const label = $("capture-space-hint");
  if (!label) return;
  const active = activeSpaceId();
  const filingId = active === SPACE_ALL ? "default" : active;
  const space = spacesCache.find((s) => s.id === filingId);
  const name = space ? space.name : "Default Space";
  label.textContent =
    active === SPACE_ALL
      ? `Filing into ${name} (pick a space above to file there instead).`
      : `Filing into ${name}.`;
}

function initSpaceSwitcher() {
  const button = $("space-switcher-btn");
  const menu = $("space-menu");
  if (!button || !menu) return;

  button.addEventListener("click", (event) => {
    event.stopPropagation();
    const open = button.getAttribute("aria-expanded") === "true";
    button.setAttribute("aria-expanded", String(!open));
    menu.classList.toggle("hidden", open);
  });

  document.addEventListener("click", (event) => {
    if (!menu.contains(event.target) && !button.contains(event.target)) closeSpaceMenu();
  });
  document.addEventListener("keydown", (event) => {
    if (event.key === "Escape") closeSpaceMenu();
  });

  // Cancel buttons. These were `onclick` attributes, which this app's CSP
  // refuses outright, so every one of them was dead markup.
  for (const closer of document.querySelectorAll("[data-close-dialog]")) {
    closer.addEventListener("click", () => {
      document.getElementById(closer.dataset.closeDialog)?.close();
    });
  }

  // Tensions: the review's own start button. `data-close-dialog` above
  // already wires its Close.
  $("tensions-run")?.addEventListener("click", runTensionReview);

  $("space-create-submit")?.addEventListener("click", async () => {
    const name = $("space-create-name").value.trim();
    const error = $("space-create-error");
    error.textContent = "";
    if (!name) {
      error.textContent = "Give the space a name.";
      return;
    }
    try {
      const space = await apiJson("/spaces", {
        method: "POST",
        body: JSON.stringify({ name, icon: $("space-create-icon").value }),
      });
      $("space-create-dialog").close();
      setActiveSpace(space.id);
    } catch (err) {
      error.textContent = err.message;
    }
  });

  $("space-edit-submit")?.addEventListener("click", async () => {
    const id = $("space-edit-id").value;
    const name = $("space-edit-name").value.trim();
    const error = $("space-edit-error");
    error.textContent = "";
    if (!name) {
      error.textContent = "Give the space a name.";
      return;
    }
    try {
      await apiJson(`/spaces/${encodeURIComponent(id)}`, {
        method: "PUT",
        body: JSON.stringify({ name, icon: $("space-edit-icon").value }),
      });
      $("space-edit-dialog").close();
      await loadSpaces();
      toast(`Renamed to “${name}”.`);
    } catch (err) {
      error.textContent = err.message;
    }
  });

  $("space-delete-submit")?.addEventListener("click", async () => {
    const id = $("space-delete-id").value;
    const error = $("space-delete-error");
    error.textContent = "";
    try {
      await apiJson(`/spaces/${encodeURIComponent(id)}`, { method: "DELETE" });
      $("space-delete-dialog").close();
      // Standing in the space you just deleted has to move you somewhere real,
      // and reload() alone would leave the header naming a space that is gone.
      if (activeSpaceId() === id) setActiveSpace("default");
      else await loadSpaces();
    } catch (err) {
      error.textContent = err.message;
    }
  });

  // Deliberately NOT loading the list here, see the "load spaces" step in
  // startApp(), which runs once there is a token.
}

initSpaceSwitcher();

// --- capture templates, Settings pane (extends Wave B) ------------------------------
//
// Built-ins (BUILTIN_TEMPLATES, declared near the Capture form) are read-only
// here: same shape as skills, where a built-in shows in the list but never
// grows Edit/Delete buttons because there is genuinely nothing in
// `custom_templates` to remove. The server enforces the name-collision half
// of that (routes_settings._validated_templates); this pane just avoids
// offering an action that would only come back as a 422.

// Which custom template (by name) the editor is currently editing, if any, 
// same tracking `editingSkillName` does, so Save updates in place on a
// rename instead of leaving a duplicate behind.
let editingTemplateName = null;

function customTemplates() {
  return (prefsCache && prefsCache.custom_templates) || [];
}

function startEditingTemplate(template) {
  editingTemplateName = template.name;
  $("template-name").value = template.name;
  $("template-description").value = template.description || "";
  $("template-body").value = template.content;
  $("template-add").textContent = "Save changes";
  $("template-cancel").classList.remove("hidden");
  $("template-status").textContent = `Editing “${template.name}”…`;
  $("template-name").focus();
}

function stopEditingTemplate() {
  editingTemplateName = null;
  for (const id of ["template-name", "template-description", "template-body"]) {
    $(id).value = "";
  }
  $("template-add").textContent = "Add template";
  $("template-cancel").classList.add("hidden");
  $("template-status").textContent = "";
}

async function saveTemplateList(templates) {
  prefsCache = await apiJson("/preferences", {
    method: "PUT",
    body: JSON.stringify({ custom_templates: templates }),
  });
  await loadTemplates();
  renderTemplateSettings();
}

async function addTemplate() {
  const name = $("template-name").value.trim();
  const body = $("template-body").value.trim();
  const status = $("template-status");
  status.classList.remove("error");
  if (!name || !body) {
    status.classList.add("error");
    status.textContent = "Both a name and a template body are needed.";
    return;
  }
  // Only the entry being edited is dropped before the push, a genuine
  // rename. A name that instead collides with a DIFFERENT template, custom
  // or built-in, is left in place and the save is rejected server-side
  // (§_validated_templates) rather than silently replacing someone else's
  // saved text the way a same-named skill would.
  const custom = customTemplates().filter((t) => t.name !== editingTemplateName);
  custom.push({
    name,
    description: $("template-description").value.trim(),
    content: body,
  });
  const wasEditing = editingTemplateName;
  try {
    await saveTemplateList(custom);
  } catch (error) {
    status.classList.add("error");
    status.textContent = error.message;
    return;
  }
  stopEditingTemplate();
  status.textContent = wasEditing ? `Updated “${name}”.` : `Saved “${name}”.`;
}

// One row in the Settings list, deliberately the same shape as `skillRow`
// (same classes, same chip-then-blurb-then-actions layout) so the two panes
// that manage a "named, user-editable list of markdown" read as one pattern
// rather than two. `textContent` throughout: template bodies are untrusted
// user text and are never rendered as HTML.
function templateRow(template, builtin) {
  const li = document.createElement("li");
  const row = document.createElement("div");
  row.className = "entry-meta skill-row";
  row.appendChild(chip(template.name));
  if (builtin) row.appendChild(chip("built-in", "tag"));
  const note = document.createElement("span");
  note.className = "muted skill-blurb";
  note.textContent = template.description || template.content;
  row.appendChild(note);
  if (!builtin) {
    const actions = document.createElement("span");
    actions.className = "entry-actions";
    actions.appendChild(
      smallButton("Edit", "Edit this template", () => startEditingTemplate(template))
    );
    actions.appendChild(
      smallButton("Delete", "Remove this template", async () => {
        if (!(await confirmDialog(`Delete the “${template.name}” template?`))) return;
        await saveTemplateList(customTemplates().filter((t) => t.name !== template.name));
      })
    );
    row.appendChild(actions);
  }
  li.appendChild(row);
  return li;
}

async function renderTemplateSettings() {
  await loadTemplates();
  const list = $("template-list");
  list.replaceChildren();
  for (const template of customTemplates()) list.appendChild(templateRow(template, false));
  for (const template of BUILTIN_TEMPLATES) list.appendChild(templateRow(template, true));
}

$("template-add")?.addEventListener("click", addTemplate);
$("template-cancel")?.addEventListener("click", stopEditingTemplate);


// Upgrade every dropdown in the app, and keep upgrading the ones that
// appear later. Last line of the file on purpose: by here every panel this
// script builds up front exists, and the observer inside covers the rest.
watchForSelects();

//: Clicking it does the one thing its name promises, and hands the pane back
//: to the follow logic by landing at the bottom, the next `scroll` event sets
//: `data-stuck` to "1" and the stream resumes carrying the view with it.
$("chat-jump-latest")?.addEventListener("click", () => {
  const pane = $("chat-messages");
  if (!pane) return;
  pane.scrollTo({ top: pane.scrollHeight, behavior: reducedMotionWanted() ? "auto" : "smooth" });
  pane.dataset.stuck = "1";
  syncChatJumpLatest();
});

//: The panel-wide half of "mark as unread": one gesture that puts every row
//: back to read, overrides included. See `forcedUnreadIds`.
$("notif-mark-all-read")?.addEventListener("click", () => {
  localStorage.setItem(NOTIFICATIONS_READ_KEY, String(Date.now()));
  setForcedUnreadIds(new Set());
  setForcedReadIds(new Set());
  openNotifications();
  toast("All notifications marked as read.");
});
